def _load_core_contract():
    import importlib.util
    module = sys.modules.get("_bridge_core_contract")
    if module is not None:
        return module
    path = _FX_ADDON_SOURCE.parent / "bridge_core_contract.py"
    spec = importlib.util.spec_from_file_location("_bridge_core_contract", path)
    module = importlib.util.module_from_spec(spec)
    sys.modules["_bridge_core_contract"] = module
    spec.loader.exec_module(module)
    return module


