def _production_allowed_commands() -> frozenset[str]:
    """Return the production surface, with raw code behind human launch opt-in."""

    enabled = str(os.environ.get(_CODE_EXEC_OPT_IN_ENV) or "").strip().lower()
    if enabled in {"1", "true", "yes", "on"}:
        return _DEFAULT_BRIDGE_COMMANDS | {"code.exec_python", "exec_python"}
    return _DEFAULT_BRIDGE_COMMANDS


def _fx_sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _fx_contract_payload(pack: dict[str, Any]) -> dict[str, Any]:
    return {
        str(key): value
        for key, value in sorted(pack.items(), key=lambda item: str(item[0]))
        if str(key) not in _FX_CONTRACT_EXCLUDED_KEYS
    }


def _fx_pack_declared_connections(pack: dict[str, Any]) -> list[dict[str, Any]]:
    """Mirror of the catalog's declared_connections(): explicit wires when the
    pack declares them, otherwise the legacy input_role compat (out0 -> in0)."""
    declared = pack.get("connections")
    if declared:
        return list(declared)
    out: list[dict[str, Any]] = []
    for node in pack.get("nodes") or []:
        input_role = node.get("input_role")
        if input_role:
            out.append({"source_role": str(input_role), "source_output": 0,
                        "destination_role": str(node.get("role") or ""), "destination_input": 0})
    return out


def _fx_pack_contract_sha256(pack: dict[str, Any]) -> str:
    encoded = json.dumps(_fx_contract_payload(pack), ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _fx_pack_semantic_contract(pack: dict[str, Any]) -> dict[str, Any]:
    """Canonical public execution fields shared by host and in-DCC catalogs."""

    return {
        "version": str(pack.get("version") or "1.0.0"),
        "nodes": [
            {
                "role": str(node.get("role") or ""),
                "category": str(node.get("category") or ""),
                "types": [str(item) for item in node.get("types") or []],
                "required_parms": [
                    [str(alias) for alias in aliases]
                    for aliases in node.get("required_parms") or []
                ],
                "input_role": str(node.get("input_role") or "") or None,
            }
            for node in pack.get("nodes") or []
        ],
        "controls": {
            str(name): {
                "role": str(control.get("role") or ""),
                "aliases": [str(item) for item in control.get("aliases") or []],
                "minimum": float(control.get("minimum")),
                "maximum": float(control.get("maximum")),
                "value_type": str(control.get("value_type") or "float"),
                "invalidates_from": str(control.get("invalidates_from") or "generation_simulation"),
                "application": str(control.get("application") or "houdini"),
            }
            for name, control in sorted((pack.get("controls") or {}).items())
        },
        "evidence": sorted(str(item) for item in pack.get("evidence") or []),
        "simulation_cache": bool(pack.get("simulation_cache")),
        "connections": [
            {
                "source_role": str(item.get("source_role") or ""),
                "source_output": int(item.get("source_output") or 0),
                "destination_role": str(item.get("destination_role") or ""),
                "destination_input": int(item.get("destination_input") or 0),
            }
            for item in _fx_pack_declared_connections(pack)
        ],
    }


def _fx_host_semantic_contract(pack_id: str) -> tuple[Optional[dict[str, Any]], Optional[str]]:
    """Load the planner-side catalog and normalize the same public fields."""

    if not _FX_CATALOG_SOURCE.is_file() or _fx_path_has_symlink(_FX_CATALOG_SOURCE):
        return None, "catalog_source_missing_or_unsafe"
    module_name = "_bridge_skills_houdini_catalog_{}".format(hashlib.sha256(str(_FX_CATALOG_SOURCE).encode("utf-8")).hexdigest()[:12])
    previous = sys.modules.get(module_name)
    try:
        spec = importlib.util.spec_from_file_location(module_name, _FX_CATALOG_SOURCE)
        if spec is None or spec.loader is None:
            return None, "catalog_import_spec_unavailable"
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        spec.loader.exec_module(module)
        host_pack = module.get_domain_pack(pack_id)
        normalized = {
            "connections": [item.to_dict() for item in getattr(host_pack, "connections", ())] or host_pack.declared_connections(),
            "version": str(host_pack.version),
            "nodes": [
                {
                    "role": str(node.role),
                    "category": str(node.category),
                    "types": [str(item) for item in node.type_candidates],
                    "required_parms": [
                        [str(alias) for alias in aliases]
                        for aliases in node.required_parameter_aliases
                    ],
                    "input_role": str(node.input_role or "") or None,
                }
                for node in host_pack.nodes
            ],
            "controls": {
                str(control.identifier): {
                    "role": str(control.node_role),
                    "aliases": [str(item) for item in control.parameter_aliases],
                    "minimum": float(control.minimum),
                    "maximum": float(control.maximum),
                    "value_type": str(control.value_type),
                    "invalidates_from": str(control.invalidates_from),
                    "application": str(control.application),
                }
                for control in sorted(host_pack.controls, key=lambda item: item.identifier)
            },
            "evidence": sorted(str(item) for item in host_pack.evidence),
            "simulation_cache": bool(host_pack.simulation_cache),
        }
        return normalized, None
    except Exception as exc:
        return None, "catalog_import_failed:{}".format(exc)
    finally:
        if previous is None:
            sys.modules.pop(module_name, None)
        else:
            sys.modules[module_name] = previous


def _fx_support_index_path() -> Path:
    configured = str(os.environ.get(_FX_SUPPORT_INDEX_ENV) or "").strip()
    if configured:
        return Path(configured).expanduser().absolute()
    # Source checkouts keep the index at repo/outputs/live-validation/index.json.
    # Installed plug-ins must opt in with the environment variable; absence is
    # fail-closed rather than trusting copied static metadata.
    candidate = _FX_ADDON_SOURCE.parents[3] / "outputs" / "live-validation" / "index.json"
    return candidate.absolute()


def _fx_path_has_symlink(path: Path) -> bool:
    absolute = path.absolute()
    parts = absolute.parts
    if not parts:
        return False
    current = Path(parts[0])
    for component in parts[1:]:
        current = current / component
        if current.is_symlink():
            return True
    return False


def _fx_entry_identity(entry: dict[str, Any]) -> str:
    payload = {
        key: value
        for key, value in entry.items()
        if key not in {"evidence_identity", "evidence_attestation"}
    }
    encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _fx_load_evidence_attestation_key() -> Optional[bytes]:
    configured = str(os.environ.get(_FX_EVIDENCE_ATTESTATION_KEY_ENV) or "").strip()
    path = Path(configured).expanduser() if configured else Path.home() / ".bridge-skills" / "evidence-attestation.key"
    try:
        info = path.lstat()
        parent_info = path.parent.stat()
        if path.is_symlink() or _fx_path_has_symlink(path) or not stat.S_ISREG(info.st_mode):
            return None
        if os.name != "nt" and (info.st_uid != os.getuid() or stat.S_IMODE(info.st_mode) != 0o600):
            return None
        if os.name != "nt" and (
            parent_info.st_uid != os.getuid() or stat.S_IMODE(parent_info.st_mode) & 0o022
        ):
            return None
        key = path.read_bytes().strip()
    except OSError:
        return None
    return key if len(key) >= 32 else None


def _fx_evidence_attestation_valid(entry: dict[str, Any], key: Optional[bytes]) -> bool:
    if key is None:
        return False
    identity = str(entry.get("evidence_identity") or "")
    supplied = entry.get("evidence_attestation")
    if not _fx_is_hex(identity, (64,)) or not isinstance(supplied, dict):
        return False
    expected_key_id = hashlib.sha256(key).hexdigest()
    expected_signature = hmac.new(
        key,
        _FX_EVIDENCE_ATTESTATION_CONTEXT + identity.encode("ascii"),
        hashlib.sha256,
    ).hexdigest()
    return (
        supplied.get("scheme") == _FX_EVIDENCE_ATTESTATION_SCHEME
        and hmac.compare_digest(str(supplied.get("key_id") or ""), expected_key_id)
        and hmac.compare_digest(str(supplied.get("signature") or ""), expected_signature)
    )


def _fx_resolve_evidence_artifact(root: Path, value: Any) -> Optional[Path]:
    text = str(value or "").strip()
    if not text:
        return None
    relative = Path(text)
    if relative.is_absolute():
        return None
    current = root
    for component in relative.parts:
        current = current / component
        if current.is_symlink():
            return None
    resolved = (root / relative).resolve()
    try:
        resolved.relative_to(root)
    except ValueError:
        return None
    return resolved


def _fx_is_hex(value: Any, lengths: tuple[int, ...]) -> bool:
    text = str(value or "")
    return len(text) in lengths and all(character in "0123456789abcdef" for character in text)


def _fx_support_harness_errors(entry: dict[str, Any], root: Path) -> list[str]:
    """Validate an evidence entry against a known primary harness artifact.

    A signed hash of arbitrary bytes only proves that those bytes were present;
    it does not prove that a DCC/model/reference harness ran or passed.  Support
    promotion therefore accepts only this fail-closed structured schema and
    binds its identity, gates, outputs, build and exact source checkout back to
    the signed index entry.
    """

    errors: list[str] = []
    evidence_kind = str(entry.get("evidence_kind") or "")
    application = str(entry.get("application") or "")
    expected_kinds = {
        "contract": {"contract_probe"},
        "real_reference": {"real_reference_case"},
        "fault_injection": {"fault_injection_case"},
        "live_model": {"model_endpoint_probe"},
        "model_skill_conformance": {"doubao_skill_conformance"},
    }
    if evidence_kind == "live_dcc":
        expected_kinds["live_dcc"] = {
            "nuke_end_to_end" if application == "nuke" else "houdini_end_to_end"
        }
    artifact_kind = str(entry.get("artifact_kind") or "")
    if artifact_kind not in expected_kinds.get(evidence_kind, set()):
        return ["artifact_kind_missing_unknown_or_incompatible"]
    primary_text = str(entry.get("primary_artifact_path") or "")
    primary = _fx_resolve_evidence_artifact(root, primary_text)
    if primary is None or not primary.is_file() or primary.is_symlink():
        return ["primary_artifact_missing_or_unsafe"]
    if primary_text not in (entry.get("artifact_paths") or []):
        errors.append("primary_artifact_not_bound_by_entry")
    try:
        payload = json.loads(primary.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, ValueError):
        return errors + ["primary_artifact_invalid_json"]
    if not isinstance(payload, dict) or payload.get("schema") != "bridge.support_harness/1.0":
        return errors + ["primary_artifact_schema_unknown"]
    if str(payload.get("evidence_identity") or "") != _fx_entry_identity(payload):
        errors.append("primary_artifact_evidence_identity_mismatch")
    if payload.get("artifact_kind") != artifact_kind:
        errors.append("primary_artifact_kind_mismatch")
    for field in (
        "evidence_kind",
        "domain_pack",
        "pack_version",
        "probe_level",
        "execution_entrypoint",
        "git_commit",
        "dirty_diff_digest",
        "domain_contract_sha256",
        "source_path",
        "source_sha256",
        "addon_source_path",
        "addon_source_sha256",
        "catalog_source_path",
        "catalog_source_sha256",
    ):
        if str(payload.get(field) or "") != str(entry.get(field) or ""):
            errors.append("primary_artifact_{}_mismatch".format(field))
    if payload.get("source_identity_stable") is not True:
        errors.append("primary_artifact_source_identity_unstable")
    if payload.get("support_promotion") is not False:
        errors.append("primary_artifact_support_promotion_boundary_missing")
    if str(payload.get("status") or "") != str(entry.get("status") or ""):
        errors.append("primary_artifact_status_mismatch")
    validation = payload.get("validation")
    if not isinstance(validation, dict) or validation.get("passed") is not True:
        errors.append("primary_artifact_validation_not_passed")
    gates = payload.get("gates")
    verification_gates = (
        [
            gate
            for gate in gates
            if isinstance(gate, dict) and gate.get("kind") == "verification"
        ]
        if isinstance(gates, list)
        else []
    )
    if not verification_gates:
        errors.append("primary_artifact_verification_gate_missing")
    elif entry.get("status") == "passed" and not all(
        gate.get("passed") is True for gate in verification_gates
    ):
        errors.append("primary_artifact_verification_gate_failed")
    required_gate_names = {
        "contract": {"domain_contract_verified"},
        "real_reference": {"reference_case_validated"},
        "fault_injection": {"fault_injection_validated"},
        "live_dcc": {"dcc_execution_verified", "render_artifact_verified"},
        "live_model": {"model_identity_verified", "provider_response_verified"},
        "model_skill_conformance": {"doubao_skill_conformance_verified"},
    }.get(evidence_kind, set())
    passed_gate_names = {
        str(gate.get("name") or "")
        for gate in verification_gates
        if gate.get("passed") is True
    }
    missing_gates = sorted(required_gate_names - passed_gate_names)
    if missing_gates:
        errors.append(
            "primary_artifact_required_gates_missing:{}".format(
                ",".join(missing_gates)
            )
        )
    declared_artifacts = payload.get("artifacts")
    declared_artifact_kinds: set[str] = set()
    if not isinstance(declared_artifacts, list) or not declared_artifacts:
        errors.append("primary_artifact_output_records_missing")
    else:
        entry_paths = set(str(item) for item in entry.get("artifact_paths") or [])
        entry_hashes = (
            entry.get("artifact_sha256")
            if isinstance(entry.get("artifact_sha256"), dict)
            else {}
        )
        for record in declared_artifacts:
            if not isinstance(record, dict):
                errors.append("primary_artifact_output_record_invalid")
                continue
            path_text = str(record.get("path") or "")
            digest = str(record.get("sha256") or "")
            record_kind = str(record.get("kind") or "")
            if not record_kind:
                errors.append("primary_artifact_output_kind_missing:{}".format(path_text))
            else:
                declared_artifact_kinds.add(record_kind)
            artifact = _fx_resolve_evidence_artifact(root, path_text)
            if path_text not in entry_paths or digest != str(entry_hashes.get(path_text) or ""):
                errors.append("primary_artifact_output_not_bound:{}".format(path_text))
            if (
                artifact is None
                or not artifact.is_file()
                or artifact.is_symlink()
                or not _fx_is_hex(digest, (64,))
            ):
                errors.append("primary_artifact_output_missing_or_unsafe:{}".format(path_text))
            elif digest != _fx_sha256_file(artifact):
                errors.append("primary_artifact_output_hash_mismatch:{}".format(path_text))
    required_artifact_kind = {
        "contract": "contract_report",
        "real_reference": "comparison_preview",
        "fault_injection": "fault_report",
        "live_dcc": "render_output",
        "live_model": "provider_response",
        "model_skill_conformance": "skill_conformance_report",
    }.get(evidence_kind)
    if required_artifact_kind and required_artifact_kind not in declared_artifact_kinds:
        errors.append(
            "primary_artifact_required_output_kind_missing:{}".format(
                required_artifact_kind
            )
        )

    if evidence_kind == "contract" and payload.get("contract_available") is not True:
        errors.append("contract_harness_not_passed")
    if evidence_kind in {"real_reference", "fault_injection"} and payload.get("case_validated") is not True:
        errors.append("case_harness_not_passed")
    if evidence_kind == "live_dcc":
        for field in ("application", "application_build"):
            if str(payload.get(field) or "") != str(entry.get(field) or ""):
                errors.append("primary_artifact_{}_mismatch".format(field))
        if payload.get("render_validated") is not True:
            errors.append("live_dcc_render_not_validated")
        if str(payload.get("renderer") or "").lower() != str(entry.get("renderer") or "").lower():
            errors.append("live_dcc_renderer_mismatch")
        if payload.get("semantic_control_coverage") != entry.get("semantic_control_coverage"):
            errors.append("live_dcc_semantic_control_coverage_mismatch")
    if evidence_kind == "live_model":
        for field in ("model_role", "model_name", "provider_response_sha256"):
            if str(payload.get(field) or "") != str(entry.get(field) or ""):
                errors.append("model_harness_{}_mismatch".format(field))
        if payload.get("identity_verified") is not True:
            errors.append("model_harness_identity_not_verified")
    if evidence_kind == "model_skill_conformance":
        for field in (
            "route_id", "ui_control_evidence_id", "ui_control_evidence_identity",
            "suite_id", "suite_version", "suite_sha256", "driver_sha256",
            "conformance_report_sha256",
        ):
            if str(payload.get(field) or "") != str(entry.get(field) or ""):
                errors.append("doubao_conformance_{}_mismatch".format(field))
        if payload.get("all_required_cases_passed") is not True:
            errors.append("doubao_conformance_cases_not_passed")
    return errors


def _fx_git_state() -> tuple[str, str]:
    """Bind live support claims to this exact checkout, including untracked bytes."""

    def run(*args: str) -> bytes:
        return subprocess.run(
            ["git", "-C", str(_FX_REPOSITORY_ROOT), *args],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        ).stdout

    try:
        commit = run("rev-parse", "HEAD").decode("ascii").strip()
        status = run("status", "--porcelain=v1", "-z", "--untracked-files=all", "--", ".", ":(exclude)outputs/live-validation/**")
        diff = run("diff", "--binary", "--", ".", ":(exclude)outputs/live-validation/**")
        staged = run("diff", "--cached", "--binary", "--", ".", ":(exclude)outputs/live-validation/**")
    except (OSError, subprocess.SubprocessError, UnicodeError):
        return "", ""
    digest = hashlib.sha256()
    digest.update(status)
    digest.update(b"\0DIFF\0")
    digest.update(diff)
    digest.update(b"\0STAGED\0")
    digest.update(staged)
    repository_root = _FX_REPOSITORY_ROOT.resolve()
    for record in status.split(b"\0"):
        if not record.startswith(b"?? "):
            continue
        relative = record[3:].decode("utf-8", errors="surrogateescape")
        relative_path = Path(relative)
        if relative_path.is_absolute() or ".." in relative_path.parts:
            return "", ""
        unresolved = repository_root / relative_path
        encoded_relative = relative.encode("utf-8", errors="surrogateescape")
        if unresolved.is_symlink():
            try:
                link_target = os.readlink(unresolved)
            except OSError:
                return "", ""
            digest.update(encoded_relative)
            digest.update(b"\0SYMLINK\0")
            digest.update(link_target.encode("utf-8", errors="surrogateescape"))
            continue
        try:
            artifact = unresolved.resolve()
            artifact.relative_to(repository_root)
        except ValueError:
            return "", ""
        if not artifact.is_file():
            return "", ""
        digest.update(encoded_relative)
        digest.update(hashlib.sha256(artifact.read_bytes()).digest())
    return commit, digest.hexdigest()


def _fx_valid_evidence_entries(pack_id: str, pack: dict[str, Any]) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    index_path = _fx_support_index_path()
    diagnostics: dict[str, Any] = {
        "index_path": str(index_path),
        "index_available": False,
        "index_sha256": None,
        "rejected_entries": [],
    }
    if not index_path.is_file() or _fx_path_has_symlink(index_path):
        return [], diagnostics
    try:
        payload = json.loads(index_path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        diagnostics["index_error"] = str(exc)
        return [], diagnostics
    if payload.get("schema_version") != 1 or not isinstance(payload.get("entries"), list):
        diagnostics["index_error"] = "unsupported evidence-index schema"
        return [], diagnostics
    diagnostics["index_available"] = True
    diagnostics["index_sha256"] = _fx_sha256_file(index_path)
    root = index_path.parents[2]
    host_contract, host_contract_error = _fx_host_semantic_contract(pack_id)
    addon_contract = _fx_pack_semantic_contract(pack)
    semantic_contract_matches = host_contract is not None and host_contract == addon_contract
    diagnostics["host_addon_semantic_contract_matches"] = semantic_contract_matches
    if host_contract_error:
        diagnostics["host_catalog_error"] = host_contract_error
    relevant_entries = [
        raw
        for raw in payload["entries"]
        if isinstance(raw, dict) and raw.get("domain_pack") == pack_id and raw.get("status") == "passed"
    ]
    if not relevant_entries:
        diagnostics["valid_evidence_ids"] = []
        return [], diagnostics
    attestation_key = _fx_load_evidence_attestation_key()
    diagnostics["attestation_key_available"] = attestation_key is not None
    current_commit, current_dirty_digest = _fx_git_state()
    diagnostics["git_state_available"] = bool(current_commit and current_dirty_digest)
    contract_sha256 = _fx_pack_contract_sha256(pack)
    addon_sha256 = _fx_sha256_file(_FX_ADDON_SOURCE)
    catalog_sha256 = _fx_sha256_file(_FX_CATALOG_SOURCE) if _FX_CATALOG_SOURCE.is_file() else ""
    valid: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    for raw in relevant_entries:
        entry_id = str(raw.get("evidence_id") or "").strip()
        reasons: list[str] = []
        if not semantic_contract_matches:
            reasons.append("host_addon_semantic_contract_mismatch")
        if not entry_id or entry_id in seen_ids:
            reasons.append("missing_or_duplicate_evidence_id")
        if entry_id:
            seen_ids.add(entry_id)
        if str(raw.get("pack_version") or "") != "1.0.0":
            reasons.append("pack_version_mismatch")
        if not current_commit or not _fx_is_hex(raw.get("git_commit"), (40, 64)) or str(raw.get("git_commit")) != current_commit:
            reasons.append("git_commit_mismatch")
        if not current_dirty_digest or not _fx_is_hex(raw.get("dirty_diff_digest"), (64,)) or str(raw.get("dirty_diff_digest")) != current_dirty_digest:
            reasons.append("dirty_diff_digest_mismatch")
        executed_at = str(raw.get("executed_at") or "")
        try:
            parsed = datetime.fromisoformat(executed_at.replace("Z", "+00:00"))
            if parsed.tzinfo is None:
                raise ValueError("timezone missing")
        except ValueError:
            reasons.append("executed_at_invalid")
        probe_level = str(raw.get("probe_level") or "")
        if probe_level not in {"contract", "runtime", "render", "end_to_end"}:
            reasons.append("probe_level_invalid")
        if not str(raw.get("execution_entrypoint") or "").strip():
            reasons.append("execution_entrypoint_missing")
        if str(raw.get("domain_contract_sha256") or "") != contract_sha256:
            reasons.append("domain_contract_sha256_mismatch")
        if str(raw.get("evidence_identity") or "") != _fx_entry_identity(raw):
            reasons.append("evidence_identity_mismatch")
        if not _fx_evidence_attestation_valid(raw, attestation_key):
            reasons.append("evidence_attestation_invalid_or_unavailable")
        source = _fx_resolve_evidence_artifact(root, raw.get("source_path"))
        if source is None or not source.is_file() or source.is_symlink():
            reasons.append("source_missing")
        elif str(raw.get("source_sha256") or "") != _fx_sha256_file(source):
            reasons.append("source_sha256_mismatch")
        application = str(raw.get("application") or "")
        expected_addon = _FX_NUKE_ADDON_SOURCE if application == "nuke" else _FX_ADDON_SOURCE
        addon_source = _fx_resolve_evidence_artifact(root, raw.get("addon_source_path"))
        if addon_source is None or addon_source != expected_addon or not addon_source.is_file():
            reasons.append("addon_source_mismatch")
        elif str(raw.get("addon_source_sha256") or "") != _fx_sha256_file(addon_source):
            reasons.append("addon_source_sha256_mismatch")
        catalog_source = _fx_resolve_evidence_artifact(root, raw.get("catalog_source_path"))
        if catalog_source is None or catalog_source != _FX_CATALOG_SOURCE or not catalog_source.is_file():
            reasons.append("catalog_source_mismatch")
        elif str(raw.get("catalog_source_sha256") or "") != catalog_sha256:
            reasons.append("catalog_source_sha256_mismatch")
        if raw.get("evidence_kind") == "live_dcc":
            build = str(raw.get("application_build") or "")
            if probe_level not in {"runtime", "render", "end_to_end"}:
                reasons.append("live_dcc_probe_level_too_low")
            if application == "houdini":
                if build not in _FX_KNOWN_HOUDINI_BUILDS:
                    reasons.append("houdini_exact_build_mismatch")
                if addon_source != _FX_ADDON_SOURCE or str(raw.get("addon_source_sha256") or "") != addon_sha256:
                    reasons.append("houdini_addon_identity_mismatch")
                if not bool(raw.get("render_validated")) or str(raw.get("renderer") or "").lower() != "karma":
                    reasons.append("karma_render_not_validated")
            elif application == "nuke":
                if build != _FX_REQUIRED_NUKE_BUILD:
                    reasons.append("nuke_exact_build_mismatch")
                if addon_source != _FX_NUKE_ADDON_SOURCE:
                    reasons.append("nuke_addon_identity_mismatch")
            else:
                reasons.append("live_dcc_application_invalid")
        artifact_paths = raw.get("artifact_paths")
        artifact_hashes = raw.get("artifact_sha256")
        if not isinstance(artifact_paths, list) or not artifact_paths or not isinstance(artifact_hashes, dict):
            reasons.append("artifact_manifest_missing")
        else:
            for item in artifact_paths:
                artifact = _fx_resolve_evidence_artifact(root, item)
                if artifact is None or not artifact.is_file() or artifact.is_symlink():
                    reasons.append("artifact_missing:{}".format(item))
                    continue
                if str(artifact_hashes.get(str(item)) or "") != _fx_sha256_file(artifact):
                    reasons.append("artifact_sha256_mismatch:{}".format(item))
        reasons.extend(_fx_support_harness_errors(raw, root))
        if raw.get("evidence_kind") == "live_model":
            provider_digest = str(raw.get("provider_response_sha256") or "")
            if raw.get("identity_verified") is not True:
                reasons.append("model_identity_not_verified")
            if not _fx_is_hex(provider_digest, (64,)) or not isinstance(artifact_hashes, dict) or provider_digest not in {str(value) for value in artifact_hashes.values()}:
                reasons.append("provider_response_artifact_mismatch")
        if raw.get("evidence_kind") == "model_skill_conformance":
            report_digest = str(raw.get("conformance_report_sha256") or "")
            if str(raw.get("route_id") or "") != "DoubaoDesktopRoute":
                reasons.append("doubao_route_id_mismatch")
            for field in ("ui_control_evidence_id", "suite_id", "suite_version"):
                if not str(raw.get(field) or "").strip():
                    reasons.append("{}_missing".format(field))
            for field in ("ui_control_evidence_identity", "suite_sha256", "driver_sha256"):
                if not _fx_is_hex(raw.get(field), (64,)):
                    reasons.append("{}_invalid".format(field))
            if not _fx_is_hex(report_digest, (64,)) or not isinstance(artifact_hashes, dict) or report_digest not in {str(value) for value in artifact_hashes.values()}:
                reasons.append("conformance_report_artifact_mismatch")
        if reasons:
            diagnostics["rejected_entries"].append({"evidence_id": entry_id or None, "reasons": reasons})
            continue
        valid.append(dict(raw))
    diagnostics["valid_evidence_ids"] = [str(entry["evidence_id"]) for entry in valid]
    return valid, diagnostics


def _fx_valid_doubao_route() -> tuple[Optional[dict[str, Any]], dict[str, Any]]:
    """Validate the global Doubao UI-control gate for the exact local route."""

    index_path = _fx_support_index_path()
    diagnostics: dict[str, Any] = {"route_id": "DoubaoDesktopRoute", "rejected_entries": []}
    try:
        payload = json.loads(index_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None, diagnostics
    rows = payload.get("model_routes") or []
    if not isinstance(rows, list):
        diagnostics["index_error"] = "model_routes_not_a_list"
        return None, diagnostics
    root = index_path.parents[2]
    key = _fx_load_evidence_attestation_key()
    commit, dirty = _fx_git_state()
    for raw in rows:
        if not isinstance(raw, dict) or raw.get("route_id") != "DoubaoDesktopRoute":
            continue
        reasons: list[str] = []
        if raw.get("status") != "passed" or raw.get("bundle_id") != "com.bot.pc.doubao":
            reasons.append("route_identity_mismatch")
        if str(raw.get("git_commit") or "") != commit or str(raw.get("dirty_diff_digest") or "") != dirty:
            reasons.append("git_identity_mismatch")
        if str(raw.get("evidence_identity") or "") != _fx_entry_identity(raw):
            reasons.append("evidence_identity_mismatch")
        if not _fx_evidence_attestation_valid(raw, key):
            reasons.append("evidence_attestation_invalid_or_unavailable")
        executable = Path(str(raw.get("executable_path") or "")).expanduser()
        if not executable.is_absolute() or executable.is_symlink() or not executable.is_file():
            reasons.append("doubao_executable_missing_or_unsafe")
        elif str(raw.get("executable_sha256") or "") != _fx_sha256_file(executable):
            reasons.append("doubao_executable_sha256_mismatch")
        driver = _fx_resolve_evidence_artifact(root, raw.get("driver_source_path"))
        if driver is None or not driver.is_file() or driver.is_symlink():
            reasons.append("driver_source_missing_or_unsafe")
        elif str(raw.get("driver_sha256") or "") != _fx_sha256_file(driver):
            reasons.append("driver_sha256_mismatch")
        cycles = raw.get("read_cycles")
        if not isinstance(cycles, list) or len(cycles) < 5 or not all(value is True for value in cycles):
            reasons.append("five_ui_read_cycles_required")
        if raw.get("isolated_session_verified") is not True or raw.get("existing_conversations_touched") is not False:
            reasons.append("isolated_session_boundary_failed")
        if raw.get("synthetic_inputs_only") is not True:
            reasons.append("synthetic_inputs_only_required")
        if raw.get("composer_verified") is not True or raw.get("image_entry_verified") is not True:
            reasons.append("composer_or_image_entry_unverified")
        if not any(
            isinstance(gate, dict)
            and gate.get("name") == "doubao_ui_control_verified"
            and gate.get("kind") == "verification"
            and gate.get("passed") is True
            for gate in raw.get("gates") or []
        ):
            reasons.append("doubao_ui_control_verification_gate_missing")
        paths = raw.get("artifact_paths")
        hashes = raw.get("artifact_sha256")
        event_digest = str(raw.get("event_manifest_sha256") or "")
        if not isinstance(paths, list) or not paths or not isinstance(hashes, dict):
            reasons.append("route_artifact_manifest_missing")
        else:
            for item in paths:
                artifact = _fx_resolve_evidence_artifact(root, item)
                if artifact is None or not artifact.is_file() or artifact.is_symlink() or str(hashes.get(str(item)) or "") != _fx_sha256_file(artifact):
                    reasons.append("route_artifact_invalid:{}".format(item))
            if not _fx_is_hex(event_digest, (64,)) or event_digest not in {str(value) for value in hashes.values()}:
                reasons.append("event_manifest_artifact_mismatch")
        if not reasons:
            diagnostics["evidence_id"] = raw.get("evidence_id")
            return dict(raw), diagnostics
        diagnostics["rejected_entries"].append({"evidence_id": raw.get("evidence_id"), "reasons": reasons})
    return None, diagnostics


def _fx_validation_state(pack_id: str, pack: dict[str, Any], current_build: Optional[str] = None) -> dict[str, Any]:
    if current_build is None:
        try:
            import hou

            current_build = str(hou.applicationVersionString())
        except Exception:
            current_build = ""
    entries, diagnostics = _fx_valid_evidence_entries(pack_id, pack)

    def matches(kind: str, **fields: str) -> list[dict[str, Any]]:
        return [
            entry
            for entry in entries
            if entry.get("evidence_kind") == kind
            and all(str(entry.get(name) or "") == value for name, value in fields.items())
        ]

    houdini_entries = matches("live_dcc", application="houdini")
    validated_builds = sorted(
        {
            str(entry.get("application_build"))
            for entry in houdini_entries
            if str(entry.get("application_build") or "") in _FX_KNOWN_HOUDINI_BUILDS
            and bool(entry.get("render_validated"))
            and str(entry.get("renderer") or "").lower() == "karma"
        }
    )
    contract_ok = bool(matches("contract"))
    reference_ok = bool(matches("real_reference"))
    fault_ok = bool(matches("fault_injection"))
    required_houdini_ok = all(build in validated_builds for build in _FX_REQUIRED_HOUDINI_BUILDS)
    nuke_ok = True
    if pack_id == "explosion_composite_v1":
        nuke_ok = bool(matches("live_dcc", application="nuke", application_build=_FX_REQUIRED_NUKE_BUILD))
    live_validated = contract_ok and reference_ok and fault_ok and required_houdini_ok and nuke_ok
    doubao_route, doubao_diagnostics = _fx_valid_doubao_route()
    doubao_ok = bool(
        doubao_route
        and matches(
            "model_skill_conformance",
            route_id="DoubaoDesktopRoute",
            ui_control_evidence_id=str(doubao_route.get("evidence_id") or ""),
            ui_control_evidence_identity=str(doubao_route.get("evidence_identity") or ""),
            driver_sha256=str(doubao_route.get("driver_sha256") or ""),
        )
    )
    current_build_validated = bool(current_build and current_build in validated_builds)

    def coverage_ok(entry: dict[str, Any], controls: set[str]) -> bool:
        coverage = entry.get("semantic_control_coverage")
        flags = ("addressable", "writable", "readback_verified", "restore_verified")
        return isinstance(coverage, dict) and all(
            isinstance(coverage.get(name), dict)
            and all(coverage[name].get(flag) is True for flag in flags)
            for name in controls
        )

    controls_by_application: dict[str, set[str]] = {}
    for name, control in (pack.get("controls") or {}).items():
        application = str(control.get("application") or "houdini")
        controls_by_application.setdefault(application, set()).add(str(name))
    control_coverage_ok = True
    for application, controls in controls_by_application.items():
        builds = _FX_REQUIRED_HOUDINI_BUILDS if application == "houdini" else (_FX_REQUIRED_NUKE_BUILD,)
        for build in builds:
            if controls and not any(
                entry.get("evidence_kind") == "live_dcc"
                and entry.get("application") == application
                and entry.get("application_build") == build
                and coverage_ok(entry, controls)
                for entry in entries
            ):
                control_coverage_ok = False
    supported = live_validated and doubao_ok and current_build_validated and control_coverage_ok
    return {
        "current_build": current_build,
        "current_build_validated": current_build_validated,
        "validated_houdini_versions": validated_builds,
        "houdini_21_validated": _FX_REQUIRED_HOUDINI_BUILDS[0] in validated_builds,
        "houdini_22_validated": _FX_REQUIRED_HOUDINI_BUILDS[1] in validated_builds,
        "karma_render_validated": current_build_validated,
        "live_validated": live_validated,
        "supported": supported,
        "semantic_control_coverage_validated": control_coverage_ok,
        "maturity": "supported" if supported else ("live-validated" if live_validated else "experimental"),
        "source_sha256": _fx_sha256_file(_FX_ADDON_SOURCE),
        "domain_contract_sha256": _fx_pack_contract_sha256(pack),
        "evidence": diagnostics,
        "doubao_acceptance": {"passed": doubao_ok, "route": doubao_diagnostics},
    }


def _fx_validation_flags(pack: dict[str, Any], pack_id: Optional[str] = None, current_build: Optional[str] = None) -> dict[str, bool]:
    """Return evidence-backed flags; legacy static version fields are ignored."""

    identifier = str(pack_id or pack.get("id") or "")
    if not identifier:
        return {"houdini_21_validated": False, "houdini_22_validated": False, "karma_render_validated": False}
    state = _fx_validation_state(identifier, pack, current_build=current_build)
    return {
        "houdini_21_validated": bool(state["houdini_21_validated"]),
        "houdini_22_validated": bool(state["houdini_22_validated"]),
        "karma_render_validated": bool(state["karma_render_validated"]),
    }


class BridgeCommandError(RuntimeError):
    """A stable structured error returned across the HTTP bridge."""

    def __init__(self, code: str, message: str, hint: Optional[str] = None) -> None:
        super().__init__(message)
        self.code = code
        self.hint = hint


def _fx_node(role: str, category: str, types: list[str], input_role: Optional[str] = None, parms: Optional[list[list[str]]] = None) -> dict[str, Any]:
    return {"role": role, "category": category, "types": types, "input_role": input_role, "required_parms": parms or []}


def _fx_control(role: str, aliases: list[str], minimum: float, maximum: float, value_type: str = "float", invalidates_from: str = "generation_simulation", application: str = "houdini") -> dict[str, Any]:
    return {"role": role, "aliases": aliases, "minimum": minimum, "maximum": maximum, "value_type": value_type, "invalidates_from": invalidates_from, "application": application}


_SPHERE = _fx_node("source", "sop", ["sphere"], parms=[["radx", "radius"]])
_GRID = _fx_node("source", "sop", ["grid"], parms=[["sizex", "size1"], ["sizey", "size2"]])
_NULL_OUTPUT = _fx_node("output", "sop", ["null"])


