def _press_button_async(parm: Any, on_error: Any = None) -> None:
    """Schedule a potentially long ROP button press after the RPC returns.

    Karma's execute button may block Houdini's UI thread while husk initializes
    delegates, even though it ultimately writes the image asynchronously.  If
    the HTTP request waits for that call, the client can time out while the DCC
    is still doing useful work.  Registering a one-shot UI callback keeps the
    Houdini API call on the main thread but lets the bridge acknowledge the
    render request immediately; the host adapter then waits on the exact output
    file before advancing to verification.
    """
    import hou

    if not hou.isUIAvailable():
        # Headless hython has no event-loop callback facility.  Keep the API
        # contract correct there; callers can choose a longer HTTP timeout.
        try:
            parm.pressButton()
        except Exception as exc:
            if on_error is not None:
                on_error(exc)
            raise
        return

    def callback() -> None:
        try:
            parm.pressButton()
        except Exception as exc:  # pragma: no cover - only exercised in DCC
            if on_error is not None:
                on_error(exc)
            try:
                print("Houdini Bridge render callback failed: {}".format(exc), file=sys.stderr)
            except Exception:
                pass
        finally:
            try:
                hou.ui.removeEventLoopCallback(callback)
            except Exception:
                pass

    hou.ui.addEventLoopCallback(callback)


def _state_dir() -> Path:
    # Explicit override for tests and sandboxed deployments; production
    # never sets it, so the default per-user location is used.
    override = os.environ.get("HOUDINI_BRIDGE_STATE_DIR")
    if override:
        return Path(override).expanduser() / "instances"
    if sys.platform == "win32":
        root = Path(os.environ.get("LOCALAPPDATA", Path.home() / "AppData" / "Local"))
        return root / "HoudiniBridge" / "instances"
    if sys.platform == "darwin":
        return Path.home() / "Library" / "Application Support" / "HoudiniBridge" / "instances"
    return Path(os.environ.get("XDG_STATE_HOME", Path.home() / ".local" / "state")) / "houdini-bridge" / "instances"


def _ensure_secure_state_directory(directory: Path) -> None:
    """Create/validate the private manifest directory without following links."""

    directory = directory.absolute()
    if _fx_path_has_symlink(directory):
        raise RuntimeError("Houdini Bridge state directory must not traverse a symlink")
    ancestor = directory
    while True:
        try:
            ancestor_info = ancestor.lstat()
            break
        except FileNotFoundError:
            if ancestor.parent == ancestor:
                raise RuntimeError("Houdini Bridge state directory has no existing trusted parent")
            ancestor = ancestor.parent
    if ancestor.is_symlink() or not stat.S_ISDIR(ancestor_info.st_mode):
        raise RuntimeError("Houdini Bridge state parent must be a real directory")
    if os.name != "nt" and (
        ancestor_info.st_uid != os.getuid() or stat.S_IMODE(ancestor_info.st_mode) & 0o022
    ):
        raise RuntimeError("Houdini Bridge state parent must be owner-controlled")
    directory.mkdir(mode=0o700, parents=True, exist_ok=True)
    if os.name == 'nt':
        from dcc_task_runtime.platform_support import set_private_permissions
        set_private_permissions(directory)
    info = directory.lstat()
    if directory.is_symlink() or not stat.S_ISDIR(info.st_mode):
        raise RuntimeError("Houdini Bridge state directory must be a real directory")
    if os.name != "nt" and (info.st_uid != os.getuid() or stat.S_IMODE(info.st_mode) & 0o022):
        raise RuntimeError("Houdini Bridge state directory must be owner-controlled")


def _write_private_file_exclusive(path: Path, payload: bytes) -> None:
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    created = False
    try:
        if os.name == 'nt':
            from dcc_task_runtime.platform_support import open_private_file
            descriptor = open_private_file(path,flags)
        else:
            descriptor = os.open(str(path), flags, 0o600)
        created = True
        try:
            remaining = memoryview(payload)
            while remaining:
                written = os.write(descriptor, remaining)
                if written <= 0:
                    raise OSError("short write while creating private Bridge state")
                remaining = remaining[written:]
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        info = path.lstat()
        if path.is_symlink() or not stat.S_ISREG(info.st_mode):
            raise RuntimeError("Houdini Bridge private state file is not regular")
        if os.name != "nt" and (info.st_uid != os.getuid() or stat.S_IMODE(info.st_mode) != 0o600):
            raise RuntimeError("Houdini Bridge private state file must be owner-only")
    except Exception:
        if created:
            path.unlink(missing_ok=True)
        raise


def _error(code: str, message: str, hint: Optional[str] = None) -> dict[str, Any]:
    return {"status": "error", "error": {"code": code, "message": message, "hint": hint}}


def _success(data: Any) -> dict[str, Any]:
    return {"status": "success", "data": data}


def _json_safe(value: Any) -> Any:
    """Return a deterministic JSON-compatible representation of DCC values."""
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, dict):
        return {str(key): _json_safe(item) for key, item in sorted(value.items(), key=lambda pair: str(pair[0]))}
    if isinstance(value, (list, tuple)):
        return [_json_safe(item) for item in value]
    if type(value).__name__ == "Ramp" and all(callable(getattr(value, name, None)) for name in ("keys", "values", "basis")):
        return {"type": "ramp", "keys": _json_safe(value.keys()),
                "values": _json_safe(value.values()), "basis": [str(item) for item in value.basis()]}
    return str(value)


class _Request:
    def __init__(self, command: str, params: dict[str, Any]) -> None:
        self.command = command
        self.params = params
        self.done = threading.Event()
        self.response: Optional[dict[str, Any]] = None
        self.cancelled = False
        self.state = "PENDING"
        self.lock = threading.Lock()


_FX_LISTENER_TRACE_LOCK = threading.Lock()
_FX_LISTENER_TRACE_MAX_BYTES = 65536
_FX_LISTENER_TRACE_MAX_ROWS = 64


def _fx_listener_trace(phase, *, expected_server=None, stop_reason=None):
    """Best-effort bounded socket observations; never affect host commands."""
    try:
        raw_root = os.environ.get("HOUDINI_BRIDGE_TASK_STATE_DIR")
        if not raw_root:
            return
        from dcc_task_runtime.platform_support import ensure_private_directory, lock_file
        root = Path(raw_root)
        if not root.is_absolute() or root != root.resolve() or any(p.is_symlink() for p in (root, *root.parents)):
            return
        ensure_private_directory(root)
        server = globals().get("_SERVER")
        observed = expected_server if expected_server is not None else server
        row = {"schema": "bridge.houdini.listener-trace/1", "phase": str(phase)[:64],
               "observed_at": time.time(), "process_id": os.getpid(),
               "scene_epoch": int(getattr(globals().get("_BRIDGE_SCENE_STATE"), "scene_epoch", 0)),
               "server_present": server is not None, "same_server": server is expected_server,
               "thread_alive": None, "socket_fd": None, "bound_port": None,
               "accepting": None, "fstat_dev": None, "fstat_ino": None, "fstat_kind": None}
        errors = []
        thread = getattr(observed, "_thread", None)
        if thread is not None:
            try:
                row["thread_alive"] = bool(thread.is_alive())
            except Exception as error:
                errors.append("thread:" + type(error).__name__)
        http = getattr(observed, "_http", None)
        listener = getattr(http, "socket", None)
        if listener is not None:
            for name, read in (
                    ("socket_fd", listener.fileno),
                    ("bound_port", lambda: listener.getsockname()[1]),
                    ("accepting", lambda: bool(listener.getsockopt(socket.SOL_SOCKET, socket.SO_ACCEPTCONN)))):
                try:
                    row[name] = read()
                except Exception as error:
                    errors.append(name + ":" + type(error).__name__)
            try:
                info = os.fstat(listener.fileno())
                row.update(fstat_dev=info.st_dev, fstat_ino=info.st_ino,
                           fstat_kind="socket" if stat.S_ISSOCK(info.st_mode) else "other")
            except Exception as error:
                errors.append("fstat:" + type(error).__name__)
        row["errors"] = errors[:6]
        if stop_reason is not None:
            import traceback
            row["stop_reason"] = stop_reason if stop_reason in {"explicit_stop", "startup_failure", "explicit_shutdown"} else "other"
            row["stack"] = [{"file": Path(item.filename).name[:80], "function": item.name[:80], "line": item.lineno}
                            for item in traceback.extract_stack(limit=6)[:-1]]
        payload = (json.dumps(row, ensure_ascii=True, separators=(",", ":"), allow_nan=False) + "\n").encode("ascii")
        if len(payload) > 2048:
            return
        if not _FX_LISTENER_TRACE_LOCK.acquire(blocking=False):
            return
        try:
            descriptor = os.open(root / "listener-trace.jsonl", os.O_CREAT | os.O_RDWR | os.O_APPEND
                                 | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NONBLOCK", 0), 0o600)
            try:
                lock_file(descriptor, blocking=False)
                info = os.fstat(descriptor)
                if (not stat.S_ISREG(info.st_mode) or info.st_size + len(payload) > _FX_LISTENER_TRACE_MAX_BYTES
                        or os.name != "nt" and (info.st_uid != os.getuid() or stat.S_IMODE(info.st_mode) != 0o600)):
                    return
                existing = os.read(descriptor, _FX_LISTENER_TRACE_MAX_BYTES + 1)
                if existing.count(b"\n") >= _FX_LISTENER_TRACE_MAX_ROWS:
                    return
                os.write(descriptor, payload)
            finally:
                os.close(descriptor)
        finally:
            _FX_LISTENER_TRACE_LOCK.release()
    except Exception:
        pass


class HoudiniBridgeServer:
    def __init__(
        self,
        *,
        token: Optional[str] = None,
        allowed_commands: Optional[set[str] | frozenset[str] | list[str] | tuple[str, ...]] = None,
        allow_legacy_unauthenticated: bool = False,
    ) -> None:
        if allow_legacy_unauthenticated:
            if token not in (None, ""):
                raise ValueError("legacy unauthenticated mode cannot be combined with a token")
            normalized_token = ""
        else:
            normalized_token = str(token) if token is not None else secrets.token_urlsafe(32)
            if not normalized_token:
                raise ValueError("Houdini Bridge token must not be empty")
        if normalized_token and len(normalized_token) < 32:
            raise ValueError("Houdini Bridge token must contain at least 32 characters")
        try:
            normalized_token.encode("ascii")
        except UnicodeEncodeError as exc:
            raise ValueError("Houdini Bridge token must be ASCII") from exc
        if any(character.isspace() for character in normalized_token):
            raise ValueError("Houdini Bridge token must not contain whitespace")
        normalized_commands = (
            _DEFAULT_BRIDGE_COMMANDS
            if allowed_commands is None
            else frozenset(str(command).strip() for command in allowed_commands if str(command).strip())
        )
        self.session_id = uuid4().hex
        self._queue: queue.Queue[_Request] = queue.Queue(maxsize=4)
        self._http: Optional[ThreadingHTTPServer] = None
        self._thread: Optional[threading.Thread] = None
        self.port: Optional[int] = None
        self._manifest: Optional[Path] = None
        self._token_file: Optional[Path] = None
        self._token = normalized_token or None
        self._allowed_commands = normalized_commands

    def start(self) -> int:
        if self._http is not None and self.port is not None:
            return self.port
        last_bind_error = None
        for port in range(8100, 8200):
            try:
                http = self._make_http(port)
            except OSError as exc:
                if exc.errno != errno.EADDRINUSE and not (
                        os.name == 'nt' and getattr(exc, 'winerror', None) in (10013,10048)):
                    raise RuntimeError(
                        f"HOUDINI_BRIDGE_BIND_FAILED address=127.0.0.1:{port} errno={exc.errno}: {exc}"
                    ) from exc
                last_bind_error = exc
                continue
            self._http = http
            self.port = port
            self._thread = threading.Thread(target=http.serve_forever, name="houdini-bridge-http", daemon=True)
            self._thread.start()
            try:
                self._write_manifest()
                self._register_pump()
            except Exception:
                self.stop(reason="startup_failure")
                raise
            return port
        raise RuntimeError(
            f"no free Houdini Bridge port in 8100..8199; errno={last_bind_error.errno}: {last_bind_error}"
        ) from last_bind_error

    def stop(self, *, reason="explicit_stop") -> None:
        _fx_listener_trace("listener_stop", expected_server=self, stop_reason=reason)
        if self._http is not None:
            self._http.shutdown()
            self._http.server_close()
        self._http = None
        self._thread = None
        self.port = None
        if self._manifest is not None:
            self._manifest.unlink(missing_ok=True)
        self._manifest = None
        if self._token_file is not None:
            self._token_file.unlink(missing_ok=True)
        self._token_file = None

    def _make_http(self, port: int) -> ThreadingHTTPServer:
        owner = self

        class Handler(BaseHTTPRequestHandler):
            def _send_json(self, response: dict[str, Any], status: int = 200) -> None:
                body = json.dumps(response, ensure_ascii=False).encode("utf-8")
                self.send_response(status)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)

            def do_POST(self) -> None:  # noqa: N802
                if self.path != "/api":
                    self.send_error(404)
                    return
                authorization_error = owner._authorize_http(self.headers)
                if authorization_error is not None:
                    self._send_json(authorization_error, status=403)
                    return
                try:
                    length = int(self.headers.get("Content-Length", "0"))
                except ValueError:
                    self._send_json(_error("INVALID_REQUEST", "invalid Content-Length"), status=400)
                    return
                if self.headers.get("Transfer-Encoding") or length <= 0 or length > 4 * 1024 * 1024:
                    self._send_json(_error("INVALID_REQUEST", "request body must contain 1..4194304 bytes with Content-Length"), status=413)
                    return
                try:
                    self.connection.settimeout(10.0)
                    body = self.rfile.read(length)
                    if len(body) != length:
                        self._send_json(_error("INVALID_REQUEST", "truncated request body"), status=400)
                        return
                    form = parse_qs(body.decode("utf-8"), keep_blank_values=True, max_num_fields=16)
                    request = json.loads(form["json"][0])
                    response = owner.rpc(request)
                except (KeyError, IndexError, json.JSONDecodeError, TypeError, ValueError, OSError) as exc:
                    response = _error("INVALID_REQUEST", str(exc))
                self._send_json(response)

            def log_message(self, _format: str, *_args: Any) -> None:
                return

        class LoopbackServer(ThreadingHTTPServer):
            allow_reuse_address = os.name != 'nt'

            def server_bind(self):
                if os.name == 'nt':
                    self.socket.setsockopt(socket.SOL_SOCKET,socket.SO_EXCLUSIVEADDRUSE,1)
                super().server_bind()

        return LoopbackServer(("127.0.0.1", port), Handler)

    def _authorize_http(self, headers: Any) -> Optional[dict[str, Any]]:
        origin = str(headers.get("Origin") or "").strip().rstrip("/")
        if origin:
            same_process_origins = {
                "http://127.0.0.1:{}".format(self.port),
                "http://localhost:{}".format(self.port),
            }
            if origin not in same_process_origins:
                return _error("CROSS_SITE_ORIGIN_REJECTED", "cross-site Origin is not allowed")
        if self._token is None:
            return None
        authorization = str(headers.get("Authorization") or "").strip()
        supplied = authorization[7:].strip() if authorization.lower().startswith("bearer ") else ""
        if not supplied:
            supplied = str(headers.get("X-Houdini-Bridge-Token") or "").strip()
        if not supplied or not hmac.compare_digest(supplied, self._token):
            return _error("AUTH_REQUIRED", "a valid Houdini Bridge token is required")
        return None

    def _register_pump(self) -> None:
        import hou

        if hou.isUIAvailable():
            hou.ui.addEventLoopCallback(self.pump)

    def _write_manifest(self) -> None:
        import hou

        directory = _state_dir()
        _ensure_secure_state_directory(directory)
        self._manifest = directory / f"{os.getpid()}.json"
        token_file_name = None
        if self._token is not None:
            self._token_file = directory / "{}.{}.token".format(os.getpid(), uuid4().hex)
            _write_private_file_exclusive(self._token_file, self._token.encode("ascii"))
            token_file_name = self._token_file.name
        payload = {
            "pid": os.getpid(),
            "session_id": self.session_id,
            "loaded_addon_sha256": _FX_LOADED_ADDON_SHA256,
            "port": self.port,
            "houdini_version": hou.applicationVersionString(),
            "edition": hou.licenseCategory().name(),
            "hip_path": hou.hipFile.path(),
            "gui": bool(hou.isUIAvailable()),
            "token_file": token_file_name,
            "allowed_commands": sorted(self._allowed_commands) if self._allowed_commands is not None else None,
        }
        temporary = directory / ".{}.{}.tmp".format(self._manifest.name, uuid4().hex)
        temporary_created = False
        try:
            _write_private_file_exclusive(
                temporary,
                (json.dumps(payload, ensure_ascii=False, indent=2) + "\n").encode("utf-8"),
            )
            temporary_created = True
            os.replace(str(temporary), str(self._manifest))
            temporary_created = False
            manifest_info = self._manifest.lstat()
            if self._manifest.is_symlink() or not stat.S_ISREG(manifest_info.st_mode):
                raise RuntimeError("Houdini Bridge manifest is not a regular file")
            if os.name != "nt" and (
                manifest_info.st_uid != os.getuid() or stat.S_IMODE(manifest_info.st_mode) != 0o600
            ):
                raise RuntimeError("Houdini Bridge manifest must be owner-only")
        finally:
            if temporary_created:
                temporary.unlink(missing_ok=True)

    def rpc(self, value: list[Any]) -> dict[str, Any]:
        if not isinstance(value, list) or len(value) != 3:
            return _error("INVALID_REQUEST", "RPC body must be [method, args, kwargs]")
        method, _args, kwargs = value
        if method == "mcp.health":
            return self._submit("ping", {})
        if method != "mcp.execute" or not isinstance(kwargs, dict):
            return _error("INVALID_REQUEST", "unsupported RPC method")
        command = kwargs.get("command")
        params = kwargs.get("params") or {}
        if not isinstance(command, str) or not isinstance(params, dict):
            return _error("INVALID_REQUEST", "command must be a string and params must be an object")
        return self._submit(command, params)

    def _submit(self, command: str, params: dict[str, Any]) -> dict[str, Any]:
        if self._allowed_commands is not None and command not in self._allowed_commands:
            return _error("COMMAND_NOT_ALLOWED", "command is outside this server's allowlist: {}".format(command))
        request = _Request(command, params)
        try:
            self._queue.put_nowait(request)
        except queue.Full:
            return _error("BUSY", "Houdini main-thread queue is full", "Retry after a short delay")
        if not request.done.wait(120):
            # Do not leave timed-out HTTP requests queued for a later UI tick;
            # stale verification calls otherwise pile up behind a long husk
            # render and make the next request appear hung as well.
            with request.lock:
                if request.state == "COMPLETED":
                    return request.response or _error("INTERNAL_ERROR", "missing completed result")
                running = request.state == "RUNNING"
                if not running:
                    request.cancelled = True
                    request.state = "CANCELLED"
            result = _error("TIMEOUT", "Houdini request deadline exceeded")
            result["error"]["indeterminate"] = running
            result["error"]["operation_state"] = "RUNNING" if running else "CANCELLED_BEFORE_EXECUTION"
            return result
        return request.response or _error("INTERNAL_ERROR", "request completed without a response")

    def pump(self) -> None:
        for _ in range(4):
            try:
                request = self._queue.get_nowait()
            except queue.Empty:
                return
            with request.lock:
                if request.cancelled:
                    request.done.set()
                    continue
                request.state = "RUNNING"
            try:
                result = dispatch(request.command, request.params)
                if request.command == "ping" and isinstance(result, dict):
                    result = {**result, "port": self.port, "session_id": self.session_id, "loaded_addon_sha256": _FX_LOADED_ADDON_SHA256}
                request.response = _success(result)
            except BridgeCommandError as exc:
                request.response = _error(exc.code, str(exc), exc.hint)
            except Exception as exc:  # Houdini exceptions vary by version.
                request.response = _error("COMMAND_FAILED", str(exc))
            finally:
                with request.lock:
                    request.state = "COMPLETED"
                    request.done.set()


def _node(path: str):
    import hou

    node = hou.node(path)
    if node is None:
        raise ValueError(f"node not found: {path}")
    return node


def _undo(label: str):
    import hou

    undos = getattr(hou, "undos", None)
    group = getattr(undos, "group", None)
    return group(label) if group else nullcontext()


def _native_parameter_value(parm, value):
    if isinstance(value, dict) and value.get('schema') == 'bridge.native-float-ramp/1':
        import hou

        if (set(value) != {'schema', 'basis', 'keys', 'values'}
                or str(parm.parmTemplate().type()).rsplit('.', 1)[-1] != 'Ramp'
                or value['basis'] != ['Linear', 'Linear']
                or value['keys'] != [0., 1.] or value['values'] != [0., 1.]
                or any(type(number) not in (int, float) for number in (*value['keys'], *value['values']))):
            raise BridgeCommandError('INVALID_ARGUMENT', 'unsupported native float ramp construction')
        return hou.Ramp((hou.rampBasis.Linear, hou.rampBasis.Linear),
                        tuple(value['keys']), tuple(value['values']))
    return value


def _set_parms(node, params: dict[str, Any]) -> dict[str, Any]:
    missing: list[str] = []
    for name, value in params.items():
        parm = node.parm(name)
        if parm is None:
            missing.append(name)
        else:
            parm.set(_native_parameter_value(parm, value))
    if missing:
        raise ValueError(f"unknown parameters on {node.path()}: {', '.join(missing)}")
    return {name: _json_safe(node.parm(name).eval()) for name in params}


def _safe_python(code: str) -> dict[str, Any]:
    import hou

    tree = ast.parse(code, mode="exec")
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            if any(alias.name.split(".")[0] not in _ALLOWED_IMPORTS for alias in node.names):
                raise ValueError("import is not allowlisted")
        if isinstance(node, ast.ImportFrom) and (node.module or "").split(".")[0] not in _ALLOWED_IMPORTS:
            raise ValueError("import is not allowlisted")
        if isinstance(node, ast.Name) and node.id in _FORBIDDEN_NAMES:
            raise ValueError(f"forbidden name: {node.id}")
        if isinstance(node, ast.Attribute) and node.attr.startswith("__"):
            raise ValueError("dunder attributes are forbidden")
    def safe_import(name, globals=None, locals=None, fromlist=(), level=0):
        root = name.split(".", 1)[0]
        if root not in _ALLOWED_IMPORTS:
            raise ImportError("import is not allowlisted")
        return builtins.__import__(name, globals, locals, fromlist, level)

    scope: dict[str, Any] = {"hou": hou, "__builtins__": {"True": True, "False": False, "None": None, "len": len, "range": range, "str": str, "int": int, "float": float, "list": list, "dict": dict, "__import__": safe_import}}
    exec(compile(tree, "<houdini-bridge>", "exec"), scope, scope)
    return {"result": scope.get("result")}


class _ResolvedParm:
    """One writable Houdini parameter target.

    HOM exposes scalar parameters through ``node.parm`` and multi-component
    parameters through ``node.parmTuple``.  Returning this small adapter from
    every lookup keeps probing, candidate application and readback verification
    on the same addressing rules instead of letting each call site guess.
    """

    def __init__(self, target: Any, alias: str, kind: str) -> None:
        self.target = target
        self.alias = alias
        self.kind = kind

    def _components(self) -> list[Any]:
        if self.kind == "parm":
            return [self.target]
        try:
            return list(self.target)
        except Exception:
            try:
                return list(self.target.parms())
            except Exception:
                return []

    @property
    def component_count(self) -> int:
        components = self._components()
        return len(components) if components else 1

    def eval(self) -> Any:
        return self.target.eval()

    def set(self, value: Any, *, follow_references: bool = True) -> None:
        if follow_references:
            self.target.set(value)
            return
        if self.kind == "parm":
            self.target.set(value, follow_parm_reference=False)
        else:
            self.target.set(value, follow_parm_references=False)

    def isDisabled(self) -> bool:  # noqa: N802 - mirrors HOM
        components = self._components()
        return any(bool(component.isDisabled()) for component in components)

    def isLocked(self) -> bool:  # noqa: N802 - mirrors HOM
        components = self._components()
        return any(bool(component.isLocked()) for component in components)

    def name(self) -> str:
        try:
            return str(self.target.name())
        except Exception:
            return self.alias

    def path(self) -> str:
        try:
            return str(self.target.path())
        except Exception:
            components = self._components()
            if components:
                try:
                    return str(components[0].path()).rsplit("/", 1)[0] + "/" + self.alias
                except Exception:
                    pass
            return self.alias

    def pressButton(self) -> None:  # noqa: N802 - mirrors HOM
        if self.kind != "parm":
            raise TypeError("a parameter tuple cannot be pressed as a button")
        self.target.pressButton()

    def __getattr__(self, name: str) -> Any:
        return getattr(self.target, name)


def _resolve_parm_target(node: Any, names: list[str]) -> Optional[_ResolvedParm]:
    """Resolve aliases exactly as all write paths will address them."""

    if node is None:
        return None
    for name in names:
        try:
            parm = node.parm(name)
        except Exception:
            parm = None
        if parm is not None:
            return _ResolvedParm(parm, str(name), "parm")
        try:
            parm_tuple = node.parmTuple(name)
        except Exception:
            parm_tuple = None
        if parm_tuple is not None:
            return _ResolvedParm(parm_tuple, str(name), "parm_tuple")
    return None


def _first_parm(node: Any, names: list[str]) -> Optional[_ResolvedParm]:
    """Compatibility alias for the unified scalar/tuple resolver."""

    return _resolve_parm_target(node, names)


def _values_match(
    expected: Any,
    actual: Any,
    tolerance: float = 1.0e-7,
    relative_tolerance: float = 1.0e-7,
) -> bool:
    if isinstance(expected, (list, tuple)) or isinstance(actual, (list, tuple)):
        if not isinstance(expected, (list, tuple)) or not isinstance(actual, (list, tuple)):
            return False
        return len(expected) == len(actual) and all(
            _values_match(left, right, tolerance, relative_tolerance) for left, right in zip(expected, actual)
        )
    # bool is an int subclass in Python, but a Houdini toggle readback is not
    # interchangeable with the numeric value 0/1.  Integer/menu controls are
    # likewise exact; only floating-point parms receive numerical tolerance.
    if type(expected) is bool or type(actual) is bool:
        return type(expected) is bool and type(actual) is bool and expected is actual
    if isinstance(expected, int) or isinstance(actual, int):
        return type(expected) is int and type(actual) is int and expected == actual
    if isinstance(expected, float) or isinstance(actual, float):
        if not isinstance(expected, (int, float)) or not isinstance(actual, (int, float)):
            return False
        return math.isclose(
            float(expected),
            float(actual),
            rel_tol=relative_tolerance,
            abs_tol=tolerance,
        )
    return expected == actual


def _read_parm_for_request(parm: _ResolvedParm, requested: Any) -> Any:
    """Read one parm using the representation appropriate to the request."""

    raw = parm.eval()
    if type(requested) is bool and type(raw) is int and raw in (0, 1):
        # HOM represents a real toggle as 0/1.  Normalize only in the explicit
        # bool write context; the comparator itself still rejects bool/int.
        return bool(raw)
    if isinstance(requested, str) and parm.kind == "parm":
        try:
            items = [str(item) for item in parm.menuItems()]
            if requested in items:
                return str(parm.evalAsString())
        except Exception:
            pass
    return raw


def _keyframe_identity(keyframe: Any) -> str:
    """Return HOM's complete, stable serialization for one keyframe."""

    try:
        return str(keyframe.asCode(brief=False, save_keys_in_frames=True))
    except Exception as exc:
        raise BridgeCommandError(
            "PARAMETER_SNAPSHOT_FAILED",
            "could not serialize a Houdini keyframe: {}".format(exc),
        ) from exc


def _component_driver_identity(component: Any) -> dict[str, Optional[str]]:
    """Identify expression/reference drivers without evaluating or following them."""

    expression: Optional[str] = None
    reference_path: Optional[str] = None
    try:
        expression = str(component.expression())
    except Exception:
        pass
    try:
        referenced = component.getReferencedParm()
        component_path = str(component.path())
        referenced_path = str(referenced.path()) if referenced is not None else component_path
        if referenced_path != component_path:
            reference_path = referenced_path
    except Exception:
        pass
    return {"expression": expression, "reference_path": reference_path}


def _snapshot_parm_state(parm: _ResolvedParm, *, capture_extrapolation: bool = False) -> dict[str, Any]:
    """Capture evaluated value plus the complete channel state for rollback.

    ``hou.Parm.set`` can add a key at the current frame or break a channel
    reference.  An evaluated-value snapshot therefore cannot prove restoration.
    Real HOM parameters are captured component-by-component using keyframe
    objects and their ``asCode`` identity.  The small value-only fallback exists
    solely for compatibility test doubles that do not implement HOM's channel
    API; production HOM failures remain fail-closed.
    """

    try:
        evaluated = parm.eval()
    except Exception as exc:
        raise BridgeCommandError(
            "PARAMETER_SNAPSHOT_FAILED",
            "could not snapshot {}: {}".format(parm.path(), exc),
        ) from exc
    components = parm._components()
    channel_api = bool(components) and all(
        callable(getattr(component, name, None))
        for component in components
        for name in ("keyframes", "deleteAllKeyframes", "setKeyframes")
    )
    if not channel_api:
        if capture_extrapolation:
            raise BridgeCommandError("PARAMETER_SNAPSHOT_FAILED", "activation channel API is unavailable: {}".format(parm.path()))
        return {"mode": "value_only_compat", "evaluated": evaluated}

    component_states: list[dict[str, Any]] = []
    for component in components:
        driver = _component_driver_identity(component)
        extrapolation_state = {}
        if capture_extrapolation:
            try:
                if not callable(getattr(component, "setKeyframeExtrapolation", None)):
                    raise ValueError("native extrapolation setter is unavailable")
                extrapolation_state["extrapolation"] = tuple(component.keyframeExtrapolation(before) for before in (True, False))
            except Exception as exc:
                raise BridgeCommandError("PARAMETER_SNAPSHOT_FAILED", "could not snapshot activation extrapolation: {}".format(component.path())) from exc
        try:
            keyframes = tuple(component.keyframes())
        except Exception as exc:
            raise BridgeCommandError(
                "PARAMETER_SNAPSHOT_FAILED",
                "could not read keyframes for {}: {}".format(component.path(), exc),
            ) from exc
        if keyframes:
            component_states.append(
                {
                    "component": component,
                    "mode": "keyframes",
                    "keyframes": keyframes,
                    "identity": tuple(_keyframe_identity(keyframe) for keyframe in keyframes),
                    **driver,
                    **extrapolation_state,
                }
            )
            continue
        try:
            raw_string = component.unexpandedString()
        except Exception:
            try:
                raw_value = component.eval()
            except Exception as exc:
                raise BridgeCommandError(
                    "PARAMETER_SNAPSHOT_FAILED",
                    "could not read {}: {}".format(component.path(), exc),
                ) from exc
            component_states.append(
                {
                    "component": component,
                    "mode": "value",
                    "value": raw_value,
                    **driver,
                    **extrapolation_state,
                }
            )
        else:
            component_states.append(
                {
                    "component": component,
                    "mode": "unexpanded_string",
                    "value": raw_string,
                    **driver,
                    **extrapolation_state,
                }
            )
    return {
        "mode": "hom_channels",
        "evaluated": evaluated,
        "components": component_states,
    }


def _verify_component_state(state: dict[str, Any]) -> bool:
    component = state["component"]
    mode = state["mode"]
    if _component_driver_identity(component) != {
        "expression": state.get("expression"),
        "reference_path": state.get("reference_path"),
    }:
        return False
    if "extrapolation" in state:
        try:
            if tuple(component.keyframeExtrapolation(before) for before in (True, False)) != state["extrapolation"]:
                return False
        except Exception:
            return False
    try:
        actual = tuple(_keyframe_identity(keyframe) for keyframe in component.keyframes())
    except Exception:
        return False
    if mode == "keyframes":
        return actual == tuple(state["identity"])
    if actual:
        return False
    if mode == "unexpanded_string":
        try:
            return str(component.unexpandedString()) == str(state["value"])
        except Exception:
            return False
    try:
        return _values_match(state["value"], component.eval())
    except Exception:
        return False


def _parm_snapshot_is_driven(snapshot: dict[str, Any]) -> bool:
    """Return True when a candidate would structurally replace a channel."""

    return snapshot.get("mode") == "hom_channels" and any(
        state.get("mode") == "keyframes"
        or bool(state.get("expression"))
        or bool(state.get("reference_path"))
        for state in snapshot.get("components") or []
    )


def _fx_output_pattern_readback(parm, pattern, frames):
    """Verify the approved frame token without weakening literal string writes."""
    import hou
    from pathlib import PurePosixPath, PureWindowsPath
    expected_types = {"picture": "Lop/karmarendersettings", "productName": "Lop/renderproduct",
                      "outputimage": "Driver/usdrender"}
    components = parm._components()
    template = parm.parmTemplate()
    if (parm.kind != "parm" or len(components) != 1
            or expected_types.get(parm.name()) != str(components[0].node().type().nameWithCategory())
            or str(template.type()).rsplit(".", 1)[-1] != "String"
            or type(template.numComponents()) is not int or template.numComponents() != 1
            or not isinstance(pattern, str) or pattern.count("$F4") != 1
            or "$" in pattern.replace("$F4", "") or "`" in pattern or "\x00" in pattern
            or not pattern.endswith("$F4.exr")
            or not (PurePosixPath(pattern).is_absolute() or PureWindowsPath(pattern).is_absolute())
            or not isinstance(frames, (tuple, list)) or not frames
            or any(type(frame) is not int or frame < 1 for frame in frames)):
        raise ValueError("output frame pattern contract is invalid")
    frame = hou.frame()
    if type(frame) not in (int, float) or not math.isfinite(frame) or frame not in frames:
        raise ValueError("output pattern observation frame is not frozen")
    raw = components[0].unexpandedString()
    evaluated = parm.eval()
    expanded = hou.expandString(pattern)
    if (raw != pattern or type(evaluated) is not str or type(expanded) is not str
            or evaluated != expanded or hou.frame() != frame):
        raise ValueError("output pattern raw or evaluated readback differs")
    return {"raw": raw, "evaluated": evaluated, "frame": frame}


def _fx_output_pattern_frames(write, node, configuration):
    expected = {("settings", "picture"): "Lop/karmarendersettings",
                ("render_product", "productName"): "Lop/renderproduct",
                ("render", "outputimage"): "Driver/usdrender"}
    node_type = expected.get((write["role"], write["parm"]))
    if node_type is None or configuration is None:
        return None
    if (str(node.type().nameWithCategory()) != node_type or write["native_type"] != "string"):
        raise BridgeCommandError("NATIVE_CONTROL_INTERFACE_REQUIRED", "output pattern target differs")
    return tuple(configuration["scene"]["frames"])


def _set_parm_verified(
    parm: _ResolvedParm,
    value: Any,
    *,
    restore: bool = False,
    output_pattern_frames=None,
) -> dict[str, Any]:
    """Set a parm, verify the evaluated value, and optionally restore it.

    The returned values are the actual HOM readbacks.  A driver, expression,
    menu coercion or incompatible tuple shape can otherwise make ``set`` return
    without applying the requested semantic value.
    """

    try:
        if parm.isDisabled() or parm.isLocked():
            raise BridgeCommandError("PARAMETER_LOCKED", "parameter is not editable: {}".format(parm.path()))
    except BridgeCommandError:
        raise
    except Exception as exc:
        raise BridgeCommandError("PARAMETER_STATE_UNAVAILABLE", "could not inspect {}: {}".format(parm.path(), exc)) from exc
    snapshot = _snapshot_parm_state(parm)
    if _parm_snapshot_is_driven(snapshot):
        # A normal candidate/rebuild write is a literal semantic patch.  HOM
        # may otherwise replace animation/expressions or follow a channel
        # reference into a parameter outside the Bridge-owned network.  Only
        # probes fail closed too: snapshotting the selected parm cannot prove
        # that HOM did not follow its reference and mutate an external target.
        raise BridgeCommandError(
            "PARAMETER_STATE_UNSUPPORTED",
            "refusing to replace an animated, expression-driven, or channel-referenced parameter: {}".format(
                parm.path()
            ),
            "Bake or explicitly remove the channel driver before applying a constant semantic candidate.",
        )
    before = snapshot["evaluated"]
    try:
        # Never follow a channel reference into an unrelated parameter.  The
        # selected Bridge-owned target is the only authorized mutation scope.
        parm.set(value, follow_references=False)
        pattern_readback = (_fx_output_pattern_readback(parm, value, output_pattern_frames)
                            if output_pattern_frames is not None else None)
        after = pattern_readback["evaluated"] if pattern_readback is not None else _read_parm_for_request(parm, value)
    except Exception as exc:
        try:
            _restore_parm_snapshot(parm, snapshot)
        except BridgeCommandError as restore_exc:
            raise restore_exc from exc
        raise BridgeCommandError("PARAMETER_SET_FAILED", "could not set {}: {}".format(parm.path(), exc)) from exc
    if output_pattern_frames is None and not _values_match(value, after):
        _restore_parm_snapshot(parm, snapshot)
        raise BridgeCommandError(
            "PARAMETER_READBACK_MISMATCH",
            "{} read back {} after requesting {}".format(parm.path(), _json_safe(after), _json_safe(value)),
        )
    restored = None
    if restore:
        restored = _restore_parm_snapshot(parm, snapshot)
    return {
        "parameter": parm.name(),
        "parameter_path": parm.path(),
        "target_kind": parm.kind,
        "component_count": parm.component_count,
        "before": _json_safe(before),
        "requested": _json_safe(value),
        "after": _json_safe(after),
        "readback_verified": True,
        "restored": _json_safe(restored) if restore else None,
        "restore_verified": bool(restore),
        **({"output_pattern_readback": pattern_readback} if pattern_readback is not None else {}),
    }


def _restore_parm_snapshot(parm: _ResolvedParm, snapshot: dict[str, Any]) -> Any:
    """Restore and verify values, expressions, references and animation keys."""

    if snapshot.get("mode") == "value_only_compat":
        try:
            parm.set(snapshot["evaluated"], follow_references=False)
            restored = parm.eval()
        except Exception as exc:
            raise BridgeCommandError(
                "PARAMETER_RESTORE_FAILED",
                "could not restore {}: {}".format(parm.path(), exc),
            ) from exc
        if not _values_match(snapshot["evaluated"], restored):
            raise BridgeCommandError(
                "PARAMETER_RESTORE_MISMATCH",
                "{} did not restore to its snapshot".format(parm.path()),
            )
        return restored

    try:
        for state in snapshot.get("components") or []:
            component = state["component"]
            component.deleteAllKeyframes()
            if state["mode"] == "keyframes":
                component.setKeyframes(state["keyframes"])
            else:
                component.set(state["value"], follow_parm_reference=False)
            if "extrapolation" in state:
                for before, value in zip((True, False), state["extrapolation"]):
                    component.setKeyframeExtrapolation(before, value)
        restored = parm.eval()
    except Exception as exc:
        raise BridgeCommandError(
            "PARAMETER_RESTORE_FAILED",
            "could not restore {}: {}".format(parm.path(), exc),
        ) from exc
    channel_restored = all(
        _verify_component_state(state) for state in snapshot.get("components") or []
    )
    if not channel_restored or not _values_match(snapshot["evaluated"], restored):
        raise BridgeCommandError(
            "PARAMETER_RESTORE_MISMATCH",
            "{} did not restore its complete channel state".format(parm.path()),
        )
    return restored


def _set_first_parm(node: Any, names: list[str], value: Any) -> bool:
    parm = _resolve_parm_target(node, names)
    if parm is None:
        return False
    _set_parm_verified(parm, value)
    return True


def _set_resolution(node, resolution: Any) -> dict[str, int]:
    """Set the first compatible Karma resolution knobs and report the result."""
    values = list(resolution or [1280, 720])
    width, height = int(values[0]), int(values[1])
    # Karma Render Settings owns the mode/override toggle on some builds, while
    # the USD Render ROP exposes res_user1/res_user2 after override_res=1.
    _set_first_parm(node, ["res_mode"], "manual")
    override = _first_parm(node, ["override_res", "override_camerares", "override_resolution", "res_override"])
    if override is not None:
        # Houdini 21/22 use a menu token (usually ``specific``) for the
        # per-ROP resolution override.  Passing integer 1 to that menu is
        # silently ignored, which otherwise makes a requested 640x360 render
        # fall back to the camera's default resolution.
        try:
            choices = [str(item) for item in override.menuItems()]
        except Exception:
            choices = []
        selected = next((item for item in choices if item.lower() in {"specific", "user", "override"}), None)
        if selected is None and "1" in choices:
            selected = "1"
        if selected is not None:
            _set_parm_verified(override, selected)
    width_set = _set_first_parm(node, ["resolutionx", "resx", "xres", "override_resx", "res_user1"], width)
    height_set = _set_first_parm(node, ["resolutiony", "resy", "yres", "override_resy", "res_user2"], height)
    return {"width": width, "height": height, "width_set": bool(width_set), "height_set": bool(height_set)}


def _choose_karma_engine(node, requested: str) -> str:
    """Choose an advertised Karma engine without assuming menu token values."""
    parm = _first_parm(node, ["engine", "rendertype", "renderer"])
    if parm is None:
        return "karma_cpu"
    try:
        choices = list(parm.menuItems())
    except Exception:
        choices = []
    preferred = "xpu" if requested == "karma_xpu" else "cpu"
    if requested == "auto":
        preferred = "xpu"
    selected = next((item for item in choices if preferred in item.lower()), None)
    if selected is None:
        selected = next((item for item in choices if "cpu" in item.lower()), None)
    if selected is None:
        return "karma_cpu"
    _set_parm_verified(parm, selected)
    return "karma_xpu" if "xpu" in selected.lower() else "karma_cpu"


def _task_name(task_id: str, prefix: str) -> str:
    """Stable storage name derived from the FULL task id.

    The previous rule kept a hex-character subset of the id, which mapped
    distinct ids (``task-01`` vs ``task-x01`` -> ``a01``) onto the same store
    and cross-wired tasks.  A digest of the full id keeps every distinct task
    on its own store; the raw id is also recorded in the store and verified
    on load.
    """
    text = str(task_id)
    if not text.strip():
        raise ValueError("task_id is required")
    return "{}_{}".format(prefix, hashlib.sha256(text.encode("utf-8")).hexdigest()[:16])


def _legacy_task_name(task_id: str, prefix: str) -> str:
    """Pre-hardening name (hex subset of the id), kept ONLY to detect old stores."""
    safe = "".join(character for character in str(task_id).lower() if character in "0123456789abcdef")[:16]
    if not safe:
        return ""
    return f"{prefix}_{safe}"



_TASK_ROOT_PREFIXES = ("HOUDINI_AGENT_WORKING_", "HOUDINI_AGENT_STAGE_", "BRIDGE_FX_", "BRIDGE_GRAPH_")
_MUTATION_COMMANDS = frozenset({
    "node.create", "node.create_batch", "node.connect", "node.set_parm",
    "node.set_parms", "node.delete", "node.bypass", "node.unlock_contents",
    "node.press_button", "node.cook", "node.layout",
})
_MUTATION_TARGET_KEYS = ("parent", "path", "destination", "source", "node")
_GRAPH_ROOT_NAME = re.compile(r"^BRIDGE_GRAPH_[0-9a-f]{64}$")
_ROOT_LEASE_TTL_SECONDS = 600.0
_ROOT_LEASE_RENEW_INTERVAL = 10.0
_LEASE_RENEW_MEMORY: dict[str, float] = {}


_CONTROL_CHANNEL_ENV = "HOUDINI_BRIDGE_CONTROL_CHANNEL"
_TRUSTED_CONTROL_COMMANDS = frozenset({"control.discover_orphans", "control.resolve"})


def _production_control_commands() -> "frozenset[str]":
    """Control-plane commands are reachable only with an explicit opt-in."""
    if str(os.environ.get(_CONTROL_CHANNEL_ENV) or "").strip().lower() in {"1", "true", "yes", "on"}:
        return _TRUSTED_CONTROL_COMMANDS
    return frozenset()


def _verify_control_authorization(action: str, payload: dict[str, Any], authorization: Any) -> str:
    """Verify a control-plane authorization (HMAC over the canonical payload).

    A bare non-empty ``verified_by`` string is NOT accepted evidence: the
    control side must sign {action, **payload} with the installation approval
    secret, exactly like cache approvals.
    """
    if not isinstance(authorization, dict):
        raise BridgeCommandError("INVALID_ARGUMENT", "control authorization object required")
    if not str(authorization.get("verified_by") or "").strip():
        raise BridgeCommandError("INVALID_ARGUMENT",
                                 "verified_by must name the control operator and the verified evidence")
    signature = str(authorization.get("signature") or "")
    if not signature:
        raise BridgeCommandError("APPROVAL_INVALID", "control authorization requires a verifiable signature")
    secret = _approval_secret_value()
    body = json.dumps({"action": action, **payload}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    expected = hmac.new(secret.encode("utf-8"), body.encode("utf-8"), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise BridgeCommandError("APPROVAL_INVALID", "control authorization signature is invalid")
    return str(authorization["verified_by"])


def _fx_check_disk_budget(directory: "Path | str", estimated_bytes: int = 0) -> dict[str, Any]:
    """Configurable disk budget for task-owned directories (R08).

    Enabled only when ``HOUDINI_BRIDGE_DISK_BUDGET_MB`` is set.  Refuses a
    heavy operation whose current usage plus the estimate would exceed the
    budget; evidence (usage/limit) is reported and NOTHING is ever deleted —
    user caches are never touched.  An uninterruptible host cannot reclaim
    space by itself; the control plane decides.
    """
    configured = str(os.environ.get("HOUDINI_BRIDGE_DISK_BUDGET_MB") or "").strip()
    if not configured:
        return {"enforced": False}
    try:
        limit_bytes = float(configured) * 1024.0 * 1024.0
    except ValueError:
        raise BridgeCommandError("INVALID_ARGUMENT", "HOUDINI_BRIDGE_DISK_BUDGET_MB is not a number")
    directory = Path(directory)
    usage = 0
    if directory.is_dir():
        for item in directory.rglob("*"):
            try:
                if item.is_file() and not item.is_symlink():
                    usage += item.stat().st_size
            except OSError:
                continue
    if usage + max(0, int(estimated_bytes)) > limit_bytes:
        raise BridgeCommandError(
            "DISK_BUDGET_EXCEEDED",
            "task directory {} holds {} bytes; budget is {} bytes".format(directory, usage, int(limit_bytes)),
            "Evidence preserved; nothing deleted. Free space or raise the budget before the next heavy operation.")
    return {"enforced": True, "usage_bytes": usage, "limit_bytes": int(limit_bytes)}


def _task_state_root() -> Path:
    override = os.environ.get('HOUDINI_BRIDGE_TASK_STATE_DIR')
    if not override:
        return _state_dir().parent
    root = Path(override).expanduser()
    if not root.is_absolute():
        raise BridgeCommandError('TASK_STATE_ROOT_INVALID', 'task facts require an absolute controlled state directory')
    return root.resolve()


def _root_leases_dir() -> Path:
    from dcc_task_runtime.platform_support import ensure_private_directory
    directory = _state_dir().parent / "scene_root_leases"
    ensure_private_directory(directory)
    return directory


def _root_lease_path(root: str) -> Path:
    # The root is an absolute scene path; flatten it or pathlib treats the
    # right operand as absolute and REPLACES the directory.
    return _root_leases_dir() / "{}.json".format(str(root).replace("/", "_"))


def _host_identity() -> dict[str, Any]:
    identity = dict(globals().get("_TASK_HOST_IDENTITY") or {})
    # A task-owned host publishes its launch/session identity in the ready
    # receipt.  The scene callback owns only the mutable epoch; replacing the
    # launch fields with the module-import identity would make every formal
    # scene transition appear to come from a different host.
    if not identity:
        identity.update({
            "session_id": str(getattr(_BRIDGE_SCENE_STATE, "session_id", "") or ""),
            "process_generation": str(getattr(_BRIDGE_SCENE_STATE, "process_generation", "") or ""),
        })
    identity["scene_epoch"] = int(getattr(_BRIDGE_SCENE_STATE, "scene_epoch", 0) or 0)
    return identity


def _root_lease_lock(root: str):
    """Cross-process lock domain for lease renewal/revoke/takeover (C1)."""
    from dcc_task_runtime.platform_support import lock_file, ensure_private_directory, open_private_file
    directory = _root_leases_dir() / "locks"
    ensure_private_directory(directory)
    name = str(root).replace("/", "_") + ".lock"
    descriptor = open_private_file(directory / name, os.O_CREAT | os.O_RDWR)
    handle = os.fdopen(descriptor, "r+b")
    try:
        lock_file(handle.fileno())
    except OSError:
        handle.close()
        raise
    return handle


@contextmanager
def _root_lease_locked(root: str):
    handle = _root_lease_lock(root)
    try:
        yield
    finally:
        try:
            from dcc_task_runtime.platform_support import unlock_file
            unlock_file(handle.fileno())
        finally:
            handle.close()


@contextmanager
def _root_lease_fence(root: str, *, task_id: "str | None" = None,
                      scope: "str | None" = None):
    """Hold the lease lock across ownership check and the side effect."""
    with _root_lease_locked(root):
        lease = _root_lease_check(root, task_id=task_id, scope=scope, renew=False)
        yield lease


def _mutation_target_paths(command: str, params: dict[str, Any]) -> list[str]:
    """Return every scene path touched by one public mutation command.

    The old dispatch guard only checked these paths before entering the
    command branch.  Keeping the inventory in one place lets the actual
    side-effect block acquire all relevant root locks in a stable order, so a
    takeover cannot land between the check and Houdini's mutating call.
    """
    keys: tuple[str, ...]
    if command in {"node.create", "node.create_batch"}:
        keys = ("parent",)
    elif command == "node.connect":
        keys = ("destination", "source")
    else:
        keys = ("path",)
    return [str(params[key]) for key in keys if isinstance(params.get(key), str) and params.get(key)]


def _preflight_creation_inputs(command: str, params: dict[str, Any]) -> None:
    if command == "node.create" and type(params.get("exact_type_name", False)) is not bool:
        raise BridgeCommandError("INVALID_ARGUMENT", "exact_type_name must be a boolean")
    parent = _node(str(params.get("parent")))
    root = _root_for_path(parent.path())
    scope = _path_scope(parent.path())
    if root is None or scope is None:
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "creation requires a leased task root")
    _root_lease_check(root, task_id=str(params.get("task_id") or "") or None, scope=scope, renew=False)
    specs = [params]
    if command == "node.create_batch":
        specs = params.get("nodes") or []
    if not isinstance(specs, list) or any(not isinstance(spec, dict) for spec in specs):
        raise BridgeCommandError("INVALID_ARGUMENT", "creation specs must be a list of objects")
    keys = []
    if command == "node.create_batch":
        keys = [str(spec.get("id") or spec.get("name") or "") for spec in specs]
        if any(not key for key in keys) or len(set(keys)) != len(keys):
            raise BridgeCommandError("INVALID_ARGUMENT", "batch nodes require unique nonempty IDs or names")
    for spec in specs:
        inputs = spec.get("inputs") or []
        if not isinstance(inputs, list):
            raise BridgeCommandError("INVALID_ARGUMENT", "node inputs must be a list of paths or batch IDs")
        for source in inputs:
            if not source:
                continue
            if not isinstance(source, str):
                raise BridgeCommandError("INVALID_ARGUMENT", "node input must be a path or batch ID")
            if source in keys:
                continue
            if (not source.startswith("/") or source != posixpath.normpath(source)
                    or _root_for_path(source) != root):
                raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "creation input must belong to the parent leased root")
            node = _node(source)
            if _root_for_path(node.path()) != root:
                raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "resolved creation input is outside the parent leased root")


@contextmanager
def _mutation_lease_fence(command: str, params: dict[str, Any]):
    """Fence a complete public node mutation, including multi-root calls."""
    requested: dict[tuple[str, str], None] = {}
    for path in _mutation_target_paths(command, params):
        root = _root_for_path(path)
        scope = _path_scope(path)
        if root is not None and scope is not None:
            requested[(root, scope)] = None
    with ExitStack() as stack:
        for root, scope in sorted(requested):
            stack.enter_context(_root_lease_fence(
                root, task_id=str(params.get("task_id") or "") or None, scope=scope))
        yield


@contextmanager
def _task_scene_lease_fence(task_id: str, params: dict[str, Any] | None = None, *, required_root: str | None = None):
    """Fence global scene-save/reopen-adjacent writes through task leases."""
    params = params or {}
    candidates = {
        str(value) for value in (
            params.get("execution_root"), params.get("root_path"),
            _task_paths(task_id)[0], _fx_task_paths(task_id)[0],
        ) if isinstance(value, str) and value.startswith("/obj/")
    }
    # A formal graph trial binds the actual generated BRIDGE_GRAPH root into
    # the production add-on manifest.  Scene save must fence that root too;
    # deriving it from persisted host state keeps the save route independent
    # from model-supplied paths.
    try:
        _manifest_root, persisted_manifest = _fx_manifest(str(task_id), required=False)
        persisted_root = persisted_manifest.get("execution_root") if isinstance(persisted_manifest, dict) else None
        if isinstance(persisted_root, str) and persisted_root.startswith("/obj/"):
            candidates.add(persisted_root)
    except Exception:
        pass
    leased = {}
    for root in sorted(candidates):
        lease = _root_lease_read(root)
        if isinstance(lease, dict) and lease.get("status") == "ACTIVE" and str(lease.get("task_id") or "") == str(task_id):
            leased[root] = str(lease.get("scope") or _path_scope(root) or "sop")
    if required_root is not None:
        if not isinstance(required_root, str) or _root_for_path(required_root) != required_root or _path_scope(required_root) is None:
            raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "required scene fence root is invalid")
        # The actual execution root must be locked even when a concurrent
        # takeover/revocation makes it ineligible for the optional-root scan.
        # Keying by root also prevents acquiring the same flock twice.
        leased[required_root] = _path_scope(required_root)
    if not leased:
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "task {} has no active scene root lease".format(task_id))
    with ExitStack() as stack:
        for root, scope in sorted(leased.items()):
            stack.enter_context(_root_lease_fence(root, task_id=task_id, scope=scope))
        yield


def _root_lease_write(root: str, lease: dict[str, Any], *, expect_version: "int | None" = None) -> dict[str, Any]:
    """CAS lease write: refuses to overwrite a concurrent version change.

    Renewal passes the version it READ; takeover passes the version it read
    plus one.  os.replace alone is NOT a CAS — the per-root lock domain plus
    the expected-version check make a stale writer lose instead of undoing a
    completed takeover.
    """
    path = _root_lease_path(root)
    if path.is_symlink():
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "lease record must not be a symlink: {}".format(path))
    with _root_lease_locked(root):
        current = None
        if path.is_file():
            try:
                current = json.loads(path.read_text(encoding="utf-8"))
            except (ValueError, OSError):
                current = None
        if expect_version is not None:
            current_version = int((current or {}).get("version") or 0) if isinstance(current, dict) else 0
            if current_version != int(expect_version):
                raise BridgeCommandError(
                    "LEASE_CAS_CONFLICT",
                    "lease for {} moved from version {} to {} concurrently".format(root, expect_version, current_version),
                    "Re-read the lease; a stale writer must not undo a completed takeover.")
        lease["version"] = int(lease.get("version") or 0) + 1
        from dcc_task_runtime.platform_support import atomic_write
        atomic_write(path, json.dumps(lease, ensure_ascii=False, indent=1, sort_keys=True).encode("utf-8"),
                     owned_root=path.parent)
    _LEASE_RENEW_MEMORY.pop(root, None)
    return lease


def _root_lease_read(root: str) -> "dict[str, Any] | None":
    """Read a lease; corruption fails closed (bytes archived, never empty)."""
    path = _root_lease_path(root)
    if not path.is_file():
        return None
    try:
        lease = json.loads(path.read_text(encoding="utf-8"))
    except (ValueError, OSError) as exc:
        archived = path.with_name(path.name + ".corrupt-" + uuid4().hex[:8])
        try:
            os.replace(path, archived)
        except OSError:
            archived = path
        raise BridgeCommandError(
            "CORRUPT_LEASE",
            "root lease for {} is unreadable; bytes preserved at {}".format(root, archived),
            "Ownership cannot be proven: fail closed. Reconcile the lease record before any mutation.") from exc
    if not isinstance(lease, dict) or not lease.get("root"):
        raise BridgeCommandError("CORRUPT_LEASE", "root lease for {} is malformed".format(root),
                                 "Ownership cannot be proven: fail closed.")
    return lease


def _root_lease_issue(root: str, task_id: str, scope: str) -> dict[str, Any]:
    identity = _host_identity()
    now = datetime.now(timezone.utc)
    lease = {
        "root": str(root), "task_id": str(task_id), "scope": str(scope),
        "status": "ACTIVE", "owner_session_id": identity["session_id"],
        "owner_generation": identity["process_generation"],
        "scene_epoch": identity["scene_epoch"],
        "created_at": now.isoformat(), "renewed_at": now.isoformat(),
        "expires_at": (now + timedelta(seconds=_ROOT_LEASE_TTL_SECONDS)).isoformat(),
        "version": 1,
    }
    return _root_lease_write(root, lease)


def _root_lease_check(root: str, *, task_id: "str | None" = None, scope: "str | None" = None,
                      renew: bool = True) -> dict[str, Any]:
    """Fail-closed ownership re-check before a side effect.

    Refuses: missing lease, revoked/expired lease, a host generation that no
    longer owns the root (takeover), a claimed task that differs from the
    lease task, and scope/context mismatch.  A corrupt record fails closed.
    """
    lease = _root_lease_read(root)
    if lease is None:
        raise BridgeCommandError(
            "SCENE_OWNERSHIP_REQUIRED",
            "node {} has no persistent root lease".format(root),
            "Roots are owned through scene.create_task_root / the task build chain; no prefix string grants ownership.")
    if lease.get("status") != "ACTIVE":
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "root {} lease is {}".format(root, lease.get("status")),
                                 "The lease was revoked; re-establish ownership through the control path.")
    identity = _host_identity()
    if str(lease.get("owner_generation") or "") != identity["process_generation"]:
        raise BridgeCommandError(
            "GENERATION_TAKEOVER",
            "root {} is owned by generation {}, current host is {}".format(root, lease.get("owner_generation"), identity["process_generation"]),
            "Another host took over the root; this executor must stop issuing side effects.")
    if str(lease.get("owner_session_id") or "") != identity["session_id"]:
        raise BridgeCommandError("GENERATION_TAKEOVER", "root {} is owned by another host session".format(root),
                                 "The lease belongs to a different host session.")
    if int(lease.get("scene_epoch") or 0) != int(identity.get("scene_epoch") or 0):
        raise BridgeCommandError(
            "SCENE_EPOCH_CHANGED",
            "root {} belongs to scene epoch {}, current scene epoch is {}".format(
                root, lease.get("scene_epoch"), identity.get("scene_epoch")),
            "A hipFile load/clear/merge changed the live scene; reopen and rebind the task before mutating it.")
    if task_id is not None and str(lease.get("task_id") or "") != str(task_id):
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED",
                                 "root {} belongs to task {}, not {}".format(root, lease.get("task_id"), task_id),
                                 "Cross-task mutation refused.")
    if scope is not None and str(lease.get("scope") or "") != str(scope):
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED",
                                 "root {} is leased for scope {}, not {}".format(root, lease.get("scope"), scope),
                                 "The /obj and /stage contexts use separate lease scopes.")
    try:
        expires = datetime.fromisoformat(str(lease.get("expires_at")))
        if datetime.now(timezone.utc) >= expires:
            raise BridgeCommandError("LEASE_EXPIRED", "root {} lease expired at {}".format(root, lease.get("expires_at")),
                                     "Renew the lease through a task-scoped operation before mutating.")
    except ValueError as exc:
        if "LEASE_EXPIRED" in str(exc):
            raise
        raise BridgeCommandError("CORRUPT_LEASE", "root {} lease has an invalid expiry".format(root)) from exc
    # sliding renewal, throttled in memory to avoid a disk write per mutation.
    # CAS: renew against the OWNER+VERSION that was just verified, so a stale
    # renewal can never undo a concurrent takeover (C1).
    now = time.time()
    if renew and now - float(_LEASE_RENEW_MEMORY.get(root, 0.0)) >= _ROOT_LEASE_RENEW_INTERVAL:
        _LEASE_RENEW_MEMORY[root] = now
        renewal = dict(lease)
        renewal["renewed_at"] = datetime.now(timezone.utc).isoformat()
        renewal["expires_at"] = (datetime.now(timezone.utc) + timedelta(seconds=_ROOT_LEASE_TTL_SECONDS)).isoformat()
        try:
            lease = _root_lease_write(root, renewal, expect_version=int(lease.get("version") or 0))
        except BridgeCommandError as exc:
            if exc.code == "LEASE_CAS_CONFLICT":
                raise BridgeCommandError(
                    "GENERATION_TAKEOVER",
                    "root {} changed ownership during renewal".format(root),
                    "This executor must stop issuing side effects.") from exc
            raise
    return lease


def _root_for_path(path: str) -> "str | None":
    if not path.startswith("/obj/") and not path.startswith("/stage/"):
        return None
    parts = path.split("/")
    return "/".join(parts[:3]) if len(parts) >= 3 else None


def _path_scope(path: str) -> "str | None":
    if path.startswith("/obj/"):
        return "sop"
    if path.startswith("/stage/"):
        return "stage"
    return None


def _guard_bridge_mutation_targets(params: dict[str, Any]) -> None:
    """Persistent-lease ownership fence for the dispatch mutation surface.

    Every mutation target must live under a root with a valid ACTIVE lease
    bound to this host session and generation (and, when the caller declares
    a task, to that exact task).  Creation under /obj or /stage directly is
    refused: task roots exist only through scene.create_task_root or the
    internal task build chain, which record ownership atomically.  A corrupt,
    revoked or expired lease fails closed.  This is a cooperative mechanism
    of the bridge surface; WorkBuddy keeps full access outside it and no
    system-level isolation is claimed.
    """
    import hou

    requested = [str(params[key]) for key in _MUTATION_TARGET_KEYS if params.get(key)]
    if not requested:
        return
    claimed_task = str(params.get("task_id") or "") or None
    for path in requested:
        node = hou.node(path)
        if node is None:
            continue  # unknown path: the command itself fails with its own error
        if path in ("/obj", "/stage", "/",):
            raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED",
                                     "refusing to mutate the scene root {} directly".format(path),
                                     "Task roots are created through scene.create_task_root or the task build chain.")
        root = _root_for_path(path)
        scope = _path_scope(path)
        if root is None or scope is None:
            raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED",
                                     "node {} is outside a leaseable task context".format(path),
                                     "Bridge mutations are limited to leased /obj and /stage task roots.")
        _root_lease_check(root, task_id=claimed_task, scope=scope)


def _scene_create_task_root(params: dict[str, Any]) -> dict[str, Any]:
    """Dedicated, atomically-accounted task root creation (persistent lease).

    Refuses any name/parent/type outside the exact BRIDGE_GRAPH contract,
    reuses a root only when the persistent lease proves the SAME task, and
    rejects a same-name root owned by another task or an ownerless leftover.
    The lease record is written in the same step as creation.
    """
    import hou

    task_id = str(params.get("task_id") or "").strip()
    root_name = str(params.get("root_name") or "").strip()
    parent_path = str(params.get("parent") or "/obj")
    node_type = str(params.get("type") or "geo")
    if not task_id:
        raise BridgeCommandError("INVALID_ARGUMENT", "task_id is required")
    if not _GRAPH_ROOT_NAME.fullmatch(root_name):
        raise BridgeCommandError("INVALID_ARGUMENT",
                                 "root_name must be BRIDGE_GRAPH_<64 lowercase hex>, got {!r}".format(root_name),
                                 "The root digest is derived from task_id and graph_hash by the graph executor.")
    layouts = {"geo":"sop_geo/1","subnet":"object_subnet/1"}
    if parent_path != "/obj" or node_type not in layouts or params.get("root_layout", "sop_geo/1") != layouts.get(node_type):
        raise BridgeCommandError("INVALID_ARGUMENT", "task root requires a registered /obj geometry or Object subnet layout")
    root = "/obj/" + root_name
    created = None
    with _root_lease_locked(root):
        existing_lease = _root_lease_read(root)
        existing_node = hou.node(root)
        if existing_lease is not None and existing_lease.get("status") == "ACTIVE":
            if str(existing_lease.get("task_id") or "") != task_id:
                raise BridgeCommandError("SCENE_CONFLICT",
                                         "root {} already belongs to task {}".format(root, existing_lease.get("task_id")),
                                         "A same-name root owned by another task is never reused or overwritten.")
            if existing_node is None:
                raise BridgeCommandError("SCENE_STATE_MISSING",
                                         "root {} has an active lease but the node is gone".format(root),
                                         "Reconcile the scene before reusing the root.")
            if existing_node.type().name() != node_type:
                raise BridgeCommandError("SCENE_CONFLICT","existing task root has a different native context")
            _root_lease_check(root, task_id=task_id, scope="sop", renew=False)
            return {"path": root, "type": node_type, "reused": True, "lease": existing_lease}
        if existing_node is not None:
            raise BridgeCommandError("SCENE_CONFLICT",
                                     "node {} exists without an active lease for this task".format(root),
                                     "An ownerless or foreign same-name root is never adopted.")
        parent = hou.node(parent_path)
        if parent is None:
            raise BridgeCommandError("SCENE_STATE_MISSING", "/obj network is missing")
        created = parent.createNode(node_type, root_name)
    # Lease creation has its own locked CAS write.  The newly-created node is
    # already protected by the root lock and cannot be claimed by a second
    # task in the interval.
    lease = _root_lease_issue(root, task_id, scope="sop")
    return {"path": str(created.path()), "type": node_type, "reused": False, "lease": lease}


def _task_paths(task_id: str) -> tuple[str, str]:
    return f"/obj/{_task_name(task_id, 'HOUDINI_AGENT_WORKING')}", f"/stage/{_task_name(task_id, 'HOUDINI_AGENT_STAGE')}"


def _task_output_dir(params: dict[str, Any]) -> Path:
    import hou

    configured = str((params.get("render") or {}).get("output_dir") or "").strip()
    if configured:
        directory = Path(hou.expandString(configured)).expanduser()
    else:
        hip_path = Path(hou.hipFile.path())
        base = hip_path.parent if hip_path.suffix else Path(hou.expandString("$HIP"))
        directory = base / "render" / _task_name(str(params.get("task_id")), "task")
    directory.mkdir(parents=True, exist_ok=True)
    return directory


def _artifact(path: Path) -> dict[str, Any]:
    stat = path.stat()
    return {"path": str(path), "bytes": stat.st_size, "modified_ns": stat.st_mtime_ns}


def _model_root(task_id: str):
    import hou

    path, _stage_path = _task_paths(task_id)
    node = hou.node(path)
    if node is None:
        raise ValueError("model root does not exist; run agent.model.build first")
    return node


def _mark_hip_dirty_without_persistent_scene_change(root: Any) -> None:
    """Restore Houdini's dirty bit after save-copy without changing identity."""

    marker = "bridge_save_copy_dirty_{}".format(uuid4().hex)
    root.setUserData(marker, "1")
    root.destroyUserData(marker)


def _save_hip_copy_preserving_current(path: Path, root: Any) -> None:
    """Write an exact HIP copy while preserving current path and dirty state."""

    import hou

    original_path = str(hou.hipFile.path() or "")
    original_dirty = hou.hipFile.hasUnsavedChanges()
    output = path.expanduser().absolute()
    current = Path(output.anchor)
    for component in output.parts[1:-1]:
        current = current / component
        if current.is_symlink():
            raise BridgeCommandError(
                "OUTPUT_NOT_WRITABLE", "save_copy output parent traverses a symlink"
            )
    if output.is_symlink():
        raise BridgeCommandError(
            "OUTPUT_NOT_WRITABLE", "save_copy output must not be a symlink"
        )
    if not output.parent.is_dir():
        raise BridgeCommandError(
            "OUTPUT_NOT_WRITABLE", "save_copy output directory does not exist"
        )
    parent_info = output.parent.stat()
    if os.name != "nt" and parent_info.st_uid != os.getuid():
        raise BridgeCommandError(
            "OUTPUT_NOT_WRITABLE", "save_copy output directory is not owned by this user"
        )
    original_file = Path(original_path).expanduser().resolve(strict=False) if original_path else None
    if original_file is not None and output == original_file:
        raise BridgeCommandError(
            "OUTPUT_NOT_WRITABLE", "save_copy output must differ from the current HIP"
        )
    temporary = output.with_name(".{}.{}.tmp".format(output.name, uuid4().hex))
    if original_dirty is False and original_file is not None and original_file.is_file():
        try:
            with original_file.open("rb") as source, temporary.open("xb") as target:
                os.chmod(temporary, 0o600)
                for chunk in iter(lambda: source.read(1024 * 1024), b""):
                    target.write(chunk)
            info = temporary.lstat()
            if temporary.is_symlink() or not stat.S_ISREG(info.st_mode):
                raise BridgeCommandError(
                    "OUTPUT_NOT_WRITABLE", "save_copy temporary output is not a regular file"
                )
            os.replace(str(temporary), str(output))
            return
        finally:
            temporary.unlink(missing_ok=True)
    try:
        if temporary.exists() or temporary.is_symlink():
            raise BridgeCommandError(
                "OUTPUT_NOT_WRITABLE", "save_copy temporary output already exists"
            )
        hou.hipFile.save(str(temporary), save_to_recent_files=False)
        hou.hipFile.setName(original_path)
        if not hou.hipFile.hasUnsavedChanges():
            _mark_hip_dirty_without_persistent_scene_change(root)
        if str(hou.hipFile.path() or "") != original_path or hou.hipFile.hasUnsavedChanges() is not True:
            raise BridgeCommandError(
                "SCENE_STATE_DRIFT", "save_copy could not restore the current dirty HIP state"
            )
        temporary_info = temporary.lstat()
        if temporary.is_symlink() or not stat.S_ISREG(temporary_info.st_mode):
            raise BridgeCommandError(
                "OUTPUT_NOT_WRITABLE", "save_copy temporary output is not a regular file"
            )
        os.replace(str(temporary), str(output))
    except Exception:
        try:
            if str(hou.hipFile.path() or "") != original_path:
                hou.hipFile.setName(original_path)
            if original_dirty is True and not hou.hipFile.hasUnsavedChanges():
                _mark_hip_dirty_without_persistent_scene_change(root)
        except Exception as restore_exc:
            raise BridgeCommandError(
                "SCENE_STATE_DRIFT",
                "save_copy failed and the current HIP state could not be restored: {}".format(
                    restore_exc
                ),
            ) from restore_exc
        raise
    finally:
        temporary.unlink(missing_ok=True)


def _model_operation_frame_range(params, stored=None):
    """A model operation may address a short segment of a longer TaskSpec."""
    frame_range = (params.get("render") or {}).get("frame_range")
    if frame_range is None:
        frame_range = dict(zip(("start", "end", "step"), stored or (1,1,1)))
    if not isinstance(frame_range, dict):
        raise BridgeCommandError("INVALID_ARGUMENT", "model operation frame_range must be explicit")
    start, end, step = (frame_range.get("start",1), frame_range.get("end",frame_range.get("start",1)), frame_range.get("step",1))
    if (any(type(value) is not int for value in (start,end,step)) or step <= 0 or end < start):
        raise BridgeCommandError("INVALID_ARGUMENT", "invalid model operation frame range")
    requested = (params.get("step_params") or {}).get("frame")
    if requested is not None:
        if type(requested) is not int or not start <= requested <= end or (requested-start) % step:
            raise BridgeCommandError("INVALID_ARGUMENT", "step frame differs from the operation range")
        start = end = requested
    if (end-start)//step + 1 > 12:
        raise BridgeCommandError("INVALID_ARGUMENT", "model operations require at most 12 explicit frames")
    return start,end,step


def _model_action(command: str, params: dict[str, Any]) -> dict[str, Any]:
    import hou

    task_id = str(params.get("task_id") or "")
    model_path, stage_path = _task_paths(task_id)
    if command == "agent.model.probe":
        return {"gates": [{"name": "houdini_running", "passed": True}], "capabilities": dispatch("capabilities.get", {})}
    if command == "agent.model.build":
        obj = hou.node("/obj")
        if obj is None:
            raise RuntimeError("/obj network is missing")
        root = hou.node(model_path)
        if root is None:
            with _undo("Houdini Agent build editable model"):
                root = obj.createNode("geo", _task_name(task_id, "HOUDINI_AGENT_WORKING"))
                root.setUserData("agent_task_id", task_id)
                intent = str(params.get("intent") or "").lower()
                if any(word in intent for word in ("bottle", "vase", "杯", "瓶")):
                    source = root.createNode("tube", "profile")
                    _set_first_parm(source, ["rad1", "radius"], 0.35)
                    _set_first_parm(source, ["rad2"], 0.28)
                    _set_first_parm(source, ["height", "height1"], 1.5)
                elif any(word in intent for word in ("sphere", "ball", "球")):
                    source = root.createNode("sphere", "source")
                else:
                    source = root.createNode("box", "source")
                    _set_first_parm(source, ["sizex"], 1.2)
                    _set_first_parm(source, ["sizey"], 1.2)
                    _set_first_parm(source, ["sizez"], 1.2)
                current = source
                try:
                    bevel = root.createNode("polybevel", "edge_softening")
                    bevel.setInput(0, current)
                    _set_first_parm(bevel, ["offset", "dist"], 0.03)
                    current = bevel
                except hou.OperationFailed:
                    pass
                output = root.createNode("null", "OUT_MODEL")
                output.setInput(0, current)
                output.setDisplayFlag(True)
                output.setRenderFlag(True)
                root.setUserData("agent_out_model", output.path())
                root.layoutChildren()
        output_path = root.userData("agent_out_model")
        return {"gates": [{"name": "editable_sop_model", "passed": bool(output_path)}], "model_root": root.path(), "out_model": output_path}
    if command == "agent.model.validate_geometry":
        root = _model_root(task_id)
        output = hou.node(root.userData("agent_out_model"))
        if output is None:
            raise RuntimeError("OUT_MODEL missing")
        output.cook(force=True)
        geometry = output.geometry()
        points = len(geometry.points())
        primitives = len(geometry.prims())
        bounds = geometry.boundingBox().sizevec()
        finite = all(abs(component) != float("inf") and component == component for component in bounds)
        passed = points > 0 and primitives > 0 and any(abs(component) > 1e-9 for component in bounds) and finite and not output.errors()
        return {"gates": [{"name": "geometry", "passed": passed, "points": points, "primitives": primitives, "bounds": list(bounds), "errors": list(output.errors())}]}
    if command == "agent.model.lookdev":
        root = _model_root(task_id)
        material_network = hou.node("/mat") or hou.node("/").createNode("mat", "mat")
        material = material_network.node(_task_name(task_id, "AGENT_MATERIAL"))
        if material is None:
            with _undo("Houdini Agent build lookdev"):
                try:
                    material = material_network.createNode("mtlxstandard_surface", _task_name(task_id, "AGENT_MATERIAL"))
                except hou.OperationFailed:
                    material = material_network.createNode("principledshader", _task_name(task_id, "AGENT_MATERIAL"))
                _set_first_parm(material, ["base_color", "basecolor"], (0.55, 0.55, 0.58))
                _set_first_parm(material, ["specular_roughness", "rough"], 0.35)
                root.setUserData("agent_material", material.path())
                shop = root.parm("shop_materialpath")
                if shop is not None:
                    shop.set(material.path())
                material.moveToGoodPosition()
        return {"gates": [{"name": "material_created", "passed": bool(root.userData("agent_material"))}], "material": root.userData("agent_material")}
    if command == "agent.model.solaris":
        root = _model_root(task_id)
        stage = hou.node(stage_path)
        if stage is None:
            stage_parent = hou.node("/stage")
            if stage_parent is None:
                stage_parent = hou.node("/").createNode("lopnet", "stage")
            with _undo("Houdini Agent build Solaris stage"):
                stage = stage_parent.createNode("subnet", _task_name(task_id, "HOUDINI_AGENT_STAGE"))
                sop_import = stage.createNode("sopimport", "import_model")
                if not _set_first_parm(sop_import, ["soppath", "soppath1"], root.userData("agent_out_model")):
                    raise RuntimeError("SOP Import node has no SOP path parameter")
                current = sop_import
                material_library = stage.createNode("materiallibrary", "materials")
                material_library.setInput(0, current)
                current = material_library
                assign = stage.createNode("assignmaterial", "assign_material")
                assign.setInput(0, current)
                _set_first_parm(assign, ["primpattern1", "primpattern"], "/geo/*")
                current = assign
                camera = stage.createNode("camera", "camera")
                camera.setInput(0, current)
                # The Camera LOP defaults its authored prim to
                # ``/cameras/camera`` while Karma Render Settings in Houdini
                # 21/22 defaults to ``/cameras/camera1``.  Align both ends
                # explicitly and move the camera back from the asset so husk
                # receives a valid renderPassState camera.
                _set_first_parm(camera, ["primpath"], "/cameras/camera1")
                _set_first_parm(camera, ["sample_cameraprim"], "/cameras/camera1")
                _set_first_parm(camera, ["tz"], 5.0)
                current = camera
                try:
                    light = stage.createNode("domelight", "key_light")
                except hou.OperationFailed:
                    light = stage.createNode("light", "key_light")
                light.setInput(0, current)
                current = light
                karma = stage.createNode("karmarendersettings", "karma_settings")
                karma.setInput(0, current)
                _set_first_parm(karma, ["camera"], "/cameras/camera1")
                selected_renderer = _choose_karma_engine(karma, str((params.get("render") or {}).get("renderer") or "auto"))
                resolution_info = _set_resolution(karma, (params.get("render") or {}).get("resolution"))
                current = karma
                render = stage.createNode("usdrender_rop", "karma_render")
                render.setInput(0, current)
                _set_first_parm(render, ["override_camera"], "/cameras/camera1")
                _set_resolution(render, (params.get("render") or {}).get("resolution"))
                stage.setUserData("agent_render", render.path())
                stage.setUserData("agent_camera", camera.path())
                stage.setUserData("agent_renderer", selected_renderer)
                stage.setUserData("agent_resolution", json.dumps(resolution_info))
                stage.layoutChildren()
        render_path = stage.userData("agent_render")
        return {"gates": [{"name": "solaris_stage", "passed": bool(render_path)}], "stage": stage.path(), "render_node": render_path, "renderer": stage.userData("agent_renderer") or "karma_cpu"}
    if command in {"agent.model.render_preview", "agent.model.render_final"}:
        stage = hou.node(stage_path)
        if stage is None:
            raise RuntimeError("Solaris stage missing")
        render = hou.node(stage.userData("agent_render"))
        if render is None:
            raise RuntimeError("Karma render node missing")
        full_start, full_end, full_stride = _model_operation_frame_range(params)
        output_dir = _task_output_dir(params)
        kind = "preview" if command.endswith("preview") else "final"
        file_pattern = output_dir / f"{kind}.$F4.exr"
        if not _set_first_parm(render, ["outputimage", "picture", "lopoutput"], str(file_pattern)):
            raise RuntimeError("Karma render node has no output image parameter")
        start, end = full_start, full_end
        if kind == "preview":
            end = start
        resolution_info = _set_resolution(render, (params.get("render") or {}).get("resolution"))
        before = json.loads(stage.userData(f"agent_{kind}_before") or "{}")
        render_stride = 1 if start == end else full_stride
        for frame in range(start, end + 1, render_stride):
            candidate = Path(str(file_pattern).replace("$F4", f"{frame:04d}"))
            if candidate.is_file():
                before[str(frame)] = {"bytes": candidate.stat().st_size, "modified_ns": candidate.stat().st_mtime_ns}
        _set_first_parm(render, ["trange"], 1 if end != start else 0)
        if end == start:
            # On Houdini 21/22 the ROP's f1/f2 controls are disabled in
            # single-frame mode; the current Houdini frame is the authoritative
            # value for a trange=0 render.  Setting it here prevents every
            # expanded task step from silently re-rendering frame 1.
            hou.setFrame(start)
        else:
            _set_first_parm(render, ["f1", "start"], start)
            _set_first_parm(render, ["f2", "end"], end)
            _set_first_parm(render, ["f3", "inc", "step"], full_stride)
        execute = _first_parm(render, ["execute", "render", "executebackground"])
        if execute is None:
            raise RuntimeError("Karma render node has no execute button")
        _press_button_async(execute)
        stage.setUserData(f"agent_{kind}_pattern", str(file_pattern))
        stored_range = [full_start, full_end, full_stride] if kind == "final" else [start, end, 1]
        stage.setUserData(f"agent_{kind}_range", json.dumps(stored_range))
        stage.setUserData(f"agent_{kind}_before", json.dumps(before))
        # The render is asynchronous; "started" is progress, not verification.
        # The host performs the deterministic file gate afterwards.
        return {"gates": [{"name": f"{kind}_render_started", "passed": True, "kind": "progress"}], "output_pattern": str(file_pattern), "resolution": resolution_info, "frame": start if start == end else None, "before": before}
    if command in {"agent.model.verify_preview", "agent.model.verify_final"}:
        stage = hou.node(stage_path)
        if stage is None:
            raise RuntimeError("Solaris stage missing")
        kind = "preview" if command.endswith("preview") else "final"
        pattern = stage.userData(f"agent_{kind}_pattern")
        stored = json.loads(stage.userData(f"agent_{kind}_range") or "[1,1,1]")
        start, end, stride = _model_operation_frame_range(params, stored)
        before = json.loads(stage.userData(f"agent_{kind}_before") or "{}")
        outputs: list[dict[str, Any]] = []
        missing: list[int] = []
        stale: list[int] = []
        if not isinstance(pattern, str) or not pattern:
            raise BridgeCommandError("SCENE_STATE_MISSING", "model operation output pattern is missing")
        for frame in range(start, end + 1, stride):
            path = Path(str(pattern).replace("$F4", f"{frame:04d}"))
            if not path.is_file() or path.stat().st_size == 0:
                missing.append(frame)
            elif str(frame) in before and path.stat().st_mtime_ns <= int(before[str(frame)].get("modified_ns") or 0):
                stale.append(frame)
            else:
                outputs.append(_artifact(path))
        return {"gates": [{"name": f"{kind}_artifacts", "passed": not missing and not stale, "missing_frames": missing, "stale_frames": stale}], "artifacts": outputs}
    if command == "agent.model.deliver":
        root = _model_root(task_id)
        delivery_mode = (params.get("delivery") or {}).get("mode", "merge_current")
        delivery = {"model_root": root.path(), "mode": delivery_mode}
        artifacts = []
        if delivery_mode == "save_copy":
            output_dir = _task_output_dir(params)
            hip_path = output_dir / f"{_task_name(task_id, 'houdini')}.hip"
            _save_hip_copy_preserving_current(hip_path, root)
            delivery["hip_path"] = str(hip_path)
            artifacts.append(_artifact(hip_path))
        # "Ready" must mean the declared artifacts exist and are non-empty;
        # otherwise the gate asserts a delivery nobody checked.
        missing = [
            str(item.get("path"))
            for item in artifacts
            if not Path(str(item.get("path") or "")).is_file() or Path(str(item.get("path") or "")).stat().st_size == 0
        ]
        return {
            "gates": [{"name": "delivery_ready", "passed": not missing, "missing_artifacts": missing}],
            "delivery": delivery,
            "artifacts": artifacts,
        }
    raise ValueError(f"unsupported model action: {command}")


def _fx_configuration(params: dict[str, Any]) -> dict[str, Any]:
    constraints = params.get("constraints") if isinstance(params.get("constraints"), dict) else {}
    nested = constraints.get("fx") if isinstance(constraints.get("fx"), dict) else {}
    result = dict(nested)
    step_params = params.get("step_params") if isinstance(params.get("step_params"), dict) else {}
    result.update(step_params)
    return result


def _fx_pack(params: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    pack_id = str(_fx_configuration(params).get("domain_pack") or "").strip()
    if not pack_id:
        raise BridgeCommandError("INVALID_ARGUMENT", "domain_pack is required")
    pack = _FX_PACKS.get(pack_id)
    if pack is None:
        raise BridgeCommandError("UNSUPPORTED_DOMAIN", "unsupported Houdini effect domain pack: {}".format(pack_id))
    if (params.get('frozen_render_scene') or {}).get('profile') == 'official_karma_disklight_v1':
        import hou
        from houdini_bridge.official_karma_scene import overlay_host_pack, DOMAIN
        if pack_id != DOMAIN:
            raise BridgeCommandError('STATIC_RENDER_SCENE_REQUIRED','official case requires its lighting domain')
        return pack_id, overlay_host_pack(pack,hou.applicationVersionString(),configuration=params.get("frozen_render_scene"))
    if pack_id in {"material_lookdev_v1", "lighting_camera_render_v1"}:
        import hou
        from houdini_bridge.native_render_domains import overlay_host_pack, NativeRenderDomainError
        try:
            pack = overlay_host_pack(pack_id, pack, hou.applicationVersionString())
        except NativeRenderDomainError as exc:
            raise BridgeCommandError(exc.code, str(exc)) from exc
    elif pack_id in {"pyro_smoke_v1", "pyro_fire_v1", "vellum_cloth_v1", "vellum_softbody_grains_v1", "crowd_agents_v1", "hair_fur_v1", "water_flip_v1", "rbd_destruction_v1", "particles_v1", "swarm_flocking_v1", "water_ocean_v1", "procedural_geometry_v1"}:
        import hou
        from houdini_bridge.native_domain_registry import overlay_host_pack
        try:
            pack = overlay_host_pack(pack_id, pack, hou.applicationVersionString(),
                                     _fx_configuration(params).get('vellum_branch'))
        except ValueError as exc:
            raise BridgeCommandError(getattr(exc, 'code', 'NATIVE_PLAN_INVALID'), str(exc)) from exc
    if (params.get('frozen_render_scene') or {}).get('profile') == 'bounded_geometry_rig_v1':
        from houdini_bridge.geometry_render_scene import overlay_pack
        if pack_id != 'material_lookdev_v1':
            raise BridgeCommandError('STATIC_RENDER_SCENE_REQUIRED', 'geometry rig requires its material domain')
        pack = overlay_pack(pack)
    return pack_id, pack


def _fx_category(name: str):
    import hou

    factories = {
        "sop": "sopNodeTypeCategory",
        "dop": "dopNodeTypeCategory",
        "lop": "lopNodeTypeCategory",
        "vop": "vopNodeTypeCategory",
        "obj": "objNodeTypeCategory",
        "rop": "ropNodeTypeCategory",
    }
    factory = getattr(hou, factories.get(name, ""), None)
    return factory() if factory is not None else None


def _fx_render_domain_connections(pack_id, roles):
    """Resolve named MaterialX ports into the existing connection transaction."""
    import hou
    from houdini_bridge.native_render_domains import connection_requirements, resolve_named_connections, NativeRenderDomainError
    interfaces = {}
    named_roles = {wire[side + '_role'] for wire in connection_requirements(pack_id, hou.applicationVersionString())
                   for side, key in (('source','source_output_name'),('destination','destination_input_name')) if key in wire}
    for role, path in roles.items():
        if role not in named_roles:
            continue
        node = hou.node(path)
        if node is None:
            raise BridgeCommandError("SCENE_STATE_MISSING", "native node role is missing: " + role)
        # Every port index comes from this actual node. Static declared ordinal
        # positions cannot establish its instantiated HOM interface.
        interfaces[role] = {"origin": "runtime_hom", "input_names": tuple(node.inputNames()),
                            "output_names": tuple(node.outputNames())}
    try:
        wires = resolve_named_connections(pack_id, hou.applicationVersionString(), interfaces)
        if 'stage_metadata' in roles:
            split = 'ground_import' in roles
            expected = {'ground', 'stage_metadata'} | ({'ground_import', 'geometry_stage_merge'} if split else {'geometry_output'})
            if not expected <= set(roles) or (split and 'geometry_output' in roles):
                raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'incomplete static scene roles')
            wires = [dict(w,source_role='stage_metadata') if w['source_role']=='geometry_import' and w['destination_role']=='material_library' else w for w in wires]
            wires += [dict(source_role=source,source_output=0,destination_role=target,destination_input=index,require_same_parent=True)
                      for source,target,index in ([('geometry_import','geometry_stage_merge',0),('ground_import','geometry_stage_merge',1),('geometry_stage_merge','stage_metadata',0)] if split else [('source','geometry_output',0),('ground','geometry_output',1),('geometry_import','stage_metadata',0)])]
        return wires
    except NativeRenderDomainError as exc:
        raise BridgeCommandError(exc.code, str(exc)) from exc


def _fx_render_domain_candidate_plan(pack_id, changes, observations, semantic_contracts):
    """Preflight data for the existing prepared/snapshot/rollback candidate loop."""
    import hou
    from houdini_bridge.native_render_domains import candidate_write_plan, validate_control_write_plan, NativeRenderDomainError
    try:
        writes = candidate_write_plan(
            pack_id, changes, hou.applicationVersionString(),
            shutter_contract=semantic_contracts.get("shutter"),
        )
        validate_control_write_plan(writes, observations)
        return writes
    except NativeRenderDomainError as exc:
        raise BridgeCommandError(exc.code, str(exc)) from exc


def _fx_render_domain_initialization_plan(pack_id, bindings, renderer_observation=None):
    """Return plans for fresh owned nodes; existing initialization owns mutation."""
    import hou
    from houdini_bridge.native_render_domains import renderer_parameter, trusted_initialization_plan, trusted_node_flag_plan, NativeRenderDomainError
    try:
        version = hou.applicationVersionString()
        field = (renderer_parameter(version, renderer_observation or {})
                 if pack_id == "lighting_camera_render_v1" else None)
        return {"parms": trusted_initialization_plan(pack_id, version, bindings, renderer_field=field),
                "node_flags": trusted_node_flag_plan(pack_id, version)}
    except NativeRenderDomainError as exc:
        raise BridgeCommandError(exc.code, str(exc)) from exc


def _fx_native_field_observation(node, name, *, observe_value=True):
    """Observe one instantiated HOM interface; unknown state is never writable."""
    parm = _resolve_parm_target(node, [name])
    if parm is None:
        raise BridgeCommandError("NATIVE_CONTROL_INTERFACE_REQUIRED", "native parameter is missing: " + name)
    try:
        template = parm.parmTemplate()
        update = getattr(node, 'updateParmStates', None)
        if callable(update):
            update()
        kind = str(template.type()).rsplit(".", 1)[-1]
        size = template.numComponents()
        native = {"Float": "float", "Int": "integer", "Menu": "integer",
                  "Toggle": "toggle", "String": "string", "Folder": "integer", "Data": "data"}.get(kind)
        if kind == "Float" and size == 3 and str(template.namingScheme()).rsplit(".", 1)[-1] == "RGBA":
            native = "color"
        components = parm._components()
        instance_menu_types = {"renderer": {"Driver/usdrender", "Lop/usdrender_rop"},
                               "res_mode": {"Lop/karmarendersettings"}}
        if (name in instance_menu_types and str(node.type().nameWithCategory()) in instance_menu_types[name]
                and kind == "String" and type(size) is int and size == 1):
            if len(components) != 1:
                raise ValueError("instance menu requires one native parameter component")
            # These exact renderer and resolution menus are generated on the instance.
            items = components[0].menuItems()
            if not isinstance(items, (tuple, list)) or any(type(item) is not str for item in items):
                raise ValueError("instance menu tokens are unavailable")
            tokens = tuple(items)
        elif kind in {"String", "Int", "Menu"}:
            tokens = tuple(str(item) for item in template.menuItems())
        elif kind in {"Float", "Toggle", "Folder", "Data"}:
            tokens = ()
        else:
            raise ValueError("unsupported native field shape")
        states = [(component.isHidden(),component.isDisabled(),component.isLocked()) for component in components]
        if any(type(value) is not bool for row in states for value in row):
            raise ValueError("unknown native gate state")
        hidden = any(row[0] for row in states)
        value = (parm.evalAsString() if tokens and kind in {"Menu", "String"} else parm.eval()) if observe_value else None
        if type(hidden) is not bool or type(size) is not int or native is None:
            raise ValueError("unsupported native field shape")
        return {"origin": "runtime_hom", "type": native, "size": size,
                "locked": parm.isLocked(), "disabled": parm.isDisabled(), "hidden": hidden,
                "menu_tokens": tokens, "value": value}
    except Exception as exc:
        raise BridgeCommandError("NATIVE_CONTROL_INTERFACE_REQUIRED", "native state unavailable: " + parm.path()) from exc


def _fx_planned_module(pack):
    from houdini_bridge.native_domain_registry import module_for, arguments
    import hou
    domain = pack['native_domain_id']
    return module_for(domain), arguments(domain, hou.applicationVersionString(), pack.get('native_branch'))


def _fx_planned_observation(node, name, *, observe_value=True):
    actual = _fx_native_field_observation(node, name, observe_value=observe_value)
    parm = _resolve_parm_target(node, [name])
    template = parm.parmTemplate()
    kind = str(template.type()).rsplit('.', 1)[-1]
    actual['type'] = 'ordinal' if kind == 'Menu' else 'multiparm' if kind == 'Folder' else actual['type']
    actual['driven'] = (_parm_snapshot_is_driven(_snapshot_parm_state(parm)) if observe_value else
        any(_component_driver_identity(p)['expression'] or _component_driver_identity(p)['reference_path'] or tuple(p.keyframes()) for p in parm._components()))
    actual['menu_labels'] = tuple(template.menuLabels()) if kind in {'Int', 'Menu', 'String'} else ()
    actual['menu_uses_token_value'] = bool(template.menuUseToken()) if hasattr(template, 'menuUseToken') else False
    if actual['menu_uses_token_value'] and observe_value:
        actual['value'] = parm.eval()
    return actual


def _fx_planned_multiparm_observation(node, parent_name, patterns):
    parent = node.parm(parent_name)
    if parent is None or not parent.isMultiParmParent():
        raise BridgeCommandError('ACTUAL_MULTIPARM_BINDING_REQUIRED', node.path() + '/' + parent_name)
    count = parent.eval()
    if type(count) is not int or count != 1:
        raise BridgeCommandError('ACTUAL_MULTIPARM_BINDING_REQUIRED', 'one compiled owned row is required')
    instances = tuple(parent.multiParmInstances())
    bindings, indices = {}, set()
    for pattern in patterns:
        matching = [p for p in instances if re.fullmatch(re.escape(pattern).replace(r'\#',r'[1-9][0-9]*'),p.name())]
        if len(matching) != 1:
            raise BridgeCommandError('ACTUAL_MULTIPARM_BINDING_REQUIRED', 'ambiguous compiled field: ' + pattern)
        bindings[pattern] = matching[0].name()
        indices.add(tuple(matching[0].multiParmInstanceIndices()))
    if len(indices) != 1 or not next(iter(indices), ()):
        raise BridgeCommandError('ACTUAL_MULTIPARM_BINDING_REQUIRED', 'compiled row indices differ')
    return {'origin':'runtime_hom','parent':parent_name,'instance_count':count,'bindings':bindings}


def _fx_planned_owned_root(roles, pack):
    import hou
    root_path = posixpath.commonpath(list(roles.values()))
    root = hou.node(root_path)
    if (not root_path.startswith('/obj/') or root is None or
            root.userData('bridge_fx_owned') != '1'):
        raise BridgeCommandError('SCENE_OWNERSHIP_REQUIRED','native context has no exact owned root')
    lease = _root_lease_check(root_path,scope='sop',renew=False)
    manifest = json.loads(root.userData('bridge_fx_manifest_v1') or '{}')
    if manifest and (manifest.get('task_id') != lease['task_id'] or
            manifest.get('domain_pack') != pack['native_domain_id'] or manifest.get('nodes') != roles):
        raise BridgeCommandError('SCENE_OWNERSHIP_REQUIRED','native context differs from its owned manifest')
    for requirement in pack['nodes']:
        node = hou.node(roles.get(requirement['role'],''))
        if (node is None or not node.path().startswith(root_path+'/') or
                node.type().name() not in requirement['types']):
            raise BridgeCommandError('SCENE_OWNERSHIP_REQUIRED','native role is outside its fixed owned layout')
        parent = requirement.get('parent_role')
        if parent and node.parent().path() != roles[parent]:
            raise BridgeCommandError('SCENE_OWNERSHIP_REQUIRED','native role context differs')
    return root_path


def _fx_planned_geometry_fact(node, *, output_index=0, input_index=None):
    geometry = (node.geometry(output_index=output_index) if input_index is None
                else node.inputGeometry(input_index))
    if geometry is None:
        raise BridgeCommandError('ACTUAL_NATIVE_GEOMETRY_REQUIRED','native geometry is absent')
    points,prims = tuple(geometry.points()),tuple(geometry.prims())
    if len(points) > 8192 or len(prims) > 8192:
        raise BridgeCommandError('NATIVE_GEOMETRY_BUDGET_EXCEEDED','bounded geometry observation exceeded')
    result = {'origin':'runtime_hom','points':len(points),'primitives':len(prims),
        'primitive_types':sorted({p.type().name() for p in prims}),
        'point_attributes':{},'primitive_attributes':{},'point_attribute_values':{},
        'primitive_attribute_values':{}}
    for owner,elements,method in [('point',points,'pointAttribs'),('primitive',prims,'primAttribs')]:
        attributes = tuple(getattr(geometry,method)())
        if len(attributes) > 128:
            raise BridgeCommandError('NATIVE_GEOMETRY_BUDGET_EXCEEDED','bounded attribute observation exceeded')
        for attribute in attributes:
            kind = str(attribute.dataType()).rsplit('.',1)[-1].lower()
            name,size = attribute.name(),attribute.size()
            result[owner+'_attributes'][name] = {'type':kind,'size':size}
            result[owner+'_attribute_values'][name] = [_json_safe(p.attribValue(name)) for p in elements]
    names = result['primitive_attribute_values'].get('constraint_name',[])
    result['constraint_names'] = sorted(set(names)) if all(isinstance(n,str) for n in names) else []
    result['positions'] = [list(p.position()) for p in points]
    if points:
        result['bbox_min'] = [min(p[axis] for p in result['positions']) for axis in range(3)]
        result['bbox_max'] = [max(p[axis] for p in result['positions']) for axis in range(3)]
    encoded = json.dumps(result,sort_keys=True,separators=(',',':'),allow_nan=False).encode()
    result['geometry_sha256'] = hashlib.sha256(encoded).hexdigest()
    return result


