def _fx_rbd_task_seed(roles, pack):
    root_path = _fx_planned_owned_root(roles, pack)
    lease = _root_lease_check(root_path, scope='sop', renew=False)
    root, manifest = _fx_manifest(lease['task_id'], root_path=root_path)
    try:
        stored = json.loads(_fx_state_path(lease['task_id']).read_text(encoding='utf-8'))
    except (OSError, ValueError) as error:
        raise BridgeCommandError('RBD_TRUSTED_TASK_SEED_REQUIRED', 'persisted task manifest required') from error
    seed = manifest.get('seed')
    if (root is None or manifest != stored or manifest.get('task_id') != lease['task_id']
            or manifest.get('domain_pack') != 'rbd_destruction_v1'
            or manifest.get('execution_root') != root_path or manifest.get('nodes') != roles
            or type(seed) is not int or not 0 <= seed < 2 ** 31):
        raise BridgeCommandError('RBD_TRUSTED_TASK_SEED_REQUIRED', 'owned scene and persisted task seed must agree')
    return seed


