    scope = globals().get('_FX_GEOMETRY_REOPEN_SCOPES', {}).get(root)
    if scope is None:
        return False
    lease = _root_lease_check(root, task_id=scope['task_id'], scope='sop', renew=False)
    return (roles == scope['roles'] and _fx_scene_contract_digest(pack) == scope['pack_sha256']
            and _fx_scene_contract_digest(checkpoint) == scope['checkpoint_sha256']
            and _fx_geometry_host_identity(lease['task_id']) == scope['identity'])


