def _fx_particle_emission_checkpoint(root, manifest):
    if manifest.get('domain_pack') != 'particles_v1':
        return None
    _, pack = _fx_pack({'constraints': {'fx': {'domain_pack': 'particles_v1'}}})
    roles = {item['role']: manifest.get('nodes', {}).get(item['role']) for item in pack['nodes']}
    if root.path() != manifest.get('execution_root'):
        raise BridgeCommandError('PARTICLE_EMISSION_OWNED_NODE_REQUIRED', 'saved particle root differs')
    host = _fx_particle_emission_host()
    if not host.registered(roles, pack):
        basis = manifest.get('native_initialization', {}).get('particle_emission_basis', {})
        if (manifest.get('particle_emission_checkpoint') is not None
                or 'emission_variance' in (manifest.get('candidate_patch') or {})
                or isinstance(basis, dict) and basis.get('schema') == 'bridge.particle-emission-basis/1'):
            raise BridgeCommandError('PARTICLE_EMISSION_REOPEN_CHECKPOINT_REQUIRED', 'saved particle registration is unavailable')
        return None
    try:
        return host.checkpoint(roles, pack)
    except ValueError as error:
        raise BridgeCommandError(getattr(error, 'code', 'PARTICLE_EMISSION_CHECKPOINT_INVALID'), str(error)) from error


def _fx_particle_emission_reopen_authority(roles, pack, checkpoint):
    import hou
    root = _fx_planned_owned_root(roles, pack)
    scope = globals().get('_FX_PARTICLE_EMISSION_REOPEN_SCOPES', {}).get(root)
    if scope is None:
        return False
    lease = _root_lease_check(root, task_id=scope['task_id'], scope='sop', renew=False)
    try:
        current_manifest = json.loads(hou.node(root).userData('bridge_fx_manifest_v1') or '{}')
        embedded = current_manifest.get('particle_emission_checkpoint')
        if (type(embedded) is not dict or
                {name: value for name, value in embedded.items() if name != 'identity'} != scope['embedded_checkpoint']
                or embedded.get('identity') not in (checkpoint.get('identity'), scope['identity'])):
            return False
    except (TypeError, ValueError, AttributeError):
        return False
    return (roles == scope['roles'] and _fx_scene_contract_digest(pack) == scope['pack_sha256']
            and _fx_scene_contract_digest(checkpoint) == scope['checkpoint_sha256']
            and Path(hou.hipFile.path()).resolve() == scope['artifact_path']
            and scope['artifact_path'].is_file()
            and _fx_sha256_file(scope['artifact_path']) == scope['artifact_sha256']
            and _fx_geometry_host_identity(lease['task_id']) == scope['identity'])


@contextmanager
def _fx_particle_emission_reopen_transaction(task_id, manifest, checkpoint, artifact_path, artifact_sha256, *, completion=None, transition_operation_id=None):
    import hou
    if checkpoint is None:
        if manifest.get('domain_pack') == 'particles_v1':
            basis = manifest.get('native_initialization', {}).get('particle_emission_basis', {})
            if (manifest.get('particle_emission_checkpoint') is not None
                    or 'emission_variance' in (manifest.get('candidate_patch') or {})
                    or isinstance(basis, dict) and basis.get('schema') == 'bridge.particle-emission-basis/1'):
                raise BridgeCommandError('PARTICLE_EMISSION_REOPEN_CHECKPOINT_REQUIRED', 'saved particle program requires its checkpoint')
        yield False
        return
    if (type(checkpoint) is not dict or manifest.get('domain_pack') != 'particles_v1'
            or manifest.get('task_id') != task_id):
        raise BridgeCommandError('PARTICLE_EMISSION_REOPEN_CHECKPOINT_REQUIRED', 'saved particle checkpoint is malformed or foreign')
    if manifest.get('particle_emission_checkpoint') != checkpoint:
        raise BridgeCommandError('PARTICLE_EMISSION_REOPEN_CHECKPOINT_REQUIRED', 'saved checkpoint differs from the verified HIP manifest')
    _, pack = _fx_pack({'constraints': {'fx': {'domain_pack': 'particles_v1'}}})
    roles = {item['role']: manifest.get('nodes', {}).get(item['role']) for item in pack['nodes']}
    root = str(manifest.get('execution_root') or '')
    if checkpoint.get('roles') != roles or _fx_planned_owned_root(roles, pack) != root:
        raise BridgeCommandError('PARTICLE_EMISSION_OWNED_NODE_REQUIRED', 'saved particle layout differs')
    path = Path(artifact_path).resolve()
    def verify_artifact():
        if (Path(hou.hipFile.path()).resolve() != path or not path.is_file()
                or _fx_sha256_file(path) != artifact_sha256):
            raise BridgeCommandError('ARTIFACT_MISMATCH', 'particle handoff HIP changed during registration')
    verify_artifact()
    lease = _root_lease_check(root, task_id=task_id, scope='sop', renew=False)
    identity = _fx_geometry_host_identity(lease['task_id'])
    scopes = globals().setdefault('_FX_PARTICLE_EMISSION_REOPEN_SCOPES', {})
    if root in scopes:
        raise BridgeCommandError('PARTICLE_EMISSION_TRANSACTION_ACTIVE', 'particle reopen already holds this root')
    scopes[root] = dict(task_id=task_id, roles=roles, pack_sha256=_fx_scene_contract_digest(pack),
        checkpoint_sha256=_fx_scene_contract_digest(checkpoint), identity=identity,
        embedded_checkpoint={name: value for name, value in checkpoint.items() if name != 'identity'},
        completion=completion, transition_operation_id=transition_operation_id,
        artifact_path=path, artifact_sha256=artifact_sha256)
    host = _fx_particle_emission_host()
    token, committed = None, False
    try:
        token = host.reopen(roles, pack, checkpoint)
        yield True
        verify_artifact()
        if _fx_geometry_host_identity(task_id) != identity:
            raise BridgeCommandError('SCENE_STATE_DRIFT', 'particle host changed during registration')
        host.end(token, commit=True)
        committed = True
    except ValueError as error:
        raise BridgeCommandError(getattr(error, 'code', 'PARTICLE_EMISSION_CHECKPOINT_INVALID'), str(error)) from error
    finally:
        try:
            if token is not None and not committed and token in host.authority['reopens']:
                host.end(token, commit=False)
        finally:
            scopes.pop(root, None)


@contextmanager
def _fx_rbd_reopen_transaction(task_id, manifest, checkpoint, artifact_path, artifact_sha256, *, completion=None, transition_operation_id=None):
    import hou
    if checkpoint is None:
        if manifest.get('domain_pack') == 'rbd_destruction_v1':
            from houdini_bridge.native_rbd_controls_host import BASIS_KEY, PROGRAM_KEY
            carrier = hou.node(manifest.get('nodes', {}).get('rbd_velocity') or '')
            if (manifest.get('rbd_velocity_checkpoint') is not None or carrier is not None
                    and any(carrier.userData(key) is not None for key in (BASIS_KEY, PROGRAM_KEY))):
                raise BridgeCommandError('RBD_REOPEN_CHECKPOINT_REQUIRED', 'saved velocity program requires its checkpoint')
        yield False
        return
    if (type(checkpoint) is not dict or manifest.get('domain_pack') != 'rbd_destruction_v1'
            or manifest.get('task_id') != task_id):
        raise BridgeCommandError('RBD_REOPEN_CHECKPOINT_REQUIRED', 'saved velocity checkpoint is malformed or foreign')
    _, pack = _fx_pack({'constraints': {'fx': {'domain_pack': 'rbd_destruction_v1'}}})
    roles = {item['role']: manifest.get('nodes', {}).get(item['role']) for item in pack['nodes']}
    root = str(manifest.get('execution_root') or '')
    if checkpoint.get('roles') != roles or _fx_planned_owned_root(roles, pack) != root:
        raise BridgeCommandError('RBD_ACTUAL_OWNED_PROGRAM_NODE_REQUIRED', 'saved velocity layout differs')
    path = Path(artifact_path).resolve()
    def verify_artifact():
        if (Path(hou.hipFile.path()).resolve() != path or not path.is_file()
                or _fx_sha256_file(path) != artifact_sha256):
            raise BridgeCommandError('ARTIFACT_MISMATCH', 'RBD handoff HIP changed during registration')
    verify_artifact()
    lease = _root_lease_check(root, task_id=task_id, scope='sop', renew=False)
    identity = _fx_owned_domain_host_identity(lease['task_id'])
    scopes = globals().setdefault('_FX_RBD_REOPEN_SCOPES', {})
    if root in scopes:
        raise BridgeCommandError('RBD_TRANSACTION_ACTIVE', 'RBD reopen already holds this root')
    scopes[root] = dict(task_id=task_id, roles=roles, pack_sha256=_fx_scene_contract_digest(pack),
        checkpoint_sha256=_fx_scene_contract_digest(checkpoint), identity=identity,
        completion=completion, transition_operation_id=transition_operation_id,
        artifact_path=path, artifact_sha256=artifact_sha256)
    host = _fx_rbd_velocity_host()
    token, committed = None, False
    try:
        token = host.reopen(roles, pack, checkpoint)
        yield True
        verify_artifact()
        if _fx_owned_domain_host_identity(task_id) != identity:
            raise BridgeCommandError('SCENE_STATE_DRIFT', 'RBD host changed during registration')
        host.end(token, commit=True)
        committed = True
    except ValueError as error:
        raise BridgeCommandError(getattr(error, 'code', 'RBD_CHECKPOINT_INVALID'), str(error)) from error
    finally:
        try:
            if token is not None and not committed:
                host.end(token, commit=False)
        finally:
            scopes.pop(root, None)


@contextmanager
def _fx_registered_rebind_saved_contract(task_id, contract, path, digest, *, transition=None, completion=None):
    try:
        with _fx_geometry_rebind_saved_contract(task_id, contract, path, digest,
                transition=transition, completion=completion) as geometry_restored:
            root, manifest = _fx_manifest(task_id, required=False,
                root_path=(contract or {}).get('execution_root'))
            checkpoint = (contract or {}).get('rbd_velocity_checkpoint')
            particle_checkpoint = (contract or {}).get('particle_emission_checkpoint')
            if root is None or not manifest:
                if checkpoint is not None:
                    raise BridgeCommandError('RBD_ACTUAL_OWNED_PROGRAM_NODE_REQUIRED', 'saved RBD graph is unavailable')
                if particle_checkpoint is not None:
                    raise BridgeCommandError('PARTICLE_EMISSION_OWNED_NODE_REQUIRED', 'saved particle graph is unavailable')
                yield dict(geometry_registry_restored=geometry_restored, rbd_velocity_restored=False, particle_emission_restored=False)
                return
            if (checkpoint is not None or particle_checkpoint is not None) and root.path() != contract.get('execution_root'):
                raise BridgeCommandError('RBD_ACTUAL_OWNED_PROGRAM_NODE_REQUIRED', 'saved velocity root differs')
            if checkpoint is None and particle_checkpoint is None and manifest.get('domain_pack') not in {'rbd_destruction_v1', 'particles_v1'}:
                yield dict(geometry_registry_restored=geometry_restored, rbd_velocity_restored=False, particle_emission_restored=False)
                return
            with _root_lease_fence(root.path(), task_id=task_id, scope='sop'):
                with _fx_rbd_reopen_transaction(task_id, manifest, checkpoint, path, digest,
                        completion=completion, transition_operation_id=(transition or {}).get('operation_id')) as rbd_restored, _fx_particle_emission_reopen_transaction(
                        task_id, manifest, particle_checkpoint, path, digest, completion=completion,
                        transition_operation_id=(transition or {}).get('operation_id')) as particle_restored:
                    yield dict(geometry_registry_restored=geometry_restored, rbd_velocity_restored=rbd_restored, particle_emission_restored=particle_restored)
    except Exception:
        _fx_geometry_restore_transition_intent(task_id, transition, completion)
        raise


@contextmanager
def _fx_geometry_reopen_transaction(task_id, manifest, checkpoint, artifact_path, artifact_sha256, *, completion=None, transition_operation_id=None):
    """Rebind only inside a verified HIP handoff and the caller's root fence."""
    import hou
    if checkpoint is None:
        if manifest.get('domain_pack') == 'procedural_geometry_v1':
            from houdini_bridge.native_geometry_controls_host import BASIS_KEY, REGISTRATION_KEY
            carrier = hou.node(manifest.get('nodes', {}).get('geometry_deform', ''))
            if carrier is not None and any(carrier.userData(key) is not None for key in (BASIS_KEY, REGISTRATION_KEY)):
                raise BridgeCommandError('GEOMETRY_REOPEN_CHECKPOINT_REQUIRED', 'persisted geometry registration requires its saved checkpoint')
        yield False
        return
    if not isinstance(checkpoint, dict):
        raise BridgeCommandError('GEOMETRY_REOPEN_CHECKPOINT_REQUIRED', 'saved geometry checkpoint is malformed')
    if manifest.get('domain_pack') != 'procedural_geometry_v1' or manifest.get('task_id') != task_id:
        raise BridgeCommandError('GEOMETRY_OWNED_GRAPH_REQUIRED', 'checkpoint belongs to another task or domain')
    _, pack = _fx_pack({'constraints': {'fx': {'domain_pack': 'procedural_geometry_v1'}}})
    roles = {item['role']: manifest.get('nodes', {}).get(item['role']) for item in pack['nodes']}
    root = str(manifest.get('execution_root') or '')
    if checkpoint.get('roles') != roles or _fx_planned_owned_root(roles, pack) != root:
        raise BridgeCommandError('GEOMETRY_OWNED_GRAPH_REQUIRED', 'checkpoint roles differ from the registered native layout')
    path = Path(artifact_path).resolve()
    def verify_artifact():
        if (Path(hou.hipFile.path()).resolve() != path or not path.is_file()
                or _fx_sha256_file(path) != artifact_sha256):
            raise BridgeCommandError('ARTIFACT_MISMATCH', 'geometry handoff HIP changed during registration')
    verify_artifact()
    lease = _root_lease_check(root, task_id=task_id, scope='sop', renew=False)
    identity = _fx_geometry_host_identity(lease['task_id'])
    scopes = globals().setdefault('_FX_GEOMETRY_REOPEN_SCOPES', {})
    if root in scopes:
        raise BridgeCommandError('GEOMETRY_TRANSACTION_ACTIVE', 'geometry reopen already holds this root')
    scopes[root] = dict(task_id=task_id, roles=roles, pack_sha256=_fx_scene_contract_digest(pack),
        checkpoint_sha256=_fx_scene_contract_digest(checkpoint), identity=identity,
        completion=completion, transition_operation_id=transition_operation_id)
    registry = _fx_geometry_registry()
    token = None
    committed = False
    try:
        token = registry.reopen(roles, pack, checkpoint)
        yield True
        verify_artifact()
        if _fx_geometry_host_identity(task_id) != identity:
            raise BridgeCommandError('SCENE_STATE_DRIFT', 'geometry host changed during registration')
        registry.end(token, commit=True)
        committed = True
    except ValueError as error:
        raise BridgeCommandError(getattr(error, 'code', 'GEOMETRY_REGISTRY_REFUSED'), str(error)) from error
    finally:
        try:
            if token is not None and not committed:
                registry.end(token, commit=False)
        finally:
            scopes.pop(root, None)


@contextmanager
def _fx_geometry_rebind_saved_contract(task_id, contract, path, digest, *, transition=None, completion=None):
    checkpoint = (contract or {}).get('geometry_registry_checkpoint')
    root, manifest = _fx_manifest(task_id, required=False,
        root_path=(contract or {}).get('execution_root'))
    if root is None or not manifest:
        if checkpoint is not None:
            raise BridgeCommandError('GEOMETRY_OWNED_GRAPH_REQUIRED', 'saved geometry graph is unavailable')
        yield False
        return
    if checkpoint is None and manifest.get('domain_pack') != 'procedural_geometry_v1':
        yield False
        return
    if checkpoint is not None and root.path() != contract.get('execution_root'):
        raise BridgeCommandError('GEOMETRY_OWNED_GRAPH_REQUIRED', 'saved checkpoint execution root differs')
    try:
        with _root_lease_fence(root.path(), task_id=task_id, scope='sop'):
            with _fx_geometry_reopen_transaction(task_id, manifest, checkpoint, path, digest,
                    completion=completion, transition_operation_id=(transition or {}).get('operation_id')) as restored:
                yield restored
    except Exception:
        _fx_geometry_restore_transition_intent(task_id, transition, completion)
        raise


def _fx_geometry_restore_transition_intent(task_id, transition, completion):
    if not isinstance(transition, dict) or transition.get('state') != 'INTENT':
        return
    runner = fx_operation_runner(task_id)
    with runner._locked():
        store = runner._load()
        operation_id = transition['operation_id']
        current = runner._record(store, operation_id, family='scene_transitions')
        completed = (completion or {}).get('record')
        if (not isinstance(current, dict) or current.get('state') != 'COMPLETED'
                or current.get('request_sha256') != transition.get('request_sha256')
                or not isinstance(completed, dict) or current != completed
                or current.get('operation_receipt_sha256') != _fx_scene_transition_digest(current)):
            return
        store_cas = int(store.get('scene_transition_cas') or 0) + 1
        restored = dict(transition, store_cas=store_cas)
        restored['operation_receipt_sha256'] = _fx_scene_transition_digest(restored)
        store['scene_transitions'][operation_id] = restored
        store['scene_transition_cas'] = store_cas
        runner._save(store)


def _fx_geometry_reconcile_checkpoint(task_id, request, command):
    if command not in {'scene.reopen_task_hip', 'scene.reopen_owned_hip'}:
        return False
    saves_path = _fx_task_saves_path(task_id)
    store = json.loads(saves_path.read_text(encoding='utf-8')) if saves_path.is_file() else {}
    path = Path(str(request.get('path') or '')).resolve()
    matching = [record for record in store.get('saves', [])
                if Path(str(record.get('path') or '')).resolve() == path
                and record.get('sha256') == request.get('sha256')]
    if not matching:
        if command == 'scene.reopen_task_hip':
            raise BridgeCommandError('GEOMETRY_REOPEN_RECONCILIATION_UNPROVEN', 'saved scene contract is unavailable')
        return False
    saved = matching[-1]
    contract = saved.get('scene_contract')
    if contract is not None and (not isinstance(contract, dict) or
            saved.get('scene_contract_sha256') != _fx_scene_contract_digest(contract)):
        raise BridgeCommandError('GEOMETRY_REOPEN_RECONCILIATION_UNPROVEN', 'saved scene contract is invalid')
    expected = (contract or {}).get('geometry_registry_checkpoint')
    root, manifest = _fx_manifest(task_id, required=False)
    if expected is not None and (root is None or manifest.get('domain_pack') != 'procedural_geometry_v1'
            or manifest.get('execution_root') != contract.get('execution_root')
            or manifest.get('geometry_registry_checkpoint') is None):
        raise BridgeCommandError('GEOMETRY_REOPEN_RECONCILIATION_UNPROVEN', 'saved geometry handoff requires its current registry and manifest')
    if root is None or manifest.get('domain_pack') != 'procedural_geometry_v1':
        return False
    import hou
    carrier = hou.node(manifest.get('nodes', {}).get('geometry_deform', ''))
    if manifest.get('geometry_registry_checkpoint') is None and (carrier is None or
            carrier.userData('bridge_geometry_deform_initialization_v1') is None):
        return False
    with _root_lease_fence(root.path(), task_id=task_id, scope='sop'):
        checkpoint = _fx_geometry_checkpoint(root, manifest)
        if not isinstance(contract, dict):
            raise BridgeCommandError('GEOMETRY_REOPEN_RECONCILIATION_UNPROVEN', 'saved geometry contract is unavailable')
        _fx_verify_scene_contract(contract, task_id)
        if (not isinstance(expected, dict) or checkpoint is None
                or {key: value for key, value in checkpoint.items() if key != 'binding'} !=
                   {key: value for key, value in expected.items() if key != 'binding'}
                or any(checkpoint['binding'].get(key) != expected.get('binding', {}).get(key)
                       for key in ('task_id', 'task_root', 'native_version'))):
            raise BridgeCommandError('GEOMETRY_REOPEN_RECONCILIATION_UNPROVEN', 'current geometry registration differs from the saved handoff')
    return True


def _fx_rbd_reconcile_checkpoint(task_id, request, command):
    if command not in {'scene.reopen_task_hip', 'scene.reopen_owned_hip'}:
        return False
    saves_path = _fx_task_saves_path(task_id)
    store = json.loads(saves_path.read_text(encoding='utf-8')) if saves_path.is_file() else {}
    path = Path(str(request.get('path') or '')).resolve()
    matching = [record for record in store.get('saves', [])
                if Path(str(record.get('path') or '')).resolve() == path
                and record.get('sha256') == request.get('sha256')]
    if not matching:
        return False
    saved = matching[-1]
    contract = saved.get('scene_contract')
    if contract is not None and (type(contract) is not dict
            or saved.get('scene_contract_sha256') != _fx_scene_contract_digest(contract)):
        raise BridgeCommandError('RBD_REOPEN_RECONCILIATION_UNPROVEN', 'saved velocity contract is invalid')
    expected = (contract or {}).get('rbd_velocity_checkpoint')
    root, manifest = _fx_manifest(task_id, required=False)
    if expected is not None and (root is None or manifest.get('domain_pack') != 'rbd_destruction_v1'
            or manifest.get('execution_root') != contract.get('execution_root')
            or manifest.get('rbd_velocity_checkpoint') is None):
        raise BridgeCommandError('RBD_REOPEN_RECONCILIATION_UNPROVEN', 'saved velocity handoff is unavailable')
    if root is None or manifest.get('domain_pack') != 'rbd_destruction_v1':
        return False
    with _root_lease_fence(root.path(), task_id=task_id, scope='sop'):
        checkpoint = _fx_rbd_checkpoint(root, manifest)
        if checkpoint is None and expected is None:
            return False
        _fx_verify_scene_contract(contract, task_id)
        if (type(expected) is not dict or checkpoint is None
                or {key: value for key, value in checkpoint.items() if key != 'identity'} !=
                   {key: value for key, value in expected.items() if key != 'identity'}):
            raise BridgeCommandError('RBD_REOPEN_RECONCILIATION_UNPROVEN', 'current velocity handoff differs')
    return True


