def _fx_geometry_observations(roles, pack):
    try:
        return _fx_geometry_host().observations(roles, pack)
    except ValueError as error:
        raise BridgeCommandError(getattr(error, 'code', 'GEOMETRY_CONTEXT_REQUIRED'), str(error)) from error


@contextmanager
def _fx_geometry_build_transaction(root_path):
    scopes = globals().setdefault('_FX_GEOMETRY_BUILD_SCOPES', {})
    if root_path in scopes:
        raise BridgeCommandError('GEOMETRY_BUILD_TRANSACTION_REQUIRED', 'nested geometry build is unavailable')
    scope = {'token': None}
    scopes[root_path] = scope
    committed = False
    try:
        yield
        committed = True
    finally:
        try:
            if scope['token'] is not None:
                registry = _fx_geometry_registry()
                try:
                    registry.end(scope['token'], commit=committed)
                except Exception:
                    if committed:
                        registry.end(scope['token'], commit=False)
                    raise
        finally:
            scopes.pop(root_path, None)


def _fx_write_planned_item(item, roles, pack):
    if 'particle_emission_snapshot' in item:
        return _fx_particle_emission_host().write(item, roles, pack)
    if 'geometry_snapshot' in item:
        return _fx_geometry_host().write({**item, 'native_write': item['geometry_native_write']}, roles, pack)
    if 'particle_size_snapshot' in item:
        return _fx_particle_size_host().write(item, roles, pack)
    if 'rbd_velocity_snapshot' in item:
        return _fx_rbd_velocity_host().write(item, roles, pack)
    if 'pyro_height_candidate' in item:
        observed = _fx_pyro_height_host().write(item['pyro_height_candidate'], roles, pack)
        return {'after': observed['registration']['program'], 'readback_verified': True,
                'evidence_scope': observed['evidence_scope'], 'native_program_readback': observed}
    if 'swarm_snapshot' in item:
        return _fx_swarm_host().write(item, roles, pack)
    if 'activation_snapshot' in item:
        return _fx_set_rbd_activation_verified(item, roles, pack)
    return _set_parm_verified(item['parm'], item['value'])


def _fx_restore_planned_item(item, roles, pack):
    if 'particle_emission_snapshot' in item:
        _fx_particle_emission_host().restore(item, roles, pack)
        return
    if 'geometry_snapshot' in item:
        try:
            _fx_geometry_host().restore({**item, 'native_write': item['geometry_native_write']}, roles, pack)
        finally:
            _fx_geometry_host().release(item)
        return
    if 'particle_size_snapshot' in item:
        _fx_particle_size_host().restore(item)
        return
    if 'rbd_velocity_snapshot' in item:
        _fx_rbd_velocity_host().restore_parameters(item)
        return
    if 'pyro_height_candidate' in item:
        _fx_pyro_height_host().restore(item['pyro_height_candidate']['snapshot'], roles, pack)
        _fx_pyro_height_host().release_snapshot(item['pyro_height_candidate']['snapshot'])
        return
    _restore_parm_snapshot(item['parm'], item['snapshot'])
    if 'activation_snapshot' in item:
        _fx_restore_rbd_activation_snapshot(item)
    if 'swarm_snapshot' in item:
        _fx_swarm_host().restore(item)


def _fx_release_planned_items(items):
    for item in items:
        if 'particle_emission_snapshot' in item:
            _fx_particle_emission_host().release(item)
        if 'geometry_snapshot' in item:
            _fx_geometry_host().release(item)
        if 'pyro_height_candidate' in item:
            _fx_pyro_height_host().release_snapshot(item['pyro_height_candidate']['snapshot'])


def _fx_rollback_planned_items(applied, prepared, roles, pack):
    errors = []
    for item in reversed(applied):
        try:
            _fx_restore_planned_item(item, roles, pack)
        except Exception as error:
            errors.append('{}:{}'.format(item['name'], getattr(error, 'code', type(error).__name__)))
    attempted = {id(item) for item in applied}
    _fx_release_planned_items([item for item in prepared if id(item) not in attempted])
    return errors


@contextmanager
def _fx_candidate_undo(prepared, applied, roles, pack):
    entered = False
    body_finished = False
    try:
        with _undo('Bridge FX apply bounded candidate'):
            entered = True
            yield
            body_finished = True
    except Exception as error:
        if not entered or body_finished:
            errors = _fx_rollback_planned_items(applied, prepared, roles, pack)
            if errors:
                raise BridgeCommandError('CANDIDATE_ROLLBACK_FAILED', ', '.join(errors)) from error
        raise


def _fx_planned_observations(changes, roles, pack, writes=()):
    import hou
    fields = {(w['role'], w['parm']) for w in writes}
    for name in changes:
        c = pack['controls'][name]
        fields.update((c['role'], p) for p in c['aliases'] if '#' not in p)
        fields.update(tuple(p) for p in c.get('targets', ()))
        fields.update((r, p) for r, p, _ in c.get('required_gates', ()))
        fields.update(tuple(p) for p in c.get('context_parms', ()))
        multiplier = c.get('native_multiplier_parm') or c.get('multiplier_parm')
        if multiplier:
            fields.add((c['role'], multiplier))
    for w in writes:
        fields.update((r, p) for r, p, _ in w.get('required_gates', ()))
        fields.update((g['role'], g['parm']) for g in w.get('frozen_readback_guards', ()))
    if pack.get('native_domain_id')=='swarm_flocking_v1' and ('seek','goal') in fields:
        goal=_fx_planned_observation(hou.node(roles['seek']),'goal')
        if goal.get('driven') or hou.node(roles['seek']).userData('bridge_swarm_goal_channels_v1'):
            fields.update({('seek','@swarm_basis'),('seek','@swarm_channels')})
    result = {}
    if pack.get('native_domain_id') == 'pyro_fire_v1' and 'flame_height' in changes:
        result['flame_height', '@height_context'] = _fx_pyro_height_host().context(roles, pack)
    if pack.get('native_domain_id') == 'particles_v1' and (
            'size_variance' in changes or any('particle_size_plan' in write for write in writes)
            or 'size' in changes and hou.node(roles['particle_size']).userData('bridge_particle_size_basis_v1') is not None):
        result.update(_fx_particle_size_host().observations(roles, pack))
    if pack.get('native_domain_id') == 'particles_v1' and (
            'emission_variance' in changes or any(write.get('value_kind') == 'trusted_particle_emission_expression' for write in writes)
            or 'birth_rate' in changes and _fx_particle_emission_host().registered(roles, pack)):
        result.update(_fx_particle_emission_host().observations(roles, pack))
    if pack.get('native_domain_id') == 'rbd_destruction_v1':
        result.update(_fx_rbd_velocity_host().observations(changes, roles, pack, writes))
    for role, field in sorted(fields):
        if (role, field) in result:
            continue
        if field.startswith('@'):
            if field == '@crowd_transition':
                from houdini_bridge.native_crowd_transition_contract import candidate_write_plan
                try:
                    context=_fx_crowd_transition_context(roles,pack)
                    current=next(p.value for p in context.parameters if p.role=='transition' and p.name=='duration')
                    result[role,field]={'origin':'runtime_hom','context':context,'frozen_guard_sha256':candidate_write_plan(context,current).frozen_guard_sha256}
                except ValueError as exc:raise BridgeCommandError(getattr(exc,'code','NATIVE_PLAN_INVALID'),str(exc)) from exc
                continue
            if field == '@crowd_route':
                from houdini_bridge.native_crowd_route_contract import candidate_write_plan
                try:
                    context = _fx_crowd_route_context(roles,pack)
                    current = next(p.value for p in context.parameters if p.role=='route' and p.name=='weight')
                    result[role,field] = {'origin':'runtime_hom','context':context,
                        'frozen_guard_sha256':candidate_write_plan(context,current).frozen_guard_sha256}
                except ValueError as exc:
                    raise BridgeCommandError(getattr(exc,'code','NATIVE_PLAN_INVALID'),str(exc)) from exc
                continue
            if field.startswith('@ocean_'):
                context=_fx_ocean_program_context(roles,pack,include_masked=field=='@ocean_geometry')
                result[role,field]=context[{'@ocean_source':'source','@ocean_surface':'surface',
                    '@ocean_spectrum':'spectrum','@ocean_emit':'native_emit','@ocean_stage':'mask_stage',
                    '@ocean_geometry':'masked_geometry'}[field]]
                continue
            if field.startswith('@cloth_'):
                context = _fx_cloth_program_context(roles,pack)
                result[role,field] = context[{'@cloth_source':'source','@cloth_thickness':'thickness',
                    '@cloth_stage':'shape_stage','@cloth_geometry':'shaped_geometry'}[field]]
                continue
            if field in ('@swarm_basis','@swarm_channels') and role=='seek':
                result[role,field]=getattr(_fx_swarm_host(),'basis' if field=='@swarm_basis' else 'channels')(roles,pack)
                continue
            if role == 'geometry_deform' and field in ('@geometry_context', '@geometry_parameters'):
                actual = _fx_geometry_observations(roles, pack)
                result[role,field] = actual['context' if field == '@geometry_context' else 'parameters']
                continue
            if field=='@activation_channel' and role=='configure':
                result[role,field]=_fx_rbd_activation_channel(roles,pack)
                continue
            if field.startswith('@multiparm/'):
                module, _ = _fx_planned_module(pack)
                parent = field.split('/',1)[1]
                patterns = module._IMPACT_TEMPLATES if parent == 'breaks' else module._LENGTH_TEMPLATES if parent == 'operations' else module._IMPORT_TEMPLATES if parent == 'fields' else module._ACTIVE_TEMPLATES if parent=='attributes' else ()
                fact = _fx_planned_multiparm_observation(hou.node(roles[role]),parent,patterns)
                result[role,field] = fact
                for name in fact['bindings'].values():
                    result[role,name] = _fx_planned_observation(hou.node(roles[role]),name)
                continue
            if field == '@trusted_axis':
                raw = json.loads(hou.node(roles[role]).userData('bridge_native_axis_v1') or '{}')
                if (raw.get('schema') != 'bridge.native-domain-axis/1' or
                        raw.get('domain') != pack['native_domain_id'] or raw.get('role') != role):
                    raise BridgeCommandError('ACTUAL_TRUSTED_UNIT_AXIS_REQUIRED',role)
                result[role,field] = {'origin':'trusted_host_runtime','value':raw.get('value')}
                continue
            if field == '@collision_radius_convention' and role == 'constraints':
                _fx_planned_owned_root(roles,pack)
                result[role,field] = {'origin':'runtime_hom','contract':'pscale_is_collision_radius',
                    'verified_from':'actual_point_pscale_and_documented_native_radius',
                    'documentation_sha256':'64f9bf4f360eb3d9f202c2174b8dd1962c70ef31debfda6108528966235a0a25'}
                continue
            if field == '@actual_clip' and role == 'agent_definition':
                result[role,field] = _fx_crowd_clip_fact(roles[role])
                continue
            if field == '@node' or field.startswith('@input/'):
                root_path = _fx_planned_owned_root(roles,pack)
                node = hou.node(roles[role])
                if field == '@node':
                    result[role,field] = {'origin':'runtime_hom','task_owned':True,'task_root':root_path,
                        'task_id':_root_lease_check(root_path,scope='sop',renew=False)['task_id'],
                        'native_version':hou.applicationVersionString(),
                        'path':node.path(),'type':node.type().name(),'category':node.type().category().name().lower(),
                        'context_parent_path':node.parent().path()}
                else:
                    index = int(field.split('/')[1])
                    connections = [c for c in node.inputConnections() if c.inputIndex() == index]
                    if len(connections) != 1 or connections[0].inputNode().path() not in roles.values():
                        raise BridgeCommandError('ACTUAL_NATIVE_CONNECTION_REQUIRED',role+'/'+field)
                    connection = connections[0];source = connection.inputNode()
                    result[role,field] = {'origin':'runtime_hom','task_owned':True,
                        'source_path':source.path(),'source_type':source.type().name(),
                        'source_role':next(r for r,p in roles.items() if p==source.path()),
                        'source_output':connection.outputIndex(),'destination_input':index}
                continue
            if field.startswith('@geometry/') or field.startswith('@input_geometry/'):
                _fx_planned_owned_root(roles,pack)
                index = int(field.split('/')[1])
                result[role,field] = _fx_planned_geometry_fact(hou.node(roles[role]),
                    **({'input_index':index} if field.startswith('@input_geometry/') else {'output_index':index}))
                continue
            raise BridgeCommandError('ACTUAL_NATIVE_CONTEXT_REQUIRED', 'native domain observation is missing: ' + role + '/' + field)
        node = hou.node(roles.get(role, ''))
        result[role, field] = _fx_planned_observation(node, field)
    return result


def _fx_planned_write_plan(pack, changes, observations):
    module, args = _fx_planned_module(pack)
    try:
        if module.SCHEMA == 'bridge.native-pyro-domains/1':
            return module.candidate_write_plan(args[0], changes, args[1],
                height_context=observations.get(('flame_height', '@height_context')))
        return module.candidate_write_plan(args[0], changes, *args[1:], observations=observations)
    except ValueError as exc:
        raise BridgeCommandError(getattr(exc, 'code', 'NATIVE_PLAN_INVALID'), str(exc)) from exc


def _fx_rbd_activation_channel(roles,pack):
    import hou
    module,_=_fx_planned_module(pack)
    root=_fx_planned_owned_root(roles,pack)
    lease=_root_lease_check(root,scope='sop',renew=False)
    node=hou.node(roles['configure'])
    names=_fx_planned_multiparm_observation(node,'attributes',module._ACTIVE_TEMPLATES)['bindings']
    name=names['active#'];parm=node.parm(name)
    actual=_fx_planned_observation(node,name)
    if actual['type']!='integer' or actual['size']!=1:
        raise BridgeCommandError('ACTUAL_OWNED_ACTIVE_CHANNEL_REQUIRED','native active compiled integer required')
    binding={'task_id':lease['task_id'],'task_root':root,'node_path':node.path(),'node_type':node.type().name(),
        'category':node.type().category().name().lower(),'parm':name,'template':'active#','type':actual['type'],'size':actual['size']}
    identity=_host_identity()
    if identity.get('task_id')!=lease['task_id']:
        raise BridgeCommandError('ACTUAL_OWNED_ACTIVE_CHANNEL_REQUIRED','authenticated current task host identity required')
    def integer(value):
        if type(value) not in (int,float) or not math.isfinite(value) or int(value)!=value:
            raise BridgeCommandError('UNTRUSTED_ACTIVE_CHANNEL','native channel contains noninteger frame/value')
        return int(value)
    keys=tuple(parm.keyframes());normalized=[]
    for key in keys:
        try:expression=key.expression();language=str(key.expressionLanguage()).rsplit('.',1)[-1]
        except Exception:expression=language=None
        normalized.append({'frame':integer(key.frame()),'value':integer(key.value()),'expression':expression,'language':language})
    driver=_component_driver_identity(parm)
    raw=node.userData('bridge_rbd_active_step_v1');registration=json.loads(raw) if raw else None
    samples=[]
    if registration is not None:
        frame=integer(registration.get('activation_frame'))
        try:
            samples=[{'frame':f,'value':integer(parm.evalAtFrame(f))} for f in (frame-2,frame-1,frame,frame+1)]
        except Exception as exc:
            raise BridgeCommandError('ACTUAL_OWNED_ACTIVE_CHANNEL_REQUIRED','native activation channel could not be evaluated') from exc
    return {'origin':'runtime_hom','schema':'bridge.rbd-active-channel-observation/1','native_version':hou.applicationVersionString(),
        'task_owned':True,'binding':binding,'identity':identity,'current_frame':hou.frame(),**driver,
        'mode':'bridge_constant_step' if registration is not None else 'undriven','keyframes':normalized,
        'keyframe_identities':[_keyframe_identity(key) for key in keys],'samples':samples,
        'pre_extrapolation':str(parm.keyframeExtrapolation(True)).rsplit('.',1)[-1].lower(),
        'post_extrapolation':str(parm.keyframeExtrapolation(False)).rsplit('.',1)[-1].lower(),'registration':registration}


def _fx_rbd_activation_output_readback(roles,pack):
    import hou
    channel=_fx_rbd_activation_channel(roles,pack)
    frame=channel['registration']['activation_frame'];original=hou.frame();samples=[]
    try:
        for f in (frame-2,frame-1,frame,frame+1):
            hou.setFrame(f);geometry=_fx_planned_geometry_fact(hou.node(roles['configure']),output_index=0)
            values=geometry['primitive_attribute_values'].get('active')
            if (geometry['primitive_attributes'].get('active')!={'type':'int','size':1} or not values or
                len(values)!=geometry['primitives'] or any(type(v) is not int or v!=int(f>=frame) for v in values)):
                raise BridgeCommandError('ACTIVE_CHANNEL_READBACK_MISMATCH','actual configure output active differs')
            samples.append({'frame':f,'active_values':values,'actual_geometry':geometry})
    finally:hou.setFrame(original)
    return {'frame':hou.frame(),'time':hou.time(),'activation_channel':channel,'configure_output_samples':samples,
        'solver_gates':{n:_fx_planned_observation(hou.node(roles['solver']),n) for n in ('overwritefromsop','overwriteattributes','minactivationimpulseoverride','startframe')}}


def _fx_set_rbd_activation_verified(item,roles,pack):
    import hou
    write=item['native_write'];module,_=_fx_planned_module(pack)
    observations=_fx_planned_observations({'activation_frame':write['value']},roles,pack,[write])
    module.validate_control_write_plan([write],observations)
    channel=observations['configure','@activation_channel'];parm=item['parm']
    result=_fx_set_solver_activation_verified(parm,item['snapshot'],write['schedule'],hou,
        owned_identities=channel['keyframe_identities'] if channel['mode']=='bridge_constant_step' else None)
    component=parm._components()[0]
    for before in (True,False):component.setKeyframeExtrapolation(before,hou.parmExtrapolate.Constant)
    identities=[_keyframe_identity(k) for k in component.keyframes()]
    registration={'schema':'bridge.rbd-active-step/1','native_version':write['native_version'],'binding':channel['binding'],
        'activation_frame':write['value'],'keyframe_identities':identities}
    registration['content_sha256']=hashlib.sha256(json.dumps(registration,sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()
    item['node'].setUserData('bridge_rbd_active_step_v1',json.dumps(registration,sort_keys=True))
    current=_fx_rbd_activation_channel(roles,pack)
    if current['registration']!=registration:
        raise BridgeCommandError('ACTIVE_CHANNEL_READBACK_MISMATCH','native registration write differs')
    result['after']=write['value'];result['native_channel_readback']=current
    return result


def _fx_restore_rbd_activation_snapshot(item):
    component=item['parm']._components()[0];extra=item['activation_snapshot']
    for before,value in ((True,extra['pre']),(False,extra['post'])):component.setKeyframeExtrapolation(before,value)
    if extra['registration'] is None:item['node'].destroyUserData('bridge_rbd_active_step_v1')
    else:item['node'].setUserData('bridge_rbd_active_step_v1',extra['registration'])
    if (component.keyframeExtrapolation(True)!=extra['pre'] or component.keyframeExtrapolation(False)!=extra['post'] or
        item['node'].userData('bridge_rbd_active_step_v1')!=extra['registration'] or
        ('bridge_rbd_active_step_v1' in item['node'].userDataDict())!=(extra['registration'] is not None)):
        raise BridgeCommandError('PARAMETER_RESTORE_MISMATCH','native activation extrapolation/registration rollback differs')


def _fx_planned_domain_prepared(pack_id, changes, roles, pack):
    import hou
    module, args = _fx_planned_module(pack)
    # Observe immutable exponent/context fields before deriving any native value.
    try:
        observations = _fx_planned_observations(changes, roles, pack)
        writes = _fx_planned_write_plan(pack, changes, observations)
        observations = _fx_planned_observations(changes, roles, pack, writes)
        module.validate_control_write_plan(writes, observations)
        if hasattr(module, 'semantic_write_map') and any(
                write.get('value_kind') in {'trusted_particle_size_program', 'trusted_particle_emission_expression'} for write in writes):
            by_key = module.semantic_write_map(writes, changes)
        else:
            by_key = {}
            for name, value in changes.items():
                for w in _fx_planned_write_plan(pack, {name: value}, observations):
                    by_key.setdefault((w['role'], w['parm']), []).append(name)
        prepared = []
        for w in writes:
            node = hou.node(roles[w['role']]); parm = _resolve_parm_target(node, [w['parm']])
            names = by_key[w['role'], w['parm']]
            prepared.append({'name': names[0], 'semantic_names': names, 'node': node, 'parm': parm,
                'snapshot': _snapshot_parm_state(parm), 'value': w['value'], 'primary': False,
                'native_target': {'multiplier': 1.0}, 'native_write': w,
                'invalidates_from': w['invalidates_from']})
        for item in prepared:
            if item['native_write'].get('value_kind') == 'trusted_geometry_deform_program':
                handle = _fx_geometry_host().prepare(item['native_write']['geometry_deform_plan'], roles, pack)
                item.update({key: value for key, value in handle.items() if key != 'native_write'})
                item['geometry_native_write'] = handle['native_write']
            if item['native_write'].get('value_kind') == 'trusted_particle_size_program':
                _fx_particle_size_host().prepare(item)
            if item['native_write'].get('value_kind') == 'trusted_particle_emission_expression':
                _fx_particle_emission_host().prepare(item, roles, pack)
            if item['native_write'].get('value_kind') == 'trusted_rbd_velocity_program':
                _fx_rbd_velocity_host().prepare(item)
            if item['node'].path() == roles.get('flame_height') and 'flame_height' in changes:
                item['pyro_height_candidate'] = _fx_pyro_height_host().plan(changes['flame_height'], roles, pack)
            if item['native_write'].get('value_kind')=='trusted_swarm_goal_channels':
                _fx_swarm_host().prepare(item)
            if item['native_write'].get('value_kind')=='trusted_constant_activation_channel':
                component=item['parm']._components()[0]
                item['activation_snapshot']={'pre':component.keyframeExtrapolation(True),'post':component.keyframeExtrapolation(False),
                    'registration':item['node'].userData('bridge_rbd_active_step_v1')}
        return prepared
    except Exception as exc:
        _fx_release_planned_items(locals().get('prepared', ()))
        raise BridgeCommandError(getattr(exc, 'code', 'NATIVE_PLAN_INVALID'), str(exc)) from exc


def _fx_planned_domain_readback(pack_id, changes, roles, pack, frozen_writes=None):
    module, args = _fx_planned_module(pack)
    observations = _fx_planned_observations(changes, roles, pack)
    writes = frozen_writes if frozen_writes is not None else _fx_planned_write_plan(pack, changes, observations)
    observations = _fx_planned_observations(changes, roles, pack, writes)
    values = {key: fact['value'] for key, fact in observations.items() if 'value' in fact}
    try:
        if hasattr(module, 'validate_readback_guards'):
            if module.SCHEMA in {'bridge.native-vellum-domains/1', 'bridge.native-flip-rbd-domains/1','bridge.native-particle-ocean-geometry-domains/1'}:
                module.validate_readback_guards(writes, observations, after_mutation=True)
            else:
                module.validate_readback_guards(writes, observations)
        if any(write.get('value_kind') in {'trusted_particle_size_program', 'trusted_rbd_velocity_program', 'trusted_particle_emission_expression'} for write in writes):
            module.validate_applied_readback(writes, observations)
        readback = getattr(module,'control_readback',None) or getattr(module,'native_control_value')
        return {name: _json_safe(_fx_pyro_height_host().readback(roles, pack)['value']
                    if module.SCHEMA == 'bridge.native-pyro-domains/1' and name == 'flame_height'
                    else readback(args[0], name, values, *args[1:],
                    **({} if module.SCHEMA == 'bridge.native-pyro-domains/1' else {'observations': observations})))
                for name in changes}
    except ValueError as exc:
        raise BridgeCommandError(getattr(exc, 'code', 'NATIVE_PLAN_INVALID'), str(exc)) from exc


def _fx_shared_render_pack(params, roles, pack):
    import hou
    from houdini_bridge.native_render_domains import LIGHTING, overlay_host_pack
    render_pack = overlay_host_pack(LIGHTING, _FX_PACKS[LIGHTING], hou.applicationVersionString())
    render_roles = {r['role']: roles['render_settings'] if r['role'] == 'settings' else
                    roles['output'] if r['role'] == 'source' else roles[r['role']]
                    for r in render_pack['nodes']}
    terminal = hou.node(roles['output'])
    for requirement in render_pack['nodes']:
        if requirement['role'] == 'source':
            requirement['types'] = [terminal.type().name()]
    return render_pack, render_roles


def _fx_set_fresh_native_verified(parm, value):
    # The caller proves this exact node was just created under its lease.
    # Its failure rollback destroys the new node, so an unknown factory default
    # is never replaced by a fabricated evaluated-value snapshot.
    for component in parm._components():
        component.deleteAllKeyframes()
    parm.set(value, follow_references=False)
    actual = _read_parm_for_request(parm, value)
    if not _values_match(value, actual):
        raise BridgeCommandError('PARAMETER_READBACK_MISMATCH', 'fresh recipe did not read back: ' + parm.path())
    return {'parameter':parm.name(),'parameter_path':parm.path(),'requested':_json_safe(value),
            'after':_json_safe(actual),'before':None,'readback_verified':True,
            'initialization':'fresh_owned_node_recipe','rollback':'destroy_new_node'}


def _fx_apply_fresh_domain_plan(plan, roles, fresh_roles):
    import hou
    result = {}
    for write in plan:
        node = hou.node(roles[write['role']]); parm = _resolve_parm_target(node,[write['parm']])
        if parm is None:
            raise BridgeCommandError('NATIVE_CONTROL_INTERFACE_REQUIRED',write['role']+'/'+write['parm'])
        fresh = write['role'] in fresh_roles
        actual = _fx_planned_observation(node,write['parm'],observe_value=not fresh)
        if actual['type'] != write['native_type'] or actual['size'] != write.get('size',1):
            raise BridgeCommandError('NATIVE_CONTROL_INTERFACE_REQUIRED','native initialization type differs: '+parm.path())
        if actual['hidden'] or actual['disabled'] or actual['locked']:
            raise BridgeCommandError('NATIVE_CONTROL_GATE_BLOCKED','native initialization is blocked: '+parm.path())
        if write.get('value_kind') == 'fixed_vendor_hscript':
            if (write.get('trusted_expression_id') != 'vendor_crowd_initial_frame_population/1' or
                    write['role'] != 'population' or write['parm'] != 'impulseactiveate' or
                    write['value'] != '$SF==1' or actual['type'] != 'float' or actual['size'] != 1):
                raise BridgeCommandError('UNTRUSTED_NATIVE_EXPRESSION','unsupported fixed expression')
            language = hou.exprLanguage.Hscript
            if fresh:
                parm.deleteAllKeyframes()
                parm.setExpression(write['value'],language=language)
            if parm.expression() != write['value'] or parm.expressionLanguage() != language:
                raise BridgeCommandError('PARAMETER_READBACK_MISMATCH','fixed population channel differs')
            result[write['role']+'.'+write['parm']] = {'parameter_path':parm.path(),
                'expression':parm.expression(),'language':str(parm.expressionLanguage()),
                'readback_verified':True,'initialization':'fresh_owned_node_recipe'}
            continue
        if not fresh:
            if actual['driven'] or not _values_match(write['value'],actual['value']):
                raise BridgeCommandError('SCENE_STATE_MISMATCH','existing owned recipe differs: '+parm.path())
            continue
        result[write['role']+'.'+write['parm']] = _fx_set_fresh_native_verified(parm,write['value'])
    return result


def _fx_guide_root_fact(path):
    import hou
    geometry = hou.node(path).geometry()
    points = tuple(geometry.points()); curves = []
    positions = {p.number():list(p.position()) for p in points}
    for prim in geometry.prims():
        if prim.type().name() not in {'Polygon','BezierCurve','NURBSCurve'} or prim.isClosed():
            raise BridgeCommandError('ACTUAL_NONEMPTY_GUIDE_CURVES_REQUIRED','guide output is not an open curve')
        curves.append({'kind':'open_curve','closed':False,
            'point_numbers':[v.point().number() for v in prim.vertices()]})
    payload = {'positions':positions,'curves':curves}
    return {'origin':'runtime_hom','role':'hair_clump','output':0,'point_count':len(points),
        'curves':curves,'geometry_sha256':hashlib.sha256(json.dumps(payload,sort_keys=True,allow_nan=False,separators=(',',':')).encode()).hexdigest()}


def _fx_initialize_hair_domain(params, roles, pack, fresh_roles):
    import hou
    module, args = _fx_planned_module(pack)
    try:
        result = _fx_apply_fresh_domain_plan(module.multiparm_allocation_plan(*args,fresh=True),roles,fresh_roles)
        fact = _fx_planned_multiparm_observation(hou.node(roles['guide_length']),'operations',module._LENGTH_TEMPLATES)
        observations = {('guide_length','@multiparm/operations'):fact}
        observations.update({('guide_length',name):{'origin':'runtime_hom'} for name in fact['bindings'].values()})
        result.update(_fx_apply_fresh_domain_plan(module.trusted_initialization_plan(*args,
            fresh=True,observations=observations,stage='source'),roles,fresh_roles))
        root_fact = _fx_guide_root_fact(roles['hair_clump'])
        root_binding = module.root_binding_plan(root_fact)
        result.update(_fx_apply_fresh_domain_plan(module.trusted_initialization_plan(*args,
            fresh=True,observations=observations,root_fact=root_fact,stage='simulation'),roles,fresh_roles))
        solver = hou.node(roles['solver'])
        axis = {'schema':'bridge.native-domain-axis/1','domain':args[0],'role':'solver','value':[0.,1.,0.]}
        if 'solver' in fresh_roles:
            solver.setUserData('bridge_native_axis_v1',json.dumps(axis,sort_keys=True))
        elif json.loads(solver.userData('bridge_native_axis_v1') or '{}') != axis:
            raise BridgeCommandError('SCENE_STATE_MISMATCH','owned wind axis differs')
        result['root_binding'] = root_binding
        render_pack,render_roles = _fx_shared_render_pack(params,roles,pack)
        render_fresh = {r for r in render_roles if (r=='settings' and 'render_settings' in fresh_roles) or
            (r=='source' and 'output' in fresh_roles) or r in fresh_roles}
        result['shared_render'] = _fx_initialize_render_domain(params,'lighting_camera_render_v1',render_roles,render_pack,render_fresh)
        return result
    except Exception:
        for role in sorted(fresh_roles,key=lambda r:roles[r].count('/'),reverse=True):
            node = hou.node(roles[role])
            if node is not None:node.destroy()
        raise


def _fx_crowd_native_identity(roles, pack):
    from houdini_bridge.native_crowd_route_contract import HostIdentity
    root_path = _fx_planned_owned_root(roles,pack)
    lease = _root_lease_check(root_path,scope='sop',renew=False)
    actual = _host_identity()
    return HostIdentity(str(lease['task_id']),root_path,_fx_pack_contract_sha256(pack),
        actual['session_id'],actual['process_generation'],actual['scene_epoch'])


def _fx_crowd_node_fact(role, path, identity):
    import hou
    from houdini_bridge.native_crowd_route_contract import NodeFact
    node = hou.node(path)
    typ = node.type()
    return NodeFact(role,node.path(),node.parent().path(),typ.category().name(),typ.name(),
        str(node.sessionId()),identity,typ.maxNumInputs(),typ.maxNumOutputs(),node.isEditable(),
        hou.applicationVersionString())


def _fx_crowd_parm_fact(role, name, path, identity, *, geometry_digest=None):
    from houdini_bridge.native_crowd_route_contract import ParmFact,MenuFact
    import hou
    node = hou.node(path)
    parm = node.parm(name)
    if parm is None:
        raise BridgeCommandError('NATIVE_CONTROL_INTERFACE_REQUIRED',role+'/'+name)
    template = parm.parmTemplate()
    if str(template.type()).rsplit('.',1)[-1]=='Ramp':
        from houdini_bridge.native_crowd_transition_contract import RampFact
        ramp=parm.evalAsRamp()
        value=RampFact(tuple(str(b).rsplit('.',1)[-1] for b in ramp.basis()),tuple(ramp.keys()),tuple(ramp.values()),ramp.isColor(),'runtime_hom')
        writable=not any((parm.isHidden(),parm.isDisabled(),parm.isLocked())) and template.isHidden() is False
        driven=any(_component_driver_identity(parm).values()) or bool(parm.keyframes())
        return ParmFact(role,name,'ramp_float','ramp_flt',template.numComponents(),value,writable,driven,'ramp_float',writable,node.path(),identity)
    actual = _fx_planned_observation(node,name,observe_value=geometry_digest is None)
    template = parm.parmTemplate()
    kind = str(template.type()).rsplit('.',1)[-1]
    native,ui = {'Float':('float','float'),'Int':('int','integer'),
        'Toggle':('int','toggle'),'String':('string','string'),'Menu':('int','ordinal'),
        'Data':('data','data')}.get(kind,(None,None))
    if kind == 'String' and str(template.stringType()).rsplit('.',1)[-1] == 'NodeReference':
        ui = 'oppath'
    menu = None
    if template.menuItems():
        tokens,labels = tuple(template.menuItems()),tuple(template.menuLabels())
        if len(tokens) != len(labels):
            raise BridgeCommandError('ACTUAL_MENU_BINDING_REQUIRED',role+'/'+name)
        storage = 'token' if template.menuUseToken() else 'index'
        menu = MenuFact(tuple(zip(tokens,labels)),storage)
        native = 'string' if storage == 'token' else 'int'
    value = geometry_digest if geometry_digest is not None else parm.eval()
    if native is None:
        raise BridgeCommandError('NATIVE_CONTROL_INTERFACE_REQUIRED',role+'/'+name)
    writable = not any(actual[k] for k in ('locked','disabled','hidden'))
    compiled_writable = writable and template.isHidden() is False
    return ParmFact(role,name,native,ui,actual['size'],value,writable,actual['driven'],
        native,compiled_writable,node.path(),identity,menu)


def _fx_crowd_route_curve_fact(node, identity, geometry):
    from houdini_bridge.native_crowd_route_contract import CurveFact,curve_geometry_sha256
    points,prims = tuple(geometry.points()),tuple(geometry.prims())
    if not 2 <= len(points) <= 8192 or len(prims) != 1:
        raise BridgeCommandError('ACTUAL_ROUTE_CURVE_REQUIRED','one bounded nonempty native primitive required')
    positions = tuple(tuple(float(v) for v in point.position()) for point in points)
    numbers = {point.number():i for i,point in enumerate(points)}
    prim = prims[0]
    vertices = tuple(numbers[v.point().number()] for v in prim.vertices())
    closed,kind = prim.isClosed(),prim.type().name()
    digest = curve_geometry_sha256(positions,vertices,closed,kind)
    return CurveFact(node.path(),0,positions,vertices,closed,kind,digest,identity,len(prims))


def _fx_crowd_route_context(roles, pack):
    import hou
    from houdini_bridge.native_crowd_route_contract import RouteContext,WireBinding
    identity = _fx_crowd_native_identity(roles,pack)
    root,sop,dop = identity.resource_id,roles['geometry_network'],roles['dop_network']
    mapping = {'route':'route','solver':'solver','state_stream':'states','route_curve':'route_curve'}
    nodes = tuple(_fx_crowd_node_fact(alias,roles[role],identity) for alias,role in mapping.items())
    parents = tuple(_fx_crowd_node_fact(alias,path,identity) for alias,path in
        (('task_root',root),('sop_root',sop),('dop_root',dop)))
    curve_node = hou.node(roles['route_curve'])
    curve = _fx_crowd_route_curve_fact(curve_node,identity,curve_node.geometry(output_index=0))
    stored = _fx_crowd_route_curve_fact(curve_node,identity,curve_node.parm('stash').evalAsGeometry())
    if stored != curve:
        raise BridgeCommandError('ACTUAL_ROUTE_GEOMETRY_DIGEST_REQUIRED','native stash and output differ')
    marker = json.loads(curve_node.userData('bridge_native_route_recipe_v1') or '{}')
    if marker != {'schema':'bridge.native-route-stash/1','domain':'crowd_agents_v1',
        'role':'route_curve','geometry_sha256':curve.geometry_sha256}:
        raise BridgeCommandError('ACTUAL_ROUTE_GEOMETRY_DIGEST_REQUIRED','saved route curve recipe differs')
    parms = tuple(_fx_crowd_parm_fact('route',name,roles['route'],identity) for name in
        ('weight','activate','uselocalforce','soppath','output','pathsource','method')) + (
        _fx_crowd_parm_fact('route_curve','stash',curve_node.path(),identity,geometry_digest=stored.geometry_sha256),)
    inverse = {roles[role]:alias for alias,role in mapping.items()}
    wires = []
    for target in ('route','solver'):
        for connection in hou.node(roles[target]).inputConnections():
            if target == 'solver' and connection.inputIndex() != 2:
                continue
            source = inverse.get(connection.inputNode().path())
            if source is None:
                raise BridgeCommandError('ACTUAL_STATE_STREAM_BINDING_REQUIRED','foreign route consumer input')
            wires.append(WireBinding(source,connection.outputIndex(),target,connection.inputIndex()))
    return RouteContext(hou.applicationVersionString(),identity,root,sop,dop,nodes,parms,curve,tuple(wires),parents)


def _fx_initialize_crowd_route(roles, pack, fresh_roles):
    import hou
    from dataclasses import asdict
    from houdini_bridge.native_crowd_route_contract import fixed_curve_geometry_plan,init_write_plan,validate_context,validate_readback
    if {'route','route_curve'} <= fresh_roles:
        node = hou.node(roles['route_curve'])
        actual = _fx_planned_observation(node,'stash',observe_value=False)
        if actual['type'] != 'data' or actual['size'] != 1 or actual['driven'] or any(actual[k] for k in ('hidden','disabled','locked')):
            raise BridgeCommandError('COMPILED_WRITABLE_GATE_REQUIRED','actual route geometry stash')
        objects = {}
        for operation in fixed_curve_geometry_plan(hou.applicationVersionString())['operations']:
            call = operation['call']
            if call == 'hou.Geometry':objects[operation['result']] = hou.Geometry()
            elif call == 'Geometry.createPolygon':objects[operation['result']] = objects[operation['receiver']].createPolygon(**operation['kwargs'])
            elif call == 'Geometry.createPoint':objects[operation['result']] = objects[operation['receiver']].createPoint()
            elif call == 'Point.setPosition':objects[operation['receiver']].setPosition(*operation['args'])
            elif call == 'Face.addVertex':objects[operation['receiver']].addVertex(objects[operation['args'][0]['object_ref']])
            elif call == 'Parm.set' and operation['role']=='route_curve' and operation['parm']=='stash':
                node.parm('stash').set(objects[operation['args'][0]['object_ref']])
            else:raise BridgeCommandError('UNTRUSTED_NATIVE_GEOMETRY_OPERATION',call)
        curve = _fx_crowd_route_curve_fact(node,None,node.geometry(output_index=0))
        node.setUserData('bridge_native_route_recipe_v1',json.dumps({'schema':'bridge.native-route-stash/1',
            'domain':'crowd_agents_v1','role':'route_curve','geometry_sha256':curve.geometry_sha256},sort_keys=True))
        # The compiler has built the desired graph; collect the real uninstalled
        # baseline before asking the pure helper for its initialization plan.
        hou.node(roles['route']).setInput(0,None)
        hou.node(roles['solver']).setInput(2,hou.node(roles['states']),0)
        # The vendor default is POP force, which hides steering weight. Open
        # the exact observed Crowds menu gate on this fresh node first.
        from houdini_bridge.native_crowd_route_contract import _menu_value
        identity = _fx_crowd_native_identity(roles,pack)
        output_fact = _fx_crowd_parm_fact('route','output',roles['route'],identity)
        if output_fact.writable is not True or output_fact.compiled_writable is not True or output_fact.driven is not False:
            raise BridgeCommandError('COMPILED_WRITABLE_GATE_REQUIRED','route/output')
        _fx_set_fresh_native_verified(_resolve_parm_target(hou.node(roles['route']),['output']),
            _menu_value(output_fact,'0','Crowds steerforce'))
        context = _fx_crowd_route_context(roles,pack)
        plan = init_write_plan(context,route_weight=1.)
        for write in plan.writes:
            _fx_set_fresh_native_verified(_resolve_parm_target(hou.node(roles[write.role]),[write.parm]),write.value)
        aliases = {'state_stream':'states','route':'route','solver':'solver'}
        for wire in plan.connections:
            hou.node(roles[aliases[wire.target_role]]).setInput(wire.input_port,
                hou.node(roles[aliases[wire.source_role]]),wire.output_port)
        actual_context = _fx_crowd_route_context(roles,pack)
        result = validate_readback(plan,actual_context)
    elif not ({'route','route_curve'} & fresh_roles):
        actual_context = _fx_crowd_route_context(roles,pack)
        validate_context(actual_context,installed=True)
        result = {'route_weight':next(p.value for p in actual_context.parameters if p.role=='route' and p.name=='weight')}
    else:
        raise BridgeCommandError('SCENE_STATE_MISMATCH','partial existing route recipe')
    return dict(result,actual_native_context=asdict(actual_context),readback_verified=True)


def _fx_crowd_transition_context(roles,pack):
    import hou
    from houdini_bridge.native_crowd_transition_contract import TransitionContext,AgentGeometryFact,WireBinding
    from houdini_bridge.crowd_helpers import snapshot_agent_geometry
    identity=_fx_crowd_native_identity(roles,pack)
    root,sop,dop=identity.resource_id,roles['geometry_network'],roles['dop_network']
    mapping={r:r for r in ('agent_definition','source','population','target_state','trigger','transition','states','transitions','solver','wander','route')}
    mapping['source_state']='state'
    nodes=tuple(_fx_crowd_node_fact(a,roles[r],identity) for a,r in mapping.items())
    parents=tuple(_fx_crowd_node_fact(a,p,identity) for a,p in (('task_root',root),('sop_root',sop),('dop_root',dop)))
    fields={'transition':('duration','blend','instate','outstate','useclipgraph','randomstart','uselocal','useoutclip'),
        'source':('state',),'population':('soppath',),'trigger':('type','fuzzyoutput','statedurationcondition','stateduration','triggername'),
        'source_state':('statename','clipname','uselocal','clipassignment','rbdragdoll'),
        'target_state':('statename','clipname','uselocal','clipassignment','rbdragdoll')}
    parms=tuple(_fx_crowd_parm_fact(a,n,roles[mapping[a]],identity) for a,names in fields.items() for n in names)
    inverse={roles[r]:a for a,r in mapping.items()};wires=[]
    for target,r in mapping.items():
        for connection in hou.node(roles[r]).inputConnections():
            # source input1 is the population position geometry outside this
            # transition subgraph; input0 carries the checked agent definition.
            if target=='source' and connection.inputIndex()!=0:continue
            source=inverse.get(connection.inputNode().path())
            if source is None:raise BridgeCommandError('ACTUAL_TRANSITION_CONNECTIONS_REQUIRED','foreign transition subgraph edge')
            wires.append(WireBinding(source,connection.outputIndex(),target,connection.inputIndex()))
    merge=next(n for n in nodes if n.role=='transitions')
    existing=[w.input_port for w in wires if w.target_role=='transitions' and w.source_role=='transition']
    used={w.input_port for w in wires if w.target_role=='transitions'}
    free=next((i for i in range(merge.input_count) if i not in used),None)
    slot=existing[0] if len(existing)==1 else free
    snapshot=_fx_crowd_stash_snapshot(roles['agent_definition'])
    output=snapshot_agent_geometry(hou,hou.node(roles['agent_definition']).geometry(output_index=0))
    if snapshot['content_sha256']!=output['content_sha256'] or snapshot['native_payloads']!=output['native_payloads']:
        raise BridgeCommandError('ACTUAL_PACKED_AGENT_SOURCE_CHANGED','actual stash output and stored definition differ')
    geometry=AgentGeometryFact(roles['agent_definition'],0,identity,json.dumps(output,sort_keys=True),'runtime_hom')
    return TransitionContext(hou.applicationVersionString(),identity,root,sop,dop,parents,nodes,parms,geometry,tuple(wires),slot)


def _fx_initialize_crowd_transition(roles,pack,fresh_roles):
    import hou
    from dataclasses import asdict
    from houdini_bridge.native_crowd_transition_contract import init_write_plan,validate_context,validate_readback,_menu_value,RampSpec
    required={'target_state','trigger','transition'}
    if required<=fresh_roles:
        identity=_fx_crowd_native_identity(roles,pack)
        for role,name,token,label in (('target_state','clipassignment','single','Single Clip'),('target_state','rbdragdoll','ignore','Ignore'),('trigger','type','10','Current State Duration'),('trigger','statedurationcondition','2','Greater Than')):
            fact=_fx_crowd_parm_fact(role,name,roles[role],identity)
            if not fact.writable or not fact.compiled_writable or fact.driven:raise BridgeCommandError('TRANSITION_COMPILED_WRITABLE_GATE_REQUIRED',role+'/'+name)
            _fx_set_fresh_native_verified(_resolve_parm_target(hou.node(roles[role]),[name]),_menu_value(fact,token,label))
        for role,name,value in (('target_state','statename','w5_transition'),('target_state','clipname','w5_transition'),('target_state','uselocal',0),('trigger','fuzzyoutput',0),('trigger','stateduration',1.),('trigger','triggername','w5_duration')):
            _fx_set_fresh_native_verified(_resolve_parm_target(hou.node(roles[role]),[name]),value)
        actual_clips=_fx_crowd_stash_snapshot(roles['agent_definition'])['content']['agents'][0]['clips']
        target_clip=next(c for c in actual_clips if c['name']=='w5_transition')
        for name,value in (('cliptype','0'),('setinitialclipname',1),('setinitialcliptime',1),('randomizecliptime',0),('retimetoparticle',0),('enablelooping',1),('globalclipoffset',target_clip['start_time'])):
            _fx_set_fresh_native_verified(_resolve_parm_target(hou.node(roles['target_state']),[name]),value)
        ramp=hou.node(roles['transition']).parm('blend')
        if ramp is None or str(ramp.parmTemplate().type()).rsplit('.',1)[-1]!='Ramp' or any((ramp.isHidden(),ramp.isDisabled(),ramp.isLocked(),ramp.parmTemplate().isHidden())) or any(_component_driver_identity(ramp).values()) or ramp.keyframes():
            raise BridgeCommandError('TRANSITION_COMPILED_WRITABLE_GATE_REQUIRED','transition/blend')
        ramp.set(hou.Ramp((hou.rampBasis.Linear,hou.rampBasis.Linear),(0.,1.),(0.,1.)))
        hou.node(roles['transition']).setInput(0,None)
        hou.node(roles['transitions']).setInput(0,None)
        context=_fx_crowd_transition_context(roles,pack)
        plan=init_write_plan(context,animation_blend=1.)
        for write in plan.writes:
            parm=hou.node(roles[write.role]).parm(write.parm)
            if isinstance(write.value,RampSpec):parm.set(hou.Ramp(tuple(getattr(hou.rampBasis,b) for b in write.value.basis),write.value.keys,write.value.values))
            else:_fx_set_fresh_native_verified(_resolve_parm_target(hou.node(roles[write.role]),[write.parm]),write.value)
        aliases={'source_state':'state'}
        for wire in plan.connections:
            hou.node(roles[aliases.get(wire.target_role,wire.target_role)]).setInput(wire.input_port,hou.node(roles[aliases.get(wire.source_role,wire.source_role)]),wire.output_port)
        actual=_fx_crowd_transition_context(roles,pack)
        result=validate_readback(plan,actual)
    elif not required&fresh_roles:
        actual=_fx_crowd_transition_context(roles,pack);validate_context(actual,installed=True)
        result={'animation_blend':next(p.value for p in actual.parameters if p.role=='transition' and p.name=='duration')}
    else:raise BridgeCommandError('SCENE_STATE_MISMATCH','partial owned transition recipe')
    return dict(result,actual_native_context=asdict(actual),readback_verified=True)


def _fx_crowd_curve_stash_snapshot(node,task_id):
    from dataclasses import asdict
    import hou
    # This read is used before trusted reopen adopts the saved root lease.
    # The caller binds task/scene receipt; edits use the full leased context.
    parent=node.parent()
    while parent is not None and parent.path().startswith('/obj/'):
        manifest=json.loads(parent.userData('bridge_fx_manifest_v1') or '{}')
        if manifest:
            roles=manifest.get('nodes',{})
            sop=hou.node(roles.get('geometry_network',''))
            if (not task_id or manifest.get('task_id')!=str(task_id) or manifest.get('domain_pack')!='crowd_agents_v1' or
                parent.userData('bridge_fx_owned')!='1' or roles.get('route_curve')!=node.path() or
                node.type().name()!='stash' or node.type().category().name()!='Sop' or
                sop is None or sop.type().name()!='geo' or sop.type().category().name()!='Obj' or
                sop.parent().path()!=parent.path() or node.parent().path()!=sop.path()):
                raise BridgeCommandError('SCENE_OWNERSHIP_REQUIRED','route data differs from exact task-owned manifest role/layout')
            actual=_fx_crowd_route_curve_fact(node,None,node.geometry(output_index=0))
            stored=_fx_crowd_route_curve_fact(node,None,node.parm('stash').evalAsGeometry())
            marker=json.loads(node.userData('bridge_native_route_recipe_v1') or '{}')
            if actual!=stored or marker!={'schema':'bridge.native-route-stash/1','domain':'crowd_agents_v1','role':'route_curve','geometry_sha256':actual.geometry_sha256}:
                raise BridgeCommandError('ACTUAL_ROUTE_GEOMETRY_DIGEST_REQUIRED','saved route stash/output/digest differs')
            curve=asdict(actual);curve.pop('identity')
            return dict(curve,schema='bridge.native-route-curve-snapshot/1',houdini_version=hou.applicationVersionString())
        parent=parent.parent()
    raise BridgeCommandError('SCENE_OWNERSHIP_REQUIRED','route stash has no owned manifest')


def _fx_crowd_stash_snapshot(path):
    import hou
    from houdini_bridge.crowd_helpers import snapshot_agent_geometry, validate_synthetic_snapshot
    from houdini_bridge.native_crowd_transition_contract import _native_payload_guard
    node=hou.node(path)
    marker=json.loads(node.userData('bridge_native_agent_recipe_v1') or '{}')
    if node.type().name()!='stash' or marker.get('domain')!='crowd_agents_v1' or marker.get('schema') not in ('bridge.native-agent-stash/1','bridge.native-agent-stash/2'):
        raise BridgeCommandError('ACTUAL_PACKED_AGENT_SOURCE_REQUIRED','owned stash recipe identity is missing')
    snapshot=snapshot_agent_geometry(hou,node.parm('stash').evalAsGeometry())
    if marker['schema']=='bridge.native-agent-stash/1':validate_synthetic_snapshot(snapshot)
    elif _native_payload_guard(snapshot['native_payloads'])!=marker.get('native_payload_guard'):
        raise BridgeCommandError('ACTUAL_PACKED_AGENT_SOURCE_CHANGED','stored native definition payload differs')
    if snapshot['content_sha256']!=marker.get('content_sha256'):
        raise BridgeCommandError('ACTUAL_PACKED_AGENT_SOURCE_CHANGED','saved agent definition content differs')
    return snapshot


def _fx_crowd_clip_fact(path):
    snapshot = _fx_crowd_stash_snapshot(path)
    clip = next(c for c in snapshot['content']['agents'][0]['clips'] if c['name']=='w5_loop')
    return {'origin':'runtime_hom','clip_name':clip['name'],'sample_count':clip['sample_count'],
        'start_time':clip['start_time'],'sample_rate':clip['sample_rate'],
        'length_seconds':clip['length_seconds'],'content_sha256':snapshot['content_sha256'],
        'native_type':'PackedAgent','api_helper':'houdini_bridge.crowd_helpers'}


def _fx_initialize_crowd_domain(params, roles, pack, fresh_roles):
    import hou
    module,args = _fx_planned_module(pack)
    from houdini_bridge.native_crowd_transition_contract import _native_payload_guard
    try:
        hooks = module.crowd_hom_hooks()
        node = hou.node(roles['agent_definition'])
        actual = _fx_planned_observation(node,'stash',observe_value=False)
        if (actual['type'] != 'data' or actual['size'] != 1 or actual['driven'] or
                actual['hidden'] or actual['disabled'] or actual['locked']):
            raise BridgeCommandError('NATIVE_CONTROL_GATE_BLOCKED','agent stash data is not writable')
        if 'agent_definition' in fresh_roles:
            geometry,built_snapshot,_ = hooks['build_synthetic_agent_geometry'](hou)
            # Extend the actual detached definition through native constructors;
            # preserve the original source clip, layers and current rest pose.
            agent=next(p for p in geometry.prims() if isinstance(p,hou.Agent))
            old=agent.definition();rig=old.rig()
            clip=hou.AgentClip('w5_transition',rig,3)
            rest=list(old.clips()[0].localTransforms(0))
            middle=[hou.Matrix4(1),hou.hmath.buildTranslate(-.2,1.1,0.)]
            for i,transforms in enumerate((rest,middle,rest)):clip.setLocalTransforms(i,transforms)
            definition=hou.AgentDefinition(rig,old.shapeLibrary())
            for layer in old.layers():definition.addLayer(layer)
            for original in old.clips():definition.addClip(original)
            definition.addClip(clip)
            layers,times,weights,current=agent.currentLayers(),agent.clipTimes(),agent.clipWeights(),agent.clips()
            pose=[agent.localTransform(i) for i in range(rig.transformCount())]
            agent.setDefinition(definition);agent.setCurrentLayers(layers);agent.setClips(current)
            agent.setClipTimes(times);agent.setClipWeights(weights)
            for i,transform in enumerate(pose):agent.setLocalTransform(transform,i)
            built_snapshot=hooks['snapshot_agent_geometry'](hou,geometry)
            node.parm('stash').set(geometry)
            snapshot = hooks['snapshot_agent_geometry'](hou,node.parm('stash').evalAsGeometry())
            compared = hooks['compare_agent_snapshots'](built_snapshot,snapshot,tolerance=1e-8)
            if not compared['content_equivalent']:
                raise BridgeCommandError('PARAMETER_READBACK_MISMATCH','materialized agent content differs')
            node.setUserData('bridge_native_agent_recipe_v1',json.dumps({
                'schema':'bridge.native-agent-stash/2','domain':args[0],
                'native_payload_guard':_native_payload_guard(snapshot['native_payloads']),
                'content_sha256':snapshot['content_sha256']},sort_keys=True))
        snapshot = _fx_crowd_stash_snapshot(node.path())
        result = {'agent_definition':{'content':snapshot['content'],
            'content_sha256':snapshot['content_sha256'],'readback_verified':True}}
        result.update(_fx_apply_fresh_domain_plan(module.multiparm_allocation_plan(*args,fresh=True),roles,fresh_roles))
        fact = _fx_planned_multiparm_observation(hou.node(roles['import_geometry']),'fields',module._IMPORT_TEMPLATES)
        observations = {('agent_definition','@actual_clip'):_fx_crowd_clip_fact(node.path()),
            ('import_geometry','@multiparm/fields'):fact,
            ('crowd_object','@node_identity'):{'origin':'runtime_hom','task_owned':True,
                'name':hou.node(roles['crowd_object']).name()}}
        observations.update({('import_geometry',name):{'origin':'runtime_hom'} for name in fact['bindings'].values()})
        for parm in ('constraintsolvertype','randomize_order'):
            observations['bullet',parm] = _fx_planned_observation(hou.node(roles['bullet']),parm)
        result.update(_fx_apply_fresh_domain_plan(module.trusted_initialization_plan(*args,
            fresh=True,observations=observations),roles,fresh_roles))
        for reference in module.role_reference_plan(*args):
            write = dict(reference,native_type='string',value=roles[reference['target_role']])
            result.update(_fx_apply_fresh_domain_plan([write],roles,fresh_roles))
        source = hou.node(roles['source'])
        axis = {'schema':'bridge.native-domain-axis/1','domain':args[0],'role':'source','value':[1.,0.,0.]}
        if 'source' in fresh_roles:
            source.setUserData('bridge_native_axis_v1',json.dumps(axis,sort_keys=True))
        elif json.loads(source.userData('bridge_native_axis_v1') or '{}') != axis:
            raise BridgeCommandError('SCENE_STATE_MISMATCH','owned source movement axis differs')
        result['route'] = _fx_initialize_crowd_route(roles,pack,fresh_roles)
        result['transition'] = _fx_initialize_crowd_transition(roles,pack,fresh_roles)
        render_pack,render_roles = _fx_shared_render_pack(params,roles,pack)
        render_fresh = {r for r in render_roles if (r=='settings' and 'render_settings' in fresh_roles) or
            (r=='source' and 'output' in fresh_roles) or r in fresh_roles}
        result['shared_render'] = _fx_initialize_render_domain(params,'lighting_camera_render_v1',render_roles,render_pack,render_fresh)
        return result
    except Exception:
        for role in sorted(fresh_roles,key=lambda r:roles[r].count('/'),reverse=True):
            node = hou.node(roles[role])
            if node is not None:node.destroy()
        raise


def _fx_initialize_rbd_domain(params,roles,pack,fresh_roles):
    import hou
    module,args = _fx_planned_module(pack)
    try:
        result = _fx_apply_fresh_domain_plan(module.trusted_initialization_plan(*args,
            fresh=True,phase='allocate',initialize_activation=True),roles,fresh_roles)
        result.update(_fx_apply_fresh_domain_plan([
            {'role':'constraint_strength','parm':'class','value':'primitive','native_type':'ordinal'},
            {'role':'constraint_strength','parm':'group','value':'','native_type':'string'},
            {'role':'constraint_strength','parm':'snippet','value':module.UNIT_GLUE_SNIPPET,'native_type':'string'},
        ],roles,fresh_roles))
        fact = _fx_planned_multiparm_observation(hou.node(roles['solver']),'breaks',module._IMPACT_TEMPLATES)
        observations = {('solver','@multiparm/breaks'):fact,
            ('configure','@geometry/1'):_fx_planned_geometry_fact(hou.node(roles['configure']),output_index=1)}
        observations['configure','@multiparm/attributes']=_fx_planned_multiparm_observation(hou.node(roles['configure']),'attributes',module._ACTIVE_TEMPLATES)
        result.update(_fx_apply_fresh_domain_plan(module.trusted_initialization_plan(*args,
            fresh=True,phase='gates',observations=observations,initialize_activation=True),roles,fresh_roles))
        normalized = _fx_planned_geometry_fact(hou.node(roles['solver']),input_index=1)
        module._unit_glue_geometry({('solver','@input_geometry/1'):normalized})
        result['constraint_strength'] = {'actual_input_geometry':normalized,
            'normalization':'persistent_primitive_glue_multiplier_one/1','readback_verified':True}
        result['rbd_velocity'] = _fx_rbd_velocity_host().initialize(params, roles, pack, fresh_roles)
        render_pack,render_roles = _fx_shared_render_pack(params,roles,pack)
        render_fresh = {r for r in render_roles if (r=='settings' and 'render_settings' in fresh_roles) or
            (r=='source' and 'output' in fresh_roles) or r in fresh_roles}
        result['shared_render'] = _fx_initialize_render_domain(params,'lighting_camera_render_v1',render_roles,render_pack,render_fresh)
        return result
    except Exception:
        for role in sorted(fresh_roles,key=lambda r:roles[r].count('/'),reverse=True):
            node = hou.node(roles[role])
            if node is not None:node.destroy()
        raise


def _fx_initialize_particle_ocean_geometry_domain(params,roles,pack,fresh_roles):
    import hou
    module,args = _fx_planned_module(pack)
    try:
        preserve_size = (args[0] == module.PARTICLES and 'particle_size' not in fresh_roles
            and hou.node(roles['particle_size']).userData('bridge_particle_size_basis_v1') is not None)
        gates = module.trusted_initialization_plan(*args, fresh=True, phase='gates')
        if preserve_size:
            gates = [write for write in gates if write['role'] != 'particle_size']
        result = _fx_apply_fresh_domain_plan(gates, roles, fresh_roles)
        if args[0]==module.OCEAN:
            recipe=[('spectrum','res',4,'integer'),('spectrum','ampscale',1.,'float'),
                ('spectrum','windspeed',10.,'float'),('spectrum','winddir',0.,'float'),('spectrum','chopscale',.7,'float'),
                ('spectrum','timeoffset',0.,'float'),('spectrum','timescale',1.,'float'),
                ('foam_emit','mincusp',.5,'float'),('foam_emit','density',1.,'float')]
            result.update(_fx_apply_fresh_domain_plan([{'role':r,'parm':p,'value':v,'native_type':t} for r,p,v,t in recipe],roles,fresh_roles))
        observations = {}
        if args[0] == module.SWARM and 'seek' in fresh_roles:
            observations['seek','goal'] = _fx_planned_observation(hou.node(roles['seek']),'goal')
        elif args[0] == module.OCEAN:
            observations['source','@geometry/0'] = _fx_planned_geometry_fact(hou.node(roles['source']))
        values = module.trusted_initialization_plan(*args, fresh=True, phase='values',
            observations=observations, preserve_goal=args[0]==module.SWARM and 'seek' not in fresh_roles)
        if preserve_size:
            values = [write for write in values if write['role'] != 'particle_size']
        result.update(_fx_apply_fresh_domain_plan(values, roles, fresh_roles))
        if preserve_size:
            from dataclasses import asdict
            from houdini_bridge.native_particle_size_program import collect_control_readback
            result['particle_size_preserved'] = asdict(collect_control_readback(
                hou.applicationVersionString(), _fx_particle_size_host().observations(roles, pack)))
        if args[0]==module.SWARM:
            result['swarm_basis']=_fx_swarm_host().initialize(params,roles,pack,fresh_roles)
        if args[0] == module.GEOMETRY:
            frozen = params.get('frozen_input_manifest')
            if isinstance(frozen, list) and any(isinstance(source, dict) and
                    source.get('semantic_role') == 'geometry_rest_basis' for source in frozen):
                root_path = _fx_planned_owned_root(roles, pack)
                scope = globals().get('_FX_GEOMETRY_BUILD_SCOPES', {}).get(root_path)
                if scope is None or scope['token'] is not None:
                    raise BridgeCommandError('GEOMETRY_BUILD_TRANSACTION_REQUIRED', 'fresh initialization requires its outer build transaction')
                scope['token'] = _fx_geometry_registry().begin(params, roles, pack, fresh_roles)
                result['geometry_deformation'] = _fx_geometry_host().initialize(params, roles, pack, fresh_roles)
            else:
                result['geometry_deformation'] = {'status': 'BLOCKED', 'evidence_scope': 'none',
                    'missing_evidence': ['GEOMETRY_AUTHENTICATED_REST_BASIS_REQUIRED',
                                         'GEOMETRY_REGISTERED_INITIALIZATION_REQUIRED']}
        if args[0]==module.OCEAN:
            result.update(_fx_apply_fresh_domain_plan([{'role':'ocean_masks','parm':'vex_precision','value':'64','native_type':'string'}],roles,fresh_roles))
            context=_fx_ocean_program_context(roles,pack,include_masked=False)
            context['foam']=False
            from houdini_bridge.native_ocean_mask_program import control_write_plan,validate_control_write_plan
            writes=control_write_plan(args[0],args[1],**context)
            observations={(w['role'],w['parm']):_fx_planned_observation(hou.node(roles[w['role']]),w['parm'],observe_value=w['role'] not in fresh_roles) for w in writes}
            validate_control_write_plan(writes,observations,**context)
            converted=[]
            for write in writes:
                item=dict(write)
                if item.get('value_kind')=='menu_label':
                    item['value']=_fx_source_menu_token(hou.node(roles[item['role']]).parm(item['parm']).parmTemplate(),item['value'])
                converted.append(item)
            result.update(_fx_apply_fresh_domain_plan(converted,roles,fresh_roles))
            result['ocean_masks']=_fx_planned_geometry_readback(pack,roles,{'foam':False})
        if args[0] == module.PARTICLES:
            axis = {'schema':'bridge.native-domain-axis/1','domain':args[0],'role':'emission','value':[0.,1.,0.]}
            source = hou.node(roles['emission'])
            if 'emission' in fresh_roles:
                source.setUserData('bridge_native_axis_v1',json.dumps(axis,sort_keys=True))
            elif json.loads(source.userData('bridge_native_axis_v1') or '{}') != axis:
                raise BridgeCommandError('SCENE_STATE_MISMATCH','owned emission axis differs')
            result['particle_size_basis'] = _fx_particle_size_host().initialize(params, roles, pack, fresh_roles)
        render_pack,render_roles = _fx_shared_render_pack(params,roles,pack)
        render_fresh = {r for r in render_roles if (r=='settings' and 'render_settings' in fresh_roles) or
            (r=='source' and 'output' in fresh_roles) or r in fresh_roles}
        result['shared_render'] = _fx_initialize_render_domain(params,'lighting_camera_render_v1',render_roles,render_pack,render_fresh)
        if args[0] == module.PARTICLES:
            result['particle_emission_basis'] = _fx_particle_emission_host().initialize(params, roles, pack, fresh_roles)
        return result
    except Exception:
        for role in sorted(fresh_roles,key=lambda r:roles[r].count('/'),reverse=True):
            node = hou.node(roles[role])
            if node is not None:node.destroy()
        raise



def _fx_cloth_geometry_observation(node,role,geometry=None):
    import hou
    geometry=node.geometry(output_index=0) if geometry is None else geometry
    points,prims=tuple(geometry.points()),tuple(geometry.prims())
    if len(points)>8192 or len(prims)>8192:
        raise BridgeCommandError('NATIVE_GEOMETRY_BUDGET_EXCEEDED','cloth source sample exceeds budget')
    position=geometry.findPointAttrib('P')
    if position is None:raise BridgeCommandError('ACTUAL_CLOTH_PRECISION_REQUIRED','P attribute absent')
    storage=str(position.numericDataType()).rsplit('.',1)[-1]
    if storage not in ('Float32','Float64'):
        raise BridgeCommandError('ACTUAL_CLOTH_PRECISION_REQUIRED','unsupported actual P storage')
    positions=[list(point.position()) for point in points]
    if not positions:raise BridgeCommandError('ACTUAL_CLOTH_GEOMETRY_REQUIRED','source has no points')
    polygons=[]
    for prim in prims:
        if prim.type().name()!='Polygon':raise BridgeCommandError('ACTUAL_CLOTH_POLYGONS_REQUIRED','source is not polygon geometry')
        polygons.append([vertex.point().number() for vertex in prim.vertices()])
    return {'origin':'runtime_hom','role':role,'node_path':node.path(),'output':0,'space':'sop_local',
        'frame':float(hou.frame()),'position_precision':storage.lower(), 'point_positions':positions,
        'polygons':polygons,'bbox':[[min(p[i] for p in positions) for i in range(3)],
            [max(p[i] for p in positions) for i in range(3)]]}


def _fx_cloth_program_context(roles,pack):
    import hou
    from houdini_bridge.native_cloth_wrinkle_program import source_geometry_sha256
    root=_fx_planned_owned_root(roles,pack)
    source=hou.node(roles['source']);stage=hou.node(roles['cloth_wrinkle']);constraints=hou.node(roles['constraints'])
    original=_fx_cloth_geometry_observation(source,'source')
    connections=[wire for wire in stage.inputConnections() if wire.inputIndex()==0]
    if len(connections)!=1 or connections[0].inputNode()!=source or connections[0].outputIndex()!=0:
        raise BridgeCommandError('ACTUAL_OWNED_CLOTH_SHAPE_STAGE_REQUIRED','owned source input differs')
    downstream=[wire for wire in constraints.inputConnections() if wire.inputIndex()==0]
    if len(downstream)!=1 or downstream[0].inputNode()!=stage or downstream[0].outputIndex()!=0:
        raise BridgeCommandError('ACTUAL_OWNED_CLOTH_SHAPE_STAGE_REQUIRED','constraints do not consume the owned shape stage')
    input_geometry=stage.inputGeometry(0)
    # Independently read the connected input instead of assigning an expected hash.
    input_node=connections[0].inputNode()
    input_fact=_fx_cloth_geometry_observation(input_node,'source',input_geometry)
    native=_fx_planned_observation(constraints,'thickness')
    thickness={key:native[key] for key in ('origin','type','size','driven','value')}
    thickness.update(role='constraints',node_path=constraints.path(),parm='thickness',
        gates={name:_fx_planned_observation(constraints,name) for name in ('constrainttype','dothickness')})
    precision=_fx_planned_observation(stage,'vex_precision')
    if precision['type']!='string' or precision['size']!=1 or precision['driven'] or precision['value'] not in ('32','64'):
        raise BridgeCommandError('ACTUAL_CLOTH_PRECISION_REQUIRED','wrangle actual vex_precision must be explicit')
    shape={'origin':'runtime_hom','role':'cloth_wrinkle','node_path':stage.path(),'category':stage.type().category().name().lower(),
        'type':stage.type().name(),'task_owned':True,'task_root':root,'input_node_path':input_node.path(),
        'input_output':connections[0].outputIndex(),'input_index':0,'input_geometry_sha256':source_geometry_sha256(input_fact),
        'space':'sop_local','frame':float(hou.frame()),'vex_precision':precision['value'],'native_version':hou.applicationVersionString()}
    return {'source':original,'thickness':thickness,'shape_stage':shape,
        'shaped_geometry':_fx_cloth_geometry_observation(stage,'cloth_wrinkle')}

def _fx_ocean_spectrum_observation(node,root,geometry=None):
    import hou
    from houdini_bridge.native_ocean_mask_program import spectrum_geometry_sha256
    geometry=node.geometry(output_index=0) if geometry is None else geometry
    prims=tuple(geometry.prims());attributes=tuple(geometry.primAttribs())
    if len(prims)>64 or len(attributes)>128:
        raise BridgeCommandError('NATIVE_GEOMETRY_BUDGET_EXCEEDED','ocean spectral layer/attribute budget exceeded')
    rows=[];total=0
    for prim in prims:
        if prim.type().name()!='Volume' or str(prim.storageType()).rsplit('.',1)[-1]!='Float' or prim.channelCount()!=1:
            raise BridgeCommandError('ACTUAL_OCEAN_SPECTRUM_REQUIRED','actual scalar native Float Volume required')
        res=list(prim.resolution())
        if len(res)!=3 or any(type(n) is not int or n<1 for n in res):
            raise BridgeCommandError('ACTUAL_OCEAN_SPECTRUM_REQUIRED','actual positive Volume resolution required')
        count=math.prod(res);total+=count
        if total>4194304:
            raise BridgeCommandError('NATIVE_GEOMETRY_BUDGET_EXCEEDED','ocean voxel collection budget exceeded')
        values=tuple(prim.allVoxels())
        if len(values)!=count or any(type(v) not in (int,float) or not math.isfinite(v) for v in values):
            raise BridgeCommandError('ACTUAL_OCEAN_SPECTRUM_REQUIRED','all actual finite scalar voxel values required')
        if 'volumebordertype' not in prim.intrinsicNames():
            raise BridgeCommandError('ACTUAL_OCEAN_SPECTRUM_REQUIRED','actual native Volume border intrinsic required')
        attrs={a.name():_json_safe(prim.attribValue(a.name())) for a in attributes}
        rows.append({'primitive_index':prim.number(),'name':prim.attribValue('name'),'type':'Volume',
            'resolution':res,'transform':{'matrix':list(prim.transform().asTuple()),
                'translation':list(prim.vertex(0).point().position())},
            'storage':{'precision':'float32','voxel_count':len(values),
                'values_sha256':hashlib.sha256(json.dumps(values,separators=(',',':'),allow_nan=False).encode()).hexdigest(),
                'border_type':str(prim.intrinsicValue('volumebordertype'))},'primitive_attributes':attrs})
    # Same-build SDK scalar Float Volume is UT_VoxelArray<fpreal32>; no
    # precision is inferred from the independently stored P attributes.
    result={'origin':'runtime_hom','role':'spectrum','node_path':node.path(),
        'category':node.type().category().name().lower(),'type':node.type().name(),
        'task_owned':True,'task_root':root,'output':0,'space':'sop_local',
        'frame':float(hou.frame()),'sample_time':float(hou.time()),'volumes':rows,'geometry_sha256':''}
    result['geometry_sha256']=spectrum_geometry_sha256(result)
    return result


def _fx_ocean_masked_geometry(node):
    geometry=node.geometry(output_index=0)
    result=_fx_cloth_geometry_observation(node,'ocean_masks',geometry)
    result['point_attributes']={}
    for name in ('bridge_ocean_layers','bridge_ocean_cusp','bridge_ocean_dual_area','cusp_mask','foam_mask'):
        attribute=geometry.findPointAttrib(name)
        if attribute is None:
            raise BridgeCommandError('ACTUAL_OCEAN_MASK_ATTRIBUTES_REQUIRED','actual point attribute absent: '+name)
        kind=str(attribute.dataType()).rsplit('.',1)[-1].lower()
        precision=str(attribute.numericDataType()).rsplit('.',1)[-1].lower()
        result['point_attributes'][name]={'owner':'point','storage':kind,'size':attribute.size(),
            'precision':precision,'values':[_json_safe(point.attribValue(name)) for point in geometry.points()]}
    return result


def _fx_ocean_program_context(roles,pack,*,include_masked=True):
    import hou
    from houdini_bridge.native_ocean_mask_program import source_geometry_sha256
    root=_fx_planned_owned_root(roles,pack)
    source,surface,spectrum,stage,emit=(hou.node(roles[r]) for r in ('source','evaluate','spectrum','ocean_masks','foam_emit'))
    original=_fx_cloth_geometry_observation(source,'source')
    spectral=_fx_ocean_spectrum_observation(spectrum,root)
    evaluated=_fx_cloth_geometry_observation(surface,'evaluate')
    inputs=[]
    for index,node,role in ((0,surface,'evaluate'),(1,spectrum,'spectrum'),(2,source,'source')):
        wires=[wire for wire in stage.inputConnections() if wire.inputIndex()==index]
        if len(wires)!=1 or wires[0].inputNode()!=node or wires[0].outputIndex()!=0:
            raise BridgeCommandError('ACTUAL_OWNED_OCEAN_MASK_STAGE_REQUIRED','actual three-input ocean mask connection differs')
        actual=stage.inputGeometry(index)
        fact=(_fx_ocean_spectrum_observation(node,root,actual) if role=='spectrum'
            else _fx_cloth_geometry_observation(node,role,actual))
        digest=fact['geometry_sha256'] if role=='spectrum' else source_geometry_sha256(fact,role=role)
        inputs.append({'input_index':index,'node_path':node.path(),'output':0,'geometry_sha256':digest})
    downstream=[wire for wire in hou.node(roles['output']).inputConnections() if wire.inputIndex()==0]
    if len(downstream)!=1 or downstream[0].inputNode()!=stage or downstream[0].outputIndex()!=0:
        raise BridgeCommandError('ACTUAL_OWNED_OCEAN_MASK_STAGE_REQUIRED','output does not consume the owned mask stage')
    precision=_fx_planned_observation(stage,'vex_precision')
    if precision['type']!='string' or precision['size']!=1 or precision['driven'] or precision['value'] not in ('32','64'):
        raise BridgeCommandError('ACTUAL_OCEAN_PRECISION_REQUIRED','actual explicit wrangle precision required')
    context={'source':original,'surface':evaluated,'spectrum':spectral,
        'mask_stage':{'origin':'runtime_hom','role':'ocean_masks','node_path':stage.path(),
            'category':stage.type().category().name().lower(),'type':stage.type().name(),
            'task_owned':True,'task_root':root,'space':'sop_local','frame':float(hou.frame()),
            'native_version':hou.applicationVersionString(),'vex_precision':precision['value'],'inputs':inputs},
        'native_emit':{'origin':'runtime_hom','role':'foam_emit','node_path':emit.path(),
            'category':emit.type().category().name().lower(),'type':emit.type().name(),'task_owned':True,
            'task_root':root,'frame':float(hou.frame()),
            'parameters':{n:_fx_planned_observation(emit,n) for n in ('mincusp','density')},
            'gates':{n:_fx_planned_observation(emit,n) for n in ('mode','region','domincusp','dominvel','dominheight','dodisplace')}},
        'foam':not (stage.parm('snippet').eval() or '').endswith('f@foam_mask = 0.0;\n')}
    if 'ocean_masks' in roles and not stage.parm('snippet').eval():context['foam']=False
    if include_masked:context['masked_geometry']=_fx_ocean_masked_geometry(stage)
    return context


def _fx_planned_geometry_readback(pack,roles,normalized):
    import hou
    domain=pack['native_domain_id']
    if domain == 'particles_v1' and 'emission_variance' in normalized:
        return _fx_particle_emission_host().readback(roles, pack)
    if domain == 'procedural_geometry_v1' and 'deformation' in normalized:
        from houdini_bridge.native_geometry_controls_program import control_readback
        actual = _fx_geometry_observations(roles, pack)
        return control_readback(hou.applicationVersionString(), actual['context'], actual['parameters'])
    if domain=='swarm_flocking_v1' and any(n in normalized for n in ('target_noise','noise_strength')):
        return _fx_swarm_host().readback(roles,pack,normalized)
    if domain=='rbd_destruction_v1' and 'activation_frame' in normalized:
        return _fx_rbd_activation_output_readback(roles,pack)
    if domain=='rbd_destruction_v1' and 'velocity_variance' in normalized:
        return _fx_rbd_velocity_host().readback(roles,pack,normalized)
    if domain=='pyro_fire_v1' and 'flame_height' in normalized:
        return _fx_pyro_height_host().readback(roles,pack)
    if domain=='particles_v1' and 'size_variance' in normalized:
        from dataclasses import asdict
        from houdini_bridge.native_particle_size_program import collect_control_readback
        return asdict(collect_control_readback(hou.applicationVersionString(),
            _fx_particle_size_host().observations(roles,pack)))
    if domain=='water_ocean_v1':
        from houdini_bridge.native_ocean_mask_program import control_write_plan,validate_applied_readback
        context=_fx_ocean_program_context(roles,pack);masked=context.pop('masked_geometry')
        if 'foam' in normalized:context['foam']=normalized['foam']
        writes=control_write_plan(domain,hou.applicationVersionString(),**context)
        observations={(w['role'],w['parm']):_fx_planned_observation(hou.node(roles[w['role']]),w['parm']) for w in writes}
        comparison=validate_applied_readback(writes,observations,masked_geometry=masked,**context)
        return {'registration':writes[-1]['trusted_program'],'context':context,'masked_geometry':masked,'comparison':comparison}
    if domain=='vellum_cloth_v1' and 'wrinkle_scale' in normalized:
        from houdini_bridge.native_cloth_wrinkle_program import source_program,validate_geometry_readback
        context=_fx_cloth_program_context(roles,pack)
        shaped=context.pop('shaped_geometry')
        registration=source_program(domain,hou.applicationVersionString(),normalized['wrinkle_scale'],**context)
        comparison=validate_geometry_readback(registration,**context,shaped_geometry=shaped)
        return {'registration':registration,'context':context,'shaped_geometry':shaped,'comparison':comparison}
    if domain=='crowd_agents_v1' and any(n in normalized for n in ('route_weight','animation_blend')):
        from dataclasses import asdict
        from houdini_bridge import native_crowd_route_contract as route,native_crowd_transition_contract as transition
        result={'frame':hou.frame(),'time':hou.time()}
        for name,module,collector,prefix in (('route_weight',route,_fx_crowd_route_context,'route'),('animation_blend',transition,_fx_crowd_transition_context,'transition')):
            if name in normalized:
                context=collector(roles,pack)
                result[prefix+'_context']=asdict(context)
                result[prefix+'_readback']=module.validate_readback(module.candidate_write_plan(context,normalized[name]),context)
        return result
    if domain=='hair_fur_v1' and 'collision_radius' in normalized:
        observed=_fx_planned_geometry_fact(hou.node(roles['constraints']))
        return {'contract':'actual_point_pscale_and_documented_native_radius/1','actual_geometry':observed,
            'actual_thickness':_fx_planned_observation(hou.node(roles['constraints']),'thickness'),
            'documentation_sha256':'64f9bf4f360eb3d9f202c2174b8dd1962c70ef31debfda6108528966235a0a25',
            'radius_measurement_observable':observed['points']>0}
    return {}


def _fx_initialize_planned_domain(params, pack_id, roles, pack, fresh_roles):
    import hou
    module, args = _fx_planned_module(pack)
    if module.SCHEMA == 'bridge.native-pyro-domains/1':
        # A fixed recipe supplies a bounded initial emitter; approved source-plan
        # controls subsequently replace it through the same trusted adapter.
        source = {'emission_windows': [(1, 2)], 'direction': [0, 1, 0], 'spread': 30,
                  'speed': 2, 'particle_separation': .1}
        plan = module.trusted_initialization_plan(*args, source)
        if _fx_configuration(params).get('source_plan') is not None:
            # The captured two-row source adapter owns allocation, row values
            # and activation channels. Keep the normal native graph and its
            # other gates, exports and render initialization.
            plan = [w for w in plan if not (w['role'] == 'solver' and
                (w['parm'] == 'numsources' or w['parm'].startswith('source_')))]
            for w in plan:
                if w['role'] == 'solver' and w['parm'] == 'srclimitframerange':
                    w['value'] = 1
            if not fresh_roles:
                mutable = {('source_points','particlesep'), ('source_volume','attributes'),
                    ('source_volume','voxelsize'), ('source_control','snippet'), ('solver','divsize')}
                plan = [w for w in plan if (w['role'],w['parm']) not in mutable]
    elif module.SCHEMA == 'bridge.native-vellum-domains/1':
        plan = module.trusted_initialization_plan(*args)
    elif module.SCHEMA == 'bridge.native-flip-rbd-domains/1' and pack_id == module.FLIP:
        plan = module.trusted_initialization_plan(*args, fresh=True)
    elif module.SCHEMA == 'bridge.native-flip-rbd-domains/1' and pack_id == module.RBD:
        return _fx_initialize_rbd_domain(params,roles,pack,fresh_roles)
    elif module.SCHEMA == 'bridge.native-crowd-hair-domains/1' and pack_id == module.HAIR:
        return _fx_initialize_hair_domain(params,roles,pack,fresh_roles)
    elif module.SCHEMA == 'bridge.native-crowd-hair-domains/1' and pack_id == module.CROWD:
        return _fx_initialize_crowd_domain(params,roles,pack,fresh_roles)
    elif module.SCHEMA == 'bridge.native-particle-ocean-geometry-domains/1':
        return _fx_initialize_particle_ocean_geometry_domain(params,roles,pack,fresh_roles)
    else:
        raise BridgeCommandError('ACTUAL_NATIVE_CONTEXT_REQUIRED', 'native Crowd/Hair geometry and clip initialization is required')
    attempted, result = [], {}
    try:
        for write in plan:
            node = hou.node(roles[write['role']]); parm = _resolve_parm_target(node, [write['parm']])
            if parm is None:
                raise BridgeCommandError('NATIVE_CONTROL_INTERFACE_REQUIRED', write['role'] + '/' + write['parm'])
            value = write['value']
            if write.get('value_kind') == 'menu_label':
                value = _fx_source_menu_token(parm.parmTemplate(), value)
            fresh = write['role'] in fresh_roles
            actual = _fx_planned_observation(node, write['parm'], observe_value=not fresh)
            typ = write['native_type']
            if typ != 'keyframes' and (actual['type'] != ('float' if typ == 'float_tuple' else typ) or actual['size'] != write.get('size', 1)):
                raise BridgeCommandError('NATIVE_CONTROL_INTERFACE_REQUIRED', 'native initialization type differs: ' + parm.path())
            if actual['hidden'] or actual['disabled'] or actual['locked']:
                raise BridgeCommandError('NATIVE_CONTROL_GATE_BLOCKED', 'native initialization is blocked: ' + parm.path())
            if not fresh:
                if typ == 'keyframes' or not _values_match(value, actual['value']):
                    raise BridgeCommandError('SCENE_STATE_MISMATCH', 'existing native domain initialization differs: ' + parm.path())
                continue
            key = write['role'] + '.' + write['parm']
            if typ == 'keyframes':
                result[key] = _fx_set_solver_activation_verified(parm, _snapshot_parm_state(parm), value, hou)
            else:
                result[key] = _fx_set_fresh_native_verified(parm, value)
        final = {(w['role'],w['parm']):w for w in plan}
        for write in final.values():
            if write['native_type'] == 'keyframes':
                continue
            parm = _resolve_parm_target(hou.node(roles[write['role']]), [write['parm']])
            value = write['value']
            if write.get('value_kind') == 'menu_label':
                value = _fx_source_menu_token(parm.parmTemplate(), value)
            if not _values_match(value, _read_parm_for_request(parm,value)):
                raise BridgeCommandError('PARAMETER_READBACK_MISMATCH', 'native initialization vector drifted: ' + parm.path())
        render_pack, render_roles = _fx_shared_render_pack(params, roles, pack)
        render_fresh = {r for r in render_roles if (r == 'settings' and 'render_settings' in fresh_roles) or
                        (r == 'source' and 'output' in fresh_roles) or r in fresh_roles}
        result['shared_render'] = _fx_initialize_render_domain(params, 'lighting_camera_render_v1',
            render_roles, render_pack, render_fresh)
        if module.SCHEMA == 'bridge.native-pyro-domains/1':
            for write in module.volume_sampling_initialization_plan(args[1]):
                if write['role'] not in fresh_roles:
                    continue
                parm = _resolve_parm_target(hou.node(roles[write['role']]), [write['parm']])
                snapshot = _snapshot_parm_state(parm)
                attempted.append((parm, snapshot)); result[write['role'] + '.' + write['parm']] = _set_parm_verified(parm, write['value'])
            if pack_id == module.FIRE:
                result['flame_height'] = _fx_pyro_height_host().initialize(params, roles, pack, fresh_roles)
        return result
    except Exception:
        for parm, snapshot in reversed(attempted):
            _restore_parm_snapshot(parm, snapshot)
        for role in sorted(fresh_roles, key=lambda r:roles[r].count('/'), reverse=True):
            node = hou.node(roles[role])
            if node is not None:
                node.destroy()
        raise


def _fx_planned_domain_static_readback(pack_id, roles, pack):
    import hou
    for requirement in pack['nodes']:
        node = hou.node(roles.get(requirement['role'], ''))
        if node is None or node.type().name() not in requirement['types']:
            raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'native domain role/type differs: ' + requirement['role'])
        if requirement.get('parent_role') and node.parent() != hou.node(roles[requirement['parent_role']]):
            raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'native domain parent differs: ' + requirement['role'])
    for wire in pack['connections']:
        node = hou.node(roles[wire['destination_role']])
        actual = {c.inputIndex(): (c.inputNode().path(), c.outputIndex()) for c in node.inputConnections()}
        if actual.get(wire['destination_input']) != (roles[wire['source_role']], wire['source_output']):
            raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'native domain wire differs')
    render_pack, render_roles = _fx_shared_render_pack({}, roles, pack)
    render = _fx_static_domain_readback('lighting_camera_render_v1', render_roles, render_pack)
    return {**render, 'output_role': 'output', 'output_kind': 'native_domain_and_usd_render_stage',
            'native_plan_schema': pack['native_plan_schema'], 'native_geometry_validated': False}


def _fx_render_domain_prepared(pack_id, changes, roles, pack):
    import hou
    from houdini_bridge.native_render_domains import candidate_write_plan, validate_control_write_plan, NativeRenderDomainError
    contracts = {"shutter": (pack.get("controls", {}).get("shutter") or {}).get("semantic_contract")}
    try:
        writes = candidate_write_plan(pack_id, changes, hou.applicationVersionString(), shutter_contract=contracts["shutter"])
        fields = {(item["role"], item["parm"]) for item in writes}
        fields.update((role, name) for item in writes for role, name, expected in item.get("required_gates", ()))
        observations = {(role, name): _fx_native_field_observation(hou.node(roles.get(role, "")), name) for role, name in fields}
        validate_control_write_plan(writes, observations)
        prepared = []
        for write in writes:
            node = hou.node(roles[write["role"]])
            parm = _resolve_parm_target(node, [write["parm"]])
            snapshot = _snapshot_parm_state(parm)
            if _parm_snapshot_is_driven(snapshot):
                raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "native control is driven: " + parm.path())
            names = [name for name, control in pack["controls"].items()
                     if name in changes and control["role"] == write["role"] and
                     (write["parm"] in control["aliases"] or name == "shutter" and write["parm"] == "xn__shutterclose_nva")]
            prepared.append({"name": names[0], "semantic_names": names, "node": node, "parm": parm,
                             "snapshot": snapshot, "value": write["value"], "primary": False,
                             "native_target": {"multiplier": 1.0},
                             "invalidates_from": str(pack["controls"][names[0]].get("invalidates_from") or "lighting")})
        return prepared
    except NativeRenderDomainError as exc:
        raise BridgeCommandError(exc.code, str(exc)) from exc


def _fx_render_domain_readback(pack_id, changes, roles, pack):
    import hou
    from houdini_bridge.native_render_domains import control_readback, NativeRenderDomainError
    values = {}
    for name in changes:
        control = pack["controls"][name]
        fields = list(control["aliases"])
        if name == "shutter":
            fields.append("xn__shutterclose_nva")
        for field in fields:
            observation = _fx_native_field_observation(hou.node(roles[control["role"]]), field)
            values[control["role"], field] = observation["value"]
    try:
        return {name: _json_safe(control_readback(pack_id, name, values, hou.applicationVersionString(),
                    shutter_contract=(pack["controls"].get("shutter") or {}).get("semantic_contract"))) for name in changes}
    except NativeRenderDomainError as exc:
        raise BridgeCommandError(exc.code, str(exc)) from exc


def _fx_frozen_scene_plan(configuration, roles, task_id, *, plan_revision=None):
    """Resolve a compiled metadata menu from its actual instance, never an ordinal."""
    import hou
    from houdini_bridge.native_render_scene import parameter_plan, PARAMETER_PLAN_REVISION
    plan = parameter_plan(configuration, hou.applicationVersionString(),
                          revision=PARAMETER_PLAN_REVISION if plan_revision is None else plan_revision)
    if configuration['profile'] in ('sphere_ground_v2', 'bounded_geometry_rig_v1'):
        geometry = '/World/' + _task_name(str(task_id), 'Bridge') + '/Geometry'
        # Karma authors its RGBA beauty RenderVar beneath rendervarsparentprimpath.
        plan += [dict(role=role,parm=name,value=value,native_type=kind,phase=phase)
                 for role,name,value,kind,phase in [
                     ('geometry_import','pathprefix',geometry+('/Model' if configuration['profile']=='bounded_geometry_rig_v1' else '/Sphere'),'string','value'),
                     ('ground_import','soppath',roles['ground'],'string','value'),
                     ('ground_import','enable_pathprefix',1,'toggle','gate'),
                     ('ground_import','pathprefix',geometry+'/Ground','string','value'),
                     ('settings','rendervarsparentprimpath',geometry.rsplit('/',1)[0]+'/Vars','string','value'),
                     ('render_product','orderedVars',geometry.rsplit('/',1)[0]+'/Vars/beauty','string','value')]]
    node = hou.node(roles['stage_metadata'])
    actual = _fx_native_field_observation(node, 'upaxis')
    template = _resolve_parm_target(node, ['upaxis']).parmTemplate()
    tokens, labels = tuple(template.menuItems()), tuple(template.menuLabels())
    choices = [token for token,label in zip(tokens,labels) if str(label) in ('Y', 'Y Axis', 'Y axis')]
    if actual['size'] != 1 or not tokens or len(tokens) != len(labels) or len(choices) != 1:
        raise BridgeCommandError('NATIVE_CONTROL_INTERFACE_REQUIRED', 'explicit Y up-axis menu is unavailable')
    plan += [dict(role='stage_metadata',parm=name,value=value,native_type=kind,phase=phase)
             for name,value,kind,phase in [('setupaxis',1,'toggle','gate'),('upaxis',choices[0],'menu','value'),
                 ('setmetersperunit',1,'toggle','gate'),('metersperunit',1.0,'float','value')]]
    return plan


def _fx_frozen_readback_revision(saved_readback):
    from houdini_bridge.native_render_scene import PARAMETER_PLAN_REVISION, LEGACY_PARAMETER_PLAN_REVISION
    if saved_readback is None:
        return PARAMETER_PLAN_REVISION
    if not isinstance(saved_readback, dict) or not isinstance(saved_readback.get("fields"), dict):
        raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "saved frozen parameter readback is malformed")
    if "parameter_plan_revision" not in saved_readback:
        additions = {"settings_binding.res_mode", "settings_binding.resolution",
                     "render.soho_foreground", "render.husk_tpostframe"}
        return (PARAMETER_PLAN_REVISION if additions <= set(saved_readback["fields"])
                else LEGACY_PARAMETER_PLAN_REVISION)
    revision = saved_readback["parameter_plan_revision"]
    if type(revision) is not int or revision != PARAMETER_PLAN_REVISION:
        raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "saved frozen parameter plan revision is unsupported")
    return revision


def _fx_frozen_readback_fields(saved_readback, by_key):
    if saved_readback is not None and set(saved_readback["fields"]) != {
            role + "." + name for role, name in by_key}:
        raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "saved frozen parameter field set differs from its plan revision")


def _fx_frozen_readback_version(payload, revision, saved_readback=None):
    from houdini_bridge.native_render_scene import PARAMETER_PLAN_REVISION
    if revision == PARAMETER_PLAN_REVISION and (saved_readback is None or "parameter_plan_revision" in saved_readback):
        payload["parameter_plan_revision"] = revision
    return payload


def _fx_frozen_scene_v1_readback(configuration, roles, pack, candidate_patch=None, *, task_id, saved_readback=None):
    """Compare actual owned fields and authored USD metadata with frozen intent."""
    import hou
    from dcc_task_runtime.canonical import canonical_sha256
    from houdini_bridge.native_render_scene import validate_configuration
    from houdini_bridge.native_render_domains import candidate_write_plan
    configuration = validate_configuration(configuration, hou.applicationVersionString())
    revision = _fx_frozen_readback_revision(saved_readback)
    writes = _fx_frozen_scene_plan(configuration, roles, task_id, plan_revision=revision)
    overrides = candidate_write_plan('material_lookdev_v1', candidate_patch or {}, hou.applicationVersionString())
    by_key = {(w['role'],w['parm']):w for w in writes}
    by_key.update({(w['role'],w['parm']):w for w in overrides})
    _fx_frozen_readback_fields(saved_readback, by_key)
    readbacks = {}
    for (role,name),write in by_key.items():
        parm = _resolve_parm_target(hou.node(roles[role]), [name])
        observed = _fx_native_field_observation(hou.node(roles[role]),name)
        if (observed['hidden'] or observed['disabled'] or observed['locked'] or
                _parm_snapshot_is_driven(_snapshot_parm_state(parm)) or
                not _values_match(write['value'], _read_parm_for_request(parm,write['value']))):
            raise BridgeCommandError('PARAMETER_READBACK_MISMATCH', 'frozen scene field drifted: ' + role + '.' + name)
        readbacks[role+'.'+name] = _json_safe(_read_parm_for_request(parm,write['value']))
    for role,typ,category in [('ground','grid','Sop'),('geometry_output','merge','Sop'),('stage_metadata','configurelayer','Lop')]:
        node = hou.node(roles[role])
        if node is None or node.type().name() != typ or node.type().category().name() != category:
            raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'static scene role drifted: ' + role)
    source = hou.node(roles['geometry_import']).parm('soppath').eval()
    if source != roles['geometry_output']:
        raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'static scene import does not consume sphere and ground merge')
    # The standard readback verifies every declared wire and exact material/ROP bindings.
    _fx_static_domain_readback('material_lookdev_v1', roles, pack)
    stage = hou.node(roles['settings_binding']).stage(frame=hou.frame(),apply_viewport_overrides=False,ignore_errors=False)
    metadata = {}
    for name,expected in [('upAxis','Y'),('metersPerUnit',1.0)]:
        if stage.HasAuthoredMetadata(name) is not True or not _values_match(expected, stage.GetMetadata(name)):
            raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'frozen USD metadata is not authored: ' + name)
        metadata[name] = stage.GetMetadata(name)
    return _fx_frozen_readback_version({'configuration_sha256':canonical_sha256(configuration),'profile':configuration['profile'],
            'fields':readbacks,'stage_metadata':metadata,'target_frames':configuration['scene']['frames'],
            'native_geometry_validated':False,'render_executed':False,'visual_verified':False}, revision, saved_readback)



def _fx_frozen_scene_readback(configuration, roles, pack, candidate_patch=None, *, task_id, saved_readback=None):
    """Compare actual owned fields and authored USD metadata with frozen intent."""
    import hou
    from dcc_task_runtime.canonical import canonical_sha256
    from houdini_bridge.native_render_scene import validate_configuration
    from houdini_bridge.native_render_domains import candidate_write_plan
    configuration = validate_configuration(configuration, hou.applicationVersionString())
    if configuration['profile'] == 'official_karma_disklight_v1':
        from houdini_bridge.official_karma_scene_host import readback
        result=readback(hou,configuration,roles,candidate_patch=candidate_patch)
        if saved_readback is not None and saved_readback!=result:
            raise BridgeCommandError('ARTIFACT_STRUCTURE_MISMATCH','official cold readback differs')
        return result
    if configuration['profile'] == 'sphere_ground_v1':
        return _fx_frozen_scene_v1_readback(configuration, roles, pack, candidate_patch,
                                          task_id=task_id, saved_readback=saved_readback)
    revision = _fx_frozen_readback_revision(saved_readback)
    writes = _fx_frozen_scene_plan(configuration, roles, task_id, plan_revision=revision)
    overrides = candidate_write_plan('material_lookdev_v1', candidate_patch or {}, hou.applicationVersionString())
    by_key = {(w['role'],w['parm']):w for w in writes}
    by_key.update({(w['role'],w['parm']):w for w in overrides})
    _fx_frozen_readback_fields(saved_readback, by_key)
    readbacks = {}
    for (role,name),write in by_key.items():
        parm = _resolve_parm_target(hou.node(roles[role]), [name])
        observed = _fx_native_field_observation(hou.node(roles[role]),name)
        if (observed['hidden'] or observed['disabled'] or observed['locked'] or
                _parm_snapshot_is_driven(_snapshot_parm_state(parm)) or
                not _values_match(write['value'], _read_parm_for_request(parm,write['value']))):
            raise BridgeCommandError('PARAMETER_READBACK_MISMATCH', 'frozen scene field drifted: ' + role + '.' + name)
        readbacks[role+'.'+name] = _json_safe(_read_parm_for_request(parm,write['value']))
    for role,typ,category in [('ground','grid','Sop'),('ground_import','sopimport','Lop'),('geometry_stage_merge','merge','Lop'),('stage_metadata','configurelayer','Lop')]:
        node = hou.node(roles[role])
        if node is None or node.type().name() != typ or node.type().category().name() != category:
            raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'static scene role drifted: ' + role)
    for import_role,source_role in [('geometry_import','source'),('ground_import','ground')]:
        if hou.node(roles[import_role]).parm('soppath').eval() != roles[source_role]:
            raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'static scene import consumes a different owned source: ' + import_role)
    # The standard readback verifies every declared wire and exact material/ROP bindings.
    _fx_static_domain_readback('material_lookdev_v1', roles, pack)
    stage = hou.node(roles['settings_binding']).stage(frame=hou.frame(),apply_viewport_overrides=False,ignore_errors=False)
    from itertools import islice
    from houdini_bridge.render_color_facts import MAX_OBSERVATION_VALUES
    prims = tuple(islice(stage.Traverse(), MAX_OBSERVATION_VALUES + 1))
    if len(prims) > MAX_OBSERVATION_VALUES:
        raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'static scene traversal exceeds its observation budget')
    try:
        from pxr import UsdShade
    except ImportError as error:
        raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'USD material resolution API is unavailable') from error
    namespace = '/World/' + _task_name(str(task_id), 'Bridge')
    material_path = namespace + '/Materials/lookdev'
    geometry = {}
    seen_paths = set()
    for name,import_role,source_role in [('Model' if configuration['profile']=='bounded_geometry_rig_v1' else 'Sphere','geometry_import','source'),('Ground','ground_import','ground')]:
        prefix = namespace + '/Geometry/' + name
        if hou.node(roles[import_role]).parm('pathprefix').eval() != prefix:
            raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'static scene import prefix differs: ' + name)
        selected = [prim for prim in prims if str(prim.GetPath()).startswith(prefix+'/') and
                    prim.GetTypeName() in {'Mesh','Sphere','Cube','Cone','Cylinder','Capsule','Points','BasisCurves','Volume'}]
        if not stage.GetPrimAtPath(prefix) or not selected:
            raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'static scene has no independent renderable prim: ' + name)
        resolved = []
        for prim in selected:
            path = str(prim.GetPath())
            if path in seen_paths:
                raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'static scene geometry identities overlap')
            seen_paths.add(path)
            try:
                material,relationship = UsdShade.MaterialBindingAPI(prim).ComputeBoundMaterial()
                if (not material or not material.GetPrim() or material.GetPrim().GetTypeName() != 'Material'
                        or str(material.GetPath()) != material_path
                        or [str(target) for target in relationship.GetTargets()] != [material_path]):
                    raise ValueError('resolved material differs')
            except Exception as error:
                raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'static scene effective material differs: ' + name) from error
            resolved.append({'prim_path':path,'material_prim_path':str(material.GetPath())})
        geometry[name] = {'source_node_path':roles[source_role],'import_node_path':roles[import_role],
                          'prim_prefix':prefix,'resolved_prims':resolved}
    metadata = {}
    for name,expected in [('upAxis','Y'),('metersPerUnit',1.0)]:
        if stage.HasAuthoredMetadata(name) is not True or not _values_match(expected, stage.GetMetadata(name)):
            raise BridgeCommandError('GRAPH_CONTRACT_UNVERIFIED', 'frozen USD metadata is not authored: ' + name)
        metadata[name] = stage.GetMetadata(name)
    return _fx_frozen_readback_version({'configuration_sha256':canonical_sha256(configuration),'profile':configuration['profile'],
            'fields':readbacks,'stage_metadata':metadata,'geometry':geometry,'target_frames':configuration['scene']['frames'],
            'native_geometry_validated':False,'render_executed':False,'visual_verified':False}, revision, saved_readback)


def _fx_initialize_manual_resolution(node, mode_parm):
    """Run the exact native menu callback on a newly owned render-settings node."""
    # Both karmarendersettings and rendersettings ship the loputils callback;
    # the rendersettings variant omits the xyz flag argument.
    expected = {"__import__('loputils').updateResolutionParameters(hou.pwd(),True)",
                "__import__('loputils').updateResolutionParameters(hou.pwd())"}
    template = mode_parm.parmTemplate()
    components = mode_parm._components()
    if (str(node.type().nameWithCategory()) not in {"Lop/karmarendersettings", "Lop/rendersettings"}
            or mode_parm.name() != "res_mode"
            or len(components) != 1 or template.scriptCallback().strip() not in expected
            or str(template.scriptCallbackLanguage()).rsplit(".", 1)[-1] != "Python"):
        raise BridgeCommandError("NATIVE_CONTROL_INTERFACE_REQUIRED", "manual resolution callback differs")
    components[0].pressButton()
    node.updateParmStates()
    mode = _fx_native_field_observation(node, "res_mode")
    resolution = _fx_native_field_observation(node, "resolution")
    resolution_parm = _resolve_parm_target(node, ["resolution"])
    if (mode["value"] != "manual" or mode["hidden"] or mode["disabled"] or mode["locked"]
            or resolution["type"] != "integer" or resolution["size"] != 2
            or resolution["hidden"] or resolution["disabled"] or resolution["locked"]
            or _parm_snapshot_is_driven(_snapshot_parm_state(mode_parm))
            or resolution_parm is None or len(resolution_parm._components()) != 2
            or _parm_snapshot_is_driven(_snapshot_parm_state(resolution_parm))):
        raise BridgeCommandError("NATIVE_CONTROL_GATE_BLOCKED", "manual resolution callback did not establish editable undriven fields")
    return {"parameter": "res_mode", "callback_executed": True, "resolution_editable_undriven": True}


def _fx_initialize_render_domain(params, pack_id, roles, pack, fresh_roles):
    import hou
    from houdini_bridge.native_render_domains import trusted_initialization_plan, trusted_node_flag_plan, renderer_parameter, NativeRenderDomainError
    root_path, _stage = _fx_task_paths(str(params["task_id"]), _fx_execution_root(params))
    if any(not str(path).startswith(root_path + "/") for path in roles.values()):
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "render layout has a foreign role")
    namespace = "/World/" + _task_name(str(params["task_id"]), "Bridge")
    bindings = {"source_node_path": roles.get("geometry_output",roles["source"]), "geometry_prim_path": namespace + "/Geometry",
                "material_output_node_path": roles.get("material_output"), "material_prim_path": namespace + "/Materials/lookdev",
                "final_lop_node_path": roles.get("settings_binding"),
                "output_image": str(_task_output_dir(params) / "beauty.$F4.exr")}
    bindings.update({name + "_prim_path": namespace + "/" + name for name in ("camera", "light", "settings", "product", "var")})
    bindings["product_prim_path"] = namespace + "/Products/renderproduct"
    try:
        renderer_observation = (_fx_native_field_observation(hou.node(roles["render"]), "renderer")
                                if "render" in roles else None)
        try:
            renderer = (renderer_parameter(hou.applicationVersionString(), {"renderer": renderer_observation})
                        if renderer_observation is not None else None)
        except NativeRenderDomainError as exc:
            observed = renderer_observation or {}
            summary = {key: repr(observed.get(key))[:100] for key in ("origin", "type", "size", "value")}
            summary["menu_tokens"] = [str(token)[:100] for token in observed.get("menu_tokens", ())[:16]]
            raise BridgeCommandError(exc.code, str(exc) + ": observed=" + repr(summary)) from exc
        plan = trusted_initialization_plan(pack_id, hou.applicationVersionString(), bindings, renderer_field=renderer)
        flags = trusted_node_flag_plan(pack_id, hou.applicationVersionString())
        configuration = params.get('frozen_render_scene')
        if configuration is not None:
            extra = _fx_frozen_scene_plan(configuration,roles,params["task_id"])
            replacements = {(write['role'],write['parm']):write for write in extra}
            plan = [replacements.pop((write['role'],write['parm']),write) for write in plan] + list(replacements.values())
    except NativeRenderDomainError as exc:
        raise BridgeCommandError(exc.code, str(exc)) from exc
    attempted, readbacks = [], {}
    try:
        for write in plan:
            node = hou.node(roles[write["role"]])
            actual = _fx_native_field_observation(node, write["parm"])
            expected_type = write["native_type"]
            permitted = {"float": {"float"}, "vector3": {"float"}, "string": {"string"},
                         "integer": {"integer"}, "toggle": {"toggle"}, "menu": {"integer", "string"},
                         "color3": {"color"}, "intvector2": {"integer"}}[expected_type]
            if actual["type"] not in permitted or actual["size"] != (3 if expected_type in {"vector3","color3"} else 2 if expected_type == "intvector2" else 1):
                raise BridgeCommandError("NATIVE_CONTROL_INTERFACE_REQUIRED", "native initialization type differs: " + write["parm"])
            parm = _resolve_parm_target(node, [write["parm"]])
            pattern_frames = _fx_output_pattern_frames(write, node, configuration)
            if write["role"] not in fresh_roles:
                if pattern_frames is not None:
                    _fx_output_pattern_readback(parm, write["value"], pattern_frames)
                elif not _values_match(write["value"], _read_parm_for_request(parm, write["value"])):
                    raise BridgeCommandError("SCENE_STATE_MISMATCH", "existing render binding differs: " + parm.path())
                continue
            if actual["hidden"] or actual["disabled"] or actual["locked"]:
                raise BridgeCommandError("NATIVE_CONTROL_GATE_BLOCKED", "native initialization is blocked: " + parm.path()[:180]
                                         + ": " + repr({key: actual[key] for key in ("type", "size", "hidden", "disabled", "locked")}))
            if expected_type == "menu" and write["value"] not in actual["menu_tokens"]:
                context = {"role": str(write["role"])[:80], "parm": str(write["parm"])[:80],
                           "node_type": str(node.type().nameWithCategory())[:120],
                           "requested_token": str(write["value"])[:80], "actual_type": str(actual["type"])[:40],
                           "size": actual["size"],
                           "menu_tokens": [str(token)[:80] for token in actual["menu_tokens"][:24]]}
                raise BridgeCommandError("NATIVE_CONTROL_INTERFACE_REQUIRED",
                                         "native initialization menu token differs: " + repr(context))
            snapshot = _snapshot_parm_state(parm)
            attempted.append((parm, snapshot))
            if _parm_snapshot_is_driven(snapshot):
                # Initializing a newly created owned node may replace its
                # factory channel. Existing scene channels remain immutable.
                for component in parm._components():
                    component.deleteAllKeyframes()
            readbacks[write["role"] + "." + write["parm"]] = _set_parm_verified(
                parm, write["value"], **({"output_pattern_frames": pattern_frames} if pattern_frames is not None else {}))
            if (write["role"] in ("settings", "settings_binding") and write["parm"] == "res_mode"
                    and write["value"] == "manual"
                    and str(node.type().nameWithCategory()) in ("Lop/karmarendersettings", "Lop/rendersettings")):
                readbacks[write["role"] + ".res_mode"]["native_callback"] = _fx_initialize_manual_resolution(node, parm)
        for write in plan:
            node = hou.node(roles[write["role"]])
            parm = _resolve_parm_target(node, [write["parm"]])
            if _parm_snapshot_is_driven(_snapshot_parm_state(parm)):
                raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "render initialization vector drifted")
            pattern_frames = _fx_output_pattern_frames(write, node, configuration)
            if pattern_frames is not None:
                _fx_output_pattern_readback(parm, write["value"], pattern_frames)
            elif not _values_match(write["value"], _read_parm_for_request(parm, write["value"])):
                raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "render initialization vector drifted")
        for flag in flags:
            node = hou.node(roles[flag["role"]])
            if flag["role"] in fresh_roles:
                getattr(node, flag["setter"])(flag["value"])
            if getattr(node, flag["getter"])() is not flag["value"]:
                raise BridgeCommandError("GRAPH_CONTRACT_UNVERIFIED", "material terminal flag differs")
        return {"bindings": bindings, "writes": readbacks, "native_semantic_contracts": {"shutter": (pack["controls"].get("shutter") or {}).get("semantic_contract")}}
    except Exception:
        for parm, snapshot in reversed(attempted):
            _restore_parm_snapshot(parm, snapshot)
        for role in reversed(tuple(fresh_roles)):
            node = hou.node(roles[role])
            if node is not None:
                node.destroy()
        raise


def _fx_resolve_type(requirement: dict[str, Any]):
    import hou

    category = _fx_category(str(requirement.get("category")))
    if category is None:
        return None
    for candidate in requirement.get("types") or []:
        node_type = hou.nodeType(category, str(candidate))
        if node_type is not None:
            return node_type
    return None


# Houdini exposes a multi-component parm as one parm template named after the
# tuple (``rad``, ``size``) while the addressable parms are the components
# (``radx/rady/radz``, ``sizex/sizey``); ``node.parm("rad")`` is None.  Probing
# aliases against template names therefore reported component aliases as
# missing.  Conversely, a tuple alias such as ``base_color`` is writable only
# through ``node.parmTuple``.  The resolver and the probe must therefore share
# both address spaces instead of assuming either spelling works everywhere.
_FX_NAMING_SCHEME_SUFFIXES: dict[str, tuple[str, ...]] = {
    "XYZW": ("x", "y", "z", "w"),
    "XYWH": ("x", "y", "w", "h"),
    "UVW": ("u", "v", "w"),
    "RGBA": ("r", "g", "b", "a"),
    "MinMax": ("min", "max"),
    "MaxMin": ("max", "min"),
    "StartEnd": ("start", "end"),
    "BeginEnd": ("begin", "end"),
    "Base1": ("1", "2", "3", "4"),
}
_FX_DEFAULT_COMPONENT_SUFFIXES = ("x", "y", "z", "w")


def _fx_template_parm_names(template: Any) -> set[str]:
    """Addressable parm names contributed by one parm template.

    A multi-component template is addressable two ways: as a tuple through
    ``node.parmTuple("base_color")`` and by component through
    ``node.parm("base_colorr")``.  Both are returned.  Note that
    ``node.parm("base_color")`` is *None* for such a template.  Runtime writes
    and probe layer (d) therefore share ``_resolve_parm_target`` and verify
    set/readback/restore rather than trusting this name set.
    """

    name = str(template.name())
    try:
        count = int(template.numComponents())
    except Exception:
        return {name}
    if count <= 1:
        return {name}
    scheme = ""
    try:
        scheme = str(template.namingScheme()).rsplit(".", 1)[-1]
    except Exception:
        scheme = ""
    suffixes = _FX_NAMING_SCHEME_SUFFIXES.get(scheme, _FX_DEFAULT_COMPONENT_SUFFIXES)
    names = {name}
    for index in range(count):
        suffix = suffixes[index] if index < len(suffixes) else str(index + 1)
        names.add("{}{}".format(name, suffix))
    return names


def _fx_addressable_parm_names(node_type: Any) -> set[str]:
    """Every parm name that can actually be addressed on this node type."""

    names: set[str] = set()
    try:
        roots = list(node_type.parmTemplateGroup().entries())
    except Exception:
        return names
    pending = list(roots)
    while pending:
        template = pending.pop()
        try:
            names |= _fx_template_parm_names(template)
        except Exception:
            pass
        try:
            pending.extend(list(template.parmTemplates()))
        except Exception:
            pass
    return names


def _fx_probe_pack(pack_id: str, pack: dict[str, Any]) -> dict[str, Any]:
    node_results: list[dict[str, Any]] = []
    parm_names_by_role: dict[str, set[str]] = {}
    supported = True
    for requirement in pack.get("nodes") or []:
        node_type = _fx_resolve_type(requirement)
        parm_names = _fx_addressable_parm_names(node_type) if node_type is not None else set()
        missing_groups = [
            aliases
            for aliases in requirement.get("required_parms") or []
            if not any(str(alias) in parm_names or any("#" in p and re.fullmatch(re.escape(p).replace(r"\#", r"[1-9][0-9]*"), str(alias)) for p in parm_names) for alias in aliases)
        ]
        available = node_type is not None and not missing_groups
        supported = supported and available
        parm_names_by_role[str(requirement.get("role"))] = parm_names
        node_results.append(
            {
                "role": requirement.get("role"),
                "category": requirement.get("category"),
                "requested_types": list(requirement.get("types") or []),
                "resolved_type": node_type.name() if node_type is not None else None,
                "missing_parameter_aliases": missing_groups,
                "available": available,
            }
        )
    control_results = []
    for name, control in sorted((pack.get("controls") or {}).items()):
        application = str(control.get("application") or "houdini")
        aliases = [str(item) for item in control.get("aliases") or []]
        host_applicable = application == "houdini"
        available = bool(host_applicable and any(alias in parm_names_by_role.get(str(control.get("role")), set()) for alias in aliases))
        control_results.append(
            {
                "name": name,
                "application": application,
                "node_role": control.get("role"),
                "parameter_aliases": aliases,
                "available": available,
                "contract_available": available,
                "runtime_verified": False,
                "routed_elsewhere": not host_applicable,
            }
        )
    houdini_control_contract_available = all(
        bool(item["available"])
        for item in control_results
        if item["application"] == "houdini"
    )
    contract_available = supported and houdini_control_contract_available
    validation = _fx_validation_state(pack_id, pack)
    result = {
        "id": pack_id,
        "version": str(pack.get("version") or "1.0.0"),
        "maturity": validation["maturity"],
        "validated_houdini_versions": list(validation["validated_houdini_versions"]),
        "simulation_cache": bool(pack.get("simulation_cache")),
        "components": list(pack.get("components") or []),
        "node_contract_available": supported,
        "semantic_control_contract_available": houdini_control_contract_available,
        "contract_available": contract_available,
        "supported_by_current_installation": bool(contract_available and validation["supported"]),
        "probe_state": "UNSUPPORTED" if not contract_available else ("SUPPORTED" if validation["supported"] else "INCONCLUSIVE"),
        "probe_layer": "contract",
        "runtime_probe_required": True,
        "preview_kind": pack.get("preview_kind", "topology_scaffold"),
        "source_plan_adapter": pack.get("source_plan_adapter"),
        "nodes": node_results,
        "semantic_controls": sorted((pack.get("controls") or {}).keys()),
        "control_probes": control_results,
        "evidence_requirements": list(pack.get("evidence") or []),
        "source_sha256": validation["source_sha256"],
        "domain_contract_sha256": validation["domain_contract_sha256"],
        "support_evidence": validation["evidence"],
    }
    identity_payload = {key: value for key, value in result.items() if key != "probe_identity"}
    result["probe_identity"] = hashlib.sha256(
        json.dumps(identity_payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8")
    ).hexdigest()
    return result


def _fx_runtime_probe_value(parm: _ResolvedParm, control: dict[str, Any]) -> Any:
    """Choose a bounded value that differs from the current temporary-node value."""

    minimum = float(control.get("minimum", 0.0))
    maximum = float(control.get("maximum", minimum))
    value_type = str(control.get("value_type") or "float")
    current = parm.eval()
    if value_type == "color3":
        midpoint = (minimum + maximum) / 2.0
        candidate = [midpoint, midpoint, midpoint]
        if isinstance(current, (list, tuple)) and len(current) == 3 and _values_match(current, candidate):
            candidate = [minimum, maximum, midpoint]
        return tuple(candidate)
    if value_type == "bool":
        return not bool(current)
    if value_type == "int":
        low = int(round(minimum))
        high = int(round(maximum))
        candidate = low if not _values_match(current, low) else high
        return candidate
    midpoint = (minimum + maximum) / 2.0
    return minimum if _values_match(current, midpoint) else midpoint


def _fx_runtime_probe_pack(pack_id: str, pack: dict[str, Any]) -> dict[str, Any]:
    """Create, connect, write/read/restore and cook a disposable pack graph.

    This is deliberately separate from the cheap contract probe.  It mutates an
    in-memory Houdini scene, destroys every node it creates, and never writes a
    task sidecar or promotes support.  Its result is suitable as one artifact
    inside a later immutable live-DCC evidence entry, not as support by itself.
    """

    import hou

    contract = _fx_probe_pack(pack_id, pack)
    result: dict[str, Any] = {
        "schema": "houdini.fx.runtime_probe/1.0",
        "id": pack_id,
        "version": str(pack.get("version") or "1.0.0"),
        "houdini_build": str(hou.applicationVersionString()),
        "source_sha256": contract["source_sha256"],
        "domain_contract_sha256": contract["domain_contract_sha256"],
        "contract_probe_identity": contract["probe_identity"],
        "contract_probe_state": contract["probe_state"],
        "node_contract_available": bool(contract["node_contract_available"]),
        "nodes": [],
        "connections": [],
        "control_probes": [],
        "cook_evidence": [],
    }
    if not contract["node_contract_available"]:
        result.update(
            {
                "runtime_executable": False,
                "runtime_probe_state": "UNSUPPORTED",
                "failure_reasons": ["node_contract_unavailable"],
            }
        )
        result["evidence_identity"] = _fx_entry_identity(result)
        return result

    task_id = "runtimeprobe{}".format(uuid4().hex)
    root_path, stage_path = _fx_task_paths(task_id)
    obj = hou.node("/obj")
    if obj is None:
        raise BridgeCommandError("SCENE_STATE_MISSING", "/obj network is missing")
    root = obj.createNode("subnet" if (pack.get("native_plan_schema") == "bridge.native-render-domains/1" or pack.get("shared_render_schema")) else "geo", root_path.rsplit("/", 1)[-1])
    _root_lease_issue(str(root.path()), task_id, scope="sop")
    roles: dict[str, Any] = {}
    created: list[Any] = [root]
    failures: list[str] = []
    try:
        for requirement in pack.get("nodes") or []:
            role = str(requirement.get("role") or "")
            node_type = _fx_resolve_type(requirement)
            if node_type is None:
                failures.append("node_type_missing:{}".format(role))
                result["nodes"].append({"role": role, "created": False, "error": "node type unavailable"})
                continue
            try:
                parent = _fx_parent_for(str(requirement.get("category") or ""), root, task_id)
                name = "{}_{}".format(_fx_node_name(role), uuid4().hex[:8])
                node = parent.createNode(node_type.name(), name)
                roles[role] = node
                created.append(node)
                result["nodes"].append(
                    {
                        "role": role,
                        "category": requirement.get("category"),
                        "requested_types": list(requirement.get("types") or []),
                        "resolved_type": node.type().name(),
                        "created": True,
                    }
                )
            except Exception as exc:
                failures.append("node_create_failed:{}".format(role))
                result["nodes"].append({"role": role, "created": False, "error": str(exc)})
        for requirement in pack.get("nodes") or []:
            role = str(requirement.get("role") or "")
            input_role = str(requirement.get("input_role") or "")
            if not input_role:
                continue
            node = roles.get(role)
            source = roles.get(input_role)
            connection = {"from": input_role, "to": role, "connected": False}
            if node is None or source is None:
                connection["error"] = "endpoint missing"
                failures.append("connection_endpoint_missing:{}:{}".format(input_role, role))
            elif node.parent() != source.parent():
                connection["error"] = "cross-context connection"
                failures.append("cross_context_connection:{}:{}".format(input_role, role))
            else:
                try:
                    node.setInput(0, source)
                    connection["connected"] = node.input(0) == source
                    if not connection["connected"]:
                        failures.append("connection_readback_mismatch:{}:{}".format(input_role, role))
                except Exception as exc:
                    connection["error"] = str(exc)
                    failures.append("connection_failed:{}:{}".format(input_role, role))
            result["connections"].append(connection)

        for name, control in sorted((pack.get("controls") or {}).items()):
            application = str(control.get("application") or "houdini")
            item: dict[str, Any] = {
                "name": name,
                "application": application,
                "node_role": control.get("role"),
                "parameter_aliases": list(control.get("aliases") or []),
            }
            if application != "houdini":
                item.update({"runtime_verified": False, "routed_elsewhere": True, "addressable": False, "writable": False})
                result["control_probes"].append(item)
                continue
            node = roles.get(str(control.get("role") or ""))
            parm = _resolve_parm_target(node, list(control.get("aliases") or []))
            if parm is None:
                item.update(
                    {
                        "runtime_verified": False,
                        "addressable": False,
                        "writable": False,
                        "readback_verified": False,
                        "restore_verified": False,
                        "error_code": "UNSUPPORTED_PARAMETER",
                    }
                )
                failures.append("control_unavailable:{}".format(name))
                result["control_probes"].append(item)
                continue
            try:
                requested = _fx_runtime_probe_value(parm, control)
                verification = _set_parm_verified(parm, requested, restore=True)
                item.update({"runtime_verified": True, "routed_elsewhere": False, "addressable": True, "writable": True, **verification})
            except BridgeCommandError as exc:
                item.update(
                    {
                        "runtime_verified": False,
                        "addressable": True,
                        "writable": False,
                        "readback_verified": False,
                        "restore_verified": False,
                        "error_code": exc.code,
                        "reason": exc.code,
                        "error": str(exc),
                    }
                )
                failures.append("control_probe_failed:{}:{}".format(name, exc.code))
            result["control_probes"].append(item)

        for requirement in pack.get("nodes") or []:
            role = str(requirement.get("role") or "")
            node = roles.get(role)
            if node is None:
                continue
            evidence = _fx_node_evidence(node)
            evidence.pop("path", None)
            evidence["role"] = role
            result["cook_evidence"].append(evidence)
            if not evidence.get("cook_succeeded"):
                failures.append("cook_failed:{}".format(role))
    finally:
        # Destroy leaf nodes first.  Root/stage deletion then removes any
        # network-owned children that were not individually destroyable.
        for node in reversed(created[1:]):
            try:
                if node is not None and node.isValid():
                    node.destroy()
            except Exception:
                pass
        stage = hou.node(stage_path)
        if stage is not None:
            try:
                stage.destroy()
            except Exception:
                pass
        try:
            if root.isValid():
                root.destroy()
        except Exception:
            pass
    result["failure_reasons"] = sorted(set(failures))
    result["semantic_control_coverage"] = {
        str(item["name"]): {
            "addressable": bool(item.get("addressable")),
            "writable": bool(item.get("writable")),
            "readback_verified": bool(item.get("readback_verified")),
            "restore_verified": bool(item.get("restore_verified")),
        }
        for item in result["control_probes"]
        if item.get("application") == "houdini"
    }
    result["runtime_executable"] = not failures
    result["runtime_probe_state"] = "INCONCLUSIVE" if not failures else "UNSUPPORTED"
    result["support_promoted"] = False
    result["evidence_identity"] = _fx_entry_identity(result)
    return result


def _fx_execution_root(params: Optional[dict[str, Any]] = None) -> Optional[str]:
    """Return the controller-authorized graph root, if this is an S-06 call."""

    binding = params.get("bridge_execution_binding") if isinstance(params, dict) else None
    if binding is None:
        return None
    if not isinstance(binding, dict):
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "short-segment host binding is not an object")
    root = binding.get("execution_root")
    if not isinstance(root, str) or not re.fullmatch(r"/obj/BRIDGE_GRAPH_[0-9a-f]{64}", root):
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "short-segment execution root is not a generated Bridge graph root")
    return root


def _fx_task_paths(task_id: str, execution_root: Optional[str] = None) -> tuple[str, str]:
    if execution_root is not None:
        return execution_root, "/stage/{}".format(_task_name(task_id, "BRIDGE_FX_STAGE"))
    return "/obj/{}".format(_task_name(task_id, "BRIDGE_FX")), "/stage/{}".format(_task_name(task_id, "BRIDGE_FX_STAGE"))


def _fx_state_path(task_id: str) -> Path:
    directory = _state_dir().parent / "fx_tasks"
    directory.mkdir(parents=True, exist_ok=True)
    return directory / "{}.json".format(_task_name(task_id, "fx"))


def _fx_write_state(task_id: str, manifest: dict[str, Any]) -> None:
    from dcc_task_runtime.platform_support import atomic_write

    path = _fx_state_path(task_id)
    payload = (json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode("utf-8")
    atomic_write(path, payload, owned_root=path.parent)


def _fx_manifest(task_id: str, required: bool = True, root_path: Optional[str] = None) -> tuple[Any, dict[str, Any]]:
    import hou

    resolved_root_path, _stage_path = _fx_task_paths(task_id, root_path)
    root = hou.node(resolved_root_path)
    manifest: dict[str, Any] = {}
    if root is not None:
        try:
            manifest = json.loads(root.userData("bridge_fx_manifest_v1") or "{}")
        except (TypeError, ValueError):
            manifest = {}
    if root_path is not None and manifest and manifest.get("execution_root") != root_path:
        manifest = {}
    if not manifest:
        state_path = _fx_state_path(task_id)
        if state_path.is_file():
            try:
                manifest = json.loads(state_path.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                manifest = {}
    if root is None and root_path is None and isinstance(manifest, dict):
        persisted_root = manifest.get("execution_root")
        if isinstance(persisted_root, str) and persisted_root.startswith("/obj/"):
            root = hou.node(persisted_root)
    if root_path is not None and manifest and manifest.get("execution_root") != root_path:
        manifest = {}
    if required and (root is None or not manifest):
        raise BridgeCommandError("SCENE_STATE_MISSING", "effect preview does not exist; run agent.fx.build_preview first")
    return root, manifest


def _fx_store_manifest(root: Any, manifest: dict[str, Any]) -> None:
    checkpoint = _fx_geometry_checkpoint(root, manifest)
    if checkpoint is not None:
        manifest['geometry_registry_checkpoint'] = checkpoint
    checkpoint = _fx_rbd_checkpoint(root, manifest)
    if checkpoint is not None:
        manifest['rbd_velocity_checkpoint'] = checkpoint
    checkpoint = _fx_particle_emission_checkpoint(root, manifest)
    if checkpoint is not None:
        manifest['particle_emission_checkpoint'] = checkpoint
    encoded = json.dumps(manifest, ensure_ascii=False, sort_keys=True)
    root.setUserData("bridge_fx_manifest_v1", encoded)
    root.setUserData("bridge_fx_pack", str(manifest.get("domain_pack") or ""))
    _fx_write_state(str(manifest.get("task_id") or ""), manifest)


_PROJECT_ENVIRONMENT_SCHEMA = "houdini.project_environment/1.0"


def _fx_project_environment_targets(task_id, root_path, roles, project_root):
    """Exact registered project resources; basename remains a filename prefix."""
    import hou
    anchor = Path(project_root)
    base = anchor / "project-environment" / hashlib.sha256(str(task_id).encode()).hexdigest()[:20]
    specs = []
    settings_role = "settings" if "settings" in roles else "render_settings"
    definitions = [
        ("usd_network", "Object/lopnet", "rendergallerysource", "gallery_database", "$HIP/galleries/$HIPNAME.$OS/rendergallery.db", None),
        (settings_role, "Lop/karmarendersettings", "dcmfilename", "deep_output", "$HIP/render/$HIPNAME.$OS.dcm.$F4.exr", "dcm"),
        (settings_role, "Lop/karmarendersettings", "productName", "render_checkpoint", "$HIP/render/$HIPNAME.$OS.$F4.checkpoint", "outputcheckpoint"),
    ]
    solver = hou.node(roles.get("solver", ""))
    if solver is not None and solver.type().nameWithCategory() == "Sop/pyrosolver":
        definitions += [
            ("solver", "Sop/pyrosolver", "checkpoint_basedir", "solver_checkpoint_directory", "$HIP/geo", "savecheckpoints"),
            ("solver", "Sop/pyrosolver", "checkpoint_basename", "solver_checkpoint_basename", "$HIPNAME.$OS", "savecheckpoints"),
        ]
    for role, kind, parameter, resource_kind, default, gate in definitions:
        path = roles.get(role)
        node = hou.node(path or "")
        if (node is None or node.type().nameWithCategory() != kind
                or not isinstance(path, str) or not path.startswith(root_path.rstrip("/") + "/")):
            raise BridgeCommandError("PROJECT_ENVIRONMENT_SCOPE_INVALID", "registered project resource role/type differs: " + role)
        directory = base / hashlib.sha256(path.encode()).hexdigest()[:20]
        prefix = "project_" + hashlib.sha256((str(task_id) + path).encode()).hexdigest()[:16]
        values = {"gallery_database": str(directory / "rendergallery.db"),
                  "deep_output": str(directory / (node.name() + ".$F4.dcm.exr")),
                  "render_checkpoint": str(directory / (node.name() + ".$F4.checkpoint")),
                  "solver_checkpoint_directory": str(directory / "geo"),
                  "solver_checkpoint_basename": prefix}
        raw = values[resource_kind].replace(os.sep, "/")
        specs.append({"role": role, "path": path, "type": kind, "parameter": parameter,
                      "resource_kind": resource_kind, "raw": raw,
                      "resource_directory": str(directory).replace(os.sep, "/"), "gate": gate,
                      "factory_default": default})
    return specs


def _fx_project_literal(node, name, task_id):
    parm = node.parm(name)
    if parm is None:
        raise BridgeCommandError("PROJECT_ENVIRONMENT_INTERFACE_REQUIRED", "project resource parameter is unavailable: " + node.path() + "/" + name)
    value, channel = _fx_scene_parameter_readback(parm, task_id)
    if channel.get("expression") is not None or channel.get("reference_path") is not None or channel.get("keyframes"):
        raise BridgeCommandError("PROJECT_ENVIRONMENT_DEFAULT_REQUIRED", "project resource channel is driven: " + parm.path())
    return parm, value, channel


def _fx_project_environment_anchor(project_root, primary_output_raw):
    from dcc_task_runtime.platform_support import _owned_path
    declared = Path(project_root).expanduser()
    primary = Path(primary_output_raw).expanduser()
    if not declared.is_absolute() or not primary.is_absolute() or primary == declared:
        raise BridgeCommandError("PROJECT_ENVIRONMENT_SCOPE_INVALID", "project root differs from the initialized output scope")
    # Preserve the initializer's output filename and subdirectories. Check both
    # original paths before resolve can hide a symbolic link.
    try:
        _owned_path(primary, declared)
    except ValueError as exc:
        raise BridgeCommandError("PROJECT_ENVIRONMENT_SCOPE_INVALID", "initialized output is outside its plain project root") from exc
    return declared.resolve()


def _fx_project_environment_readback(manifest, task_id):
    import hou
    from dcc_task_runtime.platform_support import _owned_path
    env = manifest.get("project_environment")
    root = hou.node(str(manifest.get("execution_root") or ""))
    stored = root.userData("bridge_project_environment_v1") if root is not None else None
    if env is None:
        if "project_environment_sha256" in manifest or stored:
            raise BridgeCommandError("PROJECT_ENVIRONMENT_INVALID", "frozen project environment is missing")
        return None
    if (not isinstance(env, dict) or env.get("schema") != _PROJECT_ENVIRONMENT_SCHEMA
            or env.get("task_id") != str(task_id) or manifest.get("task_id") != str(task_id)
            or not isinstance(env.get("execution_root"), str)
            or _root_for_path(env["execution_root"]) != env["execution_root"]
            or env.get("execution_root") != manifest.get("execution_root")
            or manifest.get("project_environment_sha256") != _fx_scene_contract_digest(env)):
        raise BridgeCommandError("PROJECT_ENVIRONMENT_INVALID", "project environment binding/digest differs")
    try:
        if (root is None or json.loads(stored or "null") != env
                or root.userData("bridge_project_environment_sha256") != manifest["project_environment_sha256"]):
            raise ValueError("embedded project environment differs")
    except Exception as exc:
        raise BridgeCommandError("PROJECT_ENVIRONMENT_INVALID", "embedded project environment differs") from exc
    primary = env.get("primary_output") or {}
    anchor = _fx_project_environment_anchor(str(env.get("project_root") or ""), str(primary.get("raw") or ""))
    specs = _fx_project_environment_targets(task_id, env["execution_root"], manifest["nodes"], anchor)
    if env.get("resources") != specs:
        raise BridgeCommandError("PROJECT_ENVIRONMENT_INVALID", "project resource role/path mapping differs")
    primary = env.get("primary_output") or {}
    settings_role = "settings" if "settings" in manifest["nodes"] else "render_settings"
    settings = hou.node(manifest["nodes"][settings_role])
    picture, picture_value, _channel = _fx_project_literal(settings, "picture", task_id)
    if (primary != {"role": settings_role, "path": settings.path(), "parameter": "picture", "raw": primary.get("raw")}
            or picture.unexpandedString() != primary["raw"] or picture_value != hou.expandString(primary["raw"])):
        raise BridgeCommandError("PROJECT_ENVIRONMENT_INVALID", "frozen primary output/project root differs")
    resources = []
    for spec in specs:
        _owned_path(Path(spec["resource_directory"]), anchor)
        node = hou.node(spec["path"])
        parm, value, channel = _fx_project_literal(node, spec["parameter"], task_id)
        if parm.unexpandedString() != spec["raw"]:
            raise BridgeCommandError("PROJECT_ENVIRONMENT_DRIFT", "project resource raw path differs: " + parm.path())
        expected = hou.expandString(spec["raw"])
        if value != expected:
            raise BridgeCommandError("PROJECT_ENVIRONMENT_DRIFT", "project resource evaluated path differs: " + parm.path())
        resources.append({**spec, "evaluated": value, "parameter_channel": channel})
    return {**env, "resources": resources, "primary_output": {**primary, "evaluated": picture_value}}


@contextmanager
def _fx_project_environment_transaction(root, task_id, roles, project_root, *, fresh, existing=None, enabled=True):
    """Rollback project parameter and persistence changes under the existing fence."""
    import hou
    from dcc_task_runtime.platform_support import _owned_path
    existing = existing or {}
    pending = globals().setdefault("_FX_PROJECT_ENV_RECONCILE", set())
    if root.path() in pending or root.userData("bridge_project_environment_reconcile"):
        raise BridgeCommandError("PROJECT_ENVIRONMENT_RECONCILE_REQUIRED", "project initialization has an incomplete rollback")
    if existing:
        _fx_project_environment_readback(existing, task_id)
        yield existing.get("project_environment")
        return
    if not enabled or not fresh:
        yield None
        return
    if (_host_identity().get("scene_epoch") != 0 or Path(hou.hipFile.path()).is_file()
            or root.userData("bridge_fx_manifest_v1")):
        raise BridgeCommandError("PROJECT_ENVIRONMENT_FRESH_REQUIRED", "project resources require a fresh unsaved scene")
    saves = _fx_task_saves_path(task_id)
    if saves.is_file() and json.loads(saves.read_text()).get("saves"):
        raise BridgeCommandError("PROJECT_ENVIRONMENT_FRESH_REQUIRED", "project resources cannot replace a saved project")
    settings_role = "settings" if "settings" in roles else "render_settings"
    settings = hou.node(roles[settings_role])
    picture, _value, _channel = _fx_project_literal(settings, "picture", task_id)
    anchor = _fx_project_environment_anchor(project_root, picture.unexpandedString())
    specs = _fx_project_environment_targets(task_id, root.path(), roles, anchor)
    expected_picture = picture.unexpandedString()
    prepared = []
    absent_resources = set()
    for spec in specs:
        node = hou.node(spec["path"])
        parm, value, channel = _fx_project_literal(node, spec["parameter"], task_id)
        if (str(parm.parmTemplate().type()).rsplit(".", 1)[-1].lower() != "string"
                or tuple(parm.parmTemplate().defaultValue()) != (spec["factory_default"],)
                or parm.isLocked() or parm.unexpandedString() != spec["factory_default"]):
            raise BridgeCommandError("PROJECT_ENVIRONMENT_DEFAULT_REQUIRED", "project resource is not the actual factory default: " + parm.path())
        if spec["gate"]:
            _gate_parm, gate_value, _gate_channel = _fx_project_literal(node, spec["gate"], task_id)
            if gate_value != 0:
                raise BridgeCommandError("PROJECT_ENVIRONMENT_DEFAULT_REQUIRED", "fresh project resource gate is enabled: " + spec["gate"])
        directory = Path(spec["resource_directory"])
        _owned_path(directory, anchor)
        if directory.exists() or directory.is_symlink():
            raise BridgeCommandError("PROJECT_ENVIRONMENT_RESOURCE_EXISTS", "new project resource directory already exists")
        absent_resources.add(directory)
        if spec["resource_kind"] != "solver_checkpoint_basename":
            old_path = Path(str(value)).expanduser()
            if any(parent.is_symlink() for parent in (old_path, *old_path.parents)):
                raise BridgeCommandError("PROJECT_ENVIRONMENT_RESOURCE_EXISTS", "factory resource path traverses a link")
            candidates = [old_path]
            if spec["resource_kind"] == "gallery_database":
                candidates += [old_path.parent, *(Path(str(old_path) + suffix) for suffix in ("-wal", "-shm", "-journal"))]
            if any(path.exists() or path.is_symlink() for path in candidates):
                raise BridgeCommandError("PROJECT_ENVIRONMENT_RESOURCE_EXISTS", "factory project resource already exists: " + str(old_path))
            absent_resources.update(candidates)
        prepared.append((parm, parm.unexpandedString(), value, channel, spec))
    persistence = _fx_snapshot_manifest_persistence(root, task_id)
    userdata = dict(root.userDataDict())
    env = {"schema": _PROJECT_ENVIRONMENT_SCHEMA, "task_id": str(task_id), "execution_root": root.path(),
           "project_root": str(anchor), "primary_output": {"role": settings_role, "path": settings.path(),
               "parameter": "picture", "raw": expected_picture}, "resources": specs}
    attempted = []
    try:
        for item in prepared:
            parm, _raw, _value, _channel, spec = item
            attempted.append(item)
            parm.set(spec["raw"], follow_parm_reference=False)
        root.setUserData("bridge_project_environment_v1", json.dumps(env, ensure_ascii=False, sort_keys=True))
        root.setUserData("bridge_project_environment_sha256", _fx_scene_contract_digest(env))
        probe = {"task_id": str(task_id), "execution_root": root.path(), "nodes": roles,
                 "project_environment": env, "project_environment_sha256": _fx_scene_contract_digest(env)}
        _fx_project_environment_readback(probe, task_id)
        if any(Path(spec["resource_directory"]).exists() for spec in specs):
            raise BridgeCommandError("PROJECT_ENVIRONMENT_RESOURCE_CREATED", "resource configuration unexpectedly created data")
        yield env
    except Exception as error:
        failures = []
        for parm, raw, _value, _channel, _spec in reversed(attempted):
            try:
                parm.set(raw, follow_parm_reference=False)
            except Exception as exc:
                failures.append(str(exc))
        for parm, raw, value, channel, _spec in prepared:
            try:
                if parm.unexpandedString() != raw or _fx_scene_parameter_readback(parm, task_id) != (value, channel):
                    raise ValueError("restored project channel/value differs")
            except Exception as exc:
                failures.append(str(exc))
        try:
            _fx_restore_manifest_persistence(root, persistence)
            for key in set(root.userDataDict()) - set(userdata): root.destroyUserData(key)
            for key, value in userdata.items(): root.setUserData(key, value)
            if root.userDataDict() != userdata: raise ValueError("root user data differs after restoration")
            state = persistence.get("state_path")
            if persistence.get("state_exists"):
                if state.read_bytes() != persistence["state_bytes"]: raise ValueError("sidecar bytes differ")
            elif state is not None and state.exists(): raise ValueError("fresh sidecar remains")
        except Exception as exc:
            failures.append(str(exc))
        for resource in sorted(absent_resources, key=str):
            if resource.exists() or resource.is_symlink():
                failures.append("project resource appeared during initialization: " + str(resource))
        if failures:
            pending.add(root.path())
            try: root.setUserData("bridge_project_environment_reconcile", json.dumps({"schema": "houdini.project_environment_reconcile/1", "task_id": str(task_id)}))
            except Exception: pass
            raise BridgeCommandError("PROJECT_ENVIRONMENT_RECONCILE_REQUIRED", "project environment rollback is incomplete: " + "; ".join(failures)) from error
        raise


def graph_initialize_registered_domain(task_id, selector, topology, graph_hash, output_dir, *, frozen_input_manifest=None):
    """Worker-private initialization of its freshly journaled fixed capability.

    The worker owns the process, lease and full operation fence. This function
    is deliberately absent from the public RPC command registry.
    """
    import hou
    from vfx_pipeline import graph_catalog
    from vfx_pipeline.graph_construction_inputs import freeze_construction_inputs, particle_emission_configuration, render_scene_configuration
    from dcc_task_runtime.canonical import canonical_sha256
    frozen = freeze_construction_inputs(frozen_input_manifest)
    particle_basis = particle_emission_configuration(frozen)
    configuration = render_scene_configuration(frozen, selector.get('houdini_version'))
    from houdini_bridge.native_render_scene import SUPPORTED_PROFILES
    if ((configuration is not None) != (selector.get('scene_profile') in SUPPORTED_PROFILES)
            or configuration is not None and configuration['profile'] != selector.get('scene_profile')):
        raise BridgeCommandError('STATIC_RENDER_SCENE_REQUIRED', 'registered profile and frozen input must agree')
    expected_domain = ('lighting_camera_render_v1' if selector.get('scene_profile') == 'official_karma_disklight_v1' else 'material_lookdev_v1')
    if configuration is not None and selector.get('domain_pack') != expected_domain:
        raise BridgeCommandError('STATIC_RENDER_SCENE_REQUIRED', 'static scene requires registered material domain')
    if particle_basis is not None and selector.get('domain_pack') != 'particles_v1':
        raise BridgeCommandError('PARTICLE_EMISSION_DOMAIN_REQUIRED', 'particle basis requires the particles domain')
    compiled = graph_catalog.compile_proposal(selector)
    schedule = graph_catalog.bounded_domain_schedule(compiled)
    if schedule is None or compiled.graph_hash != graph_hash or hou.applicationVersionString() != selector['houdini_version']:
        raise BridgeCommandError('SCENE_STATE_MISMATCH','registered domain initialization identity differs')
    root_path = '/obj/BRIDGE_GRAPH_' + hashlib.sha256((task_id+':'+graph_hash).encode()).hexdigest()
    layout = graph_catalog.native_layout(compiled,root_path)
    expected = {address:row['path'] for address,row in layout.items()}
    if topology.get('root') != root_path or topology.get('nodes') != expected:
        raise BridgeCommandError('SCENE_OWNERSHIP_REQUIRED','registered domain topology differs')
    _root_lease_check(root_path,task_id=task_id,scope='sop')
    root = hou.node(root_path)
    if root is None or root.type().name() != graph_catalog.native_root_type(compiled) or root.userData('bridge_fx_owned') is not None:
        raise BridgeCommandError('SCENE_CONFLICT','fresh registered domain root is unavailable')
    actual = {node.path():node for node in root.allSubChildren(recurse_in_locked_nodes=False)}
    if set(actual) != set(expected.values()):
        raise BridgeCommandError('SCENE_STATE_MISMATCH','registered domain contains unexpected native nodes')
    for address,row in layout.items():
        node = actual[row['path']]
        expected_category = 'Object' if row['category'] == 'Obj' else row['category']
        if node.type().name() != row['type'] or node.type().category().name() != expected_category or node.parent().path() != row['parent']:
            raise BridgeCommandError('SCENE_STATE_MISMATCH','registered domain native layout differs')
    roles = {node.node_id:expected[node.address] for node in compiled.nodes}
    if selector.get('scene_profile') == 'bounded_geometry_rig_v1':
        from vfx_pipeline.geometry_graph import role_nodes
        roles = {role:row['path'] for role,row in role_nodes(compiled,root_path).items()}
    if configuration is not None and configuration['profile'] == 'official_karma_disklight_v1':
        from houdini_bridge.official_karma_scene_host import initialize
        root.setUserData('bridge_fx_owned','1')
        with _root_lease_fence(root_path,task_id=task_id,scope='sop'):
            readback=initialize(hou,configuration,roles)
            manifest={'schema':'houdini.fx.scene_manifest/1.0','task_id':task_id,
                'domain_pack':selector['domain_pack'],'pack_version':'1.0.0','houdini_version':hou.applicationVersionString(),
                'hip_path':hou.hipFile.path(),'execution_root':root_path,'short_segment_scoped':True,
                'nodes':roles,'build_state':'BUILT_VERIFIED','candidate_patch':{},'native_initialization':readback,
                'graph_hash':graph_hash,'registered_domain_schedule':schedule,'seed':0,
                'connections':{'verified':topology['connections']},'frozen_render_scene':configuration,
                'frozen_render_scene_sha256':canonical_sha256(configuration),'frozen_scene_plan_revision':2,
                'execution_assessment':{'domain_graph_constructed':True,'native_graph_contract':readback,
                    'simulation_executed':False,'render_validated':False}}
            _fx_store_manifest(root,manifest)
        return {'schema':'bridge.registered-domain-initialization/1','task_id':task_id,'graph_hash':graph_hash,
            'schedule_sha256':schedule['schedule_sha256'],'domain_pack':selector['domain_pack'],'nodes':roles,
            'native_readback':readback,'frozen_inputs_sha256':canonical_sha256(frozen)}
    params = {'task_id':task_id,'constraints':{'fx':{'domain_pack':selector['domain_pack'],'run_mode':'diagnose'}},
        'render':{'output_dir':str(output_dir)},'bridge_execution_binding':{'execution_root':root_path},
        'frozen_input_manifest': frozen}
    if particle_basis is not None:
        params['constraints']['fx']['particle_emission_basis'] = particle_basis
    if selector.get('native_branch') is not None:
        params['constraints']['fx']['vellum_branch'] = selector['native_branch']
    if configuration is not None:
        params['frozen_render_scene'] = configuration
    pack_id,pack = _fx_pack(params)
    root.setUserData('bridge_fx_owned','1')
    with _root_lease_fence(root_path,task_id=task_id,scope='sop'), (
            _fx_geometry_build_transaction(root_path) if pack_id == 'procedural_geometry_v1' else nullcontext()), (
            _fx_particle_emission_host().build_transaction(root_path) if pack_id == 'particles_v1' else nullcontext()):
        count_state = {role:_fx_initialize_new_owned_counts(actual[path]) for role,path in roles.items()}
        initialization = (_fx_initialize_planned_domain(params,pack_id,roles,pack,set(roles))
            if pack.get('shared_render_schema') else _fx_initialize_render_domain(params,pack_id,roles,pack,set(roles)))
        initialization['new_owned_multiparms'] = count_state
        for role,path in roles.items():
            if actual[path].type().nameWithCategory() == 'Lop/karmarendersettings':
                color_route = ({'source': 'scene_linear', 'output': 'ACEScg'}
                               if configuration is not None and configuration.get('profile') in ('sphere_ground_v2', 'bounded_geometry_rig_v1') else None)
                initialization[role+'.exr_format'] = _fx_configure_render_output(
                    actual[path], output_color_route=color_route)
        with _fx_project_environment_transaction(root, task_id, roles, output_dir, fresh=True,
                enabled=(configuration is not None and configuration.get('profile') in ('sphere_ground_v2', 'bounded_geometry_rig_v1')
                    or selector.get('domain_pack') == 'procedural_geometry_v1')) as project_environment:
            readback = _fx_static_domain_readback(pack_id,roles,pack)
            manifest = {'schema':'houdini.fx.scene_manifest/1.0','task_id':task_id,'domain_pack':pack_id,'pack_version':'1.0.0',
                'houdini_version':hou.applicationVersionString(),'hip_path':hou.hipFile.path(),'execution_root':root_path,
                'short_segment_scoped':True,'nodes':roles,'build_state':'BUILT_VERIFIED','candidate_patch':{},
                'native_initialization':initialization,'graph_hash':graph_hash,'registered_domain_schedule':schedule,'seed':0,
                'connections':{'declared':pack['connections'] if pack.get('shared_render_schema') else _fx_render_domain_connections(pack_id,roles),'verified':topology['connections']},
                'execution_assessment':{'domain_graph_constructed':True,'native_graph_contract':readback,
                    'simulation_executed':False,'render_validated':False}}
            if configuration is not None:
                from houdini_bridge.native_render_scene import PARAMETER_PLAN_REVISION
                manifest['frozen_render_scene'] = configuration
                manifest['frozen_render_scene_sha256'] = canonical_sha256(configuration)
                manifest['frozen_scene_plan_revision'] = PARAMETER_PLAN_REVISION
                readback['frozen_scene_parameters'] = _fx_frozen_scene_readback(configuration,roles,pack,task_id=task_id)
            if project_environment is not None:
                manifest['project_environment'] = project_environment
                manifest['project_environment_sha256'] = _fx_scene_contract_digest(project_environment)
            _fx_store_manifest(root,manifest)
    return {'schema':'bridge.registered-domain-initialization/1','task_id':task_id,'graph_hash':graph_hash,
        'schedule_sha256':schedule['schedule_sha256'],'domain_pack':pack_id,'nodes':roles,'native_readback':readback,
        'frozen_inputs_sha256': canonical_sha256(frozen)}


def _fx_particle_emission_graph_checkpoint(task_id, manifest, embedded, path, digest):
    checkpoint = embedded.get('particle_emission_checkpoint')
    if checkpoint is None:
        return None
    saves_path = _fx_task_saves_path(task_id)
    try:
        store = json.loads(saves_path.read_text(encoding='utf-8')) if saves_path.is_file() else {}
        active = store.get('active_scene') or {}
        source = path
        if (Path(str(active.get('snapshot_path') or '')).resolve() == path
                and active.get('snapshot_sha256') == digest
                and active.get('identity') == _host_identity()):
            source = Path(str(active.get('path') or '')).resolve()
        matching = [record for record in store.get('saves', [])
                    if Path(str(record.get('path') or '')).resolve() == source
                    and record.get('sha256') == digest]
        saved = matching[-1] if matching else {}
        contract = saved.get('scene_contract')
        if (type(contract) is not dict or contract.get('task_id') != task_id
                or contract.get('execution_root') != manifest.get('execution_root')
                or contract.get('graph_hash') != manifest.get('graph_hash')
                or saved.get('scene_contract_sha256') != _fx_scene_contract_digest(contract)
                or contract.get('particle_emission_checkpoint') != checkpoint):
            raise BridgeCommandError('PARTICLE_EMISSION_REOPEN_AUTHORITY_REQUIRED', 'graph handoff requires its exact registered save contract')
    except (OSError, ValueError, TypeError, IndexError) as error:
        raise BridgeCommandError('PARTICLE_EMISSION_REOPEN_AUTHORITY_REQUIRED', 'registered particle save contract is unavailable') from error
    _fx_verify_scene_contract(contract, task_id)
    return checkpoint


def _fx_bind_graph_trial(params: dict[str, Any]) -> dict[str, Any]:
    """Bind an already verified graph trial to the FX operation surface.

    This is the controller-to-host handoff for the software/formal assembly.
    It never creates a substitute FX graph and never accepts a caller-provided
    ``BUILT_VERIFIED`` marker.  The graph worker's persisted completion result
    is checked against the live Houdini node topology, then the add-on derives
    the operation manifest from those actual nodes under a newly issued lease.
    """
    import hou

    task_id = str(params.get("task_id") or "").strip()
    receipt = params.get("trial_receipt")
    if not task_id or not isinstance(receipt, dict):
        raise BridgeCommandError("INVALID_ARGUMENT", "completed graph trial receipt and task_id are required")
    result = receipt.get("result") if isinstance(receipt.get("result"), dict) else receipt
    if receipt.get("state") != "SUCCEEDED" or receipt.get("stop_confirmed") is not True:
        raise BridgeCommandError("SCENE_STATE_MISMATCH", "graph trial is not in a completed state")
    if not isinstance(result, dict) or result.get("construction_executed") is not True \
            or result.get("reconciliation_required") is True:
        raise BridgeCommandError("SCENE_STATE_MISMATCH", "graph trial has no trusted completed construction result")
    verification = result.get("verification")
    artifact = result.get("artifact")
    if (not isinstance(verification, dict)
            or any(verification.get(key) is not True for key in
                   ("nodes_verified", "parameters_verified", "connections_verified"))
            or not isinstance(artifact, dict)
            or not isinstance(artifact.get("sha256"), str)):
        raise BridgeCommandError("SCENE_STATE_MISMATCH", "graph trial lacks sealed artifact verification")
    hip_path = Path(str(hou.hipFile.path() or "")).expanduser().resolve()
    if (not hip_path.is_file()
            or not hmac.compare_digest(_fx_sha256_file(hip_path), str(artifact["sha256"]))):
        raise BridgeCommandError("ARTIFACT_MISMATCH", "live task host is not bound to the verified graph-trial HIP")
    topology = result.get("topology")
    graph_hash = str(result.get("graph_hash") or "")
    if not isinstance(topology, dict) or not re.fullmatch(r"[0-9a-f]{64}", graph_hash):
        raise BridgeCommandError("SCENE_STATE_MISMATCH", "graph trial topology/hash evidence is incomplete")
    expected_root = "/obj/BRIDGE_GRAPH_" + hashlib.sha256(
        (task_id + ":" + graph_hash).encode("utf-8")).hexdigest()
    graph_root = str(topology.get("root") or "")
    if graph_root != expected_root or not _GRAPH_ROOT_NAME.fullmatch(graph_root.rsplit("/", 1)[-1]):
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "graph trial root is not derived from the task and graph hash")
    root = hou.node(graph_root)
    node_map = topology.get("nodes")
    connections = topology.get("connections")
    if root is None or not isinstance(node_map, dict) or not node_map or not isinstance(connections, list):
        raise BridgeCommandError("SCENE_STATE_MISSING", "completed graph topology is unavailable in the live host")
    actual_nodes: dict[str, Any] = {}
    for address, path in node_map.items():
        if not isinstance(address, str) or not re.fullmatch(r"houdini_(?:sop|obj|lop|vop|rop|dop):/[A-Za-z_][A-Za-z0-9_]{0,99}(?:/[A-Za-z_][A-Za-z0-9_]{0,99}){0,7}", address):
            raise BridgeCommandError("SCENE_STATE_MISMATCH", "graph topology contains an invalid node address")
        if not isinstance(path, str) or not path.startswith(graph_root + "/") or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,99}(?:/[A-Za-z_][A-Za-z0-9_]{0,99}){0,7}",path[len(graph_root)+1:]):
            raise BridgeCommandError("SCENE_STATE_MISMATCH", "graph topology contains a node outside its owned root")
        node = hou.node(path)
        if node is None:
            raise BridgeCommandError("SCENE_STATE_MISSING", "verified graph node is missing from the live host")
        expected_category = {'houdini_rop':'driver', 'houdini_obj':'object'}.get(
            address.split(':',1)[0], address.split(':',1)[0][8:])
        if node.type().category().name().lower() != expected_category:
            raise BridgeCommandError('SCENE_STATE_MISMATCH','graph native address category differs')
        actual_nodes[address] = node
    if set(n.path() for n in root.allSubChildren(recurse_in_locked_nodes=False)) != set(node_map.values()):
        raise BridgeCommandError('SCENE_STATE_MISMATCH','graph contains unexpected native descendants')
    _,embedded = _fx_manifest(task_id,required=False,root_path=graph_root)
    schedule = embedded.get('registered_domain_schedule')
    if schedule:
        from vfx_pipeline import graph_catalog
        compiled = graph_catalog.compile_proposal(schedule.get('identity'))
        expected_schedule = graph_catalog.bounded_domain_schedule(compiled)
        layout = graph_catalog.native_layout(compiled,graph_root)
        if (schedule != expected_schedule or compiled.graph_hash != graph_hash or
                node_map != {a:row['path'] for a,row in layout.items()} or
                root.type().name() != graph_catalog.native_root_type(compiled)):
            raise BridgeCommandError('SCENE_STATE_MISMATCH','domain composition differs from its fixed registration')
    for connection in connections:
        if not isinstance(connection, dict):
            raise BridgeCommandError("SCENE_STATE_MISMATCH", "graph connection evidence is malformed")
        source = hou.node(str(connection.get("source") or ""))
        destination = hou.node(str(connection.get("destination") or ""))
        if source is None or destination is None or not str(connection.get("destination") or "").startswith(graph_root + "/"):
            raise BridgeCommandError("SCENE_STATE_MISSING", "verified graph connection endpoint is missing")
        kind=connection.get('kind','wire')
        if kind == 'reference':
            field=connection.get('field')
            parm=destination.parm(field) if isinstance(field,str) else None
            if parm is None or parm.eval() != source.path():
                raise BridgeCommandError('SCENE_STATE_MISMATCH','live graph reference differs from the verified trial')
        elif kind == 'container_dependency':
            if source.parent() is not destination:
                raise BridgeCommandError('SCENE_STATE_MISMATCH','live graph container dependency differs')
        elif kind == 'wire':
            index = connection.get('input_index');output_index=connection.get('output_index',0)
            actual={(wire.inputIndex(),wire.inputNode().path(),wire.outputIndex()) for wire in destination.inputConnections()}
            if type(index) is not int or type(output_index) is not int or (index,source.path(),output_index) not in actual:
                raise BridgeCommandError('SCENE_STATE_MISMATCH','live graph connection differs from the verified trial')
        else:
            raise BridgeCommandError('SCENE_STATE_MISMATCH','graph connection kind is invalid')
    exact_nodes = {address.rsplit("/", 1)[-1]: path for address, path in node_map.items()}
    if (schedule or {}).get('identity',{}).get('scene_profile') == 'bounded_geometry_rig_v1':
        from vfx_pipeline.geometry_graph import role_nodes
        exact_nodes = {role:row['path'] for role,row in role_nodes(compiled,graph_root).items()}
    if schedule:
        # A verified registered schedule keeps the compiler's exact role
        # mapping: genuine source/output roles are already part of it, and no
        # alias is guessed for a pack without them, because a synthetic role
        # duplicates a real public node in the save contract.
        if len(exact_nodes) != len(node_map):
            raise BridgeCommandError("SCENE_STATE_MISMATCH", "registered roles collide on public node names")
        bound_nodes = exact_nodes
    else:
        source = next((node for address, node in actual_nodes.items() if address.endswith("/source")), None)
        output = next((node for address, node in actual_nodes.items() if address.endswith("/sink")), None)
        if source is None:
            source = next(iter(actual_nodes.values()))
        if output is None:
            output = list(actual_nodes.values())[-1]
        bound_nodes = {**exact_nodes, "source": source.path(), "output": output.path()}
    existing_root, existing = _fx_manifest(task_id, required=False, root_path=graph_root)
    if existing and existing.get("execution_root") not in {None, graph_root}:
        raise BridgeCommandError("SCENE_CONFLICT", "task already has a different execution root")
    lease = _root_lease_read(graph_root)
    if lease is None:
        _root_lease_issue(graph_root, task_id, scope="sop")
    else:
        _root_lease_check(graph_root, task_id=task_id, scope="sop")
    manifest = {
        **(existing if isinstance(existing, dict) else {}),
        "schema": "houdini.fx.scene_manifest/1.0",
        "task_id": task_id,
        "domain_pack": (schedule or {}).get("identity",{}).get("domain_pack","pyro_smoke_v1"),
        "pack_version": "1.0.0",
        "maturity": "software_formal_graph_binding",
        "houdini_version": hou.applicationVersionString(),
        "hip_path": hou.hipFile.path(),
        "execution_root": graph_root,
        "short_segment_scoped": True,
        "nodes": bound_nodes,
        "build_state": "BUILT_VERIFIED",
        "connections": {"verified": connections, "source": "graph_trial_completion"},
        "input_digest": graph_hash,
        "graph_hash": graph_hash,
        "graph_trial_operation_id": str(receipt.get("operation_id") or result.get("operation_id") or ""),
        "graph_trial_evidence": {
            "construction_executed": True,
            "nodes_verified": True,
            "parameters_verified": bool((result.get("verification") or {}).get("parameters_verified", True)),
            "connections_verified": True,
            "hip_sha256": str((result.get("artifact") or {}).get("sha256") or ""),
        },
        "execution_assessment": {
            "source_only_construction": True,
            "simulation_executed": False,
            "render_validated": False,
            "build_state": "BUILT_VERIFIED",
            "frame_verification": "deferred_to_operation",
        },
    }
    with _root_lease_fence(graph_root, task_id=task_id, scope="sop"):
        if root.userData("bridge_fx_owned") not in {None, "1"}:
            raise BridgeCommandError("SCENE_CONFLICT", "graph root is owned by another scene contract")
        persistence = _fx_snapshot_manifest_persistence(root, task_id)
        try:
            root.setUserData("bridge_fx_owned", "1")
            checkpoint = embedded.get('geometry_registry_checkpoint')
            rbd_checkpoint = _fx_rbd_checkpoint(root, manifest)
            if embedded.get('rbd_velocity_checkpoint') is not None and rbd_checkpoint != embedded['rbd_velocity_checkpoint']:
                raise BridgeCommandError('RBD_REOPEN_AUTHORITY_REQUIRED', 'graph handoff cannot authorize an embedded saved velocity checkpoint')
            particle_checkpoint = _fx_particle_emission_graph_checkpoint(task_id, manifest, embedded, hip_path, artifact['sha256'])
            with _fx_geometry_reopen_transaction(task_id, manifest, checkpoint, hip_path, artifact['sha256']) as restored, _fx_particle_emission_reopen_transaction(
                    task_id, manifest, particle_checkpoint, hip_path, artifact['sha256']) as particle_restored:
                _fx_store_manifest(root, manifest)
        except Exception:
            _fx_restore_manifest_persistence(root, persistence)
            raise
    return {"graph_ready": True, "task_id": task_id, "execution_root": graph_root,
            "operation_id": manifest["graph_trial_operation_id"], "nodes_verified": True,
            "connections_verified": True, "geometry_registry_restored": restored,
            "rbd_velocity_restored": False, "particle_emission_restored": particle_restored}


def _fx_snapshot_manifest_persistence(root: Any, task_id: str) -> dict[str, Any]:
    """Capture both embedded and sidecar state before candidate persistence."""

    if not callable(getattr(root, "userData", None)) or not callable(
        getattr(root, "setUserData", None)
    ):
        # Lightweight unit doubles may not implement Houdini user data.  A real
        # scene node always does, and production snapshots below are fail-closed.
        return {"available": False}
    try:
        path = _fx_state_path(task_id)
        state_exists = path.is_file()
        state_bytes = path.read_bytes() if state_exists else None
        state_mode = stat.S_IMODE(path.stat().st_mode) if state_exists and os.name != "nt" else None
        return {
            "available": True,
            "task_id": task_id,
            "embedded_manifest": root.userData("bridge_fx_manifest_v1"),
            "embedded_pack": root.userData("bridge_fx_pack"),
            "state_path": path,
            "state_exists": state_exists,
            "state_bytes": state_bytes,
            "state_mode": state_mode,
        }
    except Exception as exc:
        raise BridgeCommandError(
            "CANDIDATE_PERSIST_SNAPSHOT_FAILED",
            "could not snapshot the existing candidate manifest: {}".format(exc),
        ) from exc


def _fx_restore_manifest_persistence(root: Any, snapshot: dict[str, Any]) -> None:
    if not snapshot.get("available"):
        return
    errors: list[str] = []
    for key, value in (
        ("bridge_fx_manifest_v1", snapshot.get("embedded_manifest")),
        ("bridge_fx_pack", snapshot.get("embedded_pack")),
    ):
        try:
            if value is None:
                if root.userData(key) is not None:
                    root.destroyUserData(key)
                if root.userData(key) is not None:
                    raise ValueError("user data remains after restoration")
            else:
                root.setUserData(key, str(value))
        except Exception as exc:
            errors.append("{}:{}".format(key, exc))
    path = snapshot.get("state_path")
    if isinstance(path, Path):
        try:
            if snapshot.get("state_exists"):
                temporary = path.with_name(".{}.{}.rollback".format(path.name, uuid4().hex))
                try:
                    temporary.write_bytes(snapshot.get("state_bytes") or b"")
                    if os.name != "nt" and snapshot.get("state_mode") is not None:
                        temporary.chmod(int(snapshot["state_mode"]))
                    temporary.replace(path)
                finally:
                    temporary.unlink(missing_ok=True)
            else:
                path.unlink(missing_ok=True)
        except Exception as exc:
            errors.append("sidecar:{}".format(exc))
    if errors:
        raise BridgeCommandError(
            "CANDIDATE_MANIFEST_ROLLBACK_FAILED",
            "could not restore candidate manifest persistence: {}".format(", ".join(errors)),
        )


def _fx_parent_for(category: str, root: Any, task_id: str, execution_root: Optional[str] = None, *, requirement=None, roles=None):
    import hou

    parent_role = (requirement or {}).get("parent_role") or (requirement or {}).get("context_parent_role")
    if parent_role:
        parent = hou.node(str((roles or {}).get(parent_role) or ""))
        if parent is None or not parent.path().startswith(root.path().rstrip("/") + "/"):
            raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "context parent is outside the task layout")
        expected = {"sop":"Sop","dop":"Dop","lop":"Lop","vop":"Vop","rop":"Driver"}.get(category)
        if expected is None or str(parent.childTypeCategory().name()) != expected:
            raise BridgeCommandError("UNSUPPORTED_NODE", "context parent has the wrong native child category")
        return parent
    if category == "obj":
        if str(root.childTypeCategory().name()) != "Obj":
            raise BridgeCommandError("UNSUPPORTED_NODE", "multi-context task requires an Object subnet")
        return root
    if category == "sop":
        return root
    if category == "dop":
        simulation = root.node(_fx_node_name("simulation"))
        if simulation is None:
            raise BridgeCommandError("SCENE_STATE_MISSING", "owned simulation network must be created before DOP children")
        return simulation
    if execution_root is not None:
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "short-segment construction is limited to the leased SOP graph root")
    if category == "vop":
        return hou.node("/mat") or hou.node("/").createNode("mat", "mat")
    if category == "lop":
        _root_path, stage_path = _fx_task_paths(task_id)
        stage = hou.node(stage_path)
        if stage is not None:
            return stage
        stage_parent = hou.node("/stage")
        if stage_parent is None:
            stage_parent = hou.node("/").createNode("lopnet", "stage")
        return stage_parent.createNode("subnet", stage_path.rsplit("/", 1)[-1])
    raise BridgeCommandError("UNSUPPORTED_NODE", "unsupported node category: {}".format(category))


def _fx_node_name(role: str) -> str:
    safe = "".join(character if character.isalnum() else "_" for character in role.upper())
    return "FX_{}".format(safe[:48])


_SOURCE_PLAN_RULES: dict[str, tuple[str, Optional[float], Optional[float]]] = {
    "emission_start_frame": ("int", 0.0, 100000.0),
    "emission_end_frame": ("int", 0.0, 100000.0),
    "direction": ("vector3", -1.0, 1.0),
    "spread_angle_deg": ("float", 0.0, 180.0),
    "speed_tier": ("enum", None, None),
    "body_scale": ("float", 0.01, 100.0),
    "ground_spread": ("float", 0.0, 100.0),
    "protected_features": ("string_list", None, None),
    "roi": ("vector4", 0.0, 1.0),
    "time_range": ("frame_range", None, None),
    "estimated_speed_magnitude": ("float", 0.1, 20.0),
    "pulse_count": ("int", 1.0, 3.0),
    "source_radius": ("float", 0.01, 10.0),
    "density": ("float", 0.0, 10.0),
    "dissipation": ("float", 0.0, 5.0),
    "voxel_size": ("float", 0.005, 1.0),
}


def _fx_source_input_binding(params: dict[str, Any]) -> str:
    inputs = params.get("inputs") if isinstance(params.get("inputs"), list) else []
    bound = [
        {
            "asset_id": str(item.get("asset_id") or ""),
            "role": str(item.get("role") or ""),
            "sha256": str(item.get("sha256") or "").lower(),
        }
        for item in inputs
        if isinstance(item, dict) and str(item.get("sha256") or "")
    ]
    return hashlib.sha256(
        json.dumps(bound, ensure_ascii=False, separators=(",", ":"), sort_keys=True, allow_nan=False).encode("utf-8")
    ).hexdigest()


def _fx_validate_source_plan_value(name: str, value: Any, value_type: str, minimum: Optional[float], maximum: Optional[float]) -> Any:
    if value_type == "int":
        if isinstance(value, bool) or not isinstance(value, int):
            raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} must be an integer".format(name))
        number = float(value)
        if minimum is not None and number < minimum or maximum is not None and number > maximum:
            raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} is outside its registered range".format(name))
        return int(value)
    if value_type == "float":
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(float(value)):
            raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} must be a finite number".format(name))
        number = float(value)
        if minimum is not None and number < minimum or maximum is not None and number > maximum:
            raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} is outside its registered range".format(name))
        return number
    if value_type in {"vector3", "vector4"}:
        count = 3 if value_type == "vector3" else 4
        if not isinstance(value, (list, tuple)) or len(value) != count:
            raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} must contain {} numbers".format(name, count))
        result = []
        for item in value:
            if isinstance(item, bool) or not isinstance(item, (int, float)) or not math.isfinite(float(item)):
                raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} contains a non-finite component".format(name))
            number = float(item)
            if minimum is not None and number < minimum or maximum is not None and number > maximum:
                raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} is outside its registered range".format(name))
            result.append(number)
        return result
    if value_type == "enum":
        rendered = str(value or "").casefold()
        if name != "speed_tier" or rendered not in {"slow", "medium", "fast", "very_fast"}:
            raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} contains an unsupported enum value".format(name))
        return rendered
    if value_type == "string_list":
        if not isinstance(value, (list, tuple)) or len(value) > 32 or not all(isinstance(item, str) and item.strip() for item in value):
            raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} must be a bounded text array".format(name))
        if len(set(value)) != len(value):
            raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} contains duplicate values".format(name))
        return list(value)
    if value_type == "frame_range":
        if not isinstance(value, dict) or set(value) != {"start", "end", "step"}:
            raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} must be a strict frame range".format(name))
        start, end, step = value["start"], value["end"], value["step"]
        if any(isinstance(item, bool) or not isinstance(item, int) for item in (start, end, step)) or start > end or step <= 0:
            raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} has an invalid frame range".format(name))
        return {"start": start, "end": end, "step": step}
    raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "{} has an unsupported control type".format(name))


def _fx_source_plan_host_patch(params: dict[str, Any], pack_id: str, pack: dict[str, Any]) -> Optional[dict[str, Any]]:
    """Validate the typed visual source plan and compile it to real host controls.

    This is deliberately host-side.  Recipe metadata is not trusted as proof
    that a plan was consumed.  Unknown controls, digest drift and source-input
    drift are rejected before any scene mutation.
    """
    fx = _fx_configuration(params)
    raw_plan = fx.get("source_plan")
    if raw_plan is None:
        return None
    if pack_id != "pyro_smoke_v1":
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "source plans are currently implemented only for pyro_smoke_v1")
    if not isinstance(raw_plan, dict) or raw_plan.get("schema_version") != "1.0" or raw_plan.get("ready") is not True:
        raise BridgeCommandError("INVALID_SOURCE_CONTROL", "a ready typed source_plan/1.0 is required")
    supplied_plan_sha = str(fx.get("source_plan_sha256") or "").lower()
    actual_plan_sha = hashlib.sha256(
        json.dumps(raw_plan, ensure_ascii=False, separators=(",", ":"), sort_keys=True, allow_nan=False).encode("utf-8")
    ).hexdigest()
    if supplied_plan_sha != actual_plan_sha:
        raise BridgeCommandError("SOURCE_PLAN_DRIFT", "source_plan_sha256 does not match the host-received source plan")
    supplied_input_binding = str(fx.get("source_input_binding_sha256") or "").lower()
    if supplied_input_binding != _fx_source_input_binding(params):
        raise BridgeCommandError("SOURCE_BINDING_DRIFT", "source input bytes/identity binding changed before host execution")
    raw_entries = list(raw_plan.get("controls") or []) + list(raw_plan.get("defaults") or [])
    if not raw_entries or any(not isinstance(item, dict) for item in raw_entries):
        raise BridgeCommandError("INVALID_SOURCE_CONTROL", "source plan controls/defaults must be typed arrays")
    values: dict[str, Any] = {}
    for item in raw_entries:
        name = str(item.get("name") or "")
        if name not in _SOURCE_PLAN_RULES or name in values:
            raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "unregistered or duplicate source control: {}".format(name or "<empty>"))
        expected_type, minimum, maximum = _SOURCE_PLAN_RULES[name]
        if str(item.get("value_type") or "") != expected_type:
            raise BridgeCommandError("INVALID_SOURCE_CONTROL", "{} has an unexpected type declaration".format(name))
        values[name] = _fx_validate_source_plan_value(name, item.get("value"), expected_type, minimum, maximum)
    missing = sorted(set(_SOURCE_PLAN_RULES) - set(values))
    if missing:
        raise BridgeCommandError("INVALID_SOURCE_CONTROL", "source plan is missing controls: {}".format(", ".join(missing)))
    if fx.get("source_controls") != values:
        raise BridgeCommandError("SOURCE_PLAN_DRIFT", "source_controls do not exactly match the typed source plan")

    direction = values["direction"]
    norm = math.sqrt(sum(component * component for component in direction))
    if norm < 1.0e-9:
        raise BridgeCommandError("INVALID_SOURCE_CONTROL", "source direction must be nonzero")
    direction = [component / norm for component in direction]
    expected_speed = {"slow": 1.0, "medium": 2.5, "fast": 5.0, "very_fast": 8.0}[values["speed_tier"]]
    if abs(values["estimated_speed_magnitude"] - expected_speed) > 1.0e-9:
        raise BridgeCommandError("SOURCE_PLAN_DRIFT", "estimated speed does not match speed_tier")
    frame_range = values["time_range"]
    if not (frame_range["start"] <= values["emission_start_frame"] <= values["emission_end_frame"] <= frame_range["end"]):
        raise BridgeCommandError("INVALID_SOURCE_CONTROL", "emission frames must be inside the observed time_range")
    # Explicit source contract: full cone angle, velocity in scene units/sec,
    # finite inclusive integer-frame window, N on bands separated by off bands.
    # No semantic control is disguised as a solver noise parameter.
    start, end = values["emission_start_frame"], values["emission_end_frame"]
    segments = 2 * values["pulse_count"] - 1
    duration = end - start + 1
    if duration < segments:
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "emission window is too short for separated integer-frame pulses")
    edges = [start + index * duration // segments for index in range(segments + 1)]
    pulses = [[edges[index], edges[index + 1]] for index in range(0, segments, 2)]
    radius = values["source_radius"] * values["body_scale"]
    # Bounded footprint widening, not an asserted ground-contact simulation.
    ground_factor = 1.0 + values["ground_spread"] / 100.0
    radii = [radius * ground_factor, radius, radius * ground_factor]
    voxel = values["voxel_size"]
    estimated_cells = math.prod(math.ceil(2 * r / voxel) + 3 for r in radii)
    if estimated_cells > 4000000:
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "source bounds exceed the registered four-million-cell construction budget")
    program = _fx_source_program(pulses, direction, values["spread_angle_deg"], expected_speed, values["density"])
    compiled: dict[str, Any] = {}
    for name, raw_value in {"density_scale": 1.0, "voxel_size": voxel, "dissipation": values["dissipation"]}.items():
        control = (pack.get("controls") or {}).get(name)
        if control is None or str(control.get("application") or "houdini") != "houdini":
            raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "source-plan host binding is unavailable: {}".format(name))
        compiled[name] = _fx_coerce_control(name, raw_value, control)
    compiled.update({
        "source_radii": radii, "source_mode": "Volume Scatter", "source_particle_separation": 2.0 * voxel,
        "source_run_over": "Points", "source_group": "", "source_program": program,
        "source_raster_attributes": "density v", "source_raster_voxel_size": voxel,
    })
    solver_sourcing = _fx_solver_sourcing_binding(values, frame_range, pulses)
    return {
        "plan_sha256": actual_plan_sha, "input_binding_sha256": supplied_input_binding,
        "source_contract": _SOURCE_ADAPTER_CONTRACT,
        "host_controls": compiled,
        "source_program_registration": _fx_source_program_registration(program),
        "solver_sourcing": solver_sourcing,
        "guards": {
            "emission_start_frame": start, "emission_end_frame": end,
            "pulse_intervals_half_open": pulses, "direction": direction,
            "spread_full_cone_degrees": values["spread_angle_deg"],
            "speed_scene_units_per_second": expected_speed,
            "protected_features": values["protected_features"], "roi": values["roi"], "time_range": frame_range,
            "roi_and_protected_features_are_visual_targets_not_verified_geometry": True,
        },
    }


