def _fx_solver_activation_schedule(pulses: list[list[int]], frame_start: int, frame_end: int) -> list[dict[str, int]]:
    """Compile half-open pulses to a constant, controller-owned toggle channel."""

    values: dict[int, int] = {int(frame_start): 0, int(frame_end) + 1: 0}
    for start, end in pulses:
        values[int(start)] = 1
        values[int(end)] = 0
    return [{"frame": frame, "value": values[frame]} for frame in sorted(values)]


def _fx_solver_sourcing_binding(values: dict[str, Any], frame_range: dict[str, int], pulses: list[list[int]]) -> dict[str, Any]:
    """Return the exact H21 solver-sourcing contract from the captured types.

    Dynamic ``source_volume#`` and ``source_vfield#`` are deliberately plain
    string fields here.  No dynamic-menu token is invented or queried.
    """

    if frame_range["step"] != 1:
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "solver sourcing requires an integer frame step of 1; no skipped source frames are inferred",
        )
    source_start, source_end = int(frame_range["start"]), int(frame_range["end"])
    duration = source_end - source_start + 1
    schedule = _fx_solver_activation_schedule(pulses, source_start, source_end)
    return {
        "contract": _SOLVER_SOURCING_CONTRACT,
        "evidence": {
            "houdini_build": _SOLVER_SOURCING_BUILD,
            "node_type": _SOLVER_SOURCING_NODE_TYPE,
            "unavailable_node_types": list(_SOLVER_SOURCING_UNAVAILABLE_NODE_TYPES),
            "template_snapshot_sha256": _SOLVER_SOURCING_TEMPLATE_SNAPSHOT_SHA256,
            "capture_json_sha256": _SOLVER_SOURCING_CAPTURE_SHA256,
            "capture_state": "CAPTURED_NOT_BOUND",
        },
        "source_range": {
            "range_type": "sequence",
            "range_type_token": "sequence",
            "start": source_start,
            "end": source_end,
            "step": 1,
            "cycle_enabled": False,
            "cycle_length": duration,
        },
        "activation": {
            "parameter_template": "source_activate#",
            "instance_names": ["source_activate1", "source_activate2"],
            "mode": "constant_keyframes",
            "schedule": schedule,
            "off_outside_pulses": True,
            "velocity_copy_requires_activation": True,
            "zero_velocity_is_never_copied_when_inactive": True,
        },
        "rows": [
            {
                "index": 1,
                "source_volume": "density",
                "target_field": "density",
                "source_volume_parameter": "source_volume1",
                "target_field_parameter": "source_vfield1",
                "source_rank": "scalar",
                "source_rank_parameter": "source_rank1",
                "operation": "add",
                "operation_parameter": "source_voperator1",
                "source_scale": 1.0,
                "source_scale_parameter": "source_vscale1",
                "use_timestep": False,
                "use_timestep_parameter": "source_vnormalize1",
                "weight_source": "",
                "weight_target": "",
            },
            {
                "index": 2,
                "source_volume": "v",
                "target_field": "vel",
                "source_volume_parameter": "source_volume2",
                "target_field_parameter": "source_vfield2",
                "source_rank": "vector",
                "source_rank_parameter": "source_rank2",
                "operation": "copy",
                "operation_parameter": "source_voperator2",
                "source_scale": 1.0,
                "source_scale_parameter": "source_vscale2",
                "use_timestep": False,
                "use_timestep_parameter": "source_vnormalize2",
                "weight_source": "",
                "weight_target": "",
            },
        ],
        "units": {
            "density": "native density field value per active solver source application; source_vscale is a dimensionless multiplier",
            "velocity": "scene_units_per_second in target vel; Copy writes it only while the row activation is on",
            "source_scale": "dimensionless multiplier; Use Timestep is explicitly false for both rows",
            "fps": "read from hou.fps() at runtime; never hardcoded",
            "time_scale": "read from pyrosolver timescale at runtime; never overwritten",
            "timestep_seconds": "time_scale / fps, recorded for evidence and not silently applied to source scale",
        },
        "runtime": None,
    }


