def _fx_source_program(pulses, direction, spread, speed, density):
    """Fixed, controller-generated VEX only; numerical arguments already validated.

    @Frame (not $F/backticks) evaluates at cook time. Half-open intervals include
    every integer frame from start through end, but nothing at end+1. A cone of
    deterministic per-point velocities does not use disturbance/shredding/noise.
    No input string is interpolated into this program.
    """
    number = lambda value: format(float(value), ".17g")
    gate = " || ".join("(@Frame >= {} && @Frame < {})".format(int(a), int(b)) for a, b in pulses)
    return "\n".join([
        "// " + _SOURCE_ADAPTER_CONTRACT + " -- controller generated; not model code",
        "int active = (" + gate + ");",
        "vector axis = set(" + ", ".join(number(value) for value in direction) + ");",
        "vector helper = abs(axis.y) < 0.999 ? set(0, 1, 0) : set(1, 0, 0);",
        "vector side = normalize(cross(axis, helper));",
        "vector up = cross(side, axis);",
        "float u = rand(float(@ptnum) + 17.0);",
        "float azimuth = 6.283185307179586 * rand(float(@ptnum) + 43.0);",
        "float cone_cos = 1.0 - u * (1.0 - cos(" + number(math.radians(spread / 2.0)) + "));",
        "float cone_sin = sqrt(max(0.0, 1.0 - cone_cos * cone_cos));",
        "vector velocity_direction = cone_cos * axis + cone_sin * (cos(azimuth) * side + sin(azimuth) * up);",
        "v@v = active * " + number(speed) + " * velocity_direction;",
        "f@density = active * " + number(density) + ";",
        "f@temperature = 0.0; f@flame = 0.0; f@fuel = 0.0;",
        "",
    ])


def _fx_source_program_registration(program: str) -> dict[str, Any]:
    """Register the exact controller-generated source program for readback."""

    if not isinstance(program, str) or not program.strip():
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "controller source program is empty")
    return {
        "schema": _SOURCE_PROGRAM_REGISTRATION_SCHEMA,
        "generator": _SOURCE_PROGRAM_GENERATOR,
        "generator_version": _SOURCE_PROGRAM_GENERATOR_VERSION,
        "source_contract": _SOURCE_ADAPTER_CONTRACT,
        "binding": {
            "role": "source_control",
            "parameter_aliases": list(_SOURCE_PROGRAM_PARAMETER_ALIASES),
        },
        "program": program,
    }


def _fx_source_plan_pack(pack, binding):
    """Register the optional native source chain without widening graph MCP."""
    if binding is None or pack.get("shared_render_schema"):
        return pack
    result = dict(pack)
    nodes = [{**node, "required_parms": list(node.get("required_parms") or [])} for node in pack.get("nodes") or []]
    by_role = {node["role"]: node for node in nodes}
    if len(by_role) != len(nodes) or not {"source", "solver", "output"}.issubset(by_role):
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "source adapter requires the registered smoke source/solver/output scaffold")
    if any(node["role"] in by_role for node in _SOURCE_NATIVE_NODES):
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "source adapter native roles are already declared by another contract")
    if "sphere" not in by_role["source"].get("types", []):
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "source adapter requires a bounded native sphere source")
    by_role["source"]["required_parms"].append(["rad"])
    if binding.get("solver_sourcing"):
        # The captured binding is exact for H21.0.631.  Do not fall back to a
        # versioned operator whose UI happens to share a display label.
        by_role["solver"]["types"] = [_SOLVER_SOURCING_NODE_TYPE]
        by_role["solver"]["required_parms"].extend([
            ["startframe"], ["timescale"], ["srcrangetype"], ["srcframerange"],
            ["srcdocycle"], ["srccyclelength"], ["numsources"], ["source_activate#"],
            ["source_voperator#"], ["source_rank#"], ["source_volume#"], ["source_vfield#"],
            ["source_vscale#"], ["source_vnormalize#"],
        ])
    by_role["solver"]["input_role"] = "source_volume"
    source_index = nodes.index(by_role["source"]) + 1
    nodes[source_index:source_index] = _SOURCE_NATIVE_NODES
    result["nodes"] = nodes
    result["source_plan_adapter"] = _FX_PACKS["pyro_smoke_v1"]["source_plan_adapter"]
    return result


def _fx_source_control_spec(name, pack):
    control = _SOURCE_NATIVE_BINDINGS.get(name) or (pack.get("controls") or {}).get(name)
    if not isinstance(control, dict):
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "source host binding is not registered: {}".format(name))
    return control


def _fx_source_menu_token(template, label):
    try:
        # Never execute a menu generator script to infer a capability.
        if getattr(template, "itemGeneratorScript", lambda: "")():
            raise ValueError("dynamic menu")
        items, labels = tuple(template.menuItems()), tuple(template.menuLabels())
        matches = [index for index, value in enumerate(labels) if str(value).casefold() == label.casefold()]
        if len(items) != len(labels) or len(matches) != 1 or not items[matches[0]]:
            raise ValueError("unavailable or ambiguous menu label")
        return str(items[matches[0]])
    except Exception as exc:
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "native menu cannot bind {} without guessing".format(label)) from exc


def _fx_solver_template_type_name(template: Any) -> str:
    """Normalize HOM's enum rendering without relying on a UI label."""

    try:
        value = template.type()
    except Exception:
        value = getattr(template, "template_type", "")
    text = str(value).casefold()
    return text.rsplit(".", 1)[-1].replace("parmtemplatetype", "").strip(" _-")


def _fx_solver_folder_type_name(template: Any) -> str:
    try:
        value = template.folderType()
    except Exception:
        value = getattr(template, "folder_type", "")
    return str(value).casefold().rsplit(".", 1)[-1].strip(" _-")


def _fx_solver_template_children(template: Any) -> list[Any]:
    try:
        return list(template.parmTemplates())
    except (AttributeError, TypeError, RuntimeError):
        return []


def _fx_solver_find_templates(node_type: Any, name: str) -> list[Any]:
    try:
        pending = list(node_type.parmTemplateGroup().entries())
    except Exception:
        pending = _fx_solver_template_children(node_type)
    found: list[Any] = []
    while pending:
        template = pending.pop()
        try:
            if str(template.name()) == name:
                found.append(template)
        except Exception:
            pass
        pending.extend(_fx_solver_template_children(template))
    return found


def _fx_solver_direct_template(parent: Any, name: str) -> Optional[Any]:
    matches = []
    for template in _fx_solver_template_children(parent):
        try:
            if str(template.name()) == name:
                matches.append(template)
        except Exception:
            pass
    return matches[0] if len(matches) == 1 else None


def _fx_solver_require_template(node_type: Any, name: str, template_type: str, components: int = 1) -> Any:
    matches = _fx_solver_find_templates(node_type, name)
    if len(matches) != 1:
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "Houdini 21.0.631 solver template {} is missing or ambiguous".format(name),
        )
    template = matches[0]
    actual_type = _fx_solver_template_type_name(template)
    if actual_type != template_type:
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "solver template {} has type {}, expected {}".format(name, actual_type or "<unknown>", template_type),
        )
    try:
        actual_components = int(template.numComponents())
    except Exception as exc:
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "solver template {} does not expose a component count".format(name),
        ) from exc
    if actual_components != components:
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "solver template {} has {} components, expected {}".format(name, actual_components, components),
        )
    return template


def _fx_solver_require_static_menu(template: Any, name: str, items: tuple[str, ...], labels: tuple[str, ...]) -> None:
    try:
        actual_items = tuple(str(item) for item in template.menuItems())
        actual_labels = tuple(str(label) for label in template.menuLabels())
    except Exception as exc:
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "solver menu {} cannot be read without guessing".format(name),
        ) from exc
    if actual_items != items or actual_labels != labels:
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "solver menu {} does not match the captured H21 token/label contract".format(name),
        )


def _fx_prepare_solver_sourcing_type_contract(pack: dict[str, Any]) -> dict[str, Any]:
    """Validate the captured H21 node/template contract before scene writes."""

    import hou

    version_getter = getattr(hou, "applicationVersionString", None)
    build = str(version_getter()) if callable(version_getter) else ""
    if build != _SOLVER_SOURCING_BUILD:
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "solver sourcing binding is exact for {}, received {}".format(_SOLVER_SOURCING_BUILD, build or "<unknown>"),
            "Collect a new read-only template snapshot for this Houdini build; do not infer a versioned binding.",
        )
    requirement = {"category": "sop", "types": [_SOLVER_SOURCING_NODE_TYPE]}
    node_type = _fx_resolve_type(requirement)
    if node_type is None:
        raise BridgeCommandError(
            "UNSUPPORTED_NODE",
            "exact solver node type {} is unavailable; versioned fallback is disabled".format(_SOLVER_SOURCING_NODE_TYPE),
        )
    try:
        resolved_name = str(node_type.name())
    except Exception as exc:
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "solver node type name is unavailable") from exc
    if resolved_name != _SOLVER_SOURCING_NODE_TYPE:
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "resolved solver node {} is not the captured exact type {}".format(resolved_name, _SOLVER_SOURCING_NODE_TYPE),
        )

    for name, expected_type, components in (
        ("startframe", "int", 1),
        ("timescale", "float", 1),
        ("srcrangetype", "menu", 1),
        ("srcframe", "int", 1),
        ("srcframerange", "int", 2),
        ("srclimitframerange", "toggle", 1),
        ("srcdocycle", "toggle", 1),
        ("srccyclelength", "int", 1),
    ):
        _fx_solver_require_template(node_type, name, expected_type, components)
    range_menu = _fx_solver_require_template(node_type, "srcrangetype", "menu")
    _fx_solver_require_static_menu(range_menu, "srcrangetype", ("static", "sequence"), ("Static Frame", "Frame Range"))

    sourcing_folder = _fx_solver_require_template(node_type, "folder1_3", "folder")
    source_volumes_folder = _fx_solver_direct_template(sourcing_folder, "folder4")
    if source_volumes_folder is None or _fx_solver_template_type_name(source_volumes_folder) != "folder":
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "captured Sourcing/folder4 hierarchy is unavailable on the exact solver type",
        )
    multiparm = _fx_solver_direct_template(source_volumes_folder, "numsources")
    if multiparm is None or _fx_solver_template_type_name(multiparm) != "folder" or _fx_solver_folder_type_name(multiparm) != "multiparmblock":
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "captured numsources MultiparmBlock is unavailable or has a different folder type",
        )
    activation = _fx_solver_direct_template(multiparm, "source_activate#")
    row_folder = _fx_solver_direct_template(multiparm, "folder17_#")
    try:
        activation_components = int(activation.numComponents()) if activation is not None else 0
    except Exception as exc:
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "captured source_activate# component count is unavailable",
        ) from exc
    if activation is None or row_folder is None or _fx_solver_template_type_name(activation) != "toggle" or activation_components != 1:
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "captured source_activate# / folder17_# multiparm children have an unexpected type or component count",
        )
    if _fx_solver_template_type_name(row_folder) != "folder" or _fx_solver_folder_type_name(row_folder) != "collapsible":
        raise BridgeCommandError(
            "UNSUPPORTED_SOURCE_CONTROL",
            "captured folder17_# row folder is not the expected collapsible folder",
        )

    for name, expected_type, components in (
        ("source_voperator#", "menu", 1),
        ("source_rank#", "menu", 1),
        ("source_volume#", "string", 1),
        ("source_vfield#", "string", 1),
        ("source_weightvolume#", "string", 1),
        ("source_vweightfield#", "string", 1),
        ("source_vscale#", "float", 1),
        ("source_vnormalize#", "toggle", 1),
        ("source_usenorm#", "toggle", 1),
        ("source_nonneg#", "toggle", 1),
    ):
        matches = _fx_solver_find_templates(row_folder, name)
        if len(matches) != 1:
            raise BridgeCommandError(
                "UNSUPPORTED_SOURCE_CONTROL",
                "captured multiparm child {} is missing or ambiguous".format(name),
            )
        template = matches[0]
        actual_type = _fx_solver_template_type_name(template)
        if actual_type != expected_type or int(template.numComponents()) != components:
            raise BridgeCommandError(
                "UNSUPPORTED_SOURCE_CONTROL",
                "multiparm child {} has type/components {}/{} instead of {}/{}".format(
                    name, actual_type or "<unknown>", template.numComponents(), expected_type, components
                ),
            )
        # These are deliberately free text fields even though Houdini exposes
        # dynamic-menu scripts for them.  We do not call menuItems or execute
        # any generator for either field.
    _fx_solver_require_static_menu(
        _fx_solver_find_templates(row_folder, "source_voperator#")[0],
        "source_voperator#", _SOLVER_SOURCING_OPERATION_ITEMS, _SOLVER_SOURCING_OPERATION_LABELS,
    )
    _fx_solver_require_static_menu(
        _fx_solver_find_templates(row_folder, "source_rank#")[0],
        "source_rank#", _SOLVER_SOURCING_RANK_ITEMS, _SOLVER_SOURCING_RANK_LABELS,
    )
    return {
        "houdini_build": build,
        "node_type": resolved_name,
        "required_template_contract": _SOLVER_SOURCING_CONTRACT,
        "dynamic_string_fields": ["source_volume#", "source_vfield#", "source_weightvolume#", "source_vweightfield#"],
        "dynamic_menus_executed": False,
    }


def _fx_solver_instance_name(template_name: str, index: int) -> str:
    return str(template_name).replace("#", str(index))


def _fx_solver_parm(node: Any, template_name: str, index: Optional[int] = None) -> Optional[_ResolvedParm]:
    name = _fx_solver_instance_name(template_name, index) if index is not None else template_name
    return _resolve_parm_target(node, [name])


def _fx_solver_is_free_text(name: str) -> bool:
    return name.startswith("source_volume") or name.startswith("source_vfield") or name.startswith("source_weightvolume") or name.startswith("source_vweightfield")


def _fx_solver_current_value(parm: _ResolvedParm, requested: Any, *, free_text: bool = False) -> Any:
    if free_text:
        return parm.eval()
    return _read_parm_for_request(parm, requested)


def _fx_solver_values_equal(expected: Any, actual: Any) -> bool:
    if _values_match(expected, actual):
        return True
    return _values_match(_json_safe(expected), _json_safe(actual))


def _fx_solver_previous_value(previous: dict[str, Any], name: str) -> Any:
    item = (previous.get("parameter_readback") or {}).get(name)
    if not isinstance(item, dict) or "after" not in item:
        return None
    return item.get("after")


def _fx_solver_activation_owned(snapshot: dict[str, Any], expected_identities: Any) -> bool:
    if not isinstance(expected_identities, list) or snapshot.get("mode") != "hom_channels":
        return False
    components = snapshot.get("components") or []
    if len(components) != 1:
        return False
    state = components[0]
    if state.get("mode") != "keyframes" or list(state.get("identity") or []) != list(expected_identities):
        return False
    if state.get("reference_path"):
        return False
    expression = str(state.get("expression") or "").strip()
    return expression in {"", "constant()"}


def _fx_solver_check_writable(
    name: str,
    parm: _ResolvedParm,
    expected: Any,
    previous: dict[str, Any],
    *,
    activation_identities: Any = None,
) -> dict[str, Any]:
    readonly = False
    try:
        if parm.isLocked():
            raise BridgeCommandError("PARAMETER_LOCKED", "solver sourcing target is not editable: {}".format(parm.path()))
        if parm.isDisabled():
            inactive = name in {'srcdocycle', 'srccyclelength', 'source_vnormalize2'} or bool(re.fullmatch(r'source_(?:weightvolume|vweightfield|usenorm|nonneg)[12]', name))
            readonly = inactive and _fx_solver_values_equal(expected, _fx_solver_current_value(parm, expected, free_text=_fx_solver_is_free_text(name)))
            previous_value = _fx_solver_previous_value(previous, name)
            if (not readonly and re.fullmatch(r'source_[a-z]+[12]', name) and previous_value is not None
                    and _fx_solver_values_equal(expected, previous_value)
                    and _fx_solver_values_equal(expected, _fx_solver_current_value(parm, expected, free_text=_fx_solver_is_free_text(name)))):
                readonly = True
            if not readonly:
                raise BridgeCommandError("PARAMETER_LOCKED", "solver sourcing target is not editable: {}".format(parm.path()))
    except BridgeCommandError:
        raise
    except Exception as exc:
        raise BridgeCommandError("PARAMETER_STATE_UNAVAILABLE", "could not inspect {}".format(parm.path())) from exc
    is_activation = name.startswith("source_activate")
    snapshot = _snapshot_parm_state(parm, capture_extrapolation=is_activation)
    if is_activation:
        # Activation channels are replaced as a complete, controller-owned
        # schedule.  A value-only compatibility snapshot cannot prove that a
        # batch set will not leave or destroy keys, so it is never writable.
        components = snapshot.get("components") or []
        if snapshot.get("mode") != "hom_channels" or len(components) != 1:
            raise BridgeCommandError(
                "PARAMETER_SNAPSHOT_FAILED",
                "activation schedule snapshot is incomplete: {}".format(parm.path()),
            )
        # On rebuild, a previous manifest is the only ownership proof.  This
        # deliberately rejects missing, added, edited, expression-driven, or
        # referenced keys before deleteAllKeyframes can touch user data.
        if activation_identities is not None and not _fx_solver_activation_owned(snapshot, activation_identities):
            raise BridgeCommandError(
                "SCENE_STATE_MISMATCH",
                "activation schedule is no longer the Bridge-owned key set: {}".format(parm.path()),
                "Restore the Bridge-owned schedule or start a fresh task-owned solver.",
            )
        if activation_identities is not None:
            expected_extrapolation = (previous.get("activation") or {}).get("extrapolation", {}).get(name)
            actual_extrapolation = [str(value) for value in components[0]["extrapolation"]]
            if expected_extrapolation is None or actual_extrapolation != expected_extrapolation:
                raise BridgeCommandError("SCENE_STATE_MISMATCH", "activation extrapolation is no longer Bridge-owned: {}".format(parm.path()))
    if _parm_snapshot_is_driven(snapshot) and not (
        activation_identities is not None and _fx_solver_activation_owned(snapshot, activation_identities)
    ):
        raise BridgeCommandError(
            "PARAMETER_STATE_UNSUPPORTED",
            "solver sourcing target is animated, expression-driven, or channel-referenced: {}".format(parm.path()),
            "Bake or explicitly remove the channel driver before applying the solver sourcing plan.",
        )
    previous_value = _fx_solver_previous_value(previous, name)
    if previous_value is not None and activation_identities is None:
        actual = _fx_solver_current_value(parm, previous_value, free_text=_fx_solver_is_free_text(name))
        if not _fx_solver_values_equal(previous_value, actual):
            raise BridgeCommandError(
                "SCENE_STATE_MISMATCH",
                "managed solver sourcing parameter drifted before rebuild: {}".format(parm.path()),
                "Restore the Bridge-owned parameter or provide a fresh owned scene state; user edits are not overwritten.",
            )
    return {"name": name, "parm": parm, "expected": expected, "snapshot": snapshot, "activation_identities": activation_identities, "readonly": readonly}


def _fx_solver_sourcing_row_facts(solver, pack):
    if not pack.get('shared_render_schema'):
        return None
    parent = solver.parm('numsources')
    if parent is None or not parent.isMultiParmParent() or parent.eval() != 2:
        raise BridgeCommandError('ACTUAL_MULTIPARM_BINDING_REQUIRED','two actual owned sourcing rows required')
    instances = tuple(parent.multiParmInstances())
    fields = ('source_activate','source_voperator','source_rank','source_volume','source_vfield',
              'source_weightvolume','source_vweightfield','source_vscale','source_vnormalize','source_usenorm','source_nonneg')
    rows = []
    for index in (1,2):
        bindings = {}
        for field in fields:
            name = field+str(index)
            matching = [p for p in instances if p.name() == name]
            if len(matching) != 1 or tuple(matching[0].multiParmInstanceIndices()) != (index-1,):
                raise BridgeCommandError('ACTUAL_MULTIPARM_BINDING_REQUIRED','compiled sourcing row identity differs: '+name)
            bindings[field+'#'] = name
        rows.append({'index':index,'native_indices':[index-1],'bindings':bindings})
    return {'origin':'runtime_hom','parent_path':parent.path(),'instance_count':parent.eval(),'rows':rows}


def _fx_solver_sourcing_runtime(
    binding: dict[str, Any],
    roles: dict[str, Any],
    pack: dict[str, Any],
    existing: dict[str, Any],
    *,
    require_nodes: bool,
) -> Optional[dict[str, Any]]:
    """Preflight exact node values, ownership, timestep and multiparm rows."""

    solver = None
    source_volume = None
    import hou
    solver_path = str(roles.get("solver") or "")
    source_path = str(roles.get("source_volume") or "")
    if solver_path:
        solver = hou.node(solver_path)
    if source_path:
        source_volume = hou.node(source_path)
    if solver is None or source_volume is None:
        if require_nodes:
            raise BridgeCommandError("SCENE_STATE_MISSING", "solver sourcing nodes are missing after topology construction")
        return None
    if str(solver.type().name()) != _SOLVER_SOURCING_NODE_TYPE:
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "solver node type drifted from the captured exact pyrosolver type")
    if require_nodes:
        try:
            inputs = tuple(solver.inputs())
        except Exception as exc:
            raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "solver input connection cannot be read back") from exc
        actual_input = inputs[0] if inputs else None
        actual_path = str(actual_input.path()) if actual_input is not None else ""
        if actual_path != str(source_volume.path()):
            raise BridgeCommandError(
                "UNSUPPORTED_SOURCE_CONTROL",
                "solver input 0 did not read back as the owned source_volume node",
            )

    fps_getter = getattr(hou, "fps", None)
    if not callable(fps_getter):
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "hou.fps() is unavailable; timestep cannot be identified")
    try:
        fps = float(fps_getter())
    except Exception as exc:
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "hou.fps() could not be read") from exc
    if not math.isfinite(fps) or fps <= 0.0:
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "hou.fps() must be a positive finite number")

    timescale = _fx_solver_parm(solver, "timescale")
    if timescale is None:
        raise BridgeCommandError("UNSUPPORTED_PARAMETER", "pyrosolver timescale parameter is unavailable")
    timescale_snapshot = _snapshot_parm_state(timescale)
    if _parm_snapshot_is_driven(timescale_snapshot):
        raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "pyrosolver timescale is driven; timestep is not stable")
    try:
        time_scale = float(timescale.eval())
    except Exception as exc:
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "pyrosolver timescale could not be read") from exc
    if not math.isfinite(time_scale) or time_scale <= 0.0:
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "pyrosolver timescale must be a positive finite number")

    previous = existing.get("solver_sourcing") if isinstance(existing.get("solver_sourcing"), dict) else {}
    if previous and previous.get("contract") != binding["solver_sourcing"]["contract"]:
        raise BridgeCommandError("SCENE_STATE_MISMATCH", "persisted solver sourcing contract differs from the captured H21 contract")
    count_parm = _fx_solver_parm(solver, "numsources")
    if count_parm is None:
        raise BridgeCommandError("UNSUPPORTED_PARAMETER", "pyrosolver numsources multiparm count is unavailable")
    count_snapshot = _snapshot_parm_state(count_parm)
    if _parm_snapshot_is_driven(count_snapshot):
        raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "pyrosolver numsources multiparm count is driven")
    try:
        count = count_parm.eval()
    except Exception as exc:
        raise BridgeCommandError("PARAMETER_STATE_UNAVAILABLE", "pyrosolver numsources count could not be read") from exc
    if isinstance(count, bool) or not isinstance(count, int):
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "pyrosolver numsources is not an integer multiparm count")
    if count not in {0, 2}:
        raise BridgeCommandError(
            "SCENE_STATE_MISMATCH",
            "refusing to replace an unowned pyrosolver source group with {} rows".format(count),
            "Use a fresh Bridge-owned solver or remove the unowned source rows manually.",
        )
    if count == 2 and not previous:
        raise BridgeCommandError(
            "SCENE_STATE_MISMATCH",
            "pyrosolver already has two source rows without a Bridge-owned solver sourcing manifest",
        )
    if count == 0 and previous:
        raise BridgeCommandError("SCENE_STATE_MISMATCH", "solver sourcing manifest exists but numsources was externally reduced")

    source_range = binding["solver_sourcing"]["source_range"]
    range_gate = _fx_solver_parm(solver, "srclimitframerange")
    if range_gate is None:
        raise BridgeCommandError("UNSUPPORTED_PARAMETER", "pyrosolver source range gate is unavailable")
    if previous and _fx_solver_previous_value(previous, "srclimitframerange") is None:
        raise BridgeCommandError("SCENE_STATE_MISMATCH", "persisted solver sourcing has no owned source range gate")
    global_specs = [
        ("startframe", int(source_range["start"])),
        ("srcrangetype", "sequence"),
        ("srcframerange", (int(source_range["start"]), int(source_range["end"]))),
        ("srccyclelength", int(source_range["cycle_length"])),
        ("srcdocycle", False),
        ("srclimitframerange", range_gate.eval()),
    ]
    parameters: list[dict[str, Any]] = []
    for name, expected in global_specs:
        parm = _fx_solver_parm(solver, name)
        if parm is None:
            raise BridgeCommandError("UNSUPPORTED_PARAMETER", "pyrosolver parameter is unavailable: {}".format(name))
        item = _fx_solver_check_writable(name, parm, expected, previous)
        if name == "srclimitframerange":
            item["readonly"] = True
        parameters.append(item)

    rows = binding["solver_sourcing"]["rows"]
    if len(rows) != 2:
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "controller binding must contain exactly two source rows")
    if count == 2:
        _fx_solver_sourcing_row_facts(solver,pack)
        previous_schedule = (previous.get("activation") or {}).get("keyframe_identities") or {}
        if not isinstance(previous_schedule, dict) or any(
            not isinstance(previous_schedule.get("source_activate{}".format(int(row["index"]))), list)
            for row in rows
        ):
            raise BridgeCommandError(
                "SCENE_STATE_MISMATCH",
                "existing solver source rows have no complete Bridge-owned activation schedule",
                "Restore the task manifest or use a fresh task-owned solver.",
            )
        for row in rows:
            index = int(row["index"])
            activation_name = "source_activate{}".format(index)
            activation = _fx_solver_parm(solver, activation_name)
            if activation is None:
                raise BridgeCommandError("UNSUPPORTED_PARAMETER", "pyrosolver multiparm parameter is unavailable: {}".format(activation_name))
            identities = previous_schedule.get(activation_name)
            if list(_keyframe_identity(keyframe) for keyframe in activation.keyframes()) != identities:
                raise BridgeCommandError("SCENE_STATE_MISMATCH", "activation schedule is no longer the Bridge-owned key set: {}".format(activation.path()))
            values = [
                ("source_voperator{}".format(index), row["operation"]),
                ("source_rank{}".format(index), row["source_rank"]),
                ("source_volume{}".format(index), row["source_volume"]),
                ("source_vfield{}".format(index), row["target_field"]),
                ("source_weightvolume{}".format(index), row["weight_source"]),
                ("source_vweightfield{}".format(index), row["weight_target"]),
                ("source_vscale{}".format(index), float(row["source_scale"])),
                ("source_vnormalize{}".format(index), bool(row["use_timestep"])),
                ("source_usenorm{}".format(index), False),
                ("source_nonneg{}".format(index), False),
            ]
            for name, expected in values:
                parm = _fx_solver_parm(solver, name)
                if parm is None:
                    raise BridgeCommandError("UNSUPPORTED_PARAMETER", "pyrosolver multiparm parameter is unavailable: {}".format(name))
                parameters.append(_fx_solver_check_writable(name, parm, expected, previous,))
            activation_name = "source_activate{}".format(index)
            activation = _fx_solver_parm(solver, activation_name)
            if activation is None:
                raise BridgeCommandError("UNSUPPORTED_PARAMETER", "pyrosolver multiparm parameter is unavailable: {}".format(activation_name))
            identities = previous_schedule.get(activation_name)
            parameters.append(_fx_solver_check_writable(
                activation_name, activation, binding["solver_sourcing"]["activation"]["schedule"], previous,
                activation_identities=identities,
            ))

    runtime = {
        "houdini_build": _SOLVER_SOURCING_BUILD,
        "node_type": _SOLVER_SOURCING_NODE_TYPE,
        "solver_path": str(solver.path()),
        "source_volume_path": str(source_volume.path()),
        "fps": fps,
        "time_scale": time_scale,
        "timestep_seconds": time_scale / fps,
        "source_count_before_write": count,
        "input_index": 0,
        "input_connection_verified": bool(require_nodes),
        "dynamic_menus_executed": False,
        "parameters": parameters,
        "count_parm": count_parm,
        "count_snapshot": count_snapshot,
        "solver": solver,
        "source_volume": source_volume,
        "previous": previous,
    }
    binding["solver_sourcing"]["runtime"] = {
        key: value for key, value in runtime.items()
        if key not in {"parameters", "count_parm", "count_snapshot", "solver", "source_volume", "previous"}
    }
    return runtime


def _fx_set_free_text_verified(parm: _ResolvedParm, value: str) -> dict[str, Any]:
    """Set a dynamic string field without querying/executing its menu."""

    if not isinstance(value, str):
        raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "dynamic solver source fields must be plain strings")
    if parm.isLocked() or parm.isDisabled():
        raise BridgeCommandError("PARAMETER_LOCKED", "parameter is not editable: {}".format(parm.path()))
    snapshot = _snapshot_parm_state(parm)
    if _parm_snapshot_is_driven(snapshot):
        raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "dynamic solver source field is driven: {}".format(parm.path()))
    before = snapshot["evaluated"]
    try:
        parm.set(value, follow_references=False)
        after = parm.eval()
    except Exception as exc:
        _restore_parm_snapshot(parm, snapshot)
        raise BridgeCommandError("PARAMETER_SET_FAILED", "could not set {}".format(parm.path())) from exc
    if not isinstance(after, str) or after != value:
        _restore_parm_snapshot(parm, snapshot)
        raise BridgeCommandError(
            "PARAMETER_READBACK_MISMATCH",
            "{} did not read back the requested free text value".format(parm.path()),
        )
    return {
        "parameter": parm.name(), "parameter_path": parm.path(), "target_kind": parm.kind,
        "component_count": parm.component_count, "before": _json_safe(before),
        "requested": value, "after": after, "readback_verified": True,
        "restored": None, "restore_verified": False,
    }


def _fx_solver_keyframes(hou: Any, schedule: list[dict[str, int]]) -> list[Any]:
    keyframes = []
    for event in schedule:
        try:
            keyframe = hou.Keyframe(float(event["value"]))
            keyframe.setFrame(float(event["frame"]))
            keyframe.setValue(float(event["value"]))
            setter = getattr(keyframe, "setExpression", None)
            if not callable(setter):
                raise RuntimeError("HOM Keyframe.setExpression is unavailable for constant activation")
            try:
                setter("constant()", hou.exprLanguage.Hscript)
            except TypeError:
                language = getattr(getattr(hou, "exprLanguage", None), "Hscript", None)
                if language is None:
                    raise RuntimeError("Hscript expression language is unavailable")
                setter("constant()", language)
            keyframes.append(keyframe)
        except BridgeCommandError:
            raise
        except Exception as exc:
            raise BridgeCommandError(
                "UNSUPPORTED_SOURCE_CONTROL",
                "could not construct a constant activation keyframe schedule",
            ) from exc
    return keyframes


def _fx_set_solver_activation_verified(
    parm: _ResolvedParm,
    snapshot: dict[str, Any],
    schedule: list[dict[str, int]],
    hou: Any,
    *,
    owned_identities: Any = None,
) -> dict[str, Any]:
    components = snapshot.get("components") or []
    if snapshot.get("mode") != "hom_channels" or len(components) != 1:
        raise BridgeCommandError(
            "PARAMETER_SNAPSHOT_FAILED",
            "activation schedule snapshot is incomplete: {}".format(parm.path()),
        )
    if owned_identities is not None and not _fx_solver_activation_owned(snapshot, owned_identities):
        raise BridgeCommandError(
            "SCENE_STATE_MISMATCH",
            "activation schedule ownership changed before write: {}".format(parm.path()),
            "Restore the Bridge-owned schedule or use a fresh task-owned solver.",
        )
    keyframes = _fx_solver_keyframes(hou, schedule)
    expected_identities = tuple(_keyframe_identity(keyframe) for keyframe in keyframes)
    try:
        # Parm.setKeyframes is an upsert/merge operation in HOM.  Clear only
        # after the complete snapshot and ownership checks above, then restore
        # the exact snapshot if either the write or its readback fails.
        parm.deleteAllKeyframes()
        parm.setKeyframes(keyframes)
        if "extrapolation" in components[0]:
            for before in (True, False):
                components[0]["component"].setKeyframeExtrapolation(before, hou.parmExtrapolate.Constant)
        actual_identities = tuple(_keyframe_identity(keyframe) for keyframe in parm.keyframes())
    except Exception as exc:
        _restore_parm_snapshot(parm, snapshot)
        raise BridgeCommandError("PARAMETER_SET_FAILED", "could not set activation schedule on {}".format(parm.path())) from exc
    expected_state = {**components[0], "mode": "keyframes", "identity": expected_identities,
                      "expression": "constant()" if _component_driver_identity(components[0]["component"])["expression"] == "constant()" else None,
                      "reference_path": None}
    if "extrapolation" in expected_state:
        expected_state["extrapolation"] = (hou.parmExtrapolate.Constant, hou.parmExtrapolate.Constant)
    if actual_identities != expected_identities or not _verify_component_state(expected_state):
        _restore_parm_snapshot(parm, snapshot)
        raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "activation schedule did not read back on {}".format(parm.path()))
    return {
        "parameter": parm.name(), "parameter_path": parm.path(), "target_kind": parm.kind,
        "component_count": parm.component_count, "before": _json_safe(snapshot.get("evaluated")),
        "requested": _json_safe(schedule), "after": list(actual_identities),
        "readback_verified": True, "restored": None, "restore_verified": False,
    }


def _fx_apply_solver_sourcing(
    binding: dict[str, Any],
    roles: dict[str, Any],
    pack: dict[str, Any],
    existing: dict[str, Any],
    attempted: list[tuple[_ResolvedParm, dict[str, Any]]],
    apply_source_targets,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    """Write the two owned rows atomically and return flat readback records."""

    import hou

    runtime = binding["solver_sourcing"].get("runtime")
    if not isinstance(runtime, dict) or not runtime.get("solver"):
        runtime = _fx_solver_sourcing_runtime(binding, roles, pack, existing, require_nodes=True)
    if runtime is None:
        raise BridgeCommandError("SCENE_STATE_MISSING", "solver sourcing runtime was not prepared")
    solver = runtime["solver"]
    count = int(runtime["source_count_before_write"])
    readback: dict[str, Any] = {}
    parameter_readback: dict[str, Any] = {}

    count_parm = runtime["count_parm"]
    count_snapshot = runtime["count_snapshot"]
    if count == 0:
        attempted.append((count_parm, count_snapshot))
        count_result = _set_parm_verified(count_parm, 2)
        readback["solver_sourcing.numsources"] = count_result
        parameter_readback["numsources"] = count_result
        count = 2

    # The two rows become addressable only after the multiparm count has been
    # set.  For a new owned node this is the only structural write; every row
    # is immediately snapshotted and guarded before its first value is set.
    parameters = list(runtime.get("parameters") or [])
    if runtime["source_count_before_write"] == 0:
        previous = runtime.get("previous") or {}
        rows = binding["solver_sourcing"]["rows"]
        for row in rows:
            index = int(row["index"])
            values = [
                ("source_voperator{}".format(index), row["operation"]),
                ("source_rank{}".format(index), row["source_rank"]),
                ("source_volume{}".format(index), row["source_volume"]),
                ("source_vfield{}".format(index), row["target_field"]),
                ("source_weightvolume{}".format(index), row["weight_source"]),
                ("source_vweightfield{}".format(index), row["weight_target"]),
                ("source_vscale{}".format(index), float(row["source_scale"])),
                ("source_vnormalize{}".format(index), bool(row["use_timestep"])),
                ("source_usenorm{}".format(index), False),
                ("source_nonneg{}".format(index), False),
            ]
            for name, expected in values:
                parm = _fx_solver_parm(solver, name)
                if parm is None:
                    raise BridgeCommandError("UNSUPPORTED_PARAMETER", "pyrosolver multiparm parameter is unavailable: {}".format(name))
                parameters.append(_fx_solver_check_writable(name, parm, expected, previous))
            activation_name = "source_activate{}".format(index)
            activation = _fx_solver_parm(solver, activation_name)
            if activation is None:
                raise BridgeCommandError("UNSUPPORTED_PARAMETER", "pyrosolver multiparm parameter is unavailable: {}".format(activation_name))
            parameters.append(_fx_solver_check_writable(
                activation_name, activation, binding["solver_sourcing"]["activation"]["schedule"], previous,
            ))

    # Preserve the controller order: global range first, then each source row.
    schedule = binding["solver_sourcing"]["activation"]["schedule"]
    activation_names = {"source_activate1", "source_activate2"}
    # Copy disables Use Timestep; finish its editable value before selecting
    # Copy, so reverse rollback re-enables the field before restoring it.
    parameters.sort(key=lambda item: (item['name'] in activation_names, item['name'] == 'source_voperator2'))
    attempted.extend((item['parm'], item['snapshot']) for item in parameters)
    sources_applied = False
    for item in parameters:
        name = item["name"]
        parm = item["parm"]
        snapshot = item["snapshot"]
        expected = item["expected"]
        if name in activation_names and not sources_applied:
            apply_source_targets(runtime)
            sources_applied = True
        if item.get('readonly'):
            result = {"before":snapshot['evaluated'],"requested":expected,"after":snapshot['evaluated'],
                      "readback_verified":True,"inactive_field_preserved":True}
        elif name in activation_names:
            attempted.append((parm, snapshot))
            result = _fx_set_solver_activation_verified(
                parm, snapshot, schedule, hou,
                owned_identities=item.get("activation_identities"),
            )
        elif _fx_solver_is_free_text(name):
            attempted.append((parm, snapshot))
            result = _fx_set_free_text_verified(parm, str(expected))
        else:
            attempted.append((parm, snapshot))
            result = _set_parm_verified(parm, expected)
        readback["solver_sourcing." + name] = result
        parameter_readback[name] = result

    # Verify the complete vector after every set.  This catches a late native
    # callback changing an earlier source row before the manifest is written.
    for item in parameters:
        name = item["name"]
        parm = item["parm"]
        expected = item["expected"]
        if name in activation_names:
            actual = tuple(_keyframe_identity(keyframe) for keyframe in parm.keyframes())
            requested_keys = _fx_solver_keyframes(hou, schedule)
            expected_actual = tuple(_keyframe_identity(keyframe) for keyframe in requested_keys)
            expected_state = {**item["snapshot"]["components"][0], "mode": "keyframes", "identity": expected_actual,
                              "expression": "constant()" if _component_driver_identity(item["snapshot"]["components"][0]["component"])["expression"] == "constant()" else None,
                              "reference_path": None,
                              "extrapolation": (hou.parmExtrapolate.Constant, hou.parmExtrapolate.Constant)}
            if not _verify_component_state(expected_state):
                raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "solver activation schedule drifted: {}".format(parm.path()))
            parameter_readback[name]["after"] = list(actual)
        else:
            actual = _fx_solver_current_value(parm, expected, free_text=_fx_solver_is_free_text(name))
            if _parm_snapshot_is_driven(_snapshot_parm_state(parm)) or not _fx_solver_values_equal(expected, actual):
                raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "solver sourcing write drifted: {}".format(parm.path()))
            parameter_readback[name]["after"] = _json_safe(actual)

    activation_keyframe_identities = {
        name: list(parameter_readback[name]["after"])
        for name in activation_names
        if name in parameter_readback
    }
    source_range = binding["solver_sourcing"]["source_range"]
    direct_controls = {
        "contract": binding["solver_sourcing"]["contract"],
        "houdini_build": runtime["houdini_build"],
        "node_type": runtime["node_type"],
        "solver_path": runtime["solver_path"],
        "source_volume_path": runtime["source_volume_path"],
        "fps": runtime["fps"],
        "time_scale": runtime["time_scale"],
        "timestep_seconds": runtime["timestep_seconds"],
        "source_range": _json_safe(source_range),
        "activation_schedule": _json_safe(schedule),
        "rows": _json_safe(binding["solver_sourcing"]["rows"]),
        "input_index": 0,
        "input_connection_verified": True,
        "dynamic_menus_executed": False,
        "stop_policy": "source_activate1/source_activate2 are constant-keyframed off outside pulse intervals; velocity Copy is never active on an inactive frame",
    }
    direct_result = {
        "contract": binding["solver_sourcing"]["contract"],
        "node_type": runtime["node_type"],
        "solver_path": runtime["solver_path"],
        "input_connection": {
            "input_index": 0,
            "source_path": runtime["source_volume_path"],
            "readback_verified": True,
        },
        "source_count": 2,
        "source_count_before_write": runtime["source_count_before_write"],
        "source_count_policy": (
            "new_task_owned_solver_count_zero_explicitly_initialized_to_two"
            if runtime["source_count_before_write"] == 0
            else "existing_two_rows_require_persisted_bridge_owned_manifest"
        ),
        "source_range": _json_safe(source_range),
        "activation": {
            "mode": "constant_keyframes",
            "schedule": _json_safe(schedule),
            "keyframe_identities": activation_keyframe_identities,
            "extrapolation": {name: [str(solver.parm(name).keyframeExtrapolation(before)) for before in (True, False)]
                              for name in activation_names},
            "off_outside_pulses": True,
            "velocity_copy_requires_activation": True,
            "zero_velocity_is_never_copied_when_inactive": True,
        },
        "runtime": {
            "houdini_build": runtime["houdini_build"], "fps": runtime["fps"],
            "time_scale": runtime["time_scale"], "timestep_seconds": runtime["timestep_seconds"],
            "units": binding["solver_sourcing"]["units"], "dynamic_menus_executed": False,
        },
        "parameter_readback": parameter_readback,
        "compiled_rows": _fx_solver_sourcing_row_facts(solver,pack),
        "readback_verified": True,
        "rows": _json_safe(binding["solver_sourcing"]["rows"]),
        "stop_policy": direct_controls["stop_policy"],
    }
    binding["solver_sourcing_runtime_controls"] = direct_controls
    binding["solver_sourcing_runtime_result"] = direct_result
    return readback, direct_result, direct_controls


def _fx_control_target_specs(control):
    return [{"role":control["role"], "aliases":control["aliases"], "policy":"same", "primary":True,
             "native_multiplier_parm":control.get("native_multiplier_parm")},
            *[{**item, "primary":False} for item in control.get("linked_targets", ())]]


def _fx_control_multiplier(target, parm):
    name = target.get("native_multiplier_parm")
    if not name:
        return 1.0
    exponent = _resolve_parm_target(parm.node(), [name])
    if exponent is None:
        raise BridgeCommandError("UNSUPPORTED_PARAMETER", "native stiffness exponent is unavailable")
    snapshot = _snapshot_parm_state(exponent)
    template = exponent.parmTemplate()
    if not callable(getattr(template,"menuUseToken",None)) or not template.menuUseToken():
        raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "stiffness exponent requires the actual numeric-token menu")
    value = exponent.eval()
    if str(value) not in tuple(template.menuItems()):
        raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "stiffness exponent is outside the native menu")
    if _parm_snapshot_is_driven(snapshot) or type(value) is not int or not -20 <= value <= 20:
        raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "stiffness exponent must be a frozen native integer token")
    return 10.0 ** value


def _fx_linked_control_value(target, value, parm):
    target["multiplier"] = _fx_control_multiplier(target,parm)
    if target.get("native_multiplier_parm"):
        return value / target["multiplier"]
    if target.get("policy") == "at_least":
        actual = parm.eval()
        if type(actual) is not int or type(value) is not int:
            raise BridgeCommandError("PARAMETER_STATE_UNAVAILABLE", "linked integer bound is not observable")
        return max(value, actual)
    return value


def _fx_prepare_source_runtime(binding, pack):
    """Probe names AND menu tokens using native type templates before mutation."""
    if binding is None:
        return
    if pack.get("native_plan_schema") == "bridge.native-render-domains/1":
        import hou
        from houdini_bridge.native_render_domains import candidate_write_plan, NativeRenderDomainError
        try:
            candidate_write_plan(pack["native_domain_id"], binding["host_controls"], hou.applicationVersionString(),
                shutter_contract=(pack["controls"].get("shutter") or {}).get("semantic_contract"))
        except NativeRenderDomainError as exc:
            raise BridgeCommandError(exc.code,str(exc)) from exc
        binding["runtime_values"] = dict(binding["host_controls"])
        return
    if pack.get('shared_render_schema') and binding.get('domain_plan'):
        for name, value in binding['host_controls'].items():
            control = pack['controls'][name]
            if control.get('native_status') not in {None, 'mapped'}:
                from houdini_bridge import native_flip_rbd_domains as rbd
                if (pack.get('native_plan_schema') != rbd.SCHEMA
                        or pack.get('native_domain_id') != rbd.RBD
                        or name != 'velocity_variance'):
                    raise BridgeCommandError(control.get('blocker', 'UNSUPPORTED_NATIVE_CONTROL'), name)
                import hou
                try:
                    route = rbd.conditional_runtime_route(rbd.RBD, name, value, hou.applicationVersionString())
                except ValueError as error:
                    raise BridgeCommandError(getattr(error, 'code', 'UNSUPPORTED_NATIVE_CONTROL'), str(error)) from error
                if route != 'bridge.rbd-velocity-program/1':
                    raise BridgeCommandError('UNSUPPORTED_NATIVE_CONTROL', name)
                # Type preflight grants no scene authority. The owned Host
                # validates actual packed geometry before planning any write.
            _fx_coerce_control(name, value, control)
        binding['runtime_values'] = dict(binding['host_controls'])
        return
    by_role = {node["role"]: node for node in pack["nodes"]}
    resolved = {}
    for name, value in binding["host_controls"].items():
        control = _fx_source_control_spec(name, pack)
        native = _fx_resolve_type(by_role[control["role"]])
        for target in _fx_control_target_specs(control):
            native_target = _fx_resolve_type(by_role[target["role"]])
            available = _fx_addressable_parm_names(native_target) if native_target is not None else set()
            if not any(alias in available or any("#" in template and re.fullmatch(re.escape(template).replace(r"\#", r"[1-9][0-9]*"), alias) for template in available) for alias in target["aliases"]):
                raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "native source parameter is unavailable: {}:{}".format(name,target["role"]))
        if "menu_label" in control:
            templates = list(native.parmTemplateGroup().entries())
            found = []
            while templates:
                template = templates.pop()
                if template.name() in control["aliases"]:
                    found.append(template)
                try:
                    templates.extend(template.parmTemplates())
                except (AttributeError, TypeError):
                    pass
            if len(found) != 1:
                raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "native source menu is ambiguous: {}".format(name))
            resolved[name] = _fx_source_menu_token(found[0], control["menu_label"])
        else:
            resolved[name] = value
    # Native token values are host observations, not model-supplied metadata.
    binding["runtime_values"] = resolved
    if binding.get("solver_sourcing"):
        binding["solver_sourcing_type_contract"] = _fx_prepare_solver_sourcing_type_contract(pack)


def _fx_preflight_source_plan_targets(
    plan_binding: Optional[dict[str, Any]],
    roles: dict[str, Any],
    pack: dict[str, Any],
    existing: Optional[dict[str, Any]] = None,
    *,
    require_nodes: bool = False,
) -> None:
    if plan_binding is None:
        return
    import hou
    if pack.get("native_plan_schema") == "bridge.native-render-domains/1":
        target_roles = {pack["controls"][name]["role"] for name in plan_binding["host_controls"]}
        if require_nodes or any(hou.node(str(roles.get(role) or "")) is not None for role in target_roles):
            _fx_render_domain_prepared(pack["native_domain_id"], plan_binding["host_controls"], roles,pack)
        return
    if pack.get('shared_render_schema') and all(name in pack['controls'] for name in plan_binding['host_controls']):
        target_roles = {pack['controls'][name]['role'] for name in plan_binding['host_controls']}
        if require_nodes or any(hou.node(str(roles.get(role) or '')) is not None for role in target_roles):
            prepared = _fx_planned_domain_prepared(pack['native_domain_id'], plan_binding['host_controls'], roles, pack)
            _fx_release_planned_items(prepared)
        return
    existing = existing or {}
    requirements = {node["role"]: node for node in pack["nodes"]}
    sourcing = (_fx_solver_sourcing_runtime(plan_binding, roles, pack, existing, require_nodes=require_nodes)
                if plan_binding.get("solver_sourcing") and (require_nodes or roles.get("solver")) else None)
    for name in plan_binding["host_controls"]:
        control = _fx_source_control_spec(name, pack)
        for target in _fx_control_target_specs(control):
            node = hou.node(str(roles.get(str(target["role"])) or ""))
            if node is None:
                if require_nodes:
                    raise BridgeCommandError("SCENE_STATE_MISSING", "source-plan node role is missing: {}".format(target["role"]))
                continue
            parm = _resolve_parm_target(node, list(target["aliases"]))
            if parm is None:
                if (sourcing is not None and sourcing['source_count_before_write'] == 0 and
                        name == 'density_scale' and target['role'] == 'solver' and
                        list(target['aliases']) == ['source_vscale1']):
                    # Static row type was checked before entering the build.
                    # Resolve this actual instance after owned allocation.
                    continue
                raise BridgeCommandError("UNSUPPORTED_PARAMETER", "source-plan host parameter is unavailable: {}".format(name))
            if _parm_snapshot_is_driven(_snapshot_parm_state(parm)):
                raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "source-plan target is driven: {}".format(parm.path()))
            try:
                native_type = node.type().name()
            except Exception as exc:
                raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "existing native type is unavailable") from exc
            if native_type not in requirements[target["role"]]["types"]:
                raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "existing source node type drifted: {}".format(target["role"]))
            _fx_control_multiplier(target,parm)
            preserved = sourcing is not None and any(
                item['parm'].path() == parm.path() and item.get('readonly')
                and _fx_solver_values_equal(plan_binding['runtime_values'][name], item['expected'])
                for item in sourcing['parameters'])
            if parm.isLocked() or (parm.isDisabled() and not preserved):
                raise BridgeCommandError("PARAMETER_LOCKED", "source-plan target is not editable: {}".format(parm.path()))
            if "menu_label" in control:
                actual = _fx_source_menu_token(parm.parmTemplate(), control["menu_label"])
                if actual != plan_binding["runtime_values"][name]:
                    raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "existing source menu differs from the native contract")
    if plan_binding.get("solver_sourcing") and (require_nodes or roles.get("solver")):
        _fx_solver_sourcing_runtime(
            plan_binding, roles, pack, existing, require_nodes=require_nodes,
        )


def _fx_restore_source_parameter_snapshots(entries):
    originals = {}
    for parm, snapshot in entries:
        originals.setdefault(parm.path(), (parm, snapshot))

    def changed(parm, snapshot):
        if snapshot.get('mode') == 'value_only_compat':
            return not _values_match(snapshot['evaluated'], parm.eval())
        return not all(_verify_component_state(component) for component in snapshot.get('components', ()))

    failures = []
    for parm, snapshot in originals.values():
        match = re.fullmatch(r'source_(?!activate)[a-z]+([12])', parm.name())
        global_gate = parm.name() in {'srccyclelength', 'srcdocycle'}
        if not match and not global_gate:
            continue
        try:
            if not changed(parm, snapshot) or not parm.isDisabled():
                continue
            if global_gate:
                gates = [_fx_solver_parm(parm.node(), name) for name in ('srclimitframerange', 'srcdocycle')]
                if any(gate is None or gate.path() not in originals for gate in gates):
                    raise ValueError('source rollback has no captured global gate ownership')
                for gate in gates:
                    gate_snapshot = originals[gate.path()][1]
                    if (gate_snapshot.get('mode') != 'hom_channels' or len(gate_snapshot.get('components') or []) != 1
                            or _parm_snapshot_is_driven(gate_snapshot)):
                        raise ValueError('source rollback global gate snapshot is incomplete or driven')
                for gate in gates if parm.name() == 'srccyclelength' else gates[:1]:
                    if not _values_match(1, gate.eval()):
                        _set_parm_verified(gate, 1)
                continue
            index = match.group(1)
            activation = _fx_solver_parm(parm.node(), 'source_activate' + index)
            operation = _fx_solver_parm(parm.node(), 'source_voperator' + index)
            if activation is None or operation is None or activation.path() not in originals or operation.path() not in originals:
                raise ValueError('source rollback has no captured gate ownership')
            if not activation.eval():
                activation.deleteAllKeyframes()
                _set_parm_verified(activation, 1)
            if parm.name() == 'source_vnormalize2' and parm.isDisabled() and operation.evalAsString() == 'copy':
                _set_parm_verified(operation, 'add')
        except Exception as exc:
            failures.append(parm.path() + ':' + str(exc))

    ordered = list(reversed(list(originals.values())))
    ordered.sort(key=lambda entry: 5 if entry[0].name() == 'numsources' else
                 4 if entry[0].name() == 'srclimitframerange' else
                 3 if entry[0].name() == 'srcdocycle' else
                 2 if re.fullmatch(r'source_activate[12]', entry[0].name()) else
                 1 if re.fullmatch(r'source_voperator[12]', entry[0].name()) else 0)
    for parm, snapshot in ordered:
        try:
            if changed(parm, snapshot):
                _restore_parm_snapshot(parm, snapshot)
        except Exception as exc:
            failures.append(parm.path() + ':' + str(exc))
    removed_rows = {parm.node().path() for parm, snapshot in originals.values()
                    if parm.name() == 'numsources' and snapshot['evaluated'] == 0}
    for parm, snapshot in originals.values():
        if parm.name().startswith('source_') and parm.node().path() in removed_rows:
            continue
        try:
            if changed(parm, snapshot):
                failures.append(parm.path() + ':restored source vector drifted')
        except Exception as exc:
            failures.append(parm.path() + ':' + str(exc))
    if failures:
        raise BridgeCommandError('PARAMETER_RESTORE_FAILED', 'source parameter rollback failed: ' + ', '.join(failures))


def _fx_apply_source_plan_targets(
    plan_binding: Optional[dict[str, Any]],
    roles: dict[str, Any],
    pack: dict[str, Any],
    existing: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    if plan_binding is None:
        return {}
    import hou
    if pack.get("native_plan_schema") == "bridge.native-render-domains/1":
        values = plan_binding["host_controls"]
        prepared = _fx_render_domain_prepared(pack["native_domain_id"], values,roles,pack)
        attempted = []
        native_results = []
        try:
            for item in prepared:
                attempted.append(item)
                native_results.append(_set_parm_verified(item["parm"],item["value"]))
            for item in prepared:
                if _parm_snapshot_is_driven(_snapshot_parm_state(item["parm"])) or not _values_match(item["value"],_read_parm_for_request(item["parm"],item["value"])):
                    raise BridgeCommandError("PARAMETER_READBACK_MISMATCH","render control vector drifted")
            canonical = _fx_render_domain_readback(pack["native_domain_id"],values,roles,pack)
            if any(not _values_match(_fx_coerce_control(name,value,pack["controls"][name]),canonical[name]) for name,value in values.items()):
                raise BridgeCommandError("PARAMETER_READBACK_MISMATCH","semantic render control vector differs")
            return {name:{"requested":value,"readback":canonical[name],"readback_verified":True,
                    "native_targets":[result for item,result in zip(prepared,native_results) if name in item["semantic_names"]],
                    "invalidates_from":pack["controls"][name].get("invalidates_from")} for name,value in values.items()}
        except Exception:
            for item in reversed(attempted):
                _restore_parm_snapshot(item["parm"],item["snapshot"])
            raise
    if pack.get('shared_render_schema') and all(name in pack['controls'] for name in plan_binding['host_controls']):
        values = plan_binding['host_controls']
        prepared = _fx_planned_domain_prepared(pack['native_domain_id'], values, roles, pack)
        attempted = []; results = []
        try:
            for item in prepared:
                attempted.append(item)
                results.append(_fx_write_planned_item(item, roles, pack))
            canonical = _fx_planned_domain_readback(pack['native_domain_id'], values, roles, pack,
                [item['native_write'] for item in prepared])
            if any(not _values_match(_fx_coerce_control(name,value,pack['controls'][name]), canonical[name]) for name,value in values.items()):
                raise BridgeCommandError('PARAMETER_READBACK_MISMATCH', 'native domain semantic vector differs')
            _fx_release_planned_items(prepared)
            return {name: {'requested':value,'readback':canonical[name],'readback_verified':True,
                'native_targets':[result for item,result in zip(prepared,results) if name in item['semantic_names']],
                'invalidates_from':pack['controls'][name]['invalidates_from']} for name,value in values.items()}
        except Exception as error:
            errors = _fx_rollback_planned_items(attempted, prepared, roles, pack)
            if errors:
                raise BridgeCommandError('CANDIDATE_ROLLBACK_FAILED', ', '.join(errors)) from error
            raise
    existing = existing or {}
    applied: dict[str, Any] = {}
    attempted: list[tuple[_ResolvedParm, dict[str, Any]]] = []
    pending = []

    def apply_source_targets(sourcing=None):
        for name, value in plan_binding["runtime_values"].items():
            control = _fx_source_control_spec(name, pack)
            for target in _fx_control_target_specs(control):
                node = hou.node(str(roles.get(str(target["role"])) or ""))
                parm = _resolve_parm_target(node, list(target["aliases"])) if node is not None else None
                if parm is None:
                    raise BridgeCommandError("UNSUPPORTED_PARAMETER", "source-plan host parameter is unavailable: {}".format(name))
                snapshot = _snapshot_parm_state(parm)
                preserved = sourcing is not None and any(
                    item['parm'].path() == parm.path() and item.get('readonly')
                    and _fx_solver_values_equal(value, item['expected'])
                    for item in sourcing['parameters'])
                if _parm_snapshot_is_driven(snapshot) or parm.isLocked() or (parm.isDisabled() and not preserved):
                    raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "source-plan target cannot be overwritten: {}".format(parm.path()))
                pending.append((name, _fx_linked_control_value(target,value,parm), parm, snapshot, {**control,**target}))
        for name, value, parm, snapshot, control in pending:
            attempted.append((parm, snapshot))
            if parm.isDisabled() and _values_match(value, _read_parm_for_request(parm, value)):
                result = {'after': _json_safe(_read_parm_for_request(parm, value)), 'readback_verified': True,
                          'inactive_field_preserved': True}
            else:
                result = _set_parm_verified(parm, value)
            entry = applied.setdefault(name, {"requested":plan_binding["runtime_values"][name],
                         "readback_verified":True,"native_targets":[],
                         "invalidates_from":str(control.get("invalidates_from") or "generation_simulation")})
            entry["native_targets"].append({"path":parm.path(),"requested":value,"readback":result.get("after")})
            entry["readback_verified"] = entry["readback_verified"] and result["readback_verified"]
            if control["primary"]:
                entry["readback"] = result.get("after") * control["multiplier"] if control.get("native_multiplier_parm") else result.get("after")
    try:
        if plan_binding.get("solver_sourcing"):
            _direct_readback, _direct_result, _direct_controls = _fx_apply_solver_sourcing(
                plan_binding, roles, pack, existing, attempted, apply_source_targets,
            )
        else:
            apply_source_targets()
        for name, value, parm, snapshot, control in pending:
            actual = _read_parm_for_request(parm, value)
            if _parm_snapshot_is_driven(_snapshot_parm_state(parm)) or not _values_match(value, actual):
                raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "source write set drifted after later writes: {}".format(parm.path()))
            if _fx_control_multiplier(control,parm) != control.get("multiplier",1.0):
                raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "native stiffness exponent changed during the write set")
            if control["primary"]:
                applied[name]["readback"] = _json_safe(actual * control["multiplier"] if control.get("native_multiplier_parm") else actual)
    except Exception:
        # Restore the full literal write set, not just the last failed parm.
        _fx_restore_source_parameter_snapshots(attempted)
        raise
    if plan_binding.get("solver_sourcing"):
        # The direct solver result is stored on the binding so the manifest can
        # keep the existing flat host-readback shape while adding a structured
        # solver-specific evidence record.
        applied.update(_direct_readback)
    return applied


def _fx_apply_source_polygon_menu(node: Any) -> "dict[str, Any] | None":
    """Explicitly set a polygon mesh type on a synthetic source, using the
    node's own parm menu template values (never trial-and-error integers)."""
    parm = node.parm("type")
    if parm is None:
        return None
    try:
        labels = list(parm.menuLabels())
        items = list(parm.menuItems())
    except Exception:
        return None
    if not labels or len(labels) != len(items):
        return None
    index = _load_core_contract().choose_polygon_menu_index(labels)
    if index is None:
        return None
    token = items[index]
    try:
        parm.set(token)
    except Exception:
        return None
    return {"token": str(token), "label": str(labels[index])}


def _fx_preflight_existing_candidate_patch(existing,roles,pack):
    """Validate every persisted native target before the first build mutation."""
    patch = existing.get("candidate_patch") or {}
    if patch:
        _fx_preflight_source_plan_targets({"host_controls":patch,"runtime_values":patch},roles,pack,existing)


def _fx_domain_control_binding(params, pack_id, pack):
    """Consume the same typed semantic plan as the controller, before mutation."""
    fx = _fx_configuration(params)
    raw = fx.get("domain_control_plan")
    if raw is None:
        return None
    if fx.get("source_plan") is not None:
        raise BridgeCommandError("INVALID_SOURCE_CONTROL", "choose one objective contract per build")
    from dcc_task_runtime.domain_objective import DomainControlPlan
    try:
        plan = DomainControlPlan.from_mapping(raw).require_ready()
    except Exception as exc:
        raise BridgeCommandError("INVALID_SOURCE_CONTROL", str(exc)) from exc
    if plan.domain_pack != pack_id or fx.get("domain_control_plan_sha256") != plan.plan_sha256:
        raise BridgeCommandError("SOURCE_PLAN_DRIFT", "domain plan hash or selected domain differs")
    media = {(asset.asset_id, asset.sha256) for asset in plan.objective.media_manifest.assets}
    inputs = {(str(item.get("asset_id") or ""), str(item.get("sha256") or "").lower())
              for item in params.get("inputs", []) if isinstance(item, dict)}
    if not media or not media.issubset(inputs):
        raise BridgeCommandError("SOURCE_BINDING_DRIFT", "domain objective references unbound input content")
    values = plan.controls_for_application("houdini")
    for name in values:
        if name not in pack.get("controls", {}):
            raise BridgeCommandError("UNSUPPORTED_SOURCE_CONTROL", "domain control has no host mapping: " + name)
    return {"host_controls": values, "plan_sha256": plan.plan_sha256,
            "source_contract": raw["schema_version"], "domain_plan": raw}


