def _fx_initialize_new_owned_counts(node):
    """Explicit recipe values on a newly created node; unknown defaults stay unknown."""
    counts = {"Sop/pyrosolver": ("numfields", "numsources"), "Sop/pyrosource": ("attributes",),
              "Sop/clusterpoints": ("num_controls",), "Sop/guideprocess": ("operations",),
              "Sop/dopimportfield": ("fields","compression"), "Sop/flipcontainer": ("customattributes",),
              "Sop/rbdbulletsolver": ("breaks",),
              "Lop/karmarendersettings": ("extrarendervars", "custom_metadata")}
    result = {}
    for name in counts.get(str(node.type().nameWithCategory()), ()):
        parm = node.parm(name)
        if parm is None or parm.isLocked() or parm.isDisabled():
            raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "new recipe multiparm is unavailable")
        driver = _component_driver_identity(parm)
        if driver["expression"] or driver["reference_path"] or tuple(parm.keyframes()):
            raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "new recipe multiparm is driven")
        # The caller just created this exact node. Rollback is destruction of
        # that new node, rather than a made-up snapshot of an unknown default.
        try:
            parm.set(0, follow_parm_reference=False)
            if type(parm.eval()) is not int or parm.eval() != 0:
                raise ValueError("multiparm initialization did not read back")
        except Exception:
            node.destroy()
            raise
        result[name] = {"requested": 0, "after": parm.eval(), "readback_verified": True,
                        "initialization": "explicit_new_owned_node_recipe"}
    return result


def _fx_configure_render_output(node, *, output_color_route=None):
    """Author EXR storage and an explicit native husk output transform."""
    if str(node.type().nameWithCategory()) != "Lop/karmarendersettings":
        raise BridgeCommandError("RENDER_CONFIG_INVALID", "Karma Render Settings is required")
    count = _resolve_parm_target(node, ["custom_metadata"])
    if count is None:
        raise BridgeCommandError("RENDER_CONFIG_INVALID", "custom metadata count is missing")
    before = count.eval()
    if type(before) is not int or not 0 <= before <= 64:
        raise BridgeCommandError("RENDER_CONFIG_INVALID", "custom metadata exceeds bounded recipe")
    requirements = {"OpenEXR:storage": ("string", "metadata_string_", "scanline"),
                    "OpenEXR:multipart": ("int", "metadata_int_", 0)}
    if output_color_route is not None:
        if output_color_route != {'source': 'scene_linear', 'output': 'ACEScg'}:
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "unsupported controlled output color route")
        # Karma's official custom-metadata writer authors these exact
        # HuskRenderProductAPI attributes. husk performs the OCIO conversion;
        # this does not edit image metadata after rendering.
        requirements.update(source_colorspace=("string", "metadata_string_", output_color_route['source']),
                            output_colorspace=("string", "metadata_string_", output_color_route['output']))
    rows = {}
    for row in range(1, before + 1):
        key = node.parm("metadata_key_" + str(row)).eval()
        if key in requirements:
            if key in rows:
                raise BridgeCommandError("RENDER_CONFIG_INVALID", "duplicate output driver metadata")
            rows[key] = row
    count_after = before + len(set(requirements) - set(rows))
    if count_after > 64:
        raise BridgeCommandError("RENDER_CONFIG_INVALID", "custom metadata exceeds bounded recipe")
    attempted, readback = [], {}
    def write(name, value):
        parm = _resolve_parm_target(node, [name])
        if parm is None:
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "output metadata parameter is missing: " + name)
        snapshot = _snapshot_parm_state(parm)
        attempted.append((parm, snapshot))
        readback[name] = _set_parm_verified(parm, value)
    try:
        if count_after != before:
            write("custom_metadata", count_after)
        next_row = before
        for key, (kind, value_prefix, value) in requirements.items():
            row = rows.get(key)
            if row is None:
                next_row += 1
                row = next_row
            suffix = str(row)
            write("metadata_type_" + suffix, kind)
            write("metadata_key_" + suffix, key)
            write(value_prefix + suffix, value)
        write("image_exr_compression", "zips")
        for name, expected in (("image_exr_compression", "zips"), ("custom_metadata", count_after)):
            parm = _resolve_parm_target(node, [name])
            if not _values_match(expected, _read_parm_for_request(parm, expected)):
                raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "output format drifted")
    except Exception:
        for parm, snapshot in reversed(attempted):
            _restore_parm_snapshot(parm, snapshot)
        raise
    if output_color_route is not None:
        readback['output_color_route'] = dict(output_color_route)
    return readback


def _fx_initialize_native_domain(pack_id, roles, domain_binding, *, fresh_roles=None):
    """Set trusted recipe constants from captured HDA parameter contracts."""
    import hou
    initial = {}
    if pack_id in {"particles_v1", "swarm_flocking_v1"}:
        initial = {"emission": {"emittype": "surface", "usecontextgeo": "first", "initvel": "set", "impulseactiveate": 0.0, "constantactivate": 1.0}, "particle_size": {"attrib": "pscale", "class": "point", "operation": "set", "valuetype": "const", "singlevalue": 0.05}}
        if pack_id == "swarm_flocking_v1":
            initial["emission"].update({"constantrate": 100.0, "life": 5.0})
            initial["particle_size"]["singlevalue"] = 0.05
            initial["seek"] = {"goaly": 3.0}
        hou.node(roles["simulation_output"]).setDisplayFlag(True)
    elif pack_id == "water_flip_v1":
        controls = (domain_binding or {}).get("host_controls") or {}
        initial = {"fluid_source": {"createparticles": True},
                   "collision_transform": {"ty": -2.0},
                   "container": {"viscosity": True, "dosurfacetension": True}}
        if "particle_separation" in controls:
            initial["fluid_source"]["particlesep"] = controls["particle_separation"]
            initial["surface"] = {"particlesep": controls["particle_separation"]}
    elif pack_id == "procedural_geometry_v1":
        initial = {"point_variation": {"attrib": "pscale", "class": "point", "operation": "set", "valuetype": "rand", "rangemethod": "minplusrange", "minvalue": 1.0}}
    elif pack_id == "vellum_cloth_v1":
        initial = {"constraints": {"constrainttype": "cloth", "dothickness": "on", "stretchstiffnessexp": 0, "bendstiffnessexp": 0}, "collision_transform": {"ty": -2.0}}
    pending = []
    for role, values in initial.items():
        node = hou.node(roles.get(role, ""))
        for name, value in values.items():
            if name.endswith("stiffnessexp") and fresh_roles is not None and role not in fresh_roles:
                continue
            parameter = _resolve_parm_target(node, [name]) if node is not None else None
            if parameter is None:
                raise BridgeCommandError("UNSUPPORTED_PARAMETER", "native recipe parameter is unavailable: {}.{}".format(role, name))
            snapshot = _snapshot_parm_state(parameter)
            if parameter.isLocked() or _parm_snapshot_is_driven(snapshot):
                raise BridgeCommandError("PARAMETER_STATE_UNSUPPORTED", "native initialization target is locked or driven: " + parameter.path())
            pending.append((role + "." + name, value, parameter, snapshot))
    readback = {}
    attempted = []
    try:
        for key, value, parameter, snapshot in pending:
            attempted.append((parameter, snapshot))
            readback[key] = _set_parm_verified(parameter, value)
        for key, value, parameter, snapshot in pending:
            if not _values_match(value, _read_parm_for_request(parameter, value)):
                raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "native initialization write set drifted: " + parameter.path())
    except Exception:
        for parameter, snapshot in reversed(attempted):
            _restore_parm_snapshot(parameter, snapshot)
        raise
    return readback


def _fx_static_domain_readback(pack_id, roles, pack=None):
    """Verify complete non-simulating native graphs from their declared ports."""
    if isinstance(pack, dict) and pack.get("shared_render_schema"):
        return _fx_planned_domain_static_readback(pack_id, roles, pack)
    if isinstance(pack,dict) and pack.get("native_plan_schema") == "bridge.native-render-domains/1":
        import hou
        version = hou.applicationVersionString()
        requirements = pack["nodes"]
        for requirement in requirements:
            node = hou.node(str(roles.get(requirement["role"]) or ""))
            expected_category = {'rop':'driver', 'obj':'object'}.get(requirement["category"], requirement["category"])
            if node is None or node.type().name() not in requirement["types"] or node.type().category().name().lower() != expected_category:
                raise BridgeCommandError("GRAPH_CONTRACT_UNVERIFIED","native render role/type drifted: " + requirement["role"])
            parent_role = requirement.get("parent_role")
            if parent_role and node.parent() != hou.node(roles[parent_role]):
                raise BridgeCommandError("GRAPH_CONTRACT_UNVERIFIED","native render parent drifted: " + requirement["role"])
        declared = _fx_render_domain_connections(pack_id,roles)
        for wire in declared:
            node = hou.node(roles[wire["destination_role"]])
            actual = {connection.inputIndex():(connection.inputNode().path(),connection.outputIndex()) for connection in node.inputConnections()}
            if actual.get(wire["destination_input"]) != (roles[wire["source_role"]],wire["source_output"]):
                raise BridgeCommandError("GRAPH_CONTRACT_UNVERIFIED","native render connection drifted")
        terminal = hou.node(roles["settings_binding"] if "settings_binding" in roles else roles["material_binding"])
        sample_frame = float(hou.frame())
        if sample_frame.is_integer():
            sample_frame = int(sample_frame)
        stage = terminal.stage(frame=sample_frame,apply_viewport_overrides=False,ignore_errors=False)
        prefix = hou.node(roles["geometry_import"]).parm("pathprefix").eval()
        if 'ground_import' in roles:
            prefix = prefix.rsplit('/', 1)[0]
        imported = sorted(str(prim.GetPath()) for prim in stage.Traverse()
                          if str(prim.GetPath()).startswith(prefix.rstrip("/")+"/") and
                          prim.GetTypeName() in {"Mesh","Sphere","Cube","Cone","Cylinder","Capsule","Points","BasisCurves","Volume"})
        if not stage.GetPrimAtPath(prefix) or not imported:
            raise BridgeCommandError("GRAPH_CONTRACT_UNVERIFIED","SOP Import has no actual renderable prim under its explicit prefix")
        binding_readback = {"geometry_prefix":prefix,"imported_prim_paths":imported,
                            "stage_sha256":hashlib.sha256(stage.ExportToString().encode("utf-8")).hexdigest()}
        if pack_id == "material_lookdev_v1":
            material = hou.node(roles["material_binding"]).parm("matspecpath1").eval()
            authored_material = stage.GetPrimAtPath(material)
            targets = [str(path) for path in stage.GetPrimAtPath(prefix).GetRelationship("material:binding").GetTargets()]
            if not authored_material or authored_material.GetTypeName() != "Material" or targets != [material]:
                raise BridgeCommandError("GRAPH_CONTRACT_UNVERIFIED","actual imported USD geometry lacks its exact material binding")
            binding_readback["material_prim_path"] = material
        if "render" in roles:
            binding_readback["render_config"] = _fx_render_configuration(hou.node(roles["render"]),[sample_frame])
            for configuration in binding_readback["render_config"].values():
                if (configuration.get("loppath") != terminal.path()
                        or configuration.get("usd_sha256") != binding_readback["stage_sha256"]):
                    raise BridgeCommandError("GRAPH_CONTRACT_UNVERIFIED", "render Driver does not consume the verified final USD stage")
            if version in ("22.0.429", "22.0.459"):
                settings = hou.node(roles["settings"])
                width = settings.parm("pixelfiltersize").eval()
                scale = settings.parm("pixelfilterscale").eval()
                settings_prim = stage.GetPrimAtPath(settings.parm("primpath").eval())
                attribute = settings_prim.GetAttribute("karma:global:pixelfiltersize") if settings_prim else None
                usd_width = attribute.Get() if attribute else None
                if ((not attribute and width != 2) or
                        (attribute and (str(attribute.GetTypeName()) != 'float' or
                            type(usd_width) not in (float,int) or not math.isfinite(usd_width) or
                            not _values_match(float(width),float(usd_width))))):
                    raise BridgeCommandError("GRAPH_CONTRACT_UNVERIFIED", "H22 legacy pixel filter width has no matching authored USD value")
                binding_readback["pixel_filter"] = {"unit":"pixels", "width":width, "scale":scale,
                    "usd_legacy_width":usd_width}
        return {"version":version,"output_role":"settings_binding" if "settings_binding" in roles else "material_binding",
                "output_kind":"usd_render_stage" if "render" in roles else "material_bound_usd_stage",
                "basis":["same-version HDA/helper source + actual HOM ports/types/initialization readback"],
                "topology_and_parameters_verified":True,"native_geometry_validated":False,"usd_binding_readback":binding_readback}
    contract = _FX_STATIC_DOMAIN_GRAPHS.get(pack_id)
    if contract is None:
        # Source/domain adapters may derive a task-local prepared pack (for
        # example source_volume -> solver) or a test-owned explicit wire
        # contract.  Reading the global base pack here would verify a
        # different graph and falsely reject the native readback.
        base_pack = _FX_PACKS.get(pack_id)
        if (isinstance(pack, dict) and
                (pack is not base_pack or
                 (pack_id == "pyro_smoke_v1" and "connections" in pack))):
            # The caller already performed exact readback of the prepared
            # pack's declared wires above.  Without a captured static native
            # contract for this derived/custom graph, do not promote it to an
            # editable domain graph merely because the synthetic topology is
            # internally consistent.
            return None
        pack = base_pack
        if not isinstance(pack, dict):
            return None
        declared = list(pack.get("connections") or [])
        if not declared:
            declared = [
                {"source_role": str(item["input_role"]), "source_output": 0,
                 "destination_role": str(item["role"]), "destination_input": 0}
                for item in pack.get("nodes") or []
                if isinstance(item, dict) and item.get("input_role")
            ]
        required_inputs = tuple(
            (str(item.get("destination_role")), int(item.get("destination_input", 0)),
             str(item.get("source_role")), int(item.get("source_output", 0)))
            for item in declared if isinstance(item, dict)
        )
        contract = {
            "versions": ("21.0.631", "22.0.429", "22.0.459"),
            "output_kind": "editable_domain_topology",
            "output_role": "output" if "output" in roles else next(iter(roles), ""),
            "basis": ["software_native_api_boundary/captured-interface-adapter"],
            "required_roles": tuple(str(item.get("role")) for item in pack.get("nodes") or []),
            "required_inputs": required_inputs,
            "software_adapter": True,
        }
    import hou
    version = hou.applicationVersionString()
    if version not in contract["versions"]:
        raise BridgeCommandError("UNSUPPORTED_DOMAIN_VERSION", "native graph mapping is not recorded for " + version)
    missing = [name for name in contract["required_roles"] if hou.node(str(roles.get(name) or "")) is None]
    if missing:
        raise BridgeCommandError("SCENE_STATE_MISSING", "native graph lacks roles: " + ", ".join(missing))
    for wire_contract in contract["required_inputs"]:
        role, port, source_role = wire_contract[:3]
        source_port = wire_contract[3] if len(wire_contract) == 4 else 0
        node = hou.node(roles[role])
        inputs = {wire.inputIndex(): (wire.inputNode().path(), wire.outputIndex()) for wire in node.inputConnections()}
        if inputs.get(port) != (roles[source_role], source_port):
            raise BridgeCommandError("GRAPH_CONTRACT_UNVERIFIED", "native graph input differs: {}[{}]".format(role, port))
    if pack_id == "water_ocean_v1":
        node = hou.node(roles["evaluate"])
        parameter = _resolve_parm_target(node, ["deformgeo"])
        if parameter is None:
            raise BridgeCommandError("UNSUPPORTED_PARAMETER", "Ocean Evaluate deformgeo is missing")
        _set_parm_verified(parameter, True)
    return {"version": version, "output_role": contract["output_role"],
            "output_kind": contract["output_kind"], "basis": list(contract["basis"]),
            "topology_and_parameters_verified": True, "native_geometry_validated": False}


def _fx_build_preview_preflight(
    params: dict[str, Any], pack_id: str, pack: dict[str, Any],
) -> dict[str, Any]:
    """Perform all read-only build checks before the root can be mutated."""
    import hou

    task_id = str(params.get("task_id") or "")
    if not task_id:
        raise BridgeCommandError("INVALID_ARGUMENT", "task_id is required")
    execution_root = _fx_execution_root(params)
    source_plan_binding = _fx_source_plan_host_patch(params, pack_id, pack)
    domain_binding = _fx_domain_control_binding(params, pack_id, pack)
    prepared_pack = _fx_source_plan_pack(pack, source_plan_binding)
    if execution_root is not None and not pack.get("shared_render_schema"):
        prepared_pack = dict(prepared_pack)
        omitted = {
            str(node.get("role")) for node in prepared_pack.get("nodes") or []
            if node.get("category") == "lop" and node.get("role") == "render_settings"
        }
        unsupported = [
            str(node.get("role")) for node in prepared_pack.get("nodes") or []
            if node.get("category") not in {"sop", "dop"} and str(node.get("role")) not in omitted
        ]
        connected_omissions = [
            wire for wire in _fx_pack_declared_connections(prepared_pack)
            if wire.get("source_role") in omitted or wire.get("destination_role") in omitted
        ]
        if unsupported or connected_omissions:
            raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "execution root cannot bind all domain roles without a registered native layout")
        prepared_pack["nodes"] = [
            node for node in prepared_pack.get("nodes") or []
            if str(node.get("role")) not in omitted
        ]
    probe = _fx_probe_pack(pack_id, prepared_pack)
    if not probe["node_contract_available"]:
        missing = [item["role"] for item in probe["nodes"] if not item["available"]]
        raise BridgeCommandError(
            "UNSUPPORTED_NODE",
            "{} is unavailable in this Houdini installation; missing roles: {}".format(
                pack_id, ", ".join(missing)
            ),
            "Use capabilities.get to inspect exact node and parameter probes.",
        )
    _fx_prepare_source_runtime(source_plan_binding, prepared_pack)
    _fx_prepare_source_runtime(domain_binding, prepared_pack)
    root_path, _stage_path = _fx_task_paths(task_id, execution_root)
    root = hou.node(root_path)
    _manifest_root, existing = _fx_manifest(
        task_id, required=False, root_path=execution_root
    )
    if existing and existing.get("domain_pack") not in {None, pack_id}:
        raise BridgeCommandError("SCENE_CONFLICT", "task already owns a different effect domain pack")
    if root is not None and root.userData("bridge_fx_owned") != "1":
        raise BridgeCommandError(
            "SCENE_CONFLICT", "refusing to reuse a non-Bridge node at {}".format(root_path)
        )
    roles = dict(existing.get("nodes") or {})
    if pack_id=='swarm_flocking_v1':
        _fx_swarm_host().build_preflight(roles,prepared_pack)
    if source_plan_binding is not None:
        # A manifest is not authorization to address another scene network.
        # Check every persisted SOP endpoint before any create/connect/set call.
        for requirement in prepared_pack.get("nodes") or []:
            if requirement.get("category") != "sop":
                continue
            path = roles.get(str(requirement["role"]))
            if path and (not isinstance(path, str) or not path.startswith(root_path + "/")):
                raise BridgeCommandError(
                    "SCENE_CONFLICT",
                    "source adapter endpoint is outside the task-owned root",
                )
            node = hou.node(path) if path else None
            expected_parent = hou.node(roles.get(requirement.get('parent_role'), '')) if requirement.get('parent_role') else root
            if node is not None and (root is None or node.parent() != expected_parent):
                raise BridgeCommandError(
                    "SCENE_CONFLICT",
                    "source adapter endpoint is outside its declared task-owned parent",
                )
    _fx_preflight_source_plan_targets(source_plan_binding, roles, prepared_pack, existing)
    _fx_preflight_source_plan_targets(domain_binding, roles, prepared_pack, existing)
    _fx_preflight_existing_candidate_patch(existing, roles, prepared_pack)
    return {
        "execution_root": execution_root,
        "source_plan_binding": source_plan_binding,
        "domain_control_binding": domain_binding,
        "pack": prepared_pack,
        "probe": probe,
        "root_path": root_path,
        "root": root,
        "existing": existing,
        "roles": roles,
    }


def _fx_build_preview(params: dict[str, Any], pack_id: str, pack: dict[str, Any]) -> dict[str, Any]:
    """Fence the complete native FX build, including root creation."""
    import hou

    task_id = str(params.get("task_id") or "")
    if not task_id:
        raise BridgeCommandError("INVALID_ARGUMENT", "task_id is required")
    # This call is intentionally outside the root mutation fence: it is a
    # read-only gate that must reject source-plan drift, unsupported native
    # definitions, and driven persisted targets before root creation.
    _fx_build_preview_preflight(params, pack_id, pack)
    execution_root = _fx_execution_root(params)
    root_path, _stage_path = _fx_task_paths(task_id, execution_root)
    created_root = False
    if hou.node(root_path) is None:
        # There is no lease to check before the first node exists.  The root
        # lock still fences the create/recheck pair; the lease is issued before
        # any subsequent build mutation enters the full fence.
        with _root_lease_locked(root_path):
            if hou.node(root_path) is None:
                parent = hou.node("/obj")
                if parent is None:
                    raise BridgeCommandError("SCENE_STATE_MISSING", "/obj network is missing")
                created = parent.createNode("subnet" if (pack.get("native_plan_schema") == "bridge.native-render-domains/1" or pack.get("shared_render_schema")) else "geo", root_path.rsplit("/", 1)[-1])
                if created is None:
                    raise BridgeCommandError("SCENE_STATE_MISSING", "Houdini did not return the created FX root")
                created.setUserData("bridge_fx_owned", "1")
                created_root = True
        if created_root:
            _root_lease_issue(root_path, task_id, scope="sop")
    with _root_lease_fence(root_path, task_id=task_id, scope="sop"), (
            _fx_particle_emission_host().build_transaction(root_path) if pack_id == 'particles_v1' else nullcontext()):
        if pack.get('shared_render_schema') and (_fx_configuration(params).get('source_plan') is not None or
                pack_id in {'swarm_flocking_v1', 'procedural_geometry_v1'}):
            return _fx_build_preview_source_transaction(params,pack_id,pack,hou.node(root_path))
        return _fx_build_preview_unfenced(params, pack_id, pack)


def _fx_build_preview_source_transaction(params, pack_id, pack, root):
    """Source/Swarm build rollback under the caller's existing root lease fence."""
    import hou
    preflight = _fx_build_preview_preflight(params, pack_id, pack)
    binding, roles = preflight['source_plan_binding'], preflight['roles']
    swarm = pack_id=='swarm_flocking_v1'
    program_domain = swarm or pack_id == 'procedural_geometry_v1'
    swarm_prepared = []
    persistence = _fx_snapshot_manifest_persistence(root, str(params['task_id']))
    before_nodes = {n.path():n for n in root.allSubChildren()}
    snapshots = {}
    preview = hou.node(roles.get('source_volume',''))
    preview_parent = preview.parent() if preview is not None else hou.node(roles.get('geometry_network',''))
    flags = {}
    if preview_parent is not None:
        for node in preview_parent.children():
            if node.type().category().name().lower() != 'sop':
                continue
            pairs = (('isDisplayFlagSet','setDisplayFlag'),('isRenderFlagSet','setRenderFlag'))
            for getter,setter in pairs:
                if not callable(getattr(node,getter,None)) or not callable(getattr(node,setter,None)):
                    raise BridgeCommandError('NATIVE_CONTROL_INTERFACE_REQUIRED','native source preview flag API is absent')
                value = getattr(node,getter)()
                if type(value) is not bool:
                    raise BridgeCommandError('NATIVE_CONTROL_INTERFACE_REQUIRED','native source preview flag is not a bool')
                flags[node.path(),getter] = (node,setter,value)
    runtime = _fx_solver_sourcing_runtime(binding,roles,pack,preflight['existing'],require_nodes=True) if before_nodes and not program_domain else None
    if runtime:
        for item in runtime['parameters']:
            snapshots[item['parm'].path()] = (item['parm'],item['snapshot'])
        count = runtime['count_parm']
        snapshots[count.path()] = (count,runtime['count_snapshot'])
    if before_nodes and program_domain:
        controls = {**(preflight['existing'].get('candidate_patch') or {}),
                    **((preflight['domain_control_binding'] or {}).get('host_controls') or {})}
        if controls:
            swarm_prepared = _fx_planned_domain_prepared(pack_id,controls,roles,preflight['pack'])
            for item in swarm_prepared:
                snapshots[item['parm'].path()] = (item['parm'],item['snapshot'])
    if before_nodes and not program_domain:
        for name in binding['host_controls']:
            for target in _fx_control_target_specs(_fx_source_control_spec(name,pack)):
                parm = _resolve_parm_target(hou.node(roles[target['role']]),list(target['aliases']))
                if parm is None:
                    raise BridgeCommandError('UNSUPPORTED_PARAMETER','persisted source target is absent: '+name)
                snapshots.setdefault(parm.path(),(parm,_snapshot_parm_state(parm)))
    wires = {path:{c.inputIndex():(c.inputNode(),c.outputIndex()) for c in n.inputConnections()}
             for path,n in before_nodes.items()}
    try:
        with _fx_geometry_build_transaction(root.path()) if pack_id == 'procedural_geometry_v1' else nullcontext():
            return _fx_build_preview_unfenced(params,pack_id,pack)
    except Exception as error:
        failures = []
        try:
            _fx_restore_source_parameter_snapshots(snapshots.values())
        except Exception as exc:
            failures.append(str(exc))
        for item in swarm_prepared:
            if 'geometry_snapshot' in item:
                try:_fx_restore_planned_item(item,roles,pack)
                except Exception as exc:failures.append('geometry_registration:'+str(exc))
            if 'swarm_snapshot' in item:
                try:_fx_swarm_host().restore(item)
                except Exception as exc:failures.append('swarm_registration:'+str(exc))
        for path,node in before_nodes.items():
            try:
                actual = {c.inputIndex():(c.inputNode(),c.outputIndex()) for c in node.inputConnections()}
                for index in sorted(set(actual)|set(wires[path])):
                    if actual.get(index) != wires[path].get(index):
                        source,output = wires[path].get(index,(None,0))
                        node.setInput(index,source,output)
            except Exception as exc:
                failures.append(path+':'+str(exc))
        for node in sorted(root.allSubChildren(),key=lambda n:n.path().count('/'),reverse=True):
            if node.path() not in before_nodes:
                try:node.destroy()
                except Exception as exc:failures.append(node.path()+':'+str(exc))
        # Restore the complete sibling selection after removing fresh nodes.
        # Clearing first avoids a later false setter undoing a true selection.
        for selected in (False,True):
            for (path,getter),(node,setter,value) in flags.items():
                if value is not selected:
                    continue
                try:getattr(node,setter)(value)
                except Exception as exc:failures.append(path+'/'+getter+':'+str(exc))
        for (path,getter),(node,setter,value) in flags.items():
            try:
                if getattr(node,getter)() is not value:
                    raise ValueError('native source preview flag readback differs')
            except Exception as exc:failures.append(path+'/'+getter+':'+str(exc))
        try:_fx_restore_manifest_persistence(root,persistence)
        except Exception as exc:failures.append('manifest:'+str(exc))
        if failures:
            raise BridgeCommandError('SOURCE_BUILD_ROLLBACK_FAILED','source build failed and rollback differs: '+', '.join(failures)) from error
        raise
    finally:
        _fx_release_planned_items(swarm_prepared)


def _fx_build_preview_unfenced(params: dict[str, Any], pack_id: str, pack: dict[str, Any]) -> dict[str, Any]:
    import hou

    preflight = _fx_build_preview_preflight(params, pack_id, pack)
    task_id = str(params.get("task_id") or "")
    execution_root = preflight["execution_root"]
    source_plan_binding = preflight["source_plan_binding"]
    domain_binding = preflight["domain_control_binding"]
    pack = preflight["pack"]
    probe = preflight["probe"]
    root_path = preflight["root_path"]
    root = preflight["root"]
    existing = preflight["existing"]
    fresh_project = not existing and not root.allSubChildren(recurse_in_locked_nodes=False) if root is not None else not existing
    roles = preflight["roles"]
    # Preflight every persisted semantic write before creating or connecting a
    # single node.  Rebuilding must not partially alter the scene and only then
    # discover that an existing target carries animation, an expression, or a
    # channel reference that a literal patch would destroy/follow.
    declared_connections = list(pack.get("connections") or [])
    _legacy = [entry for entry in (pack.get("nodes") or []) if isinstance(entry, dict) and entry.get("input_role")]
    if not declared_connections and _legacy:
        declared_connections = [
            {"source_role": str(entry["input_role"]), "source_output": 0,
             "destination_role": str(entry["role"]), "destination_input": 0}
            for entry in _legacy
        ]
    symbolic = [wire for wire in declared_connections if "source_output_name" in wire or "destination_input_name" in wire]
    if symbolic and pack.get("native_plan_schema") != "bridge.native-render-domains/1":
        raise BridgeCommandError("GRAPH_CONTRACT_INVALID", "unregistered symbolic ports")
    contract = _load_core_contract().validate_connection_set(
        [wire for wire in declared_connections if wire not in symbolic],
        [str(item.get("role")) for item in pack.get("nodes") or []]
    )
    if not contract["ok"]:
        raise BridgeCommandError(
            "GRAPH_CONTRACT_INVALID",
            "{} connection contract rejected before any side effect: {}".format(pack_id, json.dumps(contract["errors"], ensure_ascii=False)),
            "Fix the domain pack connection contract; no node was created or modified.",
        )
    declared_connections = contract["connections"]
    if root is None:
        obj = hou.node("/obj")
        if obj is None:
            raise BridgeCommandError("SCENE_STATE_MISSING", "/obj network is missing")
        root = obj.createNode("subnet" if (pack.get("native_plan_schema") == "bridge.native-render-domains/1" or pack.get("shared_render_schema")) else "geo", root_path.rsplit("/", 1)[-1])
        if root is None:
            raise BridgeCommandError("SCENE_STATE_MISSING", "Houdini did not return the created FX root")
        root.setUserData("bridge_fx_owned", "1")
        _root_lease_issue(str(root.path()), task_id, scope="sop")
    created: list[Any] = []
    new_count_initialization = {}
    manifest_sources: dict[str, Any] = {}
    connection_report: dict[str, Any] = {"declared": declared_connections, "verified": [], "errors": []}
    with _undo("Bridge FX build editable {} preview".format(pack_id)):
        for requirement in pack.get("nodes") or []:
            role = str(requirement["role"])
            existing_node = hou.node(str(roles.get(role) or "")) if roles.get(role) else None
            if existing_node is not None:
                continue
            parent = _fx_parent_for(str(requirement["category"]), root, task_id, execution_root, requirement=requirement, roles=roles)
            # The material node is outside the per-task SOP root.  Derive its
            # name from the complete task id so sibling scenarios cannot
            # collide merely because their first hexadecimal characters match.
            suffix = hashlib.sha256(task_id.encode("utf-8")).hexdigest()[:8]
            name = "{}_{}".format(_fx_node_name(role), suffix) if requirement["category"] == "vop" else _fx_node_name(role)
            collision = parent.node(name)
            if collision is not None:
                raise BridgeCommandError("SCENE_CONFLICT", "refusing to overwrite existing node {}".format(collision.path()))
            node_type = _fx_resolve_type(requirement)
            if node_type is None:
                raise BridgeCommandError("UNSUPPORTED_NODE", "node role {} has no compatible native type".format(role))
            try:
                node = parent.createNode(node_type.name(), name)
            except Exception as exc:
                raise BridgeCommandError("NODE_CREATE_FAILED", "could not create {}: {}".format(node_type.name(), exc)) from exc
            roles[role] = node.path()
            if role == "source":
                source_menu_choice = _fx_apply_source_polygon_menu(node)
                if source_menu_choice is not None:
                    manifest_sources[role] = source_menu_choice
            created.append(node)
            new_count_initialization[role] = _fx_initialize_new_owned_counts(node)
        if pack.get("native_plan_schema") == "bridge.native-render-domains/1":
            declared_connections = _fx_render_domain_connections(pack_id, roles)
            actual_contract = _load_core_contract().validate_connection_set(declared_connections, list(roles))
            if not actual_contract["ok"]:
                raise BridgeCommandError("GRAPH_CONTRACT_INVALID", "runtime named-port graph is invalid")
            declared_connections = actual_contract["connections"]
            connection_report["declared"] = declared_connections
        for conn in declared_connections:
            source = hou.node(str(roles.get(str(conn["source_role"])) or ""))
            node = hou.node(str(roles.get(str(conn["destination_role"])) or ""))
            if node is None or source is None:
                raise BridgeCommandError("SCENE_STATE_MISSING", "declared effect node connection is missing")
            if node.parent() != source.parent():
                raise BridgeCommandError("UNSUPPORTED_NODE", "cross-context connection is not supported for {}.input{}".format(conn["destination_role"], conn["destination_input"]))
            try:
                node.setInput(int(conn["destination_input"]), source, int(conn["source_output"]))
            except Exception as exc:
                raise BridgeCommandError("UNSUPPORTED_NODE", "cannot connect {}.output{} -> {}.input{}: {}".format(
                    conn["source_role"], conn["source_output"], conn["destination_role"], conn["destination_input"], exc)) from exc
        # Verify against native port indices (not compact array position).
        for conn in declared_connections:
            node = hou.node(str(roles.get(str(conn["destination_role"])) or ""))
            native = {c.inputIndex(): (c.inputNode().path(), c.outputIndex()) for c in node.inputConnections()}
            actual = native.get(int(conn["destination_input"]))
            expected = (str(roles.get(str(conn["source_role"]))), int(conn["source_output"]))
            entry = dict(conn)
            entry["native_readback"] = {"source_path": actual[0] if actual else None, "source_output": actual[1] if actual else None}
            entry["verified"] = actual == expected
            connection_report["verified"].append(entry)
            if not entry["verified"]:
                connection_report["errors"].append("{}: expected {}.output{} on input {}, native says {!r}".format(
                    conn["destination_role"], conn["source_role"], conn["source_output"], conn["destination_input"], actual))
        if connection_report["errors"]:
            failure_manifest = dict(existing) if isinstance(existing, dict) else {}
            failure_manifest.update({
                "task_id": task_id,
                "domain_pack": pack_id,
                "execution_root": root_path,
                "nodes": dict(roles),
                "build_state": "BUILD_FAILED",
                "connections": connection_report,
                "source_menu_choices": dict(manifest_sources),
            })
            _fx_store_manifest(root, failure_manifest)
            raise BridgeCommandError(
                "GRAPH_CONTRACT_UNVERIFIED",
                "{} connection readback does not match the contract: {}".format(pack_id, connection_report["errors"]),
                "The task-owned partial build is kept and marked BUILD_FAILED in the scene manifest; repair or delete it explicitly.",
            )
        # Source-only construction must not display/cook the simulation branch.
        preview_role = "source_volume" if source_plan_binding is not None else "output"
        output = hou.node(str(roles.get(preview_role) or ""))
        if output is not None and execution_root is None:
            try:
                output.setDisplayFlag(True)
                output.setRenderFlag(True)
            except Exception:
                pass
        parents = {node.parent() for node in created}
        for parent in parents:
            try:
                parent.layoutChildren(items=[node for node in created if node.parent() == parent])
            except Exception:
                pass
        # A durable sidecar can outlive the embedded Python process.  When a
        # saved scene is reopened (or the task is explicitly rebuilt), restore
        # the previously selected semantic patch rather than claiming default
        # parameters still represent that approved candidate.
        fresh_roles = {role for role,path in roles.items() if any(node.path() == path for node in created)}
        native_initialization = (_fx_initialize_render_domain(params,pack_id,roles,pack,fresh_roles)
            if pack.get("native_plan_schema") == "bridge.native-render-domains/1"
            else _fx_initialize_planned_domain(params,pack_id,roles,pack,fresh_roles)
            if pack.get('shared_render_schema') else _fx_initialize_native_domain(pack_id,roles,domain_binding,fresh_roles=fresh_roles))
        # Native initialization establishes the gates. Now inspect actual
        # source instances before the source adapter's parameter transaction.
        _fx_preflight_source_plan_targets(
            source_plan_binding, roles, pack, existing, require_nodes=True,
        )
        native_initialization["new_owned_multiparms"] = new_count_initialization
        for role, path in roles.items():
            settings = hou.node(str(path))
            if settings is not None and str(settings.type().nameWithCategory()) == "Lop/karmarendersettings":
                native_initialization[role + ".exr_format"] = _fx_configure_render_output(settings)
        if existing.get("candidate_patch"):
            restored = {"host_controls":existing["candidate_patch"],"runtime_values":existing["candidate_patch"]}
            _fx_apply_source_plan_targets(restored,roles,pack,existing)
        source_plan_applied = _fx_apply_source_plan_targets(source_plan_binding, roles, pack, existing)
        domain_plan_applied = _fx_apply_source_plan_targets(domain_binding, roles, pack, existing)
    project_resources_enabled = (pack_id == 'pyro_smoke_v1' and source_plan_binding is not None
        or pack_id == 'procedural_geometry_v1' and bool(pack.get('shared_render_schema'))
        or (params.get('frozen_render_scene') or {}).get('profile') == 'sphere_ground_v2')
    with _fx_project_environment_transaction(root, task_id, roles,
            _task_output_dir(params) if project_resources_enabled else Path("."),
            fresh=fresh_project, existing=existing, enabled=project_resources_enabled) as project_environment:
        static_domain_readback = _fx_static_domain_readback(pack_id, roles, pack)
        fx = _fx_configuration(params)
        previous_plan_controls = dict(existing.get("source_plan_host_controls") or {})
        previous_plan_controls.update(existing.get("domain_control_values") or {})
        current_plan_controls = dict((source_plan_binding or {}).get("host_controls") or {})
        current_plan_controls.update((domain_binding or {}).get("host_controls") or {})
        previous_solver_controls = dict(existing.get("source_plan_solver_controls") or {})
        current_solver_controls = dict((source_plan_binding or {}).get("solver_sourcing_runtime_controls") or {})
        changed_source_controls = sorted(
            name for name in set(previous_plan_controls) | set(current_plan_controls)
            if previous_plan_controls.get(name) != current_plan_controls.get(name)
        )
        changed_solver_controls = sorted(
            name for name in set(previous_solver_controls) | set(current_solver_controls)
            if previous_solver_controls.get(name) != current_solver_controls.get(name)
        )
        changed_source_controls.extend("solver_sourcing." + name for name in changed_solver_controls)
        changed_source_controls = sorted(set(changed_source_controls))
        source_invalidates = sorted({
            str(((pack.get("controls") or {}).get(name) or {}).get("invalidates_from") or "generation_simulation")
            for name in changed_source_controls
        })
        manifest = {
            **existing,
            "schema": "houdini.fx.scene_manifest/1.0",
            "task_id": task_id,
            "domain_pack": pack_id,
            "pack_version": "1.0.0",
            "maturity": probe.get("maturity", "experimental"),
            "houdini_version": hou.applicationVersionString(),
            "hip_path": hou.hipFile.path(),
            "execution_root": root_path,
            "short_segment_scoped": execution_root is not None,
            "nodes": roles,
            "build_state": "BUILT_VERIFIED",
            "connections": connection_report,
            "source_menu_choices": dict(manifest_sources),
            "candidate_patch": dict(existing.get("candidate_patch") or {}),
            "source_adapter_contract": (source_plan_binding or {}).get("source_contract"),
            "source_plan_sha256": (source_plan_binding or {}).get("plan_sha256"),
            "source_input_binding_sha256": (source_plan_binding or {}).get("input_binding_sha256"),
            "source_plan_host_controls": current_plan_controls,
            "source_program_registration": (source_plan_binding or {}).get("source_program_registration"),
            "source_plan_host_readback": locals().get("source_plan_applied", {}),
            "domain_control_plan_sha256": (domain_binding or {}).get("plan_sha256"),
            "domain_control_values": dict((domain_binding or {}).get("host_controls") or {}),
            "domain_control_readback": locals().get("domain_plan_applied", {}),
            "native_initialization": native_initialization,
            "source_plan_solver_controls": current_solver_controls,
            "solver_sourcing": (source_plan_binding or {}).get("solver_sourcing_runtime_result"),
            "solver_sourcing_contract": ((source_plan_binding or {}).get("solver_sourcing") or {}).get("contract"),
            "source_plan_guards": dict((source_plan_binding or {}).get("guards") or {}),
            "source_plan_invalidates_from": source_invalidates,
            "source_plan_cache_invalidated": bool(changed_source_controls and "cache" in existing),
            "revision": int(existing.get("revision") or 0),
            "seed": int(fx.get("seed") or 0),
            "input_digest": hashlib.sha256(json.dumps(params.get("inputs") or [], ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest(),
            "reference_analysis": fx.get("reference_analysis") if isinstance(fx.get("reference_analysis"), dict) else {},
            "perceptual_issue": fx.get("perceptual_issue") if isinstance(fx.get("perceptual_issue"), dict) else {},
        }
        if changed_source_controls and "cache" in manifest:
            # The actual emitted source program is part of host_controls. Schedule,
            # cone, direction and speed changes therefore invalidate cached subjects.
            manifest.pop("cache", None)
            manifest["source_plan_cache_invalidated"] = True
        stage_timings: dict[str, float] = {}
        cook_failures: list[dict[str, Any]] = []
        cooked_roles: list[str] = []
        for requirement in pack.get("nodes") or []:
            if requirement.get("category") != "sop":
                continue
            role = str(requirement.get("role"))
            if source_plan_binding is not None and role not in {"source", "source_points", "source_control", "source_volume"}:
                continue
            node = hou.node(str(roles.get(role) or ""))
            if node is None:
                cook_failures.append({"role": role, "errors": ["node missing after build"]})
                continue
            if execution_root is not None:
                # S-06 performs the only permitted cooks after setFrame has been
                # verified by the validator.  Building topology must not silently
                # count as an unbounded simulation frame.
                continue
            # Build-time verification is static ON PURPOSE: scene mutation only.
            # Frame/cook verification belongs to persistent operations, never to
            # request dispatch (first VEX cook under the request context is
            # host-pathological; serve-loop execution is the sanctioned path).
            item = {
                "path": node.path(),
                "type": node.type().nameWithCategory(),
                "cook_attempted": False,
                "errors": list(node.errors()),
                "cook_succeeded": not node.errors(),
            }
            if item["errors"]:
                cook_failures.append({"role": role, "errors": item["errors"], "cook_exception": None})
            else:
                cooked_roles.append(role)
        manifest["execution_assessment"] = {
            "sop_roles_cooked": cooked_roles,
            "source_only_construction": source_plan_binding is not None,
            "simulation_executed": False if source_plan_binding is not None else None,
            "cook_failures": cook_failures,
            "preview_kind": "editable_domain_graph" if static_domain_readback else "topology_scaffold",
            "native_graph_contract": static_domain_readback,
            "cookable_domain_network": False,
            "domain_graph_constructed": bool(static_domain_readback and not cook_failures),
            "production_supported": False,
            "render_validated": False,
            **_fx_validation_flags(pack, pack_id=pack_id),
            "state": "UNSUPPORTED" if cook_failures else "TOPOLOGY_SCAFFOLD",
            "build_state": "BUILD_FAILED" if cook_failures else "BUILT_VERIFIED_STATIC",
            "frame_verification": "deferred_to_operation",
            "connections_verified": all(entry.get("verified") for entry in connection_report["verified"]) if connection_report["verified"] else False,
            "stage_timings_seconds": stage_timings,
        }
        if project_environment is not None:
            manifest['project_environment'] = project_environment
            manifest['project_environment_sha256'] = _fx_scene_contract_digest(project_environment)
        _fx_store_manifest(root, manifest)
        if cook_failures:
            raise BridgeCommandError(
                "UNSUPPORTED_DOMAIN_RUNTIME",
                "{} native preview topology did not cook cleanly: {}".format(pack_id, json.dumps(cook_failures, ensure_ascii=False)),
                "This pack remains experimental; supply the missing domain inputs or validate a corrected node adapter on this Houdini build.",
            )
        return _fx_preview_operation_result(probe, manifest, reused=bool(existing and not created))


def _fx_preview_operation_result(
    probe: dict[str, Any],
    manifest: dict[str, Any],
    *,
    reused: bool,
) -> dict[str, Any]:
    """Describe a successful topology operation without claiming validation."""

    outcome_state = "DIAGNOSIS_INCONCLUSIVE"
    return {
        # The native nodes were created, connected and cooked, so the operation
        # itself succeeded.  Visual/causal verification remains explicitly
        # inconclusive until the requested field, AOV and render evidence exists.
        "gates": [
            {
                "name": "editable_native_fx_topology",
                "passed": True,
                "kind": "operation",
                "experimental": True,
                "outcome_state": outcome_state,
                "visual_validation": "INCONCLUSIVE",
            }
        ],
        "domain_pack": probe,
        "scene_manifest": manifest,
        "reused": reused,
        "execution_state": "EDITABLE_DOMAIN_GRAPH" if (manifest.get("execution_assessment") or {}).get("native_graph_contract") else "TOPOLOGY_SCAFFOLD",
        "cookable_domain_network": bool((manifest.get("execution_assessment") or {}).get("cookable_domain_network")),
        "domain_graph_constructed": bool((manifest.get("execution_assessment") or {}).get("domain_graph_constructed")),
        "real_execution_validated": False,
        "visual_validation": "INCONCLUSIVE",
        "outcome_state": outcome_state,
    }


def _fx_frame_values(params):
    """Bound the actual operation before expanding any frame set."""
    explicit = _fx_configuration(params).get("frames")
    frame_range = (params.get("render") or {}).get("frame_range") or {}
    start = frame_range.get("start",1)
    end = frame_range.get("end",start)
    stride = frame_range.get("step",1)
    if any(type(value) is not int for value in (start,end,stride)) or end < start or stride <= 0:
        raise BridgeCommandError("INVALID_ARGUMENT","operation frame range must contain ordered integers and a positive stride")
    count = (end-start)//stride + 1
    if count > 12:
        raise BridgeCommandError("SHORT_SEGMENT_LIMIT","one operation may contain at most 12 frames; solver history uses its separate compact range")
    expected = list(range(start,end+1,stride))
    if explicit is not None:
        if not isinstance(explicit,list) or not explicit or len(explicit)>12 or any(type(frame) is not int for frame in explicit) or explicit != sorted(set(explicit)):
            raise BridgeCommandError("INVALID_ARGUMENT","explicit operation frames must be at most 12 unique increasing integers")
        if len(explicit)>2 and len({b-a for a,b in zip(explicit,explicit[1:])}) != 1:
            raise BridgeCommandError("INVALID_ARGUMENT","explicit operation frames require one stride")
        if frame_range and explicit != expected:
            raise BridgeCommandError("APPROVAL_REVOKED","explicit frames differ from the frozen operation range")
        return list(explicit)
    return expected


def _fx_node_evidence(node: Any) -> dict[str, Any]:
    node_type = node.type()
    try:
        category = str(node_type.category().name()).lower()
    except Exception:
        category = "unknown"
    geometry_required = category == "sop"
    result: dict[str, Any] = {
        "path": node.path(),
        "type": node_type.nameWithCategory(),
        "category": category,
        "cook_attempted": True,
        "geometry_required": geometry_required,
        "geometry_available": None if not geometry_required else False,
    }
    cook_exception = None
    try:
        node.cook(force=True)
    except Exception as exc:
        cook_exception = str(exc)
    try:
        result["errors"] = list(node.errors())
    except Exception as exc:
        result["errors"] = ["could not inspect node errors: {}".format(exc)]
    try:
        result["warnings"] = list(node.warnings())
    except Exception:
        result["warnings"] = []
    result["cook_exception"] = cook_exception
    if geometry_required:
        try:
            geometry = node.geometry()
            bounds = geometry.boundingBox().sizevec()
            point_attributes = sorted(attribute.name() for attribute in geometry.pointAttribs())
            primitive_types: dict[str, int] = {}
            for primitive in geometry.prims():
                name = primitive.type().name()
                primitive_types[name] = primitive_types.get(name, 0) + 1
            result.update(
                {
                    "geometry_available": True,
                    "points": len(geometry.points()),
                    "primitives": len(geometry.prims()),
                    "bounds": [float(component) for component in bounds],
                    "point_attributes": point_attributes,
                    "primitive_types": primitive_types,
                }
            )
        except Exception as exc:
            result["geometry_available"] = False
            result["geometry_unavailable"] = str(exc)
    result["cook_succeeded"] = (
        cook_exception is None
        and not result["errors"]
        and (not geometry_required or result["geometry_available"] is True)
    )
    return result


def _fx_evidence_requirements(pack: dict[str, Any]) -> list[dict[str, Any]]:
    """Never infer visual/AOV evidence from a successfully created topology."""
    return [
        {"name": name, "available": False, "reason": "external AOV or field export not attached"}
        for name in pack.get("evidence") or []
    ]


def _fx_geometry_output_evidence(roles, pack, frame, budget):
    import hou
    from itertools import islice
    from houdini_bridge import native_geometry_observation as observer
    from houdini_bridge.native_geometry_controls_program import control_readback

    initial_budget = budget['remaining']
    before = _fx_geometry_observations(roles, pack)
    if hou.frame() != frame:
        raise BridgeCommandError('GEOMETRY_SOURCE_FRAME_REQUIRED', 'output observation frame changed')
    selected = ('instance_source', 'geometry_deform', 'instance_transform', 'scatter', 'point_variation', 'instance')
    nodes = {role: hou.node(roles[role]) for role in selected}
    sessions = {role: node.sessionId() for role, node in nodes.items()}
    states = {role: (node.type().name(), node.type().category().name(), node.isEditable(), node.isBypassed(),
                     tuple(islice(iter(node.errors()), 257))) for role, node in nodes.items()}
    outputs, inputs, missing, wires = {}, {}, [], {}

    def parameters():
        observed = {}
        for requirement in pack['nodes']:
            role = requirement['role']
            if role not in nodes:
                continue
            observed[role] = {}
            for aliases in requirement.get('required_parms', ()):
                name = '/'.join(aliases)
                try:
                    target = _resolve_parm_target(nodes[role], aliases)
                    observed[role][name] = _fx_planned_observation(nodes[role], target.name())
                except Exception:
                    observed[role][name] = {'observation_unavailable': True}
        return observed

    parameter_context = parameters()
    for role, facts in parameter_context.items():
        for name, fact in facts.items():
            if fact.get('observation_unavailable'):
                missing.append(dict(location=role + '/parm/' + name, code='GEOMETRY_PARAMETER_UNAVAILABLE'))

    def capture(node, label, acquire, source_path=None):
        if budget['remaining'] <= 0:
            missing.append(dict(location=label, code='GEOMETRY_OUTPUT_BUDGET_EXCEEDED'))
            return None
        errors = tuple(islice(iter(node.errors()), 257))
        if errors:
            missing.append(dict(location=label, code='GEOMETRY_NATIVE_COOK_FAILED'))
            return None
        try:
            observed = observer.collect(acquire(), node_path=source_path or node.path(), frame=frame, output_index=0)
        except observer.GeometryObservationError as error:
            missing.append(dict(location=label, code=error.code))
            return None
        except Exception:
            missing.append(dict(location=label, code='GEOMETRY_NATIVE_OUTPUT_UNAVAILABLE'))
            return None
        if tuple(islice(iter(node.errors()), 257)):
            missing.append(dict(location=label, code='GEOMETRY_NATIVE_COOK_FAILED'))
            return None
        encoded = json.dumps(observed, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')
        if len(encoded) > budget['remaining']:
            budget['remaining'] = 0
            missing.append(dict(location=label, code='GEOMETRY_OUTPUT_BUDGET_EXCEEDED'))
            return None
        budget['remaining'] -= len(encoded)
        return observed

    for role, node in nodes.items():
        if node.isBypassed() or not node.isEditable():
            raise BridgeCommandError('GEOMETRY_OWNED_GRAPH_REQUIRED', 'output carrier scope changed')
        connections = tuple(islice(iter(node.inputConnections()), 3))
        if len(connections) > 2:
            raise BridgeCommandError('GEOMETRY_SOURCE_CONNECTION_REQUIRED', 'extra output carrier inputs')
        wires[role] = [dict(input_index=wire.inputIndex(), output_index=wire.outputIndex(),
                            node_path=wire.inputNode().path()) for wire in connections]
        observed = capture(node, role, lambda node=node: node.geometry(output_index=0))
        if observed is not None:
            outputs[role] = observed
    consumption = []
    for destination, input_index, source in (
            ('geometry_deform', 0, 'instance_source'), ('instance_transform', 0, 'geometry_deform'),
            ('point_variation', 0, 'scatter'), ('instance', 0, 'instance_transform'),
            ('instance', 1, 'point_variation')):
        expected = dict(input_index=input_index, output_index=0, node_path=roles[source])
        if expected not in wires[destination]:
            raise BridgeCommandError('GEOMETRY_SOURCE_CONNECTION_REQUIRED', 'actual downstream input changed')
        node = nodes[destination]
        label = destination + '/input' + str(input_index)
        observed = capture(node, label, lambda node=node, index=input_index: node.inputGeometry(index), roles[source])
        if observed is not None:
            inputs[label] = observed
        consumption.append(dict(source_role=source, destination_role=destination, input_index=input_index,
                                matching_observed_data=(observed is not None and source in outputs
                                    and observed['geometry_sha256'] == outputs[source]['geometry_sha256'])))
    after = _fx_geometry_observations(roles, pack)
    if (after != before or parameters() != parameter_context or hou.frame() != frame
            or any(hou.node(roles[role]) is not node or node.sessionId() != sessions[role]
                   for role, node in nodes.items())
            or any((node.type().name(), node.type().category().name(), node.isEditable(), node.isBypassed(),
                    tuple(islice(iter(node.errors()), 257))) != states[role]
                   for role, node in nodes.items())
            or any([dict(input_index=wire.inputIndex(), output_index=wire.outputIndex(),
                         node_path=wire.inputNode().path())
                    for wire in islice(iter(node.inputConnections()), 3)] != wires[role]
                   for role, node in nodes.items())):
        raise BridgeCommandError('GEOMETRY_CONTEXT_CHANGED', 'output observation context changed')
    if _fx_geometry_observations(roles, pack) != before or hou.frame() != frame:
        raise BridgeCommandError('GEOMETRY_CONTEXT_CHANGED', 'authenticated output observation context changed')
    readback = control_readback(before['binding']['native_version'], before['context'], before['parameters'])
    deformation = None
    if 'instance_source' in outputs and 'geometry_deform' in outputs:
        source, deformed = outputs['instance_source'], outputs['geometry_deform']
        required = ('P', 'N', 'id')
        complete = all(name in observed['attributes']['point']
                       for observed in (source, deformed) for name in required)
        if not complete:
            missing.append(dict(location='geometry_deform', code='GEOMETRY_OUTPUT_ATTRIBUTES_UNOBSERVED'))
        topology = ('points', 'primitives', 'vertices', 'point_numbers', 'primitive_numbers', 'vertex_numbers',
                    'primitive_types', 'primitive_closed', 'polygons', 'polygon_vertices')
        unrelated = [{owner: {name: fact for name, fact in attributes.items()
                             if owner != 'point' or name != 'P'}
                      for owner, attributes in observed['attributes'].items()}
                     for observed in (source, deformed)]
        deformation = dict(required_point_attributes_observed=complete,
            topology_matches_source=all(source[name] == deformed[name] for name in topology),
            attributes_except_point_P_match_source=unrelated[0] == unrelated[1],
            point_P_matches_source=(source['attributes']['point'].get('P')
                                    == deformed['attributes']['point'].get('P')) if complete else None)
    result = dict(schema='bridge.geometry-output-observations/1', origin='runtime_hom',
                native_version=before['binding']['native_version'], binding=before['binding'], frame=frame,
                basis_sha256=readback['basis_sha256'], program_sha256=readback['program_sha256'],
                status='BLOCKED', evidence_scope='raw_geometry_observations', outputs=outputs,
                inputs=inputs, connections=wires, consumption=consumption, deformation=deformation, missing=missing,
                parameter_context=_json_safe(parameter_context),
                missing_evidence=readback['missing_evidence'])
    size = len(json.dumps(result, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8'))
    size += len(json.dumps(str(frame)).encode('utf-8')) + 2
    if size > initial_budget:
        budget['remaining'] = 0
        raise BridgeCommandError('GEOMETRY_OUTPUT_BUDGET_EXCEEDED', 'complete output evidence exceeds its byte budget')
    budget['remaining'] = initial_budget - size
    return result


def _fx_inspect_controls(params, pack_id, pack):
    task_id = params.get('task_id')
    requested_root = (params.get('bridge_execution_binding') or {}).get('execution_root')
    if (not isinstance(task_id, str) or not task_id or pack_id != 'rbd_destruction_v1'
            or params.get('controls') != ['velocity_variance'] or not isinstance(requested_root, str)):
        raise BridgeCommandError('UNSUPPORTED_NATIVE_CONTROL', 'an exact owned RBD velocity inspection is required')
    root, manifest = _fx_manifest(task_id, root_path=requested_root)
    if (root.path() != requested_root or manifest.get('task_id') != task_id
            or manifest.get('domain_pack') != pack_id):
        raise BridgeCommandError('SCENE_OWNERSHIP_REQUIRED', 'inspection must target the registered task scene')
    roles = manifest.get('nodes') or {}
    with _root_lease_fence(requested_root, task_id=task_id, scope='sop'):
        if _fx_planned_owned_root(roles, pack) != requested_root:
            raise BridgeCommandError('SCENE_OWNERSHIP_REQUIRED', 'inspection role layout differs')
        try:
            observed = _fx_rbd_velocity_host().inspect_controls(roles, pack)
        except ValueError as error:
            raise BridgeCommandError(getattr(error, 'code', 'NATIVE_READBACK_REQUIRED'), str(error)) from error
    return {'task_id': task_id, 'execution_root': requested_root, 'domain_pack': pack_id,
        'node_path': roles['rbd_velocity'], 'controls': observed['controls'],
        'readback_verified': True, 'native_readback': observed}


def _fx_collect_evidence(params: dict[str, Any], pack_id: str, pack: dict[str, Any]) -> dict[str, Any]:
    import hou

    task_id = str(params.get("task_id") or "")
    root, manifest = _fx_manifest(task_id)
    if manifest.get("domain_pack") != pack_id:
        raise BridgeCommandError("SCENE_CONFLICT", "effect scene manifest does not match requested domain pack")
    frames = _fx_frame_values(params)
    original_frame = hou.frame()
    frame_evidence: dict[str, dict[str, Any]] = {}
    geometry_readback: dict[str, dict[str, Any]] = {}
    geometry_outputs: dict[str, dict[str, Any]] = {}
    geometry_budget = {'remaining': 2 * 1024 * 1024 - 2}
    missing: list[str] = []
    lease_root = str(manifest.get("execution_root") or root.path())
    with _root_lease_fence(lease_root, task_id=task_id, scope="sop"):
        try:
            for frame in frames:
                hou.setFrame(frame)
                nodes_at_frame: dict[str, Any] = {}
                for role, path in (manifest.get("nodes") or {}).items():
                    node = hou.node(str(path))
                    if node is None:
                        if str(role) not in missing:
                            missing.append(str(role))
                    else:
                        item = _fx_node_evidence(node)
                        item["frame"] = frame
                        nodes_at_frame[str(role)] = item
                frame_evidence[str(frame)] = nodes_at_frame
                if pack_id == 'procedural_geometry_v1':
                    roles = manifest.get('nodes') or {}
                    carrier = hou.node(roles.get('geometry_deform', ''))
                    if carrier is not None and carrier.userData('bridge_geometry_deform_initialization_v1') is not None:
                        geometry_readback[str(frame)] = _fx_planned_geometry_readback(pack, roles, {'deformation': None})
                        geometry_outputs[str(frame)] = _fx_geometry_output_evidence(roles, pack, frame, geometry_budget)
                if pack_id == 'particles_v1':
                    roles = manifest.get('nodes') or {}
                    if (manifest.get('particle_emission_checkpoint') is not None
                            or 'emission_variance' in (manifest.get('candidate_patch') or {})
                            or _fx_particle_emission_host().registered(roles, pack)):
                        geometry_readback[str(frame)] = _fx_planned_geometry_readback(pack, roles, {'emission_variance': None})
                measured = {'wrinkle_scale':0.} if pack_id=='vellum_cloth_v1' else {'collision_radius':0.} if pack_id=='hair_fur_v1' else {'foam':False} if pack_id=='water_ocean_v1' else {'route_weight':0.,'animation_blend':0.} if pack_id=='crowd_agents_v1' else {}
                if pack_id=='rbd_destruction_v1':
                    configure=hou.node((manifest.get('nodes') or {}).get('configure',''))
                    if ('activation_frame' in (manifest.get('candidate_patch') or {})
                            or configure is not None and configure.userData('bridge_rbd_active_step_v1') is not None):
                        measured={'activation_frame':0}
                if measured and pack.get('shared_render_schema'):
                    roles=manifest.get('nodes') or {}
                    actual=_fx_planned_domain_readback(pack_id,measured,roles,pack,[])
                    geometry_readback[str(frame)]=_fx_planned_geometry_readback(pack,roles,actual)
                if pack_id == 'rbd_destruction_v1':
                    from houdini_bridge.native_rbd_controls_host import BASIS_KEY, PROGRAM_KEY
                    roles = manifest.get('nodes') or {}
                    carrier = hou.node(roles.get('rbd_velocity') or '')
                    if carrier is not None and any(carrier.userData(key) is not None for key in (BASIS_KEY, PROGRAM_KEY)):
                        velocity = _fx_planned_geometry_readback(pack, roles, {'velocity_variance': None})
                        if str(frame) in geometry_readback:
                            geometry_readback[str(frame)]['initial_velocity'] = velocity
                        else:
                            geometry_readback[str(frame)] = velocity
        finally:
            hou.setFrame(original_frame)
    node_evidence = frame_evidence.get(str(frames[0]), {}) if frames else {}
    evidence = {
        "schema": "houdini.fx.evidence_bundle/1.0",
        "domain_pack": pack_id,
        "frames": frames,
        "frame_stride": frames[1] - frames[0] if len(frames) > 1 else int(((params.get("render") or {}).get("frame_range") or {}).get("step", 1)),
        "requirements": _fx_evidence_requirements(pack),
        "nodes": node_evidence,
        "frame_nodes": frame_evidence,
        "native_geometry_readback": geometry_readback,
        "native_geometry_outputs": geometry_outputs,
        "missing_roles": missing,
        "houdini_version": hou.applicationVersionString(),
        "technical_only": True,
    }
    # Geometry/node evidence is intentionally not mislabeled as image or AOV
    # evidence.  The cross-DCC doctor must request the missing diagnostic pass
    # before claiming a visual cause.
    failed_cooks = [
        {"frame": int(frame), "role": role, "errors": item.get("errors") or [], "cook_exception": item.get("cook_exception")}
        for frame, nodes in frame_evidence.items()
        for role, item in nodes.items()
        if not item.get("cook_succeeded")
    ]
    evidence["failed_cooks"] = failed_cooks
    evidence["cook_verified"] = not missing and not failed_cooks
    evidence["source_sha256"] = _fx_sha256_file(_FX_ADDON_SOURCE)
    evidence["domain_contract_sha256"] = _fx_pack_contract_sha256(pack)
    identity_payload = {key: value for key, value in evidence.items() if key != "evidence_identity"}
    evidence["evidence_identity"] = hashlib.sha256(
        json.dumps(identity_payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8")
    ).hexdigest()
    manifest["last_evidence"] = evidence
    assessment = dict(manifest.get("execution_assessment") or {})
    assessment["last_evidence_cook"] = {
        "frames": frames,
        "passed": not missing and not failed_cooks,
        "missing_roles": missing,
        "failed_cooks": failed_cooks,
    }
    manifest["execution_assessment"] = assessment
    _fx_store_manifest(root, manifest)
    passed = not missing and not failed_cooks
    return {
        "gates": [
            {
                "name": "houdini_fx_technical_evidence",
                "passed": passed,
                "kind": "verification",
                "missing_roles": missing,
                "failed_cooks": failed_cooks,
                "verified_frames": frames,
            }
        ],
        "evidence": evidence,
        "diagnosis_state": "DIAGNOSIS_INCONCLUSIVE",
        "next_required_input": "Attach the requested field/AOV or visual preview before choosing a causal parameter patch.",
    }


def _fx_boundary_operation_path(task_id: str, operation_id: str) -> Path:
    directory = _state_dir().parent / "software-boundary-operations"
    directory.mkdir(parents=True, exist_ok=True)
    key = hashlib.sha256((str(task_id) + "\0" + str(operation_id)).encode("utf-8")).hexdigest()
    return directory / (key + ".json")


def _fx_boundary_fact_digest(fact: dict[str, Any]) -> str:
    # The receipt digest covers the final persisted fact, including ``result``.
    # Only the two self-referential digest slots are removed from the canonical
    # body.  This makes every other nested result field tamper-evident.
    body = json.loads(json.dumps(fact, ensure_ascii=False, sort_keys=True,
                                 separators=(",", ":"), allow_nan=False))
    body.pop("operation_receipt_sha256", None)
    result = body.get("result")
    if isinstance(result, dict):
        artifact = result.get("output_artifact")
        if isinstance(artifact, dict):
            artifact.pop("operation_receipt_sha256", None)
    return hashlib.sha256(json.dumps(body, ensure_ascii=False, sort_keys=True,
                                    separators=(",", ":"), allow_nan=False).encode("utf-8")).hexdigest()


_FX_LEGACY_SOFTWARE_CHECKPOINT_KEYS = frozenset({
    "schema", "task_id", "operation_id", "pack_id", "frame_set",
    "output_pattern", "output_path", "graph_fingerprint", "dependencies",
    "checkpoint", "state", "started_at_epoch",
})


def _fx_legacy_software_checkpoint_is_valid(
    fact: Any, *, operation_id: str, task_id: str,
) -> bool:
    """Recognize only the exact pre-digest checkpoint format from software boundary 1.0."""
    if not isinstance(fact, dict) or set(fact) != _FX_LEGACY_SOFTWARE_CHECKPOINT_KEYS:
        return False
    if (fact.get("schema") != "bridge.houdini.software-boundary-operation/1.0"
            or fact.get("state") != "CHECKPOINT_REACHED"
            or fact.get("operation_id") != operation_id
            or fact.get("task_id") != task_id
            or not isinstance(fact.get("pack_id"), str) or not fact["pack_id"]):
        return False
    frames = fact.get("frame_set")
    if (not isinstance(frames, list) or not frames or len(frames) > 12
            or any(type(frame) is not int or frame < 1 for frame in frames)
            or len(set(frames)) != len(frames)):
        return False
    output_pattern = fact.get("output_pattern")
    output_path = fact.get("output_path")
    if (not isinstance(output_pattern, str) or not isinstance(output_path, str)
            or bool(output_pattern) == bool(output_path)):
        return False
    graph_fingerprint = fact.get("graph_fingerprint")
    if not isinstance(graph_fingerprint, str) or not re.fullmatch(r"[0-9a-f]{64}", graph_fingerprint):
        return False
    dependencies = fact.get("dependencies")
    if not isinstance(dependencies, list) or any(not isinstance(item, dict) for item in dependencies):
        return False
    checkpoint = fact.get("checkpoint")
    if (not isinstance(checkpoint, dict) or set(checkpoint) != {"stage", "node_readback"}
            or checkpoint.get("stage") != "graph_readback_complete"):
        return False
    node_readback = checkpoint.get("node_readback")
    if (not isinstance(node_readback, dict) or not node_readback
            or any(not isinstance(role, str) or not role or not isinstance(item, dict)
                   for role, item in node_readback.items())):
        return False
    started_at = fact.get("started_at_epoch")
    if (isinstance(started_at, bool) or not isinstance(started_at, (int, float))
            or not math.isfinite(float(started_at)) or started_at <= 0):
        return False
    try:
        json.dumps(fact, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
    except (TypeError, ValueError, OverflowError):
        return False
    return True


def _fx_backfill_legacy_software_checkpoint(path: Path, fact: dict[str, Any]) -> dict[str, Any]:
    """Atomically upgrade an already-validated legacy checkpoint with its receipt digest."""
    if path.is_symlink() or not path.is_file():
        raise BridgeCommandError("SOFTWARE_OPERATION_FACT_INVALID",
                                 "legacy software checkpoint path is not a regular file")
    try:
        current = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise BridgeCommandError("SOFTWARE_OPERATION_FACT_INVALID",
                                 "legacy software checkpoint changed during migration") from exc
    if current != fact or "operation_receipt_sha256" in current:
        raise BridgeCommandError("SOFTWARE_OPERATION_FACT_INVALID",
                                 "legacy software checkpoint changed during migration")
    upgraded = dict(fact)
    upgraded["operation_receipt_sha256"] = _fx_boundary_fact_digest(upgraded)
    temporary = path.with_name("." + path.name + ".tmp-" + uuid4().hex)
    try:
        with temporary.open("x", encoding="utf-8") as stream:
            stream.write(json.dumps(upgraded, ensure_ascii=False, sort_keys=True, allow_nan=False))
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    except BaseException:
        temporary.unlink(missing_ok=True)
        raise
    return upgraded


def _fx_software_boundary_operation_fact(
    operation_id: str, task_id: str = "", *, allow_legacy_checkpoint: bool = False,
) -> dict[str, Any] | None:
    operation_id = str(operation_id or "")
    task_id = str(task_id or "")
    if not operation_id:
        return None
    directory = _state_dir().parent / "software-boundary-operations"
    if task_id:
        path = _fx_boundary_operation_path(task_id, operation_id)
        paths = (path,)
    else:
        paths = tuple(sorted(directory.glob("*.json"))) if directory.is_dir() else ()
    for path in paths:
        try:
            fact = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            if task_id and path.is_file():
                raise BridgeCommandError("SOFTWARE_OPERATION_FACT_INVALID",
                                         "software boundary operation fact is unreadable")
            continue
        if (isinstance(fact, dict) and fact.get("operation_id") == operation_id
                and (not task_id or fact.get("task_id") == task_id)):
            digest = str(fact.get("operation_receipt_sha256") or "")
            schema = fact.get("schema")
            result = fact.get("result")
            artifact = result.get("output_artifact") if isinstance(result, dict) else None
            nested_digest = artifact.get("operation_receipt_sha256") if isinstance(artifact, dict) else None
            if (schema == "bridge.houdini.software-boundary-operation/1.0"
                    and not digest and allow_legacy_checkpoint and task_id
                    and _fx_legacy_software_checkpoint_is_valid(
                        fact, operation_id=operation_id, task_id=task_id)):
                return fact
            if (schema not in {"bridge.houdini.software-boundary-operation/1.0",
                               "bridge.houdini.software-boundary-fact/1.0"}
                    or not re.fullmatch(r"[0-9a-f]{64}", digest)
                    or not hmac.compare_digest(digest, _fx_boundary_fact_digest(fact))
                    or (schema == "bridge.houdini.software-boundary-fact/1.0"
                        and nested_digest != digest)):
                raise BridgeCommandError("SOFTWARE_OPERATION_FACT_INVALID",
                                         "software boundary operation fact failed digest verification")
            return fact
    return None


def _fx_software_boundary_execute(params: dict[str, Any], pack_id: str, pack: dict[str, Any]) -> dict[str, Any]:
    """Execute the explicit strict-fake software boundary for a domain graph.

    This route is unavailable to a real Houdini module.  It still performs the
    shipped add-on's graph/parameter/connection readback, cooks every task
    node through the injected HOM seam, and persists an operation fact.  The
    result is software evidence only; it never advances native support.
    """
    import hou

    if getattr(hou, "_bridge_software_boundary", False) is not True:
        raise BridgeCommandError("SOFTWARE_BOUNDARY_NOT_AUTHORIZED", "the strict software boundary is not active")
    task_id = str(params.get("task_id") or "").strip()
    operation_id = str(params.get("operation_id") or "").strip()
    if not task_id or not operation_id:
        raise BridgeCommandError("INVALID_ARGUMENT", "task_id and operation_id are required")
    root, manifest = _fx_manifest(task_id)
    if manifest.get("domain_pack") != pack_id:
        raise BridgeCommandError("SCENE_CONFLICT", "software execution domain does not match the task manifest")
    nodes = manifest.get("nodes") or {}
    if not isinstance(nodes, dict) or not nodes:
        raise BridgeCommandError("DOMAIN_GRAPH_INCOMPLETE", "software execution requires a persisted task graph")
    raw_frames = params.get("frames") or _fx_frame_values(params)
    frames = [int(frame) for frame in raw_frames]
    if not frames or len(frames) > 12 or len(set(frames)) != len(frames) or any(frame < 1 for frame in frames):
        raise BridgeCommandError("INVALID_ARGUMENT", "software boundary frames are invalid")
    output_pattern = str(params.get("output_pattern") or "").strip()
    output_path = str(params.get("output_path") or "").strip()
    if bool(output_pattern) == bool(output_path):
        raise BridgeCommandError("OUTPUT_BINDING_REQUIRED", "exactly one output_pattern or output_path is required")
    dependencies = params.get("dependency_artifacts") or []
    if dependencies and (not isinstance(dependencies, list)
                         or any(not isinstance(item, dict) or not item.get("artifact_id")
                                or not item.get("operation_id") for item in dependencies)):
        raise BridgeCommandError("UPSTREAM_ARTIFACT_BINDING_INVALID", "dependency artifacts need id and producing operation")
    operation_path = _fx_boundary_operation_path(task_id, operation_id)
    prior = _fx_software_boundary_operation_fact(
        operation_id, task_id,
        allow_legacy_checkpoint=params.get("resume") is True)
    if prior is not None:
        if (prior.get("pack_id") != pack_id or prior.get("output_pattern") != output_pattern
                or prior.get("output_path") != output_path or prior.get("frame_set") != frames
                or prior.get("dependencies") != dependencies):
            raise BridgeCommandError("SOFTWARE_OPERATION_ID_REUSED", "operation identity differs from its persisted boundary fact")
        if prior.get("state") == "COMPLETED":
            return dict(prior.get("result") or {})
        if prior.get("state") != "CHECKPOINT_REACHED" or params.get("resume") is not True:
            raise BridgeCommandError("SOFTWARE_OPERATION_RECOVERY_REQUIRED", "checkpointed domain work requires an explicit resume")
    elif params.get("resume") is True:
        raise BridgeCommandError("SOFTWARE_OPERATION_CHECKPOINT_MISSING", "resume has no persisted domain checkpoint")

    # Read back every node and its native port topology before the first cook.
    node_readback = {}
    for role, raw_path in sorted(nodes.items()):
        node = hou.node(str(raw_path))
        if node is None:
            raise BridgeCommandError("DOMAIN_GRAPH_INCOMPLETE", "node disappeared before software execution: " + str(role))
        node_readback[str(role)] = _fx_node_evidence(node)

    graph_fingerprint = str(manifest.get("graph_hash") or hashlib.sha256(
        json.dumps({"task_id": task_id, "nodes": nodes,
                    "connections": manifest.get("connections")},
                   ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest())
    if prior is not None and prior.get("graph_fingerprint") != graph_fingerprint:
        raise BridgeCommandError("SOFTWARE_OPERATION_SCENE_DRIFT", "checkpoint graph differs from the resumed graph")
    if prior is not None and "operation_receipt_sha256" not in prior:
        prior_checkpoint = prior.get("checkpoint")
        if not isinstance(prior_checkpoint, dict) or prior_checkpoint.get("node_readback") != node_readback:
            raise BridgeCommandError("SOFTWARE_OPERATION_FACT_INVALID",
                                     "legacy checkpoint node readback differs from the current graph")
        prior = _fx_backfill_legacy_software_checkpoint(operation_path, prior)
    if prior is None:
        checkpoint = {
            "schema": "bridge.houdini.software-boundary-operation/1.0",
            "task_id": task_id, "operation_id": operation_id, "pack_id": pack_id,
            "frame_set": frames, "output_pattern": output_pattern, "output_path": output_path,
            "graph_fingerprint": graph_fingerprint,
            "dependencies": json.loads(json.dumps(dependencies, ensure_ascii=False, sort_keys=True)),
            "checkpoint": {"stage": "graph_readback_complete", "node_readback": node_readback},
            "state": "CHECKPOINT_REACHED" if params.get("checkpoint_after_build") is True else "RUNNING",
            "started_at_epoch": time.time(),
        }
        checkpoint["operation_receipt_sha256"] = _fx_boundary_fact_digest(checkpoint)
        operation_path.write_text(json.dumps(checkpoint, ensure_ascii=False, sort_keys=True), encoding="utf-8")
        if params.get("checkpoint_after_build") is True:
            return {"status": "CHECKPOINT_REACHED", "operation_id": operation_id,
                    "task_id": task_id, "pack_id": pack_id,
                    "software_boundary_only": True, "execution_started": True,
                    "checkpoint": checkpoint["checkpoint"]}

    frame_snapshots = {}
    frame_evidence = []
    original_frame = hou.frame()
    try:
        for frame in frames:
            hou.setFrame(frame)
            cooked = []
            for role, raw_path in sorted(nodes.items()):
                node = hou.node(str(raw_path))
                cook = getattr(node, "cook", None)
                if not callable(cook):
                    raise BridgeCommandError("SOFTWARE_BOUNDARY_COOK_UNAVAILABLE", "node has no cook entry: " + str(role))
                cook(force=True)
                errors = list(node.errors())
                if errors:
                    raise BridgeCommandError("SOFTWARE_BOUNDARY_COOK_FAILED", "{}: {}".format(role, errors[:1]))
                cooked.append(str(role))
            terminal_role = ("render" if pack_id == "lighting_camera_render_v1"
                             else "material" if pack_id == "material_lookdev_v1"
                             else "output")
            terminal = hou.node(str(nodes.get(terminal_role) or ""))
            if terminal is None:
                raise BridgeCommandError("DOMAIN_GRAPH_INCOMPLETE", "terminal role is missing: " + terminal_role)
            evidence = _fx_node_evidence(terminal)
            evidence.update({"frame": frame, "cooked_roles": cooked})
            frame_evidence.append(evidence)
            if output_pattern:
                from dcc_task_runtime.artifact_registry import frame_path
                target = frame_path(output_pattern, frame).expanduser().resolve()
                target.parent.mkdir(parents=True, exist_ok=True)
                from dcc_task_runtime.exr_codec import encode_tiny_exr
                sample = float(frame) + (int(hashlib.sha256(graph_fingerprint.encode()).hexdigest()[:6], 16) % 1000) / 1000.0
                temporary = target.with_name(target.name + ".tmp-{}".format(os.getpid()))
                temporary.write_bytes(encode_tiny_exr(sample))
                os.replace(temporary, target)
                frame_snapshots[str(frame)] = {"path": str(target), "sha256": _fx_sha256_file(target),
                                               "bytes": target.stat().st_size}
    finally:
        hou.setFrame(original_frame)
    if output_path:
        target = Path(output_path).expanduser().resolve()
        target.parent.mkdir(parents=True, exist_ok=True)
        report = {
            "schema": "bridge.houdini.software-boundary-output/1.0",
            "task_id": task_id, "operation_id": operation_id, "pack_id": pack_id,
            "software_boundary_only": True, "graph_fingerprint": graph_fingerprint,
            "frames": frame_evidence, "dependencies": dependencies,
        }
        temporary = target.with_name(target.name + ".tmp-{}".format(os.getpid()))
        temporary.write_text(json.dumps(report, ensure_ascii=False, sort_keys=True), encoding="utf-8")
        os.replace(temporary, target)
        frame_snapshots = {"report": {"path": str(target), "sha256": _fx_sha256_file(target),
                                      "bytes": target.stat().st_size}}
    fact = {
        "schema": "bridge.houdini.software-boundary-fact/1.0",
        "task_id": task_id, "operation_id": operation_id, "pack_id": pack_id,
        "frame_set": frames, "output_pattern": output_pattern, "output_path": output_path,
        "state": "COMPLETED", "started_at_epoch": float((prior or {}).get("started_at_epoch") or time.time()),
        "completed_at_epoch": time.time(), "scene_fingerprint": graph_fingerprint,
        "frame_snapshots": frame_snapshots,
        "dependencies": json.loads(json.dumps(dependencies, ensure_ascii=False, sort_keys=True)),
        "metadata": {"software_boundary_only": True, "node_readback": node_readback,
                     "frame_evidence": frame_evidence},
    }
    result = {
        "status": "COMPLETED", "operation_id": operation_id, "task_id": task_id,
        "pack_id": pack_id, "software_boundary_only": True,
        "software_boundary_execution": "diagnostic_only", "formal_operation": False, "execution_started": True,
        "real_native_execution_verified": False, "visual_verified": False,
        "graph_fingerprint": graph_fingerprint, "frame_set": frames,
        "node_readback": node_readback, "frame_evidence": frame_evidence,
        "output_artifact": {"pattern": output_pattern, "path": output_path,
                             "frames": frame_snapshots, "operation_id": operation_id},
    }
    fact["result"] = result
    fact["operation_receipt_sha256"] = _fx_boundary_fact_digest(fact)
    result["output_artifact"]["operation_receipt_sha256"] = fact["operation_receipt_sha256"]
    operation_path.write_text(json.dumps(fact, ensure_ascii=False, sort_keys=True), encoding="utf-8")
    root_manifest = dict(manifest)
    assessment = dict(root_manifest.get("execution_assessment") or {})
    assessment.update({"software_boundary_execution": "diagnostic_only", "formal_operation": False, "render_validated": False,
                       "render_boundary_fact": {"operation_id": operation_id,
                                                 "operation_receipt_sha256": fact["operation_receipt_sha256"],
                                                 "frames": frames, "output_pattern": output_pattern,
                                                 "output_path": output_path},
                       "state": "SOFTWARE_BOUNDARY_EXECUTED"})
    root_manifest["execution_assessment"] = assessment
    root_manifest["last_software_boundary_execution"] = result
    _fx_store_manifest(root, root_manifest)
    return result


def _fx_coerce_control(name: str, raw_value: Any, control: dict[str, Any]) -> Any:
    value_type = str(control.get("value_type") or "float")
    minimum = float(control["minimum"])
    maximum = float(control["maximum"])
    if value_type == "color3":
        if not isinstance(raw_value, (list, tuple)) or len(raw_value) != 3:
            raise BridgeCommandError("INVALID_ARGUMENT", "{} must be an RGB triple".format(name))
        value = tuple(float(item) for item in raw_value)
        if any(item < minimum or item > maximum for item in value):
            raise BridgeCommandError("INVALID_ARGUMENT", "{} is outside the supported range".format(name))
        return value
    if value_type == "bool":
        if not isinstance(raw_value, (bool, int)) or int(raw_value) not in (0, 1):
            raise BridgeCommandError("INVALID_ARGUMENT", "{} must be boolean".format(name))
        return bool(raw_value)
    if value_type == "int":
        value = int(raw_value)
    else:
        value = float(raw_value)
    if value < minimum or value > maximum:
        raise BridgeCommandError("INVALID_ARGUMENT", "{} is outside the supported range".format(name))
    return value


def _fx_default_cache_pattern(params: dict[str, Any], pack_id: str) -> str:
    import hou

    task_id = str(params.get("task_id") or "")
    fx = _fx_configuration(params)
    configured = str(fx.get("output") or fx.get("cache_output") or "").strip()
    if configured:
        # Expand $HIP/$JOB while preserving the frame placeholder for each
        # approved frame; expandString otherwise freezes $F4 to the UI frame.
        protected = configured.replace("$F4", "__BRIDGE_CACHE_FRAME4__")
        return str(Path(hou.expandString(protected).replace("__BRIDGE_CACHE_FRAME4__", "$F4")).expanduser())
    hip_path = Path(hou.hipFile.path())
    base = hip_path.parent if hip_path.suffix else Path(hou.expandString("$HIP"))
    return str(base / "cache" / _task_name(task_id, pack_id) / "sim.$F4.bgeo.sc")


def _fx_cache_frame_path(pattern: str, frame: int) -> Path:
    if "$F4" in pattern:
        return Path(pattern.replace("$F4", "{:04d}".format(frame)))
    if "%04d" in pattern:
        return Path(pattern.replace("%04d", "{:04d}".format(frame)))
    if "####" in pattern:
        return Path(pattern.replace("####", "{:04d}".format(frame)))
    return Path(pattern)


def _fx_related_node_fingerprint(manifest: dict[str, Any]) -> list[dict[str, Any]]:
    import hou

    result: list[dict[str, Any]] = []
    for role, path in sorted((manifest.get("nodes") or {}).items()):
        node = hou.node(str(path))
        if node is None:
            result.append({"role": role, "path": path, "missing": True})
            continue
        parms: dict[str, Any] = {}
        for parm in node.parms():
            try:
                if not parm.isAtDefault():
                    # cook-free read (see the fingerprint walk note on eval())
                    parms[parm.name()] = _json_safe(parm.rawValue())
            except Exception:
                continue
        result.append({"role": role, "path": node.path(), "type": node.type().nameWithCategory(), "parms": parms})
    return result


def _bridge_task_nodes(
    task_id: str, errors: Optional[list[str]] = None
) -> dict[str, Any]:
    """Return the exact node set owned by one structured Bridge task."""

    import hou

    failures = errors if errors is not None else []
    if not task_id:
        return {}
    try:
        model_path, model_stage_path = _task_paths(task_id)
        fx_path, fx_stage_path = _fx_task_paths(task_id)
    except Exception as exc:
        failures.append("task path resolution failed: {}".format(exc))
        return {}
    roots: list[Any] = []
    explicit_nodes: list[Any] = []
    model_root = hou.node(model_path)
    if model_root is not None and str(model_root.userData("agent_task_id") or "") == task_id:
        roots.append(model_root)
        model_stage = hou.node(model_stage_path)
        if model_stage is not None:
            roots.append(model_stage)
        material_path = str(model_root.userData("agent_material") or "")
        material = hou.node(material_path) if material_path else None
        if material is not None:
            explicit_nodes.append(material)
    fx_root = hou.node(fx_path)
    if fx_root is not None and str(fx_root.userData("bridge_fx_owned") or "") == "1":
        try:
            manifest = json.loads(fx_root.userData("bridge_fx_manifest_v1") or "{}")
        except (TypeError, ValueError):
            manifest = {}
        if not manifest or str(manifest.get("task_id") or "") == task_id:
            roots.append(fx_root)
            fx_stage = hou.node(fx_stage_path)
            if fx_stage is not None:
                roots.append(fx_stage)
            for path in (manifest.get("nodes") or {}).values():
                node = hou.node(str(path or ""))
                if node is not None:
                    explicit_nodes.append(node)
    nodes: dict[str, Any] = {}
    for root in roots:
        nodes[root.path()] = root
        try:
            for child in root.allSubChildren():
                nodes[child.path()] = child
        except Exception as exc:
            failures.append(
                "task subtree traversal failed for {}: {}".format(root.path(), exc)
            )
    for node in explicit_nodes:
        nodes[node.path()] = node
        try:
            for child in node.allSubChildren():
                nodes[child.path()] = child
        except Exception as exc:
            failures.append(
                "task node traversal failed for {}: {}".format(node.path(), exc)
            )
    return nodes


def _houdini_node_graph_fingerprint(
    nodes: dict[str, Any], *, scope: str, inherited_errors: tuple[str, ...] = (), strict_static: bool = False
) -> Optional[dict[str, Any]]:
    """Hash static node topology/channel state without time-varying evaluation."""

    if not nodes:
        return None
    records: list[dict[str, Any]] = []
    errors = list(inherited_errors)
    for path, node in sorted(nodes.items()):
        parms: list[dict[str, Any]] = []
        try:
            node_parms = node.parms()
        except Exception as exc:
            node_parms = []
            errors.append("{} parms unreadable: {}".format(path, exc))
        for parm in node_parms:
            try:
                keyframes = tuple(parm.keyframes())
                parm_state: dict[str, Any] = {"name": str(parm.name())}
                if keyframes:
                    parm_state["keyframes"] = [
                        _keyframe_identity(keyframe) for keyframe in keyframes
                    ]
                    if strict_static:
                        parm_state.update(pre_extrapolation=str(parm.keyframeExtrapolation(True)),
                                          post_extrapolation=str(parm.keyframeExtrapolation(False)))
                else:
                    try:
                        unexpanded = parm.unexpandedString()
                        if strict_static and not isinstance(unexpanded, str):
                            raise ValueError("static unexpanded parameter is not text")
                        parm_state["unexpanded"] = str(unexpanded)
                    except Exception:
                        # parm.eval() can cook upstream sim graphs: fingerprint
                        # walks have been observed grinding inside solver parm
                        # expression evaluation. rawValue() never cooks.
                        try:
                            raw_value = parm.rawValue()
                            if strict_static and type(raw_value) not in (str, int, float, bool, type(None)):
                                raise ValueError("static parameter value has an unsupported type")
                            if strict_static:
                                json.dumps(raw_value, allow_nan=False)
                            parm_state["value"] = _json_safe(raw_value)
                        except Exception as exc:
                            parm_state["value"] = None
                            if strict_static:
                                errors.append("{} static parm unreadable: {}".format(path, exc))
                parms.append(parm_state)
            except Exception as exc:
                try:
                    parm_name = str(parm.name())
                except Exception:
                    parm_name = ""
                parms.append({"name": parm_name, "unreadable": True})
                errors.append("{} parm {} unreadable: {}".format(path, parm_name, exc))
        try:
            inputs = [item.path() if item is not None else None for item in node.inputs()]
        except Exception as exc:
            inputs = []
            errors.append("{} inputs unreadable: {}".format(path, exc))
        try:
            raw_user_data = node.userDataDict()
            if strict_static and (not isinstance(raw_user_data, dict) or any(
                    not isinstance(key, str) or not isinstance(value, str) for key, value in raw_user_data.items())):
                raise ValueError("static user data is not a complete string mapping")
            user_data = _json_safe(raw_user_data)
        except Exception as exc:
            user_data = {}
            errors.append("{} user data unreadable: {}".format(path, exc))
        flags: dict[str, bool] = {}
        for flag_name, method_name in (
            ("bypass", "isBypassed"),
            ("display", "isDisplayFlagSet"),
            ("render", "isRenderFlagSet"),
            ("template", "isTemplateFlagSet"),
            ("selectable", "isSelectableInViewport"),
            ("locked_hda", "isLockedHDA"),
            ("hard_locked", "isHardLocked"),
            # ("time_dependent", "isTimeDependent") deliberately removed:
            # isTimeDependent() cooks the node chain and has been observed
            # grinding whole vellum solver graphs during fingerprint walks.
        ):
            method = getattr(node, method_name, None)
            if not callable(method):
                continue
            try:
                value = method()
                if strict_static and type(value) is not bool:
                    raise ValueError("static flag is not a boolean")
                flags[flag_name] = bool(value)
            except Exception as exc:
                errors.append("{} flag {} unreadable: {}".format(path, flag_name, exc))
        try:
            node_type = str(node.type().nameWithCategory())
        except Exception as exc:
            node_type = ""
            errors.append("{} type unreadable: {}".format(path, exc))
        geometry_identity: Optional[dict[str, Any]] = None
        if flags.get("hard_locked") is True or "stash" in node_type.lower():
            if strict_static:
                errors.append("{} stored geometry has no non-evaluating identity".format(path))
            else:
                try:
                    geometry = node.geometry()
                    geometry_bytes = bytes(geometry.data())
                    geometry_identity = {
                        "sha256": hashlib.sha256(geometry_bytes).hexdigest(),
                        "bytes": len(geometry_bytes),
                    }
                except Exception as exc:
                    errors.append("{} stored geometry unreadable: {}".format(path, exc))
        wire_identity = None
        if strict_static:
            try:
                import hou
                wire_identity = []
                for wire in node.inputConnections():
                    indirect = wire.subnetIndirectInput()
                    item = wire.inputItem()
                    upstream = wire.inputNode()
                    if indirect is None:
                        if upstream is None or item != upstream:
                            raise ValueError("direct wire endpoint is incomplete")
                        wire_identity.append({"input_index": wire.inputIndex(), "source": upstream.path(),
                                              "output_index": wire.outputIndex()})
                        continue
                    if not isinstance(indirect, hou.SubnetIndirectInput) or item != indirect:
                        raise ValueError("indirect wire endpoint type or identity mismatch")
                    parent = indirect.parent()
                    parent_path = parent.path()
                    if (not isinstance(parent, hou.Node) or parent != node.parent()
                            or not isinstance(parent_path, str) or not parent_path.startswith("/")
                            or any(part in ("", ".", "..") for part in parent_path.split("/")[1:])):
                        raise ValueError("indirect wire parent is invalid")
                    number = indirect.number()
                    item_output = wire.inputItemOutputIndex()
                    destination_input = wire.inputIndex()
                    resolved_output = wire.outputIndex()
                    if (any(type(value) is not int or value < 0 for value in
                            (number, item_output, destination_input, resolved_output)) or item_output != 0):
                        raise ValueError("indirect wire port identity is invalid")
                    upstream_path = None
                    if upstream is not None:
                        if not isinstance(upstream, hou.Node):
                            raise ValueError("indirect wire resolved upstream is not a node")
                        upstream_path = upstream.path()
                        if (not isinstance(upstream_path, str) or not upstream_path.startswith("/")
                                or any(part in ("", ".", "..") for part in upstream_path.split("/")[1:])):
                            raise ValueError("indirect wire resolved upstream path is invalid")
                    wire_identity.append({"kind": "subnet_indirect_input", "parent_path": parent_path,
                                          "number": number, "input_item_output_index": item_output,
                                          "input_index": destination_input, "resolved_upstream": upstream_path,
                                          "output_index": resolved_output})
                json.dumps(wire_identity, allow_nan=False)
            except Exception as exc:
                errors.append("{} static wires unreadable: {}".format(path, exc))
        records.append(
            {
                **({"input_connections": wire_identity} if strict_static else {}),
                "path": path,
                "type": node_type,
                "inputs": inputs,
                "parms": parms,
                "user_data": user_data,
                "flags": flags,
                "stored_geometry": geometry_identity,
            }
        )
    encoded = json.dumps(
        records, ensure_ascii=False, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")
    return {
        "sha256": hashlib.sha256(encoded).hexdigest(),
        "node_count": len(records),
        "scope": scope,
        "identity_complete": not errors,
        "errors": errors,
        "full_scene_identity_verified": False,
    }


def _fx_project_environment_destinations(nodes):
    """Classify only absent, gated generated resources from a verified manifest."""
    import hou
    result = {}
    for node in nodes.values():
        method = getattr(node, "userData", None)
        raw = method("bridge_fx_manifest_v1") if callable(method) else None
        if not raw:
            continue
        manifest = json.loads(raw)
        if not manifest.get("project_environment"):
            continue
        observed = _fx_project_environment_readback(manifest, str(manifest.get("task_id") or ""))
        primary = observed["primary_output"]
        owner = nodes.get(primary["path"])
        if owner is not None and owner.type().nameWithCategory() == "Lop/karmarendersettings":
            result[primary["path"] + "/" + primary["parameter"]] = {
                "role": primary["role"], "path": primary["path"], "type": owner.type().nameWithCategory(),
                "parameter": primary["parameter"], "resource_kind": "primary_render_output",
                "raw": primary["raw"], "expanded": primary["evaluated"],
                "project_environment_sha256": manifest["project_environment_sha256"]}
        for item in observed["resources"]:
            owner = nodes.get(item["path"])
            if owner is None or owner.type().nameWithCategory() != item["type"]:
                continue
            directory = Path(item["resource_directory"])
            if directory.exists() or directory.is_symlink():
                continue
            if item["gate"]:
                _parm, gate, channel = _fx_project_literal(owner, item["gate"], manifest["task_id"])
                if gate != 0:
                    continue
            result[item["path"] + "/" + item["parameter"]] = {
                "role": item["role"], "path": item["path"], "type": item["type"],
                "parameter": item["parameter"], "resource_kind": item["resource_kind"],
                "raw": item["raw"], "expanded": item["evaluated"],
                "project_environment_sha256": manifest["project_environment_sha256"]}
    return result


def _fx_global_gallery_destination(parm):
    """Identify the untouched global LOP manager's absent gallery locator."""
    import hou
    default = "$HIP/galleries/$HIPNAME.$OS/rendergallery.db"
    version = hou.applicationVersionString()
    if version not in {"21.0.631", "22.0.459"}:
        return None
    node = parm.node()
    lop_network = getattr(hou, "LopNetwork", None)
    if (node != hou.node("/stage") or node.path() != "/stage"
            or lop_network is None or not isinstance(node, lop_network)
            or node.childTypeCategory().name() != "Lop"
            or parm.name() != "rendergallerysource"):
        return None
    template = parm.parmTemplate()
    if (str(template.type()).rsplit(".", 1)[-1].lower() != "string"
            or tuple(template.defaultValue()) != (default,)
            or parm.unexpandedString() != default):
        return None
    value, channel = _fx_scene_parameter_readback(parm)
    if (channel.get("expression") is not None or channel.get("reference_path") is not None
            or channel.get("keyframes") or channel.get("evaluated_available") is not True
            or value != hou.expandString(default)):
        return None
    database = Path(str(value)).expanduser()
    if not database.is_absolute():
        return None
    candidates = [database, database.parent,
                  *(Path(str(database) + suffix) for suffix in ("-wal", "-shm", "-journal"))]
    if (any(path.exists() or path.is_symlink() for path in candidates)
            or any(path.is_symlink() for path in database.parents)):
        return None
    return {"role": "global_lop_manager", "path": node.path(), "type": node.type().nameWithCategory(),
            "parameter": parm.name(), "resource_kind": "global_gallery_locator",
            "raw": default, "expanded": value, "parameter_channel": channel,
            "houdini_version": version, "classification_schema": "houdini.global-gallery-locator/1"}


def _scene_external_reference_fingerprint(
    nodes: dict[str, Any], declared_inputs: Any
) -> dict[str, Any]:
    """Bind HOM file references to an explicit, host-rehashed input manifest."""

    import hou

    allowed_raw: dict[str, set[int]] = {}
    allowed_resolved: dict[str, set[int]] = {}
    inputs = declared_inputs if isinstance(declared_inputs, (list, tuple)) else []

    def add_allowed(value: Any, index: int) -> None:
        raw = str(value or "").strip()
        if not raw:
            return
        allowed_raw.setdefault(raw, set()).add(index)
        try:
            expanded = os.path.expandvars(str(hou.expandString(raw)))
            parsed = urlparse(expanded)
            if parsed.scheme == "file":
                expanded = unquote(parsed.path)
            if parsed.scheme not in {"http", "https", "data"}:
                resolved = str(Path(expanded).expanduser().resolve(strict=False))
                allowed_resolved.setdefault(resolved, set()).add(index)
        except Exception:
            return

    for index, item in enumerate(inputs):
        if not isinstance(item, dict):
            continue
        add_allowed(item.get("path") or item.get("uri"), index)
        frames = item.get("frames")
        if isinstance(frames, (list, tuple)):
            for frame in frames:
                if isinstance(frame, dict):
                    add_allowed(frame.get("path") or frame.get("uri"), index)

    records: list[dict[str, Any]] = []
    errors: list[str] = []
    generated_destinations = []
    try:
        project_destinations = _fx_project_environment_destinations(nodes)
    except Exception as exc:
        project_destinations = {}
        errors.append("project destination identity incomplete: " + str(exc))
    node_paths = set(nodes)
    try:
        references = list(hou.fileReferences())
    except Exception as exc:
        references = []
        errors.append("HOM file reference enumeration failed: {}".format(exc))
    for reference_index, pair in enumerate(references):
        if not isinstance(pair, (list, tuple)) or len(pair) != 2:
            errors.append("file reference {} has an invalid HOM record".format(reference_index))
            continue
        parm, hom_path = pair
        try:
            parm_node_path = str(parm.node().path())
            parm_path = str(parm.path())
        except Exception as exc:
            errors.append("file reference {} has no readable owner: {}".format(reference_index, exc))
            continue
        if parm_node_path not in node_paths:
            continue
        try:
            raw = str(parm.unexpandedString() or "").strip()
        except Exception as exc:
            raw = ""
            errors.append("{} raw file reference unreadable: {}".format(parm_path, exc))
        supplied = str(hom_path or "").strip()
        destination = project_destinations.get(parm_path)
        if destination is None and parm_node_path == "/stage" and parm_path == "/stage/rendergallerysource":
            try:
                destination = _fx_global_gallery_destination(parm)
            except Exception:
                destination = None
        if destination is not None and raw == destination["raw"] and supplied in {raw, destination["expanded"]}:
            generated_destinations.append({"parm_path": parm_path, **destination})
            continue
        matched_indexes: set[int] = set(allowed_raw.get(raw, set()))
        matched_indexes.update(allowed_raw.get(supplied, set()))
        expanded = ""
        try:
            expanded_text = os.path.expandvars(str(hou.expandString(raw or supplied)))
            parsed = urlparse(expanded_text)
            if parsed.scheme == "file":
                expanded_text = unquote(parsed.path)
            if parsed.scheme not in {"http", "https", "data"}:
                expanded = str(Path(expanded_text).expanduser().resolve(strict=False))
                matched_indexes.update(allowed_resolved.get(expanded, set()))
        except Exception as exc:
            errors.append("{} file reference expansion failed: {}".format(parm_path, exc))
        if not matched_indexes:
            errors.append("{} is not covered by an explicit frozen input".format(parm_path))
        records.append(
            {
                "parm_path": parm_path,
                "raw": raw,
                "expanded": expanded,
                "input_indexes": sorted(matched_indexes),
            }
        )
    encoded = json.dumps(
        {"references": records, "generated_destinations": generated_destinations} if generated_destinations else records,
        ensure_ascii=False, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")
    return {
        **({"generated_destinations": generated_destinations} if generated_destinations else {}),
        "sha256": hashlib.sha256(encoded).hexdigest(),
        "reference_count": len(records),
        "scope": "houdini_file_references_bound_to_explicit_inputs",
        "identity_complete": not errors,
        "errors": errors,
        "references": records,
    }


def _bridge_scene_fingerprints(
    task_id: str, declared_inputs: Any = None
) -> dict[str, Any]:
    """Separate task-owned changes from all other node-graph changes."""

    import hou

    traversal_errors: list[str] = []
    task_nodes = _bridge_task_nodes(task_id, traversal_errors)
    root = hou.node("/")
    all_nodes: dict[str, Any] = {}
    if root is not None:
        try:
            for node in root.allSubChildren():
                all_nodes[node.path()] = node
        except Exception as exc:
            traversal_errors.append("scene traversal failed: {}".format(exc))
    else:
        traversal_errors.append("Houdini root node is unavailable")
    non_task_nodes = {
        path: node for path, node in all_nodes.items() if path not in task_nodes
    }
    global_record: Optional[dict[str, Any]] = None
    try:
        frame_range = [float(item) for item in hou.playbar.frameRange()]
        playback_range = [float(item) for item in hou.playbar.playbackRange()]
        current_take = hou.takes.currentTake()
        ocio_environment = {
            name: str(hou.getenv(name) or "")
            for name in (
                "OCIO",
                "HOUDINI_OCIO_FILENAME",
                "HOUDINI_COLOR_PICKER_GAMMA",
            )
        }
        ocio_path_text = ocio_environment.get("OCIO") or ocio_environment.get(
            "HOUDINI_OCIO_FILENAME"
        )
        ocio_identity: dict[str, Any] = {
            "configured": ocio_path_text or "houdini_builtin",
            "sha256": None,
            "available": True,
        }
        if ocio_path_text:
            expanded = Path(hou.expandString(ocio_path_text)).expanduser()
            ocio_identity["resolved"] = str(expanded)
            if expanded.is_file():
                ocio_identity["sha256"] = _fx_sha256_file(expanded)
            else:
                ocio_identity["available"] = False
        global_payload = {
            "houdini_build": str(hou.applicationVersionString()),
            "hip_path": str(hou.hipFile.path() or ""),
            "fps": float(hou.fps()),
            "frame_range": frame_range,
            "playback_range": playback_range,
            "current_take": str(current_take.name()),
            "ocio_environment": ocio_environment,
            "ocio_identity": ocio_identity,
        }
        encoded_global = json.dumps(
            global_payload,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        ).encode("utf-8")
        global_record = {
            "sha256": hashlib.sha256(encoded_global).hexdigest(),
            "scope": "fps_ranges_take_color_config",
            "identity_complete": bool(ocio_identity["available"]),
            "details": global_payload,
        }
    except Exception as exc:
        global_record = {
            "sha256": None,
            "scope": "fps_ranges_take_color_config",
            "identity_complete": False,
            "error": str(exc),
        }
    task_record = _houdini_node_graph_fingerprint(
        task_nodes,
        scope="bridge_task_nodes_only",
        inherited_errors=tuple(traversal_errors),
    )
    non_task_record = _houdini_node_graph_fingerprint(
        non_task_nodes,
        scope="all_scene_nodes_except_bridge_task",
        inherited_errors=tuple(traversal_errors),
    )
    external_reference_record = _scene_external_reference_fingerprint(
        all_nodes, declared_inputs
    )
    return {
        "bridge_task_fingerprint": task_record,
        "non_task_scene_fingerprint": non_task_record,
        "global_scene_fingerprint": global_record,
        "external_reference_fingerprint": external_reference_record,
        "scene_graph_identity_complete": bool(
            non_task_record
            and non_task_record.get("identity_complete") is True
            and (task_record is None or task_record.get("identity_complete") is True)
            and global_record
            and global_record.get("identity_complete") is True
            and external_reference_record.get("identity_complete") is True
        ),
        # Node graph/channel coverage is strong enough to detect normal user
        # edits, but it is not byte-level proof for external assets or opaque
        # DCC state.  Callers must not relabel it as a complete scene freeze.
        "full_scene_identity_verified": False,
    }


_SCENE_READ_ONLY_ACTIONS = frozenset(
    {
        "agent.model.probe",
        "agent.model.validate_geometry",
        "agent.model.verify_preview",
        "agent.model.verify_final",
        "agent.fx.probe",
        "agent.fx.collect_evidence",
        "agent.fx.inspect_controls",
        "agent.fx.operation_receipt",
        "agent.fx.verify",
    }
)


def _scene_fingerprint_digest(payload: dict[str, Any], name: str) -> str:
    record = payload.get(name)
    if not isinstance(record, dict) or record.get("identity_complete") is not True:
        return ""
    digest = str(record.get("sha256") or "")
    return digest if len(digest) == 64 else ""


def _canonical_payload_sha256(value: Any) -> str:
    encoded = json.dumps(
        value,
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
        allow_nan=False,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _rehash_frozen_input_manifest(manifest: Any) -> str:
    """Re-read frozen input bytes at the DCC action boundary."""

    if not isinstance(manifest, list):
        raise BridgeCommandError(
            "SCENE_STATE_DRIFT", "frozen input manifest is missing or invalid"
        )

    def verify_bytes(identity: str, expected_sha256: Any, expected_bytes: Any) -> None:
        supplied = str(expected_sha256 or "").strip().lower()
        if len(supplied) != 64:
            raise BridgeCommandError(
                "SCENE_STATE_DRIFT", "frozen input has no valid SHA-256"
            )
        if identity.startswith("data:"):
            try:
                header, encoded = identity.split(",", 1)
                content = (
                    base64.b64decode(encoded, validate=True)
                    if ";base64" in header
                    else unquote_to_bytes(encoded)
                )
            except (ValueError, binascii.Error) as exc:
                raise BridgeCommandError(
                    "SCENE_STATE_DRIFT", "frozen data URI is invalid"
                ) from exc
            actual = hashlib.sha256(content).hexdigest()
            byte_count = len(content)
        else:
            path = Path(identity).expanduser()
            if path.is_symlink():
                raise BridgeCommandError(
                    "SCENE_STATE_DRIFT", "frozen input traverses a symlink"
                )
            resolved = path.resolve()
            if not resolved.is_file():
                raise BridgeCommandError(
                    "SCENE_STATE_DRIFT", "frozen input is missing: {}".format(resolved)
                )
            digest = hashlib.sha256()
            with resolved.open("rb") as handle:
                for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                    digest.update(chunk)
            actual = digest.hexdigest()
            byte_count = int(resolved.stat().st_size)
        if not hmac.compare_digest(actual, supplied) or int(expected_bytes) != byte_count:
            raise BridgeCommandError(
                "SCENE_STATE_DRIFT",
                "frozen external input bytes changed before DCC execution",
                "AWAITING_INPUT: restore or re-freeze the exact input bytes.",
            )

    for index, record in enumerate(manifest):
        if not isinstance(record, dict) or int(record.get("index", -1)) != index:
            raise BridgeCommandError(
                "SCENE_STATE_DRIFT", "frozen input manifest ordering is invalid"
            )
        frames = record.get("frames")
        if frames is not None:
            if not isinstance(frames, list) or not frames:
                raise BridgeCommandError(
                    "SCENE_STATE_DRIFT", "frozen sequence manifest is incomplete"
                )
            seen: set[int] = set()
            for frame_index, frame in enumerate(frames):
                if not isinstance(frame, dict) or int(frame.get("index", -1)) != frame_index:
                    raise BridgeCommandError(
                        "SCENE_STATE_DRIFT", "frozen sequence frame ordering is invalid"
                    )
                frame_number = int(frame.get("frame"))
                if frame_number in seen:
                    raise BridgeCommandError(
                        "SCENE_STATE_DRIFT", "frozen sequence contains duplicate frames"
                    )
                seen.add(frame_number)
                verify_bytes(
                    str(frame.get("uri") or ""),
                    frame.get("sha256"),
                    frame.get("bytes"),
                )
            computed_frames = _canonical_payload_sha256(frames)
            if computed_frames != str(record.get("manifest_sha256") or ""):
                raise BridgeCommandError(
                    "SCENE_STATE_DRIFT", "frozen sequence manifest identity changed"
                )
            declared = str(record.get("declared_sha256") or "")
            if declared and not hmac.compare_digest(declared, computed_frames):
                raise BridgeCommandError(
                    "SCENE_STATE_DRIFT", "declared sequence identity no longer matches"
                )
            continue
        identity = str(record.get("source_uri") or record.get("identity") or "")
        verify_bytes(identity, record.get("sha256"), record.get("bytes"))
    return _canonical_payload_sha256(manifest)


def _assert_scene_action_precondition(
    params: dict[str, Any], task_id: str
) -> Optional[dict[str, Any]]:
    expected = params.get("expected_scene_fingerprints")
    if not isinstance(expected, dict):
        return None
    observed = _bridge_scene_fingerprints(task_id, params.get("inputs"))
    observed_task = ""
    if observed.get("bridge_task_fingerprint") is not None:
        observed_task = _scene_fingerprint_digest(
            observed, "bridge_task_fingerprint"
        )
    observed_inputs = _rehash_frozen_input_manifest(
        expected.get("frozen_input_manifest")
    )
    comparisons = {
        "bridge_task_sha256": observed_task,
        "non_task_scene_sha256": _scene_fingerprint_digest(
            observed, "non_task_scene_fingerprint"
        ),
        "global_scene_sha256": _scene_fingerprint_digest(
            observed, "global_scene_fingerprint"
        ),
        "external_reference_sha256": _scene_fingerprint_digest(
            observed, "external_reference_fingerprint"
        ),
        "frozen_inputs_sha256": observed_inputs,
    }
    if observed.get("scene_graph_identity_complete") is not True or any(
        str(expected.get(name) or "") != actual
        for name, actual in comparisons.items()
    ):
        raise BridgeCommandError(
            "SCENE_STATE_DRIFT",
            "the frozen Houdini scene changed between host verification and DCC execution",
            "AWAITING_INPUT: inspect and re-freeze the scene before retrying.",
        )
    return observed


def _assert_scene_action_postcondition(
    command: str,
    before: Optional[dict[str, Any]],
    after: dict[str, Any],
) -> None:
    if before is None:
        return
    required = (
        "non_task_scene_fingerprint",
        "global_scene_fingerprint",
        "external_reference_fingerprint",
    )
    changed = [
        name
        for name in required
        if _scene_fingerprint_digest(before, name)
        != _scene_fingerprint_digest(after, name)
    ]
    if command in _SCENE_READ_ONLY_ACTIONS:
        before_task = (
            _scene_fingerprint_digest(before, "bridge_task_fingerprint")
            if before.get("bridge_task_fingerprint") is not None
            else ""
        )
        after_task = (
            _scene_fingerprint_digest(after, "bridge_task_fingerprint")
            if after.get("bridge_task_fingerprint") is not None
            else ""
        )
        if before_task != after_task:
            changed.append("bridge_task_fingerprint")
    if after.get("scene_graph_identity_complete") is not True or changed:
        raise BridgeCommandError(
            "SCENE_STATE_DRIFT",
            "structured action changed scene state outside its authorized task scope: {}".format(
                ", ".join(changed) or "identity_incomplete"
            ),
            "AWAITING_INPUT: inspect the scene before resuming.",
        )


def _fx_cache_subject(params: dict[str, Any], pack_id: str, manifest: dict[str, Any]) -> tuple[dict[str, Any], str]:
    import hou

    hip_path = Path(hou.hipFile.path())
    hip_stat: dict[str, Any] = {"path": str(hip_path)}
    if hip_path.is_file():
        stat = hip_path.stat()
        digest = hashlib.sha256()
        with hip_path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        hip_stat.update({"bytes": stat.st_size, "modified_ns": stat.st_mtime_ns, "sha256": digest.hexdigest()})
    frame_range = (params.get("render") or {}).get("frame_range") or {}
    frames = _fx_frame_values(params)
    stride = frames[1] - frames[0] if len(frames) > 1 else max(1, int(frame_range.get("step", 1)))
    fx = _fx_configuration(params)
    subject = {
        "purpose": "houdini_simulation_cache",
        "task_id": str(params.get("task_id") or ""),
        "scene": hip_stat,
        "scene_fingerprint": str(fx.get("scene_fingerprint") or ""),
        "input_digest": manifest.get("input_digest"),
        "domain_pack": pack_id,
        "pack_version": manifest.get("pack_version"),
        "candidate_patch": manifest.get("candidate_patch") or {},
        "revision": int(manifest.get("revision") or 0),
        "seed": int(manifest.get("seed") or 0),
        "frame_range": {
            "start": frames[0],
            "end": frames[-1],
            "step": stride,
        },
        "frames": frames,
        "houdini_version": hou.applicationVersionString(),
        "cache_output": _fx_default_cache_pattern(params, pack_id),
        "related_nodes": _fx_related_node_fingerprint(manifest),
    }
    encoded = json.dumps(subject, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return subject, hashlib.sha256(encoded).hexdigest()


def _fx_apply_candidate(params: dict[str, Any], pack_id: str, pack: dict[str, Any]) -> dict[str, Any]:
    """Serialize native validation, writes and persistence against takeover."""
    fx = _fx_configuration(params)
    changes = fx.get("changes")
    if not isinstance(changes, dict):
        candidate = fx.get("candidate_patch")
        changes = candidate.get("changes") if isinstance(candidate, dict) and isinstance(candidate.get("changes"), dict) else candidate
    if not isinstance(changes, dict) or not changes:
        raise BridgeCommandError("INVALID_ARGUMENT", "a non-empty semantic candidate patch is required")
    if len(changes) > 5:
        raise BridgeCommandError("INVALID_ARGUMENT", "a candidate may change at most five semantic controls")
    controls = pack.get("controls") or {}
    for name in changes:
        control = controls.get(str(name))
        if control is None:
            raise BridgeCommandError("UNSUPPORTED_PARAMETER", "unsupported semantic control for {}: {}".format(pack_id, name))
        if control.get("application", "houdini") != "houdini":
            raise BridgeCommandError(
                "DCC_OWNERSHIP_MISMATCH",
                "semantic control {} belongs to {} and cannot be applied in Houdini".format(name, control.get("application")),
            )

    task_id = str(params.get("task_id") or "")
    root, _manifest = _fx_manifest(task_id)
    root_path = root.path()
    with _root_lease_fence(root_path, task_id=task_id, scope="sop"):
        current_root, _manifest = _fx_manifest(task_id)
        if current_root.path() != root_path or current_root != root:
            raise BridgeCommandError("SCENE_STATE_DRIFT", "candidate task root changed while acquiring its lease")
        return _fx_apply_candidate_unfenced(params, pack_id, pack, changes)


def _fx_apply_candidate_unfenced(params: dict[str, Any], pack_id: str, pack: dict[str, Any], changes: dict[str, Any]) -> dict[str, Any]:
    controls = pack.get("controls") or {}
    import hou

    task_id = str(params.get("task_id") or "")
    root, manifest = _fx_manifest(task_id)
    persistence_snapshot = _fx_snapshot_manifest_persistence(root, task_id)
    exact_changes: list[dict[str, Any]] = []
    invalidates: list[str] = []
    normalized: dict[str, Any] = {}
    prepared: list[dict[str, Any]] = []
    target_paths: dict[str, str] = {}
    # Resolve and snapshot every target before mutating the first one.  HOM's
    # undo group is only a UI grouping primitive; it is not a transaction.
    render_domain = pack.get("native_plan_schema") == "bridge.native-render-domains/1"
    planned_domain = bool(pack.get('shared_render_schema'))
    planned_changes = changes
    cloth_regeneration = None
    ocean_regeneration = None
    if pack.get("scene_profile") == "official_karma_disklight_v1":
        from houdini_bridge.official_karma_feedback import validate_native_feedback
        manifest = validate_native_feedback(hou, manifest, changes, configuration=params.get("frozen_render_scene"))
    if render_domain:
        prepared = _fx_render_domain_prepared(pack_id, changes, manifest.get("nodes") or {}, pack)
    elif planned_domain:
        if pack_id=='water_ocean_v1':
            roles=manifest.get('nodes') or {}
            current=_fx_planned_domain_readback(pack_id,{'foam':False},roles,pack,[])
            foam=_fx_coerce_control('foam',changes['foam'],controls['foam']) if 'foam' in changes else current['foam']
            ocean_regeneration={'foam':foam}
            planned_changes={name:value for name,value in changes.items() if name!='foam'}
        if pack_id=='vellum_cloth_v1' and any(name in changes for name in ('thickness','collision_thickness')):
            roles=manifest.get('nodes') or {}
            current=_fx_planned_domain_readback(pack_id,{'wrinkle_scale':0.},roles,pack,[])
            wavelength=_fx_coerce_control('wrinkle_scale',changes['wrinkle_scale'],controls['wrinkle_scale']) if 'wrinkle_scale' in changes else current['wrinkle_scale']
            cloth_regeneration={'wrinkle_scale':wavelength}
            planned_changes={name:value for name,value in changes.items() if name!='wrinkle_scale'}
        prepared = _fx_planned_domain_prepared(pack_id, planned_changes, manifest.get("nodes") or {}, pack)
    else:
        for name, raw_value in changes.items():
            control = controls[str(name)]
            for target in _fx_control_target_specs(control):
                node = hou.node(str((manifest.get("nodes") or {}).get(str(target["role"])) or ""))
                if node is None:
                    raise BridgeCommandError("SCENE_STATE_MISSING", "node role is missing: {}".format(target["role"]))
                parm = _resolve_parm_target(node, list(target["aliases"]))
                if parm is None:
                    raise BridgeCommandError(
                        "UNSUPPORTED_PARAMETER",
                        "{} has no compatible native parameter for {}".format(node.path(), name),
                        "The current domain pack remains experimental for this Houdini build.",
                    )
                path = parm.path()
                if path in target_paths:
                    raise BridgeCommandError(
                        "CANDIDATE_TARGET_CONFLICT",
                        "semantic controls {} and {} resolve to the same parameter {}".format(target_paths[path], name, path),
                    )
                try:
                    if parm.isDisabled() or parm.isLocked():
                        raise BridgeCommandError("PARAMETER_LOCKED", "parameter is not editable: {}".format(path))
                except BridgeCommandError:
                    raise
                except Exception as exc:
                    raise BridgeCommandError("PARAMETER_STATE_UNAVAILABLE", "could not inspect {}: {}".format(path, exc)) from exc
                snapshot = _snapshot_parm_state(parm)
                if _parm_snapshot_is_driven(snapshot):
                    raise BridgeCommandError(
                        "PARAMETER_STATE_UNSUPPORTED",
                        "candidate control {} is animated, expression-driven, or channel-referenced".format(path),
                        "Bake or explicitly remove the channel driver before applying a constant semantic candidate.",
                    )
                target_paths[path] = str(name)
                prepared.append(
                    {
                        "name": str(name),
                        "node": node,
                        "parm": parm,
                        "snapshot": snapshot,
                        "value": _fx_linked_control_value(target,_fx_coerce_control(str(name),raw_value,control),parm),
                        "primary":target["primary"],
                        "native_target":target,
                        "invalidates_from": str(control.get("invalidates_from") or "generation_simulation"),
                    }
                )
    domain_geometry_readback = {}
    applied: list[dict[str, Any]] = []

    def rollback_parameters() -> list[str]:
        return _fx_rollback_planned_items(applied, prepared, manifest.get('nodes') or {}, pack)

    with _fx_candidate_undo(prepared, applied, manifest.get('nodes') or {}, pack):
        try:
            phase_prepared=prepared
            regeneration=cloth_regeneration if cloth_regeneration is not None else ocean_regeneration
            for phase in range(2 if regeneration is not None else 1):
                if phase:
                    # Derived programs depend on the actual native controls.
                    # Collect the first phase before regenerating the program.
                    _fx_planned_domain_readback(pack_id,planned_changes,manifest.get('nodes') or {},pack,
                        [item['native_write'] for item in prepared])
                    phase_prepared=_fx_planned_domain_prepared(pack_id,regeneration,manifest.get('nodes') or {},pack)
                    dependent='wrinkle_scale' if cloth_regeneration is not None else 'foam'
                    if dependent not in changes:
                        for item in phase_prepared:
                            item['semantic_names']=[name for name in changes if name in ('thickness','collision_thickness')] if dependent=='wrinkle_scale' else list(changes)
                            item['dependent_semantic_control']=dependent
                    prepared.extend(phase_prepared)
                for item in phase_prepared:
                    applied.append(item)
                    verification = _fx_write_planned_item(item, manifest.get('nodes') or {}, pack)
                    # Persist only the confirmed HOM readback. The approval
                    # subject must bind reality, not merely the requested value.
                    if item["primary"]:
                        normalized[item["name"]] = verification["after"] * item["native_target"]["multiplier"] if item["native_target"].get("native_multiplier_parm") else verification["after"]
                    invalidates.append(item["invalidates_from"])
                    for semantic_name in item.get('semantic_names',[item['name']]):
                        exact_changes.append(
                            {
                                "semantic_control": semantic_name,
                                "node": item["node"].path(),
                                "invalidates_from": (controls[semantic_name]['invalidates_from'] if item.get('dependent_semantic_control')=='foam' else item["invalidates_from"]),
                                **({'dependent_semantic_control':item['dependent_semantic_control']} if 'dependent_semantic_control' in item else {}),
                                **verification,
                            }
                        )
            for item in prepared:
                if 'particle_size_snapshot' in item or 'rbd_velocity_snapshot' in item or 'particle_emission_snapshot' in item:
                    continue
                if 'swarm_snapshot' in item:
                    observations=_fx_planned_observations({'target_noise':item['native_write']['public_value']},manifest.get('nodes') or {},pack,[item['native_write']])
                    _fx_planned_module(pack)[0].validate_applied_readback([item['native_write']],observations)
                    continue
                if 'activation_snapshot' in item:
                    observations=_fx_planned_observations({'activation_frame':item['value']},manifest.get('nodes') or {},pack,[item['native_write']])
                    _fx_planned_module(pack)[0].validate_applied_readback([item['native_write']],observations)
                    continue
                actual = _read_parm_for_request(item["parm"],item["value"])
                if (_fx_control_multiplier(item["native_target"],item["parm"]) != item["native_target"]["multiplier"] or
                        _parm_snapshot_is_driven(_snapshot_parm_state(item["parm"])) or not _values_match(item["value"],actual)):
                    raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "candidate write set drifted: " + item["parm"].path())
            if planned_domain:
                readback_changes={**changes,**(regeneration or {})}
                normalized = _fx_planned_domain_readback(pack_id, readback_changes, manifest.get('nodes') or {}, pack, [item['native_write'] for item in prepared])
                if any(not _values_match(_fx_coerce_control(name, value, controls[name]), normalized[name]) for name,value in changes.items()):
                    raise BridgeCommandError('PARAMETER_READBACK_MISMATCH', 'native domain semantic controls did not read back')
                domain_geometry_readback=_fx_planned_geometry_readback(pack,manifest.get('nodes') or {},normalized)
            if render_domain:
                normalized = _fx_render_domain_readback(pack_id, changes, manifest.get("nodes") or {}, pack)
                if any(not _values_match(_fx_coerce_control(name, value, controls[name]), normalized[name]) for name,value in changes.items()):
                    raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "semantic render controls did not read back")
                if "filter_width" in changes and hou.applicationVersionString() in ("22.0.429", "22.0.459"):
                    _fx_static_domain_readback(pack_id, manifest.get("nodes") or {}, pack)
        except Exception as exc:
            rollback_errors = rollback_parameters()
            if rollback_errors:
                raise BridgeCommandError(
                    "CANDIDATE_ROLLBACK_FAILED",
                    "candidate failed with {} and rollback failed for {}".format(
                        getattr(exc, "code", type(exc).__name__), ", ".join(rollback_errors)
                    ),
                ) from exc
            if isinstance(exc, BridgeCommandError):
                raise
            raise BridgeCommandError(
                "CANDIDATE_APPLY_FAILED",
                "candidate parameter application failed: {}".format(exc),
            ) from exc

    updated_manifest = dict(manifest)
    updated_manifest["candidate_patch"] = {
        **dict(manifest.get("candidate_patch") or {}),
        **normalized,
    }
    updated_manifest["revision"] = int(manifest.get("revision") or 0) + 1
    updated_manifest.pop("cache", None)
    updated_manifest["last_parameter_diff"] = exact_changes
    persistence_touched = False
    try:
        subject, subject_hash = _fx_cache_subject(params, pack_id, updated_manifest)
        persistence_touched = True
        _fx_store_manifest(root, updated_manifest)
        if any('particle_emission_snapshot' in item for item in prepared):
            _fx_planned_domain_readback(pack_id, {**changes, **(regeneration or {})},
                manifest.get('nodes') or {}, pack, frozen_writes=[item['native_write'] for item in prepared])
    except Exception as exc:
        rollback_errors = rollback_parameters()
        if persistence_touched:
            try:
                _fx_restore_manifest_persistence(root, persistence_snapshot)
            except BridgeCommandError as restore_exc:
                rollback_errors.append("manifest:{}".format(restore_exc.code))
        if rollback_errors:
            raise BridgeCommandError(
                "CANDIDATE_ROLLBACK_FAILED",
                "candidate persistence failed and rollback failed for {}".format(", ".join(rollback_errors)),
            ) from exc
        raise BridgeCommandError(
            "CANDIDATE_PERSIST_FAILED",
            "candidate parameters were restored because persistence failed: {}".format(exc),
        ) from exc
    readback_verified = bool(exact_changes) and all(item.get("readback_verified") is True for item in exact_changes)
    _fx_release_planned_items(prepared)
    return {
        "gates": [
            {
                "name": "candidate_patch_applied",
                "passed": readback_verified,
                "kind": "operation",
                "change_count": len(changes),
                "cache_subject_hash": subject_hash,
                "cache_approval_subject": subject,
            }
        ],
        "parameter_diff": exact_changes,
        "native_geometry_readback": domain_geometry_readback,
        "invalidates_from": sorted(set(invalidates)),
        "cache_approval_subject": subject,
        "cache_subject_hash": subject_hash,
    }


def _fx_verify(params: dict[str, Any], pack_id: str, pack: dict[str, Any]) -> dict[str, Any]:
    evidence_result = _fx_collect_evidence(params, pack_id, pack)
    evidence = evidence_result["evidence"]
    missing_visual = [item["name"] for item in evidence.get("requirements") or [] if not item.get("available")]
    return {
        "gates": evidence_result["gates"],
        "scorecard": {
            "schema": "houdini.fx.visual_scorecard/1.0",
            "technical_network_valid": all(gate.get("passed") for gate in evidence_result["gates"]),
            "visual_verdict": "INCONCLUSIVE" if missing_visual else "READY_FOR_HUMAN_REVIEW",
            "missing_evidence": missing_visual,
            "protected_attributes_verified": False,
            "claims_real_dynamics_from_single_image": False,
        },
        "diagnosis_state": "DIAGNOSIS_INCONCLUSIVE" if missing_visual else "CANDIDATES_READY",
    }


def _fx_parse_expiry(value: Any) -> Optional[datetime]:
    if value in (None, ""):
        return None
    text = str(value).strip().replace("Z", "+00:00")
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError as exc:
        raise BridgeCommandError("APPROVAL_INVALID", "approval expires_at must be ISO-8601") from exc
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _approval_secret_value() -> str:
    direct = os.environ.get("HOUDINI_BRIDGE_APPROVAL_SECRET")
    if direct:
        if len(direct) < 32:
            raise BridgeCommandError("APPROVAL_INVALID", "approval secret is too short")
        return direct
    configured = os.environ.get("BRIDGE_SKILLS_APPROVAL_SECRET_FILE")
    path = Path(configured).expanduser() if configured else Path.home() / ".bridge-skills" / "approval.key"
    if path.is_symlink() or not path.is_file():
        raise BridgeCommandError("APPROVAL_INVALID", "approval secret must be a regular file: {}".format(path))
    try:
        from dcc_task_runtime.platform_support import private_permissions_valid
        with path.open("r", encoding="ascii") as stream:
            if not private_permissions_valid(path, file_descriptor=stream.fileno()):
                raise BridgeCommandError("APPROVAL_INVALID", "approval secret file must have private current-user permissions")
            value = stream.read().strip()
    except (OSError, UnicodeError) as exc:
        raise BridgeCommandError("APPROVAL_INVALID", "approval secret file cannot be read") from exc
    if len(value) < 32:
        raise BridgeCommandError("APPROVAL_INVALID", "approval secret is empty or too short")
    return value


def _fx_validate_cache_approval(approval: Any, subject_hash: str, resource_contract=None) -> dict[str, Any]:
    if not isinstance(approval, dict):
        raise BridgeCommandError("APPROVAL_REQUIRED", "trusted human cache approval is required")
    if approval.get("purpose") != "houdini_simulation_cache":
        raise BridgeCommandError("APPROVAL_SCOPE_MISMATCH", "approval purpose must be houdini_simulation_cache")
    if not hmac.compare_digest(str(approval.get("subject_hash") or ""), subject_hash):
        raise BridgeCommandError("APPROVAL_REVOKED", "scene or cache subject changed after approval")
    grant_id = str(approval.get("grant_id") or "").strip()
    if not grant_id:
        raise BridgeCommandError("APPROVAL_INVALID", "approval grant_id is required")
    expiry = _fx_parse_expiry(approval.get("expires_at"))
    if expiry is not None and expiry <= datetime.now(timezone.utc):
        raise BridgeCommandError("APPROVAL_EXPIRED", "cache approval has expired")
    signature = str(approval.get("signature") or "")
    if not signature:
        # Caller-provided booleans are forgeable by any bridge client and can
        # never establish a trusted-human boundary.
        raise BridgeCommandError("APPROVAL_INVALID", "cache approval requires a verifiable control-plane signature")
    secret = _approval_secret_value()
    if expiry is None:
        raise BridgeCommandError("APPROVAL_INVALID", "signed approval requires expires_at")
    signed = "{}:{}:{}:{}".format(approval["purpose"], subject_hash, grant_id, approval.get("expires_at"))
    if resource_contract is not None:
        resource_hash = _canonical_payload_sha256(resource_contract)
        if approval.get("resource_contract_hash") != resource_hash:
            raise BridgeCommandError("APPROVAL_SCOPE_MISMATCH", "cache resource confirmation hash changed")
        signed += ":" + resource_hash
    expected = hmac.new(secret.encode("utf-8"), signed.encode("utf-8"), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise BridgeCommandError("APPROVAL_INVALID", "cache approval signature is invalid")
    return {"grant_id": grant_id, "purpose": approval["purpose"], "subject_hash": subject_hash, "expires_at": approval.get("expires_at"), "verified_by": "signature"}


def _fx_cache_files_complete(record: dict[str, Any], paths: list[Path]) -> bool:
    if record.get("state") == "FAILED" or not paths:
        return False
    before = record.get("before")
    # Legacy records cannot prove that old files belong to this execution.
    if not isinstance(before, dict):
        return False
    for frame, path in zip(record.get("frames") or [], paths):
        if not path.is_file() or path.stat().st_size <= 0:
            return False
        previous = before.get(str(frame))
        if previous and path.stat().st_mtime_ns <= int(previous.get("modified_ns", 0)):
            return False
    return True


def _fx_cache_resource_contract(params, subject):
    resource = dict(_fx_configuration(params).get("resource_contract") or {})
    required = ("estimated_bytes", "max_disk_bytes", "max_seconds", "task_roots", "invalidation_scope", "content_version")
    if any(key not in resource for key in required):
        raise BridgeCommandError("APPROVAL_REQUIRED", "exact cache resource confirmation is missing")
    frames = subject["frames"]
    if (type(resource["estimated_bytes"]) is not int or resource["estimated_bytes"] <= 0 or
            type(resource["max_disk_bytes"]) is not int or resource["max_disk_bytes"] < resource["estimated_bytes"] or
            isinstance(resource["max_seconds"], bool) or not isinstance(resource["max_seconds"], (int, float)) or
            not math.isfinite(resource["max_seconds"]) or not 0 < resource["max_seconds"] <= 120):
        raise BridgeCommandError("APPROVAL_SCOPE_MISMATCH", "cache budget is invalid")
    expected_range = [subject["frame_range"][key] for key in ("start", "end", "step")]
    if (resource.get("output_path") != subject["cache_output"] or resource.get("frame_range") != expected_range or
            resource.get("content_version") != _canonical_payload_sha256(subject["scene"]) or
            not resource.get("invalidation_scope")):
        raise BridgeCommandError("APPROVAL_SCOPE_MISMATCH", "cache resource identity differs from approved scene/range/path")
    roots = resource.get("task_roots")
    output = Path(subject["cache_output"])
    if (not isinstance(roots, list) or not roots or not output.is_absolute() or
            any(not isinstance(root, str) or not Path(root).is_absolute() or Path(root).is_symlink() for root in roots) or
            not any(output.resolve().is_relative_to(Path(root).resolve()) for root in roots)):
        raise BridgeCommandError("APPROVAL_SCOPE_MISMATCH", "cache output is outside trusted task roots")
    start = resource.get("simulation_start_frame")
    if type(start) is not int or start > frames[0]:
        raise BridgeCommandError("APPROVAL_REQUIRED", "explicit solver history start frame is required")
    return resource


def _fx_cache_usage(resource, reserve=0):
    total, seen = 0, set()
    for root in resource["task_roots"]:
        root = Path(root)
        if root.is_symlink():
            raise BridgeCommandError("DISK_BUDGET_EXCEEDED", "task budget root changed into a symlink")
        for path in root.rglob("*"):
            if path.is_symlink():
                raise BridgeCommandError("DISK_BUDGET_EXCEEDED", "unaccounted symlink in task budget root")
            if path.is_file():
                info = path.stat()
                identity = (info.st_dev, info.st_ino)
                if identity not in seen:
                    total += info.st_size; seen.add(identity)
    if total + reserve > resource["max_disk_bytes"]:
        raise BridgeCommandError("DISK_BUDGET_EXCEEDED", "confirmed cache disk budget exceeded")
    return total


def _fx_cache_status(params: dict[str, Any], pack_id: str, _pack: dict[str, Any]) -> dict[str, Any]:
    """Pure read: only a completed runner plus exact saved bytes proves cache completion."""
    _root, manifest = _fx_manifest(str(params.get("task_id") or ""))
    expected = str(params.get("expected_subject_hash") or "")
    if not expected:
        raise BridgeCommandError("INVALID_REQUEST", "cache status requires expected_subject_hash")
    _subject, current_hash = _fx_cache_subject(params, pack_id, manifest)
    if current_hash != expected:
        raise BridgeCommandError("SCENE_STATE_DRIFT", "current cache subject differs from requested operation")
    previous = manifest.get("cache") or {}
    if not previous:
        return {"cached": False, "cache": {"state": "NOT_STARTED"}, "artifacts": []}
    if previous.get("subject_hash") != expected:
        raise BridgeCommandError("SCENE_STATE_DRIFT", "host holds a different cache operation")
    cache = dict(previous)
    operation_id = cache.get("operation_id")
    if not operation_id:
        cache["state"] = "RECONCILE"
        return {"cached": False, "cache_required": True, "cache": cache, "artifacts": [],
                "gates": [{"name": "approved_simulation_cache", "passed": False, "kind": "verification"}]}
    try:
        record = fx_operation_runner(str(params["task_id"])).status(operation_id)
    except BridgeCommandError as exc:
        if getattr(exc, "code", None) != "OPERATION_NOT_FOUND":
            raise
        cache["state"] = "SUBMISSION_PENDING"
        return {"cached": False, "cache_required": True, "cache": cache, "artifacts": [],
                "gates": [{"name": "approved_simulation_cache", "passed": False, "kind": "progress"}]}
    stop_confirmed = bool((record.get("lifecycle_fact") or {}).get("stop_confirmed"))
    complete = record.get("state") == "COMPLETED" and stop_confirmed
    paths = [_fx_cache_frame_path(cache["output_pattern"], frame) for frame in cache["frames"]]
    written = {int(row["frame"]): row.get("cache_file") for row in record.get("evidence", []) if row.get("cache_file")}
    for frame, path in zip(cache["frames"], paths):
        snapshot = written.get(frame) or {}
        complete = complete and path.is_file() and path.stat().st_size > 0 and snapshot.get("sha256") == _fx_sha256_file(path)
    cache.update({"state": "COMPLETE" if complete else record.get("state", "RECONCILE"),
                  "operation_state": record.get("state"), "stop_confirmed": stop_confirmed,
                  "segments_done": list(record.get("cache_segments_done") or [])})
    return {"cached": bool(complete), "cache_required": True, "cache": cache, "reused": True,
            "artifacts": [_artifact(path) for path in paths] if complete else [],
            "gates": [{"name": "approved_simulation_cache", "passed": bool(complete), "kind": "verification"}]}


def _fx_cache_history(binding):
    """Read old durable intents without flattening their segment lists."""
    if "history_range" in binding:
        history = binding.get("history_range")
        count = binding.get("segment_count")
        if (not isinstance(history, list) or len(history) != 2 or
                any(type(frame) is not int for frame in history) or history[1] < history[0] or
                type(count) is not int or count != (history[1] - history[0]) // 12 + 1):
            raise BridgeCommandError("APPROVAL_SCOPE_MISMATCH", "invalid compact solver history")
        return history, count
    segments = binding.get("segments")
    if not isinstance(segments, list) or not segments:
        raise BridgeCommandError("APPROVAL_SCOPE_MISMATCH", "missing solver history")
    first = None
    expected = None
    for index, segment in enumerate(segments):
        if (not isinstance(segment, list) or not 0 < len(segment) <= 12 or
                (index < len(segments) - 1 and len(segment) != 12) or
                any(type(frame) is not int for frame in segment)):
            raise BridgeCommandError("APPROVAL_SCOPE_MISMATCH", "invalid legacy solver segment")
        if first is None:
            first = expected = segment[0]
        for frame in segment:
            if frame != expected:
                raise BridgeCommandError("APPROVAL_SCOPE_MISMATCH", "non-contiguous solver history")
            expected += 1
    return [first, expected - 1], len(segments)


def _fx_cache_segment(binding, index):
    """Expand only the current approved solver segment, never its history."""
    history, count = _fx_cache_history(binding)
    if type(index) is not int or not 0 <= index < count:
        raise BridgeCommandError("APPROVAL_SCOPE_MISMATCH", "invalid solver segment index")
    start = history[0] + index * 12
    return list(range(start, min(start + 12, history[1] + 1)))


def _fx_cache(params: dict[str, Any], pack_id: str, pack: dict[str, Any]) -> dict[str, Any]:
    if not pack.get("simulation_cache"):
        return {"gates": [{"name": "simulation_cache_not_applicable", "passed": True, "kind": "not_applicable", "skipped": True}], "cache_required": False, "cached": False}
    task_id = str(params.get("task_id") or "")
    root, manifest = _fx_manifest(task_id)
    subject, subject_hash = _fx_cache_subject(params, pack_id, manifest)
    resource = _fx_cache_resource_contract(params, subject)
    supplied = _fx_configuration(params).get("approval")
    approval = _fx_validate_cache_approval(supplied, subject_hash, resource)
    previous = manifest.get("cache") or {}
    if previous:
        if previous.get("subject_hash") != subject_hash or previous.get("resource_hash") != _canonical_payload_sha256(resource):
            raise BridgeCommandError("CONTENT_CHANGED", "cache subject/resources changed; resolve the previous operation first")
        status = _fx_cache_status({**params, "expected_subject_hash": subject_hash}, pack_id, pack)
        if status["cache"]["state"] != "SUBMISSION_PENDING":
            return status
    _fx_cache_usage(resource, resource["estimated_bytes"])
    history_range = [resource["simulation_start_frame"], subject["frames"][-1]]
    segment_count = (history_range[1] - history_range[0]) // 12 + 1
    operation_id = "cache-" + subject_hash[:32]
    binding = {"subject_hash": subject_hash, "resource_contract": resource,
               "resource_hash": _canonical_payload_sha256(resource),
               "history_range": history_range, "segment_count": segment_count,
               "output_frames": subject["frames"], "output_pattern": subject["cache_output"],
               "approval": supplied}
    # A PREPARED legacy intent retains its original request digest and shape.
    if previous.get("segments"):
        binding.pop("history_range"); binding.pop("segment_count")
        binding["segments"] = previous["segments"]
        _fx_cache_history(binding)
    cache = {"subject_hash": subject_hash, "resource_hash": binding["resource_hash"], "subject": subject,
             "operation_id": operation_id, "output_pattern": subject["cache_output"], "frames": subject["frames"],
             "state": "PREPARED", "approval": approval,
             "history_range": history_range, "segment_count": segment_count}
    # Runner intent owns launch/recovery; cache metadata is saved first and
    # an interrupted submit is recovered only by repeating the exact identity.
    manifest["cache"] = cache
    _fx_store_manifest(root, manifest)
    runner_params = json.loads(json.dumps(params))
    first_segment = _fx_cache_segment(binding, 0)
    runner_params["constraints"]["fx"]["frames"] = first_segment
    runner_params["render"] = {"frame_range": {"start": first_segment[0], "end": first_segment[-1], "step": 1}}
    runner_params["budget_seconds"] = resource["max_seconds"]
    runner_params["_cache_binding"] = binding
    result = fx_operation_runner(task_id).submit(runner_params, pack_id, pack, request_id=operation_id)
    return {"cache_required": True, "cached": False, "cache": {**cache, "state": result["record"]["state"]},
            "artifacts": [], "gates": [{"name": "approved_simulation_cache", "passed": False, "kind": "progress"}]}


def _fx_deliver(params: dict[str, Any], pack_id: str, _pack: dict[str, Any]) -> dict[str, Any]:
    import hou

    task_id = str(params.get("task_id") or "")
    _root, manifest = _fx_manifest(task_id)
    nodes = manifest.get("nodes") or {}
    missing = [str(role) for role, path in sorted(nodes.items()) if hou.node(str(path)) is None]
    assessment = manifest.get("execution_assessment") or {}
    # Delivery may only claim success when the network is still present in the
    # scene and has actually been rendered, rather than merely scaffolded.
    render_validated = bool(assessment.get("render_validated"))
    passed = bool(nodes) and not missing and render_validated
    return {
        "gates": [
            {
                "name": "editable_fx_delivery",
                "passed": passed,
                "kind": "verification",
                "domain_pack": pack_id,
                "missing_nodes": missing,
                "render_validated": render_validated,
                "reason": None if passed else ("missing_nodes" if missing else "render_not_validated"),
            }
        ],
        "delivery": {
            "domain_pack": pack_id,
            "maturity": manifest.get("maturity", "experimental"),
            "nodes": nodes,
            "cache": manifest.get("cache"),
            "scene_metadata_persisted": True,
        },
    }


def _fx_query_producer_receipt(params):
    task_id, operation_id = params.get('task_id'), params.get('operation_id')
    if (not isinstance(task_id, str) or not task_id
            or not isinstance(operation_id, str)
            or not re.fullmatch(r'[A-Za-z0-9_.-]{1,100}', operation_id)):
        raise BridgeCommandError('INVALID_ARGUMENT', 'task and bounded producer operation ID required')
    identity = _fx_producer_identity(task_id)
    runner = fx_operation_runner(task_id)
    with runner._locked():
        prior, _, storage = _fx_producer_record(runner, runner._load(), operation_id)
    current_scene = (_fx_producer_scene(task_id, prior['request'], capture_policy=_fx_scene_capture_policy(
                        prior['after_scene']['scene_contract'], task_id))
                     if prior is not None and prior.get('state') == 'COMPLETED'
                     and prior.get('schema') == 'bridge.houdini.producer-operation/1.0' else None)
    if _fx_producer_identity(task_id) != identity:
        raise BridgeCommandError('SCENE_STATE_DRIFT', 'producer identity changed during receipt query')
    return {'task_id': task_id, 'operation_id': operation_id,
        'operation_receipt': prior, 'operation_store_format': storage,
        'current_host_identity': identity, 'current_scene': current_scene}


def _fx_operation_dispatch(command: str, params: dict[str, Any]) -> "dict[str, Any] | None":
    if command == "render.start":
        task_id = str(params.get("task_id") or "")
        if not task_id:
            raise BridgeCommandError("INVALID_ARGUMENT", "task_id is required")
        return fx_operation_runner(task_id).submit_render(params)
    if command in ("render.status", "render.verify", "render.cancel"):
        task_id = str(params.get("task_id") or "")
        operation_id = str(params.get("operation_id") or "")
        if not task_id or not operation_id:
            raise BridgeCommandError("INVALID_ARGUMENT", "task_id and operation_id are required")
        runner = fx_operation_runner(task_id)
        record = runner.cancel(operation_id) if command == "render.cancel" else runner.status(operation_id)
        if record.get("kind") != "render":
            raise BridgeCommandError("OPERATION_KIND_MISMATCH", "operation is not a render")
        return {"operation": record, "execution_fact": runner.render_fact(operation_id)}
    if command == "operation.status":
        return fx_operation_status(params)
    if command == "operation.cancel":
        return fx_operation_cancel(params)
    return None


def _fx_action(command: str, params: dict[str, Any]) -> dict[str, Any]:
    if command == "agent.fx.operation_receipt":
        return _fx_query_producer_receipt(params)
    if command == "agent.fx.bind_graph_trial":
        return _fx_bind_graph_trial(params)
    if command == "agent.fx.probe" and not str(_fx_configuration(params).get("domain_pack") or "").strip():
        return {"domain_packs": [_fx_probe_pack(pack_id, pack) for pack_id, pack in sorted(_FX_PACKS.items())]}
    pack_id, pack = _fx_pack(params)
    if command == "agent.fx.probe":
        probe = _fx_probe_pack(pack_id, pack)
        return {
            "gates": [{"name": "fx_node_contract_probe", "passed": probe["node_contract_available"], "kind": "capability", "status": probe["probe_state"]}],
            "domain_pack": probe,
            "diagnosis_state": probe["probe_state"],
        }
    if command == "agent.fx.simulate_segment":
        return fx_simulate_segment(params, pack_id, pack)
    if command == "agent.fx.software_boundary_execute":
        return _fx_software_boundary_execute(params, pack_id, pack)
    if command == "agent.fx.build_preview":
        return _fx_build_preview(params, pack_id, pack)
    if command == "agent.fx.collect_evidence":
        return _fx_collect_evidence(params, pack_id, pack)
    if command == "agent.fx.inspect_controls":
        return _fx_inspect_controls(params, pack_id, pack)
    if command == "agent.fx.apply_candidate":
        return _fx_apply_candidate(params, pack_id, pack)
    if command == "agent.fx.verify":
        return _fx_verify(params, pack_id, pack)
    if command == "agent.fx.cache_status":
        return _fx_cache_status(params, pack_id, pack)
    if command == "agent.fx.cache":
        return _fx_cache(params, pack_id, pack)
    if command == "agent.fx.deliver":
        return _fx_deliver(params, pack_id, pack)
    raise BridgeCommandError("UNSUPPORTED_COMMAND", "unsupported structured FX action: {}".format(command))


_BRIDGE_SCENE_STATE_KEY = "_houdini_bridge_scene_identity_state"
_BRIDGE_SCENE_STATE = sys.modules.get(_BRIDGE_SCENE_STATE_KEY)
if _BRIDGE_SCENE_STATE is None:
    _BRIDGE_SCENE_STATE = SimpleNamespace(
        session_id=uuid4().hex,
        process_generation="{}:{}".format(os.getpid(), uuid4().hex),
        scene_epoch=0,
    )
    sys.modules[_BRIDGE_SCENE_STATE_KEY] = _BRIDGE_SCENE_STATE
_BRIDGE_SCENE_CALLBACK_INSTALLED = False


_FX_OWNED_HIP_LOAD = None


def _fx_scene_event_increments_epoch(channel, event_type):
    import hou
    increments = event_type in (hou.hipFileEventType.BeforeClear, hou.hipFileEventType.BeforeLoad,
                                hou.hipFileEventType.BeforeMerge)
    context = _FX_OWNED_HIP_LOAD
    if context is None or channel not in context:
        return increments
    state = context[channel]
    phase = state["phase"]
    events = hou.hipFileEventType
    if phase == "start" and event_type == events.BeforeLoad:
        state["phase"] = "loading"
    elif phase == "loading" and event_type == events.BeforeClear:
        state["phase"] = "clearing"
        return False
    elif phase == "clearing" and event_type == events.AfterClear:
        state["phase"] = "cleared"
    elif phase in {"loading", "cleared"} and event_type == events.AfterLoad:
        state["phase"] = "complete"
    else:
        state["invalid"] = True
    return increments


@contextmanager
def _fx_owned_hip_load_events(*, trace_phase="owned_hip_load"):
    """Count a native load's embedded clear as one bounded scene transition."""
    import hou
    global _FX_OWNED_HIP_LOAD
    if _FX_OWNED_HIP_LOAD is not None:
        raise BridgeCommandError("SCENE_STATE_DRIFT", "nested owned HIP load is not permitted")
    _ = (hou.hipFileEventType.AfterClear, hou.hipFileEventType.AfterLoad)
    callbacks = hou.hipFile.eventCallbacks()
    if _bridge_scene_event not in callbacks:
        raise BridgeCommandError("SCENE_STATE_DRIFT", "owned HIP load requires retained scene callback")
    context = {"host": {"phase": "start", "invalid": False}}
    if _graph_worker_scene_event in callbacks:
        context["producer"] = {"phase": "start", "invalid": False}
    _FX_OWNED_HIP_LOAD = context
    listener = globals().get("_SERVER")
    _fx_listener_trace(trace_phase + "_before", expected_server=listener)
    try:
        try:
            yield
        except Exception as error:
            if isinstance(error, getattr(hou, "LoadWarning", ())):
                if any(state["phase"] != "complete" or state["invalid"] for state in context.values()):
                    raise BridgeCommandError("SCENE_STATE_DRIFT", "warned HIP load event sequence differs: " + repr(context)) from error
            raise
        if any(state["phase"] != "complete" or state["invalid"] for state in context.values()):
            raise BridgeCommandError("SCENE_STATE_DRIFT", "owned HIP load event sequence differs: " + repr(context))
    finally:
        _fx_listener_trace(trace_phase + "_after", expected_server=listener)
        _FX_OWNED_HIP_LOAD = None


def _bridge_scene_event(event_type, **_kwargs):
    import hou
    if _fx_scene_event_increments_epoch("host", event_type):
        _BRIDGE_SCENE_STATE.scene_epoch += 1
        if globals().get('_BRIDGE_PARTICLE_EMISSION_AUTHORITY') is not None:
            _fx_particle_emission_host().invalidate_scene()
    events = list(getattr(_BRIDGE_SCENE_STATE, "recent_events", ()))
    events.append({"event": str(event_type)[:80], "epoch": _BRIDGE_SCENE_STATE.scene_epoch})
    _BRIDGE_SCENE_STATE.recent_events = events[-8:]


def bridge_scene_identity():
    """Return the live GUI/headless identity used by the S-06 controller.

    Unlike ``graph_worker_identity`` this is allowed in a normal Houdini GUI.
    It still requires a saved hip and retained hip-file event support; a
    version string alone can never authorize a host operation.
    """
    import hou
    global _BRIDGE_SCENE_CALLBACK_INSTALLED
    if _BRIDGE_SCENE_CALLBACK_INSTALLED:
        if _bridge_scene_event not in hou.hipFile.eventCallbacks():
            raise BridgeCommandError("SCENE_STATE_DRIFT", "scene identity callback was removed")
    else:
        _ = (hou.hipFileEventType.BeforeClear, hou.hipFileEventType.BeforeLoad,
             hou.hipFileEventType.BeforeMerge)
        hou.hipFile.addEventCallback(_bridge_scene_event)
        _BRIDGE_SCENE_CALLBACK_INSTALLED = True
        if _bridge_scene_event not in hou.hipFile.eventCallbacks():
            raise BridgeCommandError("SCENE_STATE_DRIFT", "scene identity callback registration was not retained")
    raw_path = str(hou.hipFile.path() or "").strip()
    if not raw_path:
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "an explicitly saved hip file is required")
    hip_path = str(Path(raw_path).expanduser().resolve())
    scene_id = hashlib.sha256(
        json.dumps([hip_path, _BRIDGE_SCENE_STATE.scene_epoch], ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    return {
        "session_id": _BRIDGE_SCENE_STATE.session_id,
        "process_generation": _BRIDGE_SCENE_STATE.process_generation,
        "scene_id": scene_id,
        "hip_path": hip_path,
    }


def _s06_contracts_module():
    """Load the path-free S-06 contract helpers without importing Houdini."""

    package_root = _FX_REPOSITORY_ROOT / "packages" / "vfx-pipeline" / "src"
    if package_root.is_dir() and str(package_root) not in sys.path:
        sys.path.insert(0, str(package_root))
    try:
        from vfx_pipeline import s06_contracts
    except ImportError as exc:
        raise BridgeCommandError(
            "S06_CONTRACT_UNAVAILABLE",
            "the reviewed S-06 controller contract is not installed beside the add-on",
        ) from exc
    return s06_contracts


def _s06_velocity_module():
    """Load the structured field comparator used by the dedicated adapter."""

    package_root = _FX_REPOSITORY_ROOT / "packages" / "vfx-pipeline" / "src"
    if package_root.is_dir() and str(package_root) not in sys.path:
        sys.path.insert(0, str(package_root))
    try:
        from vfx_pipeline import s06_velocity
    except ImportError as exc:
        raise BridgeCommandError(
            "S06_VELOCITY_CONTRACT_UNAVAILABLE",
            "the reviewed S-06 velocity comparator is not installed beside the add-on",
        ) from exc
    return s06_velocity


def _s06_strict_json(value: Any, *, path: str = "$", depth: int = 0) -> Any:
    """Copy a bounded JSON payload while rejecting code/control escape hatches."""

    if depth > 12:
        raise BridgeCommandError("S06_PAYLOAD_INVALID", "S-06 adapter payload nesting is too deep")
    if isinstance(value, dict):
        result = {}
        for key, item in value.items():
            if not isinstance(key, str):
                raise BridgeCommandError("S06_PAYLOAD_INVALID", "S-06 adapter payload keys must be strings")
            if key.casefold() in {"code", "python", "exec", "eval", "command", "shell"}:
                raise BridgeCommandError("S06_RAW_CODE_FORBIDDEN", "S-06 adapter does not accept executable fields")
            result[key] = _s06_strict_json(item, path=path + "." + key, depth=depth + 1)
        return result
    if isinstance(value, (list, tuple)):
        if len(value) > 4096:
            raise BridgeCommandError("S06_PAYLOAD_INVALID", "S-06 adapter arrays are too large")
        return [_s06_strict_json(item, path=path + "[]", depth=depth + 1) for item in value]
    if value is None or isinstance(value, bool) or isinstance(value, int):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise BridgeCommandError("S06_PAYLOAD_INVALID", "S-06 adapter payload contains a non-finite number")
        return value
    if isinstance(value, str):
        if len(value) > 100000:
            raise BridgeCommandError("S06_PAYLOAD_INVALID", "S-06 adapter text field is too large")
        return value
    raise BridgeCommandError("S06_PAYLOAD_INVALID", "S-06 adapter payload is not JSON-compatible")


def _s06_authorized_path(root: str, value: Any, label: str, *, allow_root: bool = False) -> str:
    """Accept only a simple Houdini node path below the controller root."""

    if not isinstance(value, str) or not value.startswith(root + "/"):
        if allow_root and value == root:
            return value
        raise BridgeCommandError("S06_SCENE_SCOPE_INVALID", "{} is outside the authorized graph root".format(label))
    suffix = value[len(root) + 1 :]
    if not suffix or any(part in {"", ".", ".."} for part in suffix.split("/")):
        raise BridgeCommandError("S06_SCENE_SCOPE_INVALID", "{} contains an unsafe node path".format(label))
    if not re.fullmatch(r"[A-Za-z0-9_.-]+(?:/[A-Za-z0-9_.-]+)*", suffix):
        raise BridgeCommandError("S06_SCENE_SCOPE_INVALID", "{} is not a simple task-owned node path".format(label))
    return value


def _s06_validate_schedule(schedule: Any, frame_segment: dict[str, Any]) -> None:
    if not isinstance(schedule, dict) or set(schedule) != {"schema", "frame_start", "frame_end", "step", "rows"}:
        raise BridgeCommandError("S06_SCHEDULE_INVALID", "controller source schedule has an unexpected shape")
    if schedule.get("schema") != "bridge.f2.source-activation-schedule/1.0":
        raise BridgeCommandError("S06_SCHEDULE_INVALID", "controller source schedule schema is invalid")
    start = frame_segment.get("start")
    end = frame_segment.get("end")
    if schedule.get("frame_start") != start or schedule.get("frame_end") != end or schedule.get("step") != 1:
        raise BridgeCommandError("S06_SCHEDULE_INVALID", "controller source schedule is not bound to the frame segment")
    rows = schedule.get("rows")
    if not isinstance(rows, dict) or set(rows) != {"1", "2"} or rows["1"] != rows["2"]:
        raise BridgeCommandError("S06_SCHEDULE_INVALID", "controller source rows do not share one frozen schedule")
    for row in ("1", "2"):
        intervals = rows[row]
        if not isinstance(intervals, list) or not intervals:
            raise BridgeCommandError("S06_SCHEDULE_INVALID", "controller source schedule is empty")
        prior_end = None
        for interval in intervals:
            if not isinstance(interval, dict) or set(interval) != {"start", "end"}:
                raise BridgeCommandError("S06_SCHEDULE_INVALID", "controller source interval is invalid")
            interval_start, interval_end = interval["start"], interval["end"]
            if (
                type(interval_start) is not int
                or type(interval_end) is not int
                or interval_start < start
                or interval_end <= interval_start
                or interval_end > end + 1
                or (prior_end is not None and interval_start < prior_end)
            ):
                raise BridgeCommandError("S06_SCHEDULE_INVALID", "controller source interval is outside the frozen frame window")
            prior_end = interval_end


def _s06_validate_controller_request(params: dict[str, Any]) -> tuple[dict[str, Any], str]:
    """Validate the exact request issued by the software controller."""

    _s06_strict_json(params)
    request = params.get("s06_controller_request")
    if not isinstance(request, dict):
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_MISSING", "S-06 adapter requires a controller-issued request")
    expected_keys = {
        "schema", "adapter", "transport", "task_id", "operation_id", "request_id",
        "execution_root", "host_identity", "frame_segment", "source_schedule",
        "source_binding", "velocity_sentinel", "authorization_hash", "cache_allowed",
        "render_allowed", "first_graph_mutation",
    }
    request_keys = set(request)
    if request_keys not in (expected_keys, expected_keys | {"scene_ownership"}):
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller request keys are not exact")
    if request.get("schema") != _S06_CONTROLLER_REQUEST_SCHEMA:
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller request schema is invalid")
    if request.get("adapter") != _S06_ADAPTER_SCHEMA or request.get("transport") != "houdini_main_thread":
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller request is not bound to the Houdini main-thread adapter")
    for key in ("task_id", "operation_id", "request_id"):
        if not isinstance(request.get(key), str) or not re.fullmatch(r"[A-Za-z0-9_-]{1,100}", request[key]):
            raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller request identity is invalid: {}".format(key))
    root = request.get("execution_root")
    if not isinstance(root, str) or not re.fullmatch(r"/obj/BRIDGE_GRAPH_[0-9a-f]{64}", root):
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller request root is not generated")
    identity = request.get("host_identity")
    if not isinstance(identity, dict) or set(identity) != {"session_id", "process_generation", "scene_id", "hip_path"}:
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller host identity is incomplete")
    if any(not isinstance(identity[key], str) or not identity[key].strip() for key in identity):
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller host identity contains an empty value")
    if not isinstance(identity["hip_path"], str) or not Path(identity["hip_path"]).is_absolute():
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller HIP identity is not absolute")

    frame_segment = request.get("frame_segment")
    if not isinstance(frame_segment, dict) or set(frame_segment) != {
        "start", "end", "step", "preroll_frames", "max_elapsed_seconds", "max_cook_seconds_per_frame",
    }:
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller frame segment is incomplete")
    if (
        type(frame_segment["start"]) is not int
        or type(frame_segment["end"]) is not int
        or frame_segment["start"] < 0
        or frame_segment["end"] < frame_segment["start"]
        or frame_segment["step"] != 1
        or type(frame_segment["preroll_frames"]) is not int
        or frame_segment["preroll_frames"] < 0
        or type(frame_segment["max_elapsed_seconds"]) not in (int, float)
        or type(frame_segment["max_cook_seconds_per_frame"]) not in (int, float)
        or not math.isfinite(float(frame_segment["max_elapsed_seconds"]))
        or not math.isfinite(float(frame_segment["max_cook_seconds_per_frame"]))
        or frame_segment["max_elapsed_seconds"] <= 0
        or frame_segment["max_cook_seconds_per_frame"] <= 0
    ):
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller frame segment values are invalid")
    _s06_validate_schedule(request.get("source_schedule"), frame_segment)
    expected_source_binding = {
        "capture_file_sha256": _SOLVER_SOURCING_CAPTURE_SHA256,
        "snapshot_sha256": _SOLVER_SOURCING_TEMPLATE_SNAPSHOT_SHA256,
        "capture_state": "CAPTURED_NOT_BOUND",
    }
    if request.get("source_binding") != expected_source_binding:
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller source evidence binding is not the reviewed capture")
    velocity = _s06_velocity_module()
    sentinel = request.get("velocity_sentinel")
    if velocity.validate_snapshot(sentinel) or sentinel != velocity.default_controller_sentinel():
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller velocity sentinel is not the fixed nonzero reviewed sentinel")
    if not isinstance(request.get("authorization_hash"), str) or not re.fullmatch(r"[0-9a-f]{64}", request["authorization_hash"]):
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "controller authorization hash is invalid")
    if request.get("cache_allowed") is not False or request.get("render_allowed") is not False:
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "S-06 request permits cache or render output")
    if request.get("first_graph_mutation") != "pending":
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "S-06 graph mutation was not pending at issuance")
    if "scene_ownership" in request:
        ownership = request.get("scene_ownership")
        if not isinstance(ownership, dict):
            raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "scene ownership record is not an object")
        try:
            valid = _s06_contracts_module().scene_ownership_record_valid(ownership)
        except Exception:
            valid = False
        if not valid or ownership.get("task_id") != request["task_id"] or ownership.get("operation_id") != request["operation_id"]:
            raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "scene ownership record is not bound to the request")
    declared_request_hash = params.get("s06_controller_request_hash")
    if declared_request_hash is not None:
        if not isinstance(declared_request_hash, str) or declared_request_hash != _s06_contracts_module().controller_request_hash(request):
            raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "S-06 controller request hash does not read back")

    binding = params.get("bridge_execution_binding")
    if not isinstance(binding, dict) or set(binding) != {"schema", "task_id", "operation_id", "host_identity", "execution_root"}:
        raise BridgeCommandError("S06_SCENE_SCOPE_INVALID", "S-06 execution binding is incomplete")
    if binding.get("schema") != _S06_HOST_BINDING_SCHEMA or binding.get("execution_root") != root:
        raise BridgeCommandError("S06_SCENE_SCOPE_INVALID", "S-06 execution binding does not match the request root")
    if binding.get("task_id") != request["task_id"] or binding.get("operation_id") != request["operation_id"]:
        raise BridgeCommandError("S06_SCENE_SCOPE_INVALID", "S-06 execution binding identity differs from the request")
    if binding.get("host_identity") != identity or params.get("bridge_graph_root") != root:
        raise BridgeCommandError("S06_SCENE_SCOPE_INVALID", "S-06 execution binding host identity differs from the request")
    f2_intent = params.get("f2_short_segment")
    if not isinstance(f2_intent, dict) or f2_intent.get("schema") != _S06_INTENT_SCHEMA:
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "S-06 source intent is missing")
    if (
        f2_intent.get("frame_segment") != frame_segment
        or f2_intent.get("source_schedule") != request["source_schedule"]
        or f2_intent.get("source_binding") != expected_source_binding
        or f2_intent.get("cache_allowed") is not False
        or f2_intent.get("render_allowed") is not False
    ):
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "S-06 source intent is not bound to the controller request")
    if params.get("task_id") is not None and params.get("task_id") != request["task_id"]:
        raise BridgeCommandError("S06_CONTROLLER_REQUEST_INVALID", "S-06 task parameter differs from the controller request")
    return request, root


def _s06_provider_module() -> Any | None:
    """Load the Bridge-owned provider from the add-on directory only."""

    global _S06_NATIVE_PROVIDER_MODULE, _S06_NATIVE_PROVIDER_LOAD
    if _S06_NATIVE_PROVIDER_MODULE is not None:
        return _S06_NATIVE_PROVIDER_MODULE
    source = _S06_NATIVE_PROVIDER_SOURCE
    if not source.is_file() or _fx_path_has_symlink(source):
        _S06_NATIVE_PROVIDER_LOAD = {
            "state": "SOURCE_UNAVAILABLE",
            "path": str(source),
            "sha256": None,
        }
        return None
    try:
        source_hash = _fx_sha256_file(source)
        module_name = "_bridge_s06_native_provider_{}".format(source_hash[:16])
        spec = importlib.util.spec_from_file_location(module_name, source)
        if spec is None or spec.loader is None:
            raise ImportError("provider module spec is unavailable")
        module = importlib.util.module_from_spec(spec)
        previous = sys.modules.get(module_name)
        sys.modules[module_name] = module
        try:
            spec.loader.exec_module(module)
        except Exception:
            if previous is None:
                sys.modules.pop(module_name, None)
            else:
                sys.modules[module_name] = previous
            raise
        _S06_NATIVE_PROVIDER_MODULE = module
        _S06_NATIVE_PROVIDER_LOAD = {
            "state": "LOADED",
            "path": str(source),
            "sha256": source_hash,
            "module": module_name,
        }
        return module
    except Exception as exc:
        _S06_NATIVE_PROVIDER_LOAD = {
            "state": "LOAD_ERROR",
            "path": str(source),
            "sha256": None,
            "error_type": type(exc).__name__,
        }
        return None


def _s06_install_native_provider(hou: Any) -> dict[str, Any]:
    """Install the Bridge provider during plugin load without overwriting a host seam."""

    global _S06_NATIVE_PROVIDER_LOAD
    module = _s06_provider_module()
    if module is None:
        return {**dict(_S06_NATIVE_PROVIDER_LOAD), "provider_installed": False}
    installer = getattr(module, "install", None)
    if not callable(installer):
        return {
            **dict(_S06_NATIVE_PROVIDER_LOAD),
            "state": "INSTALLER_UNAVAILABLE",
            "provider_installed": False,
        }
    try:
        result = installer(hou)
    except Exception as exc:
        return {
            **dict(_S06_NATIVE_PROVIDER_LOAD),
            "state": "INSTALL_ERROR",
            "provider_installed": False,
            "error_type": type(exc).__name__,
        }
    if not isinstance(result, dict):
        return {
            **dict(_S06_NATIVE_PROVIDER_LOAD),
            "state": "INSTALL_RESULT_INVALID",
            "provider_installed": False,
        }
    provider = result.get("provider")
    state = str(result.get("state") or "UNKNOWN")
    _S06_NATIVE_PROVIDER_LOAD = {
        **dict(_S06_NATIVE_PROVIDER_LOAD),
        "state": "INSTALLED" if state in {"installed", "already_installed"} else state.upper(),
        "provider_installed": state in {"installed", "already_installed"},
        "provider_state": state,
    }
    return {
        **dict(_S06_NATIVE_PROVIDER_LOAD),
        "provider_installed": state in {"installed", "already_installed"},
        "provider": provider,
        "result": {key: value for key, value in result.items() if key not in {"provider", "capabilities"}},
        "capabilities": result.get("capabilities"),
    }


def _s06_provider_value(provider: Any, name: str) -> Any:
    value = getattr(provider, name, None)
    if callable(value):
        try:
            return value()
        except Exception:
            return None
    return value


def _s06_provider_capabilities(provider: Any) -> tuple[dict[str, Any] | None, str | None]:
    getter = getattr(provider, "capabilities", None)
    if not callable(getter):
        return None, "PROVIDER_CAPABILITIES_METHOD_MISSING"
    try:
        value = getter()
    except Exception as exc:
        return None, "PROVIDER_CAPABILITIES_ERROR:{}".format(type(exc).__name__)
    if not isinstance(value, dict):
        return None, "PROVIDER_CAPABILITIES_NOT_OBJECT"
    if value.get("schema") != _S06_NATIVE_ADAPTER_SCHEMA:
        return value, "PROVIDER_CAPABILITIES_SCHEMA_INVALID"
    interfaces = value.get("interfaces")
    if not isinstance(interfaces, dict):
        return value, "PROVIDER_CAPABILITIES_INTERFACES_INVALID"
    return value, None


def _s06_native_provider(hou: Any) -> Any | None:
    """Resolve a mutation-ready provider, not merely a callable-shaped object.

    The four methods are intentionally not sufficient.  The provider must
    publish a typed capability registry and explicitly mark every interface as
    ``verified``/mutation-ready.  The Bridge implementation installed by this
    package is currently partial, so it remains blocked until a separately
    authorized native experiment supplies the missing verification.
    """

    provider = getattr(hou, _S06_NATIVE_ADAPTER_ATTRIBUTE, None)
    if provider is None:
        return None
    if _s06_provider_value(provider, "schema") != _S06_NATIVE_ADAPTER_SCHEMA:
        return None
    capabilities, error = _s06_provider_capabilities(provider)
    if error or capabilities is None:
        return None
    if capabilities.get("provider_version") != "1.0":
        return None
    if capabilities.get("houdini_build") != _SOLVER_SOURCING_BUILD:
        return None
    interfaces = capabilities.get("interfaces")
    if any(
        not isinstance(interfaces.get(name), dict)
        or interfaces[name].get("status") != "verified"
        for name in _S06_NATIVE_INTERFACE_NAMES
    ):
        return None
    if capabilities.get("ready_for_mutation") is not True:
        return None
    if not all(callable(getattr(provider, name, None)) for name in _S06_NATIVE_INTERFACE_NAMES):
        return None
    return provider


def _s06_host_capabilities(hou: Any) -> dict[str, Any]:
    """Report the exact native interface status without probing scene state."""

    provider = getattr(hou, _S06_NATIVE_ADAPTER_ATTRIBUTE, None)
    available: list[str] = []
    if provider is not None:
        for name in _S06_NATIVE_INTERFACE_NAMES:
            if callable(getattr(provider, name, None)):
                available.append(name)
    missing = [name for name in _S06_NATIVE_INTERFACE_NAMES if name not in available]
    schema = _s06_provider_value(provider, "schema") if provider is not None else None
    provider_capabilities: dict[str, Any] | None = None
    provider_capabilities_error = None
    if provider is not None:
        provider_capabilities, provider_capabilities_error = _s06_provider_capabilities(provider)
    interface_capabilities = (
        provider_capabilities.get("interfaces")
        if isinstance(provider_capabilities, dict) and isinstance(provider_capabilities.get("interfaces"), dict)
        else {}
    )
    capability_statuses = {
        name: (
            dict(interface_capabilities[name])
            if isinstance(interface_capabilities.get(name), dict)
            else {"status": "unavailable", "reason": "capability record missing"}
        )
        for name in _S06_NATIVE_INTERFACE_NAMES
    }
    exact_provider = (
        schema == _S06_NATIVE_ADAPTER_SCHEMA
        and not missing
        and provider_capabilities_error is None
        and isinstance(provider_capabilities, dict)
        and provider_capabilities.get("provider_version") == "1.0"
        and provider_capabilities.get("houdini_build") == _SOLVER_SOURCING_BUILD
        and provider_capabilities.get("ready_for_mutation") is True
        and all(item.get("status") == "verified" for item in capability_statuses.values())
    )
    if exact_provider:
        status = "READY"
    elif provider is None:
        status = "UNIMPLEMENTED"
    elif schema != _S06_NATIVE_ADAPTER_SCHEMA or provider_capabilities_error in {
        "PROVIDER_CAPABILITIES_SCHEMA_INVALID",
        "PROVIDER_CAPABILITIES_INTERFACES_INVALID",
    }:
        status = "UNSUPPORTED"
    elif any(item.get("status") == "unimplemented" for item in capability_statuses.values()):
        status = "UNIMPLEMENTED"
    elif any(item.get("status") == "unsupported" for item in capability_statuses.values()):
        status = "UNSUPPORTED"
    else:
        status = "UNVERIFIED"
    unverified = [
        name for name, item in capability_statuses.items()
        if item.get("status") != "verified"
    ]
    try:
        supplement_hash = _fx_sha256_file(_S06_SUPPLEMENTARY_PROBE) if _S06_SUPPLEMENTARY_PROBE.is_file() else None
    except OSError:
        supplement_hash = None
    return {
        "schema": "bridge.f2.s06-host-capabilities/1.0",
        "status": status,
        "provider_attribute": _S06_NATIVE_ADAPTER_ATTRIBUTE,
        "provider_schema": schema if isinstance(schema, str) else None,
        "required_interfaces": list(_S06_NATIVE_INTERFACE_NAMES),
        "available_interfaces": available,
        "missing_interfaces": list(missing),
        "unverified_interfaces": unverified,
        "provider_capabilities": provider_capabilities,
        "provider_capabilities_error": provider_capabilities_error,
        "provider_load": dict(_S06_NATIVE_PROVIDER_LOAD),
        "pre_mutation_action": "ALLOW_S06_ADAPTER" if exact_provider else "BLOCK_BEFORE_NODE_CREATION",
        "supplementary_readonly_probe": {
            "path": str(_S06_SUPPLEMENTARY_PROBE),
            "sha256": supplement_hash,
            "entrypoint": "capture(hou)",
            "writes_scene": False,
            "cooks": False,
            "writes_cache": False,
            "renders": False,
        },
    }


def _s06_require_native_provider(hou: Any) -> Any:
    provider = _s06_native_provider(hou)
    if provider is None:
        capabilities = _s06_host_capabilities(hou)
        raise BridgeCommandError(
            "S06_HOST_CAPABILITY_UNAVAILABLE",
            "the exact versioned native S-06 host provider is unavailable",
            "Run the read-only supplementary probe and supply the missing native interfaces: {}".format(
                ",".join(capabilities["missing_interfaces"])
            ),
        )
    return provider


def _s06_field_snapshot(provider: Any, node: Any, field: str, *, stage: str, frame: int) -> tuple[dict[str, Any] | None, dict[str, Any] | None, str | None]:
    """Read a typed native snapshot and its freshness token; never synthesize one."""

    velocity = _s06_velocity_module()
    try:
        guard_factory = getattr(provider, "authorized_frame", None)
        guard = guard_factory(frame) if callable(guard_factory) else nullcontext()
        with guard:
            raw = provider.field_snapshot(node, field, stage, frame)
    except Exception as exc:
        code = getattr(exc, "code", None)
        return None, None, "FIELD_SNAPSHOT_UNAVAILABLE:{}".format(code or type(exc).__name__)
    if not isinstance(raw, dict) or not isinstance(raw.get("snapshot"), dict) or not isinstance(raw.get("freshness"), dict):
        return None, None, "FIELD_SNAPSHOT_UNAVAILABLE:NATIVE_SNAPSHOT_AND_FRESHNESS_REQUIRED"
    snapshot = raw["snapshot"]
    failures = velocity.validate_snapshot(snapshot)
    if failures or snapshot.get("field") != field:
        return None, None, "FIELD_SNAPSHOT_INVALID:" + ",".join(failures or ["FIELD_NAME_MISMATCH"])
    freshness = raw["freshness"]
    if (
        freshness.get("stage") != stage
        or freshness.get("frame") != frame
        or not isinstance(freshness.get("freshness_token"), str)
        or type(freshness.get("field_generation")) is not int
    ):
        return None, None, "FIELD_SNAPSHOT_INVALID:FRESHNESS_EVIDENCE_INVALID"
    return dict(snapshot), dict(freshness), None


def _s06_velocity_writer_inventory(provider: Any, root_node: Any, manifest: dict[str, Any]) -> dict[str, Any]:
    """Return a typed native writer inventory; absence remains unknown."""

    try:
        raw = provider.velocity_writer_inventory(root_node, dict(manifest))
    except Exception as exc:
        return {"status": "unknown", "complete": False, "other_writers": [], "reason": "WRITER_INVENTORY_ERROR:{}".format(type(exc).__name__)}
    if not isinstance(raw, dict) or raw.get("complete") is not True or not isinstance(raw.get("other_writers"), list):
        return {"status": "unknown", "complete": False, "other_writers": [], "reason": "WRITER_INVENTORY_INCOMPLETE"}
    # A fixed source-row/topology inventory is not proof that the solver's
    # internal dynamics writer set is exhaustive.  Never let the legacy
    # ``complete`` flag open source-effect isolation unless the provider
    # separately proves that stronger scope.
    if raw.get("field_writer_scope_complete") is not True:
        return {
            "status": "unknown",
            "complete": False,
            "other_writers": [],
            "scope": raw.get("scope", "task_owned_fixed_graph"),
            "reason": "WRITER_INTERNAL_SCOPE_UNVERIFIED",
            "detail": raw.get("scope_note") or "source rows/topology do not enumerate solver internal field writers",
        }
    if not all(isinstance(item, str) and item.strip() for item in raw["other_writers"]):
        return {"status": "unknown", "complete": False, "other_writers": [], "reason": "WRITER_INVENTORY_INVALID"}
    other = list(raw["other_writers"])
    return {
        "status": "pass" if not other else "unknown",
        "complete": True,
        "other_writers": other,
        "owned_writers": list(raw.get("owned_writers") or []) if isinstance(raw.get("owned_writers", []), list) else [],
        "reason": "NO_OTHER_VELOCITY_WRITERS" if not other else "OTHER_VELOCITY_WRITER_PRESENT",
    }


def _s06_apply_velocity_sentinel(provider: Any, root_node: Any, sentinel: dict[str, Any]) -> dict[str, Any]:
    """Ask the typed native provider to apply/read back the sentinel."""

    try:
        raw = provider.apply_velocity_sentinel(root_node, dict(sentinel))
    except Exception as exc:
        return {"status": "unknown", "applied": False, "readback_verified": False, "reason": "VELOCITY_SENTINEL_APPLY_ERROR:{}".format(type(exc).__name__)}
    if not isinstance(raw, dict) or raw.get("applied") is not True:
        return {"status": "unknown", "applied": False, "readback_verified": False, "reason": "VELOCITY_SENTINEL_APPLY_NOT_CONFIRMED"}
    readback = raw.get("readback")
    if not isinstance(readback, dict):
        return {"status": "unknown", "applied": True, "readback_verified": False, "reason": "VELOCITY_SENTINEL_READBACK_SAMPLE_MISSING"}
    velocity = _s06_velocity_module()
    failures = velocity.validate_snapshot(readback)
    if failures or readback.get("field") != "vel" or readback.get("digest_sha256") != sentinel.get("digest_sha256"):
        return {
            "status": "unknown", "applied": True, "readback_verified": False,
            "reason": "VELOCITY_SENTINEL_READBACK_MISMATCH", "readback_failures": failures,
        }
    return {
        "status": "pass", "applied": True, "readback_verified": True, "field": "vel",
        "digest_sha256": sentinel.get("digest_sha256"), "readback": dict(readback),
        "reason": "VELOCITY_SENTINEL_APPLIED_AND_READ_BACK",
    }


def _s06_observe_sourcing_boundary(provider: Any, solver: Any, source: Any, rows: list[dict[str, Any]], frame: int, request: dict[str, Any]) -> dict[str, Any]:
    """Delegate the actual source/cook/readback boundary to the native host."""

    try:
        guard_factory = getattr(provider, "authorized_frame", None)
        guard = guard_factory(frame) if callable(guard_factory) else nullcontext()
        with guard:
            raw = provider.observe_sourcing_boundary(solver, source, frame, [dict(row) for row in rows], dict(request))
    except Exception as exc:
        raise BridgeCommandError(
            "S06_SOURCING_BOUNDARY_UNAVAILABLE",
            "native sourcing boundary readback failed: {}".format(getattr(exc, "code", type(exc).__name__)),
        ) from exc
    if not isinstance(raw, dict):
        raise BridgeCommandError("S06_SOURCING_BOUNDARY_UNAVAILABLE", "native sourcing boundary returned no structured record")
    velocity = _s06_velocity_module()
    boundary = raw.get("sourcing_boundary")
    failures = velocity.validate_sourcing_boundary(boundary, frame=frame)
    if failures:
        raise BridgeCommandError(
            "S06_SOURCING_BOUNDARY_UNAVAILABLE",
            "native sourcing boundary lacks distinct pre/post freshness evidence",
            ",".join(failures),
        )
    before = raw.get("before_snapshot")
    after = raw.get("after_snapshot")
    if not isinstance(after, dict) or velocity.validate_snapshot(after):
        raise BridgeCommandError("S06_SOURCING_BOUNDARY_UNAVAILABLE", "native post-sourcing velocity snapshot is invalid")
    if before is not None and (not isinstance(before, dict) or velocity.validate_snapshot(before)):
        raise BridgeCommandError("S06_SOURCING_BOUNDARY_UNAVAILABLE", "native pre-sourcing velocity snapshot is invalid")
    return {
        "sourcing_boundary": dict(boundary),
        "before_snapshot": dict(before) if isinstance(before, dict) else None,
        "after_snapshot": dict(after),
        "cook_succeeded": raw.get("cook_succeeded") is True,
        "cook_errors": [str(value) for value in raw.get("cook_errors", [])] if isinstance(raw.get("cook_errors", []), list) else ["NATIVE_COOK_ERRORS_INVALID"],
        "output_nonempty": raw.get("output_nonempty") is True,
    }


def _s06_solver_rows(solver: Any) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for row in (1, 2):
        activation_parm = solver.parm("source_activate{}".format(row))
        source_parm = solver.parm("source_volume{}".format(row))
        target_parm = solver.parm("source_vfield{}".format(row))
        if activation_parm is None or source_parm is None or target_parm is None:
            raise BridgeCommandError("S06_SOURCE_BINDING_UNAVAILABLE", "solver sourcing row {} cannot be read back".format(row))
        try:
            active_value = activation_parm.eval()
            if type(active_value) is bool:
                active = active_value
            else:
                active = bool(int(active_value))
            source_volume = source_parm.eval()
            target_field = target_parm.eval()
        except Exception as exc:
            raise BridgeCommandError("S06_SOURCE_BINDING_UNAVAILABLE", "solver sourcing row {} could not be evaluated".format(row)) from exc
        if not isinstance(source_volume, str) or not isinstance(target_field, str):
            raise BridgeCommandError("S06_SOURCE_BINDING_UNAVAILABLE", "solver sourcing row {} returned non-text fields".format(row))
        rows.append({"row": row, "active": active, "source_volume": source_volume, "target_field": target_field})
    return rows


def _s06_observe_frame(params: dict[str, Any]) -> dict[str, Any]:
    """Cook and read one authorized frame, with structured inactive velocity evidence."""

    import hou

    request, root = _s06_validate_controller_request(params)
    frame = params.get("frame")
    if type(frame) is not int:
        raise BridgeCommandError("S06_FRAME_INVALID", "S-06 frame must be an integer")
    segment = request["frame_segment"]
    if frame < segment["start"] - segment["preroll_frames"] or frame > segment["end"]:
        raise BridgeCommandError("S06_FRAME_INVALID", "S-06 frame is outside the authorized frame segment")
    set_frame = getattr(hou, "setFrame", None)
    frame_getter = getattr(hou, "frame", None)
    if not callable(set_frame) or not callable(frame_getter):
        raise BridgeCommandError("S06_FRAME_CONTROL_UNAVAILABLE", "Houdini frame set/readback is unavailable")
    try:
        with _root_lease_fence(root, task_id=request["task_id"], scope="sop"):
            set_frame(frame)
            actual_frame = int(round(float(frame_getter())))
    except BridgeCommandError:
        raise
    except Exception as exc:
        raise BridgeCommandError("S06_FRAME_CONTROL_UNAVAILABLE", "Houdini frame set/readback failed") from exc
    if actual_frame != frame:
        raise BridgeCommandError("S06_FRAME_READBACK_MISMATCH", "Houdini frame readback differs from the authorized frame")

    solver_path = _s06_authorized_path(root, params.get("solver_path"), "solver_path")
    source_path = _s06_authorized_path(root, params.get("source_path"), "source_path")
    task_id = request["task_id"]
    manifest_root, manifest = _fx_manifest(task_id, required=True, root_path=root)
    if manifest_root is None or not isinstance(manifest.get("nodes"), dict):
        raise BridgeCommandError("S06_SCENE_STATE_MISSING", "S-06 task manifest is unavailable")
    nodes = manifest["nodes"]
    if manifest.get("task_id") != task_id or manifest.get("execution_root") != root or manifest.get("domain_pack") != "pyro_smoke_v1":
        raise BridgeCommandError("S06_SCENE_SCOPE_INVALID", "S-06 task manifest identity is not bound to the controller request")
    if nodes.get("solver") != solver_path or nodes.get("source_volume") != source_path:
        raise BridgeCommandError("S06_SCENE_SCOPE_INVALID", "S-06 observation endpoints differ from the task manifest")
    solver = hou.node(solver_path)
    source = hou.node(source_path)
    if solver is None or source is None:
        raise BridgeCommandError("S06_SCENE_STATE_MISSING", "S-06 solver/source node is missing")
    rows = _s06_solver_rows(solver)
    if rows[0]["source_volume"] != "density" or rows[0]["target_field"] != "density" or rows[1]["source_volume"] != "v" or rows[1]["target_field"] != "vel":
        raise BridgeCommandError("S06_SOURCE_BINDING_MISMATCH", "S-06 requires density->density and v->vel source rows")

    source_fields: list[str]
    target_fields: list[str]
    try:
        source_fields = _bridge_volume_names(source)
    except Exception:
        source_fields = []
    try:
        target_fields = _bridge_volume_names(solver)
    except Exception:
        target_fields = []

    provider = _s06_require_native_provider(hou)
    inactive = not rows[1]["active"]
    try:
        with _root_lease_fence(root, task_id=request["task_id"], scope="sop"):
            boundary_data = _s06_observe_sourcing_boundary(provider, solver, source, rows, frame, request)
    except BridgeCommandError:
        raise
    before_snapshot = boundary_data["before_snapshot"] if inactive else None
    after_snapshot = boundary_data["after_snapshot"]
    before_reason = None if before_snapshot is not None else "NATIVE_PRE_SOURCING_READBACK_UNAVAILABLE"
    after_reason = None
    try:
        source_fields = _bridge_volume_names(source)
    except Exception:
        pass
    try:
        target_fields = _bridge_volume_names(solver)
    except Exception:
        pass
    output_nonempty = boundary_data["output_nonempty"]

    sentinel_state = (manifest.get("s06_adapter") or {}).get("velocity_sentinel")
    if not isinstance(sentinel_state, dict):
        sentinel_state = {"status": "unknown", "reason": "VELOCITY_SENTINEL_STATE_NOT_PERSISTED"}
    inventory = _s06_velocity_writer_inventory(provider, manifest_root, manifest)
    sentinel_readback = sentinel_state.get("readback")
    sentinel_failures = _s06_velocity_module().validate_snapshot(sentinel_readback)
    source_effect_isolated = (
        sentinel_state.get("status") == "pass"
        and sentinel_state.get("readback_verified") is True
        and not sentinel_failures
        and sentinel_readback.get("digest_sha256") == request["velocity_sentinel"].get("digest_sha256")
    ) if isinstance(sentinel_readback, dict) else False
    no_other_writers = inventory.get("status") == "pass"
    velocity = _s06_velocity_module()
    if rows[1]["active"]:
        evidence = velocity.not_applicable(frame=frame, reason="ACTIVE_SOURCE_ROW")
    else:
        evidence = velocity.compare_inactive_velocity(
            before_snapshot,
            after_snapshot,
            frame=frame,
            before_frame=frame if before_snapshot is not None else None,
            after_frame=frame if after_snapshot is not None else None,
            row2_active_before=False,
            row2_active_after=False,
            source_effect_isolated=source_effect_isolated,
            no_other_velocity_writers=no_other_writers,
            sourcing_boundary=boundary_data["sourcing_boundary"],
        )
    return {
        "actual_frame": actual_frame,
        "solver_path": solver_path,
        "execution_root": root,
        "source_fields": source_fields,
        "target_fields": target_fields,
        "active_source_windows": rows,
        "velocity_preservation": evidence,
        "velocity_field_readback": {
            "field": "vel",
            "before_snapshot": before_snapshot,
            "after_snapshot": after_snapshot,
            "before_reason": before_reason,
            "after_reason": after_reason,
            # Retained as a compatibility field; the validator uses the
            # explicit native sourcing boundary below as authority.
            "same_stop_frame": {"before_frame": frame if before_snapshot is not None else None, "after_frame": frame},
            "sourcing_boundary": boundary_data["sourcing_boundary"],
            "sentinel": sentinel_state,
            "writer_inventory": inventory,
        },
        # Kept only for consumers of the old observation shape.  The validator
        # deliberately ignores it and uses velocity_preservation above.
        "inactive_velocity_preserved": False,
        "output_nonempty": output_nonempty,
        "cook_succeeded": boundary_data["cook_succeeded"],
        "cook_errors": boundary_data["cook_errors"],
        "probe_kind": "live_native_provider_structured_readback",
        "smoke_capability_proven": False,
    }


def _s06_validate_source_plan_schedule(params: dict[str, Any], pack_id: str, pack: dict[str, Any], request: dict[str, Any]) -> None:
    """Preflight that the typed source plan and the issued pulse schedule agree."""

    binding = _fx_source_plan_host_patch(params, pack_id, pack)
    if not isinstance(binding, dict):
        raise BridgeCommandError("S06_SOURCE_PLAN_REQUIRED", "S-06 source plan did not produce a host binding")
    guards = binding.get("guards")
    schedule = request.get("source_schedule")
    planned = guards.get("pulse_intervals_half_open") if isinstance(guards, dict) else None
    issued = schedule.get("rows", {}).get("1") if isinstance(schedule, dict) else None
    normalized_planned = [list(item) for item in planned] if isinstance(planned, list) else None
    normalized_issued = [[item.get("start"), item.get("end")] for item in issued] if isinstance(issued, list) and all(isinstance(item, dict) for item in issued) else None
    if normalized_planned != normalized_issued:
        raise BridgeCommandError(
            "S06_SOURCE_SCHEDULE_MISMATCH",
            "typed source plan pulse intervals differ from the controller-issued schedule",
            "Reissue the operation with pulses derived from the same source plan; do not infer a new window.",
        )


def _s06_file_evidence(path: Path | None) -> dict[str, Any]:
    """Collect only read-only lstat/hash evidence for one HIP path."""

    result: dict[str, Any] = {
        "schema": "bridge.f2.s06-file-evidence/1.0",
        "path": str(path) if path is not None else "",
        "is_regular_file": False,
        "is_symlink": False,
        "parent_symlink": False,
        "uid": None,
        "gid": None,
        "mode": None,
        "device": None,
        "inode": None,
        "size": None,
        "mtime_ns": None,
        "sha256": None,
    }
    if path is None:
        return result
    try:
        info = path.lstat()
        result.update({
            "is_regular_file": stat.S_ISREG(info.st_mode),
            "is_symlink": stat.S_ISLNK(info.st_mode),
            "uid": int(info.st_uid),
            "gid": int(info.st_gid),
            "mode": int(stat.S_IMODE(info.st_mode)),
            "device": int(info.st_dev),
            "inode": int(info.st_ino),
            "size": int(info.st_size),
            "mtime_ns": int(info.st_mtime_ns),
        })
        for parent in path.parents:
            try:
                if stat.S_ISLNK(parent.lstat().st_mode):
                    result["parent_symlink"] = True
                    break
            except OSError:
                result["parent_symlink"] = True
                break
        if result["is_regular_file"] and not result["is_symlink"] and not result["parent_symlink"]:
            result["sha256"] = _fx_sha256_file(path)
    except OSError:
        pass
    return result


def _s06_graph_paths(hou: Any, root_path: str) -> list[str]:
    root = hou.node(root_path) if isinstance(root_path, str) and root_path else None
    if root is None:
        return []
    paths = [root_path]
    children = getattr(root, "allSubChildren", None)
    if callable(children):
        try:
            paths.extend(str(item.path()) for item in children() if callable(getattr(item, "path", None)))
        except Exception:
            return paths
    return sorted(set(paths))


def _s06_ownership_evidence(
    hou: Any,
    identity: Mapping[str, Any],
    file_evidence: Mapping[str, Any],
    children: list[str],
    params: Mapping[str, Any] | None,
) -> tuple[bool, bool, list[str], list[str], dict[str, Any]]:
    """Derive ownership only from a controller record plus fresh readbacks."""

    record = params.get("ownership_record") if isinstance(params, Mapping) else None
    if record is None:
        return (
            False,
            False,
            [],
            list(children),
            {
                "schema": _S06_SCENE_OWNERSHIP_EVIDENCE_SCHEMA,
                "record_status": "ABSENT",
                "controller_record_supplied": False,
                "identity_match": False,
                "hip_file_match": False,
                "graph_match": False,
                "freshness_basis": "unregistered_read_only_probe",
            },
        )
    valid = False
    try:
        valid = _s06_contracts_module().scene_ownership_record_valid(record)
    except Exception:
        valid = False
    if not valid:
        return False, False, [], list(children), {
            "schema": _S06_SCENE_OWNERSHIP_EVIDENCE_SCHEMA,
            "record_status": "INVALID",
            "controller_record_supplied": True,
            "identity_match": False,
            "hip_file_match": False,
            "graph_match": False,
            "freshness_basis": "record_hash_or_schema_invalid",
        }
    expected_identity = record.get("scene_identity")
    identity_match = isinstance(expected_identity, Mapping) and all(
        identity.get(key) == expected_identity.get(key)
        for key in ("session_id", "process_generation", "scene_id", "hip_path")
    )
    expected_file = record.get("hip_file_evidence")
    hip_file_match = isinstance(expected_file, Mapping) and dict(expected_file) == dict(file_evidence)
    phase = record.get("phase")
    root_path = record.get("graph_root")
    actual_graph = _s06_graph_paths(hou, root_path) if isinstance(root_path, str) else []
    expected_nodes = record.get("task_owned_nodes")
    if not isinstance(expected_nodes, list) or not all(isinstance(item, str) for item in expected_nodes):
        expected_nodes = []
    if phase == "PREPARED":
        graph_match = not actual_graph and not expected_nodes
    elif phase == "GRAPH_MUTATION_COMPLETED":
        graph_match = bool(actual_graph) and set(actual_graph) == set(expected_nodes)
    else:
        graph_match = False
    owned = bool(identity_match and hip_file_match and graph_match)
    task_manifest_ids = list(record.get("task_manifest_ids") or []) if isinstance(record.get("task_manifest_ids"), list) else []
    conflicts = list(children) if phase == "PREPARED" else [item for item in children if item != root_path]
    fresh = bool(owned and phase == "PREPARED" and not conflicts)
    return owned, fresh, task_manifest_ids, conflicts, {
        "schema": _S06_SCENE_OWNERSHIP_EVIDENCE_SCHEMA,
        "record_status": "MATCHED" if owned else "MISMATCHED",
        "controller_record_supplied": True,
        "record_hash": record.get("record_hash"),
        "record_phase": phase,
        "identity_match": identity_match,
        "hip_file_match": hip_file_match,
        "graph_match": graph_match,
        "actual_graph_paths": actual_graph,
        "expected_task_owned_nodes": list(expected_nodes),
        "freshness_basis": "controller_record_and_current_read_only_evidence",
    }


def bridge_s06_inspect_scene(params: dict[str, Any] | None = None) -> dict[str, Any]:
    """Read-only probe; ownership is derived only when a record verifies."""

    import hou

    version_getter = getattr(hou, "applicationVersionString", None)
    version = str(version_getter()) if callable(version_getter) else ""
    identity: dict[str, Any] = {}
    identity_error = None
    try:
        identity = dict(bridge_scene_identity())
    except BridgeCommandError as exc:
        identity_error = {"code": exc.code, "message": str(exc)}
    except Exception as exc:
        identity_error = {"code": "SCENE_IDENTITY_UNAVAILABLE", "message": type(exc).__name__}
    hip_path = str(identity.get("hip_path") or "")
    if not hip_path:
        try:
            hip_path = str(hou.hipFile.path() or "")
        except Exception:
            hip_path = ""
    hip_file = Path(hip_path).expanduser() if hip_path else None
    file_evidence = _s06_file_evidence(hip_file)
    saved = bool(file_evidence.get("is_regular_file") and not file_evidence.get("is_symlink") and not file_evidence.get("parent_symlink"))
    hip_sha256 = file_evidence.get("sha256") if saved else None
    try:
        has_unsaved_changes = bool(hou.hipFile.hasUnsavedChanges())
    except Exception:
        has_unsaved_changes = None
    obj = hou.node("/obj")
    children: list[str] = []
    if obj is not None:
        try:
            children = sorted(str(child.path()) for child in obj.children())
        except Exception:
            children = []
    owned, fresh, task_manifest_ids, conflicts, ownership_evidence = _s06_ownership_evidence(
        hou, identity, file_evidence, children, params,
    )
    return {
        "state": "SCENE_PROBE",
        "houdini_version": version,
        "route": {
            "reachable": True,
            "main_thread": True,
            "adapter": "bridge.s06.short_segment",
            "raw_code_allowed": "code.exec_python" in _production_allowed_commands(),
        },
        "scene_identity": identity,
        "identity_error": identity_error,
        "saved": saved,
        "has_unsaved_changes": has_unsaved_changes,
        "hip_sha256": hip_sha256,
        "file_evidence": file_evidence,
        "children": children,
        "conflicting_nodes": conflicts,
        "task_manifest_ids": task_manifest_ids,
        "owned_project": owned,
        "fresh_project": fresh,
        "read_only_capture_session": False,
        "ownership_evidence": ownership_evidence,
        "host_capabilities": _s06_host_capabilities(hou),
        "host_calls": 0,
        "simulation_cache_written": False,
        "render_started": False,
        "smoke_capability_proven": False,
    }


def bridge_s06_short_segment_adapter(params: dict[str, Any]) -> dict[str, Any]:
    """Dedicated S-06 adapter: build or observe, with no generic FX fallback."""

    import hou

    # Capability is checked before any pack resolution or graph construction.
    # The old per-node bridge_* test hooks are not a production substitute.
    native_provider = _s06_require_native_provider(hou)
    request, root = _s06_validate_controller_request(params)
    action = params.get("s06_action")
    if action not in {"build", "observe"}:
        raise BridgeCommandError("S06_ACTION_INVALID", "S-06 adapter action must be build or observe")
    pack_id, pack = _fx_pack(params)
    if pack_id != "pyro_smoke_v1":
        raise BridgeCommandError("S06_DOMAIN_INVALID", "S-06 adapter is registered only for pyro_smoke_v1")
    if not isinstance(_fx_configuration(params).get("source_plan"), dict):
        raise BridgeCommandError("S06_SOURCE_PLAN_REQUIRED", "S-06 requires the typed controller source plan")
    if action == "observe":
        return _s06_observe_frame(params)

    _s06_validate_source_plan_schedule(params, pack_id, pack, request)
    built = _fx_build_preview(params, pack_id, pack)
    manifest = built.get("scene_manifest") if isinstance(built, dict) else None
    if not isinstance(manifest, dict) or manifest.get("execution_root") != root or manifest.get("task_id") != request["task_id"]:
        raise BridgeCommandError("S06_SCENE_SCOPE_INVALID", "S-06 build returned an unbound task manifest")
    root_node = hou.node(root)
    if root_node is None:
        raise BridgeCommandError("S06_SCENE_STATE_MISSING", "S-06 graph root disappeared after build")
    sentinel_state = _s06_apply_velocity_sentinel(native_provider, root_node, request["velocity_sentinel"])
    manifest["s06_adapter"] = {
        "schema": "bridge.f2.s06-main-thread-adapter/1.0",
        "task_id": request["task_id"],
        "operation_id": request["operation_id"],
        "request_id": request["request_id"],
        "controller_request_hash": params.get("s06_controller_request_hash"),
        "first_graph_mutation": "completed",
        "velocity_sentinel": sentinel_state,
        "simulation_cache_written": False,
        "render_started": False,
    }
    _fx_store_manifest(root_node, manifest)
    return {
        **dict(built),
        "adapter": _S06_ADAPTER_SCHEMA,
        "s06_action": "build",
        "first_graph_mutation": "completed",
        "velocity_sentinel": sentinel_state,
        "simulation_cache_written": False,
        "render_started": False,
        "smoke_capability_proven": False,
        "scene_manifest": manifest,
    }


def _assert_bridge_execution_binding(params: dict[str, Any]) -> None:
    binding = params.get("bridge_execution_binding")
    if binding is None:
        return
    if not isinstance(binding, dict) or binding.get("schema") != _S06_HOST_BINDING_SCHEMA:
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "short-segment host binding is invalid")
    root = binding.get("execution_root")
    if not isinstance(root, str) or not re.fullmatch(r"/obj/BRIDGE_GRAPH_[0-9a-f]{64}", root):
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "short-segment root is not a generated Bridge graph root")
    if params.get("bridge_graph_root") != root:
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "short-segment root binding differs from the host command")
    expected = binding.get("host_identity")
    actual = bridge_scene_identity()
    if not isinstance(expected, dict) or any(actual.get(key) != expected.get(key)
                                              for key in ("session_id", "process_generation", "scene_id", "hip_path")):
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "live Houdini session/scene identity differs from the lease")


def _bridge_volume_names(node: Any) -> list[str]:
    geometry = node.geometry()
    names: set[str] = set()
    for primitive in geometry.prims():
        for getter_name in ("intrinsicValue", "stringAttribValue", "attribValue"):
            getter = getattr(primitive, getter_name, None)
            if not callable(getter):
                continue
            try:
                value = getter("name")
            except Exception:
                continue
            if isinstance(value, str) and value:
                names.add(value)
                break
    for attribute in geometry.pointAttribs():
        try:
            names.add(str(attribute.name()))
        except Exception:
            continue
    return sorted(names)


def bridge_short_segment_observation(
    solver_path: str,
    frame: int,
    source_path: str = "",
    execution_root: str = "",
) -> dict[str, Any]:
    """Read one cooked frame without creating a cache or rendering output."""
    import hou
    if not isinstance(execution_root, str) or not re.fullmatch(r"/obj/BRIDGE_GRAPH_[0-9a-f]{64}", execution_root):
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "observation root is not authorized")
    if not isinstance(solver_path, str) or not solver_path.startswith(execution_root + "/"):
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "solver observation is outside the leased root")
    solver = hou.node(solver_path)
    source = hou.node(source_path) if isinstance(source_path, str) and source_path.startswith(execution_root + "/") else None
    if solver is None or source is None:
        raise BridgeCommandError("SCENE_STATE_MISSING", "solver/source output cannot be observed inside the leased root")
    cook_errors: list[str] = []
    try:
        cook_errors.extend(str(value) for value in solver.errors())
    except Exception as exc:
        cook_errors.append("solver errors unavailable: {}".format(exc))
    try:
        source_fields = _bridge_volume_names(source)
    except Exception:
        source_fields = []
    try:
        target_fields = _bridge_volume_names(solver)
    except Exception:
        target_fields = []
    windows: list[dict[str, Any]] = []
    for row in (1, 2):
        activation_parm = solver.parm("source_activate{}".format(row))
        source_parm = solver.parm("source_volume{}".format(row))
        target_parm = solver.parm("source_vfield{}".format(row))
        if activation_parm is None or source_parm is None or target_parm is None:
            raise BridgeCommandError("SCENE_STATE_MISSING", "solver sourcing row {} cannot be read".format(row))
        try:
            active = bool(int(activation_parm.eval()))
            source_volume = str(source_parm.eval())
            target_field = str(target_parm.eval())
        except Exception as exc:
            raise BridgeCommandError("SCENE_STATE_MISSING", "solver sourcing row {} cannot be evaluated".format(row)) from exc
        windows.append({"row": row, "active": active, "source_volume": source_volume, "target_field": target_field})
    try:
        output_nonempty = bool(len(solver.geometry().prims()) or len(solver.geometry().points()))
    except Exception:
        output_nonempty = False
    # A single frame cannot prove that an inactive velocity row preserved an
    # earlier nonzero field.  The live probe therefore remains conservative;
    # the validator reports this as inconclusive rather than smoke success.
    inactive_velocity_preserved = False
    return {
        "actual_frame": int(round(float(hou.frame()))),
        "solver_path": solver_path,
        "execution_root": execution_root,
        "source_fields": source_fields,
        "target_fields": target_fields,
        "active_source_windows": windows,
        "inactive_velocity_preserved": inactive_velocity_preserved,
        "output_nonempty": output_nonempty,
        "cook_succeeded": not cook_errors,
        "cook_errors": cook_errors,
        "probe_kind": "live_host_readback_only",
        "smoke_capability_proven": False,
    }


# Private in-process worker identity. No new HTTP/MCP command is added.
_GRAPH_WORKER_SESSION = uuid4().hex
_GRAPH_WORKER_PROCESS = "{}:{}".format(os.getpid(), uuid4().hex)
_GRAPH_WORKER_SCENE_EPOCH = 0
_GRAPH_WORKER_SCENE_EVENTS = []
_GRAPH_WORKER_CALLBACK_INSTALLED = False


def _graph_worker_scene_event(event_type, **_kwargs):
    import hou
    global _GRAPH_WORKER_SCENE_EPOCH
    if _fx_scene_event_increments_epoch("producer", event_type):
        _GRAPH_WORKER_SCENE_EPOCH += 1
    _GRAPH_WORKER_SCENE_EVENTS.append({"event": str(event_type)[:80], "epoch": _GRAPH_WORKER_SCENE_EPOCH})
    del _GRAPH_WORKER_SCENE_EVENTS[:-8]


def graph_worker_identity():
    """Fresh private host identity; missing event support fails closed.

    Official event API: sidefx.com/docs/houdini/hom/hou/hipFile.html.
    Presence in the API documentation is not a tested host-version claim.
    """
    import hou
    global _GRAPH_WORKER_CALLBACK_INSTALLED
    if hou.isUIAvailable():
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "fresh headless graph worker required")
    if _GRAPH_WORKER_CALLBACK_INSTALLED:
        if _graph_worker_scene_event not in hou.hipFile.eventCallbacks():
            raise BridgeCommandError("SCENE_STATE_DRIFT", "worker scene identity callback was removed")
    else:
        # Resolve these before registration; unsupported host APIs must not
        # silently return a made-up identity.
        _ = (hou.hipFileEventType.BeforeClear, hou.hipFileEventType.BeforeLoad,
             hou.hipFileEventType.BeforeMerge)
        hou.hipFile.addEventCallback(_graph_worker_scene_event)
        _GRAPH_WORKER_CALLBACK_INSTALLED = True
        if _graph_worker_scene_event not in hou.hipFile.eventCallbacks():
            raise BridgeCommandError("SCENE_STATE_DRIFT", "worker scene callback registration was not retained")
    hip_path = str(Path(hou.hipFile.path()).resolve())
    scene_id = hashlib.sha256(json.dumps([hip_path, _GRAPH_WORKER_SCENE_EPOCH]).encode()).hexdigest()
    return {"session_id": _GRAPH_WORKER_SESSION, "process_generation": "{}:{}".format(os.getpid(), _GRAPH_WORKER_PROCESS),
            "scene_id": scene_id, "hip_path": hip_path}


def dispatch(command: str, params: dict[str, Any]) -> dict[str, Any]:
    from houdini_bridge.operation_receipts import COMMAND_KINDS

    command = {"scene_info": "scene.info"}.get(command, command)
    if "inspect_policy" in params:
        from houdini_bridge.operation_receipts import CHILDREN_INSPECT_POLICY
        if (command != "node.children" or params["inspect_policy"] != CHILDREN_INSPECT_POLICY
                or not (params.get("operation_id") or params.get("request_id"))):
            raise BridgeCommandError("INVALID_ARGUMENT", "children inspect policy requires an exact typed node.children query")
        return _fx_producer_query_dispatch(command, params)
    if command in COMMAND_KINDS and (params.get("operation_id") or params.get("request_id")):
        return _fx_producer_dispatch(command, params)
    return _dispatch_command(command, params)


def _dispatch_command(command: str, params: dict[str, Any], *, _scene_save_fenced=False) -> dict[str, Any]:
    """Execute supported structured commands on Houdini's main thread."""
    import hou

    aliases = {"health": "ping", "scene_info": "scene.info", "node_create": "node.create", "node_create_batch": "node.create_batch", "viewport_screenshot": "viewport.screenshot", "exec_python": "code.exec_python"}
    command = aliases.get(command, command)
    if command in _TRUSTED_CONTROL_COMMANDS:
        return _fx_control_dispatch(command, params)
    if command == "scene.create_task_root":
        return _scene_create_task_root(params)
    if command in _MUTATION_COMMANDS:
        _guard_bridge_mutation_targets(params)
    if command == "bridge.s06.inspect_scene":
        return bridge_s06_inspect_scene(params)
    if command == "bridge.s06.short_segment":
        return bridge_s06_short_segment_adapter(params)
    if command.startswith("agent.model."):
        task_id = str(params.get("task_id") or "")
        scene_before = _assert_scene_action_precondition(params, task_id)
        result = _model_action(command, params)
        if task_id:
            scene_after = _bridge_scene_fingerprints(task_id, params.get("inputs"))
            _assert_scene_action_postcondition(command, scene_before, scene_after)
            result = {
                **result,
                "bridge_scene_fingerprints": scene_after,
            }
        return result
    if command == "scene.reopen_task_hip":
        return scene_reopen_task_hip(params)
    if command == "scene.reconcile_transition":
        return _fx_scene_transition_reconcile(params)
    if command in ("operation.status", "operation.cancel", "render.start", "render.status", "render.cancel", "render.verify"):
        result = _fx_operation_dispatch(command, params)
        if result is not None:
            return result
    if command.startswith("agent.fx."):
        task_id = str(params.get("task_id") or "")
        if command == "agent.fx.build_preview" and params.get("bridge_execution_binding") is not None:
            raise BridgeCommandError(
                "S06_ADAPTER_REQUIRED",
                "controller-bound S-06 builds must use bridge.s06.short_segment",
            )
        scene_before = _assert_scene_action_precondition(params, task_id)
        result = _fx_action(command, params)
        if task_id:
            scene_after = _bridge_scene_fingerprints(task_id, params.get("inputs"))
            _assert_scene_action_postcondition(command, scene_before, scene_after)
            result = {
                **result,
                "bridge_scene_fingerprints": scene_after,
            }
        return result
    if command == "ping":
        return {"pid": os.getpid(), "port": _SERVER.port if _SERVER else None, "houdini_version": hou.applicationVersionString(), "python_version": "{}.{}.{}".format(*sys.version_info[:3]), "edition": hou.licenseCategory().name(), "hip_path": hou.hipFile.path(), "gui": bool(hou.isUIAvailable()),
                "task_host_identity": {**globals().get("_TASK_HOST_IDENTITY", {}),
                                       "scene_epoch": _host_identity()["scene_epoch"]}}
    if command == "scene.info":
        root = hou.node("/")
        hip_path = str(hou.hipFile.path() or "")
        hip_file = Path(hip_path).expanduser()
        hip_sha256 = _fx_sha256_file(hip_file) if hip_file.is_file() else None
        task_id = str(params.get("task_id") or "")
        scene_fingerprints = _bridge_scene_fingerprints(
            task_id, params.get("inputs")
        )
        return {
            "hip_path": hip_path,
            "hip_sha256": hip_sha256,
            "has_unsaved_changes": bool(hou.hipFile.hasUnsavedChanges()),
            "fps": hou.fps(),
            "frame": hou.frame(),
            "children": [child.path() for child in root.children()],
            "houdini_version": hou.applicationVersionString(),
            **scene_fingerprints,
        }
    if command == "scene.reopen_owned_hip":
        # Private worker operation: deliberately absent from HTTP allowlists.
        # hasUnsavedChanges() always returns True in hython; require the exact
        # just-saved scene inside the worker's private directory instead.
        raw = Path(str(params.get("path") or "")).expanduser()
        task_id = str(params.get("task_id") or "")
        pref = hou.getenv("HOUDINI_USER_PREF_DIR") or ""
        expected = str(params.get("sha256") or "").strip().lower()
        if hou.isUIAvailable() or not pref or Path(pref).parent.name != "houdini-user-pref" or not Path(pref).is_dir():
            raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "owned headless worker required")
        path = raw.resolve()
        if (raw.is_symlink() or not path.is_file() or path.suffix.lower() not in {".hip", ".hiplc", ".hipnc"}
                or path.parent != Path(pref).resolve().parent.parent
                or Path(hou.hipFile.path()).resolve() != path
                or len(expected) != 64 or any(c not in "0123456789abcdef" for c in expected)):
            raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "exact owned saved HIP and hash required")
        if not hmac.compare_digest(hashlib.sha256(path.read_bytes()).hexdigest(), expected):
            raise BridgeCommandError("ARTIFACT_INVALID", "owned HIP hash changed")
        transition = _fx_scene_transition_begin(params, "scene.reopen_owned_hip", path, expected)
        replay = _fx_scene_transition_replay(transition)
        if replay is not None:
            return replay
        completion = {}
        def complete_owned_reopen(root_rebind):
            if Path(hou.hipFile.path()).resolve() != path or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
                raise BridgeCommandError("SCENE_STATE_DRIFT", "owned HIP changed during reopening")
            result = {"path": str(path), "sha256": expected, "owned_headless_reopen": True,
                      "has_unsaved_changes": None, "dirty_detection_available": False}
            if root_rebind is not None:
                result["root_lease_rebind"] = root_rebind
            if transition is not None:
                result["scene_transition"] = _fx_scene_transition_complete(
                    task_id, str(transition.get("operation_id") or ""), result)
            return result
        if params.get("root_path"):
            return _fx_reopen_owned_root(params, path, expected, complete=complete_owned_reopen,
                                         transition=transition, completion=completion)
        hou.hipFile.load(str(path), suppress_save_prompt=True, ignore_load_warnings=False)
        return complete_owned_reopen(None)
    if command == "scene.open_hip":
        path = Path(str(params.get("path") or "")).expanduser().resolve()
        if not path.is_file() or path.suffix.lower() not in {".hip", ".hiplc", ".hipnc"}:
            raise BridgeCommandError("ARTIFACT_MISSING", "target HIP does not exist or has an unsupported suffix: {}".format(path))
        expected = str(params.get("sha256") or "").strip().lower()
        actual = _fx_sha256_file(path)
        if expected:
            if not hmac.compare_digest(actual, expected):
                raise BridgeCommandError("ARTIFACT_INVALID", "target HIP hash does not match its frozen manifest")
        try:
            dirty_before = hou.hipFile.hasUnsavedChanges()
        except Exception as exc:
            raise BridgeCommandError(
                "SCENE_STATE_DRIFT",
                "could not determine whether the current Houdini scene is clean",
                "AWAITING_INPUT: inspect and explicitly save/discard the current scene.",
            ) from exc
        if dirty_before is not False:
            current = Path(hou.hipFile.path()).expanduser().resolve()
            code = "SCENE_STATE_DRIFT" if current == path and expected else "SCENE_DIRTY"
            raise BridgeCommandError(
                code,
                "refusing to replace a Houdini scene with unsaved changes",
                "AWAITING_INPUT: save, discard, or move the unsaved edits explicitly before retrying.",
            )
        transition = _fx_scene_transition_begin(params, "scene.open_hip", path, expected or actual)
        replay = _fx_scene_transition_replay(transition)
        if replay is not None:
            return replay
        hou.hipFile.load(str(path), suppress_save_prompt=True, ignore_load_warnings=False)
        reopened = Path(hou.hipFile.path()).expanduser().resolve()
        reopened_sha256 = _fx_sha256_file(reopened) if reopened.is_file() else None
        dirty_after = bool(hou.hipFile.hasUnsavedChanges())
        if reopened != path or dirty_after or (expected and reopened_sha256 != expected):
            raise BridgeCommandError(
                "SCENE_STATE_DRIFT",
                "Houdini did not retain the exact clean frozen scene after opening it",
                "AWAITING_INPUT: inspect the target HIP and retry from a clean scene.",
            )
        result = {
            "path": hou.hipFile.path(),
            "sha256": reopened_sha256,
            "has_unsaved_changes": dirty_after,
        }
        if transition is not None:
            result["scene_transition"] = _fx_scene_transition_complete(
                str(params.get("task_id") or ""), str(transition.get("operation_id") or ""), result)
        return result
    if command == "scene.save_hip":
        path = params.get("path")
        task_id = str(params.get("task_id") or "")
        fence = _task_scene_lease_fence(task_id, params) if task_id and not _scene_save_fenced else nullcontext()
        with fence:
            with _undo("Houdini Bridge save scene"):
                if path:
                    hou.hipFile.save(str(path))
                else:
                    hou.hipFile.save()
            saved_path = hou.hipFile.path()
            receipt = {"path": saved_path, "sha256": _fx_sha256_file(Path(saved_path)) if Path(saved_path).is_file() else None,
                       "saved_at": datetime.now(timezone.utc).isoformat(),
                       "process_generation": (_FX_OPERATIONS.generation if _FX_OPERATIONS is not None else None),
                       "houdini_version": hou.applicationVersionString()}
            if task_id:
                structure = {}
                root, manifest = _fx_manifest(task_id, required=False)
                for role, node_path in (manifest.get("nodes") or {}).items():
                    node = hou.node(str(node_path))
                    if node is not None:
                        structure[str(node_path)] = node.type().nameWithCategory()
                receipt["structure"] = structure
                scene_contract = _fx_capture_scene_contract(task_id)
                if scene_contract is None and params.get("operation_id"):
                    scene_contract = _fx_native_command_scene_contract(task_id, params)
                if scene_contract is not None:
                    receipt["scene_contract"] = scene_contract
                    receipt["scene_contract_sha256"] = _fx_scene_contract_digest(scene_contract)
                _fx_record_task_save(task_id, receipt)
            return receipt
    if command in {"node.children", "node.subtree"}:
        node = _node(str(params.get("path")))
        children = node.children() if command == "node.children" else node.allSubChildren()
        return {"path": node.path(), "nodes": [{"path": item.path(), "type": item.type().name(), "name": item.name()} for item in children]}
    if command == "node.info":
        node = _node(str(params.get("path")))
        result = {"path": node.path(), "type": node.type().nameWithCategory(), "errors": list(node.errors()), "warnings": list(node.warnings()),
                "inputs": [item.path() if item is not None else None for item in node.inputs()],
                "input_connections":[{"input_index":wire.inputIndex(),"source":wire.inputNode().path(),"output_index":wire.outputIndex()} for wire in node.inputConnections()]}
        if params.get('native_port_names') is True:
            result.update(input_names=list(node.inputNames()),output_names=list(node.outputNames()))
        if params.get('geometry_observation') is True:
            from houdini_bridge.geometry_render_scene import observe_geometry
            task_id = str(params.get('task_id') or '')
            root, manifest = _fx_manifest(task_id)
            if ((manifest.get('frozen_render_scene') or {}).get('profile') != 'bounded_geometry_rig_v1'
                    or (manifest.get('nodes') or {}).get('source') != node.path()):
                raise BridgeCommandError('GEOMETRY_OBSERVATION_SOURCE_REQUIRED', 'query requires current owned geometry output')
            _root_lease_check(root.path(),task_id=task_id,scope='sop')
            result['geometry_observation'] = observe_geometry(hou,manifest['nodes'])
        return result
    if command == "node.parms":
        node = _node(str(params.get("path")))
        if "names" in params:
            names = params["names"]
            if (not isinstance(names, list) or not names or len(names) > 64
                    or any(not isinstance(name, str) or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,99}", name) for name in names)
                    or len(names) != len(set(names))):
                raise BridgeCommandError("INVALID_ARGUMENT", "parameter names must be a bounded unique list")
            selected = [_resolve_parm_target(node, [name]) for name in names]
            if any(parm is None for parm in selected):
                raise BridgeCommandError("UNSUPPORTED_PARAMETER", "requested native parameter is unavailable")
            return {"path": node.path(), "parms": {name: _json_safe(parm.eval()) for name, parm in zip(names, selected)}}
        return {"path": node.path(), "parms": {parm.name(): _json_safe(parm.eval()) for parm in node.parms()}}
    if command == "node.find":
        root = _node(str(params.get("path") or "/"))
        query = str(params.get("query") or "").lower()
        return {"nodes": [{"path": item.path(), "type": item.type().name()} for item in root.allSubChildren() if query in item.name().lower() or query in item.type().name().lower()]}
    if command == "node.create":
        parent = _node(str(params.get("parent")))
        node_type = str(params.get("type"))
        name = params.get("name")
        with _mutation_lease_fence(command, params):
            _preflight_creation_inputs(command, params)
            with _undo("Houdini Bridge create node"):
                creation_options = ({"exact_type_name": params["exact_type_name"]}
                                    if "exact_type_name" in params else {})
                child = parent.createNode(node_type, str(name) if name else None, **creation_options)
                if params.get("task_id") and params.get("operation_id"):
                    # Definition loading is part of the journaled creation, not
                    # a side effect of subsequent scene capture or verification.
                    if child.isDelayedDefinition():
                        child.syncDelayedDefinition()
                    child.allSubChildren(recurse_in_locked_nodes=True, sync_delayed_definition=True)
                if params.get("parms"):
                    _set_parms(child, dict(params["parms"]))
                for index, source in enumerate(params.get("inputs") or []):
                    if source:
                        child.setInput(index, _node(str(source)))
                if "xpos" in params and "ypos" in params:
                    child.setPosition(hou.Vector2(float(params["xpos"]), float(params["ypos"])))
        return {"path": child.path(), "type": child.type().name()}
    if command == "node.create_batch":
        parent = _node(str(params.get("parent")))
        created: dict[str, Any] = {}
        with _mutation_lease_fence(command, params):
            _preflight_creation_inputs(command, params)
            with _undo("Houdini Bridge create nodes"):
                for spec in params.get("nodes") or []:
                    key = str(spec.get("id") or spec.get("name") or uuid4().hex)
                    child = parent.createNode(str(spec["type"]), str(spec.get("name") or key))
                    if spec.get("parms"):
                        _set_parms(child, dict(spec["parms"]))
                    created[key] = child
                for spec in params.get("nodes") or []:
                    child = created[str(spec.get("id") or spec.get("name"))]
                    for index, source in enumerate(spec.get("inputs") or []):
                        if source:
                            child.setInput(index, created.get(str(source)) or _node(str(source)))
                parent.layoutChildren(items=list(created.values()))
        return {"nodes": {key: value.path() for key, value in created.items()}}
    if command == "node.connect":
        destination = _node(str(params.get("destination")))
        source = _node(str(params.get("source")))
        with _mutation_lease_fence(command, params):
            with _undo("Houdini Bridge connect nodes"):
                output_index = int(params.get("output_index", 0))
                if output_index < 0:
                    raise ValueError("output_index must be >= 0")
                destination.setInput(int(params.get("input_index", 0)), source, output_index)
        return {"destination": destination.path(), "source": source.path(), "output_index": output_index}
    if command in {"node.set_parm", "node.set_parms"}:
        node = _node(str(params.get("path")))
        changes = {str(params["name"]): params.get("value")} if command == "node.set_parm" else dict(params.get("parms") or {})
        root = _root_for_path(node.path())
        scope = _path_scope(node.path())
        if root is None or scope is None:
            raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "node is outside a leased task root")
        with _mutation_lease_fence(command, params):
            with _undo("Houdini Bridge set parameters"):
                # 只有当前跨案例范围认证的固定迁移能同步更新工程来源合同。
                from houdini_bridge.official_case_variant import transition_context
                with transition_context(hou,node,params,globals()):
                    values = _set_parms(node, changes)
        return {"path": node.path(), "values": values}
    if command == "node.cook":
        node = _node(str(params.get("path")))
        with _mutation_lease_fence(command, params):
            node.cook(force=bool(params.get("force", False)))
            payload: dict[str, Any] = {"path": node.path(), "errors": list(node.errors()), "warnings": list(node.warnings())}
            try:
                geometry = node.geometry()
                payload.update({"points": len(geometry.points()), "primitives": len(geometry.prims())})
            except Exception:
                pass
        return payload
    if command == "node.press_button":
        node = _node(str(params.get("path")))
        parm = node.parm(str(params.get("parm")))
        if parm is None:
            raise ValueError("button parameter not found")
        with _mutation_lease_fence(command, params):
            with _undo("Houdini Bridge press button"):
                parm.pressButton()
        return {"path": node.path(), "parm": parm.name()}
    if command == "node.delete":
        node = _node(str(params.get("path")))
        with _mutation_lease_fence(command, params):
            with _undo("Houdini Bridge delete node"):
                node.destroy()
        return {"deleted": str(params.get("path"))}
    if command == "node.bypass":
        node = _node(str(params.get("path")))
        with _mutation_lease_fence(command, params):
            with _undo("Houdini Bridge bypass node"):
                node.bypass(bool(params.get("value", True)))
        return {"path": node.path(), "bypassed": node.isBypassed()}
    if command == "node.unlock_contents":
        node = _node(str(params.get("path")))
        contract = _load_core_contract().interpret_unlock_params(params)
        if not contract.get("ok"):
            raise BridgeCommandError(contract["error"], contract["message"])
        task_id = str(params.get("task_id") or "")
        if not task_id:
            raise BridgeCommandError("TASK_SCOPE_REQUIRED",
                                     "node.unlock_contents requires task_id: only task-owned assets may be unlocked")
        root_path, _stage = _fx_task_paths(task_id, None)
        if not node.path().startswith(root_path + "/"):
            raise BridgeCommandError("TASK_SCOPE_REQUIRED",
                                     "refusing to unlock {}: it is outside the calling task root {}".format(node.path(), root_path))
        root = hou.node(root_path)
        if root is None or root.userData("bridge_fx_owned") != "1":
            raise BridgeCommandError("SCENE_CONFLICT", "task root {} is not a bridge-owned task root".format(root_path))
        with _mutation_lease_fence(command, params):
            _check_executor_generation(task_id)
            before = {"path": node.path(), "isLockedHDA": node.isLockedHDA()}
            with _undo("Houdini Bridge unlock node contents"):
                node.allowEditingOfContents(propagate=bool(contract["propagate"]))
            after = {"path": node.path(), "isLockedHDA": node.isLockedHDA()}
        return {"path": node.path(), "before": before, "after": after,
                "propagate": bool(contract["propagate"]),
                "deprecated_value_used": bool(contract.get("deprecated_value_used")),
                "note": "native allowEditingOfContents has no instance re-lock; an unlocked asset stays editable"}
    if command == "node.layout":
        node = _node(str(params.get("path")))
        with _mutation_lease_fence(command, params):
            with _undo("Houdini Bridge layout nodes"):
                node.layoutChildren()
        return {"path": node.path()}
    if command == "code.exec_python":
        return _safe_python(str(params.get("code") or ""))
    if command == "capabilities.get":
        sop_category = hou.sopNodeTypeCategory()
        try:
            lop_category = hou.lopNodeTypeCategory()
        except AttributeError:
            lop_category = None
        node_types = {
            "box": hou.nodeType(sop_category, "box") is not None,
            "tube": hou.nodeType(sop_category, "tube") is not None,
            "sopimport": bool(lop_category and hou.nodeType(lop_category, "sopimport") is not None),
            "karmarendersettings": bool(lop_category and hou.nodeType(lop_category, "karmarendersettings") is not None),
            "usdrender_rop": bool(lop_category and hou.nodeType(lop_category, "usdrender_rop") is not None),
        }
        return {
            "houdini_version": hou.applicationVersionString(),
            "python_version": "{}.{}.{}".format(*sys.version_info[:3]),
            "python_entry": "python{}.{}libs".format(*sys.version_info[:2]),
            "edition": hou.licenseCategory().name(),
            "gui": bool(hou.isUIAvailable()),
            "node_types": node_types,
            "fx_domain_packs": [_fx_probe_pack(pack_id, pack) for pack_id, pack in sorted(_FX_PACKS.items())],
        }
    raise ValueError(f"unsupported command: {command}")


def autostart() -> int:
    global _SERVER
    # Load the Bridge-owned provider before exposing the server.  Installation
    # is idempotent and never replaces an unknown existing seam.  A partial
    # provider still reports its exact blocked capabilities; it cannot make
    # the S-06 adapter mutation-ready.
    try:
        import hou
        _s06_install_native_provider(hou)
    except Exception:
        # Server startup remains diagnosable even when the optional provider
        # module is unavailable; inspect_scene exposes the load state and the
        # adapter remains fail-closed before its first graph mutation.
        pass
    if _SERVER is None:
        # Authenticate every newly loaded production instance. Existing GUI
        # sessions created by an older add-on remain discoverable through
        # their legacy tokenless manifests, so no running DCC must be stopped.
        _SERVER = HoudiniBridgeServer(
            token=secrets.token_urlsafe(32),
            allowed_commands=_production_allowed_commands() | _production_control_commands(),
        )
    return _SERVER.start()


def shutdown() -> None:
    global _SERVER
    if _SERVER is not None:
        _SERVER.stop(reason="explicit_shutdown")
        _SERVER = None


# ============================================================================
# Task host lifecycle + persistent frame operations (core-chain batch)
#
# Design invariants (from the core-chain task brief):
#   * Long frame-segment work is NEVER executed inside request dispatch. A
#     submit returns a stable operation_id immediately; the serve loop (or the
#     GUI event-loop callback) advances operations one frame per tick.
#   * Operation records persist outside the process: an identical submit after
#     a timeout returns the same operation without re-running any frame
#     (unknown-result protection). A RUNNING record from a dead generation is
#     reconciled to RECONCILE, never silently re-executed.
#   * One heavy operation at a time per host process; the heavy slot is
#     released only after an observed terminal state (never while a cook may
#     still be in flight).
# ============================================================================

_FX_OPERATIONS: "Optional[OperationRunner]" = None
_FX_OPERATIONS_LOCK = threading.Lock()


def _fx_operations_store_path(task_id: str) -> Path:
    directory = _state_dir().parent / "fx_operations"
    directory.mkdir(parents=True, exist_ok=True)
    return directory / "{}.json".format(_task_name(task_id, "ops"))


def _fx_scene_transition_digest(record: dict[str, Any]) -> str:
    body = {key: value for key, value in record.items()
            if key != "operation_receipt_sha256"}
    return hashlib.sha256(json.dumps(
        body, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        allow_nan=False).encode("utf-8")).hexdigest()


def _fx_producer_identity(task_id: str) -> dict[str, Any]:
    import hou

    global _BRIDGE_SCENE_CALLBACK_INSTALLED
    if not _BRIDGE_SCENE_CALLBACK_INSTALLED:
        _ = (hou.hipFileEventType.BeforeClear, hou.hipFileEventType.BeforeLoad, hou.hipFileEventType.BeforeMerge)
        hou.hipFile.addEventCallback(_bridge_scene_event)
        _BRIDGE_SCENE_CALLBACK_INSTALLED = True
    if _bridge_scene_event not in hou.hipFile.eventCallbacks():
        raise BridgeCommandError("SCENE_STATE_DRIFT", "producer scene callback was not retained")
    identity = _host_identity()
    if not globals().get("_TASK_HOST_IDENTITY"):
        from dcc_task_runtime.owned_process import read_receipt
        directory = os.environ.get("BRIDGE_OWNED_SUPERVISOR_DIR", "")
        binding = json.loads(os.environ.get("BRIDGE_OWNED_SUPERVISOR_IDENTITY", "{}"))
        started = read_receipt(directory, "started", identity=binding) if directory else None
        graph_binding = (isinstance(binding.get("operation_id"), str) and bool(binding["operation_id"])
                         and isinstance(binding.get("attempt_token"), str) and bool(binding["attempt_token"])
                         and type(binding.get("generation")) is int and binding["generation"] > 0)
        task_binding = binding.get("task_id") == task_id and bool(binding.get("launch_nonce"))
        if (not started or started.get("pid") != os.getpid() or not (task_binding or graph_binding)):
            raise BridgeCommandError("SUPERVISOR_REQUIRED", "graph command producer requires an observed task-owned launch")
        if os.name == "nt":
            from dcc_task_runtime.platform_support import process_identity
            observed_process = process_identity(os.getpid())
            if observed_process.get("birth") != started.get("process_birth") or observed_process.get("state") != "alive":
                raise BridgeCommandError("SUPERVISOR_REQUIRED", "supervisor start belongs to a different process birth")
        if graph_binding and not task_binding:
            graph_identity = graph_worker_identity()
            identity.update(session_id=graph_identity["session_id"],
                            process_generation=graph_identity["process_generation"],
                            scene_epoch=_GRAPH_WORKER_SCENE_EPOCH)
        identity.update(task_id=task_id, pid=os.getpid(), launch_nonce=binding.get("launch_nonce") or binding["attempt_token"],
                        plugin_build=_FX_LOADED_ADDON_SHA256, supervisor_identity=binding)
    if (hou.isUIAvailable() or identity.get("task_id") != task_id
            or identity.get("pid") != os.getpid()
            or identity.get("plugin_build") != _FX_LOADED_ADDON_SHA256
            or any(not identity.get(name) for name in
                   ("session_id", "launch_nonce", "process_generation"))):
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "producer requires a bound task-owned headless host")
    return identity


def _fx_official_capture_scope():
    """Select larger internal-HDA bounds only for the admitted official scope."""
    directory = os.environ.get('BRIDGE_OWNED_SUPERVISOR_DIR')
    if not directory:
        return None
    intent_path = Path(directory)/'intent.json'
    if not intent_path.is_file():
        return None
    intent=json.loads(intent_path.read_text(encoding='utf-8'))
    binding=(intent.get('resource_budget') or {}).get('native_scope')
    if binding is None:
        return None
    # 新增量范围沿用原官方 HDA 上限，范围认证和当前宿主准入检查保持不变。
    from dcc_task_runtime.native_scope import NativeScope, OFFICIAL_RESOURCE_PROFILE, OFFICIAL_INCREMENTAL_RESOURCE_PROFILE
    scope=NativeScope(binding)
    from dcc_task_runtime.rectlight_shape_scope import RESOURCE_PROFILE as RECT_SHAPE_PROFILE
    if scope.resource_profile not in (OFFICIAL_RESOURCE_PROFILE, OFFICIAL_INCREMENTAL_RESOURCE_PROFILE, RECT_SHAPE_PROFILE):
        return None
    from dcc_task_runtime.owned_process import read_receipt
    identity=intent.get('identity')
    start=read_receipt(directory,'started',identity=identity)
    if (not start or start.get('pid')!=os.getpid()
            or not any(t['directory']==directory and t['identity']==identity
                       and t['role'] in ('graph-worker','houdini-host') and t['stopped_at'] is None
                       for t in scope.snapshot()['tickets'])):
        raise BridgeCommandError('SCENE_CONTRACT_SCOPE_INVALID','official capture requires its current admitted host')
    return binding


def _fx_current_capture_limits():
    from houdini_bridge.operation_receipts import scene_capture_limits
    return scene_capture_limits(_fx_official_capture_scope())


def _fx_scene_capture_policy(contract, task_id, *, allow_legacy_v1=False):
    from houdini_bridge.operation_receipts import validate_scene_contract_header
    try:
        return validate_scene_contract_header(contract, task_id=task_id, allow_legacy_v1=allow_legacy_v1)
    except ValueError as exc:
        raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", str(exc)) from exc


def _fx_hda_bool(node, method):
    value = getattr(node, method)()
    if type(value) is not bool:
        raise ValueError("HDA state is not a boolean: " + method)
    return value


def _fx_hda_definition_identity(node):
    node_type = node.type()
    definition = node_type.definition()
    if definition is None:
        return None
    category = definition.nodeTypeCategory().name()
    type_name = category + "/" + definition.nodeTypeName()
    if (not isinstance(category, str) or not category
            or category != node_type.category().name() or type_name != node_type.nameWithCategory()):
        raise ValueError("active HDA definition type differs from its instance")
    sections = definition.sections()
    if not isinstance(sections, dict) or not sections or any(not isinstance(name, str) or not name for name in sections):
        raise ValueError("active HDA definition sections are unavailable")
    section_records = []
    for name, section in sorted(sections.items()):
        contents = section.binaryContents()
        if type(contents) is not bytes:
            raise ValueError("HDA section binary contents are unavailable")
        section_records.append({"name": name, "bytes": len(contents), "sha256": hashlib.sha256(contents).hexdigest()})
    options = definition.extraFileOptions()
    if not isinstance(options, dict):
        raise ValueError("active HDA extra file options are unavailable")
    normalized_options = {}
    for name, value in options.items():
        if not isinstance(name, str):
            raise ValueError("active HDA extra file option name is not a string")
        if type(value) in (bool, int, float, str):
            valid = type(value) is not float or math.isfinite(value)
        elif type(value) in (tuple, list):
            valid = all(type(item) in (int, float)
                        and (type(item) is not float or math.isfinite(item)) for item in value)
            value = list(value)
        else:
            valid = False
        if not valid:
            raise ValueError("unsupported active HDA extra file option {!r} ({})".format(name, type(value).__name__))
        normalized_options[name] = value
    version, extra_info = definition.version(), definition.extraInfo()
    if not isinstance(version, str) or not isinstance(extra_info, str):
        raise ValueError("active HDA definition metadata is unavailable")
    # The active definition bytes are semantic identity. Library location can
    # change to Embedded on save, so it must not enter the contract or digest.
    payload = {"type": type_name, "category": category, "version": version, "sections": section_records,
               "extra_file_options": normalized_options, "extra_info": extra_info}
    return {**payload, "sha256": _fx_scene_contract_digest(payload)}


def _fx_locked_hda_boundary(node, descendants, public_paths, *, parameter_limit=512):
    import hou

    if (not _fx_hda_bool(node, "isLockedHDA") or not _fx_hda_bool(node, "matchesCurrentDefinition")
            or _fx_hda_bool(node, "isDelayedDefinition")):
        raise ValueError("HDA boundary is not locked to a fully loaded active definition")
    definition = _fx_hda_definition_identity(node)
    if definition is None:
        raise ValueError("locked HDA has no active definition")
    definitions = {definition["sha256"]: definition}
    internal_nodes = []
    static_nodes = {}
    for child in sorted(descendants, key=lambda item: item.path()):
        path = child.path()
        reasons = []
        if not path.startswith(node.path() + "/"):
            reasons.append("outside_boundary")
        if path in static_nodes:
            reasons.append("duplicate_path")
        states = {}
        for method in ("isEditable", "isEditableInsideLockedHDA", "isDelayedDefinition"):
            try:
                states[method] = _fx_hda_bool(child, method)
            except Exception as exc:
                states[method] = "unavailable: " + str(exc)[:160]
                reasons.append(method + "_malformed")
        if reasons or any(value is not False for value in states.values()):
            raise ValueError("HDA internal state is editable, delayed, or malformed: boundary={!r} child={!r} "
                             "flags={!r} malformed_reasons={!r}".format(node.path()[:180], path[:180], states, reasons))
        kind = child.type().nameWithCategory()
        category = child.type().category().name()
        flag_methods = {
            "Sop": ("isBypassed", "isDisplayFlagSet", "isRenderFlagSet", "isTemplateFlagSet", "isHardLocked"),
            "Lop": ("isBypassed", "isDisplayFlagSet"),
            "Dop": ("isBypassed", "isDisplayFlagSet", "isTemplateFlagSet"),
            "Object": ("isDisplayFlagSet", "isSelectableInViewport"),
            "Vop": ("isBypassed",),
        }
        flag_category = "Object" if isinstance(child, getattr(hou, "ObjNode", ())) else category
        if flag_category not in flag_methods:
            raise ValueError("HDA internal static flag coverage is unknown for category " + flag_category)
        for method in flag_methods[flag_category]:
            try:
                _fx_hda_bool(child, method)
            except Exception as exc:
                raise ValueError("HDA internal required flag is unavailable: path={!r} type={!r} runtime={!r} "
                                 "method={!r}".format(path[:180], kind[:100], type(child).__name__[:80], method)) from exc
        hard_lock = getattr(child, "isHardLocked", None)
        if flag_category == "Sop" and not callable(hard_lock):
            raise ValueError("HDA internal hard lock state is unavailable")
        if (callable(hard_lock) and _fx_hda_bool(child, "isHardLocked")) or "stash" in kind.lower():
            raise ValueError("HDA internal stored geometry requires a separate complete identity")
        parms = list(child.parms())
        if len(parms) > parameter_limit:
            raise BridgeCommandError("SCENE_CONTRACT_TOO_LARGE", "HDA internal node exceeds receipt parameter limit")
        for parm in parms:
            if str(parm.parmTemplate().type()).rsplit(".", 1)[-1] == "Data":
                raise ValueError("HDA internal Data cannot be identified without evaluation")
        child_definition = _fx_hda_definition_identity(child)
        if _fx_hda_bool(child, "isLockedHDA") and child_definition is None:
            raise ValueError("locked internal HDA has no active definition")
        if child_definition is not None:
            locked = _fx_hda_bool(child, "isLockedHDA")
            matches = _fx_hda_bool(child, "matchesCurrentDefinition")
            if not locked or not matches:
                section_names = [section["name"] for section in child_definition["sections"]]
                network = "UNAVAILABLE"
                try:
                    network = _fx_hda_bool(child, "isNetwork")
                    children = child.children()
                    metadata_leaf = (not network and type(children) in (tuple, list) and not children
                                     and not {"Contents", "Contents.gz"}.intersection(section_names))
                except Exception:
                    metadata_leaf = False
                if not metadata_leaf:
                    raise ValueError("nested HDA is not locked to its active definition: path={!r} type={!r} "
                                     "network={!r} sections={!r}".format(
                                         path[:180], kind[:100], network, [name[:60] for name in section_names[:16]]))
            definitions[child_definition["sha256"]] = child_definition
        static_nodes[path] = child
        if path not in public_paths:
            internal_nodes.append({"path": path, "type": kind, "category": category,
                                   "definition_sha256": child_definition["sha256"] if child_definition else None})
    static = _houdini_node_graph_fingerprint(static_nodes, scope="locked-hda-internal/1", strict_static=True)
    if static is None or static.get("identity_complete") is not True:
        errors = [str(error)[:200] for error in (static or {}).get("errors", [])[:4]]
        raise ValueError("HDA internal static identity is incomplete: node_count={!r} errors={!r}".format(
            (static or {}).get("node_count"), errors))
    return {"path": node.path(), "type": node.type().nameWithCategory(), "category": node.type().category().name(),
            "is_locked_hda": True, "matches_current_definition": True, "definition": definition,
            "definitions": [definitions[key] for key in sorted(definitions)],
            "internal_nodes": internal_nodes, "internal_node_count": len(internal_nodes), "static_fingerprint": static}


def _fx_scene_contract_nodes(owned_roots, registered, *, capture_policy=None):
    """Collect public nodes and a bounded non-evaluating locked-HDA proof."""
    import hou
    if capture_policy not in (None, "legacy-full/2.0", "locked-hda-definition/1", "official-locked-hda-definition/1"):
        raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "unknown scene capture policy")
    limits = _fx_current_capture_limits()
    nodes = dict(registered)
    public_paths = {str(path) for path in nodes.values()}
    if any(not any(path == root or path.startswith(root.rstrip("/") + "/") for root in owned_roots)
           for path in public_paths):
        raise BridgeCommandError("SCENE_CONTRACT_NODE_MISSING", "registered task node is outside the owned roots")
    roots = [hou.node(path) for path in owned_roots]
    try:
        for root in roots:
            if root is None:
                continue
            descendants = (root.allSubChildren() if capture_policy == "legacy-full/2.0" else
                           () if _fx_hda_bool(root, "isLockedHDA") else
                           root.allSubChildren(recurse_in_locked_nodes=False, sync_delayed_definition=False))
            for child in descendants:
                if child.path() not in public_paths:
                    nodes["owned:" + child.path()] = child.path()
                    public_paths.add(child.path())
        if len(nodes) > 128:
            raise BridgeCommandError("SCENE_CONTRACT_TOO_LARGE", "task scene exceeds receipt node limit")
        if capture_policy == "legacy-full/2.0":
            return nodes, []
        boundaries, covered, all_paths = [], set(), set(public_paths)
        candidates = {node.path(): node for node in roots if node is not None}
        candidates.update({path: hou.node(path) for path in public_paths})
        for path, node in sorted(candidates.items(), key=lambda item: (item[0].count("/"), item[0])):
            if node is None:
                raise BridgeCommandError("SCENE_CONTRACT_NODE_MISSING", "registered task node is unavailable during save")
            if path in covered:
                continue
            if _fx_hda_bool(node, "isDelayedDefinition"):
                raise ValueError("public HDA definition is delayed")
            if not _fx_hda_bool(node, "isLockedHDA"):
                continue
            descendants = tuple(node.allSubChildren(recurse_in_locked_nodes=True, sync_delayed_definition=False))
            all_paths.update(child.path() for child in descendants)
            if len(all_paths) > limits["total_nodes"]:
                raise BridgeCommandError("SCENE_CONTRACT_TOO_LARGE", "HDA internals exceed receipt node limit")
            if not any(child.path() not in public_paths for child in descendants):
                continue
            if path not in public_paths:
                raise ValueError("opaque HDA boundary is not a registered public node")
            boundaries.append(_fx_locked_hda_boundary(node, descendants, public_paths)
                              if limits['parameters_per_node'] == 512 else
                              _fx_locked_hda_boundary(node, descendants, public_paths, parameter_limit=limits['parameters_per_node']))
            covered.update(child.path() for child in descendants)
        if capture_policy == "locked-hda-definition/1" and not boundaries:
            raise ValueError("saved HDA capture policy has no live opaque boundary")
        return nodes, sorted(boundaries, key=lambda item: item["path"])
    except BridgeCommandError:
        raise
    except Exception as exc:
        raise BridgeCommandError("SCENE_CONTRACT_HDA_UNPROVEN", "locked HDA capture is incomplete: " + str(exc)) from exc


def _fx_scene_contract_policy_fields(contract, boundaries):
    native_scope = _fx_official_capture_scope()
    if native_scope is not None:
        import hou
        from houdini_bridge.operation_receipts import OFFICIAL_CAPTURE_SCHEMA, OFFICIAL_CAPTURE_POLICY, OFFICIAL_CAPTURE_LIMITS
        contract.update(schema=OFFICIAL_CAPTURE_SCHEMA,capture_policy=OFFICIAL_CAPTURE_POLICY,
                        native_scope=native_scope,capture_limits=dict(OFFICIAL_CAPTURE_LIMITS),hda_boundaries=boundaries)
        for record in contract['nodes']:
            record['category']=hou.node(record['path']).type().category().name()
        _fx_scene_capture_policy(contract,contract['task_id'])
        return contract
    if boundaries:
        import hou
        contract.update(schema="houdini.task_scene_contract/2.1", capture_policy="locked-hda-definition/1",
                        hda_boundaries=boundaries)
        for record in contract["nodes"]:
            record["category"] = hou.node(record["path"]).type().category().name()
    _fx_scene_capture_policy(contract, contract["task_id"])
    return contract


def _fx_native_command_scene_contract(task_id: str, params: dict[str, Any], *, pending_stash_nodes=(), capture_policy=None) -> dict[str, Any] | None:
    import hou

    target = params.get("root_path") or params.get("execution_root") or params.get("parent") or params.get("destination") or params.get("path")
    if params.get("root_name"):
        target = str(params.get("parent") or "/obj").rstrip("/") + "/" + str(params["root_name"])
    root = _root_for_path(str(target or ""))
    if not root or hou.node(root) is None:
        return None
    _root_lease_check(root, task_id=task_id, scope=_path_scope(root), renew=False)
    registered, boundaries = _fx_scene_contract_nodes([root], {"owned:" + root: root}, capture_policy=capture_policy)
    nodes = [hou.node(path) for path in registered.values()]
    limits = _fx_current_capture_limits()
    records = []
    for node in sorted(nodes, key=lambda item: item.path()):
        parms = list(node.parms())
        if len(parms) > limits["parameters_per_node"]:
            raise BridgeCommandError("SCENE_CONTRACT_TOO_LARGE", "native command node exceeds receipt parameter limit")
        readbacks = {str(parm.name()): _fx_scene_parameter_readback(
            parm, task_id, allow_uninitialized_stash=node in pending_stash_nodes) for parm in parms}
        records.append({"role": "owned:" + node.path(), "path": node.path(),
                        "type": node.type().nameWithCategory(),
                        "parameters": {name: value for name, (value, channel) in readbacks.items() if channel["evaluated_available"]},
                        "parameter_channels": {name: channel for name, (value, channel) in readbacks.items()},
                        "inputs": [item.path() if item is not None else None for item in node.inputs()]})
    if _fx_current_capture_limits() != limits:
        raise BridgeCommandError("SCENE_CONTRACT_SCOPE_INVALID", "capture limits changed during native readback")
    contract = {"schema": "houdini.task_scene_contract/2.0", "task_id": task_id,
                "execution_root": root, "owned_roots": [root],
                "graph_hash": str(params.get("graph_hash") or ""), "nodes": records}
    _fx_scene_contract_policy_fields(contract, boundaries)
    if len(json.dumps(contract, ensure_ascii=False, allow_nan=False).encode("utf-8")) > 2 * 1024 * 1024:
        raise BridgeCommandError("SCENE_CONTRACT_TOO_LARGE", "native command contract exceeds receipt byte limit")
    return contract


def _fx_producer_scene(task_id: str, params: dict[str, Any], *, allow_missing: bool = False,
                       pending_stash_nodes=(), capture_policy=None) -> dict[str, Any]:
    import hou

    contract = _fx_capture_scene_contract(task_id, capture_policy=capture_policy)
    if contract is None:
        contract = _fx_native_command_scene_contract(task_id, params, pending_stash_nodes=pending_stash_nodes, capture_policy=capture_policy)
    if contract is None and not allow_missing:
        raise BridgeCommandError("SCENE_CONTRACT_REQUIRED", "producer requires actual task node readback")
    if contract is not None:
        _root_lease_check(contract["execution_root"], task_id=task_id, scope="sop", renew=False)
    path = Path(str(hou.hipFile.path())).expanduser().resolve()
    return {"host_identity": _fx_producer_identity(task_id), "hip_path": str(path),
            "hip_sha256": _fx_sha256_file(path) if path.is_file() else None,
            "scene_contract": contract,
            "scene_contract_sha256": _fx_scene_contract_digest(contract) if contract else None}


def _fx_producer_record(runner, store: dict[str, Any], operation_id: str):
    from houdini_bridge.operation_receipt_store import load_record, record_path
    from houdini_bridge.operation_receipts import validate_operation_receipt

    legacy = store.get("producer_operations", {})
    if not isinstance(legacy, dict):
        raise BridgeCommandError("PRODUCER_RECEIPT_INVALID", "legacy producer map is malformed")
    try:
        standalone = load_record(runner.path, runner.task_id, operation_id)
        prior = legacy.get(operation_id)
        if operation_id in legacy:
            validate_operation_receipt(prior, require_completed=False)
            if prior.get("task_id") != runner.task_id or prior.get("operation_id") != operation_id:
                raise ValueError("legacy producer task or operation binding differs")
        if standalone is not None and prior is not None and standalone != prior:
            raise ValueError("standalone and legacy producer records disagree")
    except ValueError as exc:
        raise BridgeCommandError("PRODUCER_RECEIPT_INVALID", str(exc)) from exc
    if standalone is not None:
        return standalone, record_path(runner.path, runner.task_id, operation_id), "producer_record"
    return prior, runner.path, "legacy_task_store"


def _fx_reject_producer_operation_id(runner, store: dict[str, Any], operation_id: str) -> None:
    prior, _path, _format = _fx_producer_record(runner, store, operation_id)
    if prior is not None:
        raise BridgeCommandError("CONTENT_CHANGED", "operation ID already belongs to a producer command")


def _fx_pending_stash_creations(identity):
    from houdini_bridge.operation_receipt_store import load_record
    from houdini_bridge.operation_receipts import canonical_sha256, validate_operation_receipt
    import hou

    creations = globals().setdefault('_FX_NATIVE_STASH_CREATIONS', {})
    binding = canonical_sha256(identity)
    creations = creations.setdefault(binding, {})
    nodes = []
    for path, creation in list(creations.items()):
        node = hou.node(path)
        if node is None or node != creation['node']:
            del creations[path]
            continue
        record = load_record(creation['runner_path'], identity['task_id'], creation['operation_id'])
        validate_operation_receipt(record)
        if (record['host_identity'] != identity or record['command'] not in {'node.create', 'node.create_batch'}
                or not any(item['path'] == path and item['type'] == 'Sop/stash'
                           for item in record['facts'].get('created_nodes', []))):
            raise BridgeCommandError('PRODUCER_RECONCILE_REQUIRED', 'pending stash creation is not bound to this host')
        nodes.append(node)
    return creations, tuple(nodes)


def _fx_scene_has_pending_data(scene):
    contract = scene.get('scene_contract') or {}
    return any(channel.get('data_observation_schema') == 'bridge.pending-stash-data/1'
               for node in contract.get('nodes', [])
               for channel in node.get('parameter_channels', {}).values())


def _fx_producer_checkpoint(stage: str, operation_id: str, scene=None) -> None:
    if os.environ.get("BRIDGE_GRAPH_STARTUP_DIAGNOSTICS") != "1":
        return
    try:
        wall_time_ns, monotonic_ns = time.time_ns(), time.monotonic_ns()
        contract = (scene or {}).get("scene_contract") or {}
        nodes = contract.get("nodes") or []
        boundaries = contract.get("hda_boundaries") or []
        counts = " public_nodes={} internal_nodes={} parm_readbacks={} definitions={}".format(
            len(nodes), sum(item.get("internal_node_count", 0) for item in boundaries),
            sum(len(item.get("parameter_channels") or {}) for item in nodes),
            sum(len(item.get("definitions") or []) for item in boundaries))
        message = ("bridge.houdini-producer.timing/1 stage=" + stage
                   + " operation_id=" + operation_id[:100] + " pid=" + str(os.getpid())
                   + " wall_time_ns=" + str(wall_time_ns) + " monotonic_ns=" + str(monotonic_ns)
                   + counts + "\n")
        os.write(2, message.encode("ascii"))
    except Exception:
        pass


def _fx_producer_execution_root(command, task_id, request, before, result=None):
    contract = before.get("scene_contract") or {}
    root = contract.get("execution_root")
    if command == "scene.create_task_root":
        name = str(request.get("root_name") or "").strip()
        kind = str(request.get("type") or "geo")
        layouts = {"geo": "sop_geo/1", "subnet": "object_subnet/1"}
        if (not _GRAPH_ROOT_NAME.fullmatch(name) or request.get("parent", "/obj") != "/obj"
                or kind not in layouts or request.get("root_layout", "sop_geo/1") != layouts[kind]):
            raise BridgeCommandError("INVALID_ARGUMENT", "task root requires the registered generated root layout")
        requested = "/obj/" + name
        if root is not None and root != requested:
            raise BridgeCommandError("SCENE_CONTRACT_SCOPE_INVALID", "request and captured task root differ")
        root = requested
    if root is None and command == "agent.fx.build_preview":
        root = _fx_task_paths(task_id, _fx_execution_root(request))[0]
    if not isinstance(root, str) or _root_for_path(root) != root or _path_scope(root) != "sop":
        raise BridgeCommandError("SCENE_CONTRACT_SCOPE_INVALID", "producer has no unique trusted object root")
    for name in ("root_path", "execution_root"):
        if request.get(name) is not None and request[name] != root:
            raise BridgeCommandError("SCENE_CONTRACT_SCOPE_INVALID", "request and captured task root differ")
    bound_root = _fx_execution_root(request)
    if bound_root is not None and bound_root != root:
        raise BridgeCommandError("SCENE_CONTRACT_SCOPE_INVALID", "bound execution root differs from captured root")
    if result is not None:
        handler_root = result.get("path") if command == "scene.create_task_root" else None
        if command == "agent.fx.build_preview":
            manifest = result.get("scene_manifest") or {}
            if manifest.get("task_id") != task_id:
                raise BridgeCommandError("SCENE_CONTRACT_SCOPE_INVALID", "handler manifest task differs")
            handler_root = manifest.get("execution_root")
        if command in {"scene.create_task_root", "agent.fx.build_preview"} and handler_root != root:
            raise BridgeCommandError("SCENE_CONTRACT_SCOPE_INVALID", "handler returned a different task root")
        _manifest_node, manifest = _fx_manifest(task_id, required=False)
        if manifest and (manifest.get("task_id") != task_id or manifest.get("execution_root") != root):
            raise BridgeCommandError("SCENE_CONTRACT_SCOPE_INVALID", "persisted manifest root differs")
    return root


def _fx_producer_query_identity(task_id, root):
    """Observe only native owner/epoch/HIP/lease, without scene capture."""
    import hou
    path = Path(str(hou.hipFile.path())).expanduser().resolve()
    return {"host_identity": _fx_producer_identity(task_id), "lease_identity": _host_identity(),
            "hip_path": str(path),
            "hip_sha256": _fx_sha256_file(path) if path.is_file() else None,
            "root_lease": _root_lease_check(root, task_id=task_id, scope="sop", renew=False)}


def _fx_producer_query_dispatch(command, params):
    from copy import deepcopy
    from houdini_bridge.operation_receipt_store import write_record
    from houdini_bridge.operation_receipts import (
        QUERY_SCHEMA, CHILDREN_INSPECT_POLICY, canonical_sha256,
        operation_receipt_sha256, validate_query_receipt,
    )
    import hou

    request = json.loads(json.dumps(params, ensure_ascii=False, allow_nan=False))
    task_id = str(request.get("task_id") or "")
    operation_id = str(request.get("operation_id") or "")
    request_id = str(request.get("request_id") or operation_id)
    root, target = request.get("root_path"), request.get("path")
    if (command != "node.children" or request.get("inspect_policy") != CHILDREN_INSPECT_POLICY
            or not task_id or not re.fullmatch(r"[A-Za-z0-9_.-]{1,100}", operation_id)
            or not re.fullmatch(r"[A-Za-z0-9_.-]{1,100}", request_id)
            or not isinstance(root, str) or _root_for_path(root) != root or _path_scope(root) != "sop"
            or not isinstance(target, str) or (target != root and not target.startswith(root + "/"))):
        raise BridgeCommandError("INVALID_ARGUMENT", "query requires a typed owned-root children request")
    frozen = request.get("frozen_input_manifest")
    frozen_sha256 = _rehash_frozen_input_manifest(frozen)
    request_sha256 = canonical_sha256({"task_id": task_id, "command": command,
                                       "request_id": request_id, "request": request})
    runner = fx_operation_runner(task_id)
    with _root_lease_fence(root, task_id=task_id, scope="sop"):
        before = _fx_producer_query_identity(task_id, root)
        record = {"schema": QUERY_SCHEMA, "kind": "inspect", "stage": "inspect", "command": command,
                  "state": "INTENT", "task_id": task_id, "operation_id": operation_id,
                  "request_id": request_id, "request": request, "request_sha256": request_sha256,
                  "host_identity": before["host_identity"], "before_query": before,
                  "frozen_input_manifest": frozen, "frozen_inputs_sha256": frozen_sha256,
                  "execution_boundary": "software_hou_api" if getattr(hou, "_bridge_software_boundary", False) else "native_hom",
                  "started_at": datetime.now(timezone.utc).isoformat()}
        record["operation_receipt_sha256"] = operation_receipt_sha256(record)
        validate_query_receipt(record, require_completed=False)
        with runner._locked():
            store = runner._load()
            if operation_id in (store.get("operations") or {}) or operation_id in (store.get("scene_transitions") or {}):
                raise BridgeCommandError("CONTENT_CHANGED", "operation ID belongs to another operation kind")
            prior, prior_path, prior_format = _fx_producer_record(runner, store, operation_id)
            if prior is not None:
                if prior["schema"] != QUERY_SCHEMA or prior["request_sha256"] != request_sha256:
                    raise BridgeCommandError("CONTENT_CHANGED", "query ID already binds different content")
                if prior["state"] != "COMPLETED":
                    raise BridgeCommandError("PRODUCER_RECONCILE_REQUIRED", "prior query is incomplete; no automatic re-execution")
            else:
                write_record(runner.path, task_id, operation_id, record)
        intent = deepcopy(record)
        try:
            result = _dispatch_command(command, request)
            after = _fx_producer_query_identity(task_id, root)
            if before != after or _rehash_frozen_input_manifest(frozen) != frozen_sha256:
                raise BridgeCommandError("SCENE_STATE_DRIFT", "query host, epoch, HIP, root lease or frozen inputs changed")
            completed = {**deepcopy(intent), "state": "COMPLETED", "after_query": after,
                         "result": result, "facts": {"scope": "inspect", "proof_scope": "owned_root_children",
                             "full_scene_identity_verified": False, "handler_result_sha256": canonical_sha256(result)},
                         "completed_at": datetime.now(timezone.utc).isoformat()}
            completed["operation_receipt_sha256"] = operation_receipt_sha256(completed)
            validate_query_receipt(completed)
            with runner._locked():
                store = runner._load()
                current, _path, _format = _fx_producer_record(runner, store, operation_id)
                if (operation_id in (store.get("operations") or {})
                        or operation_id in (store.get("scene_transitions") or {})
                        or current != (prior if prior is not None else intent)):
                    raise BridgeCommandError("PRODUCER_RECEIPT_INVALID", "query record changed during execution")
                if prior is not None:
                    if prior["after_query"] != after or prior["result"] != result:
                        raise BridgeCommandError("SCENE_STATE_DRIFT", "completed query differs from current identity or children")
                    return {**prior["result"], "operation_receipt": prior, "operation_store_path": str(prior_path),
                            "operation_store_format": prior_format, "idempotent": True}
                receipt_path = write_record(runner.path, task_id, operation_id, completed, expected=intent)
            return {**result, "operation_receipt": completed, "operation_store_path": str(receipt_path),
                    "operation_store_format": "producer_record", "idempotent": False}
        except Exception as exc:
            if prior is None:
                failed = {**deepcopy(intent), "state": "FAILED", "error": {
                    "code": getattr(exc, "code", type(exc).__name__), "message": str(exc)[:1000]},
                    "failed_at": datetime.now(timezone.utc).isoformat()}
                failed["operation_receipt_sha256"] = operation_receipt_sha256(failed)
                with runner._locked():
                    store = runner._load()
                    current, _path, _format = _fx_producer_record(runner, store, operation_id)
                    if (current == intent and operation_id not in (store.get("operations") or {})
                            and operation_id not in (store.get("scene_transitions") or {})):
                        write_record(runner.path, task_id, operation_id, failed, expected=intent)
            raise


def _fx_producer_dispatch(command: str, params: dict[str, Any]) -> dict[str, Any]:
    if command == "scene.save_hip":
        with _task_scene_lease_fence(str(params.get("task_id") or ""), params):
            return _fx_producer_dispatch_impl(command, params, save_fenced=True)
    return _fx_producer_dispatch_impl(command, params)


def _fx_producer_dispatch_impl(command: str, params: dict[str, Any], *, save_fenced=False) -> dict[str, Any]:
    from copy import deepcopy
    from houdini_bridge.operation_receipt_store import write_record
    from houdini_bridge.operation_receipts import (
        SCHEMA, COMMAND_KINDS, canonical_sha256, operation_receipt_sha256,
        validate_operation_receipt,
    )
    import hou

    task_id = str(params.get("task_id") or "")
    operation_id = str(params.get("operation_id") or "")
    request_id = str(params.get("request_id") or operation_id)
    if (not task_id or not re.fullmatch(r"[A-Za-z0-9_.-]{1,100}", operation_id)
            or not re.fullmatch(r"[A-Za-z0-9_.-]{1,100}", request_id)):
        raise BridgeCommandError("INVALID_ARGUMENT", "typed producer requires task, operation and request IDs")
    request = json.loads(json.dumps(params, ensure_ascii=False, allow_nan=False))
    frozen = request.get("frozen_input_manifest")
    frozen_sha256 = _rehash_frozen_input_manifest(frozen)
    asset_inputs = [] if command == "node.create" else request.get("inputs") or []
    for item in asset_inputs:
        if (not isinstance(item, dict) or not any(
                isinstance(source, dict) and source.get("asset_id") == item.get("asset_id")
                and source.get("sha256") == item.get("sha256") for source in frozen)):
            raise BridgeCommandError("PRODUCER_INPUT_BINDING_REQUIRED", "each task input requires a byte-verified frozen source")
    identity = _fx_producer_identity(task_id)
    allow_uninitialized_stash = command in {
        'node.create', 'node.create_batch', 'node.set_parms', 'node.connect', 'scene.create_task_root',
        'node.info', 'node.children'}
    creations, pending_stash_nodes = _fx_pending_stash_creations(identity) if allow_uninitialized_stash else ({}, ())
    request_sha256 = canonical_sha256({"task_id": task_id, "command": command,
                                       "request_id": request_id, "request": request})
    runner = fx_operation_runner(task_id)
    with runner._locked():
        initial_store = runner._load()
        if operation_id in (initial_store.get("operations") or {}) or operation_id in (initial_store.get("scene_transitions") or {}):
            raise BridgeCommandError("CONTENT_CHANGED", "operation ID already belongs to another operation kind")
        initial_prior, _path, _format = _fx_producer_record(runner, initial_store, operation_id)
        if initial_prior is not None:
            if initial_prior["schema"] != SCHEMA or initial_prior["request_sha256"] != request_sha256:
                raise BridgeCommandError("CONTENT_CHANGED", "producer operation ID already binds different content")
            if initial_prior["state"] != "COMPLETED":
                raise BridgeCommandError("PRODUCER_RECONCILE_REQUIRED", "prior producer attempt is incomplete; no automatic re-execution")
            capture_policy = _fx_scene_capture_policy(initial_prior["after_scene"]["scene_contract"], task_id)
        else:
            capture_policy = None
        initial_prior = deepcopy(initial_prior)
    _fx_producer_checkpoint("before_start", operation_id)
    before = _fx_producer_scene(task_id, request, allow_missing=command in {"agent.fx.build_preview", "scene.create_task_root"},
                                pending_stash_nodes=pending_stash_nodes, capture_policy=capture_policy)
    _fx_producer_checkpoint("before_end", operation_id, before)
    execution_root = _fx_producer_execution_root(command, task_id, request, before)
    if command.startswith("node."):
        owned_roots = before["scene_contract"]["owned_roots"]
        for name in ("path", "parent", "source", "destination"):
            target = request.get(name)
            if isinstance(target, str) and not any(target == root or target.startswith(root + "/") for root in owned_roots):
                raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "native command target is outside the task contract")
    if command in {"node.create", "node.create_batch"}:
        with _mutation_lease_fence(command, request):
            _preflight_creation_inputs(command, request)
    with runner._locked():
        store = runner._load()
        if operation_id in (store.get("operations") or {}) or operation_id in (store.get("scene_transitions") or {}):
            raise BridgeCommandError("CONTENT_CHANGED", "operation ID already belongs to another operation kind")
        prior, prior_path, prior_format = _fx_producer_record(runner, store, operation_id)
        if prior != initial_prior:
            raise BridgeCommandError("PRODUCER_RECEIPT_INVALID", "producer record changed during before capture")
        if prior is not None:
            try:
                validate_operation_receipt(prior, require_completed=False)
            except ValueError as exc:
                raise BridgeCommandError("PRODUCER_RECEIPT_INVALID", str(exc)) from exc
            if prior["request_sha256"] != request_sha256:
                raise BridgeCommandError("CONTENT_CHANGED", "producer operation ID already binds different content")
            if prior["state"] != "COMPLETED":
                raise BridgeCommandError("PRODUCER_RECONCILE_REQUIRED", "prior producer attempt is incomplete; no automatic re-execution")
            if _fx_scene_has_pending_data(prior['after_scene']) or _fx_scene_has_pending_data(before):
                raise BridgeCommandError('PRODUCER_RECONCILE_REQUIRED', 'unobserved stash Data cannot prove scene equality for replay')
            if prior["host_identity"] != identity or prior["after_scene"] != before:
                raise BridgeCommandError("SCENE_STATE_DRIFT", "completed producer belongs to a different current scene or host")
            saved = (prior.get("facts") or {}).get("saved_scene")
            if saved and _fx_scene_transition_snapshot(task_id, saved, require_source=True) != saved:
                raise BridgeCommandError("ARTIFACT_INVALID", "completed save bytes or snapshot changed")
            return {**prior["result"], "operation_receipt": prior,
                    "operation_store_path": str(prior_path), "operation_store_format": prior_format, "idempotent": True}
        if command == "scene.save_hip":
            raw_path = Path(str(request.get("path") or "")).expanduser()
            if (not request.get("path") or not raw_path.is_absolute() or raw_path.suffix.lower() not in {".hip", ".hiplc", ".hipnc"}
                    or raw_path.exists() or any(parent.is_symlink() for parent in (raw_path, *raw_path.parents))):
                raise BridgeCommandError("PRODUCER_SAVE_NOT_FRESH", "typed save requires an explicit fresh HIP path")
        record = {"schema": SCHEMA, "kind": COMMAND_KINDS[command], "command": command,
                  "stage": COMMAND_KINDS[command],
                  "state": "INTENT", "task_id": task_id, "operation_id": operation_id,
                  "request_id": request_id, "request": request, "request_sha256": request_sha256,
                  "host_identity": identity, "before_scene": before,
                  "frozen_input_manifest": frozen, "frozen_inputs_sha256": frozen_sha256,
                  "execution_boundary": "software_hou_api" if getattr(hou, "_bridge_software_boundary", False) else "native_hom",
                  "started_at": datetime.now(timezone.utc).isoformat()}
        if save_fenced:
            record["save_name_transition"] = {"original_hip_path": str(hou.hipFile.path()),
                                              "target_hip_path": str(raw_path)}
        record["operation_receipt_sha256"] = operation_receipt_sha256(record)
        _fx_producer_checkpoint("intent_validation_start", operation_id)
        validate_operation_receipt(record, require_completed=False)
        _fx_producer_checkpoint("intent_validation_end", operation_id)
        intent = deepcopy(record)
        _fx_producer_checkpoint("intent_persist_start", operation_id)
        receipt_path = write_record(runner.path, task_id, operation_id, record)
        _fx_producer_checkpoint("intent_persist_end", operation_id)
    save_named_before, rename_started, save_attempted = before, False, False
    try:
        if save_fenced:
            rename_started = True
            hou.hipFile.setName(str(raw_path))
            if Path(hou.hipFile.path()).resolve() != raw_path.resolve() or _fx_producer_identity(task_id) != identity:
                raise BridgeCommandError("SCENE_STATE_DRIFT", "typed save naming changed its bound host or target")
            save_named_before = _fx_producer_scene(task_id, request, capture_policy=capture_policy)
            _fx_producer_execution_root(command, task_id, request, save_named_before)
        _fx_producer_checkpoint("handler_start", operation_id)
        save_attempted = save_fenced
        result = (_dispatch_command(command, request, _scene_save_fenced=True)
                  if save_fenced else _dispatch_command(command, request))
        _fx_producer_checkpoint("handler_end", operation_id)
        new_stash_nodes = ()
        if command in {'node.create', 'node.create_batch'}:
            paths = list((result.get('nodes') or {}).values()) if command == 'node.create_batch' else [result.get('path')]
            before_paths = {node['path'] for node in before['scene_contract']['nodes']}
            new_stash_nodes = tuple(hou.node(path) for path in paths
                                    if path not in before_paths and hou.node(path) is not None
                                    and hou.node(path).type().nameWithCategory() == 'Sop/stash')
        pending_stash_nodes += new_stash_nodes
        _fx_producer_execution_root(command, task_id, request, before, result)
        _root_lease_check(execution_root, task_id=task_id, scope="sop", renew=False)
        with (nullcontext() if save_fenced else _task_scene_lease_fence(
                task_id, {**request, "root_path": execution_root}, required_root=execution_root)):
            _fx_producer_checkpoint("after_start", operation_id)
            after = _fx_producer_scene(task_id, request, pending_stash_nodes=pending_stash_nodes)
            _fx_producer_checkpoint("after_end", operation_id, after)
            if after["scene_contract"].get("execution_root") != execution_root:
                raise BridgeCommandError("SCENE_CONTRACT_SCOPE_INVALID", "after scene differs from the fenced task root")
            if after["host_identity"] != identity or _rehash_frozen_input_manifest(frozen) != frozen_sha256:
                raise BridgeCommandError("SCENE_STATE_DRIFT", "producer owner or frozen inputs changed during execution")
            facts = {"scope": COMMAND_KINDS[command], "handler_result_sha256": canonical_sha256(result)}
            facts["proof_scope"] = "native_command" if command.startswith("node.") or command == "scene.create_task_root" else "task_scene"
            if command == "agent.fx.build_preview":
                manifest = result.get("scene_manifest") or {}
                assessment = manifest.get("execution_assessment") or {}
                if (manifest.get("task_id") != task_id
                        or assessment.get("build_state") != "BUILT_VERIFIED_STATIC"
                        or assessment.get("domain_graph_constructed") is not True):
                    raise BridgeCommandError("PRODUCER_BUILD_UNPROVEN", "handler did not establish a verified static domain graph")
                facts["static_domain_readback"] = assessment.get("native_graph_contract")
                facts["connections"] = manifest.get("connections")
            elif command == "agent.fx.apply_candidate":
                changes = result.get("parameter_diff")
                if not changes or any(item.get("readback_verified") is not True for item in changes):
                    raise BridgeCommandError("PRODUCER_EDIT_UNPROVEN", "handler has no verified native parameter diff")
                facts["parameter_diff"] = changes
                facts["invalidates_from"] = result.get("invalidates_from")
            elif command in {"scene.info", "node.children", "node.info", "node.parms"}:
                if before != after:
                    raise BridgeCommandError("SCENE_STATE_DRIFT", "inspect changed the task scene")
            elif command in {"node.set_parm", "node.set_parms"}:
                changes = {str(request["name"]): request.get("value")} if command == "node.set_parm" else request.get("parms") or {}
                node = _node(str(request["path"]))
                actual = {name: _json_safe(node.parm(name).eval()) for name in changes}
                if not changes or any(not _values_match(value, (result.get("values") or {}).get(name))
                                      or not _values_match(value, actual[name]) for name, value in changes.items()):
                    raise BridgeCommandError("PARAMETER_READBACK_MISMATCH", "native parameter result differs from requested edit")
                facts["parameter_readback"] = actual
            elif command == "node.connect":
                destination = _node(str(request["destination"]))
                wires = [{"input_index": wire.inputIndex(), "source": wire.inputNode().path(),
                          "output_index": wire.outputIndex()} for wire in destination.inputConnections()]
                expected = {"input_index": int(request.get("input_index", 0)), "source": str(request["source"]),
                            "output_index": int(request.get("output_index", 0))}
                if expected not in wires:
                    raise BridgeCommandError("GRAPH_CONTRACT_UNVERIFIED", "native wire differs from command result")
                facts["input_connections"] = wires
            elif command in {"node.create", "node.create_batch", "scene.create_task_root"}:
                paths = list((result.get("nodes") or {}).values()) if command == "node.create_batch" else [result.get("path")]
                facts["created_nodes"] = [node for node in after["scene_contract"]["nodes"] if node["path"] in paths]
                if not paths or len(facts["created_nodes"]) != len(paths):
                    raise BridgeCommandError("NODE_CREATE_FAILED", "created nodes were not read back in the owned root")
            elif command == "node.cook":
                if result.get("errors"):
                    raise BridgeCommandError("NODE_COOK_FAILED", "native cook returned node errors")
                facts["cook_readback"] = result
            elif command == "scene.save_hip":
                if (save_named_before["scene_contract"] != after["scene_contract"]
                        or result.get("scene_contract") != after["scene_contract"]
                        or str(Path(str(result.get("path") or "")).resolve()) != after["hip_path"]
                        or result.get("sha256") != after["hip_sha256"]):
                    raise BridgeCommandError("PRODUCER_SAVE_UNPROVEN", "saved HIP or actual contract differs from current scene")
                saved = _fx_scene_transition_snapshot(task_id, after | {"path": after["hip_path"],
                                                       "sha256": after["hip_sha256"]}, require_source=True)
                if saved is None:
                    raise BridgeCommandError("PRODUCER_SAVE_UNPROVEN", "saved HIP bytes cannot be frozen")
                facts["saved_scene"] = saved
                facts["save_name_transition"] = {**intent["save_name_transition"],
                    "named_scene_contract_sha256": save_named_before["scene_contract_sha256"]}
            completed = {**deepcopy(intent), "state": "COMPLETED", "after_scene": after,
                         "result": result, "facts": facts,
                         "completed_at": datetime.now(timezone.utc).isoformat()}
            completed["operation_receipt_sha256"] = operation_receipt_sha256(completed)
            _fx_producer_checkpoint("terminal_validation_start", operation_id)
            validate_operation_receipt(completed)
            _fx_producer_checkpoint("terminal_validation_end", operation_id)
            with runner._locked():
                store = runner._load()
                prior, _path, _format = _fx_producer_record(runner, store, operation_id)
                if (prior != intent or operation_id in (store.get("operations") or {})
                        or operation_id in (store.get("scene_transitions") or {})):
                    raise BridgeCommandError("PRODUCER_RECEIPT_INVALID", "producer intent changed during execution")
                _fx_producer_checkpoint("terminal_persist_start", operation_id)
                receipt_path = write_record(runner.path, task_id, operation_id, completed, expected=intent)
                _fx_producer_checkpoint("terminal_persist_end", operation_id)
            for node in new_stash_nodes:
                creations[node.path()] = {'node': node, 'runner_path': runner.path, 'operation_id': operation_id}
        return {**result, "operation_receipt": completed, "operation_store_path": str(receipt_path),
                "operation_store_format": "producer_record", "idempotent": False}
    except Exception as exc:
        reconciliation_required, restore_error = False, None
        if rename_started:
            try:
                hou.hipFile.setName(intent["save_name_transition"]["original_hip_path"])
                if (str(hou.hipFile.path()) != intent["save_name_transition"]["original_hip_path"]
                        or _fx_producer_identity(task_id) != identity):
                    raise ValueError("original HIP name or owner was not restored")
            except Exception as error:
                restore_error = type(error).__name__
            # Once native save was entered, its effects cannot be rolled back
            # by renaming the live scene; the failed intent remains non-replayable.
            reconciliation_required = save_attempted or raw_path.exists() or restore_error is not None
        failed = {**deepcopy(intent), "state": "FAILED", "error": {"code": getattr(exc, "code", type(exc).__name__),
                   "message": str(exc)[:1000]}, "failed_at": datetime.now(timezone.utc).isoformat()}
        if rename_started:
            failed["save_name_restored"] = restore_error is None
            failed["reconciliation_required"] = reconciliation_required
            if restore_error is not None:
                failed["save_name_restore_error"] = restore_error
        failed["operation_receipt_sha256"] = operation_receipt_sha256(failed)
        with runner._locked():
            store = runner._load()
            prior, _path, _format = _fx_producer_record(runner, store, operation_id)
            if (prior == intent and operation_id not in (store.get("operations") or {})
                    and operation_id not in (store.get("scene_transitions") or {})):
                _fx_producer_checkpoint("failed_persist_start", operation_id)
                write_record(runner.path, task_id, operation_id, failed, expected=intent)
                _fx_producer_checkpoint("failed_persist_end", operation_id)
        if reconciliation_required:
            raise BridgeCommandError("PRODUCER_RECONCILE_REQUIRED",
                                     "typed save failed after a possibly effective native mutation; inspect its persisted intent") from exc
        raise


def _fx_scene_transition_snapshot(task_id: str, request: dict[str, Any], *, require_source: bool) -> dict[str, str] | None:
    raw_path = str(request.get("path") or "")
    expected = str(request.get("sha256") or "").lower()
    if (not raw_path or len(expected) != 64
            or any(char not in "0123456789abcdef" for char in expected)):
        return None
    raw_source = Path(raw_path).expanduser()
    if raw_source.is_symlink():
        return None
    source = raw_source.resolve()
    if require_source and not source.is_file():
        return None
    root = _task_state_root() / "scene-transition-snapshots"
    safe_task = "".join(char if char.isalnum() or char in ".-_" else "_"
                         for char in str(task_id))[:120] or "unbound"
    directory = root / safe_task
    directory.mkdir(parents=True, exist_ok=True)
    snapshot = directory / (expected + ".hip")
    if snapshot.is_symlink():
        return None
    if not snapshot.is_file():
        if not require_source or hashlib.sha256(source.read_bytes()).hexdigest() != expected:
            return None
        temporary = snapshot.with_name("." + snapshot.name + ".tmp")
        temporary.write_bytes(source.read_bytes())
        temporary.chmod(0o400)
        temporary.replace(snapshot)
    try:
        if hashlib.sha256(snapshot.read_bytes()).hexdigest() != expected:
            return None
        if require_source and hashlib.sha256(source.read_bytes()).hexdigest() != expected:
            return None
    except OSError:
        return None
    return {"path": str(source), "sha256": expected,
            "snapshot_path": str(snapshot), "snapshot_sha256": expected}


def _fx_scene_transition_begin(params: dict[str, Any], command: str,
                               path: Path, expected_sha256: str, *, scene_contract_sha256=None) -> dict[str, Any] | None:
    task_id = str(params.get("task_id") or "").strip()
    # Direct low-level/unit callers from the legacy C1 lease surface do not
    # carry a controller operation identity.  Keep that compatibility path
    # free of a fake formal receipt; configured task-owned controllers always
    # supply operation_id/request_id/scene_before_identity and therefore take
    # the durable transition path below.
    if (not task_id or not any(params.get(key) for key in
                               ("operation_id", "request_id", "scene_before_identity"))):
        return None
    import hou
    global _BRIDGE_SCENE_CALLBACK_INSTALLED
    if not _BRIDGE_SCENE_CALLBACK_INSTALLED:
        _ = (hou.hipFileEventType.BeforeClear, hou.hipFileEventType.BeforeLoad,
             hou.hipFileEventType.BeforeMerge)
        hou.hipFile.addEventCallback(_bridge_scene_event)
        _BRIDGE_SCENE_CALLBACK_INSTALLED = True
        if _bridge_scene_event not in hou.hipFile.eventCallbacks():
            raise BridgeCommandError("PRODUCTION_SCENE_IDENTITY_UNAVAILABLE",
                                     "scene epoch callback was not retained")
    observed = _host_identity()
    supplied_before = params.get("scene_before_identity")
    if isinstance(supplied_before, dict):
        for key in ("session_id", "process_generation", "scene_epoch"):
            if supplied_before.get(key) != observed.get(key):
                raise BridgeCommandError("PRODUCTION_SCENE_IDENTITY_MISMATCH",
                                         "scene transition started from a different host identity")
    request = {"path": str(path.expanduser().resolve()),
               "sha256": str(expected_sha256 or "").lower()}
    if len(request["sha256"]) != 64 or any(char not in "0123456789abcdef" for char in request["sha256"]):
        raise BridgeCommandError("PRODUCTION_SCENE_TRANSITION_BINDING_INVALID",
                                 "scene transition requires a content-addressed HIP")
    operation_id = str(params.get("operation_id") or "").strip()
    request_id = str(params.get("request_id") or operation_id).strip()
    if not operation_id:
        operation_id = "scene-" + hashlib.sha256(json.dumps(
            {"task_id": task_id, "command": command, "request": request,
             "before_identity": {key: observed.get(key) for key in
                 ("task_id", "session_id", "launch_nonce", "pid", "process_generation", "plugin_build", "scene_epoch")}},
            ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()[:48]
    if not request_id:
        request_id = operation_id
    if (not re.fullmatch(r"[A-Za-z0-9_.-]{1,100}", operation_id)
            or not re.fullmatch(r"[A-Za-z0-9_.-]{1,100}", request_id)):
        raise BridgeCommandError("INVALID_ARGUMENT", "scene transition operation and request IDs are bounded identifiers")
    request_sha256 = hashlib.sha256(json.dumps(
        {"task_id": task_id, "command": command, "request": request,
         "request_id": request_id}, ensure_ascii=False, sort_keys=True,
        separators=(",", ":")).encode("utf-8")).hexdigest()
    runner = fx_operation_runner(task_id)
    with runner._locked():
        store = runner._load()
        store.setdefault("task_id", task_id)
        _fx_reject_producer_operation_id(runner, store, operation_id)
        if operation_id in (store.get("operations") or {}):
            raise BridgeCommandError("CONTENT_CHANGED", "scene transition ID already belongs to another operation kind")
        transitions = store.setdefault("scene_transitions", {})
        prior = runner._record(store, operation_id, family="scene_transitions")
        if prior is not None:
            if (prior.get("task_id") != task_id or prior.get("request_id") != request_id
                    or prior.get("request_sha256") != request_sha256
                    or (command == "scene.reopen_task_hip"
                        and prior.get("scene_contract_sha256") != scene_contract_sha256)):
                raise BridgeCommandError("CONTENT_CHANGED", "scene transition operation was reused with different content")
            return dict(prior)
        store_cas = int(store.get("scene_transition_cas") or 0) + 1
        record = {
            "schema": "bridge.houdini.scene-transition-operation/1.0",
            "state": "INTENT", "task_id": task_id,
            "operation_id": operation_id, "request_id": request_id,
            "request_sha256": request_sha256, "command": str(command),
            "request": request, "before_identity": dict(supplied_before or observed),
            "before_scene_epoch": int(observed.get("scene_epoch")),
            "store_cas": store_cas,
            "started_at": datetime.now(timezone.utc).isoformat(),
        }
        if command == "scene.reopen_task_hip":
            record["scene_contract_sha256"] = scene_contract_sha256
        record["operation_receipt_sha256"] = _fx_scene_transition_digest(record)
        transitions[operation_id] = record
        store["scene_transition_cas"] = store_cas
        runner._save(store)
        return dict(record)


def _fx_task_reopen_scene_proof(record, result, *, require_active):
    """Prove a task reopen from its registered full contract at the saved path."""
    import hou

    task_id = str(record.get('task_id') or '')
    request = record.get('request') or {}
    path = Path(str(request.get('path') or '')).expanduser().resolve()
    digest = request.get('sha256')
    contract_digest = record.get('scene_contract_sha256')
    if (not contract_digest or record.get('operation_receipt_sha256') != _fx_scene_transition_digest(record)
            or str(path) != request.get('path') or result.get('path') != str(path)
            or result.get('sha256') != digest or result.get('scene_contract_sha256') != contract_digest
            or Path(hou.hipFile.path()).expanduser().resolve() != path
            or not path.is_file() or _fx_sha256_file(path) != digest):
        raise BridgeCommandError('ARTIFACT_CONTRACT_INVALID', 'task reopen path or registered contract binding differs')
    saves_path = _fx_task_saves_path(task_id)
    saved = json.loads(saves_path.read_text(encoding='utf-8')) if saves_path.is_file() else {}
    receipts = [item for item in saved.get('saves') or []
                if item.get('path') == str(path) and item.get('sha256') == digest
                and item.get('scene_contract_sha256') == contract_digest]
    receipt = receipts[-1] if receipts else {}
    contract = receipt.get('scene_contract')
    if not isinstance(contract, dict) or _fx_scene_contract_digest(contract) != contract_digest:
        raise BridgeCommandError('ARTIFACT_CONTRACT_INVALID', 'task reopen has no complete registered save contract')
    if require_active:
        active = saved.get('active_scene') or {}
        if (active.get('path') != str(path) or active.get('sha256') != digest
                or active.get('scene_contract_sha256') != contract_digest
                or active.get('scene_contract') != contract or active.get('identity') != _host_identity()
                or active.get('transition_operation_id') != record.get('operation_id')
                or active.get('transition_request_sha256') != record.get('request_sha256')):
            raise BridgeCommandError('ARTIFACT_CONTRACT_INVALID', 'active task scene belongs to another transition')
    return receipt, _fx_verify_scene_contract(contract, task_id)


def _fx_task_reopen_record_loaded(transition, snapshot, load_count, warnings):
    if transition is None:
        return None
    import hou
    actual = _host_identity()
    before = transition.get('before_identity') or {}
    loaded_path = Path(str(snapshot.get('snapshot_path') or '')).expanduser().resolve()
    request = transition.get('request') or {}
    stable = ('task_id', 'session_id', 'launch_nonce', 'pid', 'process_generation', 'plugin_build')
    if (any(before.get(key) in (None, '') or before.get(key) != actual.get(key) for key in stable)
            or load_count not in (1, 2)
            or actual.get('scene_epoch') != transition.get('before_scene_epoch', -1) + load_count
            or Path(hou.hipFile.path()).expanduser().resolve() != loaded_path
            or snapshot.get('path') != request.get('path') or snapshot.get('sha256') != request.get('sha256')
            or snapshot.get('snapshot_sha256') != request.get('sha256')
            or not loaded_path.is_file() or _fx_sha256_file(loaded_path) != request.get('sha256')):
        raise BridgeCommandError('PRODUCTION_SCENE_TRANSITION_RECONCILIATION_UNPROVEN',
                                 'snapshot load did not retain its exact controlled host identity')
    runner = fx_operation_runner(str(transition['task_id']))
    with runner._locked():
        store = runner._load()
        prior = runner._record(store, transition['operation_id'], family='scene_transitions')
        if prior != transition or prior.get('state') != 'INTENT':
            raise BridgeCommandError('PRODUCTION_SCENE_TRANSITION_RECORD_INVALID', 'task load intent changed before readback')
        loaded = dict(prior, post_load_identity=dict(actual), load_count=load_count,
            loaded_snapshot=dict(snapshot), load_warnings=list(warnings),
            store_cas=int(store.get('scene_transition_cas') or 0) + 1)
        loaded['operation_receipt_sha256'] = _fx_scene_transition_digest(loaded)
        store['scene_transitions'][loaded['operation_id']] = loaded
        store['scene_transition_cas'] = loaded['store_cas']
        runner._save(store)
        return loaded


def _fx_scene_transition_replay(record):
    """Return a completed load only while its exact scene is still current."""
    import hou
    if not isinstance(record, dict) or record.get('state') != 'COMPLETED':
        return None
    after = record.get('after_identity') or {}
    actual = _host_identity()
    required = ('task_id', 'session_id', 'launch_nonce', 'pid', 'process_generation', 'plugin_build', 'scene_epoch')
    if (any(after.get(key) in (None, '') or actual.get(key) != after.get(key) for key in required)
            or record.get('operation_receipt_sha256') != _fx_scene_transition_digest(record)):
        raise BridgeCommandError('PRODUCTION_SCENE_TRANSITION_REPLAY_UNPROVEN', 'completed transition belongs to another scene identity')
    result = record.get('result') or {}
    if record.get('command') == 'scene.reopen_task_hip':
        try:
            _fx_task_reopen_scene_proof(record, result, require_active=True)
        except Exception as exc:
            raise BridgeCommandError('PRODUCTION_SCENE_TRANSITION_REPLAY_UNPROVEN',
                                     'current task scene cannot be proven unchanged') from exc
        return {**result, 'scene_transition': dict(record), 'idempotent': True}
    current = Path(hou.hipFile.path()).expanduser().resolve()
    allowed = {str(Path(str(result[key])).expanduser().resolve()) for key in ('path', 'snapshot_path') if result.get(key)}
    if (str(current) not in allowed or not current.is_file()
            or _fx_sha256_file(current) != (record.get('request') or {}).get('sha256')):
        raise BridgeCommandError('PRODUCTION_SCENE_TRANSITION_REPLAY_UNPROVEN', 'current HIP differs from completed transition')
    if hou.hipFile.hasUnsavedChanges() is not False:
        saves = _fx_task_saves_path(str(record['task_id']))
        saved = json.loads(saves.read_text(encoding='utf-8')) if saves.is_file() else {}
        active = saved.get('active_scene') or {}
        contract = active.get('scene_contract')
        if active.get('identity') != actual or not isinstance(contract, dict):
            raise BridgeCommandError('PRODUCTION_SCENE_TRANSITION_REPLAY_UNPROVEN', 'current scene content cannot be proven unchanged')
        _fx_verify_scene_contract(contract, str(record['task_id']))
    return {**result, 'scene_transition': dict(record), 'idempotent': True}


def _fx_scene_transition_complete(task_id: str, operation_id: str,
                                  result: dict[str, Any], *, completion=None) -> dict[str, Any] | None:
    if not task_id or not operation_id:
        return None
    runner = fx_operation_runner(task_id)
    with runner._locked():
        store = runner._load()
        transitions = store.get("scene_transitions") or {}
        prior = runner._record(store, operation_id, family="scene_transitions")
        if not isinstance(prior, dict):
            raise BridgeCommandError("PRODUCTION_SCENE_TRANSITION_RECORD_MISSING",
                                     "scene transition intent is not durable")
        if prior.get("state") == "COMPLETED":
            return dict(prior)
        if prior.get("state") != "INTENT":
            raise BridgeCommandError("PRODUCTION_SCENE_TRANSITION_RECORD_INVALID",
                                     "scene transition is not completable")
        request = prior.get("request") or {}
        if (str(result.get("path") or "") != str(request.get("path") or "")
                or str(result.get("sha256") or "").lower() != str(request.get("sha256") or "").lower()):
            raise BridgeCommandError("PRODUCTION_SCENE_TRANSITION_RESULT_MISMATCH",
                                     "scene result does not match the durable HIP intent")
        after = _host_identity()
        before_epoch = prior.get("before_scene_epoch")
        if type(before_epoch) is not int or type(after.get("scene_epoch")) is not int or after["scene_epoch"] <= before_epoch:
            raise BridgeCommandError("PRODUCTION_SCENE_TRANSITION_EPOCH_INVALID",
                                     "scene transition did not advance the host epoch")
        snapshot = _fx_scene_transition_snapshot(task_id, request, require_source=True)
        if snapshot is None:
            raise BridgeCommandError("PRODUCTION_SCENE_TRANSITION_SNAPSHOT_INVALID",
                                     "the immutable loaded HIP snapshot could not be verified")
        if prior.get('command') == 'scene.reopen_task_hip':
            if (not prior.get('scene_contract_sha256')
                    or result.get('scene_contract_sha256') != prior['scene_contract_sha256']
                    or prior.get('post_load_identity') != after):
                raise BridgeCommandError('ARTIFACT_CONTRACT_INVALID', 'task transition result contract differs')
            snapshot['scene_contract_sha256'] = prior['scene_contract_sha256']
        store_cas = int(store.get("scene_transition_cas") or 0) + 1
        completed = dict(prior)
        completed.update({"state": "COMPLETED", "after_identity": dict(after),
                          "after_scene_epoch": after["scene_epoch"],
                          "result": snapshot, "store_cas": store_cas,
                          "completed_at": datetime.now(timezone.utc).isoformat()})
        completed["operation_receipt_sha256"] = _fx_scene_transition_digest(completed)
        transitions[operation_id] = completed
        store["scene_transition_cas"] = store_cas
        reopen_scopes = [*globals().get('_FX_GEOMETRY_REOPEN_SCOPES', {}).values(),
                         *globals().get('_FX_RBD_REOPEN_SCOPES', {}).values(),
                         *globals().get('_FX_PARTICLE_EMISSION_REOPEN_SCOPES', {}).values()]
        for scope in reopen_scopes:
            if (scope['task_id'] == task_id and scope.get('transition_operation_id') == operation_id
                    and isinstance(scope.get('completion'), dict)):
                if _fx_geometry_host_identity(task_id) != scope['identity']:
                    raise BridgeCommandError('SCENE_STATE_DRIFT', 'geometry handoff identity changed before completion')
                scope['completion']['record'] = json.loads(json.dumps(completed, allow_nan=False))
        if isinstance(completion, dict):
            completion['record'] = json.loads(json.dumps(completed, allow_nan=False))
        runner._save(store)
        return dict(completed)


def _fx_scene_transition_reconcile(params: dict[str, Any]) -> dict[str, Any]:
    task_id = str(params.get("task_id") or "").strip()
    operation_id = str(params.get("operation_id") or "").strip()
    if not task_id or not operation_id:
        raise BridgeCommandError("INVALID_ARGUMENT", "task_id and operation_id are required")
    runner = fx_operation_runner(task_id)
    with runner._locked():
        store = runner._load()
        prior = runner._record(store, operation_id, family="scene_transitions")
        if not isinstance(prior, dict):
            raise BridgeCommandError("PRODUCTION_SCENE_TRANSITION_RECORD_MISSING",
                                     "no durable scene transition operation exists")
        if prior.get("state") == "COMPLETED":
            return {"scene_transition": dict(prior), "reconciled": False}
        if prior.get("state") != "INTENT":
            raise BridgeCommandError("PRODUCTION_SCENE_TRANSITION_RECORD_INVALID",
                                     "scene transition is not an interrupted intent")
        after = _host_identity()
        before_epoch = prior.get("before_scene_epoch")
        if prior.get('command') == 'scene.reopen_task_hip':
            loaded = prior.get('loaded_snapshot') or {}
            request = prior.get('request') or {}
            count = prior.get('load_count')
            proven_epoch = (type(before_epoch) is int and type(count) is int and count in (1, 2)
                and prior.get('post_load_identity') == after
                and after.get('scene_epoch') == before_epoch + count
                and loaded.get('path') == request.get('path') and loaded.get('sha256') == request.get('sha256')
                and loaded.get('snapshot_sha256') == request.get('sha256')
                and prior.get('operation_receipt_sha256') == _fx_scene_transition_digest(prior))
        else:
            proven_epoch = type(before_epoch) is int and after.get('scene_epoch') == before_epoch + 1
        if not proven_epoch:
            raise BridgeCommandError("PRODUCTION_SCENE_TRANSITION_RECONCILIATION_UNPROVEN",
                                     "current host epoch is not the single controlled transition after the intent")
        result = prior.get("result") or _fx_scene_transition_snapshot(
            task_id, prior.get("request") or {}, require_source=True)
        if not isinstance(result, dict):
            raise BridgeCommandError("PRODUCTION_SCENE_TRANSITION_RECONCILIATION_UNPROVEN",
                                     "the interrupted HIP content fact is unavailable")
    if prior.get('command') == 'scene.reopen_task_hip':
        try:
            before = prior.get('before_identity') or {}
            if any(before.get(key) in (None, '') or before.get(key) != after.get(key)
                   for key in ('task_id', 'session_id', 'launch_nonce', 'pid', 'process_generation', 'plugin_build')):
                raise BridgeCommandError('ARTIFACT_CONTRACT_INVALID', 'interrupted task reopen belongs to another host')
            result = dict(result, scene_contract_sha256=prior.get('scene_contract_sha256'))
            receipt, verification = _fx_task_reopen_scene_proof(prior, result, require_active=False)
        except Exception as exc:
            raise BridgeCommandError('PRODUCTION_SCENE_TRANSITION_RECONCILIATION_UNPROVEN',
                                     'interrupted task scene cannot be proven at its saved path') from exc
        finalized = _fx_finalize_task_reopen(task_id, Path(result['path']), result['sha256'],
            receipt, result, prior, warnings=prior.get('load_warnings') or [],
            structure_verified=len(receipt.get('structure') or {}), contract_verification=verification)
        return {'scene_transition': finalized['scene_transition'], 'reconciled': True}
    if _fx_geometry_reconcile_checkpoint(task_id, prior.get('request') or {}, prior.get('command')):
        result = dict(result, geometry_registry_restored=True)
    if _fx_rbd_reconcile_checkpoint(task_id, prior.get('request') or {}, prior.get('command')):
        result = dict(result, rbd_velocity_restored=True)
    if _fx_particle_emission_reconcile_checkpoint(task_id, prior.get('request') or {}, prior.get('command')):
        result = dict(result, particle_emission_restored=True)
    completed = _fx_scene_transition_complete(task_id, operation_id, result)
    return {"scene_transition": completed, "reconciled": True}


def _fx_legacy_operations_store_path(task_id: str) -> Path:
    directory = _state_dir().parent / "fx_operations"
    directory.mkdir(parents=True, exist_ok=True)
    legacy = _legacy_task_name(task_id, "ops")
    return directory / "{}.json".format(legacy) if legacy else directory / "__none__.json"


_FX_GRAPH_SCHEDULER: "Optional[Any]" = None


def _fx_graph_scheduler():
    """Installation-wide heavy-slot authority, shared with Nuke and the graph flow.

    ONE GraphScheduler database per installation: every adapter (Houdini frame
    operations, Nuke renders, graph jobs) resolves the same root, so a single
    active heavy job is enforced across hosts and control surfaces.
    """
    global _FX_GRAPH_SCHEDULER
    if _FX_GRAPH_SCHEDULER is None:
        for src in ("packages/dcc-task-runtime/src", "packages/vfx-pipeline/src"):
            package_root = _FX_REPOSITORY_ROOT / src
            if package_root.is_dir() and str(package_root) not in sys.path:
                sys.path.insert(0, str(package_root))
        from dcc_task_runtime.graph_scheduler import GraphScheduler
        from dcc_task_runtime.state_paths import installation_scheduler_root
        _FX_GRAPH_SCHEDULER = GraphScheduler(installation_scheduler_root())
    return _FX_GRAPH_SCHEDULER


def _fx_host_protocol_version() -> str:
    return "task-host/1.0"


def _fx_host_generation() -> str:
    return uuid4().hex[:12]


def _fx_houdini_supported() -> bool:
    import hou
    version = hou.applicationVersionString()
    return version.startswith(("21.", "22."))


def _durable_execution_lock(database, task_id):
    """Prefer the runtime package's execution lock; fall back to the vendored
    copy of the same primitive when the runtime package is not importable."""
    try:
        from dcc_task_runtime.execution_lock import execution_lock
        return execution_lock(database, task_id)
    except Exception:
        module = sys.modules.get("_bridge_durable_lock")
        if module is None:
            import importlib.util
            path = _FX_ADDON_SOURCE.parent / "durable_lock.py"
            spec = importlib.util.spec_from_file_location("_bridge_durable_lock", path)
            module = importlib.util.module_from_spec(spec)
            sys.modules["_bridge_durable_lock"] = module
            spec.loader.exec_module(module)
        return module.execution_lock(database, task_id)


def hou_node(path: str):
    import hou
    return hou.node(path)


def hou_set_frame(frame) -> None:
    import hou
    hou.setFrame(frame)


def hou_time() -> float:
    import hou
    return hou.time()


def _reconcile_source_is_trusted(value: Any) -> bool:
    """Accept only named controller/host observation channels.

    A free-form string is not a stop receipt.  The source label is still not
    a cryptographic signature (the control authorization covers that), but it
    must identify one of the bounded channels that can produce a separate
    lifecycle observation.
    """
    source = str(value or "").strip()
    return bool(re.fullmatch(
        r"(?:controller|host|houdini|nuke|workbuddy|supervisor|unit-test)(?:[/:-][A-Za-z0-9_.-]+)*",
        source,
    ))


def _reconcile_observed_at_is_valid(value: Any) -> bool:
    """Require a timezone-bearing ISO-8601 observation timestamp."""
    rendered = str(value or "").strip()
    if not rendered:
        return False
    try:
        parsed = datetime.fromisoformat(rendered.replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return False
    return (parsed.tzinfo is not None and parsed.utcoffset() is not None
            and parsed.timestamp() <= time.time() + 5.0)


def _lifecycle_fact_digest(fact: dict[str, Any]) -> str:
    """Hash the persisted lifecycle fact without its self-referential digest."""
    payload = {key: value for key, value in fact.items() if key != "fact_digest"}
    return hashlib.sha256(json.dumps(
        payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
    ).encode("utf-8")).hexdigest()


def _new_lifecycle_fact(record: dict[str, Any], *, kind: str,
                        side_effect_started: bool = False,
                        process_exited: bool = False,
                        stop_confirmed: bool = False,
                        source: str = "controller/operation-runner") -> dict[str, Any]:
    """Create the controller-owned lifecycle receipt for one exact attempt.

    Caller-supplied reconcile dictionaries are never allowed to manufacture a
    STOP_CONFIRMED receipt.  The runner writes this fact at the lifecycle
    boundary and binds it to the current reservation and process identity.
    """
    process = record.get("process") if isinstance(record.get("process"), dict) else {}
    attempt = record.get("attempt") if isinstance(record.get("attempt"), dict) else {}
    slot = record.get("slot") if isinstance(record.get("slot"), dict) else {}
    fact = {
        "schema": "bridge.houdini.lifecycle_fact/1.0",
        "kind": str(kind),
        "task_id": str(record.get("task_id") or ""),
        "request_id": str(record.get("request_id") or ""),
        "attempt_id": str(attempt.get("attempt_id") or record.get("execution_id") or ""),
        "slot_generation": int(slot.get("generation") or 0),
        "slot_token": str(slot.get("token") or ""),
        "process_generation": str(
            process.get("process_generation") or attempt.get("process_generation")
            or record.get("claimed_by_generation") or ""),
        "process_identity": str(
            process.get("process_identity") or attempt.get("process_identity") or ""),
        "pid": process.get("pid"),
        "observed_at": datetime.now(timezone.utc).isoformat(),
        "source": str(source),
        "side_effect_started": bool(side_effect_started),
        "process_exited": bool(process_exited),
        "stop_confirmed": bool(stop_confirmed),
        "exit_code": record.get("exit_code"),
    }
    # Only a task host launched by our fixed supervisor has a durable
    # process-exit observation channel. Preserve its binding on STARTED.
    if kind == "STARTED" and os.environ.get("BRIDGE_OWNED_SUPERVISOR_DIR"):
        fact["supervisor_binding"] = {
            "directory": os.environ["BRIDGE_OWNED_SUPERVISOR_DIR"],
            "identity": json.loads(os.environ["BRIDGE_OWNED_SUPERVISOR_IDENTITY"]),
        }
    fact["fact_digest"] = _lifecycle_fact_digest(fact)
    return fact


def _lifecycle_fact_is_valid(record: dict[str, Any], fact: Any) -> bool:
    """Check that the persisted receipt is intact and still bound to record."""
    if not isinstance(fact, dict) or fact.get("schema") != "bridge.houdini.lifecycle_fact/1.0":
        return False
    digest = str(fact.get("fact_digest") or "")
    if not digest or not hmac.compare_digest(digest, _lifecycle_fact_digest(fact)):
        return False
    slot = record.get("slot") if isinstance(record.get("slot"), dict) else {}
    process = record.get("process") if isinstance(record.get("process"), dict) else {}
    attempt = record.get("attempt") if isinstance(record.get("attempt"), dict) else {}
    expected = {
        "task_id": str(record.get("task_id") or ""),
        "request_id": str(record.get("request_id") or ""),
        "attempt_id": str(attempt.get("attempt_id") or record.get("execution_id") or ""),
        "slot_generation": int(slot.get("generation") or 0),
        "slot_token": str(slot.get("token") or ""),
        "process_generation": str(
            process.get("process_generation") or attempt.get("process_generation")
            or record.get("claimed_by_generation") or ""),
        "process_identity": str(
            process.get("process_identity") or attempt.get("process_identity") or ""),
    }
    return all(str(fact.get(key)) == str(value) for key, value in expected.items())


def _validate_reconcile_evidence(record: dict[str, Any], task_id: str,
                                 request_id: str, evidence: Any,
                                 *, allow_external_stop: bool = False) -> dict[str, Any]:
    """Validate the fact that permits a RECONCILE slot transition.

    Control authorization proves who requested a decision; it never proves
    that an unknown worker stopped or never started.  That second fact is a
    separate, persisted receipt bound to the exact old reservation.
    """
    if not isinstance(evidence, dict):
        raise BridgeCommandError(
            "RECONCILE_EVIDENCE_REQUIRED",
            "a signed control decision must carry a separate stop/not-started receipt")
    kind = str(evidence.get("kind") or "")
    if kind not in {"confirmed_stop", "confirmed_not_started"}:
        raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "unsupported reconcile evidence kind")
    if str(evidence.get("task_id") or "") != str(task_id) or str(evidence.get("request_id") or "") != str(request_id):
        raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "reconcile evidence is bound to a different task or operation")
    slot = record.get("slot") if isinstance(record.get("slot"), dict) else {}
    try:
        if int(evidence.get("slot_generation")) != int(slot.get("generation")):
            raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "reconcile evidence slot generation does not match the record")
    except (TypeError, ValueError) as exc:
        raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "reconcile evidence lacks a numeric slot generation") from exc
    if not hmac.compare_digest(str(evidence.get("slot_token") or ""), str(slot.get("token") or "")):
        raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "reconcile evidence slot token does not match the record")
    if not _reconcile_observed_at_is_valid(evidence.get("observed_at")):
        raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "reconcile evidence needs a timezone-bearing ISO observation time")
    if not _reconcile_source_is_trusted(evidence.get("source")):
        raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "reconcile evidence source is not a trusted observation channel")
    if evidence.get("confirmed") is not True:
        raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "reconcile evidence is not confirmed")
    lifecycle_fact = record.get("lifecycle_fact")
    if not _lifecycle_fact_is_valid(record, lifecycle_fact):
        raise BridgeCommandError(
            "RECONCILE_EVIDENCE_INVALID",
            "the operation has no intact controller lifecycle fact bound to this attempt",
        )
    if kind == "confirmed_stop":
        if evidence.get("process_exited") is not True or evidence.get("stop_confirmed") is not True:
            raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "stop evidence must confirm process exit and stop")
        lifecycle_digest = str(lifecycle_fact.get("fact_digest") or "")
        supplied_digest = str(evidence.get("lifecycle_fact_digest") or evidence.get("fact_digest") or "")
        if lifecycle_fact.get("kind") == "STOP_CONFIRMED":
            if lifecycle_fact.get("process_exited") is not True or lifecycle_fact.get("stop_confirmed") is not True:
                raise BridgeCommandError(
                    "RECONCILE_EVIDENCE_INVALID",
                    "stop evidence requires a persisted controller-confirmed stop receipt",
                )
            if not hmac.compare_digest(supplied_digest, lifecycle_digest):
                raise BridgeCommandError(
                    "RECONCILE_EVIDENCE_INVALID",
                    "stop evidence is not bound to the persisted lifecycle receipt",
                )
        elif allow_external_stop and lifecycle_fact.get("kind") == "STARTED":
            # A trusted supervisor may import the stop observation after the
            # controller lost its process handle.  The controller fact remains
            # STARTED until this method creates the next immutable fact; a
            # free-form status field or an ordinary controller query is not
            # sufficient.
            if not str(evidence.get("source") or "").startswith("supervisor/"):
                raise BridgeCommandError(
                    "RECONCILE_EVIDENCE_INVALID",
                    "external stop evidence must come from the supervisor channel",
                )
            from dcc_task_runtime.owned_process import read_receipt
            binding = lifecycle_fact.get("supervisor_binding") or {}
            if not binding.get("directory") or not isinstance(binding.get("identity"), dict):
                raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "STARTED fact has no owned supervisor binding")
            try:
                observed = read_receipt(binding["directory"], "stopped", identity=binding["identity"])
            except (OSError, ValueError, KeyError) as exc:
                raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "owned supervisor receipt is invalid") from exc
            if (not observed or observed.get("pid") != lifecycle_fact.get("pid")
                    or observed.get("identity", {}).get("task_id") != str(task_id)
                    or evidence.get("supervisor_receipt") != observed
                    or evidence.get("exit_code") != observed.get("exit_code")):
                raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "owned supervisor has not observed this host stop")

        else:
            raise BridgeCommandError(
                "RECONCILE_EVIDENCE_INVALID",
                "stop evidence requires a persisted controller-confirmed stop receipt",
            )
        if not str(evidence.get("process_generation") or "").strip() or not str(evidence.get("process_identity") or "").strip():
            raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "stop evidence must identify the owned process")
        process = record.get("process") if isinstance(record.get("process"), dict) else {}
        attempt = record.get("attempt") if isinstance(record.get("attempt"), dict) else {}
        expected_generation = str(
            process.get("process_generation")
            or attempt.get("process_generation")
            or record.get("claimed_by_generation")
            or ""
        )
        expected_identity = str(
            process.get("process_identity")
            or attempt.get("process_identity")
            or ""
        )
        if not expected_generation or not expected_identity:
            raise BridgeCommandError(
                "RECONCILE_EVIDENCE_INVALID",
                "the operation has no persisted attempt-bound process identity",
            )
        if not hmac.compare_digest(str(evidence.get("process_generation") or ""), expected_generation):
            raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "stop evidence process generation does not match the attempt")
        if not hmac.compare_digest(str(evidence.get("process_identity") or ""), expected_identity):
            raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "stop evidence process identity does not match the attempt")
        if evidence.get("pid") is not None and str(evidence.get("pid")) != str(process.get("pid") or ""):
            raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "stop evidence pid does not match the attempt")
        if evidence.get("attempt_id") is not None:
            expected_attempt = str(attempt.get("attempt_id") or record.get("execution_id") or "")
            if str(evidence.get("attempt_id")) != expected_attempt:
                raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "stop evidence belongs to a different execution attempt")
        if type(evidence.get("exit_code")) is not int:
            raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "stop evidence needs the integer process exit code")
    else:
        if lifecycle_fact.get("kind") != "NOT_STARTED" or lifecycle_fact.get("side_effect_started") is not False:
            raise BridgeCommandError(
                "RECONCILE_EVIDENCE_INVALID",
                "not-started evidence conflicts with the persisted lifecycle fact",
            )
        if evidence.get("side_effect_started") is not False or record.get("frames_done"):
            raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "not-started evidence conflicts with recorded execution")
        if record.get("in_flight_frame") is not None:
            raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "an in-flight frame cannot be declared not started")
    return dict(evidence)


def _fx_controlled_output_readback(node, settings, color_fact, frame, scene_contract, policy, project_color):
    """Read a restricted saved scene and output route; never infer writer internals."""
    import hou
    from houdini_bridge.controlled_output import validate_controlled_policy, controlled_route_sha256
    policy = validate_controlled_policy(policy)
    frozen = (scene_contract or {}).get('frozen_scene_parameters') or {}
    roles = {item['role']: item['path'] for item in (scene_contract or {}).get('nodes', [])}
    if (frozen.get('profile') != policy['scene_variant'] or roles.get('render') != node.path()
            or not isinstance(project_color, dict)):
        raise BridgeCommandError('CONTROLLED_OUTPUT_SCENE_REQUIRED', 'requires the verified frozen sphere_ground_v2 scene')
    native = hou.node(roles.get('settings', ''))
    expected_type = ('Lop/karmarenderproperties' if policy['scene_variant'] == 'official_karma_disklight_v1' else 'Lop/karmarendersettings')
    if frame not in policy['frames'] or native is None or native.type().nameWithCategory() != expected_type:
        raise BridgeCommandError('CONTROLLED_OUTPUT_CONFIG_READBACK_REQUIRED', 'saved Karma settings node is missing')
    wanted = {'resolution': policy['resolution'], 'engine': 'cpu', 'denoiser': 'off', 'enablemblur': 0}
    observed = {}
    for name, expected in wanted.items():
        parm = _resolve_parm_target(native, [name])
        if parm is None or _parm_snapshot_is_driven(_snapshot_parm_state(parm)):
            raise BridgeCommandError('CONTROLLED_OUTPUT_CONFIG_READBACK_REQUIRED', name)
        value = _json_safe(_read_parm_for_request(parm, expected))
        if not _values_match(expected, value) or frozen.get('fields', {}).get('settings.' + name) != value:
            raise BridgeCommandError('CONTROLLED_OUTPUT_CONFIG_OUTSIDE_POLICY', name)
        observed[name] = value
    resolution = settings.GetAttribute('resolution')
    if not resolution or list(resolution.Get(frame)) != policy['resolution']:
        raise BridgeCommandError('CONTROLLED_OUTPUT_CONFIG_OUTSIDE_POLICY', 'composed USD resolution differs')
    relation = settings.GetRelationship('husk:orderedImageFilters')
    attribute = settings.GetAttribute('husk:orderedImageFilters')
    if ((relation and (list(relation.GetTargets()) or list(relation.GetForwardedTargets())))
            or attribute):
        raise BridgeCommandError('CONTROLLED_OUTPUT_CONFIG_OUTSIDE_POLICY', 'extra image filters are not permitted')
    products = color_fact.get('products') or []
    if len(products) != 1 or products[0].get('attributes', {}).get('productType', {}).get('value') != 'raster':
        raise BridgeCommandError('CONTROLLED_OUTPUT_CONFIG_OUTSIDE_POLICY', 'one raster beauty product required')
    output_color_route = {'source': 'scene_linear', 'output': 'ACEScg'}
    if project_color.get('colorspace') != output_color_route['output']:
        raise BridgeCommandError('CONTROLLED_OUTPUT_CONFIG_OUTSIDE_POLICY', 'controlled output color selection differs')
    for key, expected in [('source_colorspace', output_color_route['source']),
                          ('output_colorspace', output_color_route['output'])]:
        attribute = products[0].get('attributes', {}).get('driver:parameters:husk:' + key, {})
        if (attribute.get('present') is not True or attribute.get('authored') is not True
                or attribute.get('type_name') != 'string' or attribute.get('value') != expected):
            raise BridgeCommandError('CONTROLLED_OUTPUT_CONFIG_OUTSIDE_POLICY', 'native output color attribute differs: ' + key)
    variables = products[0].get('vars') or []
    if len(variables) != 1:
        raise BridgeCommandError('CONTROLLED_OUTPUT_CONFIG_OUTSIDE_POLICY', 'one standard beauty variable required')
    attrs = variables[0].get('attributes') or {}
    expected_var = {'sourceName': 'C.*[LO]', 'sourceType': 'lpe', 'dataType': 'color4f',
                    'driver:parameters:aov:husk:name': 'C'}
    if any(attrs.get(name, {}).get('value') != value for name, value in expected_var.items()):
        raise BridgeCommandError('CONTROLLED_OUTPUT_CONFIG_OUTSIDE_POLICY', 'standard Karma beauty LPE is required')
    identity = _host_identity()
    result = {'scene_variant': policy['scene_variant'], 'resolution': observed['resolution'],
              'denoiser': observed['denoiser'], 'motion_blur': False, 'image_filters': [],
              'products': [{'kind': 'beauty', 'channels': list(policy['channels']), 'multipart': False}],
              'houdini_version': hou.applicationVersionString(), 'plugin_build': identity.get('plugin_build'),
              'renderer': node.parm('renderer').evalAtFrame(frame), 'colorspace': project_color['colorspace'],
              'output_color_route': output_color_route,
              'aov_semantics': 'karma_beauty_lpe_v1'}
    result['route_sha256'] = controlled_route_sha256(result)
    return result


def _fx_exr_attribute_value(product, key, expected_type, frame):
    context = {"exists": None, "usd_type": None, "value_type": None, "value": None}
    try:
        attribute = product.GetAttribute("driver:parameters:husk:OpenEXR:" + key)
        context["exists"] = bool(attribute)
        if not attribute:
            raise ValueError("EXR attribute is missing")
        context["usd_type"] = str(attribute.GetTypeName())[:80]
        actual = attribute.Get(frame)
        context["value_type"] = type(actual).__name__[:80]
        if actual is None or type(actual) in (str, bool, int, float):
            context["value"] = str(actual)[:160]
        if key == "multipart" and expected_type == "int":
            if context["usd_type"] == "bool" and type(actual) is bool and actual is False:
                return 0
            if context["usd_type"] == "int" and type(actual) is int and actual == 0:
                return actual
            raise ValueError("unsupported EXR multipart type or value")
        if context["usd_type"] != expected_type:
            raise ValueError("unsupported EXR attribute type")
        return actual
    except Exception as error:
        raise BridgeCommandError("RENDER_CONFIG_INVALID", "EXR product format is unreadable: " + key
                                 + ": observed=" + repr(context)) from error


def _fx_active_scene_contract_for_record(task_id, scene_ref):
    """Re-load the persisted active-scene contract a render record refers to.

    The record stores only the scene reference (paths, digests, identity);
    the full contract is re-read from the durable saves store and bound to
    that reference, so a drift between record and persisted evidence fails
    closed instead of trusting an embedded copy.
    """
    saves = json.loads(_fx_task_saves_path(task_id).read_text(encoding="utf-8"))
    active = saves.get("active_scene") or {}
    contract = active.get("scene_contract")
    if (not isinstance(contract, dict)
            or active.get("snapshot_sha256") != scene_ref.get("snapshot_sha256")
            or active.get("sha256") != scene_ref.get("sha256")
            or active.get("identity") != scene_ref.get("identity")
            or scene_ref.get("scene_contract_sha256") != _fx_scene_contract_digest(contract)):
        raise BridgeCommandError("SCENE_STATE_DRIFT", "persisted active scene no longer matches the render record")
    return contract


def _fx_render_configuration(node, frames, *, output_pattern=None, read_budget=None, project_color=None,
                             output_acceptance=None, scene_contract=None):
    """Read actual H21/H22 USD render configuration; no scene authoring."""
    import hou
    from houdini_bridge.render_observation_budget import (
        ConfigurationObservationBudget, FileReadBudget, RenderObservationLimit,
    )
    observation_budget = ConfigurationObservationBudget()
    read_budget = read_budget if read_budget is not None else FileReadBudget()
    if node is None or not isinstance(node, hou.RopNode) or node.type().nameWithCategory() != "Driver/usdrender":
        raise BridgeCommandError("RENDER_TARGET_UNSUPPORTED", "requires Driver/usdrender")
    version = hou.applicationVersion()[0]
    renderer_name = "renderer" if version in {21, 22} else None
    if renderer_name is None:
        raise BridgeCommandError("HOUDINI_VERSION_UNSUPPORTED", "render supports H21/H22")
    result = {}
    for frame in frames:
        values = {}
        for name in ("loppath", "rendersettings", "override_camera", renderer_name):
            parm = node.parm(name)
            if parm is None:
                raise BridgeCommandError("RENDER_CONFIG_INVALID", "required native render parameter missing: " + name)
            actual = parm.evalAtFrame(frame)
            if not isinstance(actual, str) or (name == renderer_name and not actual.strip()):
                raise BridgeCommandError("RENDER_CONFIG_INVALID", "native render parameter has wrong value type: " + name)
            values[name] = actual
        lop = hou.node(values["loppath"])
        if lop is None or not isinstance(lop, hou.LopNode):
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "explicit source LOP is required")
        stage = lop.stage(frame=frame, apply_viewport_overrides=False, ignore_errors=False)
        settings = stage.GetPrimAtPath(values["rendersettings"])
        if not settings or settings.GetTypeName() != "RenderSettings":
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "explicit RenderSettings prim is required")
        from houdini_bridge.render_color_facts import (
            MAX_OBSERVATION_VALUES, MAX_TARGETS, _path, collect_render_color_facts,
        )
        try:
            color_fact = collect_render_color_facts(
                stage, frame=frame, settings_path=values["rendersettings"],
                operation_budget=observation_budget)
        except ValueError as error:
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "USD output observation is invalid or exceeds its budget") from error
        observed_settings = color_fact.get("settings")
        products = (observed_settings or {}).get("products", {}).get("forwarded_targets", [])
        captured_products = color_fact["products"]
        if (len(products) != 1 or len(captured_products) != 1
                or captured_products[0]["path"] != products[0]):
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "bounded render requires one fully observed RenderProduct")
        observed_product = captured_products[0]
        product = stage.GetPrimAtPath(products[0])
        output_format = {}
        for key, expected_type, value_type, permitted in (
            ("storage", "string", str, {"scanline"}),
            ("multipart", "int", int, {0}),
            ("compression", "string", str, {"none", "zips", "zip"}),
        ):
            actual = _fx_exr_attribute_value(product, key, expected_type, frame)
            if type(actual) is not value_type or actual not in permitted:
                raise BridgeCommandError("RENDER_CONFIG_INVALID", "EXR product format is unsupported: " + key)
            output_format[key] = actual
        cameras = observed_settings["camera"]["forwarded_targets"]
        camera = values["override_camera"] or (cameras[0] if len(cameras) == 1 else "")
        prim = stage.GetPrimAtPath(camera)
        if not prim or prim.GetTypeName() != "Camera":
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "actual camera is missing")
        aovs = observed_product["ordered_vars"]["forwarded_targets"]
        if not aovs or [item["path"] for item in observed_product["vars"]] != aovs:
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "fully observed RenderVars are required")
        lights = []
        try:
            for index, prim in enumerate(stage.Traverse()):
                if index >= MAX_OBSERVATION_VALUES:
                    raise ValueError("native prim traversal exceeds observation limit")
                if str(prim.GetTypeName()).endswith("Light"):
                    if len(lights) >= MAX_TARGETS:
                        raise ValueError("native light count exceeds observation limit")
                    lights.append(_path(prim.GetPath()))
        except Exception as error:
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "native light observation failed or exceeds its budget") from error
        lights.sort()
        if not lights:
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "actual scene light is required")
        values.update({"camera": camera, "lights": lights, "products": products, "aovs": aovs,
                       "exr_format": output_format,
                       "default_renderer_environment": str(os.environ.get("HOUDINI_HUSK_DEFAULT_DELEGATE") or "")})
        values["color_configuration_fact"] = color_fact
        if output_acceptance is not None:
            values['controlled_output_readback'] = _fx_controlled_output_readback(
                node, settings, color_fact, frame, scene_contract, output_acceptance, project_color)
        if project_color is not None:
            from dcc_task_runtime.project_color import validate_project_color
            values["project_color"] = validate_project_color(project_color)
        if output_pattern is not None and project_color is None:
            from dcc_task_runtime.artifact_registry import frame_path
            from houdini_bridge.render_ocio_facts import (
                MAX_MISSING_FACTS, MAX_TRANSFORM_REQUESTS, collect_ocio_configuration)

            requests = []
            for configured_product in values["color_configuration_fact"]["products"]:
                observations = [(configured_product, "driver:parameters:husk:")]
                observations.extend((variable, "driver:parameters:aov:husk:")
                                    for variable in configured_product["vars"])
                for observation, prefix in observations:
                    source = observation["attributes"].get(prefix + "source_colorspace", {}).get("value")
                    destination = observation["attributes"].get(prefix + "output_colorspace", {}).get("value")
                    if isinstance(source, str) and source and isinstance(destination, str) and destination:
                        requests.append({"label": observation["path"], "source": source,
                                         "destination": destination})
            try:
                ocio = collect_ocio_configuration(
                    hou, final_output_path=str(frame_path(output_pattern, frame)),
                    transform_requests=requests[:MAX_TRANSFORM_REQUESTS], read_budget=read_budget)
            except RenderObservationLimit as error:
                raise BridgeCommandError("RENDER_OBSERVATION_BUDGET_EXCEEDED", str(error)) from error
            omitted = len(requests) - MAX_TRANSFORM_REQUESTS
            if omitted > 0:
                api = "raw_usd.transform_requests.omitted"
                ocio["api_facts"][api] = {"observed": True, "value": omitted}
                ocio["missing_facts"].insert(0, {"code": "PROCESSOR_REQUEST_BUDGET_EXCEEDED", "api": api})
                del ocio["missing_facts"][MAX_MISSING_FACTS:]
            values["ocio_configuration_fact"] = ocio
        try:
            # Include the fixed-size digest before the unbounded native stage export.
            observation_budget.reserve_configuration({str(frame): {**values, "usd_sha256": "0" * 64}})
        except RenderObservationLimit as error:
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "all-frame render configuration exceeds its observation budget") from error
        values["usd_sha256"] = hashlib.sha256(stage.ExportToString().encode("utf-8")).hexdigest()
        result[str(frame)] = values
    return result


def _fx_render_execution_fact(record):
    from houdini_bridge.client import render_execution_fact
    return render_execution_fact(record)


class OperationRunner:
    """Persistent frame operations built on the durable execution lock.

    Identities: ``request_id`` binds the model request (task + subject +
    frames); ``execution_id`` names one actual execution attempt;
    ``claimed_by_generation`` records which host generation holds the work.
    The heavy slot is the installation-wide GraphScheduler reservation
    (shared with Nuke and the graph flow) held from submit until an observed
    terminal state; a crashed host leaves it blocked for control-side
    release, never silently available. ``status`` is a pure read — only the
    serve loop's ``advance()`` claims, cooks or reconciles.
    """

    def __init__(self, task_id: str, store_root: "Optional[Path]" = None) -> None:
        self.task_id = str(task_id)
        self.store_root = Path(store_root) if store_root else _fx_operations_store_path(self.task_id).parent
        self.path = _fx_operations_store_path(self.task_id)
        self.generation = _fx_host_generation()
        self._in_cook = False

    # ---- durable lock ----------------------------------------------------
    @contextmanager
    def _locked(self):
        with _durable_execution_lock(self.store_root, self.task_id):
            yield

    # ---- installation heavy slot (GraphScheduler-backed, shared with Nuke) ----
    def _acquire_slot(self, request_id: str) -> dict[str, Any]:
        """Reserve the single installation heavy slot for this operation.

        The reservation stays active until an observed terminal state releases
        it (or the control plane releases with evidence); a crashed host
        leaves it blocked rather than silently available.
        """
        try:
            permit = _fx_graph_scheduler().reserve(str(self.path), request_id)
        except ValueError as exc:  # SchedulerBusy subclasses ValueError
            raise BridgeCommandError("HEAVY_SLOT_BUSY", str(exc),
                                     "One heavy operation per installation at a time; query or cancel the active one first.") from exc
        return {"owner_root": str(self.path), "operation_id": request_id,
                "token": str(permit["token"]), "generation": int(permit["generation"])}

    def _fence_slot(self, record: dict[str, Any]) -> None:
        """Prove this record still owns the installation slot before cooking."""
        slot = record.get("slot") or {}
        if not slot.get("owner_root"):
            raise BridgeCommandError("HEAVY_SLOT_LOST",
                                     "operation {} has no installation slot reservation".format(record.get("request_id")),
                                     "The control plane must requeue the operation with a fresh reservation.")
        try:
            _fx_graph_scheduler().owned(slot["owner_root"], slot["operation_id"], slot["token"])
        except ValueError as exc:
            raise BridgeCommandError("HEAVY_SLOT_LOST", str(exc),
                                     "The slot was released or taken over; the record is fenced against execution.") from exc

    def _release_slot(self, record: dict[str, Any], *, stopped: bool = True) -> None:
        slot = record.get("slot") or {}
        if not (slot.get("owner_root") and slot.get("operation_id") and slot.get("token")):
            return
        try:
            _fx_graph_scheduler().release(slot["owner_root"], slot["operation_id"], slot["token"], stopped=stopped)
        except ValueError:
            pass  # already released or rotated by the control plane

    # ---- store -----------------------------------------------------------
    def _load(self) -> dict[str, Any]:
        from houdini_bridge.render_observation_budget import (
            RenderObservationLimit, read_store_payload, validate_store,
        )
        blocked = self.path.with_name(self.path.name + ".corrupt-blocked")
        if blocked.is_file():
            # Corruption blocks REPEATEDLY and across restarts: a process exit
            # proves nothing about what ran before, so only a control-side
            # resolve clears the block; the store is never treated as empty.
            raise BridgeCommandError("CORRUPT_STORE",
                                     "operation store for task {} stays blocked; unreadable record preserved at {}".format(self.task_id, blocked),
                                     "A control-side resolve_corrupt_store with verification evidence is required before any submit.")
        if not self.path.is_file():
            legacy = _fx_legacy_operations_store_path(self.task_id)
            if legacy.is_file():
                # Pre-hardening stores keep ambiguous identity: block, never
                # auto-merge or auto-upgrade them into valid evidence.
                raise BridgeCommandError("LEGACY_STORE_AMBIGUOUS",
                                         "task {} has a pre-hardening store at {}; task identity is ambiguous".format(self.task_id, legacy),
                                         "Reconcile the legacy store explicitly before submitting new work.")
            return {}
        try:
            store = json.loads(read_store_payload(self.path))
            validate_store(store)
        except RenderObservationLimit as exc:
            raise BridgeCommandError("RENDER_OBSERVATION_BUDGET_EXCEEDED", str(exc),
                                     "The original store is preserved; archive completed records through a trusted maintenance workflow before retrying.") from exc
        except (ValueError, OSError, RecursionError) as exc:
            preserved = self.path.with_name(self.path.name + ".corrupt-" + uuid4().hex[:8])
            location = str(self.path)
            try:
                os.replace(self.path, preserved)
                location = str(preserved)
            except OSError:
                pass
            try:
                blocked.write_text(json.dumps({
                    "blocked_at": datetime.now(timezone.utc).isoformat(),
                    "generation": self.generation,
                    "preserved_record": location,
                    "task_id": str(self.task_id),
                }, ensure_ascii=False, indent=1), encoding="utf-8")
            except OSError:
                pass
            raise BridgeCommandError("CORRUPT_STORE",
                                     "operation store for task {} is unreadable; original preserved at {} and the store stays blocked".format(self.task_id, location),
                                     "Reconcile the preserved record via resolve_corrupt_store; nothing was treated as empty.") from exc
        recorded = str(store.get("task_id") or "")
        if recorded and recorded != str(self.task_id):
            raise BridgeCommandError("TASK_IDENTITY_CONFLICT",
                                     "store {} was created for task {}, not {}".format(self.path.name, recorded, self.task_id),
                                     "Distinct tasks never share a store; verify which task owns this record.")
        return store

    def _save(self, store: dict[str, Any]) -> None:
        from houdini_bridge.operation_store import write_snapshot
        from houdini_bridge.render_observation_budget import RenderObservationLimit
        try:
            write_snapshot(self.path, store)
        except RenderObservationLimit as exc:
            raise BridgeCommandError("RENDER_OBSERVATION_BUDGET_EXCEEDED", str(exc)) from exc
        self._journal(store)

    def _record(self, store, operation_id, *, family="operations"):
        from houdini_bridge.operation_store import resolve_record
        try:
            return resolve_record(self.path, store, operation_id, family=family)
        except (ValueError, OSError, RecursionError) as exc:
            raise BridgeCommandError("OPERATION_ARCHIVE_INVALID", str(exc)) from exc

    def compact_store(self, authorization, note=""):
        verified_by = _verify_control_authorization("compact_store", {"task_id": str(self.task_id)}, authorization)
        from houdini_bridge.operation_store import compact_store
        from houdini_bridge.render_observation_budget import RenderObservationLimit
        with self._locked():
            if self.path.with_name(self.path.name + ".corrupt-blocked").exists():
                raise BridgeCommandError("CORRUPT_STORE", "corruption must be reconciled before capacity maintenance")
            try:
                result = compact_store(self.path, self.task_id)
            except RenderObservationLimit as exc:
                raise BridgeCommandError("RENDER_OBSERVATION_BUDGET_EXCEEDED", str(exc)) from exc
            except (ValueError, OSError, RecursionError) as exc:
                raise BridgeCommandError("STORE_MAINTENANCE_FAILED", str(exc)) from exc
        return {**result, "verified_by": verified_by, "note": str(note)}

    def resolve_corrupt_store(self, authorization: Any, note: str = "") -> dict[str, Any]:
        """Control-channel only: clear a corruption block after verification.

        Never exposed to model dispatch. Handles both the persistent block
        marker and an as-yet-unloaded unreadable store file; the preserved
        corrupt record is kept (renamed to ``.corrupt-resolved-<hex>``) —
        resolving archives the evidence, it does not delete it.
        """
        verified_by = _verify_control_authorization("resolve_corrupt_store", {"task_id": str(self.task_id)}, authorization)
        blocked = self.path.with_name(self.path.name + ".corrupt-blocked")
        marker_present = blocked.is_file()
        unreadable = False
        if not marker_present and self.path.is_file():
            try:
                json.loads(self.path.read_text(encoding="utf-8"))
            except (ValueError, OSError):
                unreadable = True
        if not marker_present and not unreadable:
            raise BridgeCommandError("NO_CORRUPT_BLOCK", "task {} is not corruption-blocked".format(self.task_id))
        if marker_present:
            resolved = blocked.with_name(blocked.name[: -len(".corrupt-blocked")] + ".corrupt-resolved-" + uuid4().hex[:8])
            os.replace(blocked, resolved)
        else:
            resolved = self.path.with_name(self.path.name + ".corrupt-resolved-" + uuid4().hex[:8])
            os.replace(self.path, resolved)
        with self._locked():
            store = self._load() if self.path.is_file() else {}
            store["corruption_resolved"] = {"verified_by": str(verified_by), "note": str(note or ""),
                                            "resolved_at": datetime.now(timezone.utc).isoformat(),
                                            "evidence": str(resolved)}
            if self.path.is_file():
                self._save(store)
        return {"resolved": True, "evidence": str(resolved)}

    # ---- recovery protocol: orphan discovery + authorized control release --
    def _write_attempt_marker(self, path, payload):
        from dcc_task_runtime.platform_support import atomic_write
        atomic_write(path, json.dumps(payload, ensure_ascii=False, sort_keys=True,
                                     allow_nan=False).encode("utf-8"), owned_root=path.parent)

    def _read_recovery_marker(self, path):
        from houdini_bridge.render_observation_budget import read_store_payload
        marker = json.loads(read_store_payload(path))
        if type(marker) is not dict:
            raise ValueError("recovery marker must be a JSON object")
        return marker

    def _matching_orphan_attempt(self, slot):
        owner = Path(str(slot.get("owner_root") or ""))
        if owner.parent != self.store_root:
            return None
        path = owner.with_suffix(".attempt.json")
        try:
            marker = self._read_recovery_marker(path)
        except (ValueError, OSError, RecursionError):
            return None
        bound = marker.get("slot")
        if (type(marker.get("task_id")) is not str or not marker["task_id"]
                or marker.get("request_id") != slot.get("operation_id")
                or type(marker.get("request_sha256")) is not str
                or not re.fullmatch(r"[0-9a-f]{64}", marker["request_sha256"])
                or _fx_operations_store_path(marker["task_id"]) != owner):
            return None
        if bound is None:
            # Reserve may commit before the returned token reaches the marker.
            # Only the scheduler's exact still-RESERVED permit can prove non-dispatch.
            if (marker.get("phase") != "intent" or slot.get("phase") != "RESERVED"
                    or slot.get("process_json") is not None):
                return None
        elif (type(bound) is not dict or any(bound.get(key) != slot.get(key) for key in
                ("owner_root", "operation_id", "token", "generation"))):
            return None
        return path, marker

    def _orphan_host_stopped(self, slot, marker):
        from dcc_task_runtime.owned_process import read_receipt, _canonical
        host = marker.get("host_identity")
        binding = marker.get("supervisor_binding")
        if (type(host) is not dict or type(binding) is not dict
                or type(binding.get("identity")) is not dict or not binding.get("directory")
                or host.get("task_id") != marker.get("task_id")
                or binding["identity"].get("task_id") != marker.get("task_id")
                or not host.get("launch_nonce")
                or binding["identity"].get("launch_nonce") != host["launch_nonce"]):
            return False
        try:
            process = json.loads(slot["process_json"]) if slot.get("process_json") else None
            if process is not None and process != {"host_identity": host, "supervisor_binding": binding}:
                return False
            started = read_receipt(binding["directory"], "started", identity=binding["identity"])
            stopped = read_receipt(binding["directory"], "stopped", identity=binding["identity"])
            return bool(started and stopped and started.get("pid") == host.get("pid")
                        and stopped.get("pid") == host.get("pid")
                        and marker.get("supervisor_started_sha256") == hashlib.sha256(_canonical(started)).hexdigest()
                        and stopped.get("started_sha256") == marker["supervisor_started_sha256"])
        except (ValueError, OSError, RecursionError, KeyError, TypeError):
            return False

    def discover_orphans(self) -> dict[str, Any]:
        """Read-only recovery scan across this installation.

        Kinds: ``uncommitted_attempt`` (attempt marker without reservation or
        record), ``reserved_without_record`` (active reservation whose record
        never committed), ``terminal_without_release`` (record reached an
        observed terminal state but the slot is still active) and
        ``unknown_active`` (active reservation with no matching evidence —
        stays blocked until the control plane decides).  Queries NEVER start
        jobs, treat unknowns as stopped, or release anything.
        """
        scheduler = _fx_graph_scheduler()
        snapshot = scheduler.snapshot()
        orphans: list[dict[str, Any]] = []
        slot = dict(snapshot) if snapshot else None
        records = {}
        blocked_stores = set()
        for marker in self.store_root.glob("ops_*.json.corrupt-blocked"):
            owner = str(marker)[:-len(".corrupt-blocked")]
            blocked_stores.add(owner)
            orphans.append({"kind": "corruption_blocked", "task_store": owner,
                            "evidence": "persistent corruption marker; source evidence is preserved"})
        from houdini_bridge.render_observation_budget import read_store_payload, validate_store
        for store_file in sorted(self.store_root.glob("ops_*.json")):
            if store_file.name.endswith((".attempt.json", ".requeue-phase.json")):
                continue
            try:
                data = json.loads(read_store_payload(store_file))
                validate_store(data)
                if slot and str(store_file) == slot.get("owner_root"):
                    from houdini_bridge.operation_store import resolve_record
                    selected = str(slot.get("operation_id") or "")
                    record = resolve_record(store_file, data, selected)
                    if record is not None:
                        data["operations"][selected] = record
            except (ValueError, OSError, RecursionError) as error:
                blocked_stores.add(str(store_file))
                orphans.append({"kind": "corruption_blocked", "task_store": str(store_file),
                                "error_type": type(error).__name__,
                                "evidence": "unreadable, invalid or over-budget store preserved; not an empty store"})
                continue
            for request_id, record in data.get("operations", {}).items():
                records[(str(store_file), str(request_id))] = dict(record)
        if slot and slot.get("active"):
            op_id = str(slot.get("operation_id") or "")
            owner = str(slot.get("owner_root") or "")
            record = records.get((owner, op_id))
            # C1: a record whose bound slot generation differs from the ACTIVE
            # slot means an interrupted requeue rotation (record token is stale)
            if str(slot.get("owner_root")) in blocked_stores:
                orphans.append({"kind": "corruption_blocked", "operation_id": op_id,
                                "task_store": str(slot.get("owner_root")),
                                "evidence": "active owner store is unreadable; stop remains unknown"})
            elif (record is not None and record.get("state") == "RECONCILE"
                    and int((record.get("slot") or {}).get("generation") or 0) != int(slot.get("generation") or 0)):
                orphans.append({"kind": "requeue_interrupted", "operation_id": op_id,
                                "task_store": owner, "record_slot_generation": (record.get("slot") or {}).get("generation"),
                                "active_slot_generation": slot.get("generation"),
                                "evidence": "record exists but its slot no longer matches the active reservation"})
            elif record is not None and record.get("state") in ("COMPLETED", "FAILED", "CANCELLED", "BUDGET_REACHED", "SUPERSEDED"):
                orphans.append({"kind": "terminal_without_release", "operation_id": op_id,
                                "task_store": owner, "record_state": record.get("state"),
                                "evidence": "record reached an observed terminal state; release requires control authorization"})
            elif record is None:
                attempt = self._matching_orphan_attempt(slot)
                never_dispatched = bool(attempt and attempt[1].get("phase") in {"intent", "reserved"}
                    and slot.get("phase") in {"RESERVED", "FENCED_UNSTARTED"}
                    and slot.get("process_json") is None)
                stopped = bool(attempt and slot.get("phase") == "DISPATCHING"
                               and self._orphan_host_stopped(slot, attempt[1]))
                orphans.append({"kind": "reserved_without_record" if never_dispatched else
                                "stopped_preflight_without_record" if stopped else "unknown_active",
                                "operation_id": op_id, "owner_root": slot.get("owner_root"),
                                "attempt_files": [attempt[0].name] if attempt else [],
                                "evidence": "exact permit can be fenced before dispatch" if never_dispatched else
                                            "owned supervisor observed this preflight host exit" if stopped else
                                            "attempt is not stop evidence; active work remains blocked"})
        for phase_file in sorted(self.store_root.glob("*.requeue-phase.json")):
            try:
                marker = self._read_recovery_marker(phase_file)
            except (ValueError, OSError, RecursionError):
                orphans.append({"kind": "corruption_blocked", "marker_file": str(phase_file),
                                "evidence": "invalid recovery marker preserved"})
                continue
            orphans.append({"kind": "requeue_phase_interrupted", "phase_file": str(phase_file.name),
                            "request_id": marker.get("request_id"), "phase": marker.get("phase"),
                            "old_slot_generation": marker.get("old_slot_generation"),
                            "new_slot_generation": marker.get("new_slot_generation"),
                            "evidence": "requeue transaction did not commit"})
        for attempt_file in sorted(self.store_root.glob("*.attempt.json")):
            try:
                marker = self._read_recovery_marker(attempt_file)
            except (ValueError, OSError, RecursionError):
                orphans.append({"kind": "corruption_blocked", "marker_file": str(attempt_file),
                                "evidence": "invalid attempt marker preserved"})
                continue
            orphans.append({"kind": "uncommitted_attempt", "attempt_file": str(attempt_file.name),
                            "request_id": marker.get("request_id"),
                            "evidence": "reserve->record never committed; harmless residual marker"})
        return {"orphans": orphans, "slot_active": bool(slot and slot.get("active"))}

    def release_orphan(self, operation_id: str, authorization: Any, note: str = "") -> dict[str, Any]:
        """Control-channel only: release ONE proven orphan reservation.

        Accepted only with a signed control authorization and only for a
        reservation whose evidence was listed by discover_orphans.  Unknown
        reservations are never released here — they need real reconciliation.
        """
        verified_by = _verify_control_authorization("release_orphan",
                                                    {"operation_id": str(operation_id), "task_id": str(self.task_id)},
                                                    authorization)
        scheduler = _fx_graph_scheduler()
        snapshot = scheduler.snapshot()
        if (not snapshot or not snapshot.get("active")
                or str(snapshot.get("operation_id") or "") != str(operation_id)):
            raise BridgeCommandError("ORPHAN_GONE", "the reservation is no longer active")
        if snapshot.get("owner_root") != str(self.path):
            raise BridgeCommandError("ORPHAN_NOT_RELEASABLE", "reservation belongs to another task")
        report = self.discover_orphans()
        listed = [o for o in report["orphans"] if o.get("operation_id") == str(operation_id)]
        if not listed or listed[0].get("kind") not in (
                "terminal_without_release", "reserved_without_record", "stopped_preflight_without_record"):
            raise BridgeCommandError("ORPHAN_NOT_RELEASABLE",
                                     "operation {} is not a proven releasable orphan".format(operation_id),
                                     "Unknown reservations require actual reconciliation, not a release.")
        current = scheduler.snapshot()
        if (not current or not current.get("active") or any(current.get(key) != snapshot.get(key)
                for key in ("owner_root", "operation_id", "token", "generation"))):
            raise BridgeCommandError("ORPHAN_GONE", "orphan permit changed during verification")
        if current.get("owner_root") != str(self.path):
            raise BridgeCommandError("ORPHAN_NOT_RELEASABLE", "reservation belongs to another task")
        kind = listed[0]["kind"]
        attempt = self._matching_orphan_attempt(current)
        if attempt and attempt[1].get("task_id") != self.task_id:
            raise BridgeCommandError("ORPHAN_NOT_RELEASABLE", "attempt belongs to another task")
        if kind == "reserved_without_record":
            if (not attempt or attempt[1].get("phase") not in {"intent", "reserved"}
                    or not scheduler.fence_unstarted(current["owner_root"], operation_id, current["token"])):
                raise BridgeCommandError("ORPHAN_NOT_RELEASABLE", "preflight dispatch has started; stop remains unknown")
            scheduler.release(current["owner_root"], operation_id, current["token"], unstarted=True)
        else:
            if kind == "stopped_preflight_without_record" and (
                    not attempt or not self._orphan_host_stopped(current, attempt[1])):
                raise BridgeCommandError("ORPHAN_NOT_RELEASABLE", "owned supervisor has not observed this preflight host exit")
            scheduler.release(current["owner_root"], operation_id, current["token"], stopped=True)
        if attempt:
            # The old launcher must finish its fenced transition before cleanup;
            # under the same task lock a new attempt cannot be deleted by race.
            with _durable_execution_lock(self.store_root, str(attempt[1]["task_id"])):
                same = self._matching_orphan_attempt(current)
                if same:
                    same[0].unlink(missing_ok=True)
        return {"released": True, "operation_id": str(operation_id), "kind": listed[0]["kind"],
                "verified_by": verified_by, "note": str(note or "")}

    def adopt_requeue(self, operation_id: str, authorization: Any, note: str = "") -> dict[str, Any]:
        """Control-channel only: bind a RECONCILE record to the ACTIVE slot.

        Recovers an interrupted requeue rotation (C1): the fresh reservation
        already exists (evidence: record slot generation mismatch + phase
        file), so adopting it continues the control decision without a new
        side effect and without releasing anything.  Unknown mismatches stay
        blocked; the signature authorizes the decision, the record/phase
        evidence must still match exactly.
        """
        verified_by = _verify_control_authorization(
            "adopt_requeue", {"operation_id": str(operation_id), "task_id": str(self.task_id)}, authorization)
        scheduler = _fx_graph_scheduler()
        snapshot = scheduler.snapshot()
        if not snapshot or not snapshot.get("active") or str(snapshot.get("operation_id") or "") != str(operation_id):
            raise BridgeCommandError("ADOPT_TARGET_GONE", "no active reservation for {}".format(operation_id))
        with self._locked():
            store = self._load()
            record = self._record(store, str(operation_id))
            if record is None or record.get("state") != "RECONCILE":
                raise BridgeCommandError("ADOPT_INVALID", "operation {} is not a RECONCILE record".format(operation_id))
            phase_path = self.path.with_suffix(".requeue-phase.json")
            phase = {}
            if phase_path.is_file():
                try:
                    phase = json.loads(phase_path.read_text(encoding="utf-8"))
                except (ValueError, OSError):
                    raise BridgeCommandError("ADOPT_PHASE_INVALID", "requeue phase evidence is unreadable")
            if not isinstance(phase, dict) or phase.get("phase") != "reserved":
                raise BridgeCommandError(
                    "ADOPT_PHASE_REQUIRED",
                    "adopt_requeue requires a persisted reserved requeue phase; a signature alone cannot adopt unknown work")
            if str(phase.get("request_id") or "") != str(operation_id) or str(phase.get("task_id") or "") != str(self.task_id):
                raise BridgeCommandError("ADOPT_PHASE_INVALID", "requeue phase is bound to a different task or operation")
            old_slot = phase.get("old_slot") if isinstance(phase.get("old_slot"), dict) else {}
            record_slot = record.get("slot") if isinstance(record.get("slot"), dict) else {}
            if any(str(old_slot.get(key)) != str(record_slot.get(key))
                   for key in ("owner_root", "operation_id", "token", "generation")):
                raise BridgeCommandError("ADOPT_PHASE_INVALID", "record does not still reference the phase's old slot")
            phase_slot = phase.get("new_slot") if isinstance(phase.get("new_slot"), dict) else {}
            if any(str(phase_slot.get(key)) != str(snapshot.get(key))
                   for key in ("owner_root", "operation_id", "token", "generation")):
                raise BridgeCommandError("ADOPT_PHASE_INVALID", "active slot does not match the persisted reserved phase")
            if str(phase.get("new_slot_generation")) != str(snapshot.get("generation")):
                raise BridgeCommandError("ADOPT_PHASE_INVALID", "active slot generation does not match the phase")
            phase_resolution = phase.get("reconcile_resolution") if isinstance(phase.get("reconcile_resolution"), dict) else {}
            if phase_resolution.get("decision") != "requeue":
                raise BridgeCommandError("ADOPT_PHASE_INVALID", "requeue phase has no persisted control decision")
            phase_evidence = phase.get("reconcile_evidence")
            if not isinstance(phase_evidence, dict):
                raise BridgeCommandError("ADOPT_PHASE_INVALID", "requeue phase has no persisted stop/not-started evidence")
            validated_evidence = _validate_reconcile_evidence(
                record, str(self.task_id), str(operation_id), phase_evidence)
            prior_resolution = record.get("reconcile_resolution")
            if isinstance(prior_resolution, dict) and prior_resolution and prior_resolution.get("decision") != "requeue":
                raise BridgeCommandError("ADOPT_PHASE_INVALID", "record control decision conflicts with the reserved requeue phase")
            if int((record.get("slot") or {}).get("generation") or 0) == int(snapshot.get("generation") or 0):
                raise BridgeCommandError("ADOPT_UNNECESSARY", "the record already binds the active slot")
            record["reconcile_resolution"] = dict(phase_resolution)
            record["reconcile_evidence"] = validated_evidence
            record["slot"] = {"owner_root": str(snapshot.get("owner_root")), "operation_id": str(operation_id),
                              "token": str(snapshot.get("token")), "generation": int(snapshot.get("generation") or 0)}
            record["lifecycle_fact"] = _new_lifecycle_fact(
                record, kind="NOT_STARTED", source="controller/operation-runner")
            record.setdefault("history", []).append({
                "at": datetime.now(timezone.utc).isoformat(), "note": "requeue rotation adopted by control",
                "generation": self.generation, "adopted_by": verified_by})
            self._set_state(record, "QUEUED", stage="requeued_by_control_adopt")
            record["claimed_by_generation"] = None
            record["in_flight_frame"] = None
            if phase.get("request_id") == str(operation_id) and phase.get("phase") == "reserved":
                phase_path.unlink(missing_ok=True)
            self._save(store)
        return {"adopted": True, "operation_id": str(operation_id), "verified_by": verified_by,
                "slot_generation": int(record["slot"]["generation"]), "note": str(note or "")}

    def resolve_legacy_store(self, authorization: Any, note: str = "") -> dict[str, Any]:
        """Control-channel only: archive a pre-hardening legacy store.

        The legacy store's identity is ambiguous, so it is NEVER merged into
        the current store.  With control evidence the file is archived
        (``.legacy-archived-<hex>``), which lifts the block for THIS task; the
        archived bytes stay on disk as evidence for the reconciliation record.
        """
        verified_by = _verify_control_authorization("resolve_legacy_store", {"task_id": str(self.task_id)}, authorization)
        legacy = _fx_legacy_operations_store_path(self.task_id)
        if not legacy.is_file():
            raise BridgeCommandError("NO_LEGACY_STORE", "task {} has no legacy store".format(self.task_id))
        archived = legacy.with_name(legacy.name + ".legacy-archived-" + uuid4().hex[:8])
        os.replace(legacy, archived)
        with self._locked():
            store = self._load() if self.path.is_file() else {}
            store["legacy_store_resolution"] = {"verified_by": str(verified_by), "note": str(note or ""),
                                                "resolved_at": datetime.now(timezone.utc).isoformat(),
                                                "evidence": str(archived)}
            if self.path.is_file():
                self._save(store)
        return {"resolved": True, "evidence": str(archived)}

    def supervisor_stop_evidence(self, request_id: str) -> dict[str, Any]:
        """Read an exact supervisor observation; never accept a caller path."""
        from dcc_task_runtime.owned_process import read_receipt
        with self._locked():
            record = self._record(self._load(), str(request_id))
            if not record or (record.get("lifecycle_fact") or {}).get("kind") != "STARTED":
                raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "an intact STARTED attempt is required")
            fact = record["lifecycle_fact"]
            binding = fact.get("supervisor_binding") or {}
            if not binding.get("directory"):
                raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "no supervisor owns this host")
            observed = read_receipt(binding["directory"], "stopped", identity=binding["identity"])
            if not observed or observed.get("pid") != fact.get("pid"):
                raise BridgeCommandError("RECONCILE_EVIDENCE_INVALID", "host stop is not observed")
            return {"kind": "confirmed_stop", "task_id": str(self.task_id), "request_id": str(request_id),
                    "slot_generation": fact["slot_generation"], "slot_token": fact["slot_token"],
                    "observed_at": datetime.fromtimestamp(observed["observed_at"], timezone.utc).isoformat(),
                    "source": "supervisor/owned-child-wait", "confirmed": True, "process_exited": True,
                    "stop_confirmed": True, "process_generation": fact["process_generation"],
                    "process_identity": fact["process_identity"], "pid": fact["pid"],
                    "attempt_id": fact["attempt_id"], "exit_code": observed["exit_code"],
                    "lifecycle_fact_digest": fact["fact_digest"], "supervisor_receipt": observed}

    def import_external_stop_fact(self, request_id: str, evidence: Any,
                                  authorization: Any, note: str = "") -> dict[str, Any]:
        """Persist a stop observation supplied by the trusted supervisor.

        This is the positive C1 path for a host whose controller lost its
        process handle.  The supervisor receipt is checked against the exact
        STARTED lifecycle fact and process identity before a new
        ``STOP_CONFIRMED`` fact is written.  Importing the fact does not make
        an archive/requeue decision; that remains the separate control action.
        """
        if not isinstance(evidence, dict):
            raise BridgeCommandError("RECONCILE_EVIDENCE_REQUIRED", "external stop fact must be an object")
        auth_payload = {"task_id": str(self.task_id), "request_id": str(request_id),
                        "evidence": evidence}
        verified_by = _verify_control_authorization("import_stop_fact", auth_payload, authorization)
        with self._locked():
            store = self._load()
            record = self._record(store, str(request_id))
            if record is None:
                raise BridgeCommandError("OPERATION_NOT_FOUND", "no operation {}".format(request_id))
            if record.get("state") != "RECONCILE":
                raise BridgeCommandError("NOT_RECONCILE", "operation {} is {}, not RECONCILE".format(request_id, record.get("state")))
            if (record.get("lifecycle_fact") or {}).get("kind") != "STARTED":
                raise BridgeCommandError(
                    "EXTERNAL_STOP_NOT_STARTED",
                    "external stop import requires the exact persisted STARTED lifecycle fact",
                )
            receipt = _validate_reconcile_evidence(
                record, str(self.task_id), str(request_id), evidence,
                allow_external_stop=True,
            )
            record["exit_code"] = int(receipt["exit_code"])
            fact = _new_lifecycle_fact(
                record,
                kind="STOP_CONFIRMED",
                side_effect_started=True,
                process_exited=True,
                stop_confirmed=True,
                source=str(receipt["source"]),
            )
            # Preserve the supervisor's observation time while keeping the
            # fact digest controller-computed and self-consistent.
            fact["observed_at"] = str(receipt["observed_at"])
            fact["external_supervisor_receipt"] = dict(receipt["supervisor_receipt"])
            fact["fact_digest"] = _lifecycle_fact_digest(fact)
            record["lifecycle_fact"] = fact
            record["stop_confirmed_at"] = str(receipt["observed_at"])
            record["external_stop_import"] = {
                "verified_by": str(verified_by),
                "source": str(receipt["source"]),
                "imported_at": datetime.now(timezone.utc).isoformat(),
                "note": str(note or ""),
            }
            bound_receipt = dict(receipt)
            bound_receipt["lifecycle_fact_digest"] = str(fact["fact_digest"])
            record["reconcile_evidence"] = bound_receipt
            record["stage"] = "stop_confirmed_by_external_supervisor"
            self._save(store)
            return {"imported": True, "operation_id": str(request_id),
                    "verified_by": verified_by, "lifecycle_fact": dict(fact),
                    "reconcile_evidence": dict(bound_receipt),
                    "record": dict(record)}

    def resolve_reconcile(self, request_id: str, decision: str, authorization: Any, note: str = "",
                          evidence: Any = None) -> dict[str, Any]:
        """Control-channel only: decide a RECONCILE record after verification.

        ``decision`` is "archive" (result stays unknown; the record is
        archived and never re-executed) or "requeue" (control verified the
        attempt never ran, so the work returns to QUEUED).  Anything else is
        rejected, and model-submitted params can never reach this path.
        """
        if decision not in ("archive", "requeue"):
            raise BridgeCommandError("INVALID_ARGUMENT", "decision must be archive or requeue")
        auth_payload = {"task_id": str(self.task_id), "request_id": str(request_id), "decision": decision}
        if evidence is not None:
            auth_payload["evidence"] = evidence
        verified_by = _verify_control_authorization("resolve_reconcile", auth_payload, authorization)
        with self._locked():
            store = self._load()
            store.setdefault("task_id", str(self.task_id))
            record = self._record(store, str(request_id))
            if record is None:
                raise BridgeCommandError("OPERATION_NOT_FOUND", "no operation {}".format(request_id))
            if record.get("state") != "RECONCILE":
                raise BridgeCommandError("NOT_RECONCILE", "operation {} is {}, not RECONCILE".format(request_id, record.get("state")))
            receipt = evidence if evidence is not None else record.get("reconcile_evidence")
            receipt = _validate_reconcile_evidence(record, str(self.task_id), str(request_id), receipt)
            record["reconcile_resolution"] = {"decision": decision, "verified_by": str(verified_by),
                                              "note": str(note or ""),
                                              "resolved_at": datetime.now(timezone.utc).isoformat()}
            record["reconcile_evidence"] = receipt
            # The reservation is released only after the separate receipt has
            # proved that this operation did not start or that its owned
            # process stopped.  The HMAC only proves authorization.
            self._release_slot(record)
            if decision == "archive":
                self._set_state(record, "SUPERSEDED")
                record["superseded_by_request"] = "{}#archived".format(request_id)
                record["stage"] = "archived_by_control_reconcile"
                self._terminal(record, store, release_slot=False)
            else:
                # recoverable requeue transaction: register the intent (with
                # the OLD slot generation) BEFORE rotating to the new slot;
                # a crash between reserve and record-commit is discoverable
                phase_path = self.path.with_suffix(".requeue-phase.json")
                phase_path.write_text(json.dumps({
                    "request_id": str(request_id), "task_id": str(self.task_id),
                    "phase": "intent", "old_slot": dict(record.get("slot") or {}),
                    "at": datetime.now(timezone.utc).isoformat()}, ensure_ascii=False, indent=1), encoding="utf-8")
                old_slot_generation = int((record.get("slot") or {}).get("generation") or 0)
                new_slot = self._acquire_slot(str(request_id))  # fresh reservation for the new attempt
                phase_path.write_text(json.dumps({
                    "request_id": str(request_id), "task_id": str(self.task_id),
                    "phase": "reserved", "old_slot_generation": old_slot_generation,
                    "old_slot": dict(record.get("slot") or {}),
                    "reconcile_resolution": dict(record.get("reconcile_resolution") or {}),
                    "reconcile_evidence": dict(record.get("reconcile_evidence") or {}),
                    "new_slot_generation": int(new_slot.get("generation") or 0),
                    "new_slot": dict(new_slot)}, ensure_ascii=False, indent=1), encoding="utf-8")
                self._set_state(record, "QUEUED")
                record["claimed_by_generation"] = None
                record["in_flight_frame"] = None
                record["stage"] = "requeued_by_control_reconcile"
                record["slot"] = new_slot
                record["lifecycle_fact"] = _new_lifecycle_fact(
                record, kind="NOT_STARTED", source="controller/operation-runner")
                self._save(store)
                phase_path.unlink(missing_ok=True)  # record committed: transaction done
            return dict(record)

    def _journal(self, store: dict[str, Any]) -> None:
        try:
            journal = self.path.parent / (self.path.stem + ".jsonl")
            active = [r for r in (store.get("operations") or {}).values()
                      if r.get("state") in ("QUEUED", "RUNNING", "CANCEL_PENDING")]
            entry = {"ts": datetime.now(timezone.utc).isoformat(), "task_id": self.task_id,
                     "generation": self.generation,
                     "active": [{"request_id": r.get("request_id"), "state": r.get("state"),
                                 "frames_done": len(r.get("frames_done") or [])} for r in active]}
            with journal.open("a", encoding="utf-8") as handle:
                handle.write(json.dumps(entry, ensure_ascii=False) + "\n")
        except OSError:
            pass

    # ---- helpers ---------------------------------------------------------
    def _manifest(self) -> tuple[Any, dict[str, Any]]:
        return _fx_manifest(self.task_id)

    def _reconcile_stale(self, store: dict[str, Any]) -> bool:
        """Old-generation RUNNING records hold unknown results: RECONCILE them.

        Returns True when anything changed (caller persists under its lock).
        """
        changed = False
        for record in (store.get("operations") or {}).values():
            if record.get("state") == "RUNNING" and record.get("claimed_by_generation") not in (None, self.generation):
                self._set_state(record, "RECONCILE")
                record["reconcile_reason"] = "claimed by generation {} outlived its process; result unknown".format(
                    record.get("claimed_by_generation"))
                changed = True
        return changed

    def _active(self, store: dict[str, Any]) -> "Optional[dict[str, Any]]":
        for record in (store.get("operations") or {}).values():
            if record.get("state") in ("QUEUED", "RUNNING", "CANCEL_PENDING"):
                return record
        return None

    def _set_state(self, record: dict[str, Any], state: str, *, stage: "Optional[str]" = None,
                   note: "Optional[str]" = None) -> None:
        """Transition a record's state, keeping the FULL execution history.

        Every change is appended to ``record["history"]`` with the acting
        generation; history is never truncated, so recovery and control-side
        reconciliation can audit the whole life of an execution attempt.
        """
        if record.get("state") == state:
            if stage:
                record["stage"] = stage
            return
        record.setdefault("history", []).append({
            "at": datetime.now(timezone.utc).isoformat(),
            "from": record.get("state"),
            "to": state,
            "generation": self.generation,
            "note": str(note or "") or None,
        })
        record["state"] = state
        if stage:
            record["stage"] = stage

    def _bind_execution_attempt(self, record: dict[str, Any]) -> None:
        """Bind a queued requeue to the process that actually claims it."""
        execution_id = uuid4().hex[:12]
        process_generation = str(self.generation)
        process_identity = hashlib.sha256(json.dumps(
            {"pid": os.getpid(), "task_id": str(self.task_id),
             "request_id": str(record.get("request_id") or ""),
             "execution_id": execution_id,
             "process_generation": process_generation},
            ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        ).encode("utf-8")).hexdigest()
        previous = record.get("process") if isinstance(record.get("process"), dict) else {}
        record["execution_id"] = execution_id
        record["process"] = {
            "pid": os.getpid(),
            "port": _SERVER.port if _SERVER else previous.get("port"),
            "session_id": _SERVER.session_id if _SERVER else previous.get("session_id"),
            "process_generation": process_generation,
            "process_identity": process_identity,
        }
        record["attempt"] = {
            "attempt_id": execution_id,
            "process_generation": process_generation,
            "process_identity": process_identity,
            "owner": "houdini-operation-runner",
        }

    def _terminal(self, record: dict[str, Any], store: dict[str, Any], *, release_slot: bool = True) -> None:
        record["finished_at"] = datetime.now(timezone.utc).isoformat()
        if record.get("state") != "RECONCILE":
            record["lifecycle_fact"] = _new_lifecycle_fact(
                record, kind="STOP_CONFIRMED",
                side_effect_started=bool(record.get("frames_done") or record.get("started_at")),
                process_exited=record.get("kind") != "render", stop_confirmed=True,
                source="houdini/native_render_returned" if record.get("kind") == "render" else "controller/operation-runner")
        sealed_completed = False
        if record.get("kind") == "render" and record.get("state") != "RECONCILE":
            # The queued scene stays a byte-stable reference (frozen inside
            # the controller's producer binding); the terminal record carries
            # the contract beside it for the execution fact.  The completion
            # headroom reserve only ever saw the queued reference record.
            scene = record.get("scene")
            if (isinstance(scene, dict) and not isinstance(record.get("scene_contract_evidence"), dict)
                    and scene.get("scene_contract_sha256")):
                record["scene_contract_evidence"] = _fx_active_scene_contract_for_record(
                    str(record.get("task_id") or ""), scene)
            record["execution_fact"] = _fx_render_execution_fact(record)
            if record.get("state") == "COMPLETED":
                from houdini_bridge.client import seal_render_terminal
                seal_budget = self._render_read_budget(record, store, sealing=True)
                seal_budget.persist()
                seal_render_terminal(record, read_budget=seal_budget)
                sealed_completed = True
        budget_finished = False
        try:
            if record.get("kind") == "render" and record.get("state") != "RECONCILE":
                self._render_budget(record, finished=True)
                budget_finished = True
            self._save(store)
            if release_slot:
                self._release_slot(record)
        except Exception as error:
            if not sealed_completed:
                raise
            # Native completion and its original seal survive publication
            # failure. A pending supervisor deadline must still hold the slot.
            try:
                if budget_finished:
                    self._release_slot(record)
            finally:
                raise BridgeCommandError('RENDER_TERMINAL_PUBLICATION_PENDING', str(error)) from error

    def _render_budget(self, record, *, finished=False):
        from dcc_task_runtime.owned_process import _signed_write, SCHEMA
        binding = record["supervisor_binding"]
        payload = {
            "schema": SCHEMA, "event": "operation-budget", "identity": binding["identity"], "pid": record["host_identity"]["pid"],
            "operation_id": record["request_id"], "token": record["budget_token"],
            "host_identity": record["host_identity"], "budget_seconds": record["budget_seconds"],
            "started_at_epoch": record["started_at_epoch"], "finished": bool(finished)}
        if finished:
            _signed_write(Path(binding["directory"]), {**payload, "event": "operation-finished-" + record["budget_token"]})
        _signed_write(Path(binding["directory"]), payload)

    def _render_read_budget(self, record, store, *, sealing=False):
        from houdini_bridge.render_observation_budget import FileReadBudget
        def persist():
            if not sealing:
                self._save(store)
                return
            from copy import deepcopy
            from houdini_bridge.client import render_terminal_pending_record
            if (store.get('operations') or {}).get(record['request_id']) is not record:
                raise BridgeCommandError('OPERATION_BINDING_MISMATCH', 'terminal publication requires its current operation')
            pending = deepcopy(store)
            pending['operations'][record['request_id']] = render_terminal_pending_record(record)
            self._save(pending)
        if type(record.get("ocio_read_budget")) is not dict:
            raise BridgeCommandError("RENDER_OBSERVATION_BUDGET_STATE_REQUIRED",
                                     "legacy active render has no durable OCIO read allowance; reconciliation required")
        try:
            return FileReadBudget(record["ocio_read_budget"], persist=persist)
        except ValueError as error:
            raise BridgeCommandError("RENDER_OBSERVATION_BUDGET_STATE_REQUIRED", str(error)) from error

    def submit_render(self, params):
        import hou, math
        from dcc_task_runtime.project_color import validate_project_color
        try:
            project_color = validate_project_color(params.get("project_color"))
        except ValueError as error:
            raise BridgeCommandError(str(error), "render requires the controller project color selection") from error
        output_acceptance = params.get('output_acceptance')
        if output_acceptance is not None:
            from houdini_bridge.controlled_output import validate_controlled_policy
            try:
                output_acceptance = validate_controlled_policy(output_acceptance)
            except ValueError as error:
                raise BridgeCommandError(str(error), 'invalid controlled output policy') from error
        frames = params.get("frames")
        budget = params.get("budget_seconds", 120.0)
        operation_id = str(params.get("request_id") or "")
        if (not isinstance(frames, list) or not 0 < len(frames) <= 12
                or any(type(f) is not int or f < 1 for f in frames)
                or len(set(frames)) != len(frames)
                or type(budget) not in (float, int) or not math.isfinite(budget) or not 0 < budget <= 120
                or not re.fullmatch(r"[A-Za-z0-9_.-]{1,100}", operation_id)):
            raise BridgeCommandError("INVALID_ARGUMENT", "render requires an ID, exact unique frames and a <=120s budget")
        frames = sorted(frames)
        dependencies = params.get("dependencies", [])
        if (not isinstance(dependencies, list) or any(not isinstance(d, str) or not d for d in dependencies)
                or len(set(dependencies)) != len(dependencies)):
            raise BridgeCommandError("INVALID_ARGUMENT", "dependencies must be exact unique identifiers")
        pattern = str(params.get("output_pattern") or "")
        from dcc_task_runtime.artifact_registry import frame_path
        if not Path(pattern).is_absolute() or not pattern.lower().endswith(".exr"):
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "render output must be an absolute EXR pattern")
        paths = [frame_path(pattern, f) for f in frames]
        if len(set(paths)) != len(frames):
            raise BridgeCommandError("RENDER_CONFIG_INVALID", "output pattern does not distinguish exact frames")
        target = str(params.get("render_target") or "")
        node = hou.node(target)
        # H21/H22 hom.zip RopNode.render and nodes.zip out/usdrender.
        # A LopNode (including usdrender_rop) is not a RopNode.
        if node is None or node.type().nameWithCategory() != "Driver/usdrender" or not isinstance(node, hou.RopNode):
            raise BridgeCommandError("RENDER_TARGET_UNSUPPORTED", "render target must be a Driver/usdrender RopNode")
        identity = _host_identity()
        required = ("task_id", "pid", "session_id", "launch_nonce", "process_generation", "plugin_build", "scene_epoch")
        if (hou.isUIAvailable() or identity.get("task_id") != self.task_id
                or any(identity.get(k) is None or identity.get(k) == "" for k in required)):
            raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "render requires a fully bound task-owned headless host")
        saves = json.loads(_fx_task_saves_path(self.task_id).read_text(encoding="utf-8"))
        scene = saves.get("active_scene") or {}
        snapshot = Path(str(scene.get("snapshot_path") or ""))
        original = Path(str(scene.get("path") or "")).expanduser().resolve()
        if (scene.get("identity") != identity or not snapshot.is_file() or snapshot.is_symlink()
                or _fx_sha256_file(snapshot) != scene.get("snapshot_sha256")
                or scene.get('snapshot_sha256') != scene.get('sha256')
                or not original.is_file() or original.is_symlink() or _fx_sha256_file(original) != scene.get('sha256')
                or Path(hou.hipFile.path()).expanduser().resolve() != original):
            raise BridgeCommandError("SCENE_STATE_DRIFT", "render requires the unchanged reopened HIP at its original saved path")
        if not scene.get("scene_contract"):
            raise BridgeCommandError("SCENE_CONTRACT_REQUIRED", "saved scene requires a structural contract")
        if scene.get('scene_contract_sha256') != _fx_scene_contract_digest(scene['scene_contract']):
            raise BridgeCommandError('ARTIFACT_CONTRACT_INVALID', 'active render scene contract digest differs')
        _fx_verify_scene_contract(scene["scene_contract"], self.task_id)
        owned_paths = {n["path"] for n in scene["scene_contract"]["nodes"]}
        if target not in owned_paths or node.parm("loppath") is None or str(node.parm("loppath").eval()) not in owned_paths:
            raise BridgeCommandError("SCENE_CONTRACT_REQUIRED", "render target and source LOP must belong to the saved task contract")
        from dcc_task_runtime.owned_process import read_receipt
        directory = os.environ.get("BRIDGE_OWNED_SUPERVISOR_DIR", "")
        binding_identity = json.loads(os.environ.get("BRIDGE_OWNED_SUPERVISOR_IDENTITY", "{}"))
        started = read_receipt(directory, "started", identity=binding_identity) if directory else None
        if (not started or started.get("pid") != identity["pid"]
                or binding_identity.get("task_id") != self.task_id
                or binding_identity.get("launch_nonce") != identity["launch_nonce"]):
            raise BridgeCommandError("SUPERVISOR_REQUIRED", "render requires the owned host supervisor")
        resources = started.get("resource_budget") or {}
        budget_roots = [Path(p).resolve() for p in resources.get("roots", [])]
        if (type(resources.get("max_bytes")) is not int or resources["max_bytes"] <= 0 or not budget_roots
                or any(not any(path.resolve().is_relative_to(root) for root in budget_roots) for path in paths)):
            raise BridgeCommandError("RENDER_OUTPUT_SCOPE_INVALID", "render outputs require the supervisor's frozen disk budget roots")
        request = {"task_id": self.task_id, "frames": frames, "budget_seconds": float(budget),
                   "scene_sha256": scene["snapshot_sha256"], "render_target": target,
                   "output_pattern": pattern, "dependencies": sorted(dependencies),
                   "project_color": project_color}
        if output_acceptance is not None:
            request['output_acceptance'] = output_acceptance
        digest = _fx_scene_contract_digest(request)
        with self._locked():
            store = self._load()
            _fx_reject_producer_operation_id(self, store, operation_id)
            if operation_id in (store.get("scene_transitions") or {}):
                raise BridgeCommandError("CONTENT_CHANGED", "render ID already belongs to a scene transition")
            existing = self._record(store, operation_id)
            if existing:
                if existing.get("request_sha256") != digest:
                    raise BridgeCommandError("CONTENT_CHANGED", "render ID already binds different content")
                return {"operation_id": operation_id, "request_id": operation_id, "record": existing,
                        "operation_store_path": str(self.path), "idempotent": True}
            if self._active(store):
                raise BridgeCommandError("HEAVY_SLOT_BUSY", "task operation is still active")
            for path in paths:
                if path.exists() or any(parent.is_symlink() for parent in (path, *path.parents)):
                    raise BridgeCommandError("RENDER_OUTPUT_NOT_FRESH", "render output exists or traverses a symlink")
            _check_executor_generation(self.task_id)
            record = {"kind": "render", "command": "render.start", "task_id": self.task_id,
                      "request_id": operation_id, "request_sha256": digest, "frames": frames, "frames_done": [],
                      "budget_seconds": float(budget),
                      "scene": {"path": scene["path"], "snapshot_path": scene["snapshot_path"],
                                "sha256": scene["sha256"], "snapshot_sha256": scene["snapshot_sha256"],
                                "identity": scene["identity"],
                                "scene_contract_sha256": _fx_scene_contract_digest(scene["scene_contract"])},
                      "host_identity": identity,
                      "render_target": target, "output_pattern": pattern, "dependencies": sorted(dependencies),
                      "project_color": project_color,
                      "supervisor_binding": {"directory": directory, "identity": binding_identity},
                      "budget_token": uuid4().hex, "started_at_epoch": time.time(), "submitted_at": datetime.now(timezone.utc).isoformat(),
                      "frame_snapshots": {}, "cancel_requested": False, "claimed_by_generation": None}
            if output_acceptance is not None:
                record['output_acceptance'] = output_acceptance
            from houdini_bridge.render_observation_budget import FileReadBudget, validate_preflight_attempt
            intents = store.setdefault("render_observation_intents", {})
            prior_intent = intents.get(operation_id)
            if prior_intent is not None and prior_intent.get("request_sha256") != digest:
                raise BridgeCommandError("CONTENT_CHANGED", "render ID already binds a preflight read allowance for different content")
            attempt_path = self.path.with_suffix(".attempt.json")
            try:
                validate_preflight_attempt(attempt_path, task_id=self.task_id,
                                           operation_id=operation_id, has_budget=prior_intent is not None)
            except (ValueError, OSError, RecursionError) as error:
                raise BridgeCommandError("RENDER_OBSERVATION_BUDGET_STATE_REQUIRED", str(error)) from error
            read_state = prior_intent["budget"] if prior_intent is not None else FileReadBudget().state
            record["ocio_read_budget"] = read_state
            intents[operation_id] = {"request_sha256": digest, "budget": read_state}
            store.setdefault("task_id", self.task_id)
            read_budget = FileReadBudget(read_state, persist=lambda: self._save(store))
            # Stage evaluation itself is native work and is included in the frozen budget.
            attempt = {"task_id": self.task_id, "request_id": operation_id,
                "request_sha256": digest, "intent": "reserve", "phase": "intent",
                "generation": self.generation, "at": record["submitted_at"]}
            # Reserve the whole-store terminal allowance before stage evaluation.
            self._save(store)
            self._write_attempt_marker(attempt_path, attempt)
            try:
                record["slot"] = self._acquire_slot(operation_id)
                record["scheduler_root"] = str(_fx_graph_scheduler().root)
                from dcc_task_runtime.owned_process import _canonical
                attempt.update(phase="reserved", slot=record["slot"],
                    host_identity=identity, supervisor_binding=record["supervisor_binding"],
                    supervisor_started_sha256=hashlib.sha256(_canonical(started)).hexdigest())
                self._write_attempt_marker(attempt_path, attempt)
                scheduler = _fx_graph_scheduler()
                scheduler.arm(str(self.path), operation_id, record["slot"]["token"], identity={
                    "host_identity": identity, "supervisor_binding": record["supervisor_binding"]})
                attempt["phase"] = "preflight_dispatching"
                self._write_attempt_marker(attempt_path, attempt)
                self._render_budget(record)
                root = str(self._manifest()[1].get("execution_root") or "")
                with _root_lease_fence(root, task_id=self.task_id, scope="sop"):
                    record["render_config"] = _fx_render_configuration(
                        node, frames, output_pattern=pattern, read_budget=read_budget, project_color=project_color,
                        output_acceptance=output_acceptance, scene_contract=scene["scene_contract"])
                record["scene_fingerprint"] = _fx_scene_contract_digest({"scene": scene["snapshot_sha256"], "config": record["render_config"]})
                from houdini_bridge.render_observation_budget import (
                    RenderObservationLimit, reserve_render_completion,
                )
                try:
                    reserve_render_completion(record)
                except RenderObservationLimit as error:
                    raise BridgeCommandError("RENDER_OBSERVATION_BUDGET_EXCEEDED", str(error)) from error
                self._bind_execution_attempt(record)
                record["lifecycle_fact"] = _new_lifecycle_fact(record, kind="NOT_STARTED")
                self._set_state(record, "QUEUED", stage="render_queued")
                store.setdefault("task_id", self.task_id)
                store.setdefault("operations", {})[operation_id] = record
                intents.pop(operation_id, None)
                self._save(store)
                attempt_path.unlink(missing_ok=True)
            except BaseException:
                if record.get("slot"):
                    self._release_slot(record)
                    self._render_budget(record, finished=True)
                attempt_path.unlink(missing_ok=True)
                raise
            return {"operation_id": operation_id, "request_id": operation_id, "record": record,
                    "operation_store_path": str(self.path), "idempotent": False}

    def render_fact(self, operation_id):
        record = self.status(operation_id)
        fact = record.get("execution_fact")
        if fact is not None and fact.get("operation_receipt_sha256") != _fx_scene_contract_digest(
                {k: v for k, v in fact.items() if k != "operation_receipt_sha256"}):
            raise BridgeCommandError("RECEIPT_MISMATCH", "persisted render fact digest differs")
        if isinstance(fact, dict):
            # The persisted record stores only the scene reference; queries
            # return a self-contained fact with the contract re-read from the
            # durable saves store and a freshly computed receipt digest.  The
            # stored record and fact stay byte-identical to the worker's own
            # terminal seal.
            scene = fact.get("scene")
            if (isinstance(scene, dict) and not isinstance(scene.get("scene_contract"), dict)
                    and scene.get("scene_contract_sha256")):
                from houdini_bridge.client import render_receipt_digest
                contract = _fx_active_scene_contract_for_record(self.task_id, scene)
                fact = {**fact, "scene": {**scene, "scene_contract": contract}}
                fact = {**fact, "operation_receipt_sha256": render_receipt_digest(
                    {k: v for k, v in fact.items() if k != "operation_receipt_sha256"})}
        return fact

    def _advance_render(self, record, store):
        import hou
        if record.get("state") == "RECONCILE" or record.get('stage') == 'render_terminal_sealing':
            return
        try:
            read_budget = self._render_read_budget(record, store)
        except BridgeCommandError as error:
            self._set_state(record, "RECONCILE", stage="render_read_allowance_unknown")
            record["reconcile_reason"] = str(error)
            self._save(store)
            return  # No native call and no unproven slot release for old records.
        if record.get("state") == "QUEUED":
            self._set_state(record, "RUNNING", stage="render_claimed")
            record["claimed_by_generation"] = self.generation
            record["started_at"] = datetime.fromtimestamp(record["started_at_epoch"], timezone.utc).isoformat()
            record["lifecycle_fact"] = _new_lifecycle_fact(record, kind="STARTED", side_effect_started=False)
            self._save(store)
        if record.get("in_flight_frame") is not None:
            self._set_state(record, "RECONCILE", stage="render_in_flight_unknown")
            self._terminal(record, store, release_slot=False)
            return
        if record.get("cancel_requested"):
            self._set_state(record, "CANCELLED", stage="render_cancelled_before_frame")
            self._terminal(record, store)
            return
        if time.time() - record["started_at_epoch"] >= record["budget_seconds"]:
            self._set_state(record, "BUDGET_REACHED", stage="render_budget_exhausted")
            self._terminal(record, store)
            return
        pending = [f for f in record["frames"] if f not in record["frames_done"]]
        if not pending:
            self._set_state(record, "COMPLETED", stage="render_all_frames_collected")
            self._terminal(record, store)
            return
        self._fence_slot(record)
        frame = pending[0]
        node = hou.node(record["render_target"])
        snapshot = Path(record["scene"]["snapshot_path"])
        try:
            if (_host_identity() != record["host_identity"] or not snapshot.is_file()
                    or _fx_sha256_file(snapshot) != record["scene"]["snapshot_sha256"]):
                raise BridgeCommandError("SCENE_STATE_DRIFT", "frozen render scene or host changed")
            scene_contract = _fx_active_scene_contract_for_record(self.task_id, record["scene"])
            _fx_verify_scene_contract(scene_contract, self.task_id)
            from dcc_task_runtime.artifact_registry import frame_path
            path = frame_path(record["output_pattern"], frame)
            if path.exists() or any(p.is_symlink() for p in (path, *path.parents)):
                raise BridgeCommandError("RENDER_OUTPUT_NOT_FRESH", "render frame already exists")
            record["in_flight_frame"] = frame
            self._save(store)
            self._in_cook = True
            root = str(self._manifest()[1].get("execution_root") or "")
            with _root_lease_fence(root, task_id=self.task_id, scope="sop"):
                if _fx_render_configuration(node, [frame], output_pattern=record["output_pattern"], read_budget=read_budget,
                                            project_color=record.get("project_color"), output_acceptance=record.get("output_acceptance"),
                                            scene_contract=scene_contract) != {
                        str(frame): record["render_config"][str(frame)]}:
                    raise BridgeCommandError("SCENE_STATE_DRIFT", "frozen USD render configuration changed")
                path.parent.mkdir(parents=True, exist_ok=True)
                scope_binding = os.environ.get('BRIDGE_NATIVE_SCOPE_BINDING')
                if scope_binding:
                    from dcc_task_runtime.native_scope import NativeScope
                    parent_ticket = os.environ.get('BRIDGE_NATIVE_SCOPE_TICKET')
                    if record.get('native_scope_ticket'):
                        raise BridgeCommandError('NATIVE_SCOPE_AUTOMATIC_RETRY_FORBIDDEN', 'native frame already admitted')
                    supervisor = record['supervisor_binding']
                    record['native_scope_ticket'] = NativeScope(json.loads(scope_binding)).admit(
                        'main-husk', supervisor['directory'], supervisor['identity'], parent=parent_ticket)
                    self._save(store)
                from houdini_bridge.render_writer_facts import render_writer_frame
                with render_writer_frame(node, record, frame, self.path.parent / 'writer-observations', hou_module=hou):
                    node.render(frame_range=(frame, frame, 1), output_file=str(path),
                                output_format="exr", ignore_inputs=True, to_flipbook=False)
                if _fx_render_configuration(node, [frame], output_pattern=record["output_pattern"], read_budget=read_budget,
                                            project_color=record.get("project_color"), output_acceptance=record.get("output_acceptance"),
                                            scene_contract=scene_contract) != {
                        str(frame): record["render_config"][str(frame)]}:
                    raise BridgeCommandError("SCENE_STATE_DRIFT", "native render configuration changed during frame")
            if node.errors():
                raise BridgeCommandError("RENDER_FAILED", str(node.errors()))
            stat = path.stat()
            if stat.st_size <= 0 or stat.st_mtime < record["started_at_epoch"]:
                raise BridgeCommandError("RENDER_OUTPUT_NOT_FRESH", "native render produced no fresh frame")
            from dcc_task_runtime.exr_codec import read_exr, ExrDecodeError
            try:
                decoded = read_exr(path, with_pixels=False)
            except ExrDecodeError as exc:
                raise BridgeCommandError("RENDER_OUTPUT_INVALID", "native output is not readable EXR") from exc
            expected_compression = {"none": 0, "zips": 2, "zip": 3}[
                record["render_config"][str(frame)]["exr_format"]["compression"]]
            if decoded["compression"] != expected_compression:
                raise BridgeCommandError("RENDER_OUTPUT_INVALID", "native EXR differs from frozen driver compression")
            record["frame_snapshots"][str(frame)] = {"path": str(path), "bytes": stat.st_size,
                "sha256": _fx_sha256_file(path), "modified_ns": stat.st_mtime_ns, "observed_at_epoch": time.time(),
                "exr": {"width": decoded["width"], "height": decoded["height"],
                        "channels": decoded["channels"], "compression": decoded["compression"]}}
            from houdini_bridge.client import collect_render_output_fact
            record.setdefault("output_facts", {})[str(frame)] = collect_render_output_fact(
                record, frame, read_budget=read_budget)
            record["frames_done"].append(frame)
            record.pop("in_flight_frame", None)
            if time.time() - record["started_at_epoch"] >= record["budget_seconds"]:
                self._set_state(record, "BUDGET_REACHED", stage="render_budget_exhausted")
                self._terminal(record, store)
            elif record["frames_done"] == record["frames"]:
                self._set_state(record, "COMPLETED", stage="render_all_frames_collected")
                self._terminal(record, store)
            else:
                self._save(store)
        except Exception as exc:
            if getattr(exc, 'code', None) == 'RENDER_TERMINAL_PUBLICATION_PENDING':
                return
            record["error"] = str(exc)
            if getattr(exc, 'code', None) == 'RENDER_WRITER_STOP_UNCONFIRMED':
                record["reconcile_reason"] = str(exc)
                self._set_state(record, "RECONCILE", stage="render_writer_stop_unknown")
                self._terminal(record, store, release_slot=False)
            else:
                record.pop("in_flight_frame", None)
                self._set_state(record, "FAILED", stage="render_failed")
                self._terminal(record, store)
        finally:
            self._in_cook = False

    # ---- public API ------------------------------------------------------
    def submit(self, params: dict[str, Any], pack_id: str, pack: dict[str, Any],
               request_id: "Optional[str]" = None) -> dict[str, Any]:
        import math
        frames = _fx_frame_values(params)
        if not frames:
            raise BridgeCommandError("INVALID_ARGUMENT", "frames or frame_range is required")
        root, manifest = self._manifest()
        if not manifest or manifest.get("domain_pack") != pack_id:
            raise BridgeCommandError("SCENE_CONFLICT", "no built scene manifest for task {} with pack {}".format(self.task_id, pack_id))
        output_path = str((manifest.get("nodes") or {}).get("output") or "")
        if hou_node(output_path) is None:
            raise BridgeCommandError("SCENE_STATE_MISSING", "built output node is missing for task {}".format(self.task_id))
        subject = str((manifest.get("cache") or {}).get("subject_hash") or manifest.get("input_digest") or manifest.get("execution_root") or "")
        requested_id = str(request_id or "").strip()
        if requested_id and not re.fullmatch(r"[A-Za-z0-9_.-]{1,100}", requested_id):
            raise BridgeCommandError("INVALID_ARGUMENT", "request_id is not a bounded operation identifier")
        request_id = requested_id or _load_core_contract().derive_operation_id(self.task_id, subject, frames)
        budget = float(params.get("budget_seconds") if params.get("budget_seconds") is not None else 120.0)
        cache_binding = params.get("_cache_binding")
        if cache_binding is not None:
            if not isinstance(cache_binding, dict):
                raise BridgeCommandError("APPROVAL_REQUIRED", "cache binding must come from the approved cache controller")
            resource = cache_binding.get("resource_contract") or {}
            _fx_validate_cache_approval(cache_binding.get("approval"), str(cache_binding.get("subject_hash") or ""), resource)
            outputs = cache_binding.get("output_frames") or []
            approved_range = resource.get("frame_range") or []
            history_range, segment_count = _fx_cache_history(cache_binding)
            first_segment = _fx_cache_segment(cache_binding, 0)
            # Output frames are the public short job, not the solver history.
            if (not outputs or len(outputs) > 12 or len(approved_range) != 3 or
                    type(approved_range[2]) is not int or approved_range[2] <= 0 or
                    (approved_range[1] - approved_range[0]) // approved_range[2] + 1 != len(outputs) or
                    any(frame != approved_range[0] + index * approved_range[2] for index, frame in enumerate(outputs)) or
                    history_range != [resource["simulation_start_frame"], outputs[-1]] or
                    frames != first_segment or any(frame < resource["simulation_start_frame"] for frame in outputs) or
                    budget != resource["max_seconds"] or cache_binding.get("output_pattern") != resource["output_path"] or
                    str(cache_binding.get("subject_hash")) != subject):
                raise BridgeCommandError("APPROVAL_SCOPE_MISMATCH", "cache segments do not match approved contiguous solver history")
            original_params = json.loads(json.dumps(params))
            original_params["constraints"]["fx"]["frames"] = outputs
            original_params["render"] = {"frame_range": dict(zip(("start", "end", "step"), approved_range))}
            _current_subject, current_hash = _fx_cache_subject(original_params, pack_id, manifest)
            if current_hash != cache_binding["subject_hash"]:
                raise BridgeCommandError("SCENE_STATE_DRIFT", "cache scene changed before runner submission")
        elif len(frames) > 12 or not math.isfinite(budget) or not 0 < budget <= 120:
            raise BridgeCommandError("INVALID_ARGUMENT", "frame operations require at most 12 frames and 120 seconds")
        request_sha256 = hashlib.sha256(json.dumps(
            {"task_id": str(self.task_id), "subject": str(subject), "frames": [int(f) for f in frames],
             "request_id": str(request_id),
             "pack_id": str(pack_id), "budget_seconds": budget, "cache_binding": cache_binding},
            ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
        with self._locked():
            store = self._load()
            store.setdefault("task_id", str(self.task_id))
            _fx_reject_producer_operation_id(self, store, request_id)
            if request_id in (store.get("scene_transitions") or {}):
                raise BridgeCommandError("CONTENT_CHANGED", "frame operation ID already belongs to a scene transition")
            self._reconcile_stale(store)
            existing = self._record(store, request_id)
            if existing is not None:
                recorded = str(existing.get("request_sha256") or "")
                if recorded != request_sha256:
                    # Same request id with different content (frames, budget,
                    # pack binding or subject) is refused, never silently
                    # treated as idempotent.
                    raise BridgeCommandError(
                        "CONTENT_CHANGED",
                        "request {} already exists with different content".format(request_id),
                        "Resubmit the original content or use a new subject; stored evidence must not be re-bound.")
                if existing.get("state") == "RECONCILE":
                    # No model-supplied flag can archive a RECONCILE record:
                    # archiving is a control decision taken after the real
                    # host, execution log and artifacts have been verified.
                    return {"request_id": request_id, "operation_id": request_id, "record": existing, "idempotent": True,
                            "blocked": "RECONCILE",
                            "hint": "control channel must resolve the reconciliation (fx runner resolve_reconcile) after verifying host evidence; submit can never archive it"}
                return {"request_id": request_id, "operation_id": request_id, "record": existing, "idempotent": True}
            _check_executor_generation(self.task_id)
            if self._active(store) is not None:
                raise BridgeCommandError("HEAVY_SLOT_BUSY", "an operation is still active for this task",
                                         "Query operation.status or cancel it first.")
            # crash window #1 (reserve -> record): a durable ATTEMPT marker
            # written BEFORE the reservation lets recovery distinguish
            # "reserved but never recorded" from a clean state
            attempt_path = self.path.with_suffix(".attempt.json")
            attempt = {
                "task_id": str(self.task_id), "request_id": request_id,
                "request_sha256": request_sha256, "phase": "intent",
                "intent": "reserve", "generation": self.generation,
                "at": datetime.now(timezone.utc).isoformat()}
            self._write_attempt_marker(attempt_path, attempt)
            slot = self._acquire_slot(request_id)  # held until an observed terminal state
            try:
                attempt.update(phase="reserved", slot=slot)
                self._write_attempt_marker(attempt_path, attempt)
                execution_id = uuid4().hex[:12]
                process_generation = str(self.generation)
                process_identity = hashlib.sha256(json.dumps(
                    {"pid": os.getpid(), "task_id": str(self.task_id),
                     "request_id": str(request_id), "execution_id": execution_id,
                     "process_generation": process_generation},
                    ensure_ascii=False, sort_keys=True, separators=(",", ":"),
                ).encode("utf-8")).hexdigest()
                submitted_at = datetime.now(timezone.utc).isoformat()
                record = {
                    "request_id": request_id,
                    "execution_id": execution_id,
                    "task_id": self.task_id,
                    "pack_id": pack_id,
                    "frames": frames,
                    "frames_done": [],
                    "evidence": [],
                    "budget_seconds": budget,
                    "cache_binding": cache_binding,
                    "cache_segment_index": 0,
                    "cache_segments_done": [],
                    "request_sha256": request_sha256,
                    "submitted_at": submitted_at,
                    "generation": self.generation,
                    "claimed_by_generation": None,
                    "process": {"pid": os.getpid(), "port": _SERVER.port if _SERVER else None,
                                "session_id": _SERVER.session_id if _SERVER else None,
                                "process_generation": process_generation,
                                "process_identity": process_identity},
                    "attempt": {"attempt_id": execution_id,
                                 "process_generation": process_generation,
                                 "process_identity": process_identity,
                                 "owner": "houdini-operation-runner"},
                    "slot": slot,
                    "cancel_requested": False,
                    "cancel_requested_at": None,
                    "stop_confirmed_at": None,
                    "stage": "queued",
                    "error": None,
                }
                record["lifecycle_fact"] = _new_lifecycle_fact(
                    record, kind="NOT_STARTED", source="controller/operation-runner")
                self._set_state(record, "QUEUED", stage="queued")
                store.setdefault("operations", {})[request_id] = record
                self._save(store)
                attempt_path.unlink(missing_ok=True)  # reserve->record committed
            except BaseException:
                self._release_slot(record={"slot": slot})
                attempt_path.unlink(missing_ok=True)
                raise
            return {"request_id": request_id, "operation_id": request_id, "record": record, "idempotent": False}

    def status(self, op_id: str) -> dict[str, Any]:
        """Pure read: never claims, promotes or reconciles."""
        with self._locked():
            store = self._load()
            record = self._record(store, str(op_id))
            if record is None:
                raise BridgeCommandError("OPERATION_NOT_FOUND", "no operation {}".format(op_id))
            return dict(record)

    def cancel(self, op_id: str) -> dict[str, Any]:
        with self._locked():
            store = self._load()
            record = self._record(store, str(op_id))
            if record is None:
                raise BridgeCommandError("OPERATION_NOT_FOUND", "no operation {}".format(op_id))
            if (record.get("state") in ("COMPLETED", "FAILED", "CANCELLED", "BUDGET_REACHED", "RECONCILE", "SUPERSEDED")
                    or record.get('stage') == 'render_terminal_sealing'):
                return dict(record)
            record["cancel_requested"] = True
            record["cancel_requested_at"] = record.get("cancel_requested_at") or datetime.now(timezone.utc).isoformat()
            if self._in_cook:
                self._set_state(record, "CANCEL_PENDING")
                record["stage"] = "cancel_pending_uninterruptible_cook"
            else:
                self._set_state(record, "CANCELLED")
                record["stage"] = "cancelled_before_observed_work"
                record["stop_confirmed_at"] = datetime.now(timezone.utc).isoformat()
                self._terminal(record, store)
                return dict(record)
            self._save(store)
            return dict(record)

    # ---- executor (serve-loop level; claims work itself) ------------------
    def advance(self) -> None:
        with self._locked():
            store = self._load()
            if self._reconcile_stale(store):
                self._save(store)
            record = self._active(store)
            if record is None:
                # nothing active: an idle executor must NOT release the
                # installation slot — it belongs to whichever acquisition
                # holds it and is freed by that owner at terminal state
                return
            if record.get("kind") == "render":
                self._advance_render(record, store)
                return
            state = record.get("state")
            if state == "RECONCILE":
                return  # controller decision required; never auto-rerun
            if state == "CANCEL_PENDING":
                self._set_state(record, "CANCELLED")
                record["stage"] = "cancelled_after_observed_stop"
                record["stop_confirmed_at"] = datetime.now(timezone.utc).isoformat()
                self._terminal(record, store)
                return
            if state == "QUEUED":
                # atomic claim (per-task lock + replace): queued work from any
                # generation was never executed, so the current host claims it
                self._set_state(record, "RUNNING")
                record["claimed_by_generation"] = self.generation
                self._bind_execution_attempt(record)
                record["started_at"] = datetime.now(timezone.utc).isoformat()
                record["stage"] = "claimed"
                record["lifecycle_fact"] = _new_lifecycle_fact(
                    record, kind="STARTED", side_effect_started=False,
                    source="controller/operation-runner")
                self._save(store)
            if record.get("cancel_requested"):
                self._set_state(record, "CANCELLED")
                record["stage"] = "cancelled"
                self._terminal(record, store)
                return
            started = datetime.fromisoformat(record.get("started_at") or record.get("submitted_at"))
            elapsed = (datetime.now(timezone.utc) - started).total_seconds()
            budget = float(record.get("budget_seconds") or 120.0)
            if elapsed >= budget:
                self._set_state(record, "BUDGET_REACHED")
                record["stage"] = "budget_exhausted_partial_results_kept"
                self._terminal(record, store)
                return
            pending = [f for f in record["frames"] if f not in set(record["frames_done"])]
            if not pending:
                self._set_state(record, "COMPLETED")
                record["stage"] = "all_frames_collected"
                self._terminal(record, store)
                return
            if record.get("in_flight_frame") is not None:
                # a previous executor cooked this frame but never recorded the
                # result: unknown, reconcile instead of silently repeating it
                self._set_state(record, "RECONCILE")
                record["reconcile_reason"] = "frame {} in flight without recorded result".format(record["in_flight_frame"])
                self._terminal(record, store, release_slot=False)
                return
            # lease/identity re-check before any mutation or cook
            if record.get("claimed_by_generation") not in (None, self.generation):
                self._set_state(record, "RECONCILE")
                self._terminal(record, store, release_slot=False)
                return
            self._fence_slot(record)  # prove the installation slot is still ours before cooking
            cache_binding = record.get("cache_binding")
            if cache_binding:
                try:
                    _fx_cache_usage(cache_binding["resource_contract"])
                except BridgeCommandError as exc:
                    self._set_state(record, "BUDGET_REACHED")
                    record["error"] = str(exc)
                    self._terminal(record, store)
                    return
            _fx_check_disk_budget(self.store_root)
            checked_lease_versions: dict[str, int] = {}
            operation_root = str((self._manifest()[1] or {}).get("execution_root") or
                                 _fx_task_paths(str(self.task_id))[0])
            for root in (operation_root,):
                try:
                    lease_seen = _root_lease_check(root)
                    checked_lease_versions[root] = int((lease_seen or {}).get("version") or 0)
                except BridgeCommandError as exc:
                    # ownership lost (takeover/expiry/corruption): stop issuing
                    # side effects; the slot stays held for the control plane
                    record["state_before_ownership_loss"] = str(record.get("state"))
                    self._set_state(record, "RECONCILE",
                                    note="root ownership check failed: {}".format(exc.code))
                    self._terminal(record, store, release_slot=False)
                    return
            # lease fence before the side effect: a takeover that completed
            # after the check bumped the version — this executor must not cook
            for root, seen_version in checked_lease_versions.items():
                try:
                    current = _root_lease_read(root)
                except BridgeCommandError:
                    current = None
                if (current or {}).get("status") != "ACTIVE" or int((current or {}).get("version") or 0) != seen_version:
                    record["state_before_ownership_loss"] = str(record.get("state"))
                    self._set_state(record, "RECONCILE",
                                    note="root {} changed ownership between check and side effect".format(root))
                    self._terminal(record, store, release_slot=False)
                    return
            frame = pending[0]
            output = hou_node(str((self._manifest()[1].get("nodes") or {}).get("output") or ""))
            if output is None:
                self._set_state(record, "FAILED")
                record["error"] = "output node missing"
                self._terminal(record, store)
                return
            record["in_flight_frame"] = frame
            self._save(store)
            t0 = time.monotonic()
            self._in_cook = True
            try:
                # The ownership check and the first Houdini side effect must
                # share one inter-process fence.  A plain check followed by
                # hou.setFrame()/cook leaves a takeover window in which an
                # old host can still mutate the scene after a new host owns
                # the root.
                try:
                    with _root_lease_fence(root, task_id=str(self.task_id), scope="sop"):
                        hou_set_frame(frame)
                        output.cook(force=bool(not record["frames_done"]))
                        cook_error = list(output.errors())
                        cache_file = None
                        if cache_binding and not cook_error and frame in cache_binding["output_frames"]:
                            cache_path = _fx_cache_frame_path(cache_binding["output_pattern"], frame)
                            budget_roots = {Path(item).resolve() for item in cache_binding["resource_contract"]["task_roots"]}
                            for item in (cache_path, *cache_path.parents):
                                if item.resolve() in budget_roots:
                                    break
                                if item.is_symlink():
                                    raise BridgeCommandError("CACHE_PATH_INVALID", "cache output traverses a symlink")
                            cache_path.parent.mkdir(parents=True, exist_ok=True)
                            output.geometry().saveToFile(str(cache_path))
                            if not cache_path.is_file() or cache_path.stat().st_size <= 0:
                                raise BridgeCommandError("CACHE_WRITE_FAILED", "native geometry writer returned no output")
                            cache_file = {"path": str(cache_path), "sha256": _fx_sha256_file(cache_path),
                                          "bytes": cache_path.stat().st_size}
                except BridgeCommandError as exc:
                    record["state_before_ownership_loss"] = str(record.get("state"))
                    record["reconcile_reason"] = "root ownership fence rejected frame {}: {}".format(frame, exc.code)
                    self._set_state(record, "RECONCILE", note=str(exc.code))
                    self._terminal(record, store, release_slot=False)
                    return
            finally:
                self._in_cook = False
            cook_seconds = round(time.monotonic() - t0, 3)
            t1 = time.monotonic()
            evidence: dict[str, Any] = {"frame": int(frame), "time": hou_time(), "cook_seconds": cook_seconds}
            if cache_binding and cache_file:
                evidence["cache_file"] = cache_file
            if cook_error:
                evidence["errors"] = cook_error
                self._set_state(record, "FAILED")
                record["error"] = "output cook failed at frame {}: {}".format(frame, cook_error[:1])
                record.pop("in_flight_frame", None)
                self._terminal(record, store)
            else:
                geometry = output.geometry()
                bounds = geometry.boundingBox().sizevec()
                evidence.update({
                    "points": len(geometry.points()),
                    "prims": len(geometry.prims()),
                    "bounds": [round(float(v), 6) for v in bounds],
                    "point_attributes": sorted(a.name() for a in geometry.pointAttribs()),
                })
                record["frames_done"].append(int(frame))
                record.pop("in_flight_frame", None)
                record.setdefault("evidence", []).append(evidence)
                record["evidence_collect_seconds"] = round(time.monotonic() - t1, 3)
                record["stage"] = "frame_{}_done".format(frame)
                if cache_binding:
                    try:
                        _fx_cache_usage(cache_binding["resource_contract"])
                    except BridgeCommandError as exc:
                        self._set_state(record, "BUDGET_REACHED")
                        record["error"] = str(exc)
                        self._terminal(record, store)
                        return
                    if (datetime.now(timezone.utc) - started).total_seconds() >= budget:
                        self._set_state(record, "BUDGET_REACHED")
                        record["stage"] = "cache_total_budget_exhausted"
                        self._terminal(record, store)
                        return
                if not [f for f in record["frames"] if f not in set(record["frames_done"])]:
                    if cache_binding:
                        segment_index = record["cache_segment_index"]
                        record["cache_segments_done"].append({"segment_index": segment_index,
                            "frame_range": [record["frames"][0], record["frames"][-1]], "state": "COMPLETED",
                            "operation_id": record["request_id"] + ".segment-" + str(segment_index)})
                        if segment_index + 1 < _fx_cache_history(cache_binding)[1]:
                            record["cache_segment_index"] = segment_index + 1
                            record["frames"] = _fx_cache_segment(cache_binding, segment_index + 1)
                            record["frames_done"] = []
                            record["evidence"] = [row for row in record["evidence"] if row.get("cache_file")]
                            record["stage"] = "cache_segment_{}_ready_same_owner".format(segment_index + 1)
                            self._save(store)
                            return
                    self._set_state(record, "COMPLETED")
                    record["stage"] = "all_frames_collected"
                    self._terminal(record, store)
                    return
                self._save(store)


def fx_operation_runner(task_id: str) -> OperationRunner:
    global _FX_OPERATIONS
    with _FX_OPERATIONS_LOCK:
        if _FX_OPERATIONS is None or _FX_OPERATIONS.task_id != task_id:
            _FX_OPERATIONS = OperationRunner(task_id)
        return _FX_OPERATIONS




def _fx_task_saves_path(task_id: str) -> Path:
    directory = _task_state_root() / "fx_operations"
    directory.mkdir(parents=True, exist_ok=True)
    return directory / "{}.saves.json".format(_task_name(task_id, "ops"))


def _fx_record_task_save(task_id: str, receipt: dict[str, Any]) -> None:
    from dcc_task_runtime.platform_support import atomic_write
    path = _fx_task_saves_path(task_id)
    store: dict[str, Any] = {}
    if path.is_file():
        try:
            store = json.loads(path.read_text(encoding="utf-8"))
        except (ValueError, OSError):
            store = {}
    store.setdefault("saves", []).append(receipt)
    store["active_generation"] = receipt.get("process_generation")
    atomic_write(path, json.dumps(store, ensure_ascii=False, indent=1).encode("utf-8"), owned_root=path.parent)


def _check_executor_generation(task_id: str) -> None:
    """One executor per task: an older generation must not keep writing."""
    path = _fx_task_saves_path(task_id)
    if not path.is_file():
        return
    try:
        store = json.loads(path.read_text(encoding="utf-8"))
    except (ValueError, OSError):
        return
    active = store.get("active_generation")
    if not active:
        return
    current = _FX_OPERATIONS.generation if _FX_OPERATIONS is not None else None
    if current is not None and current != active:
        raise BridgeCommandError("STALE_EXECUTOR",
                                 "task {} is owned by executor generation {}; this process holds {}".format(task_id, active, current),
                                 "Reopen the task in this process to take over ownership explicitly.")


def _fx_scene_contract_digest(contract: dict[str, Any]) -> str:
    payload = json.dumps(contract, ensure_ascii=False, sort_keys=True,
                          separators=(",", ":"), allow_nan=False).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _fx_scene_parameter_readback(parm,task_id=None, *, allow_uninitialized_stash=False):
    """Preserve actual channel definitions even when an expression cannot cook."""
    driver = _component_driver_identity(parm)
    keys_method = getattr(parm, "keyframes", None)
    keys = tuple(keys_method()) if callable(keys_method) else ()
    channel = {**driver, "keyframes": [_keyframe_identity(key) for key in keys]}
    if keys:
        channel.update(pre_extrapolation=str(parm.keyframeExtrapolation(True)),post_extrapolation=str(parm.keyframeExtrapolation(False)))
    try:
        template_type = str(parm.parmTemplate().type()).rsplit(".",1)[-1]
    except Exception:
        template_type = None
    if template_type in {"Button", "Label", "Separator"}:
        channel.update(evaluated_available=False,non_value_type=template_type)
        return None,channel
    if template_type == 'Data':
        node = parm.node()
        if (allow_uninitialized_stash and parm.name() == 'stash' and node.type().nameWithCategory() == 'Sop/stash'
                and node.userData('bridge_native_agent_recipe_v1') is None
                and node.userData('bridge_native_route_recipe_v1') is None):
            stashfile = node.parm('stashfile')
            channel['stashfile_available'] = stashfile is not None
            stashfile_value = stashfile.eval() if stashfile is not None else None
            if stashfile is not None:
                channel['stashfile_value'] = stashfile_value
            if (driver['expression'] is not None or driver['reference_path'] is not None or keys
                    or stashfile is not None and stashfile_value != ''):
                raise BridgeCommandError('UNREGISTERED_STASH_DATA', 'intermediate stash has an external file or driver')
            schema = 'bridge.pending-stash-data/1'
            try:
                geometry = parm.evalAsGeometry()
            except Exception as error:
                channel.update(evaluated_available=False, data_observation_schema=schema,
                               data_state='readback_unavailable',
                               evaluation_error=type(error).__name__ + ': ' + str(error))
                return None, channel
            if geometry is not None:
                raise BridgeCommandError('UNREGISTERED_STASH_DATA', 'intermediate stash contains unregistered data')
            channel.update(evaluated_available=True, data_observation_schema=schema, data_state='observed_null')
            return None, channel
        if parm.name()=='stash' and parm.node().userData('bridge_native_route_recipe_v1'):
            snapshot = _fx_crowd_curve_stash_snapshot(parm.node(),task_id)
            channel.update(evaluated_available=True,geometry_contract=snapshot['schema'])
            return _json_safe(snapshot),channel
        snapshot = _fx_crowd_stash_snapshot(parm.node().path())
        channel.update(evaluated_available=True,geometry_contract=snapshot['schema'])
        return {k:snapshot[k] for k in ('schema','houdini_version','content','content_sha256')},channel
    if driver["expression"] is not None:
        language = getattr(parm, "expressionLanguage", None)
        if callable(language):
            channel["expression_language"] = str(language())
    try:
        value = _json_safe(parm.eval())
        channel["evaluated_available"] = True
    except Exception:
        if not driver["expression"] and not keys:
            raise
        # A serialized native driver is an exact channel fact, never an
        # inferred sample value. Critical controls still require evaluated
        # readback in their edit/preview/render preflight.
        value = None
        channel["evaluated_available"] = False
    return value, channel


def _fx_frozen_scene_capture_basis(manifest, task_id):
    from houdini_bridge.native_render_scene import PARAMETER_PLAN_REVISION
    revision = manifest.get("frozen_scene_plan_revision")
    if revision is not None:
        if type(revision) is not int or revision != PARAMETER_PLAN_REVISION:
            raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "scene parameter plan revision is unsupported")
        return None
    path = _fx_task_saves_path(task_id)
    if not path.is_file():
        return None
    active = json.loads(path.read_text(encoding="utf-8")).get("active_scene") or {}
    contract = active.get("scene_contract")
    if (not isinstance(contract, dict) or active.get("identity") != _host_identity()
            or contract.get("execution_root") != manifest.get("execution_root")
            or contract.get("frozen_render_scene_sha256") != manifest.get("frozen_render_scene_sha256")):
        return None
    if active.get("scene_contract_sha256") != _fx_scene_contract_digest(contract):
        raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "active legacy scene contract digest differs")
    saved = contract.get("frozen_scene_parameters")
    _fx_frozen_readback_revision(saved)
    return saved


def _fx_capture_scene_contract(task_id: str, *, capture_policy=None) -> Optional[dict[str, Any]]:
    """Capture bounded node, parameter, and connection readback for a task HIP."""
    import hou

    root, manifest = _fx_manifest(task_id, required=False)
    nodes = manifest.get("nodes") if isinstance(manifest, dict) else None
    if not isinstance(nodes, dict) or not nodes:
        return None
    execution_root = str(manifest.get("execution_root") or "")
    task_root, task_stage_root = _fx_task_paths(str(task_id))
    owned_roots = [execution_root]
    if execution_root == task_root:
        owned_roots.append(task_stage_root)
    # VOP material nodes live in the task's material-network namespace rather
    # than under the SOP execution root.  Register each task-owned material
    # node as its own exact root; this does not authorize unrelated /mat
    # contents during save/reopen verification.
    for raw_path in nodes.values():
        candidate = str(raw_path or "")
        if candidate.startswith("/mat/") and candidate not in owned_roots:
            owned_roots.append(candidate)
    if (manifest.get("task_id") != str(task_id) or not execution_root.startswith("/obj/")
            or ".." in execution_root.split("/")
            or any(".." in root.split("/") for root in owned_roots)):
        raise BridgeCommandError("SCENE_CONTRACT_SCOPE_INVALID", "task scene manifest is not bound to an owned object root")
    nodes, boundaries = _fx_scene_contract_nodes(owned_roots, nodes, capture_policy=capture_policy)
    limits = _fx_current_capture_limits()
    records = []
    for role, raw_path in sorted(nodes.items(), key=lambda item: str(item[0])):
        path = str(raw_path or "")
        node = hou.node(path)
        if not any(path == root or path.startswith(root.rstrip("/") + "/") for root in owned_roots) or node is None:
            raise BridgeCommandError("SCENE_CONTRACT_NODE_MISSING", "a registered task node is unavailable during save")
        try:
            parms = list(node.parms())
            if len(parms) > limits["parameters_per_node"]:
                raise ValueError("parameter count exceeds contract limit")
            readbacks = {str(parm.name()): _fx_scene_parameter_readback(parm,task_id) for parm in parms}
            parm_values = {name: value for name, (value, channel) in readbacks.items()
                           if channel["evaluated_available"]}
            parm_channels = {name: channel for name, (value, channel) in readbacks.items()}
            inputs = [item.path() if item is not None else None for item in node.inputs()]
            if len(inputs) > 64:
                raise ValueError("input count exceeds contract limit")
            node_type = str(node.type().nameWithCategory())
        except Exception as exc:
            raise BridgeCommandError("SCENE_CONTRACT_READBACK_FAILED", "task node state could not be read during save") from exc
        records.append({"role": str(role), "path": path, "type": node_type,
                        "parameters": parm_values, "parameter_channels": parm_channels, "inputs": inputs})
    if _fx_current_capture_limits() != limits:
        raise BridgeCommandError("SCENE_CONTRACT_SCOPE_INVALID", "capture limits changed during task readback")
    contract = {"schema": "houdini.task_scene_contract/2.0", "task_id": str(task_id),
                "execution_root": execution_root, "owned_roots": owned_roots,
                "graph_hash": str(manifest.get("graph_hash") or ""), "nodes": records}
    _fx_scene_contract_policy_fields(contract, boundaries)
    configuration = manifest.get('frozen_render_scene')
    if configuration is not None:
        from dcc_task_runtime.canonical import canonical_sha256
        if canonical_sha256(configuration) != manifest.get('frozen_render_scene_sha256'):
            raise BridgeCommandError('SCENE_STATE_MISMATCH', 'frozen scene configuration digest differs')
        domain,pack = _fx_pack({'constraints':{'fx':{'domain_pack':manifest['domain_pack']}},'frozen_render_scene':configuration})
        contract['frozen_scene_parameters'] = _fx_frozen_scene_readback(configuration,manifest['nodes'],pack,manifest.get('candidate_patch'),
            task_id=task_id, saved_readback=_fx_frozen_scene_capture_basis(manifest, str(task_id)))
        contract['frozen_render_scene_sha256'] = manifest['frozen_render_scene_sha256']
    environment = _fx_project_environment_readback(manifest, str(task_id))
    if environment is not None:
        contract['project_environment'] = environment
        contract['project_environment_sha256'] = manifest['project_environment_sha256']
    checkpoint = _fx_geometry_checkpoint(root, manifest)
    if checkpoint is not None:
        contract['geometry_registry_checkpoint'] = checkpoint
    checkpoint = _fx_rbd_checkpoint(root, manifest)
    if checkpoint is not None:
        contract['rbd_velocity_checkpoint'] = checkpoint
    checkpoint = _fx_particle_emission_checkpoint(root, manifest)
    if checkpoint is not None:
        contract['particle_emission_checkpoint'] = checkpoint
    if len(json.dumps(contract, ensure_ascii=False, separators=(",", ":"), allow_nan=False).encode("utf-8")) > 2 * 1024 * 1024:
        raise BridgeCommandError("SCENE_CONTRACT_TOO_LARGE", "task scene contract exceeds the receipt limit")
    return contract


def _fx_verify_scene_contract(contract: dict[str, Any], task_id: str) -> dict[str, Any]:
    import hou

    _manifest_root, manifest = _fx_manifest(task_id, required=False,
        root_path=(contract or {}).get('execution_root'))
    # Contracts written before the explicit owned-roots field remain safe to
    # verify against their already-bound execution root.  New captures always
    # include the field; a present-but-malformed field is still rejected.
    contract = dict(contract or {})
    if ("owned_roots" not in contract and contract.get("schema") in {
            "houdini.task_scene_contract/1.0", "houdini.task_scene_contract/2.0"}):
        contract["owned_roots"] = [str(contract.get("execution_root") or "")]
    _fx_scene_capture_policy(contract, str(task_id), allow_legacy_v1=True)
    if (contract.get("task_id") != str(task_id)
            or contract.get("execution_root") != manifest.get("execution_root")
            or not isinstance(contract.get("owned_roots"), list)
            or not contract.get("owned_roots")
            or contract.get("graph_hash") != str(manifest.get("graph_hash") or "")
            or not isinstance(contract.get("nodes"), list)
            or not contract["nodes"] or len(contract["nodes"]) > 128):
        raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "saved task scene contract is malformed")
    return _fx_verify_scene_contract_nodes(contract, task_id)


def _fx_verify_scene_contract_nodes(contract: dict[str, Any], task_id: str) -> dict[str, Any]:
    import hou

    capture_policy = _fx_scene_capture_policy(contract, str(task_id), allow_legacy_v1=True)
    expected_paths = {str(n.get("path") or "") for n in contract["nodes"]}
    if capture_policy in ("locked-hda-definition/1", "official-locked-hda-definition/1"):
        try:
            actual_nodes, boundaries = _fx_scene_contract_nodes(contract["owned_roots"],
                {str(index): record["path"] for index, record in enumerate(contract["nodes"])},
                capture_policy=capture_policy)
        except BridgeCommandError as exc:
            raise BridgeCommandError("ARTIFACT_STRUCTURE_MISMATCH", "live HDA proof differs from the saved contract") from exc
        if set(actual_nodes.values()) != expected_paths or boundaries != contract["hda_boundaries"]:
            raise BridgeCommandError("ARTIFACT_STRUCTURE_MISMATCH", "live HDA definitions or static internal state differ")
    else:
        for owned in contract["owned_roots"]:
            owned_node = hou.node(owned)
            if owned_node is not None and any(n.path() not in expected_paths for n in owned_node.allSubChildren()):
                raise BridgeCommandError("ARTIFACT_STRUCTURE_MISMATCH", "task namespace contains unsaved nodes")
    nodes_verified = parameters_verified = connections_verified = True
    differences, difference_kinds = [], set()

    def summary(value):
        result = {"type": type(value).__name__[:40]}
        if value is None or type(value) in (bool, int, float):
            result["value"] = str(value)[:80]
        else:
            encoded = json.dumps(value, ensure_ascii=False, sort_keys=True, default=lambda item: type(item).__name__)
            result["sha256"] = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
            result["size"] = len(value) if isinstance(value, (dict, list, tuple, str)) else len(encoded)
        return result

    def difference(kind, path, field, actual, saved, **details):
        if kind in difference_kinds or len(differences) >= 4:
            return
        difference_kinds.add(kind)
        differences.append({"path": path[:180], "field": field[:160], "actual": summary(actual),
                            "expected": summary(saved), **details})

    for expected in contract["nodes"]:
        if not isinstance(expected, dict):
            raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "saved task scene node record is malformed")
        path = str(expected.get("path") or "")
        node = hou.node(path)
        owned_roots = [str(root) for root in contract.get("owned_roots") or []]
        if node is None or not any(path == root or path.startswith(root.rstrip("/") + "/") for root in owned_roots):
            nodes_verified = False
            difference("node", path, "node_presence_or_scope", node is not None, True)
            break
        if (str(node.type().nameWithCategory()) != expected.get("type")
                or capture_policy in ("locked-hda-definition/1", "official-locked-hda-definition/1") and node.type().category().name() != expected.get("category")):
            nodes_verified = False
            difference("node", path, "node_type_category",
                       [str(node.type().nameWithCategory()), str(node.type().category().name())],
                       [expected.get("type"), expected.get("category")],
                       actual_node_type=str(node.type().nameWithCategory())[:100],
                       actual_category=str(node.type().category().name())[:40],
                       expected_node_type=str(expected.get("type"))[:100], expected_category=str(expected.get("category"))[:40])
        try:
            if contract["schema"] in {"houdini.task_scene_contract/2.0", "houdini.task_scene_contract/2.1", "houdini.task_scene_contract/2.2"}:
                channels = expected.get("parameter_channels")
                if not isinstance(channels, dict) or set(channels) != {str(p.name()) for p in node.parms()}:
                    parameters_verified = False
                    actual_names = {str(p.name()) for p in node.parms()}
                    saved_names = set(channels) if isinstance(channels, dict) else set()
                    difference("channel", path, "parameter_channel_names", sorted(actual_names), sorted(saved_names),
                               missing_names=[name[:80] for name in sorted(saved_names - actual_names)[:12]],
                               extra_names=[name[:80] for name in sorted(actual_names - saved_names)[:12]])
                else:
                    for name, saved_channel in channels.items():
                        _, actual_channel = _fx_scene_parameter_readback(node.parm(name),task_id)
                        if actual_channel != saved_channel:
                            parameters_verified = False
                            keys = (sorted(set(actual_channel) | set(saved_channel))
                                    if isinstance(actual_channel, dict) and isinstance(saved_channel, dict) else [])
                            changed = [key for key in keys if key not in actual_channel or key not in saved_channel
                                       or actual_channel[key] != saved_channel[key]][:6]
                            difference("channel", path, "parameter_channels." + str(name), actual_channel, saved_channel,
                                       changed_subkeys=[str(key)[:80] for key in changed],
                                       subkey_values={str(key)[:80]: {"actual": summary(actual_channel.get(key)),
                                                                     "expected": summary(saved_channel.get(key))} for key in changed})
                            break
            for name, value in dict(expected.get("parameters") or {}).items():
                parm = node.parm(str(name))
                actual_value = _fx_scene_parameter_readback(parm,task_id)[0] if parm is not None else None
                if parm is None or json.dumps(actual_value, ensure_ascii=False,
                                              sort_keys=True, separators=(",", ":"), allow_nan=False) != json.dumps(
                                                  value, ensure_ascii=False, sort_keys=True,
                                                  separators=(",", ":"), allow_nan=False):
                    parameters_verified = False
                    difference("value", path, "parameters." + str(name), actual_value, value, missing=parm is None)
                    break
            actual_inputs = [item.path() if item is not None else None for item in node.inputs()]
            if actual_inputs != expected.get("inputs"):
                connections_verified = False
                difference("inputs", path, "inputs", actual_inputs, expected.get("inputs"),
                           actual_paths=[item[:180] if isinstance(item, str) else None for item in actual_inputs[:8]],
                           expected_paths=[str(item)[:180] if item is not None else None for item in (expected.get("inputs") or [])[:8]])
        except Exception as exc:
            raise BridgeCommandError("ARTIFACT_CONTRACT_READBACK_FAILED", "reopened task node state could not be read: {}: {}".format(getattr(exc,"code",type(exc).__name__),path)) from exc
    if not nodes_verified or not parameters_verified or not connections_verified:
        raise BridgeCommandError("ARTIFACT_STRUCTURE_MISMATCH",
                                 "reopened task nodes, parameters, or connections differ from the saved receipt: " + repr(differences))
    verification = {"nodes_verified": nodes_verified, "parameters_verified": parameters_verified,
                    "connections_verified": connections_verified, "node_count": len(contract["nodes"])}
    root,manifest = _fx_manifest(task_id,required=False,root_path=contract.get('execution_root'))
    environment = _fx_project_environment_readback(manifest, str(task_id))
    if (environment != contract.get('project_environment')
            or manifest.get('project_environment_sha256') != contract.get('project_environment_sha256')):
        raise BridgeCommandError('ARTIFACT_STRUCTURE_MISMATCH', 'saved project environment differs')
    configuration = manifest.get('frozen_render_scene')
    if configuration is not None or 'frozen_render_scene_sha256' in contract:
        from dcc_task_runtime.canonical import canonical_sha256
        if (configuration is None or canonical_sha256(configuration) != manifest.get('frozen_render_scene_sha256') or
                contract.get('frozen_render_scene_sha256') != manifest.get('frozen_render_scene_sha256')):
            raise BridgeCommandError('ARTIFACT_CONTRACT_INVALID', 'saved frozen scene identity differs')
        domain,pack = _fx_pack({'constraints':{'fx':{'domain_pack':manifest['domain_pack']}},'frozen_render_scene':configuration})
        verification['frozen_scene_parameters'] = _fx_frozen_scene_readback(configuration,manifest['nodes'],pack,manifest.get('candidate_patch'),
            task_id=task_id, saved_readback=contract.get('frozen_scene_parameters'))
        if verification['frozen_scene_parameters'] != contract.get('frozen_scene_parameters'):
            raise BridgeCommandError('ARTIFACT_STRUCTURE_MISMATCH', 'saved frozen parameter readback differs')
    return verification


def _fx_prepare_loaded_hda_boundaries(contract, task_id, contract_digest):
    """Instantiate only saved locked boundaries before the pure scene verifier."""
    import hou
    if not isinstance(contract, dict) or _fx_scene_contract_digest(contract) != contract_digest:
        raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "loaded HDA preparation requires exact saved contract")
    policy = _fx_scene_capture_policy(contract, task_id, allow_legacy_v1=True)
    if policy not in ("locked-hda-definition/1", "official-locked-hda-definition/1"):
        return
    records = {record["path"]: record for record in contract["nodes"]}
    prepared = []
    for boundary in contract["hda_boundaries"]:
        path = boundary["path"]
        record = records.get(path)
        node = hou.node(path)
        if (record is None or node is None or node.path() != path
                or not any(path == root or path.startswith(root.rstrip("/") + "/") for root in contract["owned_roots"])
                or record["type"] != boundary["type"] or record.get("category") != boundary["category"]
                or node.type().nameWithCategory() != boundary["type"] or node.type().category().name() != boundary["category"]
                or not _fx_hda_bool(node, "isLockedHDA") or not _fx_hda_bool(node, "matchesCurrentDefinition")
                or _fx_hda_definition_identity(node) != boundary["definition"]):
            raise BridgeCommandError("ARTIFACT_STRUCTURE_MISMATCH", "loaded HDA boundary identity differs: " + path[:180])
        for owned in contract["owned_roots"]:
            if path == owned or path.startswith(owned.rstrip("/") + "/"):
                root = hou.node(owned)
                marker = root.userData("agent_task_id") if root is not None else None
                if marker is not None and marker != str(task_id):
                    raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "loaded HDA root task marker differs")
        prepared.append(node)
    for node in prepared:
        if _fx_hda_bool(node, "isDelayedDefinition"):
            node.syncDelayedDefinition()
        node.allSubChildren(recurse_in_locked_nodes=True, sync_delayed_definition=True)


def _fx_reopen_owned_root(params: dict[str, Any], path: Path, expected: str, *, complete=None, transition=None, completion=None) -> dict[str, Any]:
    import hou

    task_id = str(params.get("task_id") or "")
    root = str(params.get("root_path") or "")
    if not task_id or _root_for_path(root) != root or _path_scope(root) != "sop":
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "reopen requires the exact task-owned object root")
    producer_before = _fx_producer_identity(task_id)
    with _root_lease_fence(root, task_id=task_id, scope="sop") as lease:
        host_before = _host_identity()
        events_before = {"host": list(getattr(_BRIDGE_SCENE_STATE, "recent_events", ())),
                         "producer": list(_GRAPH_WORKER_SCENE_EVENTS)}
        saves_path = _fx_task_saves_path(task_id)
        store = json.loads(saves_path.read_text(encoding="utf-8")) if saves_path.is_file() else {}
        receipts = [receipt for receipt in store.get("saves") or []
                    if Path(str(receipt.get("path") or "")).resolve() == path and receipt.get("sha256") == expected]
        if not receipts:
            raise BridgeCommandError("ARTIFACT_UNREGISTERED", "exact task save receipt required for root rebind")
        saved = receipts[-1]
        saved_contract = saved.get("scene_contract")
        capture_policy = _fx_scene_capture_policy(saved_contract, task_id)
        if (saved_contract.get("execution_root") != root
                or saved.get("scene_contract_sha256") != _fx_scene_contract_digest(saved_contract)):
            raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "saved scene contract digest is invalid")
        contract = _fx_capture_scene_contract(task_id, capture_policy=capture_policy)
        has_manifest = contract is not None
        if contract is None:
            contract = _fx_native_command_scene_contract(task_id, {"root_path": root}, capture_policy=capture_policy)
        if contract is None or contract.get("execution_root") != root:
            raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "saved scene must bind the requested root")
        if not has_manifest:
            contract["graph_hash"] = saved_contract.get("graph_hash")
        if contract != saved_contract:
            raise BridgeCommandError("ARTIFACT_STRUCTURE_MISMATCH", "live scene differs from the exact saved task contract")
        with _fx_owned_hip_load_events(trace_phase="owned_root_load"):
            hou.hipFile.load(str(path), suppress_save_prompt=True, ignore_load_warnings=False)
        if Path(hou.hipFile.path()).resolve() != path or _fx_sha256_file(path) != expected:
            raise BridgeCommandError("SCENE_STATE_DRIFT", "owned HIP changed during root reopening")
        producer_after = _fx_producer_identity(task_id)
        host_after = _host_identity()
        if (any(producer_before.get(key) != producer_after.get(key) for key in producer_before if key != "scene_epoch")
                or producer_after["scene_epoch"] != producer_before["scene_epoch"] + 1
                or host_after["session_id"] != host_before["session_id"]
                or host_after["process_generation"] != host_before["process_generation"]
                or host_after["scene_epoch"] != host_before["scene_epoch"] + 1):
            context = {
                "producer_changed_fields": [str(key)[:80] for key in producer_before
                                            if key != "scene_epoch" and producer_before.get(key) != producer_after.get(key)][:16],
                "producer_epochs": [producer_before.get("scene_epoch"), producer_after.get("scene_epoch")],
                "host_changed_fields": [key for key in ("session_id", "process_generation")
                                        if host_before.get(key) != host_after.get(key)],
                "host_epochs": [host_before.get("scene_epoch"), host_after.get("scene_epoch")],
                "events_before": events_before,
                "events_after": {"host": list(getattr(_BRIDGE_SCENE_STATE, "recent_events", ())),
                                 "producer": list(_GRAPH_WORKER_SCENE_EVENTS)},
            }
            raise BridgeCommandError("SCENE_STATE_DRIFT", "root reopen changed host identity or unexpected scene epoch: "
                                     + repr(context))
        _fx_prepare_loaded_hda_boundaries(saved_contract, task_id, saved["scene_contract_sha256"])
        if has_manifest:
            verification = _fx_verify_scene_contract(saved_contract, task_id)
        else:
            verification = _fx_verify_scene_contract_nodes(saved_contract, task_id)
        if (_host_identity() != host_after or _fx_producer_identity(task_id) != producer_after
                or Path(hou.hipFile.path()).resolve() != path or _fx_sha256_file(path) != expected):
            raise BridgeCommandError("SCENE_STATE_DRIFT", "owned host or HIP changed during contract verification")
        rebound = dict(lease, scene_epoch=host_after["scene_epoch"],
                       renewed_at=datetime.now(timezone.utc).isoformat(),
                       expires_at=(datetime.now(timezone.utc) + timedelta(seconds=_ROOT_LEASE_TTL_SECONDS)).isoformat())
        version = int(lease.get("version") or 0)
    rebound = _root_lease_write(root, rebound, expect_version=version)
    with _fx_registered_rebind_saved_contract(task_id, saved_contract, path, expected,
            transition=transition, completion=completion) as restored:
        result = {"root_path": root, "task_id": task_id, "before_version": version,
                  "version": rebound["version"], "scene_epoch": rebound["scene_epoch"],
                  "scene_contract_sha256": saved["scene_contract_sha256"], "verification": verification,
                  **restored}
        return complete(result) if complete is not None else result


def scene_reopen_task_hip(params: dict[str, Any]) -> dict[str, Any]:
    """Formal task-owned reopen (headless workers only).

    Requires a save receipt recorded by scene.save_hip for the exact path and
    content hash; refuses replaced or corrupted files and reports load
    warnings instead of suppressing them.
    """
    import hou

    if hou.isUIAvailable():
        raise BridgeCommandError("SCENE_OWNERSHIP_REQUIRED", "task reopen is a headless worker operation; the GUI keeps its dirty-scene protection")
    task_id = str(params.get("task_id") or "")
    raw_path = str(params.get("path") or "")
    if not task_id or not raw_path:
        raise BridgeCommandError("INVALID_ARGUMENT", "task_id and path are required")
    path = Path(raw_path).expanduser().resolve()
    saves_path = _fx_task_saves_path(task_id)
    store: dict[str, Any] = {}
    if saves_path.is_file():
        try:
            store = json.loads(saves_path.read_text(encoding="utf-8"))
        except (ValueError, OSError):
            store = {}
    actual_sha = _fx_sha256_file(path) if path.is_file() else None
    if actual_sha is None:
        raise BridgeCommandError("ARTIFACT_MISSING", "task hip does not exist: {}".format(path))
    if params.get('sha256') is not None and str(params['sha256']).lower() != actual_sha:
        raise BridgeCommandError('ARTIFACT_MISMATCH', 'requested task HIP hash differs from the registered file')
    receipts = [s for s in store.get("saves") or [] if Path(str(s.get("path"))).resolve() == path]
    if not receipts:
        raise BridgeCommandError("ARTIFACT_UNREGISTERED",
                                 "no save receipt for {} under task {}; reopen only accepts controller-registered task hips".format(path, task_id))
    matching = [s for s in receipts if str(s.get("sha256")) == actual_sha]
    if not matching:
        raise BridgeCommandError("ARTIFACT_MISMATCH",
                                 "file content sha {} does not match any recorded save receipt for {} ({} receipts on file)".format(
                                     actual_sha[:12], path, len(receipts)))
    receipt = matching[-1]
    if (params.get('scene_contract_sha256') is not None
            and params['scene_contract_sha256'] != receipt.get('scene_contract_sha256')):
        raise BridgeCommandError('ARTIFACT_CONTRACT_INVALID', 'requested saved scene contract differs from its registered receipt')
    scene_contract = receipt.get("scene_contract")
    if scene_contract is not None:
        if _fx_scene_contract_digest(scene_contract) != receipt.get("scene_contract_sha256"):
            raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "saved task scene contract digest does not match")
        _fx_scene_capture_policy(scene_contract, task_id, allow_legacy_v1=True)
    snapshot = _fx_scene_transition_snapshot(task_id, {"path": str(path), "sha256": actual_sha}, require_source=True)
    if snapshot is None:
        raise BridgeCommandError("ARTIFACT_MISMATCH", "task HIP snapshot is unavailable")
    transition = _fx_scene_transition_begin(params, "scene.reopen_task_hip", path, actual_sha,
        scene_contract_sha256=receipt.get("scene_contract_sha256"))
    replay = _fx_scene_transition_replay(transition)
    if replay is not None:
        return replay
    if transition is not None and _host_identity().get('scene_epoch') != transition.get('before_scene_epoch'):
        raise BridgeCommandError('PRODUCTION_SCENE_TRANSITION_RECONCILIATION_UNPROVEN',
                                 'interrupted task load requires reconciliation before another load')
    warnings: list[str] = []
    load_error = None
    load_count = 1
    try:
        with _fx_owned_hip_load_events(trace_phase="task_reopen_load"):
            hou.hipFile.load(snapshot["snapshot_path"], suppress_save_prompt=True, ignore_load_warnings=False)
    except hou.LoadWarning as exc:
        # Only a native post-load warning permits the existing second load.
        load_error = str(exc)
        warnings.append(load_error)
        load_count = 2
        with _fx_owned_hip_load_events(trace_phase="task_reopen_warning_retry"):
            hou.hipFile.load(snapshot["snapshot_path"], suppress_save_prompt=True, ignore_load_warnings=True)
    transition = _fx_task_reopen_record_loaded(transition, snapshot, load_count, warnings)
    hou.hipFile.setName(str(path))
    if Path(hou.hipFile.path()).expanduser().resolve() != path:
        raise BridgeCommandError('SCENE_STATE_DRIFT', 'loaded task HIP did not retain its original saved path')
    structure = {}
    for node_path, expected_type in (receipt.get("structure") or {}).items():
        node = hou.node(node_path)
        structure[node_path] = {"expected_type": expected_type, "actual_type": node.type().nameWithCategory() if node else None,
                                "present": node is not None}
    missing = [p for p, v in structure.items() if not v["present"]]
    drifted = {p: v for p, v in structure.items() if v["present"] and v["actual_type"] != v["expected_type"]}
    if missing or drifted:
        raise BridgeCommandError("ARTIFACT_STRUCTURE_MISMATCH",
                                 "reopen verification failed: {} missing, {} drifted".format(len(missing), len(drifted)),
                                 "missing={}; drifted={}".format(missing[:5], sorted(drifted)[:5]))
    scene_contract = receipt.get("scene_contract")
    contract_verification = None
    if scene_contract is not None:
        if receipt.get("scene_contract_sha256") != _fx_scene_contract_digest(scene_contract):
            raise BridgeCommandError("ARTIFACT_CONTRACT_INVALID", "saved task scene contract digest does not match")
        if transition is not None:
            _fx_prepare_loaded_hda_boundaries(scene_contract, task_id, receipt["scene_contract_sha256"])
        contract_verification = _fx_verify_scene_contract(scene_contract, task_id)
    return _fx_finalize_task_reopen(task_id, path, actual_sha, receipt, snapshot, transition,
        warnings=warnings, structure_verified=len(structure), contract_verification=contract_verification)


def _fx_finalize_task_reopen(task_id, path, actual_sha, receipt, snapshot, transition, *,
                           warnings, structure_verified, contract_verification):
    """Complete the same ownership and durable scene handoff after load or recovery."""
    import hou
    listener = globals().get("_SERVER")
    from dcc_task_runtime.platform_support import atomic_write

    saves_path = _fx_task_saves_path(task_id)
    previous_save = saves_path.read_bytes()
    store = json.loads(previous_save)
    scene_contract = receipt.get('scene_contract')
    loaded_root, loaded_manifest = _fx_manifest(task_id, required=False,
        root_path=(scene_contract or {}).get('execution_root'))
    previous_manifest = (_fx_snapshot_manifest_persistence(loaded_root, task_id)
        if loaded_root is not None and loaded_manifest else None)
    reopened_runner = fx_operation_runner(task_id)
    previous_generation = reopened_runner.generation
    new_generation = _fx_host_generation()
    identity = _host_identity()
    lease_changes = {}
    transferred = []
    completion = {}
    try:
        if scene_contract is not None:
            saved_root = str(scene_contract.get('execution_root') or '')
            if saved_root and _root_lease_read(saved_root) is None:
                owned_root = hou.node(saved_root)
                if (owned_root is None or owned_root.userData('bridge_fx_owned') != '1'
                        or _root_for_path(saved_root) != saved_root or _path_scope(saved_root) != 'sop'):
                    raise BridgeCommandError('SCENE_OWNERSHIP_REQUIRED', 'saved scene has no exact owned task root')
                issued = _root_lease_issue(saved_root, task_id, scope='sop')
                lease_changes[saved_root] = (None, dict(issued))
        for lease_file in sorted(_root_leases_dir().glob('*.json')):
            try:
                lease = json.loads(lease_file.read_text(encoding='utf-8'))
            except (ValueError, OSError):
                continue
            if (not isinstance(lease, dict) or str(lease.get('task_id') or '') != task_id
                    or lease.get('status') != 'ACTIVE'):
                continue
            root = str(lease.get('root'))
            previous = lease_changes[root][0] if root in lease_changes else dict(lease)
            lease.update(owner_generation=identity['process_generation'], owner_session_id=identity['session_id'],
                scene_epoch=identity['scene_epoch'], renewed_at=datetime.now(timezone.utc).isoformat(),
                expires_at=(datetime.now(timezone.utc) + timedelta(seconds=_ROOT_LEASE_TTL_SECONDS)).isoformat())
            try:
                written = _root_lease_write(root, lease, expect_version=int(lease.get('version') or 0))
            except BridgeCommandError as exc:
                if exc.code == 'LEASE_CAS_CONFLICT': continue
                raise
            lease_changes[root] = (previous, dict(written))
            transferred.append(root)
        with _fx_registered_rebind_saved_contract(task_id, scene_contract,
                str(path), actual_sha, transition=transition, completion=completion) as restored:
            if previous_manifest is not None:
                _fx_write_state(task_id, loaded_manifest)
            reopened_runner.generation = new_generation
            store['active_generation'] = new_generation
            store['active_scene'] = {**snapshot, 'scene_contract': scene_contract,
                'scene_contract_sha256': receipt.get('scene_contract_sha256'), 'identity': _host_identity(),
                'transition_operation_id': (transition or {}).get('operation_id'),
                'transition_request_sha256': (transition or {}).get('request_sha256')}
            atomic_write(saves_path, json.dumps(store, ensure_ascii=False, indent=1).encode('utf-8'),
                         owned_root=saves_path.parent)
            result = {'path': str(path), 'sha256': actual_sha,
                'save_receipt': {'saved_at': receipt.get('saved_at'), 'generation': receipt.get('process_generation')},
                'load_warnings': warnings, 'structure_verified': structure_verified,
                'scene_contract_sha256': receipt.get('scene_contract_sha256'),
                **(contract_verification or {}), 'active_generation': new_generation,
                'leases_transferred': transferred, **restored}
            if transition is not None:
                result['scene_transition'] = _fx_scene_transition_complete(task_id,
                    str(transition.get('operation_id') or ''), result, completion=completion)
            _fx_listener_trace("formal_reopen_return", expected_server=listener)
            return result
    except Exception:
        _fx_geometry_restore_transition_intent(task_id, transition, completion)
        reopened_runner.generation = previous_generation
        if saves_path.read_bytes() != previous_save:
            atomic_write(saves_path, previous_save, owned_root=saves_path.parent)
        if previous_manifest is not None:
            _fx_restore_manifest_persistence(loaded_root, previous_manifest)
        for root, (previous, written) in reversed(list(lease_changes.items())):
            if previous is None:
                with _root_lease_locked(root):
                    if _root_lease_read(root) == written:
                        _root_lease_path(root).unlink()
                        _LEASE_RENEW_MEMORY.pop(root, None)
            else:
                try:
                    _root_lease_write(root, dict(previous, version=written['version']),
                                      expect_version=written['version'])
                except BridgeCommandError as error:
                    if error.code != 'LEASE_CAS_CONFLICT': raise
        raise


def fx_simulate_segment(params: dict[str, Any], pack_id: str, pack: dict[str, Any]) -> dict[str, Any]:
    task_id = str(params.get("task_id") or "")
    if not task_id:
        raise BridgeCommandError("INVALID_ARGUMENT", "task_id is required")
    return fx_operation_runner(task_id).submit(params, pack_id, pack,
                                                request_id=params.get("request_id"))


def fx_operation_status(params: dict[str, Any]) -> dict[str, Any]:
    task_id = str(params.get("task_id") or "")
    op_id = str(params.get("operation_id") or "")
    if not task_id or not op_id:
        raise BridgeCommandError("INVALID_ARGUMENT", "task_id and operation_id are required")
    record = fx_operation_runner(task_id).status(op_id)
    return {"gates": [{"name": "operation_record", "passed": record.get("state") in ("RUNNING", "COMPLETED"), "kind": "progress"}],
            "operation": record}


def fx_operation_cancel(params: dict[str, Any]) -> dict[str, Any]:
    task_id = str(params.get("task_id") or "")
    op_id = str(params.get("operation_id") or "")
    if not task_id or not op_id:
        raise BridgeCommandError("INVALID_ARGUMENT", "task_id and operation_id are required")
    record = fx_operation_runner(task_id).cancel(op_id)
    return {"gates": [{"name": "operation_cancel", "passed": record.get("cancel_requested") is True, "kind": "progress"}],
            "operation": record}


def _fx_control_dispatch(command: str, params: dict[str, Any]) -> dict[str, Any]:
    """Independent control-plane entry (never on the model surface).

    ``control.discover_orphans`` is read-only.  ``control.resolve`` routes
    proven recovery decisions (corrupt/legacy stores, reconcile records,
    proven orphan reservations) through signed-control-authorizations.
    """
    action = str(params.get("action") or "")
    task_id = str(params.get("task_id") or "")
    authorization = params.get("authorization")
    note = str(params.get("note") or "")
    if command == "control.discover_orphans":
        if not task_id:
            raise BridgeCommandError("INVALID_ARGUMENT", "task_id is required")
        return fx_operation_runner(task_id).discover_orphans()
    if command == "control.resolve":
        runner = fx_operation_runner(task_id) if task_id else None
        if runner is None:
            raise BridgeCommandError("INVALID_ARGUMENT", "task_id is required")
        if action == "compact_store":
            return {"compacted": runner.compact_store(authorization, note)}
        if action == "resolve_corrupt_store":
            return {"resolved": runner.resolve_corrupt_store(authorization, note)}
        if action == "resolve_legacy_store":
            return {"resolved": runner.resolve_legacy_store(authorization, note)}
        if action == "resolve_reconcile":
            record = runner.resolve_reconcile(str(params.get("operation_id") or ""),
                                              str(params.get("decision") or ""), authorization, note,
                                              params.get("evidence"))
            return {"resolved": True, "operation": record}
        if action == "import_stop_fact":
            return runner.import_external_stop_fact(
                str(params.get("operation_id") or ""),
                params.get("evidence"), authorization, note,
            )
        if action == "release_orphan":
            return {"released": runner.release_orphan(str(params.get("operation_id") or ""), authorization, note)}
        if action == "adopt_requeue":
            return {"adopted": runner.adopt_requeue(str(params.get("operation_id") or ""), authorization, note)}
        raise BridgeCommandError("INVALID_ARGUMENT", "unsupported control action: {}".format(action))
    raise BridgeCommandError("UNSUPPORTED_COMMAND", command)


def _task_writer_process_identity(writer_executable, task_identity):
    from dcc_task_runtime.process_image import freeze_executable, observe_process
    from dcc_task_runtime.owned_process import read_receipt
    from houdini_bridge.render_writer_facts import authenticated_writer_process_binding
    frozen = freeze_executable(writer_executable['image']['path'], writer_executable['version'],
                               writer_executable['image']['sha256'])
    if frozen != writer_executable or frozen['version'] != task_identity['version']:
        raise ValueError('writer executable differs from the frozen task deployment')
    task_identity = dict(task_identity)
    task_identity['writer_executable_sha256'] = hashlib.sha256(json.dumps(
        frozen, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')).hexdigest()
    directory = os.environ.get('BRIDGE_OWNED_SUPERVISOR_DIR', '')
    identity = json.loads(os.environ.get('BRIDGE_OWNED_SUPERVISOR_IDENTITY', '{}'))
    if not directory or identity.get('writer_executable_sha256') != task_identity['writer_executable_sha256']:
        raise ValueError('writer executable requires a bound supervisor launch')
    deadline = time.monotonic() + 20
    while read_receipt(directory, 'started', identity=identity) is None:
        if time.monotonic() >= deadline:
            raise ValueError('writer executable signed host anchor was not observed')
        time.sleep(.01)
    binding = authenticated_writer_process_binding(task_identity, {'directory':directory, 'identity':identity})
    if binding['expected_executable'] != frozen or observe_process(os.getpid()) != binding['host_anchor']:
        raise ValueError('writer host anchor differs from this task process')
    return task_identity


def task_host_serve(task_id: str = "task-host", stop_file: "str | None" = None,
                    ready_file: "str | None" = None, poll_seconds: float = 0.05,
                    max_seconds: "float | None" = None, warmup: bool = False,
                    launch_nonce: "str | None" = None,
                    writer_executable: "dict | None" = None) -> dict[str, Any]:
    """PUBLIC headless serving entry (the only sanctioned way to run a task host).

    Starts the bridge, writes a ready receipt, advances persistent operations
    and drains the request queue until the stop file appears (or max_seconds
    elapses), then writes a shutdown receipt. Machine paths arrive as
    arguments; nothing here reads batch-private state.
    """
    import hou

    if writer_executable is not None:
        from dcc_task_runtime.owned_process import runtime_ready_and_wait
        runtime_ready_and_wait()

    if not _fx_houdini_supported() or hou.applicationVersionString() not in _FX_KNOWN_HOUDINI_BUILDS:
        raise RuntimeError("HOUDINI_VERSION_UNSUPPORTED: {}".format(hou.applicationVersionString()))
    generation = _fx_host_generation()
    # Optional explicit warmup (default OFF). Observation that motivated it:
    # first VEX compilation inside an active request context once spun in OP
    # time-dependency recursion (samples in the review batch). That root cause
    # is a hypothesis supported by process samples, not a proven statement;
    # the warmup is therefore opt-in, task-owned, runs before the server and
    # its cost is reported in the receipt instead of being silently charged.
    warmup_receipt = {"warmup": "skipped"}
    if warmup:
        try:
            t_warm = time.monotonic()
            _fx_build_preview({"task_id": "_warmup", "step_params": {"domain_pack": "vellum_softbody_grains_v1"}},
                              "vellum_softbody_grains_v1", _FX_PACKS["vellum_softbody_grains_v1"])
            warm_root = hou.node(_fx_task_paths("_warmup", None)[0])
            warm_out = warm_root.node("FX_OUTPUT") if warm_root else None
            if warm_out is not None:
                hou.setFrame(1)
                warm_out.cook(force=True)
                hou.setFrame(2)
                warm_out.cook(force=True)
            if warm_root is not None:
                warm_root.destroy()
            state_file = _fx_state_path("_warmup")
            if state_file.is_file():
                state_file.unlink()
            warmup_receipt = {"warmup": "done", "warmup_seconds": round(time.monotonic() - t_warm, 3)}
        except Exception as exc:
            warmup_receipt = {"warmup": "failed", "error": str(exc)[:200]}
    try:
        port = int(autostart())
        server = _SERVER
        if server is None:
            raise RuntimeError("bridge server did not start")
    except Exception as exc:
        raise RuntimeError("BRIDGE_START_FAILED: {}".format(exc)) from exc
    runner = fx_operation_runner(task_id)
    receipt = {
        "task_id": task_id,
        "session_id": server.session_id,
        "pid": os.getpid(),
        "port": port,
        "process_generation": generation,
        "protocol_version": _fx_host_protocol_version(),
        "addon_sha256": _FX_LOADED_ADDON_SHA256,
        "houdini_version": hou.applicationVersionString(),
        "gui": bool(hou.isUIAvailable()),
        "started_at": datetime.now(timezone.utc).isoformat(),
        "launch_nonce": launch_nonce,
        **warmup_receipt,
    }
    task_identity = {"task_id": task_id, "session_id": server.session_id,
                     "launch_nonce": launch_nonce, "pid": os.getpid(),
                     "process_generation": generation, "plugin_build": _FX_LOADED_ADDON_SHA256,
                     "scene_epoch": _host_identity()["scene_epoch"], "version": hou.applicationVersionString()}
    if writer_executable is not None:
        task_identity = _task_writer_process_identity(writer_executable, task_identity)
    globals()["_TASK_HOST_IDENTITY"] = task_identity
    receipt["task_host_identity"] = task_identity
    if ready_file:
        Path(ready_file).write_text(json.dumps(receipt, ensure_ascii=False))
    deadline = time.monotonic() + float(max_seconds) if max_seconds else None
    requests_served = 0
    stop_reason = "stop_file"
    t_start = time.monotonic()
    while True:
        try:
            server.pump()
        except Exception as exc:
            stop_reason = "QUEUE_UNAVAILABLE: {}".format(exc)
            break
        try:
            runner.advance()
        except Exception as exc:
            stop_reason = "OPERATION_ADVANCE_ERROR: {}".format(exc)
            break
        if stop_file and Path(stop_file).exists():
            break
        if deadline is not None and time.monotonic() >= deadline:
            stop_reason = "max_seconds_elapsed"
            break
        time.sleep(poll_seconds)
    receipt.update({
        "stopped_at": datetime.now(timezone.utc).isoformat(),
        "stop_reason": stop_reason,
        "wall_seconds": round(time.monotonic() - t_start, 3),
        "stopped_cleanly": stop_reason in ("stop_file", "max_seconds_elapsed"),
        "process_generation": generation,
        "protocol_version": _fx_host_protocol_version(),
    })
    if ready_file:
        stop_path = str(ready_file) + ".shutdown.json"
        Path(stop_path).write_text(json.dumps(receipt, ensure_ascii=False))
    try:
        server.shutdown() if hasattr(server, "shutdown") else None
    except Exception:
        pass
    return receipt
